// Quick per-item section picker (bottom sheet). Returns the chosen section name,
// '' for Unassigned, or null when dismissed (no change). Managed sections show as
// chips; a free-text field covers custom/legacy stations.
class _StationPickerSheet extends StatefulWidget {
  final String itemName;
  final String current;
  final List<String> sections;
  const _StationPickerSheet({required this.itemName, required this.current, required this.sections});

  @override
  State<_StationPickerSheet> createState() => _StationPickerSheetState();
}

class _StationPickerSheetState extends State<_StationPickerSheet> {
  late final TextEditingController _custom;

  @override
  void initState() {
    super.initState();
    // Seed the custom field only with a legacy/unmanaged label so managed picks
    // aren't duplicated as free text.
    final inList = widget.sections.any((s) => s.toLowerCase() == widget.current.toLowerCase());
    _custom = TextEditingController(text: inList ? '' : widget.current);
  }

  @override
  void dispose() {
    _custom.dispose();
    super.dispose();
  }

  bool _isSelected(String s) => s.toLowerCase() == widget.current.toLowerCase();

  // Selectable section pill — copper tint + outline when it is the current
  // assignment (selection is never colour alone: the label is the section).
  Widget _pill(BuildContext context, String label, {required bool selected, required VoidCallback onTap}) {
    return MouseRegion(
      cursor: SystemMouseCursors.click,
      child: GestureDetector(
        onTap: onTap,
        child: AnimatedContainer(
          duration: AppDurations.fast,
          curve: Curves.easeOut,
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
          decoration: BoxDecoration(
            color: selected ? AppColors.tint(AppColors.copper) : AppColors.inset,
            borderRadius: AppRadius.controlAll,
            border: Border.all(
              color: selected ? AppColors.copper.withValues(alpha: 0.55) : AppColors.border,
            ),
          ),
          child: Text(
            label,
            style: TextStyle(
              fontSize: 12.5,
              fontWeight: selected ? FontWeight.w600 : FontWeight.w500,
              letterSpacing: 0.2,
              color: selected ? AppColors.copperHi : AppColors.textSecondary,
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return Padding(
      padding: EdgeInsets.fromLTRB(20, 0, 20, 20 + MediaQuery.of(context).viewInsets.bottom),
      child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('KOT ROUTING', style: text.labelSmall),
        const SizedBox(height: 6),
        Text('Kitchen section', style: text.titleMedium),
        const SizedBox(height: 3),
        Text(widget.itemName, style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Wrap(spacing: 8, runSpacing: 8, children: [
          _pill(
            context,
            'Unassigned',
            selected: widget.current.isEmpty,
            onTap: () => Navigator.pop(context, ''),
          ),
          for (final s in widget.sections)
            _pill(
              context,
              s,
              selected: _isSelected(s),
              onTap: () => Navigator.pop(context, s),
            ),
        ]),
        const SizedBox(height: AppSpacing.lg),
        Row(children: [
          Expanded(
            child: TextField(
              controller: _custom,
              decoration: const InputDecoration(
                labelText: 'Custom section',
                hintText: 'e.g. grill, bar',
                isDense: true,
              ),
              // Empty custom text is a no-op (dismiss) — clearing a section is
              // done explicitly via the Unassigned chip, so an accidental blank
              // "Set" never wipes a managed assignment.
              onSubmitted: (v) => Navigator.pop(context, v.trim().isEmpty ? null : v.trim()),
            ),
          ),
          const SizedBox(width: AppSpacing.sm),
          ForkButton(
            label: 'Set',
            icon: Icons.check,
            onPressed: () {
              final t = _custom.text.trim();
              Navigator.pop(context, t.isEmpty ? null : t);
            },
          ),
        ]),
      ]),
    );
  }
}

// A reusable section selector for the add/edit item dialog: a dropdown of managed
// sections (+ Unassigned, + a "Custom…" escape hatch, + any legacy label) that
// flips to a free-text field. Falls back to plain free text when no sections
// exist yet. Reports the chosen station ('' = unassigned) via [onChanged].
class _SectionSelector extends StatefulWidget {
  final String value;
  final List<String> sections;
  final ValueChanged<String> onChanged;
  const _SectionSelector({required this.value, required this.sections, required this.onChanged});

  @override
  State<_SectionSelector> createState() => _SectionSelectorState();
}

class _SectionSelectorState extends State<_SectionSelector> {
  static const _none = '__none__';
  static const _customSentinel = '__custom__';
  late final TextEditingController _custom;
  late String _value; // current station ('' = unassigned) — owned locally
  bool _customMode = false;

  bool _inList(String v) => widget.sections.any((s) => s.toLowerCase() == v.toLowerCase());

  @override
  void initState() {
    super.initState();
    _value = widget.value;
    _custom = TextEditingController(text: widget.value);
    // A non-empty value that isn't a managed section starts in free-text mode
    // (legacy/unmanaged label) — unless there are simply no managed sections.
    _customMode = widget.sections.isNotEmpty && widget.value.isNotEmpty && !_inList(widget.value);
  }

  @override
  void dispose() {
    _custom.dispose();
    super.dispose();
  }

  void _set(String v) {
    setState(() => _value = v);
    widget.onChanged(v);
  }

  @override
  Widget build(BuildContext context) {
    // No managed sections yet → plain free-text entry with the same contract.
    if (widget.sections.isEmpty) {
      return TextField(
        controller: _custom,
        decoration: const InputDecoration(labelText: 'Kitchen section', hintText: 'Optional — e.g. tandoor, grill, bar', isDense: true),
        onChanged: widget.onChanged,
      );
    }
    if (_customMode) {
      return Row(children: [
        Expanded(
          child: TextField(
            controller: _custom,
            autofocus: true,
            decoration: const InputDecoration(labelText: 'Custom section', isDense: true),
            onChanged: widget.onChanged,
          ),
        ),
        IconButton(
          icon: const Icon(Icons.close),
          tooltip: 'Pick from list',
          onPressed: () => setState(() {
            _customMode = false;
            _set('');
          }),
        ),
      ]);
    }
    final current = _value;
    final inList = _inList(current);
    return DropdownButtonFormField<String>(
      initialValue: current.isEmpty ? _none : current,
      isExpanded: true,
      decoration: const InputDecoration(labelText: 'Kitchen section', isDense: true),
      items: [
        const DropdownMenuItem(value: _none, child: Text('Unassigned')),
        for (final s in widget.sections) DropdownMenuItem(value: s, child: Text(s)),
        if (current.isNotEmpty && !inList)
          DropdownMenuItem(value: current, child: Text('$current (unassigned)', style: TextStyle(color: AppColors.warning))),
        const DropdownMenuItem(value: _customSentinel, child: Text('Custom…')),
      ],
      onChanged: (v) {
        if (v == _customSentinel) {
          setState(() {
            _customMode = true;
            _custom.text = '';
          });
          widget.onChanged('');
        } else if (v == _none) {
          _set('');
        } else if (v != null) {
          _set(v);
        }
      },
    );
  }
}

// "Undo Audited Action". The server independently re-checks this *and* the
// original action's own permission — this is only a UI convenience filter, never
// the security boundary.
const String _undoAuditPermissionId = '6f2a4c81-9d35-4b7e-a0c2-5e8b1d3f7a94';

// 'Review Attendance' — the EXISTING gate on GET /attendance and the clock-in
// review, which the leave routes reuse rather than minting a new Action. Whoever
// reviews a shift is who reviews a day off.
const String _attendanceReviewPermissionId = '2e7b9c40-1f83-4d6a-b902-5a8c3e1f6047';

// The one analytics Action every /analytics/* route is gated on, including
// /analytics/staff-performance and /analytics/concerns.
const String _analyticsPermissionId = 'df75119b-e5f1-4f38-aba5-78a1cf182f56';

// Whether this profile holds [actionId]. A UI convenience only — the server
// re-checks every one of these, so a wrong answer here costs an affordance, not
// a boundary. Mirrors the check `_mayUndo` has always used.
bool _holdsAction(Profile p, String actionId) =>
    p.isAdmin || p.actions.contains('*') || p.actions.contains(actionId);

/// MAY THIS PROFILE DO [c] — THE SERVER'S ANSWER, with the uuid test this call
/// site used to make as the fallback for an older backend.
///
/// Every gate below that has a capability goes through here rather than through
/// [_holdsAction] directly, and the difference is not cosmetic. `_holdsAction`
/// asks "is this uuid in the token", which means the uuid is written down twice
/// — once in the server's route guard and once here — and the two are free to
/// drift the next time a permission is split, renamed or re-registered. The
/// server already resolved the question and ships the ANSWER on `scope`; the
/// uuid stays only as the answer for a backend too old to have said.
bool _mayDo(Profile p, Capability c, String fallbackActionId) =>
    RoleScope.may(p, c, fallback: _holdsAction(p, fallbackActionId));

/// The UTC instant at which the restaurant-local day [dayKey] ("YYYY-MM-DD")
/// begins, or ends when [end] is set.
///
/// Deliberately NOT the bare day key: `/audit-logs` compares `from`/`to` against
/// `created_at`, a timestamptz, so a bare date is read as UTC midnight — which in
/// Asia/Kolkata drops the first 5½ hours of the restaurant's own day off the
/// front of "today" and adds them to the back of "yesterday". The offset is
/// resolved from [RestaurantTime]'s transition table, so it is right across DST;
/// where the table cannot answer (a zone this build predates) the device zone is
/// the only honest fallback left, which is the same one RestaurantTime renders in.
String _restaurantDayBoundIso(String dayKey, {bool end = false}) {
  final base = DateTime.tryParse('${dayKey.trim()}T00:00:00Z');
  if (base == null) return '';
  final wall = end
      ? base.add(const Duration(hours: 23, minutes: 59, seconds: 59, milliseconds: 999))
      : base;
  final probe = RestaurantTime.offsetMinutesAt(wall);
  if (probe == null) {
    return DateTime(wall.year, wall.month, wall.day, wall.hour, wall.minute, wall.second,
            wall.millisecond)
        .toUtc()
        .toIso8601String();
  }
  // The offset depends on the instant and the instant is what we are solving
  // for, so subtract once and re-ask. One correction settles everything except
  // a wall time inside the hour a DST shift skips, which no day boundary is.
  var instant = wall.subtract(Duration(minutes: probe));
  final refined = RestaurantTime.offsetMinutesAt(instant);
  if (refined != null && refined != probe) {
    instant = wall.subtract(Duration(minutes: refined));
  }
  return instant.toIso8601String();
}

/// [days] before today in the restaurant's zone, as a "YYYY-MM-DD" day key.
String _restaurantDayKeyBack(int days) {
  final wall = RestaurantTime.nowWall();
  return RestaurantTime.isoDate(wall.subtract(Duration(days: days)));
}

/// [months] calendar months before today in the restaurant's zone. Calendar, not
/// 30-day blocks: "past 3 months" on the 31st means the 30th/28th of the month
/// three back, not a date that does not exist.
String _restaurantDayKeyMonthsBack(int months) {
  final wall = RestaurantTime.nowWall();
  var year = wall.year;
  var month = wall.month - months;
  while (month <= 0) {
    month += 12;
    year -= 1;
  }
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  final leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
  final maxDay = month == 2 && leap ? 29 : lengths[month - 1];
  final day = wall.day > maxDay ? maxDay : wall.day;
  return RestaurantTime.isoDate(DateTime.utc(year, month, day));
}

// Audit log: searchable history of staff actions (proves the audit system is
// recording). Backed by GET /audit-logs, paged 50 at a time with `?meta=1` so
// the header reports the trail's REAL size; the search box re-queries the
// server, so it filters the whole trail rather than the pages already pulled in.
// Reversible entries can be undone via
// POST /audit-logs/:id/undo, which is append-only (the original entry is never
// edited — a new "Undid: …" entry is written on top).
Widget auditLogModule(RestClient rest, Profile p) => _AuditLogView(rest: rest, profile: p);

class _AuditLogView extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  const _AuditLogView({required this.rest, required this.profile});
  @override
  State<_AuditLogView> createState() => _AuditLogViewState();
}

class _AuditLogViewState extends State<_AuditLogView> with CachePrimedScreen {
  // Rows per fetch. The trail runs to thousands of entries, so it is pulled one
  // batch at a time and appended as the list nears its end — the old single
  // `?limit=300` shot both stalled the open and made the count chip read "300"
  // forever, whatever the trail actually holds.
  static const int _pageSize = 50;

  // Past this the server refuses the page (limit is clamped to 500), so a
  // refresh-in-place of everything scrolled in falls back to a plain reload.
  static const int _maxWindow = 500;

  final List<Map> _rows = [];
  // Ids already held. An entry written mid-scroll shifts the offset window, so
  // the same row can arrive in two consecutive pages.
  final Set<String> _ids = {};
  final ScrollController _scroll = ScrollController();
  final TextEditingController _search = TextEditingController();

  bool _loading = true;
  bool _loadingMore = false;
  bool _hasMore = false;
  int _total = 0;
  String? _error;

  // The term the SERVER is filtering on (the field debounces into it), so a
  // search spans the whole trail rather than the pages scrolled in so far.
  String _query = '';
  Timer? _debounce;

  // Mirrors the backend's Audit_log_category enum, in the same order the web
  // dashboard lists it. 'All' is the absence of the filter, not a value.
  static const List<String> _categories = [
    'All', 'General', 'Bill', 'Orders', 'Valet', 'Inventory',
    'Tables', 'Roles', 'Customer', 'Bookings', 'Menu',
  ];

  // Date presets. The last two open a picker; everything before them resolves
  // to a range without a dialog, which is what an owner reaches for daily.
  static const List<String> _presets = [
    'All time', 'Today', 'Last 7 days', 'Last 30 days', 'Last 3 months', 'A day…', 'A range…',
  ];
  static const int _presetDay = 5;
  static const int _presetRange = 6;

  int _preset = 0;
  // Inclusive restaurant day keys ("YYYY-MM-DD"); empty = unbounded that side.
  // Converted to absolute instants only at request time, by
  // [_restaurantDayBoundIso] — created_at is a timestamptz and a bare date would
  // be read as UTC midnight, sliding the whole window by the tenant's offset.
  String _from = '';
  String _to = '';
  String _category = 'All';
  // Request racing is guarded by CachePrimedScreen's generation counter: a
  // response whose generation is stale lost a race with a newer filter and
  // must not be merged into the list.

  @override
  void initState() {
    super.initState();
    _scroll.addListener(_onScroll);
    unawaited(primeFromCache(
      fetch: () => _fetchPage(offset: 0),
      apply: (res) { _applyPage(res, append: false); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _scroll.dispose();
    _search.dispose();
    super.dispose();
  }

  // Admins always qualify; otherwise the employee must hold the undo action.
  bool get _mayUndo {
    final p = widget.profile;
    return p.isAdmin || p.actions.contains('*') || p.actions.contains(_undoAuditPermissionId);
  }

  /// One page's GET under the CURRENT filters, side-effect free — replayable
  /// against the persisted cache at boot and the network path of every [_load].
  Future<Map<String, dynamic>> _fetchPage({required int offset, int? limit}) {
    final q = _query.trim();
    final fromIso = _from.isEmpty ? '' : _restaurantDayBoundIso(_from);
    final toIso = _to.isEmpty ? '' : _restaurantDayBoundIso(_to, end: true);
    // ?meta=1 returns { logs, total, has_more } — the true row count, which is
    // what the header chip reports, instead of "however many are loaded".
    final path = '/audit-logs?meta=1&limit=${limit ?? _pageSize}&offset=$offset'
        '${q.isEmpty ? '' : '&search=${Uri.encodeQueryComponent(q)}'}'
        '${_category == 'All' ? '' : '&category=${Uri.encodeQueryComponent(_category)}'}'
        '${fromIso.isEmpty ? '' : '&from=${Uri.encodeQueryComponent(fromIso)}'}'
        '${toIso.isEmpty ? '' : '&to=${Uri.encodeQueryComponent(toIso)}'}';
    return widget.rest.getMap(path);
  }

  /// Merge one page into the list — field assignment only, shared by the cache
  /// prime and the network load so the two paths cannot drift.
  void _applyPage(Map<String, dynamic> res, {required bool append}) {
    final page = <Map>[for (final r in (res['logs'] as List?) ?? const []) if (r is Map) r];
    if (!append) {
      _rows.clear();
      _ids.clear();
    }
    var added = 0;
    for (final r in page) {
      final id = _s(r, 'id', '');
      if (id.isNotEmpty && !_ids.add(id)) continue;
      _rows.add(r);
      added++;
    }
    _total = _int(res['total']) ?? _rows.length;
    // A page that brought nothing new can never advance the offset — stop
    // instead of asking for the same window forever.
    _hasMore = res['has_more'] == true && (!append || added > 0);
  }

  /// One page. [append] adds the next window; otherwise the list is replaced
  /// from offset 0 — which is also what a filter change must do, so a filtered
  /// view can never keep rows that no longer match. [silent] keeps whatever is
  /// on screen up while the refetch is in flight (the cache prime's follow-up).
  Future<void> _load({bool append = false, int? limit, bool silent = false}) async {
    if (append && (_loadingMore || !_hasMore)) return;
    final gen = bumpCacheGen();
    if (!silent) {
      setState(() {
        if (append) {
          _loadingMore = true;
        } else {
          _loading = true;
          _error = null;
        }
      });
    }
    final offset = append ? _rows.length : 0;
    try {
      final res = await _fetchPage(offset: offset, limit: limit);
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _applyPage(res, append: append);
        _loading = false;
        _loadingMore = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      // Only a SILENT refresh keeps the trail up behind the offline pill: a
      // loud non-append failure means a filter just changed, and old rows under
      // a new filter would describe neither.
      if (silent && _rows.isNotEmpty) {
        setState(() { _loading = false; _loadingMore = false; markCacheOffline(); });
        return;
      }
      setState(() {
        _error = '$e';
        _loading = false;
        _loadingMore = false;
        // Don't re-fire the same failing page every time the list settles.
        if (append) _hasMore = false;
      });
    }
  }

  // Near the end of the scroll extent, pull the next page. Guarded on
  // _loadingMore/_hasMore so a burst of scroll notifications is one request.
  void _onScroll() {
    if (!_scroll.hasClients || _loading || _loadingMore || !_hasMore) return;
    final pos = _scroll.position;
    if (pos.pixels >= pos.maxScrollExtent - 400) _load(append: true);
  }

  // Typing re-queries the SERVER, so it filters the whole trail; the debounce
  // keeps that to one request per pause rather than one per keystroke.
  void _onSearchChanged(String v) {
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 300), () {
      final next = v.trim();
      if (!mounted || next == _query) return;
      setState(() => _query = next);
      _load();
    });
  }

  /// Every filter change funnels through here, because all of them share one
  /// rule: the request restarts at offset 0 AND everything already scrolled in
  /// is discarded. Appending to a list built under different filters would mix
  /// two result sets and make the count chip describe neither. `_load()` with
  /// append:false already clears `_rows`/`_ids`; the bumped generation inside
  /// it also strands any page still in flight for the previous filter.
  void _applyFilters(VoidCallback change) {
    setState(() {
      change();
      // Dropped HERE rather than when the new page lands: if the request fails,
      // leaving the old rows on screen would show a list that does not match the
      // filter above it and a count chip that describes neither.
      _rows.clear();
      _ids.clear();
      _total = 0;
      _hasMore = false;
    });
    _load();
  }

  /// Resolves a preset to a day-key range. The two picker presets are handled by
  /// the caller (they need a dialog and can be cancelled).
  void _selectPreset(int i) {
    if (i == _preset && i != _presetDay && i != _presetRange) return;
    switch (i) {
      case 1:
        final today = RestaurantTime.todayIso();
        _applyFilters(() { _preset = i; _from = today; _to = today; });
      case 2:
        _applyFilters(() { _preset = i; _from = _restaurantDayKeyBack(6); _to = RestaurantTime.todayIso(); });
      case 3:
        _applyFilters(() { _preset = i; _from = _restaurantDayKeyBack(29); _to = RestaurantTime.todayIso(); });
      case 4:
        _applyFilters(() { _preset = i; _from = _restaurantDayKeyMonthsBack(3); _to = RestaurantTime.todayIso(); });
      case _presetDay:
        _pickDay();
      case _presetRange:
        _pickRange();
      default:
        _applyFilters(() { _preset = 0; _from = ''; _to = ''; });
    }
  }

  /// The window a picker starts from and is bounded by. `firstDate` is three
  /// years back — further than any trail this app pages through — and the last
  /// date is the restaurant's today, because there are no future audit entries.
  DateTime get _pickerLast {
    final w = RestaurantTime.nowWall();
    return DateTime(w.year, w.month, w.day);
  }

  DateTime get _pickerFirst {
    final l = _pickerLast;
    return DateTime(l.year - 3, l.month, l.day);
  }

  DateTime _seedDay(String key) {
    final parsed = DateTime.tryParse('${key}T00:00:00');
    if (parsed == null) return _pickerLast;
    final clamped = parsed.isAfter(_pickerLast)
        ? _pickerLast
        : (parsed.isBefore(_pickerFirst) ? _pickerFirst : parsed);
    return DateTime(clamped.year, clamped.month, clamped.day);
  }

  Future<void> _pickDay() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: _seedDay(_from.isEmpty ? RestaurantTime.todayIso() : _from),
      firstDate: _pickerFirst,
      lastDate: _pickerLast,
      helpText: 'Entries from one day',
    );
    // A cancelled picker must leave the previous window alone — including the
    // selected pill, which is why the preset is only written on success.
    if (picked == null || !mounted) return;
    final key = RestaurantTime.isoDate(picked);
    _applyFilters(() { _preset = _presetDay; _from = key; _to = key; });
  }

  Future<void> _pickRange() async {
    final seedFrom = _seedDay(_from.isEmpty ? _restaurantDayKeyBack(6) : _from);
    final seedTo = _seedDay(_to.isEmpty ? RestaurantTime.todayIso() : _to);
    final picked = await showDateRangePicker(
      context: context,
      initialDateRange: DateTimeRange(
        start: seedFrom,
        end: seedTo.isBefore(seedFrom) ? seedFrom : seedTo,
      ),
      firstDate: _pickerFirst,
      lastDate: _pickerLast,
      helpText: 'Entries between two days',
    );
    if (picked == null || !mounted) return;
    _applyFilters(() {
      _preset = _presetRange;
      _from = RestaurantTime.isoDate(picked.start);
      _to = RestaurantTime.isoDate(picked.end);
    });
  }

  bool get _hasFilters =>
      _query.isNotEmpty || _category != 'All' || _from.isNotEmpty || _to.isNotEmpty;

  void _clearFilters() {
    _search.clear();
    _debounce?.cancel();
    _applyFilters(() {
      _preset = 0;
      _from = '';
      _to = '';
      _category = 'All';
      _query = '';
    });
  }

  /// The window in words, in the RESTAURANT's zone — so the reader can tell a
  /// preset's answer from the pill's label ("Last 7 days" vs "Jul 28 – Aug 3").
  String get _rangeLabel {
    if (_from.isEmpty && _to.isEmpty) return 'All time';
    if (_from.isNotEmpty && _from == _to) return _fmtDay(_from);
    if (_from.isEmpty) return 'Up to ${_fmtDay(_to)}';
    if (_to.isEmpty) return 'From ${_fmtDay(_from)}';
    return '${_fmtDay(_from)} – ${_fmtDay(_to)}';
  }

  /// After an undo, re-read exactly the window already scrolled in (one request)
  /// so the "Undone" badge and the new "Undid:" entry appear without throwing
  /// the reader back to the top.
  Future<void> _refreshLoaded() {
    final held = _rows.length;
    return _load(limit: held == 0 || held > _maxWindow ? null : held);
  }

  /// Confirm, then reverse [row]. Surfaces the server's own `error` text on
  /// failure (it is already human-readable) and reloads on success so the new
  /// "Undid:" entry and the updated badges appear.
  Future<void> _undo(BuildContext context, Map row) async {
    final messenger = ScaffoldMessenger.of(context);
    final action = _s(row, 'action');
    final detail = _s(row, 'details', '');
    final emp = _s(row, 'employee', '');
    final when = _fmtTime(_s(row, 'timestamp', ''));
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) {
        final text = Theme.of(ctx).textTheme;
        return AlertDialog(
          title: const Text('Undo this action?'),
          content: SizedBox(
            width: 400,
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(action, style: text.titleSmall),
              if (detail.isNotEmpty && detail != '—') ...[
                const SizedBox(height: 4),
                Text(detail, style: text.bodySmall),
              ],
              const SizedBox(height: 10),
              Wrap(spacing: 6, runSpacing: 6, children: [
                if (emp.isNotEmpty && emp != '—') InfoChip(icon: Icons.person_outline, label: emp),
                if (when.isNotEmpty) InfoChip(icon: Icons.schedule, label: when),
              ]),
              const SizedBox(height: 12),
              Text(
                'This reverses that change and puts the data back the way it was before. '
                'Nothing is deleted from the trail — the original entry stays, and a new '
                '"Undid:" entry is added on top.',
                style: text.bodySmall,
              ),
            ]),
          ),
          actions: [
            ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
            ForkButton(label: 'Undo this action', icon: Icons.undo, onPressed: () => Navigator.pop(ctx, true)),
          ],
        );
      },
    );
    if (ok != true) return;
    final id = _s(row, 'id', '');
    if (id.isEmpty) return;
    final tenant = widget.profile.restaurantUsername;
    try {
      await widget.rest.post(
        '/audit-logs/${Uri.encodeComponent(id)}/undo'
        '${tenant.isEmpty ? '' : '?restaurantId=${Uri.encodeQueryComponent(tenant)}'}',
      );
      messenger.showSnackBar(SnackBar(content: Text('Undone: $action.')));
      await _refreshLoaded();
    } catch (e) {
      // The backend's `error` string is already a human sentence — show it as-is.
      messenger.showSnackBar(SnackBar(content: Text('$e'), backgroundColor: AppColors.danger));
    }
  }

  @override
  Widget build(BuildContext context) {
    final loaded = _rows.length;
    return cacheStaleOverlay(Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
        child: SectionHeader(
          title: 'Audit trail',
          // The server's total for the current filter — NOT how many rows have
          // been paged in, which is what used to pin this chip at "300".
          count: _loading && loaded == 0 ? null : _total,
          padding: const EdgeInsets.only(bottom: 12),
          trailing: loaded == 0 || loaded >= _total ? null : TickTag('$loaded loaded'),
        ),
      ),
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 10),
        child: TextField(
          controller: _search,
          decoration: const InputDecoration(
            prefixIcon: Icon(Icons.search, size: 18),
            hintText: 'Filter by action, employee, or detail…',
            isDense: true,
          ),
          onChanged: _onSearchChanged,
        ),
      ),
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
        child: _filterBar(context),
      ),
      Expanded(child: _body(context)),
    ]));
  }

  /// Date presets, the category filter, and what the two of them currently mean.
  /// Every control here goes through [_applyFilters], so changing any one of
  /// them restarts the trail at offset 0 rather than appending to a list built
  /// under the old filter.
  Widget _filterBar(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      ForkTabs(tabs: _presets, selected: _preset, onSelected: _selectPreset),
      const SizedBox(height: 10),
      Wrap(spacing: 8, runSpacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
        // The window in restaurant time, spelled out: a pill reading "Last 3
        // months" does not say which days that is.
        InfoChip(icon: Icons.event_outlined, label: _rangeLabel),
        PopupMenuButton<String>(
          tooltip: 'Filter by category',
          color: AppColors.cardRaised,
          onSelected: (v) {
            if (v == _category) return;
            _applyFilters(() => _category = v);
          },
          itemBuilder: (_) => [
            for (final c in _categories)
              CheckedPopupMenuItem<String>(value: c, checked: c == _category, child: Text(c)),
          ],
          child: InfoChip(
            icon: Icons.filter_list,
            label: _category == 'All' ? 'All categories' : _category,
          ),
        ),
        if (_hasFilters)
          ForkButton.ghost(label: 'Clear filters', icon: Icons.close, dense: true, onPressed: _clearFilters),
        if (_loading && _rows.isNotEmpty)
          Text('Reloading…', style: text.bodySmall),
      ]),
    ]);
  }

  Widget _body(BuildContext context) {
    if (_loading && _rows.isEmpty) {
      return ListView(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
        children: [
          for (var i = 0; i < 6; i++)
            const Padding(
              padding: EdgeInsets.only(bottom: 8),
              child: SkeletonBox(height: 54, radius: AppRadius.card),
            ),
        ],
      );
    }
    if (_error != null && _rows.isEmpty) {
      return LoadErrorState(
        whatFailed: "Couldn't load the audit trail",
        error: _error!,
        onRetry: _load,
      );
    }
    if (_rows.isEmpty) {
      return _empty(_hasFilters
          ? 'No entries match these filters — try a wider date range or another category.'
          : 'No audit entries yet.');
    }
    // The list stays interactive while a page is in flight — the foot is the
    // only thing that changes.
    return ListView.separated(
      controller: _scroll,
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
      itemCount: _rows.length + 1,
      separatorBuilder: (_, _) => const SizedBox(height: 8),
      itemBuilder: (context, i) =>
          i == _rows.length ? _pagingFoot(context) : _entryCard(context, _rows[i]),
    );
  }

  /// Foot of the list: what is in flight, what is left, and a manual pull for
  /// anyone whose pointer never reaches the scroll end.
  Widget _pagingFoot(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final child = _loadingMore
        ? Row(mainAxisAlignment: MainAxisAlignment.center, children: [
            SizedBox(
              width: 13,
              height: 13,
              child: CircularProgressIndicator(strokeWidth: 2, color: AppColors.copper),
            ),
            const SizedBox(width: AppSpacing.sm),
            Text('Loading the next $_pageSize…', style: text.bodySmall),
          ])
        : _hasMore
            ? Center(
                child: ForkButton.ghost(
                  label: 'Load more (${_rows.length} of $_total)',
                  icon: Icons.expand_more,
                  dense: true,
                  onPressed: () => _load(append: true),
                ),
              )
            // Either the trail ran out or a page failed — say which, never both.
            : Center(
                child: Text(
                  _error ?? 'All $_total shown',
                  textAlign: TextAlign.center,
                  style: text.bodySmall?.copyWith(color: _error == null ? null : AppColors.danger),
                ),
              );
    return Padding(padding: const EdgeInsets.only(top: 4), child: child);
  }

  Widget _entryCard(BuildContext context, Map r) {
    final text = Theme.of(context).textTheme;
    final detail = _s(r, 'details', '');
    final emp = _s(r, 'employee', '');
    // Additive undo metadata (older backends simply omit it).
    final undone = r['undone'] == true;
    final isUndoEntry = _s(r, 'undo_of', '').isNotEmpty;
    final undoable = r['undoable'] == true;
    final blockReason = _s(r, 'undo_block_reason', '');
    // An entry that was already undone, or that *is* an undo, is never offered
    // an Undo button.
    final offerUndo = _mayUndo && undoable && !undone && !isUndoEntry;
    final showBlockHint =
        _mayUndo && !undoable && !undone && !isUndoEntry && blockReason.isNotEmpty;
    return ForkCard(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      child: Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
        Container(
          width: 30,
          height: 30,
          decoration: BoxDecoration(
            color: AppColors.inset,
            borderRadius: AppRadius.controlAll,
            border: Border.all(color: AppColors.border),
          ),
          child: Icon(Icons.history, size: 14, color: AppColors.copper),
        ),
        const SizedBox(width: AppSpacing.md),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text(_s(r, 'action'), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            if (detail.isNotEmpty && detail != '—') ...[
              const SizedBox(height: 2),
              Text(detail, style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
            ],
          ]),
        ),
        const SizedBox(width: AppSpacing.md),
        // Trail badges: an entry that was reversed reads "Undone"; the entry
        // that did the reversing reads "Undo", so the pair is legible in
        // sequence.
        if (undone) ...[
          StatusChip(label: 'Undone', color: AppColors.neutral, dense: true),
          const SizedBox(width: AppSpacing.md),
        ],
        if (isUndoEntry) ...[
          TickTag('Undo', color: AppColors.info),
          const SizedBox(width: AppSpacing.md),
        ],
        if (emp.isNotEmpty && emp != '—') ...[
          InfoChip(icon: Icons.person_outline, label: emp),
          const SizedBox(width: AppSpacing.md),
        ],
        Text(_fmtTime(_s(r, 'timestamp', '')).toUpperCase(), style: text.labelSmall),
        if (offerUndo) ...[
          const SizedBox(width: AppSpacing.md),
          ForkButton.ghost(
            label: 'Undo',
            icon: Icons.undo,
            dense: true,
            onPressed: () => _undo(context, r),
          ),
        ] else if (showBlockHint) ...[
          const SizedBox(width: AppSpacing.md),
          // No dead control — a quiet muted hint carrying the server's own
          // reason (never one we invent).
          Tooltip(
            message: blockReason,
            child: InfoChip(
              icon: Icons.block,
              label: blockReason.length > 30 ? '${blockReason.substring(0, 29)}…' : blockReason,
            ),
          ),
        ],
      ]),
    );
  }
}

// ---------------------------------------------------------------- concerns ---

/// Severity bands, worst first — the order the screen renders them in.
const List<String> _concernSeverities = ['high', 'medium', 'low'];

Color _concernColor(String severity) => switch (severity) {
      'high' => AppColors.danger,
      'medium' => AppColors.warning,
      _ => AppColors.info,
    };

/// What a band means in the owner's terms. "High" alone says how bad, not how
/// soon — and how soon is the decision being made on this screen.
String _concernBandTitle(String severity) => switch (severity) {
      'high' => 'High — deal with today',
      'medium' => 'Medium — deal with this week',
      _ => 'Low — worth a look',
    };

/// One concern: what is wrong, WHO or WHAT it is happening to (by name), the
/// server's suggested action, and a working way to go and fix it.
///
/// The routing is [_attentionCard]'s, deliberately: both screens read the same
/// `deep_link`, so a row cannot send the Overview strip and this list to two
/// different places. `_attentionFocus` drops any focus key the destination does
/// not READ, which is why Attendance / Purchase Orders / Billing rows navigate
/// with no focus payload at all rather than landing there and claiming the
/// record "isn't in this list".
Widget _concernCard(BuildContext context, Map m, ModuleNavigator? nav, int windowDays) {
  final text = Theme.of(context).textTheme;
  final severity = '${m['severity'] ?? 'low'}';
  final colour = _concernColor(severity);
  final count = _numOf(m['count']).round();
  final title = '${m['title'] ?? m['label'] ?? ''}'.trim();
  final advice = '${m['what_to_do'] ?? ''}'.trim();
  final amount = m['amount'];

  final link = (m['deep_link'] as Map?) ?? const {};
  final deep = '${link['module'] ?? ''}';
  final legacy = '${m['module'] ?? ''}';
  final dest = nav == null ? null : (nav.canOpen(deep) ? deep : (nav.canOpen(legacy) ? legacy : null));
  final focus = _attentionFocus(dest, '${m['key'] ?? ''}', link['params']);

  final items = <Map>[for (final it in (m['items'] as List?) ?? const []) if (it is Map) it];
  final shown = items.length > 5 ? items.sublist(0, 5) : items;
  final more = count - shown.length;
  final detail = '${m['detail'] ?? ''}'.trim();

  return ForkCard(
    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
    // The card caps the offenders at five and drops the server's prose the
    // moment it has any of them; the sheet carries both in full. The "Open
    // <dest>" button below stays exactly where it was — the card tap is the
    // additional way in, never a replacement for it, and never the destructive
    // one (nothing on this screen destroys anything).
    onTap: () => _concernSheet(context, m, dest: dest, focus: focus, windowDays: windowDays),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        StatusChip(label: severity.toUpperCase(), color: colour, dense: true),
        const SizedBox(width: AppSpacing.sm),
        Expanded(
          child: Text(title, style: text.titleSmall, maxLines: 2, overflow: TextOverflow.ellipsis),
        ),
        if (amount != null) ...[
          const SizedBox(width: AppSpacing.sm),
          Text(_money(amount), style: text.titleSmall?.copyWith(color: AppColors.copperHi)),
        ],
      ]),
      const SizedBox(height: 8),
      Text('$count affected', style: text.labelSmall),
      const SizedBox(height: 8),
      // Names, not a count. A bare "6 items low on stock" sends the owner off to
      // find out WHICH six; the server already knows and sends them.
      if (shown.isNotEmpty) ...[
        for (final it in shown)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 2),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Padding(
                padding: EdgeInsets.only(top: 5, right: 7),
                child: Icon(Icons.circle, size: 4, color: AppColors.textTertiary),
              ),
              Expanded(
                child: Text('${it['label'] ?? ''}',
                    style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
              ),
              if ('${it['sub'] ?? ''}'.trim().isNotEmpty) ...[
                const SizedBox(width: AppSpacing.sm),
                Flexible(
                  child: Text('${it['sub']}',
                      textAlign: TextAlign.right,
                      style: TextStyle(fontSize: 11, color: AppColors.textSecondary),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis),
                ),
              ],
            ]),
          ),
        if (more > 0)
          Padding(
            padding: const EdgeInsets.only(top: 3),
            child: Text('and $more more',
                style: TextStyle(fontSize: 10.5, color: AppColors.textTertiary)),
          ),
      ] else if (detail.isNotEmpty)
        Text(detail, style: text.bodySmall?.copyWith(color: AppColors.textSecondary)),
      const SizedBox(height: 12),
      // The suggested action, always — every concern on this screen carries one,
      // and a problem stated without a next step is just bad news.
      Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        decoration: BoxDecoration(
          color: AppColors.tint(colour),
          borderRadius: AppRadius.controlAll,
          border: Border.all(color: AppColors.edge(colour)),
        ),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Icon(Icons.tips_and_updates_outlined, size: 14, color: colour),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              advice.isEmpty
                  // The server sends advice for every key it knows and a generic
                  // sentence for one it does not, so this is a last resort — and
                  // it still names a destination rather than shrugging.
                  ? 'Open ${dest ?? legacy} and clear these $count.'
                  : advice,
              style: text.bodySmall,
            ),
          ),
        ]),
      ),
      if (dest != null) ...[
        const SizedBox(height: 10),
        Align(
          alignment: Alignment.centerLeft,
          child: ForkButton.ghost(
            label: 'Open $dest',
            icon: Icons.arrow_forward,
            dense: true,
            onPressed: () => nav!.openModule(dest, target: focus),
          ),
        ),
      ],
    ]),
  );
}

/// The whole concern, which the card can only ever show part of: EVERY
/// offender (the card stops at five), the server's prose (the card drops it as
/// soon as it has structured rows), and the window the count was measured over.
///
/// The jump is [_detailSheet]'s, so it carries the same filtered focus payload
/// the card's button does — only keys the destination actually reads travel,
/// and a concern with no reachable module simply has no jump.
Future<void> _concernSheet(
  BuildContext context,
  Map m, {
  required String? dest,
  required Map<String, dynamic>? focus,
  required int windowDays,
}) {
  final text = Theme.of(context).textTheme;
  final severity = '${m['severity'] ?? 'low'}';
  final count = _numOf(m['count']).round();
  final advice = '${m['what_to_do'] ?? ''}'.trim();
  final detail = '${m['detail'] ?? ''}'.trim();
  final amount = m['amount'];
  final items = <Map>[for (final it in (m['items'] as List?) ?? const []) if (it is Map) it];
  // The server sends the worst offenders, not necessarily all of them, so a
  // shortfall is stated rather than left as a silent disagreement with `count`.
  final unlisted = count - items.length;

  return _detailSheet(
    context,
    eyebrow: _concernBandTitle(severity),
    title: '${m['title'] ?? m['label'] ?? ''}'.trim(),
    jumpTo: dest,
    jumpTarget: focus,
    children: [
      _detailRow(context, 'Affected', '$count'),
      if (amount != null) _detailRow(context, 'At stake', _money(amount)),
      _detailRow(context, 'Measured over', 'Last $windowDays days'),
      if (detail.isNotEmpty) ...[
        const SizedBox(height: AppSpacing.md),
        Text(detail, style: text.bodySmall?.copyWith(color: AppColors.textSecondary)),
      ],
      if (items.isNotEmpty) ...[
        const SizedBox(height: AppSpacing.lg),
        Text('AFFECTED', style: text.labelSmall),
        for (final it in items)
          _detailRow(
            context,
            '${it['label'] ?? ''}',
            '${it['sub'] ?? ''}'.trim().isNotEmpty
                ? '${it['sub']}'
                : (it['value'] == null ? '—' : _score(it['value'])),
          ),
        if (unlisted > 0)
          Padding(
            padding: const EdgeInsets.only(top: 4),
            child: Text('$unlisted more not listed by the server.',
                style: text.bodySmall?.copyWith(color: AppColors.textTertiary)),
          ),
      ],
      if (advice.isNotEmpty) ...[
        const SizedBox(height: AppSpacing.lg),
        Text('WHAT TO DO', style: text.labelSmall),
        const SizedBox(height: 6),
        Text(advice, style: text.bodySmall),
      ],
    ],
  );
}

/// One severity's summary pill, which doubles as the filter for that band.
///
/// A band with nothing in it renders as a plain chip: no click cursor, no tap.
/// Selection is spelled out in the label, so the state is never carried by the
/// tint alone (same rule as every other chip here).
Widget _concernBandChip(String severity, int count, {required bool selected, VoidCallback? onTap}) {
  final chip = StatusChip(
    label: selected ? '$count $severity · only' : '$count $severity',
    color: _concernColor(severity),
  );
  if (onTap == null) return chip;
  return MouseRegion(
    cursor: SystemMouseCursors.click,
    child: GestureDetector(onTap: onTap, child: chip),
  );
}

/// Everything that needs a person, worst first.
///
/// Reads GET /analytics/concerns, which EXTENDS the Overview strip's
/// `needs_attention` rather than re-detecting it — so a count here and a count
/// on the Overview can never disagree. Gated on the same analytics permission as
/// the rest of /analytics/*, which is what the module's keywords mirror.
Widget concernsModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () => rest.getMap('/analytics/concerns?days=30'),
      builder: (context, data, reload) => _ConcernsBoard(data: data, reload: reload),
    );

/// Stateful only for the severity filter. The summary pills and the band
/// headings are the same control from two places — on a busy day this list runs
/// well past a screen, and "show me only the ones I have to deal with today" is
/// the question those two counts were already being asked.
class _ConcernsBoard extends StatefulWidget {
  const _ConcernsBoard({required this.data, required this.reload});

  final Map<String, dynamic> data;
  final VoidCallback reload;

  @override
  State<_ConcernsBoard> createState() => _ConcernsBoardState();
}

class _ConcernsBoardState extends State<_ConcernsBoard> {
  /// Severity the list is narrowed to, or null for everything.
  String? _band;

  @override
  Widget build(BuildContext context) {
    final data = widget.data;
    final reload = widget.reload;
    final nav = ModuleNavigator.of(context);
    final text = Theme.of(context).textTheme;
    final all = <Map>[for (final c in (data['concerns'] as List?) ?? const []) if (c is Map) c];
    final totals = (data['totals'] as Map?) ?? const {};
    final windowDays = _int(data['window_days']) ?? 30;

    if (all.isEmpty) {
      // Good news, not a failed load: an empty list is the state an owner is
      // trying to reach, so it reads as an achievement rather than an error.
      return EmptyState(
        icon: Icons.verified_outlined,
        title: 'Nothing needs your attention',
        caption: 'No open concerns across stock, bills, approvals, staff, guest '
            'feedback or suppliers in the last $windowDays days. Anything that '
            'goes wrong shows up here on its own.',
        // Nothing to drill into, so the state offers the two things that are
        // still true: ask the server again, or go back to the day's numbers.
        action: Wrap(
          alignment: WrapAlignment.center,
          spacing: AppSpacing.sm,
          runSpacing: AppSpacing.sm,
          children: [
            ForkButton.ghost(
                label: 'Check again', icon: Icons.refresh, dense: true, onPressed: reload),
            if (nav?.canOpen('Overview') ?? false)
              ForkButton(
                label: 'Back to Overview',
                icon: Icons.arrow_forward,
                dense: true,
                onPressed: () => nav!.openModule('Overview'),
              ),
          ],
        ),
      );
    }

    int bandCount(String sev) => all.where((c) => '${c['severity'] ?? 'low'}' == sev).length;
    // A refresh can empty the band that was selected; falling back to "all"
    // beats showing a filtered screen with nothing on it and no explanation.
    final band = _band != null && bandCount(_band!) > 0 ? _band : null;

    final width = MediaQuery.sizeOf(context).width;
    final cols = width >= 1500 ? 3 : (width >= 1000 ? 2 : 1);

    final children = <Widget>[
      SectionHeader(
        title: 'Concerns',
        count: all.length,
        trailing: ForkButton.ghost(
            label: 'Refresh', icon: Icons.refresh, dense: true, onPressed: reload),
      ),
      Wrap(spacing: 8, runSpacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
        for (final sev in _concernSeverities)
          _concernBandChip(
            sev,
            _int(totals[sev]) ?? bandCount(sev),
            selected: band == sev,
            onTap: bandCount(sev) == 0
                ? null
                : () => setState(() => _band = band == sev ? null : sev),
          ),
        InfoChip(icon: Icons.date_range, label: 'Last $windowDays days'),
        if (band != null)
          ForkButton.subtle(
            label: 'Show every severity',
            icon: Icons.close,
            onPressed: () => setState(() => _band = null),
          ),
      ]),
      const SizedBox(height: 16),
    ];

    for (final sev in _concernSeverities) {
      if (band != null && sev != band) continue;
      final rows = all.where((c) => '${c['severity'] ?? 'low'}' == sev).toList();
      if (rows.isEmpty) continue;
      children.addAll([
        _TapRow(
          onTap: () => setState(() => _band = band == sev ? null : sev),
          child: SectionHeader(
            title: _concernBandTitle(sev),
            count: rows.length,
            trailing: Text(band == sev ? 'Showing only this band' : 'Show only this band',
                style: text.labelSmall),
          ),
        ),
        _dashGrid([for (final c in rows) _concernCard(context, c, nav, windowDays)], cols),
        const SizedBox(height: 20),
      ]);
    }

    final generated = _s(data, 'generated_at', '');
    if (generated.isNotEmpty) {
      children.add(Text('Checked ${RestaurantTime.stamp(generated)}', style: text.labelSmall));
    }

    return ListView(padding: AppSpacing.pageNarrow, children: children);
  }
}

// Tables are uniform, tappable boxes (not organised by seat count — any table
// can seat a flexible number of people). Tap a free table to seat guests; tap
// an occupied one to see its single consolidated bill + APC, or release it.
/// THE TABLES SCREEN — service. See [FloorSurface] for the split, which is
/// requirement D5.
///
/// Read the floor, open a table, take the order, print, settle. It moves,
/// re-labels and deletes NOTHING: no "Add table", no drag between sections, no
/// section create / rename / dissolve / arrange, and no "Edit seating" or
/// "Delete table" on the sheet it opens. Those are all still there, for everyone
/// who had them, on [floorPlanModule].
Widget tablesModule(RestClient rest, Profile p) => _floorModule(rest, p, FloorSurface.service);

/// THE FLOOR PLAN SCREEN — layout. The other half of D5, and the one place
/// 'Delete table' now lives (C7 / H8).
///
/// Everything the Tables screen used to carry and no longer does: the "Add
/// table" button, the section groups with their drag-and-drop, Arrange / New
/// section / Rename / Remove, "Edit seating", and the delete control in this
/// screen's own header.
///
/// It is the SAME widget as Tables with the surface flipped, deliberately.
/// Two screens that render one floor out of two code paths is how the zone order
/// on one comes to disagree with the zone order on the other — and the floor
/// plan is the screen where that disagreement would be invisible until somebody
/// dragged a table into a section that is not where they are looking.
Widget floorPlanModule(RestClient rest, Profile p) => _floorModule(rest, p, FloorSurface.plan);

Widget _floorModule(RestClient rest, Profile p, FloorSurface surface) => AsyncView<Map<String, dynamic>>(
      load: () async {
        // 6.4 — the live gross above the grid, read ALONGSIDE the floor rather
        // than after it: started first so it costs no extra wait, and read in
        // this loader so the box refreshes exactly when the tiles do and can
        // never describe a different moment from them. Service surface only —
        // the floor plan is a layout editor, and 2.1 keeps the live floor off
        // it. limit=1: only the envelope's totals are wanted, and
        // `running_total` spans every running table whatever the page size.
        // Never throws: a failure is filed as a word for the builder (see
        // [liveGrossFailure]), because the floor must still render without it.
        final liveGross = surface != FloorSurface.service
            ? null
            : rest.getMap('/bills/open?limit=1').then<Object>((page) => page, onError: (Object e) => liveGrossFailure(e));
        final tables = await rest.getList('/get-tables');
        // 2.1 — "WHAT IS SEEN IN TABLES IS NOT SHOWN IN THE FLOOR PLAN." Who is
        // waiting on a table and which booking it is clubbed into are the live
        // floor, and the layout editor draws neither (see [_TableBox]), so it
        // does not ask for them either.
        final live = surface == FloorSurface.service;
        List assignments = const [];
        if (live) {
          try {
            assignments = await rest.getList('/table-assignments');
          } catch (_) {/* assignments are optional */}
        }
        // A clubbed party (T1 + T2) lives on the BOOKING, not on the table, so
        // the floor plan has to fold it in to be able to mark it.
        final clubbed = <String, List<String>>{};
        if (live) {
          try {
            for (final b in await rest.getList('/get-bookings')) {
              final status = _s(b as Map, 'status', '').toLowerCase();
              if (status.contains('cancel') || status.contains('no')) continue;
              final names = _strList(b['table_names']);
              if (names.length < 2) continue;
              for (final n in names) {
                clubbed[n.toLowerCase()] = names;
              }
            }
          } catch (_) {/* bookings are optional here */}
        }
        final byName = <String, Map>{};
        for (final a in assignments) {
          byName[_s(a as Map, 'table_name').toLowerCase()] = a;
        }
        for (final t in tables) {
          final m = t as Map;
          final key = _s(m, 'table_name').toLowerCase();
          final a = byName[key];
          if (a != null) {
            m['waiter_name'] = a['employee_name'];
            m['waiter_id'] = a['employee_id'];
          }
          final set = clubbed[key];
          if (set != null) {
            m['clubbed_with'] = set.where((n) => n.toLowerCase() != key).toList();
          }
        }
        // The zone ROSTER is the second source a floor plan needs. A zone with no
        // tables in it exists ONLY there, so without this call a zone created on
        // the web (or here) is invisible until something is dragged into it —
        // which is the whole reason "Add section" used to be web-only.
        //
        // GET /table-sections carries the same "Manage Table Sections" gate as
        // the writes, so an unpermitted user must not ask for it: they'd collect
        // a 403 for a roster they can't act on, and the zones their tables DO
        // carry still render underneath.
        var zones = const <String>[];
        var zoneError = '';
        // The outlet's chosen section ORDER (migration 041), keyed the way the
        // backend resolves a zone: lower(trim(name)) -> 1-based position. A key
        // that is absent has no position and belongs in the alphabetical tail —
        // which, on an outlet nobody has rearranged, is every key, so this map
        // is empty and the floor plan reads exactly as it did on 1.8.5.
        final order = <String, int>{};
        // ...and, for every zone the owner has NOT positioned, when it came into
        // being. That is the order the floor now reads in by default: a
        // restaurant is built Entrance, then Main Hall, then Terrace, and that
        // sequence is a real choice the owner already made. Alphabetical was
        // never one — it was the only total order the schema could express
        // before there was a column to put a position in.
        final born = <String, DateTime>{};
        // Both ride on the TABLES as well as on the admin-gated roster, so a
        // manager or waiter who can see the floor but not the roster still sees
        // the sections in the same order the owner does.
        for (final t in tables) {
          final label = _s(t as Map, 'section', '').trim();
          if (label.isEmpty) continue;
          final key = label.toLowerCase();
          final pos = _int(t['section_position']);
          if (pos != null) order.putIfAbsent(key, () => pos);
          final at = DateTime.tryParse(_s(t, 'section_created_at', ''));
          if (at != null) born.putIfAbsent(key, () => at);
        }
        if (_canManageSections(p)) {
          try {
            final roster = await rest.getMap('/table-sections');
            final rows = ((roster['sections'] as List?) ?? const []).whereType<Map>();
            zones = rows.map((s) => _s(s, 'section', '').trim()).where((s) => s.isNotEmpty).toList();
            // The roster is the only source that knows an EMPTY zone's position;
            // it has no table to carry one.
            for (final s in rows) {
              final label = _s(s, 'section', '').trim();
              if (label.isEmpty) continue;
              final key = label.toLowerCase();
              final pos = _int(s['sort_order']);
              if (pos != null) order[key] = pos;
              // The roster is also the only source that knows when an EMPTY
              // zone was created — it has no table to have been dated by.
              final at = DateTime.tryParse(_s(s, 'created_at', ''));
              if (at != null) born[key] = at;
            }
          } catch (e) {
            // Not swallowed into an empty roster: the floor still renders from
            // the tables, and the banner says which half is missing.
            zoneError = '$e';
          }
        }
        // Only the NAMES and their positions are kept. Table and seat counts are
        // derived from the rows rendered below, so a group header can never
        // disagree with the tiles inside it.
        // REQUIREMENT C3'S BOOKKEEPING, done off a read that has already happened.
        //
        // A table this device printed stops being "printed" the moment its
        // sitting ends, however it ends — settled, released, merged away. The
        // floor read above is the only thing that knows that, so it is what
        // clears the record; asking the server a second question would be a
        // second answer to one the list in hand has just given.
        try {
          await PrintedBills.instance.load(p.resId, p.outletId);
          await PrintedBills.instance.reconcile(
            p.resId,
            p.outletId,
            [for (final t in tables) if (_tableSeated(t as Map)) _s(t, 'table_name')],
          );
        } catch (_) {/* a device memory must never fail a floor read */}
        return {
          'tables': tables,
          'zones': zones,
          'zone_error': zoneError,
          'order': order,
          'born': born,
          'live_gross': await liveGross,
        };
      },
      builder: (context, data, reload) {
        final scope = FloorScope.of(p, surface: surface);
        final allRows = (data['tables'] as List?) ?? const [];
        // REQUIREMENT C3 — "the table should clear/reset from their view".
        //
        // THEIR VIEW, and nothing else. The row leaves this one grid on this one
        // device; the table is still occupied, still owes the money, still on
        // every manager's screen and still on the Floor plan. Nothing is written
        // — see [BillPrintScope] for why "clear the table" could not be what was
        // meant, given C2 says the same waiter may not settle.
        //
        // Only on the SERVICE surface. The floor plan is a picture of the room,
        // and a room with a table missing out of it is not a floor plan.
        //
        // CLIENT ITEM 6 — AND THE ROOM HAS NO "12 #2" IN IT. A next-party seat
        // ([isNextPartyRow]) is a second name for a table the plan already
        // draws, opened by the server when 12's bill was printed and retired
        // once it is idle; it is not furniture, so the layout editor never
        // shows it. On the service surface it is an ordinary row and passes
        // the C3 filter below on ITS OWN print state: the printed party at 12
        // leaves the waiter's grid, and the tile for the next party at 12 is
        // exactly what they are left with.
        final List rows = surface != FloorSurface.service
            ? [for (final r in allRows) if (!isNextPartyRow(r as Map)) r]
            : [
                for (final r in allRows)
                  if (!BillPrintScope.of(p,
                          // THE SERVER DECIDES, AND THE `??` IS THE WHOLE POINT.
                          // When the row carries print state at all, that state
                          // is the answer — including when it says "not printed"
                          // and this tablet remembers otherwise. The per-device
                          // memory is reached ONLY on the null, which means the
                          // backend shipped no print state on this payload; see
                          // [serverBillPrintState] for the exact keys and
                          // [PrintedBills] for what that fallback is worth (it
                          // survives a restart, not a reinstall and not a second
                          // tablet).
                          printed: serverBillPrintState(r as Map) ??
                              PrintedBills.instance
                                  .printed(p.resId, p.outletId, _s(r, 'table_name')))
                      .retiresTable)
                    r,
              ];
        final zones = ((data['zones'] as List?) ?? const []).map((z) => '$z').toList();
        final zoneError = _s(data, 'zone_error', '');
        final zoneOrder = (data['order'] as Map?)?.cast<String, int>() ?? const <String, int>{};
        final zoneBorn = (data['born'] as Map?)?.cast<String, DateTime>() ?? const <String, DateTime>{};
        // Counted off the SAME three-state rule the cards paint with, so the
        // legend can never disagree with what is on screen.
        final occ = rows.where((r) => _tableState(r as Map).label == 'Occupied').length;
        final waiting = rows.where((r) => _tableState(r as Map).label == 'Seated').length;
        // A PARTY at "12 #2" is counted like any other (it is somebody to
        // serve), but an idle next-party seat is not a free TABLE — 12 is
        // already counted — and it carries 12's booking, so it would count a
        // reservation twice. Free and Reserved are the room's.
        final res = rows
            .where((r) => !isNextPartyRow(r as Map) && _tableState(r).label == 'Reserved')
            .length;
        final free = rows
            .where((r) => !isNextPartyRow(r as Map) && _tableState(r).label == 'Free')
            .length;
        // A caller (an order notification's "Open T4") asked us to focus a table.
        final focus = _focusOf(context, 'Tables');
        final focusTable = focus?.tableName ?? focus?.idOf(const ['table_name']);
        final focusFound = focusTable != null && rows.any((r) => _s(r as Map, 'table_name') == focusTable);
        final serviceLegend = <Widget>[
          StatusChip(label: '$occ Occupied', color: AppColors.copper, dense: true),
          // Only when there IS one. A restaurant where every seated table has
          // ordered should not carry a permanent "0 Seated" chip explaining a
          // distinction it never sees.
          if (waiting > 0)
            StatusChip(label: '$waiting Seated', color: AppColors.warning, dense: true),
          StatusChip(label: '$res Reserved', color: AppColors.info, dense: true),
          StatusChip(label: '$free Free', color: AppColors.neutral, dense: true),
        ];
        // 2.1 — ON THE FLOOR PLAN THE HEADER READS THE ROOM, NOT THE SERVICE.
        // "4 Occupied · 23 Free" is the Tables screen's read-out (2.2), and the
        // requirement is that what Tables shows, the Floor plan does not. The
        // layout editor counts what it edits: tables and the seats they lay.
        final layoutLegend = <Widget>[
          StatusChip(
              label: '${rows.length} table${rows.length == 1 ? '' : 's'}',
              color: AppColors.neutral,
              dense: true),
          StatusChip(
              label: '${rows.fold<int>(0, (n, r) => n + (_int((r as Map)['capacity']) ?? 0))} seats',
              color: AppColors.neutral,
              dense: true),
        ];
        final legend = surface == FloorSurface.plan ? layoutLegend : serviceLegend;
        final legendBelow = MediaQuery.sizeOf(context).width < 620;
        // REQUIREMENTS C7 AND H8 — 'Delete table' lives HERE and nowhere else.
        //
        // It used to sit at the bottom of the per-table sheet, which is the sheet
        // a waiter opens to take an order and a manager opens to settle a bill:
        // the two busiest taps of a service, with an irreversible floor edit
        // parked one scroll under them. H8 asks for it in the Floor header and
        // for the UI to be explicit about what the action does — so it is a
        // named control on the layout screen, it makes you pick the table by
        // name, and the confirmation spells out what survives (see
        // [_deleteTableFromHeader]).
        final headerActions = <Widget>[
          if (scope.deleteTable && allRows.isNotEmpty)
            ForkButton.ghost(
              key: const ValueKey('floor-delete-table'),
              label: 'Delete a table',
              icon: Icons.delete_outline,
              dense: true,
              // Room tables only: the server refuses a next-party seat, which
              // closes by itself once it is idle (client item 6).
              onPressed: () => _deleteTableFromHeader(
                  context, rest, [for (final r in allRows) if (!isNextPartyRow(r as Map)) r], reload),
            ),
        ];
        return Scaffold(
          backgroundColor: Colors.transparent,
          // See [FloorScope.addTable]: the floor's layout controls travel
          // together, and a waiter has none of them.
          floatingActionButton: !scope.addTable
              ? null
              : FloatingActionButton.extended(
            onPressed: () => _addTable(
              context,
              rest,
              reload,
              // Zones already on the floor: the labels the loaded tables carry,
              // plus the roster names (which is where an EMPTY zone lives — a
              // brand-new zone is precisely the one you want to place a table
              // into). De-duplicated case-insensitively, the way the backend
              // resolves a zone. Placing a table in an existing zone still needs
              // no sections permission.
              sections: () {
                final byKey = <String, String>{};
                for (final r in rows) {
                  final v = _s(r as Map, 'section', '').trim();
                  if (v.isNotEmpty) byKey.putIfAbsent(v.toLowerCase(), () => v);
                }
                for (final z in zones) {
                  final v = z.trim();
                  if (v.isNotEmpty) byKey.putIfAbsent(v.toLowerCase(), () => v);
                }
                return byKey.values.toList()..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
              }(),
              // Every name on the floor, so a numbered run steps over the ones
              // already taken instead of collecting "Table exists" from the
              // server halfway through.
              existing: [
                for (final r in rows)
                  if (!isNextPartyRow(r as Map)) _s(r, 'table_name', ''),
              ],
            ),
            icon: const Icon(Icons.add),
            label: const Text('Add table'),
          ),
          // A restaurant with zones but no tables yet is a real state now that a
          // zone can exist on its own — don't hide the roster behind "no tables".
          body: rows.isEmpty && allRows.isNotEmpty
              // C3: every table this waiter had is printed and off their list.
              // Said in words, because a blank grid on the screen they land on
              // reads as an outage rather than as a finished section.
              ? _empty('Nothing open for you right now — every table you printed '
                  'has gone to a manager to settle.')
              : rows.isEmpty && zones.isEmpty
              ? _empty(scope.addTable
                  ? 'No tables yet — add one with the button below.'
                  : 'No tables on the floor yet.')
              : SingleChildScrollView(
                  padding: AppSpacing.pageNarrow,
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    if (focus != null)
                      _focusBanner(
                        context,
                        found: focusFound,
                        message: focusFound
                            ? 'Highlighted $focusTable — tap it to manage the bill.'
                            : '${focusTable ?? 'That table'} is not on this floor plan — it may have been removed, or belong to another outlet.',
                      ),
                    // 6.4 — what is on the floor right now, ABOVE the tables:
                    // "what is out there" before "which table". For a waiter it
                    // is the count alone ([FloorScope.money], and the server
                    // strips the amount as well); a user refused /bills/open
                    // does not get a box at all.
                    if (surface == FloorSurface.service && data['live_gross'] != liveGrossRefused)
                      LiveGrossBox(
                        view: readLiveGross(
                          data['live_gross'] is Map ? data['live_gross'] as Map : null,
                          showMoney: scope.money,
                        ),
                      ),
                    // Legend doubles as the occupancy read-out — tint + label,
                    // never colour alone. On a phone it moves to its own line:
                    // three chips do not fit beside the title, and in the header
                    // row they overflowed it by ~215px.
                    // NOT FOR A WAITER — see [FloorScope.floorSummary]. "23 Free"
                    // is a fact about the restaurant on a screen that is
                    // otherwise about this waiter's own tables, and it is the
                    // first thing they see, because Tables is where they land.
                    if (scope.floorSummary) ...[
                      SectionHeader(
                        title: surface == FloorSurface.plan ? 'Floor plan' : 'Tables',
                        count: rows.length,
                        padding: EdgeInsets.only(bottom: legendBelow ? 8 : 14),
                        trailing: legendBelow
                            ? null
                            : Wrap(
                                spacing: 6,
                                runSpacing: 6,
                                crossAxisAlignment: WrapCrossAlignment.center,
                                children: [...legend, ...headerActions]),
                      ),
                      if (legendBelow)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 10),
                          child: Wrap(
                              spacing: 6,
                              runSpacing: 6,
                              crossAxisAlignment: WrapCrossAlignment.center,
                              children: [...legend, ...headerActions]),
                        ),
                    ]
                    // The header carries the delete control (H8) and a waiter has
                    // no summary strip to hang it off. They also have no delete —
                    // but if that ever changes, the control must not vanish with
                    // the strip, so it gets its own row rather than living inside
                    // an `if` about something else.
                    else if (headerActions.isNotEmpty)
                      Padding(
                        padding: const EdgeInsets.only(bottom: 10),
                        child: Wrap(spacing: 6, runSpacing: 6, children: headerActions),
                      ),
                    // Floor SECTIONS — create / rename / un-label, and drag a
                    // table from one zone to another. See [_FloorSections].
                    _FloorSections(
                      surface: surface,
                      rows: rows,
                      zones: zones,
                      zoneError: zoneError,
                      zoneOrder: zoneOrder,
                      zoneBorn: zoneBorn,
                      rest: rest,
                      profile: p,
                      reload: reload,
                      focusTable: focusTable,
                    ),
                  ]),
                ),
        );
      },
    );


// ------------------------------------------------------- floor sections ----
// A zone lives in TWO places and this view reads both. "Tables".section says
// which zone each table sits in (a drag is one single-row `PATCH /table/:name
// {section}`), and the ROSTER — `GET /table-sections` — records that the NAME
// exists, which is the only place a zone with no tables in it can be. Reading
// the tables alone was the app's gap: a zone created on the web stayed invisible
// here until somebody dragged a table into it.
//
// So the writes are:
//   POST   /table-sections        mint the name (a zone can now start empty)
//   PATCH  /table-sections/:name  rename it
//   DELETE /table-sections/:name  dissolve it (its tables become unassigned)
//   PATCH  /table/:name {section} move ONE table between zones
// Nothing here ever bulk-writes the floor, and nothing ever sends a field the
// user didn't change: a PATCH that also carried capacity once stamped
// max_capacity onto every table it touched.
//
// Both kinds of write are optimistic. The new grouping shows the instant a table
// is dropped (or a zone is minted) and is rolled back only if the call fails.
// The optimistic value is kept until the reloaded data agrees with it, so a
// successful write never flickers back while the refresh is still in flight.

// C3 — HAS THE SERVER SAID THIS TABLE'S CURRENT BILL IS ALREADY PRINTED?
//
// THE FIELDS THIS CLIENT READS, WHICH IS THE CONTRACT THE BACKEND LANE OWES:
//
//   * `bill_printed_at` — ISO instant of the FIRST print of the CURRENT bill,
//     cleared whenever the seating ends (settled, released, merged away), so
//     the next party at T4 starts clean. The preferred field: an instant can
//     also be shown to the waiter ("printed 18:42"), which a bare count cannot.
//   * `printed_at` / `last_printed_at` — the same thing under the names the
//     bill reader might more naturally use. Accepted so the backend lane is not
//     forced into one spelling.
//   * `print_count` — an integer, for a server that counts rather than stamps.
//     ZERO IS AN ANSWER, not a silence; see [serverBillPrintState].
//
// AND IT IS NEEDED IN TWO PLACES, not one: on `/bill-for-table` (the sheet,
// which decides whether to draw the button) AND on the `/get-tables` row (the
// floor grid, which decides whether the table is still on this waiter's
// screen). Without the second, C3's "clear from their view" survives a
// back-navigation on the device that printed and nowhere else. Both halves are
// pinned against the backend's own source in
// test/bill_print_authority_test.dart, so the day either payload stops carrying
// print state is the day a test goes red rather than the day this app silently
// starts answering from a tablet's memory again.

/// The keys that carry print state, in preference order. A row that contains
/// ANY of them is a server that has answered; a row that contains NONE of them
/// is a backend too old to have been asked.
const List<String> billPrintStateKeys = [
  'bill_printed_at',
  'printed_at',
  'last_printed_at',
  'print_count',
];

/// THREE ANSWERS, NOT TWO: printed, not printed, and NOBODY ASKED.
///
/// THE DEFECT THIS CLOSES. The grid used to fold the server's answer and this
/// device's memory together with `||`, which quietly made the DEVICE the
/// authority in the one case that matters: the server says `print_count: 0`
/// (this seating's bill has not been printed — the last one was, and the table
/// has since turned over) and a stale local record says it has. An `||` keeps
/// the table off that waiter's screen forever, on that tablet only. Whoever the
/// server is describing, it is describing the CURRENT bill, and it is describing
/// it identically to every device in the building.
///
/// So: `true`/`false` when the payload carries print state, and `null` — "no
/// answer" — only when it carries none of [billPrintStateKeys] at all. The
/// `null` is what the per-device fallback is allowed to fill, and nothing else
/// is.
///
/// PRESENCE OF THE KEY IS THE SIGNAL, not truthiness of its value. `print_count:
/// 0` and `bill_printed_at: null` are the server SAYING "not printed" for an
/// unprinted table — that is the ordinary case, not silence — and reading them
/// as silence would hand the answer straight back to the device memory this
/// exists to demote.
///
/// IT STILL FAILS SAFE. Silence means the waiter keeps their button and can bill
/// the table in front of them; a guest waiting with no way to get a bill is a
/// worse outage than a second copy of one.
@visibleForTesting
bool? serverBillPrintState(Map? row) {
  if (row == null) return null;
  var answered = false;
  for (final k in const ['bill_printed_at', 'printed_at', 'last_printed_at']) {
    if (!row.containsKey(k)) continue;
    answered = true;
    if ('${row[k] ?? ''}'.trim().isNotEmpty) return true;
  }
  if (row.containsKey('print_count')) {
    answered = true;
    if ((num.tryParse('${row['print_count'] ?? ''}') ?? 0) > 0) return true;
  }
  return answered ? false : null;
}

/// "Did the server say printed?" — [serverBillPrintState] with no answer read as
/// no. Kept for readers that genuinely have nothing to fall back to; anything
/// that HAS a fallback must use the tri-state, or it re-introduces the `||`.
@visibleForTesting
bool serverSaysBillPrinted(Map? row) => serverBillPrintState(row) ?? false;

/// Re-seating is ordinary floor work — the backend keeps a move onto an
/// EXISTING label on the same `Table Added` gate the floor already holds.
///
/// THE SERVER'S `edit_table` DECIDES IT. The keyword test below is the fallback
/// for a backend that predates the flag, and it was never more than a guess:
/// `p.can(['table'])` substring-matches permitted ACTION NAMES, so it says yes
/// to anybody holding any action with "table" in its name — "Table Sections",
/// "View Table" — whether or not the server would accept the write.
bool _canMoveTables(Profile p) =>
    RoleScope.may(p, Capability.editTable, fallback: p.can(['table']));

/// Minting, renaming or dissolving a zone is administration ("Manage Table
/// Sections"). Admins keep everything, as everywhere else in this app.
bool _canManageSections(Profile p) => RoleScope.may(p, Capability.manageTableSections,
    fallback: p.isAdmin || p.can(['table section']));

/// The floor grouped by section: a header per group with its table and seat
/// counts, drag-and-drop between groups, and (for admins) create / rename /
/// un-label. Every zone on the roster gets a group even when it holds nothing.
/// "Unassigned" always renders LAST so no table is hidden behind a section it
/// hasn't been given yet.
class _FloorSections extends StatefulWidget {
  /// WHICH FLOOR SCREEN THIS IS — requirement D5. On [FloorSurface.service] the
  /// groups are a READ: no drag, no drop target, no Arrange / New section /
  /// Rename / Remove. The zones, the counts and the tiles are identical, because
  /// "you may not re-layout the floor here" is not the same sentence as "you may
  /// not see how the floor is laid out".
  final FloorSurface surface;

  final List rows;

  /// Zone names off `GET /table-sections`. Empty for a user without the
  /// sections permission (the roster is gated), who then sees only the zones
  /// the tables themselves carry.
  final List<String> zones;

  /// Why the roster couldn't be read, '' when it was. Never silently empty:
  /// a blank roster and a failed one look identical on screen otherwise.
  final String zoneError;

  /// The outlet's chosen section order: zone key (lower-cased, trimmed) -> its
  /// 1-based position. A key that is ABSENT has no chosen position and sorts
  /// into the alphabetical tail — so an empty map is 1.8.5's behaviour exactly,
  /// and that is the state of every outlet until somebody rearranges one.
  final Map<String, int> zoneOrder;

  /// When each zone first existed: zone key -> the earliest evidence the server
  /// has of it (its roster row, or the first table ever put in it — whichever
  /// is older; see readSectionBirthByKey). This is the tail of the order —
  /// everything the owner has never dragged sorts by it, oldest first.
  ///
  /// A key that is ABSENT has no known birth and falls through to the
  /// alphabetical tiebreak, so an outlet whose instants could not be read
  /// renders exactly as 1.8.5 did rather than in some arbitrary order.
  final Map<String, DateTime> zoneBorn;
  final RestClient rest;
  final Profile profile;
  final VoidCallback reload;
  final String? focusTable;
  const _FloorSections({
    required this.surface,
    required this.rows,
    required this.zones,
    required this.zoneError,
    required this.zoneOrder,
    required this.zoneBorn,
    required this.rest,
    required this.profile,
    required this.reload,
    this.focusTable,
  });

  @override
  State<_FloorSections> createState() => _FloorSectionsState();
}

class _FloorSectionsState extends State<_FloorSections> {
  /// table name (lower-cased) -> section, `null` meaning unassigned. Optimistic
  /// only: an entry lives until the reloaded rows carry the same value.
  final Map<String, String?> _pending = {};

  /// The same bet, one level up: zone name (lower-cased) -> what that zone reads
  /// as now — a new or renamed label, or `null` for one being dissolved. Keyed
  /// case-insensitively because that is how the backend resolves a zone name.
  final Map<String, String?> _zonePending = {};

  /// The same bet for the ORDER: the zone keys in the sequence the user just
  /// dragged them into, held until the server's own order agrees. Null = show
  /// the server's order. Keys not in the list keep no position, so a section
  /// created while a reorder is in flight still falls to the tail rather than
  /// jumping to the front.
  List<String>? _orderPending;

  @override
  void didUpdateWidget(covariant _FloorSections old) {
    super.didUpdateWidget(old);
    // A reorder is confirmed once the reloaded positions rank the same keys in
    // the same sequence. Compared as a RANKING rather than by number because the
    // server renumbers the whole outlet: a stale request that had to be appended
    // to comes back with different integers for the same visible order, and
    // holding the optimistic list any longer than that would fight the reload.
    final pending = _orderPending;
    if (pending != null) {
      final live = widget.zoneOrder;
      var settled = pending.every(live.containsKey);
      if (settled) {
        final ranked = [...pending]..sort((a, b) => live[a]!.compareTo(live[b]!));
        for (var i = 0; i < ranked.length; i++) {
          if (ranked[i] != pending[i]) {
            settled = false;
            break;
          }
        }
      }
      if (settled) _orderPending = null;
    }
    // Drop every optimistic value the server has now confirmed; a build follows
    // this callback, so no setState is needed (or allowed) here.
    if (_pending.isNotEmpty) {
      final live = <String, String?>{};
      for (final r in widget.rows) {
        final m = r as Map;
        final s = _s(m, 'section', '').trim();
        live[_s(m, 'table_name').toLowerCase()] = s.isEmpty ? null : s;
      }
      _pending.removeWhere((k, v) => live.containsKey(k) && live[k] == v);
    }
    if (_zonePending.isNotEmpty) {
      final live = _serverZones();
      // A dissolve is confirmed once the old name is gone; a create or rename
      // once the NEW name is on the roster under its own key.
      _zonePending.removeWhere((key, value) =>
          value == null ? !live.containsKey(key) : live.containsKey(value.toLowerCase()));
    }
  }

  /// Every zone the SERVER currently knows: the labels the tables carry, unioned
  /// with the roster (the only place a zone with no tables exists). Keyed
  /// case-insensitively so a stored "patio" and a table's "Patio" stay ONE zone
  /// — the union the backend itself renders. Table labels win the casing, since
  /// that is what the tiles below actually show.
  Map<String, String> _serverZones() {
    final out = <String, String>{};
    for (final r in widget.rows) {
      final s = _serverSection(r as Map);
      if (s != null) out.putIfAbsent(s.toLowerCase(), () => s);
    }
    for (final z in widget.zones) {
      final name = z.trim();
      if (name.isNotEmpty) out.putIfAbsent(name.toLowerCase(), () => name);
    }
    return out;
  }

  /// The roster as it reads RIGHT NOW: the server's zones with any optimistic
  /// rename/dissolve applied, plus zones minted in this session that the
  /// reloaded roster hasn't caught up with yet.
  Map<String, String> _zonesNow() {
    final out = <String, String>{};
    _serverZones().forEach((key, name) {
      if (!_zonePending.containsKey(key)) {
        out[key] = name;
        return;
      }
      final next = _zonePending[key];
      if (next != null) out[next.toLowerCase()] = next;
    });
    _zonePending.forEach((key, next) {
      if (next != null) out.putIfAbsent(next.toLowerCase(), () => next);
    });
    return out;
  }

  // ---- EDGE AUTO-SCROLL WHILE A TABLE IS BEING DRAGGED ---------------------
  //
  // WHY THIS EXISTS, AND WHAT WAS ACTUALLY BROKEN.
  //
  // "Long-press and drag does nothing" was reported against a drag that, tested
  // on its own, works: a card really does pick up and a drop really does write
  // PATCH /table/:name — under a mouse, under a finger, on Windows and on
  // Android, with and without the app's own scroll behaviour. What does NOT
  // work is doing it on a REAL floor plan. Each zone is ~240px tall, so a
  // restaurant with four sections is already taller than a 1080p window, and
  // the destination is below the fold. Pick a card up, drag it to the bottom
  // edge, hold it there — and the page does not move, because a Draggable has
  // won the gesture arena and the Scrollable is no longer receiving anything.
  // There is nothing to aim at, so the drop lands on whatever zone happens to
  // be under the cursor (usually the one you started in, which is refused) or
  // outside every one of them, which is silently nothing.
  //
  // That is the whole bug, and it is invisible in a test with a tall viewport:
  // the fix is not a different gesture, it is making the destination REACHABLE.
  // Hold a card within [_edge] of the top or bottom of the scroll viewport and
  // the floor plan scrolls under it until the zone you want is on screen.
  //
  // The Scrollable is found from context rather than passed in, so this keeps
  // working whoever owns the scroll view — the module builds it today, and a
  // page that later wraps this widget in its own gets the same behaviour for
  // free.

  /// How close to the viewport edge a dragged card has to be before the floor
  /// plan starts moving. One card height, so the trigger zone is big enough to
  /// hit with a finger and small enough not to fire mid-list.
  static const double _edge = 96;

  /// Pixels per frame at the very edge, tapering to zero at [_edge] away.
  static const double _maxSpeed = 18;

  Timer? _edgeScroll;
  double _edgeSpeed = 0;

  /// Called on every drag update with the pointer in GLOBAL coordinates.
  void _autoScroll(Offset globalPosition) {
    final scrollable = Scrollable.maybeOf(context);
    final box = scrollable?.context.findRenderObject();
    if (scrollable == null || box is! RenderBox || !box.hasSize) {
      _stopAutoScroll();
      return;
    }
    final top = box.localToGlobal(Offset.zero).dy;
    final bottom = top + box.size.height;
    final y = globalPosition.dy;
    // Positive = scroll down (reveal what is below), negative = scroll up.
    var speed = 0.0;
    if (y > bottom - _edge) {
      speed = _maxSpeed * ((y - (bottom - _edge)) / _edge).clamp(0.0, 1.0);
    } else if (y < top + _edge) {
      speed = -_maxSpeed * (((top + _edge) - y) / _edge).clamp(0.0, 1.0);
    }
    _edgeSpeed = speed;
    if (speed == 0) {
      _stopAutoScroll();
      return;
    }
    // One ticker for the whole drag; the speed it reads is updated in place, so
    // moving further into the edge accelerates without restarting anything.
    _edgeScroll ??= Timer.periodic(const Duration(milliseconds: 16), (_) {
      final sc = Scrollable.maybeOf(context);
      if (sc == null || _edgeSpeed == 0) return;
      final pos = sc.position;
      final next = (pos.pixels + _edgeSpeed).clamp(pos.minScrollExtent, pos.maxScrollExtent);
      // jumpTo, not animateTo: the pointer is the animation. An eased scroll
      // would lag behind the finger and land the drop on the wrong zone.
      if (next != pos.pixels) pos.jumpTo(next);
    });
  }

  void _stopAutoScroll() {
    _edgeScroll?.cancel();
    _edgeScroll = null;
    _edgeSpeed = 0;
  }

  @override
  void dispose() {
    // A timer that outlives the drag would keep scrolling a disposed page.
    _stopAutoScroll();
    super.dispose();
  }

  /// Stages an optimistic zone change and hands back exactly what was there
  /// before, so a failed call can put it back (see [_restoreZone]).
  ({bool had, String? value}) _stageZone(String key, String? next) {
    final prev = (had: _zonePending.containsKey(key), value: _zonePending[key]);
    setState(() => _zonePending[key] = next);
    return prev;
  }

  void _restoreZone(String key, ({bool had, String? value}) prev) {
    setState(() {
      if (prev.had) {
        _zonePending[key] = prev.value;
      } else {
        _zonePending.remove(key);
      }
    });
  }

  /// Where a zone sits RIGHT NOW — the optimistic position while a drag of the
  /// section list is in flight, otherwise the server's. Null = no chosen
  /// position, which is every zone until somebody rearranges the floor.
  int? _positionOf(String key) {
    final pending = _orderPending;
    if (pending != null) {
      final i = pending.indexOf(key);
      return i < 0 ? null : i + 1;
    }
    return widget.zoneOrder[key];
  }

  /// The one order this screen draws sections in, mirroring the server's
  /// comparator exactly (compareTableSections in table_sections_order.ts):
  ///
  ///   1. positioned zones first, in the position the owner chose,
  ///   2. then everything unpositioned in CREATION order, oldest first,
  ///   3. then, for anything with no known birth instant and for any tie,
  ///      alphabetically on the key.
  ///
  /// Step 2 is what changed. Alphabetical was never a choice anyone made — it
  /// was the only order the schema could express before there was a column for a
  /// position — and it is the one ordering in this app that can file a room
  /// opened this morning above one the restaurant has had for years. Creation
  /// order is a choice the owner already made, by building the place in that
  /// sequence.
  ///
  /// Step 3 still matters and is not a formality: the server materialises a
  /// whole outlet's roster rows in ONE insert, so equal instants are the normal
  /// case the first time anybody rearranges, and without it the list would flap
  /// between two renders of identical data.
  int _compareZoneKeys(String a, String b) {
    final ap = _positionOf(a);
    final bp = _positionOf(b);
    if ((ap == null) != (bp == null)) return ap == null ? 1 : -1;
    if (ap != null && bp != null && ap != bp) return ap - bp;
    final ab = widget.zoneBorn[a];
    final bb = widget.zoneBorn[b];
    if ((ab == null) != (bb == null)) return ab == null ? 1 : -1;
    if (ab != null && bb != null && ab != bb) return ab.compareTo(bb);
    return a.compareTo(b);
  }

  String? _serverSection(Map t) {
    final s = _s(t, 'section', '').trim();
    return s.isEmpty ? null : s;
  }

  /// What this table's section reads as RIGHT NOW — the optimistic value while
  /// one is in flight, otherwise the server's.
  String? _sectionOf(Map t) {
    final key = _s(t, 'table_name').toLowerCase();
    return _pending.containsKey(key) ? _pending[key] : _serverSection(t);
  }

  Map<String, ({bool had, String? value})> _snapshot(List<Map> members) {
    final snap = <String, ({bool had, String? value})>{};
    for (final m in members) {
      final key = _s(m, 'table_name').toLowerCase();
      snap[key] = (had: _pending.containsKey(key), value: _sectionOf(m));
    }
    return snap;
  }

  void _restore(Map<String, ({bool had, String? value})> snap, {Set<String>? only}) {
    setState(() {
      snap.forEach((key, s) {
        if (only != null && !only.contains(key)) return;
        if (s.had) {
          _pending[key] = s.value;
        } else {
          _pending.remove(key);
        }
      });
    });
  }

  /// One PATCH per table, each carrying ONLY `section`. Tables that fail are
  /// rolled back to exactly what they showed before; the rest keep the new
  /// value. Returns the failures and the first error to report.
  Future<({List<String> failed, String error})> _apply(List<Map> tables, String? section) async {
    if (tables.isEmpty) return (failed: const <String>[], error: '');
    final snap = _snapshot(tables);
    setState(() {
      for (final t in tables) {
        _pending[_s(t, 'table_name').toLowerCase()] = section;
      }
    });
    final failed = <String>[];
    var error = '';
    for (final t in tables) {
      final name = _s(t, 'table_name');
      if (name.isEmpty) continue;
      try {
        await widget.rest.patch('/table/${Uri.encodeComponent(name)}', {'section': section});
      } catch (e) {
        failed.add(name);
        if (error.isEmpty) error = '$e';
      }
    }
    if (mounted && failed.isNotEmpty) {
      _restore(snap, only: failed.map((n) => n.toLowerCase()).toSet());
    }
    return (failed: failed, error: error);
  }

  Future<void> _move(Map table, String? section) async {
    final name = _s(table, 'table_name');
    if (name.isEmpty) return;
    final messenger = ScaffoldMessenger.of(context);
    final res = await _apply([table], section);
    if (!mounted) return;
    if (res.failed.isEmpty) {
      widget.reload();
    } else {
      messenger.showSnackBar(SnackBar(content: Text('Could not move $name — ${res.error}')));
    }
  }

  /// Two steps, roster first: POST mints the NAME — which is what makes the zone
  /// survive a reload and reach every other device even while it's empty — and
  /// only then are the picked tables moved into it. Picking tables is optional;
  /// an empty zone is a legitimate thing to create, and used to be impossible
  /// here. If the POST fails nothing is moved, so no table is left carrying a
  /// label the roster never accepted.
  Future<void> _createSection(List<Map> all, List<String> existing) async {
    final messenger = ScaffoldMessenger.of(context);
    final picked = await showDialog<({String name, List<String> tables})>(
      context: context,
      builder: (_) => _NewSectionDialog(tables: all, existing: existing, sectionOf: _sectionOf),
    );
    if (picked == null || !mounted) return;
    final key = picked.name.toLowerCase();
    final prev = _stageZone(key, picked.name);
    try {
      await widget.rest.post('/table-sections', {'name': picked.name});
    } catch (e) {
      if (!mounted) return;
      _restoreZone(key, prev);
      messenger.showSnackBar(SnackBar(content: Text('Could not create "${picked.name}" — $e')));
      return;
    }
    final chosen = all.where((t) => picked.tables.contains(_s(t, 'table_name'))).toList();
    final res = await _apply(chosen, picked.name);
    if (!mounted) return;
    widget.reload();
    if (res.failed.isNotEmpty) {
      messenger.showSnackBar(SnackBar(
        content: Text('${picked.name}: ${res.failed.join(', ')} could not be moved — ${res.error}'),
      ));
    }
  }

  /// Rearrange the sections. One `PUT /table-sections/order` carrying the WHOLE
  /// list, never "move this one to slot 3": a positional edit needs both ends to
  /// agree on what the list currently is, and two tablets dragging at once do
  /// not. Sending the finished list makes the write idempotent and makes a
  /// collision resolve to "the other device's arrangement won", which is
  /// something an owner can understand and undo, rather than a blend of two.
  ///
  /// Optimistic like every other write here: the new order shows immediately and
  /// is rolled back only if the call fails. The server answers with the order it
  /// actually holds — which differs from what was sent whenever this client was
  /// stale — so the reload, not the request, has the last word.
  Future<void> _reorderSections(List<({String key, String name, int tables})> items) async {
    final messenger = ScaffoldMessenger.of(context);
    final picked = await showDialog<List<String>>(
      context: context,
      builder: (_) => _ReorderSectionsDialog(items: items),
    );
    if (picked == null || !mounted) return;
    final prev = _orderPending;
    setState(() => _orderPending = [for (final n in picked) n.trim().toLowerCase()]);
    try {
      await widget.rest.put('/table-sections/order', {'sections': picked});
      if (!mounted) return;
      widget.reload();
    } catch (e) {
      if (!mounted) return;
      setState(() => _orderPending = prev);
      messenger.showSnackBar(SnackBar(content: Text('Could not save the section order — $e')));
    }
  }

  Future<void> _renameSection(String from, List<Map> members) async {
    final messenger = ScaffoldMessenger.of(context);
    final raw = await _askText(context, 'Rename "$from"', 'Section name', initial: from);
    final to = (raw ?? '').trim().replaceAll(RegExp(r'\s+'), ' ');
    if (to.isEmpty || to == from || !mounted) return;
    // Both halves move together: the members' labels AND the roster entry, so an
    // EMPTY zone (no members at all) still renames on screen.
    final snap = _snapshot(members);
    final key = from.toLowerCase();
    final prev = _stageZone(key, to);
    setState(() {
      for (final m in members) {
        _pending[_s(m, 'table_name').toLowerCase()] = to;
      }
    });
    try {
      await widget.rest.patch('/table-sections/${Uri.encodeComponent(from)}', {'name': to});
      if (!mounted) return;
      widget.reload();
    } catch (e) {
      if (!mounted) return;
      _restore(snap);
      _restoreZone(key, prev);
      messenger.showSnackBar(SnackBar(content: Text('Could not rename "$from" — $e')));
    }
  }

  /// Dissolves the zone: the name leaves the roster and its tables stop carrying
  /// it. No table is ever deleted — they simply fall through to "Unassigned".
  Future<void> _deleteSection(String name, List<Map> members) async {
    final messenger = ScaffoldMessenger.of(context);
    final ok = await _confirm(
      context,
      'Remove section "$name"?',
      members.isEmpty
          ? 'Nothing is in it — removing it just takes the name off the floor plan.'
          : 'The ${members.length} table${members.length == 1 ? '' : 's'} in it stay on the floor — they just stop carrying a section.',
    );
    if (!ok || !mounted) return;
    final snap = _snapshot(members);
    final key = name.toLowerCase();
    final prev = _stageZone(key, null);
    setState(() {
      for (final m in members) {
        _pending[_s(m, 'table_name').toLowerCase()] = null;
      }
    });
    try {
      await widget.rest.delete('/table-sections/${Uri.encodeComponent(name)}');
      if (!mounted) return;
      widget.reload();
    } catch (e) {
      if (!mounted) return;
      _restore(snap);
      _restoreZone(key, prev);
      messenger.showSnackBar(SnackBar(content: Text('Could not remove "$name" — $e')));
    }
  }

  Widget _tableTile(Map m, {required bool canMove, required bool touch, required double width}) {
    final focused = widget.focusTable != null && _s(m, 'table_name') == widget.focusTable;
    Widget box({required bool focus}) => _TableBox(
          table: m,
          rest: widget.rest,
          profile: widget.profile,
          reload: widget.reload,
          surface: widget.surface,
          focused: focus,
          width: width,
        );
    if (!canMove) return box(focus: focused);
    // The dragged copy rides in the app overlay, outside any Scaffold, so it
    // needs its own Material for the card's ink to have a surface.
    final feedback = Material(
      color: Colors.transparent,
      child: Opacity(opacity: 0.9, child: box(focus: false)),
    );
    final placeholder = Opacity(opacity: 0.3, child: box(focus: false));
    // Both variants get the same edge-scroll wiring: the destination being
    // below the fold is a property of the floor plan, not of the pointer.
    void update(DragUpdateDetails d) => _autoScroll(d.globalPosition);
    void stop() => _stopAutoScroll();
    return touch
        ? LongPressDraggable<Map>(
            data: m,
            feedback: feedback,
            childWhenDragging: placeholder,
            onDragUpdate: update,
            onDragEnd: (_) => stop(),
            onDraggableCanceled: (_, _) => stop(),
            child: box(focus: focused))
        : Draggable<Map>(
            data: m,
            feedback: feedback,
            childWhenDragging: placeholder,
            onDragUpdate: update,
            onDragEnd: (_) => stop(),
            onDraggableCanceled: (_, _) => stop(),
            child: box(focus: focused));
  }

  /// One zone. [key] is the lower-cased identity used for grouping and drop
  /// tests; [name] is the label as it should READ and as it must be WRITTEN back
  /// (a table dropped into the roster's "Patio" gets "Patio", not "patio").
  Widget _group(
    BuildContext context,
    String key,
    String name,
    List<Map> members, {
    required bool canMove,
    required bool canManage,
    required bool touch,
  }) {
    final text = Theme.of(context).textTheme;
    final label = key.isEmpty ? 'Unassigned' : name;
    final seats = members.fold<int>(0, (a, m) => a + (_int(m['capacity']) ?? 0));
    return Padding(
      padding: const EdgeInsets.only(bottom: AppSpacing.md),
      // The WHOLE group is the drop target, not just its header strip — a small
      // strip is a miss waiting to happen with a 168px card under the cursor.
      child: DragTarget<Map>(
        onWillAcceptWithDetails: (d) => canMove && (_sectionOf(d.data) ?? '').toLowerCase() != key,
        onAcceptWithDetails: (d) => _move(d.data, key.isEmpty ? null : name),
        builder: (context, candidate, rejected) {
          final hot = candidate.isNotEmpty;
          return AnimatedContainer(
            duration: AppDurations.fast,
            curve: Curves.easeOut,
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 14),
            decoration: BoxDecoration(
              color: hot ? AppColors.tint(AppColors.copper) : AppColors.inset,
              borderRadius: AppRadius.cardAll,
              border: Border.all(
                color: hot ? AppColors.copper : AppColors.border,
                width: hot ? 2 : 1,
              ),
            ),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Icon(key.isEmpty ? Icons.help_outline : Icons.dashboard_outlined,
                    size: 15, color: hot ? AppColors.copperHi : AppColors.textSecondary),
                const SizedBox(width: 8),
                Expanded(
                  child: Wrap(
                    spacing: 8,
                    runSpacing: 6,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      Text(label.toUpperCase(),
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                            letterSpacing: 0.8,
                            color: hot ? AppColors.copperHi : AppColors.textSecondary,
                          )),
                      // An empty zone is a real, saved zone — say so rather than
                      // letting it read as a rendering accident.
                      if (members.isEmpty && key.isNotEmpty)
                        StatusChip(label: 'Empty', color: AppColors.neutral, dense: true)
                      else ...[
                        InfoChip(
                          icon: Icons.table_restaurant,
                          label: '${members.length} ${members.length == 1 ? 'table' : 'tables'}',
                        ),
                        InfoChip(icon: Icons.event_seat_outlined, label: '$seats seats'),
                      ],
                      if (hot)
                        Text('DROP TO MOVE HERE',
                            style: text.labelSmall!.copyWith(color: AppColors.copperHi)),
                    ],
                  ),
                ),
                if (!hot && canManage && key.isNotEmpty) ...[
                  const SizedBox(width: AppSpacing.sm),
                  ForkIconButton(
                    icon: Icons.drive_file_rename_outline,
                    tooltip: 'Rename section',
                    onPressed: () => _renameSection(name, members),
                  ),
                  ForkIconButton(
                    icon: Icons.layers_clear_outlined,
                    tooltip: 'Remove section (tables stay)',
                    onPressed: () => _deleteSection(name, members),
                  ),
                ],
              ]),
              const SizedBox(height: AppSpacing.md),
              if (members.isEmpty)
                // No gesture instruction. See the header on _autoScroll: telling
                // someone to long-press and drag was the wrong sentence to put
                // in front of them, because on a floor plan taller than the
                // window the drag could not reach anywhere useful. The gesture
                // still works — and now reaches the whole list — but it is not
                // what this screen promises.
                Text('Nothing here yet.', style: text.bodySmall)
              else
                // Measured, not guessed: the tile sizes itself to the zone it is
                // actually laid out in, which is what keeps a portrait phone at
                // two across without touching the desktop breakpoints.
                LayoutBuilder(
                  builder: (context, box) {
                    final tile = _tableTileWidth(box.maxWidth);
                    return Wrap(spacing: 12, runSpacing: 12, children: [
                      for (final m in members)
                        _tableTile(m, canMove: canMove, touch: touch, width: tile),
                    ]);
                  },
                ),
            ]),
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final all = widget.rows.map((r) => r as Map).toList();
    // Grouped on the lower-cased name so a table labelled "Patio" lands in the
    // roster's "patio" instead of splitting the floor into two look-alike zones.
    final groups = <String, List<Map>>{};
    final labels = <String, String>{};
    for (final m in all) {
      final s = _sectionOf(m);
      final key = (s ?? '').toLowerCase();
      groups.putIfAbsent(key, () => <Map>[]).add(m);
      if (s != null) labels.putIfAbsent(key, () => s);
    }
    // Every zone on the roster gets a group even when nothing is in it. This is
    // the whole point of reading the roster: an empty zone has no table to be
    // inferred from, so before this it simply did not exist on this screen.
    _zonesNow().forEach((key, name) {
      groups.putIfAbsent(key, () => <Map>[]);
      labels.putIfAbsent(key, () => name);
    });
    // The owner's arrangement, falling through to alphabetical for anything
    // they have not placed. "Unassigned" is never IN this list — it always
    // renders last, so no table can hide behind a section it hasn't been given.
    final named = groups.keys.where((k) => k.isNotEmpty).toList()..sort(_compareZoneKeys);
    final ordered = <String>[...named, if (groups.containsKey('')) ''];
    // BOTH GATES, ANDed. The permission is what the server enforces on the
    // writes; the surface is D5. Neither can stand in for the other — moving
    // these controls to the layout screen must not hand them to somebody the
    // permission refused, and holding the permission must not put them back on
    // the service screen.
    final arrange = FloorScope.of(widget.profile, surface: widget.surface).arrangeFloor;
    final canMove = arrange && _canMoveTables(widget.profile);
    final canManage = arrange && _canManageSections(widget.profile);
    final touch = switch (Theme.of(context).platform) {
      TargetPlatform.android || TargetPlatform.iOS => true,
      _ => false,
    };

    // SectionHeader puts `trailing` in an unflexed slot, so two buttons there
    // overflow a phone by ~43px. Same answer the legend above already uses:
    // below 620 they move to their own line rather than being squeezed.
    final actionsBelow = MediaQuery.sizeOf(context).width < 620;
    final actions = <Widget>[
      if (canManage) ...[
        // Nothing to arrange with fewer than two zones, and a control that opens
        // onto a one-line list is just a dead end.
        if (named.length > 1)
          ForkButton.ghost(
            label: 'Arrange',
            icon: Icons.swap_vert,
            dense: true,
            onPressed: () => _reorderSections([
              for (final k in named)
                (key: k, name: labels[k] ?? k, tables: (groups[k] ?? const <Map>[]).length),
            ]),
          ),
        ForkButton.ghost(
          label: 'New section',
          icon: Icons.add,
          dense: true,
          onPressed: () => _createSection(all, [for (final k in named) labels[k] ?? k]),
        ),
      ],
    ];

    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      const SizedBox(height: AppSpacing.lg),
      SectionHeader(
        title: 'Sections',
        count: named.length,
        padding: const EdgeInsets.only(bottom: 6),
        trailing: actions.isEmpty || actionsBelow
            ? null
            : Wrap(spacing: 6, runSpacing: 6, crossAxisAlignment: WrapCrossAlignment.center, children: actions),
      ),
      if (actionsBelow && actions.isNotEmpty)
        Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Wrap(spacing: 6, runSpacing: 6, children: actions),
        ),
      // THE MESSAGE THAT WAS REMOVED. It read "Long-press a table and drag it
      // onto another section to move it", and it was the one instruction on this
      // screen that could not be followed: any restaurant with more than about
      // three sections has the destination below the fold, and nothing scrolled
      // while a card was held. What is left says what the screen IS rather than
      // what to do to it — every action here is reachable by tapping a table.
      Text('Tables are grouped by their floor section.', style: text.bodySmall),
      // The roster is half the picture — if it didn't load, say so instead of
      // quietly showing only the zones that happen to have a table in them.
      if (widget.zoneError.isNotEmpty) ...[
        const SizedBox(height: AppSpacing.md),
        Container(
          width: double.infinity,
          padding: const EdgeInsets.fromLTRB(14, 10, 10, 10),
          decoration: BoxDecoration(
            color: AppColors.tint(AppColors.warning),
            borderRadius: AppRadius.controlAll,
            border: Border.all(color: AppColors.edge(AppColors.warning)),
          ),
          child: Row(children: [
            Icon(Icons.warning_amber_outlined, size: 16, color: AppColors.warning),
            const SizedBox(width: AppSpacing.sm),
            Expanded(
              child: Text(
                'Section list unavailable — sections with no tables in them are missing from this floor plan. ${widget.zoneError}',
                style: text.bodySmall!.copyWith(fontSize: 12, color: AppColors.warning),
              ),
            ),
            const SizedBox(width: AppSpacing.sm),
            ForkButton.ghost(label: 'Retry', icon: Icons.refresh, dense: true, onPressed: widget.reload),
          ]),
        ),
      ],
      const SizedBox(height: AppSpacing.md),
      for (final key in ordered)
        _group(context, key, labels[key] ?? key, groups[key] ?? const <Map>[],
            canMove: canMove, canManage: canManage, touch: touch),
    ]);
  }
}

/// Names a new section and optionally picks the tables to start it with. The
/// roster (`POST /table-sections`) records the NAME, so an empty zone is a real
/// saved thing now — tables can be dragged in whenever the floor is ready.
class _NewSectionDialog extends StatefulWidget {
  final List<Map> tables;
  final List<String> existing;
  final String? Function(Map table) sectionOf;
  const _NewSectionDialog({required this.tables, required this.existing, required this.sectionOf});

  @override
  State<_NewSectionDialog> createState() => _NewSectionDialogState();
}

class _NewSectionDialogState extends State<_NewSectionDialog> {
  final _name = TextEditingController();
  final Set<String> _picked = {};
  String? _error;

  @override
  void dispose() {
    _name.dispose();
    super.dispose();
  }

  void _submit() {
    final name = _name.text.trim().replaceAll(RegExp(r'\s+'), ' ');
    if (name.isEmpty) {
      setState(() => _error = 'Give the section a name.');
      return;
    }
    // Cheap client-side echo of the server's own 409 — the POST is still the
    // authority, this just saves a round-trip on the obvious case.
    if (widget.existing.any((e) => e.toLowerCase() == name.toLowerCase())) {
      setState(() => _error = '"$name" already exists — drag tables into it instead.');
      return;
    }
    Navigator.pop(context, (name: name, tables: _picked.toList()));
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return Dialog(
      backgroundColor: Colors.transparent,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: 400, maxHeight: MediaQuery.sizeOf(context).height * 0.85),
        child: Container(
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            gradient: AppColors.cardGradient,
            borderRadius: AppRadius.cardAll,
            border: Border.all(color: AppColors.borderStrong),
          ),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('FLOOR', style: text.labelSmall),
            const SizedBox(height: 6),
            Text('New section', style: text.titleMedium),
            const SizedBox(height: AppSpacing.lg),
            TextField(
              controller: _name,
              autofocus: true,
              textCapitalization: TextCapitalization.words,
              decoration: const InputDecoration(labelText: 'Section name (e.g. Terrace)', isDense: true),
              onChanged: (_) {
                if (_error != null) setState(() => _error = null);
              },
              onSubmitted: (_) => _submit(),
            ),
            const SizedBox(height: AppSpacing.md),
            Text(
                widget.tables.isEmpty
                    ? 'The section is saved on its own — add tables to the floor and drag them in whenever you like.'
                    : 'Optionally start it with a few tables. Leave them all unticked to create an empty section and drag tables in later.',
                style: text.bodySmall),
            const SizedBox(height: AppSpacing.sm),
            Flexible(
              child: SingleChildScrollView(
                child: Column(children: [
                  for (final t in widget.tables)
                    Builder(builder: (_) {
                      final name = _s(t, 'table_name');
                      final current = widget.sectionOf(t);
                      final seats = _seatsLabel(t);
                      return CheckboxListTile(
                        value: _picked.contains(name),
                        dense: true,
                        contentPadding: EdgeInsets.zero,
                        controlAffinity: ListTileControlAffinity.leading,
                        activeColor: AppColors.copper,
                        onChanged: (v) => setState(() {
                          if (v == true) {
                            _picked.add(name);
                          } else {
                            _picked.remove(name);
                          }
                          _error = null;
                        }),
                        title: Text(name, style: text.titleSmall),
                        subtitle: Text(
                          '${seats.isEmpty ? 'No seat count' : seats} · ${current == null ? 'unassigned' : 'in $current'}',
                          style: text.bodySmall,
                        ),
                      );
                    }),
                ]),
              ),
            ),
            if (_error != null) ...[
              const SizedBox(height: AppSpacing.sm),
              Text(_error!, style: text.bodySmall!.copyWith(color: AppColors.danger)),
            ],
            const SizedBox(height: AppSpacing.lg),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(context)),
              const SizedBox(width: AppSpacing.sm),
              ForkButton(label: 'Create section', icon: Icons.check, onPressed: _submit),
            ]),
          ]),
        ),
      ),
    );
  }
}

/// Rearrange the floor's sections. Returns the section NAMES in their new order,
/// or null when dismissed.
///
/// WHY A SHEET AND NOT DRAGGING THE HEADERS IN PLACE. The floor plan is already
/// a drag surface: every table tile is a Draggable, and on a phone that drag
/// begins with a long press. Laying a second reorder gesture over the same cards
/// would put both in one gesture arena — "press and pull" would sometimes carry
/// a table and sometimes a whole zone, and no affordance can explain which. A
/// list with no tables in it has only one thing a drag can mean.
///
/// THREE WAYS TO MOVE A ROW, because on this app one is never enough:
///   * the HANDLE is a drag listener, which is pointer-kind agnostic — the same
///     grab works under a mouse on the Windows desktop build and under a finger
///     on the phone build. A handle wired to hover or to a mouse cursor would
///     leave the phone unable to reorder at all.
///   * MOVE UP / MOVE DOWN buttons, so the list is workable by keyboard, by
///     screen reader, and by anyone for whom a precise drag is hard.
///   * and the row itself is deliberately NOT a drag target, so a drag anywhere
///     else still SCROLLS. A reorder list a phone cannot scroll is worse than
///     no reorder list.
///
/// It renders in both design systems for free: every piece of it is a Fork*
/// primitive or an AppColors token, and Gaia repaints those through the shell
/// and accent bridges without this widget knowing it exists.
class _ReorderSectionsDialog extends StatefulWidget {
  final List<({String key, String name, int tables})> items;
  const _ReorderSectionsDialog({required this.items});

  @override
  State<_ReorderSectionsDialog> createState() => _ReorderSectionsDialogState();
}

class _ReorderSectionsDialogState extends State<_ReorderSectionsDialog> {
  late final List<({String key, String name, int tables})> _items = [...widget.items];

  bool get _changed {
    if (_items.length != widget.items.length) return true;
    for (var i = 0; i < _items.length; i++) {
      if (_items[i].key != widget.items[i].key) return true;
    }
    return false;
  }

  void _shift(int from, int to) {
    if (to < 0 || to >= _items.length || from == to) return;
    setState(() => _items.insert(to, _items.removeAt(from)));
  }

  void _onReorder(int oldIndex, int newIndex) {
    setState(() {
      // ReorderableListView reports the destination as a GAP index, so a
      // downward move is one past where the row actually lands.
      if (newIndex > oldIndex) newIndex -= 1;
      _items.insert(newIndex, _items.removeAt(oldIndex));
    });
  }

  Widget _row(BuildContext context, int i) {
    final text = Theme.of(context).textTheme;
    final it = _items[i];
    return Container(
      key: ValueKey(it.key),
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.fromLTRB(4, 4, 4, 4),
      decoration: BoxDecoration(
        color: AppColors.inset,
        borderRadius: AppRadius.controlAll,
        border: Border.all(color: AppColors.border),
      ),
      child: Row(children: [
        ReorderableDragStartListener(
          index: i,
          child: MouseRegion(
            cursor: SystemMouseCursors.grab,
            child: Padding(
              // Padded out to a comfortable finger target; the icon alone is 18px.
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 10),
              child: Icon(Icons.drag_indicator, size: 18, color: AppColors.textSecondary),
            ),
          ),
        ),
        // The position, spelled out — the order is the whole subject of this
        // screen, so it should never have to be counted off the rows.
        SizedBox(
          width: 22,
          child: Text('${i + 1}', style: text.labelSmall, textAlign: TextAlign.center),
        ),
        const SizedBox(width: 6),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text(it.name, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            Text(
              it.tables == 0 ? 'Empty' : '${it.tables} ${it.tables == 1 ? 'table' : 'tables'}',
              style: text.bodySmall,
            ),
          ]),
        ),
        ForkIconButton(
          icon: Icons.keyboard_arrow_up,
          tooltip: 'Move up',
          onPressed: i == 0 ? null : () => _shift(i, i - 1),
        ),
        ForkIconButton(
          icon: Icons.keyboard_arrow_down,
          tooltip: 'Move down',
          onPressed: i == _items.length - 1 ? null : () => _shift(i, i + 1),
        ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return Dialog(
      backgroundColor: Colors.transparent,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: 440, maxHeight: MediaQuery.sizeOf(context).height * 0.85),
        child: Container(
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            gradient: AppColors.cardGradient,
            borderRadius: AppRadius.cardAll,
            border: Border.all(color: AppColors.borderStrong),
          ),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('FLOOR', style: text.labelSmall),
            const SizedBox(height: 6),
            Text('Arrange sections', style: text.titleMedium),
            const SizedBox(height: AppSpacing.md),
            Text(
              'Drag a handle, or use the arrows. This is the order the floor plan '
              'shows for this outlet on every device. Tables with no section always '
              'come last.',
              style: text.bodySmall,
            ),
            const SizedBox(height: AppSpacing.md),
            Flexible(
              child: ReorderableListView.builder(
                shrinkWrap: true,
                buildDefaultDragHandles: false,
                itemCount: _items.length,
                onReorder: _onReorder,
                // The dragged copy rides in an overlay outside this Dialog's
                // Material, and the default proxy would stamp an elevation
                // shadow on it — right for Rustic, wrong for Gaia's flat
                // surfaces. Carrying the row's own decoration instead is
                // correct in both, and matches how a dragged TABLE already looks.
                proxyDecorator: (child, index, animation) =>
                    Material(color: Colors.transparent, child: Opacity(opacity: 0.9, child: child)),
                itemBuilder: (context, i) => _row(context, i),
              ),
            ),
            const SizedBox(height: AppSpacing.lg),
            // A Wrap, not a Row: at 390px the dialog is 310 wide and these two
            // buttons want 307 inside its padding, which a Row reports as a
            // 43px overflow — a striped bar across the bottom of the sheet on
            // exactly the device this feature most needs to work on.
            Wrap(
              alignment: WrapAlignment.end,
              spacing: AppSpacing.sm,
              runSpacing: AppSpacing.sm,
              children: [
                ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(context)),
                ForkButton(
                  label: 'Save order',
                  icon: Icons.check,
                  // Nothing moved = nothing to save. Sending the list anyway
                  // would stamp explicit positions on an outlet that had none,
                  // which is a real change (new sections would start landing at
                  // the end) dressed up as a no-op.
                  onPressed: _changed ? () => Navigator.pop(context, [for (final it in _items) it.name]) : null,
                ),
              ],
            ),
          ]),
        ),
      ),
    );
  }
}

// ---- WHAT "OCCUPIED" MEANS ON SCREEN, AND WHAT IT STILL MEANS IN THE DATABASE --
//
// THE ASK: a table should only read Occupied once an order has been placed on
// it. THE HAZARD: "Tables".is_occupied is not a colour. It is the flag the
// table_session_track trigger watches, and a seating row is what a COVER is
// counted from, and covers are the denominator of APC — so they are the
// denominator of the APC traffic-light, the analytics, the MIS reports and the
// simulator baseline. Delay the flag and you delay the seating, which changes
// what a cover is, retrospectively and silently.
//
// So the flag is untouched and the SCREEN gains the state it was missing:
//
//   Free      nobody is sitting there.
//   Seated    a party is seated — counted, timed, waiter assigned, OTP minted —
//             and has not ordered yet. This is the state that used to be
//             painted as Occupied and was the actual complaint.
//   Occupied  seated AND food is on the bill.
//
// Everything money-adjacent on this card still keys on SEATED, never on the
// display state: the covers chip, the OTP, the bill line, and every action in
// the sheet. The only things the new state changes are the chip, the tint and
// the legend.

/// Is a party physically at this table? The seating fact — `is_occupied` —
/// under whichever name this backend sends it.
bool _tableSeated(Map t) => t['seated'] == true || t['occupied'] == true;

/// Has anything been ordered at this table yet?
///
/// A backend that does not send `has_order` at all (anything before 1.8.7)
/// answers TRUE, so a seated table keeps reading Occupied exactly as it did
/// rather than every table in the restaurant suddenly claiming nobody has
/// ordered. Missing data must degrade to the old behaviour, never to a new
/// claim about the floor.
bool _tableHasOrder(Map t) => t.containsKey('has_order') ? t['has_order'] == true : true;

/// How strongly a table tile is washed with its state colour.
///
/// One place to tune the floor's readability, because these three numbers are
/// the whole difference between "I can see which tables are busy" and "I have to
/// read every card". They are alphas composited over `AppColors.card`
/// (0xFF1B1716), so they behave the same way under every shell scheme rather
/// than being hand-picked hexes that only work against one background.
///
/// Ordered by how much the state wants attention, and deliberately NOT equal:
/// Occupied is the state the floor is scanned for, so it is the loudest.
const double _kOccupiedWash = 0.20;
const double _kSeatedWash = 0.16;
const double _kReservedWash = 0.13;

/// The three-state floor status. `reserved` covers both an active booking
/// window and an upcoming one, and never outranks a party who is actually
/// sitting there.
({String label, Color color}) _tableState(Map t) {
  final seated = _tableSeated(t);
  if (seated && _tableHasOrder(t)) return (label: 'Occupied', color: AppColors.copper);
  // Amber, not copper: a party sitting with nothing ordered is the one state on
  // this floor plan that is asking somebody to go over. It is deliberately NOT
  // the reserved blue either — a reserved table is a promise, this is a guest.
  if (seated) return (label: 'Seated', color: AppColors.warning);
  if (t['reserved'] == true || t['booked'] == true) return (label: 'Reserved', color: AppColors.info);
  return (label: 'Free', color: AppColors.neutral);
}

/// A one-line description of an order, for a picker that has to let somebody
/// tell two tickets on the same table apart: how many lines and what it is
/// worth. Falls back to the id only when the payload carries neither, so a row
/// is never blank.
String _kotSummary(Map order) {
  // `/orders` carries `items` and `total` on the row itself; the nested `food`
  // map is an older shape, still honoured so nothing that sends it goes blank.
  final food = order['food'] is Map ? order['food'] as Map : order;
  final items = (food['items'] as List?) ?? const [];
  final total = food['total'] ?? food['subtotal'];
  final n = items.length;
  final money = total == null ? '' : ' \u00b7 ${_money(total)}';
  if (n == 0 && money.isEmpty) return 'Order ${_s(order, 'id')}';
  return '$n item${n == 1 ? '' : 's'}$money';
}

/// Card width for one floor-plan tile inside a zone [available] px wide.
///
/// 168 is the design width and every desktop column keeps it. A portrait phone
/// cannot: 390px leaves ~334 inside the page and zone padding, which is 2px
/// short of two 168s, so the floor plan collapsed to ONE card per row — an
/// owner scrolling past three tables to reach T4 mid-service. Below that
/// threshold the tile takes half the row instead, so portrait is always at
/// least 2-up, with a floor that keeps the name + status chip readable.
double _tableTileWidth(double available) {
  const preferred = 168.0;
  const gap = 12.0; // the Wrap's spacing between tiles
  if (!available.isFinite || available >= preferred * 2 + gap) return preferred;
  // One pixel of slack, floored to whole pixels: a fractional layout width must
  // not be what pushes the second card onto its own row.
  final half = ((available - gap - 1) / 2).floorToDouble();
  return half < 120 ? 120 : half;
}

class _TableBox extends StatelessWidget {
  final Map table;
  final RestClient rest;
  final Profile profile;
  final VoidCallback reload;

  /// Which floor screen this tile was drawn on — carried through to the sheet it
  /// opens so the sheet's layout controls answer D5 as well. See [FloorSurface].
  final FloorSurface surface;
  // True when a caller (e.g. a notification's "Open T4") asked for this table —
  // draws the copper focus ring so the eye finds it in a full floor plan.
  final bool focused;

  /// Set by the zone's [LayoutBuilder] so narrow screens still get two across.
  final double width;
  const _TableBox({
    required this.table,
    required this.rest,
    required this.profile,
    required this.reload,
    required this.surface,
    this.focused = false,
    this.width = 168,
  });

  @override
  Widget build(BuildContext context) {
    if (surface == FloorSurface.plan) return _planTile(context);
    final text = Theme.of(context).textTheme;
    // The HANDLE — what every request, the outbox tag and the paper use.
    final name = _s(table, 'table_name');
    // CLIENT ITEM 6. "Same number for order taking for the next round of
    // guests": a next-party seat's tile reads the ROOT's number, big, with a
    // "Next party" chip beside the state. Its bill and KOT still say "12 #2",
    // so two open bills for 12 stay apart at the till.
    final nextParty = isNextPartyRow(table);
    final shownName = tableDisplayName(table);
    // `occupied` here is the SEATING — a party is physically at this table —
    // and it is what every money-adjacent line below keys on. What the card
    // SAYS is a separate decision with three answers; see _tableState.
    final occupied = _tableSeated(table);
    final reserved = table['reserved'] == true || table['booked'] == true;
    final state = _tableState(table);
    final status = state.label;
    final stateColor = state.color;
    // A seated party who has not ordered is tinted like the state they are in,
    // so the floor reads at a glance without anyone parsing a chip.
    final awaitingOrder = occupied && !_tableHasOrder(table);
    final apcStatus = _s(table, 'apc_status', 'neutral');
    final covers = table['covers'];
    // Per-table ordering OTP: only meaningful (and only sent) while require_table_otp
    // is ON and the table is occupied. Read aloud to the guest so they can order.
    final otp = _tableOtp(table);
    final paymentPending = table['payment_pending'] == true;
    final waiter = _s(table, 'waiter_name', '');
    final hasWaiter = waiter.isNotEmpty && waiter != '—';
    // ITEM 19 ON THE FLOOR PLAN. `hasTotal` guards the two money-carrying
    // affordances on this tile — the "₹1,200 · bill · apc ₹300" line and the APC
    // traffic-light — so scoping it here takes BOTH off a waiter's grid in one
    // place, rather than leaving one of them to be found later.
    final showsMoney = RoleScope.showsMoney(profile);
    final hasTotal = showsMoney && occupied && (table['table_total'] ?? 0) != 0;
    // Seat guide + the most it can take with extra chairs.
    final seats = _seatsLabel(table);
    // Part of a clubbed booking — the partner tables it is joined to.
    final clubbedWith = _strList(table['clubbed_with']);
    // APC traffic-light (green = meeting target, yellow = close, red = well
    // below), kept as a labelled tick so status is never colour alone.
    final apcTick = hasTotal && apcStatus != 'neutral'
        ? TickTag(
            apcStatus == 'green'
                ? 'APC ok'
                : apcStatus == 'yellow'
                    ? 'APC close'
                    : 'APC low',
            color: apcStatus == 'green'
                ? AppColors.success
                : apcStatus == 'yellow'
                    ? AppColors.warning
                    : AppColors.danger,
          )
        : null;
    return InkWell(
      onTap: () => showModalBottomSheet<void>(
        context: context,
        showDragHandle: true,
        isScrollControlled: true,
        backgroundColor: AppColors.surface,
        builder: (_) => _TableSheet(
            rest: rest, profile: profile, table: table, reload: reload, surface: surface),
      ),
      borderRadius: AppRadius.cardAll,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeOut,
        width: width,
        // Min height (not fixed) so an extra row (waiter + payment-pending) grows
        // the card instead of overflowing the bottom.
        constraints: const BoxConstraints(minHeight: 128),
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          gradient: occupied || reserved ? null : AppColors.cardGradient,
          // OCCUPIED AND FREE MUST BE TELLABLE APART ACROSS THE ROOM.
          //
          // These washes used to be 0.07 / 0.07 / 0.06 over AppColors.card,
          // which is 0xFF1B1716 — very nearly black. Seven per cent of copper
          // over that is a difference you can find if you already know which
          // card you are looking at, and cannot find if you do not. On a phone,
          // at arm's length, in a dim dining room, an occupied table and a free
          // one read as the same dark rectangle and the only real signal was the
          // small status pill. Somebody walking the floor should not have to
          // READ the card to know whether there is a party at it.
          //
          // The fills below are strong enough to carry the state on their own,
          // and the status pill now confirms what the colour already said rather
          // than being the only thing that says it. Each state keeps its own hue
          // — copper earns, amber wants attention, blue is a promise — so this is
          // more contrast, not a new vocabulary.
          color: awaitingOrder
              ? Color.alphaBlend(AppColors.warning.withValues(alpha: _kSeatedWash), AppColors.card)
              : occupied
                  ? Color.alphaBlend(AppColors.copper.withValues(alpha: _kOccupiedWash), AppColors.card)
                  : reserved
                      ? Color.alphaBlend(AppColors.info.withValues(alpha: _kReservedWash), AppColors.card)
                      : null,
          borderRadius: AppRadius.cardAll,
          border: Border.all(
            color: focused
                ? AppColors.copperHi
                : awaitingOrder
                    ? AppColors.warning.withValues(alpha: 0.60)
                    : occupied
                        ? AppColors.copper.withValues(alpha: 0.85)
                        : reserved
                            ? AppColors.info.withValues(alpha: 0.50)
                            : AppColors.border,
            // A busy table is outlined, not hairlined. At 1px against a 7%-white
            // border the occupied edge was the same weight as every free card's;
            // 2px is what makes the distinction survive being glanced at.
            width: focused ? 2 : (occupied || awaitingOrder ? 2 : 1),
          ),
          // The copper glow is the "this table is earning" signal, so it belongs
          // to Occupied alone. A seated table with no order gets the tint and
          // the border but not the glow.
          boxShadow: focused
              ? [BoxShadow(color: AppColors.copperHi.withValues(alpha: 0.22), blurRadius: 26, spreadRadius: 1)]
              : occupied && !awaitingOrder
                  ? [BoxShadow(color: AppColors.copper.withValues(alpha: 0.10), blurRadius: 24)]
                  : null,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(children: [
              Expanded(
                child: Text(shownName,
                    key: ValueKey('table-title-$name'),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: text.titleMedium),
              ),
              if (paymentPending) StatusChip(label: 'PAID', color: AppColors.warning, dense: true),
              // Per-table honesty. An order taken during an outage is saved on
              // this device and the kitchen has NOT seen it — so the table it
              // belongs to says so on the floor plan, not just a global counter
              // in the AppBar. Renders a zero-size box (and zero gap) when this
              // table has nothing waiting, which is every moment online.
              OutboxTagBadge(tag: 'table:$name', gap: paymentPending ? 6 : 0),
            ]),
            const SizedBox(height: 8),
            // State and APC tick share one line while they fit and the tick sits
            // hard right, exactly as a Row + Spacer did. A Wrap is what makes the
            // pair degrade: at a raised text scale the tick drops to its own run
            // instead of pushing the row off a 168px card. The chips themselves
            // ellipsise (see ChipLabel), so neither path can overflow.
            Wrap(
              alignment: WrapAlignment.spaceBetween,
              spacing: 6,
              runSpacing: 6,
              children: [
                AnimatedSwitcher(
                  duration: AppDurations.base,
                  switchInCurve: Curves.easeOut,
                  switchOutCurve: Curves.easeIn,
                  child: StatusChip(
                      key: ValueKey('table-$name-$status'),
                      label: status,
                      color: stateColor,
                      dense: true),
                ),
                if (nextParty)
                  StatusChip(
                      key: ValueKey('next-party-chip-$name'),
                      label: nextPartyChip,
                      color: AppColors.info,
                      dense: true),
                ?apcTick,
              ],
            ),
            if (occupied && otp.isNotEmpty) ...[
              const SizedBox(height: 8),
              // Copper-accented, kept prominent — staff read this aloud to guests.
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
                decoration: BoxDecoration(
                  color: AppColors.tint(AppColors.copper),
                  borderRadius: BorderRadius.circular(7),
                  border: Border.all(color: AppColors.edge(AppColors.copper)),
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  Icon(Icons.lock_outline, size: 13, color: AppColors.copperHi),
                  const SizedBox(width: 6),
                  Text('OTP $otp',
                      style: TextStyle(
                          fontSize: 13.5, fontWeight: FontWeight.w700, letterSpacing: 1.5, color: AppColors.copperHi)),
                ]),
              ),
            ],
            if (clubbedWith.isNotEmpty) ...[
              const SizedBox(height: 8),
              // Clubbed for a large party — name the tables it is joined to so
              // nobody pulls one half away. Ellipsised (the box is 168px at its
              // widest, less on a phone) with the full set on the tooltip.
              Tooltip(
                message: 'Clubbed with ${clubbedWith.join(' + ')}',
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
                  decoration: BoxDecoration(
                    color: AppColors.tint(AppColors.copper),
                    borderRadius: BorderRadius.circular(7),
                    border: Border.all(color: AppColors.edge(AppColors.copper)),
                  ),
                  child: Row(mainAxisSize: MainAxisSize.min, children: [
                    Icon(Icons.link, size: 13, color: AppColors.copperHi),
                    const SizedBox(width: 6),
                    Flexible(
                      child: Text('+ ${clubbedWith.join(' + ')}',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              fontSize: 11.5, fontWeight: FontWeight.w700, color: AppColors.copperHi)),
                    ),
                  ]),
                ),
              ),
            ],
            if (seats.isNotEmpty || hasWaiter || (occupied && covers != null)) ...[
              const SizedBox(height: 8),
              Wrap(spacing: 6, runSpacing: 6, children: [
                if (seats.isNotEmpty) InfoChip(icon: Icons.event_seat_outlined, label: seats),
                if (occupied && covers != null) InfoChip(icon: Icons.people_outline, label: '$covers covers'),
                if (hasWaiter)
                  InfoChip(
                    icon: Icons.badge_outlined,
                    label: waiter.length > 14 ? '${waiter.substring(0, 13)}…' : waiter,
                  ),
              ]),
            ],
            const SizedBox(height: 10),
            if (paymentPending)
              // Approving a guest's payment CLOSES the table, so it is a settle
              // by another name and a waiter no longer has it (item 18). The
              // tile still says the table is waiting — hiding the state as well
              // as the control would leave a paid table looking ordinary — it
              // just stops promising an action this reader cannot take.
              Text(FloorScope.of(profile).settle ? 'Tap to approve payment' : 'Paid — a manager must approve',
                  style: text.bodySmall!.copyWith(fontSize: 11, fontWeight: FontWeight.w600, color: AppColors.warning))
            else if (hasTotal)
              MicroStat(value: _money(table['table_total']), label: 'bill · apc ${_money(table['table_apc'])}')
            else if (awaitingOrder)
              // The actionable half of the new state: somebody is sitting there
              // waiting, and this is the line that says so.
              Text('Seated — no order yet',
                  style: text.bodySmall!.copyWith(fontSize: 11, fontWeight: FontWeight.w600, color: AppColors.warning))
            else
              Text('Tap to manage', style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
          ],
        ),
      ),
    );
  }

  /// THE SAME TABLE, AS A PIECE OF FURNITURE — requirement 2.1.
  ///
  /// "In the Floor Plan, users can rearrange, group tables, and modify the
  /// layout … make sure what is seen in Tables is not shown in the floor plan."
  ///
  /// D5 split the CONTROLS across the two screens but left them drawing one
  /// tile, so the layout editor still repainted the live floor: the Occupied /
  /// Seated / Reserved / Free chip and its wash, the bill and APC, covers, the
  /// waiter, the guest OTP, PAID, the outbox badge — and a tap opened the
  /// service sheet with the running order, the bill and Settle on it. That is
  /// the Tables screen, twice. On [FloorSurface.plan] the tile is the name and
  /// the seats, one neutral surface for every table, and a tap opens
  /// [_PlanTableSheet], which is layout only.
  ///
  /// The drag is untouched: [_FloorSections] wraps THIS widget either way.
  Widget _planTile(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final name = _s(table, 'table_name');
    final seats = _seatsLabel(table);
    final canEditSeating = FloorScope.of(profile, surface: FloorSurface.plan).editSeating;
    return InkWell(
      key: ValueKey('plan-table-$name'),
      onTap: () => showModalBottomSheet<void>(
        context: context,
        showDragHandle: true,
        isScrollControlled: true,
        backgroundColor: AppColors.surface,
        builder: (_) => _PlanTableSheet(rest: rest, profile: profile, table: table, reload: reload),
      ),
      borderRadius: AppRadius.cardAll,
      child: Container(
        width: width,
        constraints: const BoxConstraints(minHeight: 96),
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: focused ? AppColors.copperHi : AppColors.border, width: focused ? 2 : 1),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(name, maxLines: 1, overflow: TextOverflow.ellipsis, style: text.titleMedium),
            if (seats.isNotEmpty) ...[
              const SizedBox(height: 8),
              InfoChip(icon: Icons.event_seat_outlined, label: seats),
            ],
            const SizedBox(height: 10),
            Text(canEditSeating ? 'Tap to edit seating' : 'Layout',
                style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
          ],
        ),
      ),
    );
  }
}

/// The Floor plan's per-table sheet — requirement 2.1's other half.
///
/// What a table IS in the room: its name, its seats and its zone, and the one
/// per-table layout act, "Edit seating" (PATCH /table/:name {capacity,
/// max_capacity}). Deliberately nothing the Tables screen shows: no state chip,
/// no order, no bill, no timers, no waiter, no QR, no Settle. Deleting stays in
/// the Floor plan header (C7 / H8), and seating a party stays on Tables.
class _PlanTableSheet extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  final Map table;
  final VoidCallback reload;
  const _PlanTableSheet({required this.rest, required this.profile, required this.table, required this.reload});

  @override
  State<_PlanTableSheet> createState() => _PlanTableSheetState();
}

class _PlanTableSheetState extends State<_PlanTableSheet> {
  late final FloorScope _scope = FloorScope.of(widget.profile, surface: FloorSurface.plan);
  String get _name => _s(widget.table, 'table_name');

  // The same write the service sheet used to carry, and the same dialog. The
  // server refuses a table with a party seated on it; its words are shown.
  Future<void> _editSeating(ScaffoldMessengerState messenger) async {
    final seats = await showDialog<_TableSeating>(
      context: context,
      builder: (_) => _TableSeatingDialog(existing: widget.table),
    );
    if (seats == null) return;
    try {
      final res = await widget.rest.patch('/table/${Uri.encodeComponent(_name)}', {
        'capacity': seats.capacity,
        'max_capacity': seats.maxCapacity,
      });
      if (mounted) {
        setState(() {
          widget.table['capacity'] = res is Map ? (res['capacity'] ?? seats.capacity) : seats.capacity;
          widget.table['max_capacity'] =
              res is Map ? (res['max_capacity'] ?? seats.maxCapacity) : seats.maxCapacity;
        });
      }
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final messenger = ScaffoldMessenger.of(context);
    final text = Theme.of(context).textTheme;
    final seats = _seatsLabel(widget.table);
    final zone = _s(widget.table, 'section', '').trim();
    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Text('Table $_name', style: text.headlineMedium),
          const SizedBox(height: 10),
          Wrap(spacing: 6, runSpacing: 6, children: [
            if (seats.isNotEmpty) InfoChip(icon: Icons.event_seat_outlined, label: seats),
            InfoChip(icon: Icons.grid_view, label: zone.isEmpty ? 'Unassigned' : zone),
          ]),
          const SizedBox(height: 12),
          Text('Seating guests, orders and bills are on the Tables screen.',
              style: text.bodySmall!.copyWith(color: AppColors.textTertiary)),
          if (_scope.editSeating) ...[
            const SizedBox(height: 14),
            Center(
              child: ForkButton.ghost(
                key: const ValueKey('plan-edit-seating'),
                label: 'Edit seating',
                icon: Icons.event_seat_outlined,
                dense: true,
                onPressed: () => _editSeating(messenger),
              ),
            ),
          ],
        ]),
      ),
    );
  }
}

/// Bottom sheet for a table: its customer QR (printable) + seat / order /
/// settle / release actions.
///
/// NO LONGER DELETES ANYTHING — requirements C7 and H8. 'Delete table' lived at
/// the bottom of this sheet, which is the surface a waiter opens to take an
/// order and a manager opens to settle a bill; it is now a named control in the
/// Floor plan header (see [_deleteTableFromHeader]) and this sheet has no code
/// path that reaches DELETE /table/:name, for any role, on either surface.
class _TableSheet extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  final Map table;
  final VoidCallback reload;

  /// Which floor screen opened this sheet — requirement D5. The sheet carried
  /// two layout controls ("Edit seating", "Delete table"); on
  /// [FloorSurface.service] it now carries neither, for anybody.
  final FloorSurface surface;
  const _TableSheet(
      {required this.rest,
      required this.profile,
      required this.table,
      required this.reload,
      required this.surface});

  @override
  State<_TableSheet> createState() => _TableSheetState();
}

class _TableSheetState extends State<_TableSheet> {
  Map? _bill;

  /// GET /orders, read beside the bill so the preview can split the bill's lines
  /// by KOT (1.8). Null until read, and left null when the read fails — the
  /// preview then draws the flat list it always drew. See [tableKotGroups].
  List? _tableOrders;

  /// What this reader may do on this table, and whether they may see what it is
  /// worth. ONE object asked at every affordance below — see [FloorScope] for
  /// why it is a record of flags rather than a role check per control.
  late final FloorScope _scope = FloorScope.of(widget.profile, surface: widget.surface);

  String get _name => _s(widget.table, 'table_name');
  // "4 seats · max 6" — the guide seat count and the most it takes with extra
  // chairs (what the seating suggester sizes parties against).
  String get _seats => _seatsLabel(widget.table);
  // Partner tables when this one is half of a clubbed booking.
  List<String> get _clubbedWith => _strList(widget.table['clubbed_with']);
  // The ordering code to read out, or '' when the OTP gate is off.
  String get _otp => _tableOtp(widget.table);
  // Occupied == physically SEATED (is_occupied), and every action below keys on
  // it: a party who has not ordered yet still needs Add order, Settle, Release
  // and Edit seating. Only the header CHIP uses the three-state reading (see
  // _tableState), because only the chip is a description rather than a decision.
  bool get _occupied => _tableSeated(widget.table);
  /// The three-state floor status for the header chip — the only place in this
  /// sheet that describes rather than decides. Every ACTION below reads
  /// [_occupied], the seating, because a party who has not ordered yet still
  /// needs Add order, Settle, Release and Edit seating.
  ({String label, Color color}) get _state => _tableState(widget.table);
  String get _orderUrl {
    final root = '${AppConfig.orderBaseUrl}/order/${widget.profile.restaurantUsername}';
    // Opaque token hides + locks the table in the URL (preferred).
    final token = _s(widget.table, 'qr_token', '');
    if (token.isNotEmpty) return '$root?t=${Uri.encodeQueryComponent(token)}';
    final sig = _s(widget.table, 'qr_sig', '');
    final base = '$root?table=${Uri.encodeQueryComponent(_name)}';
    return sig.isEmpty ? base : '$base&sig=${Uri.encodeQueryComponent(sig)}';
  }

  @override
  void initState() {
    super.initState();
    if (_occupied) _loadBill();
  }

  Future<void> _loadBill() async {
    try {
      final r = await widget.rest.get('/bill-for-table?table_name=${Uri.encodeQueryComponent(_name)}');
      if (mounted && r is Map) setState(() => _bill = r);
    } on ApiException catch (e) {
      // 1.3 — cancelling a table's LAST KOT leaves it with no open bill, and the
      // server says so with a 404. Keeping the old bill would leave the
      // cancelled lines on screen under the button that just removed them.
      if (mounted && e.status == 404 && _bill != null) setState(() => _bill = null);
    } catch (_) {/* no bill yet */}
    // 1.8 — the orders the bill is made of, for their KOT numbers. A failure
    // here costs the split, never the bill: the flat list is still drawn.
    try {
      final orders = await widget.rest.getList('/orders');
      if (mounted) setState(() => _tableOrders = orders);
    } catch (_) {
      if (mounted && _tableOrders != null) setState(() => _tableOrders = null);
    }
  }

  /// 1.3 — CANCEL ONE KOT from its block in the preview.
  ///
  /// Nothing new underneath: [_cancelOrder] is the app's one cancel, so this
  /// gets the mandatory reason (1.2), the void-vs-plain route decision and the
  /// server's cancellation slip (1.1) exactly as the Orders screen does. The
  /// preview and the floor are re-read only when something was cancelled.
  Future<void> _cancelKot(TableKotGroup group) async {
    final order = group.order;
    if (order == null) return;
    final ok = await _cancelOrder(
      context,
      rest: widget.rest,
      profile: widget.profile,
      orderId: _s(order, 'id'),
      what: '${group.label} on Table $_name',
      value: _scope.money ? _money(order['total']) : '',
    );
    if (!ok) return;
    await _loadBill();
    widget.reload();
  }

  void _popAndReload() {
    if (mounted) Navigator.of(context).pop();
    widget.reload();
  }

  // Assign / change / remove the waiter responsible for this table.
  Widget _waiterRow(ScaffoldMessengerState messenger) {
    final waiter = _s(widget.table, 'waiter_name', '');
    final assigned = waiter.isNotEmpty && waiter != '—';
    return ForkCard(
      inset: true,
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      child: Row(children: [
        Icon(Icons.badge_outlined, size: 16, color: AppColors.textSecondary),
        const SizedBox(width: 10),
        Expanded(
          child: Text(assigned ? 'Waiter: $waiter' : 'No waiter assigned',
              style: Theme.of(context).textTheme.bodyLarge, maxLines: 1, overflow: TextOverflow.ellipsis),
        ),
        ForkButton.subtle(label: assigned ? 'Change' : 'Assign', onPressed: () => _assignWaiter(messenger)),
        if (assigned) ...[
          const SizedBox(width: 6),
          ForkIconButton(
            icon: Icons.close,
            tooltip: 'Remove waiter',
            onPressed: () => _removeWaiter(messenger),
          ),
        ],
      ]),
    );
  }

  Future<void> _assignWaiter(ScaffoldMessengerState messenger) async {
    // The picker is fed from the server's ASSIGNABLE roster, not the full staff
    // list: when the outlet uses attendance, only staff clocked in right now may
    // be assigned (the backend enforces the same rule on the assign write). An
    // outlet where nobody has ever clocked in gets everyone, as before.
    List users;
    var attendanceInUse = false;
    try {
      final m = await widget.rest.getMap('/table-assignments/assignable');
      users = (m['employees'] as List?) ?? [];
      attendanceInUse = m['attendance_in_use'] == true;
    } catch (_) {
      // Older backend without the roster endpoint — fall back to the full staff
      // list so assignment keeps working against it.
      try {
        final m = await widget.rest.getMap('/restaurant/users');
        users = (m['users'] as List?) ?? [];
      } catch (e) {
        messenger.showSnackBar(SnackBar(content: Text('$e')));
        return;
      }
    }
    if (!mounted) return;
    if (users.isEmpty && attendanceInUse) {
      messenger.showSnackBar(const SnackBar(
          content: Text(
              'No staff are clocked in right now — staff must clock in before they can be assigned a table.')));
      return;
    }
    final chosen = await showDialog<Map>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: const Text('Assign waiter'),
        children: [
          for (final u in users)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, u as Map),
              child: ListTile(
                dense: true,
                leading: const Icon(Icons.badge),
                title: Text('${_s(u, 'emp_Fname')} ${_s(u, 'emp_Lname', '')}'.trim()),
                subtitle: Text('@${_s(u, 'employee_Username')} · ${_s(u, 'role', 'staff')}'),
              ),
            ),
        ],
      ),
    );
    if (chosen == null) return;
    final id = '${chosen['employee_id'] ?? chosen['id'] ?? ''}';
    try {
      await widget.rest.post('/table-assignments/assign', {'table_name': _name, 'employeeId': id});
      setState(() {
        widget.table['waiter_name'] = '${_s(chosen, 'emp_Fname')} ${_s(chosen, 'emp_Lname', '')}'.trim();
        widget.table['waiter_id'] = id;
      });
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _removeWaiter(ScaffoldMessengerState messenger) async {
    try {
      await widget.rest.post('/table-assignments/unassign', {'table_name': _name});
      setState(() {
        widget.table.remove('waiter_name');
        widget.table.remove('waiter_id');
      });
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // APC traffic-light + push suggestions for the current table.
  Widget _apcInsight() {
    final status = _s(_bill!, 'apc_status', 'neutral');
    if (status == 'neutral') return const SizedBox.shrink();
    final text = Theme.of(context).textTheme;
    if (status == 'green') {
      return Container(
        margin: const EdgeInsets.only(top: 10),
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: AppColors.tint(AppColors.success),
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.edge(AppColors.success)),
        ),
        child: Row(children: [
          Icon(Icons.check_circle_outline, color: AppColors.success, size: 16),
          const SizedBox(width: 8),
          Expanded(
            child: Text('On target — great APC for this table.',
                style: text.titleSmall!.copyWith(color: AppColors.success)),
          ),
        ]),
      );
    }
    final c = status == 'red' ? AppColors.danger : AppColors.warning;
    final suggestions = (_bill!['apc_suggestions'] as List?) ?? [];
    return Container(
      margin: const EdgeInsets.only(top: 10),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: AppColors.tint(c),
        borderRadius: AppRadius.cardAll,
        border: Border.all(color: AppColors.edge(c)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(status == 'red' ? Icons.trending_down : Icons.lightbulb_outline, color: c, size: 16),
          const SizedBox(width: 8),
          Expanded(
            child: Text(status == 'red' ? 'Below target — push to upsell' : 'Close to target — suggest more',
                style: text.titleSmall!.copyWith(color: c)),
          ),
        ]),
        const SizedBox(height: 6),
        if (suggestions.isEmpty)
          Text('Suggest a dessert or a drink to lift the bill.', style: text.bodySmall)
        else
          ...suggestions.map((s) => Padding(
                padding: const EdgeInsets.only(top: 2),
                child: Text('• $s', style: text.bodySmall),
              )),
      ]),
    );
  }

  // Shown when a customer has paid from the QR page and is awaiting staff
  // approval. Staff review the uploaded screenshot, then approve & close.
  Widget _paymentReview(ScaffoldMessengerState messenger) {
    final method = _s(_bill!, 'payment_method');
    final shot = _s(_bill!, 'screenshot_url');
    // Only treat it as a screenshot if it's a real image URL — methods that don't
    // require proof (Cash/UPI/Card/…) have no screenshot, so don't show the box.
    final hasShot = shot.startsWith('http');
    final text = Theme.of(context).textTheme;
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: AppColors.tint(AppColors.warning),
        borderRadius: AppRadius.cardAll,
        border: Border.all(color: AppColors.edge(AppColors.warning)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [
          Icon(Icons.notifications_active_outlined, color: AppColors.warning, size: 18),
          const SizedBox(width: 8),
          Expanded(
            child: Text('Customer paid via ${method.isEmpty ? 'unknown method' : method} — review & approve',
                style: text.titleSmall),
          ),
        ]),
        if (hasShot) ...[
          const SizedBox(height: 10),
          GestureDetector(
            onTap: () => _viewImage(shot),
            child: ClipRRect(
              borderRadius: AppRadius.controlAll,
              child: Image.network(shot, height: 160, fit: BoxFit.cover,
                  errorBuilder: (_, _, _) => const Padding(
                      padding: EdgeInsets.all(8), child: Text('Could not load screenshot'))),
            ),
          ),
          const SizedBox(height: 4),
          Text('Tap to enlarge', style: text.bodySmall!.copyWith(fontSize: 11)),
        ],
        const SizedBox(height: 12),
        Align(
          alignment: Alignment.centerRight,
          child: ForkButton(
            label: 'Approve payment & close',
            icon: Icons.check_circle_outline,
            onPressed: () => _approveAndClose(messenger),
          ),
        ),
      ]),
    );
  }

  bool get _isAdmin => widget.profile.role == 'admin' || widget.profile.roleAll.contains('admin');

  // Server-side thermal print of this table's bill.
  //
  // RETURNS WHETHER THE SERVER TOOK IT, because requirement C3 hangs a one-shot
  // rule off this call: a print that was refused (no printer, a 400, the line
  // down) is a print the waiter still has to make, and burning their single
  // attempt on it would leave them holding a table they cannot bill.
  //
  // NO "WITHOUT THE SERVICE CHARGE" HERE ANY MORE. That used to be a flag on
  // this call, and the server stopped letting a flag lower a total: only a
  // recorded waiver takes the charge off, so the flag could only ever print
  // WITH it and say so. Taking the charge off and printing is now one control
  // with one server call — "Remove service charge & print" in
  // [misServiceChargeBlock] — and a bill that already carries a waiver prints
  // without the charge from here too, because the server applies the waiver to
  // every print.
  ///
  /// CLIENT ITEM 6: every successful print answers `next_party_table` — the
  /// seat the server opened (or found) for the next guests at this number -
  /// and the sentence that names it. It is kept in [_nextPartySeat] for the
  /// caller and said here unless [announceNextParty] is off (the waiter's path
  /// says it in its own, longer line). The floor behind this sheet is re-read
  /// so a manager sees the new tile without leaving the bill.
  Future<bool> _thermalPrint(ScaffoldMessengerState messenger, {bool announceNextParty = true}) async {
    try {
      final res = await widget.rest.post('/print/bill', {'table_name': _name});
      _nextPartySeat = nextPartyAfterPrint(res);
      final seat = _nextPartySeat.message;
      final say = announceNextParty && seat != null;
      messenger.showSnackBar(SnackBar(
          content: Text(say ? 'Printing bill… $seat' : 'Printing bill…'),
          duration: Duration(seconds: say ? 6 : 3)));
      if (_nextPartySeat.table != null) widget.reload();
      return true;
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
      return false;
    }
  }

  /// What the last print said about the next party's seat; see [_thermalPrint].
  ({String? table, String? message}) _nextPartySeat = (table: null, message: null);

  /// C3 — HAS THIS TABLE'S BILL ALREADY BEEN PRINTED?
  ///
  /// THE SERVER'S ANSWER DECIDES, exactly as [Profile.waiterOnly] is taken from
  /// the server rather than re-derived: there is one restaurant and several
  /// devices, and a rule about "once" that each device answers privately is a
  /// rule that means something different on each of them. `/bill-for-table`
  /// carries `print_count` / `bill_printed_at` / `printed_at`, so on any current
  /// backend the `??` below never fires.
  ///
  /// THE FALLBACK IS FOR AN OLDER BACKEND AND NOTHING ELSE — reached only when
  /// [serverBillPrintState] returns null, i.e. the payload carried none of
  /// [billPrintStateKeys]. It is NOT a second opinion: a server that says "not
  /// printed" is not overruled by this tablet's memory, because the server is
  /// describing the bill the guest is actually sitting in front of.
  bool get _billPrinted =>
      serverBillPrintState(_bill) ??
      PrintedBills.instance.printed(widget.profile.resId, widget.profile.outletId, _name);

  /// Whether this reader may print this bill, and what happens to the table on
  /// their screen once they have. One object asked at every affordance, for the
  /// same reason [FloorScope] is.
  BillPrintScope get _printScope => BillPrintScope.of(widget.profile, printed: _billPrinted);

  /// THE SERVER'S SERVICE CLOCK FOR THIS SEATING — requirement D2, measured
  /// once, on the machine that has the whole picture.
  ///
  /// Its start is the EARLIEST order on the bill (a guest ordering another round
  /// must not reset how long they have been sitting there, which is the exact
  /// behaviour D2 replaces) and its end is the SETTLEMENT. Null on a backend
  /// that predates `service`, which is the only reason [_settledAt] below still
  /// exists.
  ServiceClock? get _tableClock =>
      _bill == null ? null : ServiceClock.fromJson(_bill!['service']);

  /// WHEN THIS TABLE'S MONEY WAS CONFIRMED, or '' while it still owes — the
  /// FALLBACK closing end of requirement D2's span, for a backend with no
  /// service clock. Where [_tableClock] exists it decides instead, and it may
  /// legitimately still be RUNNING when this is set: the server does not treat a
  /// recorded payment method as a settled bill.
  ///
  /// The admin approval is preferred over the waiter's confirmation because on
  /// an outlet that reviews guest payments the waiter's is the REQUEST and the
  /// admin's is the settlement; on an outlet that does not, only the waiter's is
  /// ever written and it IS the settlement. Taking whichever exists, approval
  /// first, gives one answer on both.
  String get _settledAt {
    final b = _bill;
    if (b == null) return '';
    for (final k in const ['admin_approved_at', 'waiter_confirmed_at']) {
      final v = '${b[k] ?? ''}'.trim();
      if (v.isNotEmpty) return v;
    }
    return '';
  }

  // Fetch the current bill and show a receipt-style preview before anything is
  // sent to the thermal printer. "Print" in the dialog fires the same
  // server-side /print/bill call as before; "Cancel" prints nothing.
  // Legal entity, address lines, phone, GSTIN — in the order the printed bill
  // lays them out, and each included ONLY when the tenant actually has one. A
  // restaurant with no GSTIN gets a clean header, never a stray "GSTN :".
  // Mirrors the same rule in escpos.ts, which renders the real paper.
  //
  // The same two reads also say which ROLL the paper is cut from (58mm lays the
  // item table out in narrower columns and prints no margins), the tenant's
  // sentence above the QR, and whether the QR prints at all — nothing more is
  // fetched for any of them, they were already in these answers.
  Future<_BillPaper> _billPaper() async {
    try {
      final results = await Future.wait([
        widget.rest.getMap('/restaurant/settings'),
        widget.rest.getMap('/restaurant/profile'),
      ]);
      final settings = results[0];
      final profile = results[1];
      final lines = <String>[];
      final legalName = _s(settings, 'bill_legal_name', '').trim();
      if (legalName.isNotEmpty) lines.add(legalName);
      // A stored address is one field owners fill in with real line breaks;
      // honour those and drop blank ones so a trailing newline is not a gap.
      for (final l in _s(profile, 'outlet_add', '').split(RegExp(r'\r?\n'))) {
        if (l.trim().isNotEmpty) lines.add(l.trim());
      }
      // The outlet's own number, under the address and above the GSTIN — where
      // escpos.ts prints "Ph : …" off the same `outlet_phone`.
      final phone = _s(profile, 'outlet_phone', '').trim();
      if (phone.isNotEmpty) lines.add('Ph : $phone');
      final gstin = _s(settings, 'bill_gstin', '').trim();
      if (gstin.isNotEmpty) lines.add('GSTN : $gstin');
      return (
        headerLines: lines,
        narrow: _s(settings, 'bill_paper_width', '80mm') == '58mm',
        qrNote: _s(settings, 'bill_qr_note', '').trim(),
        qrNoteDefault: _s(settings, 'bill_qr_note_default', '').trim(),
        showQr: billShowsQr(settings),
      );
    } catch (_) {
      // An unreadable settings answer previews the DEFAULT paper, and the
      // default carries the QR — see [billShowsQr].
      return (headerLines: const <String>[], narrow: false, qrNote: '', qrNoteDefault: '', showQr: true);
    }
  }

  Future<void> _previewBill(ScaffoldMessengerState messenger) async {
    Map? bill;
    try {
      final r = await widget.rest.get('/bill-for-table?table_name=${Uri.encodeQueryComponent(_name)}');
      if (r is Map) bill = r;
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
      return;
    }
    if (bill == null || ((bill['items'] as List?) ?? const []).isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('No open bill to print for this table.')));
      return;
    }
    // The identity block the paper carries — legal entity, address, GSTIN — so
    // the preview shows the header the printer will actually produce instead of
    // just the trading name. Best-effort on purpose: this is a PREVIEW of a bill
    // the server renders, so a settings/profile hiccup must degrade to the old
    // name-only header rather than block the print.
    final paper = await _billPaper();
    // 5.1 — and the LOGO, which this preview never drew. The logo the roll
    // prints (GET /restaurant/logo/bill: the SVG bill logo or the branding PNG,
    // fitted and thresholded exactly as the printer gets it), falling back to
    // the branding PNG on a backend that predates that route. Best-effort like
    // the header: no logo is a preview without one, never a blocked print.
    Uint8List? logo;
    for (final path in const ['/restaurant/logo/bill', '/restaurant/logo']) {
      try {
        logo = billLogoBytes(await widget.rest.get(path));
      } catch (_) {/* none configured, or an older backend */}
      if (logo != null) break;
    }
    if (!mounted) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (_) => _BillPreviewDialog(
        bill: bill!,
        restaurantName: widget.profile.restaurantName,
        headerLines: paper.headerLines,
        logo: logo,
        tableName: _name,
        narrow: paper.narrow,
        qrNote: paper.qrNote.isNotEmpty ? paper.qrNote : paper.qrNoteDefault,
        // The owner's "Print QR code on the bill" switch. Off, /print/bill
        // sends the renderer no feedback URL and the paper ends at the total
        // (or the disclaimer), so the preview must end there too.
        showQr: paper.showQr,
        // The paper's "Cashier:" is whoever sends the print — /print/bill reads
        // the caller's employee record — which is the person signed in here.
        cashier: widget.profile.firstName.trim(),
        printedAt: RestaurantTime.nowWall(),
        // ROUND 2 ITEM 4 — read off the bill JUST fetched, not the sheet's copy:
        // another till may have printed it since this sheet opened. The same
        // tri-state C3 uses, so an older backend falls back to this device's
        // memory and nothing else.
        reprint: serverBillPrintState(bill) ??
            PrintedBills.instance.printed(widget.profile.resId, widget.profile.outletId, _name),
      ),
    );
    if (confirmed == true) {
      await _thermalPrint(messenger);
    }
  }

  /// Print the table's bill WITHOUT putting it on screen first.
  ///
  /// The two items pull against each other here and this is the seam between
  /// them: item 17 keeps "Print bill" as one of a waiter's two big controls, and
  /// item 19 takes every rupee off their screen — but [_previewBill] renders the
  /// whole receipt, line prices and grand total included, which is the money
  /// item 19 removes, drawn larger than anywhere else in the app.
  ///
  /// So the ACTION survives intact and only the on-screen rehearsal of it goes.
  /// The paper is unchanged: the same POST /print/bill, the same ESC/POS
  /// receipt, priced in full for the guest who is about to pay it. A waiter
  /// still hands over a real bill; they just do not read the restaurant's
  /// takings off their own screen to do it.
  ///
  /// The emptiness check is kept — printing a blank bill wastes a walk to the
  /// printer — but it reports only WHETHER there are lines, never what they are
  /// worth.
  Future<void> _printBillWithoutPreview(ScaffoldMessengerState messenger) async {
    Map? bill;
    try {
      final r = await widget.rest.get('/bill-for-table?table_name=${Uri.encodeQueryComponent(_name)}');
      if (r is Map) bill = r;
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
      return;
    }
    final lines = (bill?['items'] as List?) ?? const [];
    if (lines.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('No open bill to print for this table.')));
      return;
    }
    if (!mounted) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: AppColors.surface,
        title: Text('Print the bill for $_name?'),
        content: Text('${lines.length} item(s) on this table. The printed bill goes to the guest.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Print')),
        ],
      ),
    );
    if (ok != true) return;
    final retires = BillPrintScope.of(widget.profile, printed: true).retiresTable;
    if (!await _thermalPrint(messenger, announceNextParty: !retires)) return;
    // ---- REQUIREMENT C3: the one print, and what it costs the waiter --------
    //
    // Asked as the state the print PUTS this reader in — "printed: true" — so
    // the one rule in [BillPrintScope] answers here too rather than a second
    // role test being written at the call site. It comes back false for every
    // identity that is not waiter-only, so a manager's print marks nothing,
    // retires nothing, and reads exactly as it did.
    if (!BillPrintScope.of(widget.profile, printed: true).retiresTable) return;
    await PrintedBills.instance.mark(widget.profile.resId, widget.profile.outletId, _name);
    if (!mounted) return;
    // CLIENT ITEM 6: the table's NUMBER is not gone with it. The line names
    // the seat the server opened for the next guests ("Seat the next party at
    // 12 (next party).") — the tile the waiter will find on the floor below.
    final seat = _nextPartySeat.message;
    messenger.showSnackBar(SnackBar(
        duration: Duration(seconds: seat == null ? 4 : 7),
        content: Text('${tableSentenceNameOf(widget.table)} is printed and with a manager to settle. '
            'It has come off your tables.${seat == null ? '' : ' $seat'}')));
    // The sheet closes and the floor reloads WITHOUT this table — that is the
    // whole of "clear/reset from their view". NOTHING IS WRITTEN to the table:
    // it is still occupied, still owes the money, and is still on every
    // manager's screen. See [BillPrintScope] for why it cannot mean more than
    // that without becoming the settle C2 forbids.
    _popAndReload();
  }

  Future<void> _removeBillItem(ScaffoldMessengerState messenger, String name, double price) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Remove item?'),
        content: Text('Remove "$name" from this table\'s bill?'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), style: FilledButton.styleFrom(backgroundColor: AppColors.danger), child: const Text('Remove')),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await widget.rest.post('/bills/remove-item', {'table_name': _name, 'item_name': name, 'price': price});
      messenger.showSnackBar(SnackBar(content: Text('Removed $name.')));
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _moveBillItem(ScaffoldMessengerState messenger, String name, double price) async {
    // Pick a destination table (any other table).
    List tables = const [];
    try { tables = await widget.rest.getList('/get-tables'); } catch (_) {}
    final others = tables.map((t) => _s(t as Map, 'table_name')).where((n) => n.isNotEmpty && n != _name).toList();
    if (others.isEmpty) { messenger.showSnackBar(const SnackBar(content: Text('No other tables available.'))); return; }
    if (!mounted) return;
    final dest = await showDialog<String>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: Text('Move "$name" to…'),
        children: [
          for (final n in others)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, n),
              child: Text('Table $n'),
            ),
        ],
      ),
    );
    if (dest == null || dest.isEmpty) return;
    try {
      final res = await widget.rest.post('/bills/move-item', {'from_table': _name, 'to_table': dest, 'item_name': name, 'price': price});
      // CLIENT ITEM 6: moved onto a table whose bill is already printed — its
      // paper is now short, and the line offers the reprint of THAT table.
      final reprint = ReprintNeeded.parse(res, fallbackTable: dest);
      if (reprint == null) {
        messenger.showSnackBar(SnackBar(content: Text('Moved $name to Table $dest.')));
      } else if (mounted) {
        await askToReprint(context, widget.rest, reprint,
            messenger: messenger, lead: 'Moved $name to Table $dest.');
      }
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Add / edit / clear the kitchen note on a bill item, at any time (any staff).
  Future<void> _editBillItemNote(ScaffoldMessengerState messenger, String name, double price, String current) async {
    final ctrl = TextEditingController(text: current);
    final note = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Note for $name'),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          minLines: 1,
          maxLines: 3,
          decoration: const InputDecoration(hintText: 'e.g. no onions, extra spicy…', border: OutlineInputBorder()),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, ctrl.text.trim()), child: const Text('Save')),
        ],
      ),
    );
    if (note == null) return;
    try {
      await widget.rest.post('/bills/item-note', {'table_name': _name, 'item_name': name, 'price': price, 'note': note});
      messenger.showSnackBar(SnackBar(content: Text(note.isEmpty ? 'Note cleared.' : 'Note saved.')));
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Numeric bill field as a double (0 when missing).
  double _bn(String k) => (num.tryParse('${_bill?[k] ?? 0}') ?? 0).toDouble();

  // Apply, edit, or clear a percentage/flat discount on the table's open bill.
  Future<void> _setDiscount(ScaffoldMessengerState messenger) async {
    String type = _s(_bill!, 'discount_type').isEmpty ? 'percent' : _s(_bill!, 'discount_type');
    final ctrl = TextEditingController(text: _bn('discount_value') > 0 ? _bn('discount_value').toString() : '');
    final ok = await showDialog<bool?>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setLocal) => AlertDialog(
          title: const Text('Apply discount'),
          content: Column(mainAxisSize: MainAxisSize.min, children: [
            SegmentedButton<String>(
              segments: const [
                ButtonSegment(value: 'percent', label: Text('% off')),
                ButtonSegment(value: 'flat', label: Text('Flat')),
              ],
              selected: {type},
              onSelectionChanged: (s) => setLocal(() => type = s.first),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: ctrl,
              autofocus: true,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: InputDecoration(
                labelText: type == 'percent' ? 'Percent off (0–100)' : 'Amount off',
                border: const OutlineInputBorder(),
              ),
            ),
          ]),
          actions: [
            if (_bn('discount') > 0)
              TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: Text('Remove', style: TextStyle(color: AppColors.danger)),
              ),
            TextButton(onPressed: () => Navigator.pop(ctx, null), child: const Text('Cancel')),
            FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Apply')),
          ],
        ),
      ),
    );
    if (ok == null) return; // cancelled
    final value = ok ? (double.tryParse(ctrl.text.trim()) ?? 0) : 0;
    try {
      final res = await widget.rest.post('/bills/discount', {'table_name': _name, 'type': type, 'value': value});
      // Above the restaurant's approval threshold: parked for a manager instead
      // of applying — tell the waiter what happened.
      final pending = res is Map && res['pending'] == true;
      messenger.showSnackBar(SnackBar(
          content: Text(pending
              ? 'Discount sent for manager approval — it will apply once approved.'
              : value > 0
                  ? 'Discount applied.'
                  : 'Discount removed.')));
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Apply a coupon code to the table's bill (validated + applied server-side).
  Future<void> _applyCoupon(ScaffoldMessengerState messenger) async {
    final ctrl = TextEditingController(text: _s(_bill!, 'coupon_code'));
    final code = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Apply coupon'),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          textCapitalization: TextCapitalization.characters,
          decoration: const InputDecoration(labelText: 'Coupon code', hintText: 'e.g. SAVE10', border: OutlineInputBorder()),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, ctrl.text.trim()), child: const Text('Apply')),
        ],
      ),
    );
    if (code == null || code.isEmpty) return;
    try {
      final res = await widget.rest.post('/bills/apply-coupon', {'table_name': _name, 'code': code});
      final disc = res is Map ? _money(res['discount']) : '';
      messenger.showSnackBar(SnackBar(content: Text('Coupon applied — $disc off.')));
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  /// 6.5 — change the name printed on this table's bill (POST
  /// /bills/customer-name), then re-read the bill so the sheet, the preview and
  /// the next print all carry it. The dialog and its rules live in
  /// bill_customer_name.dart.
  ///
  /// ROUND 2 ITEM 1 — and the customer's GSTIN with it. `customer_gstin` is
  /// sent only when the person CHANGED it: the route reads an omitted field as
  /// "unchanged", so a name-only correction is exactly the request it always
  /// was, and keeps working on a server whose GSTIN column is not migrated yet.
  Future<void> _editBillCustomerName(ScaffoldMessengerState messenger) async {
    final currentGstin = '${_bill?['customer_gstin'] ?? ''}'.trim();
    final details = await _askBillCustomerDetails(
      context,
      title: 'Name / GSTIN on bill · Table $_name',
      // Said plainly because the behaviour is not obvious: the name is stored
      // on every running order, so it changes the whole table's bill, and a
      // settled bill is refused by this route (Accounting has its own).
      explanation: 'This is the name printed at the top of the bill. It applies to the whole '
          'table, and can be changed until the bill is settled. Leave it empty to '
          'print no name.',
      currentName: _bill?['customer'],
      currentGstin: currentGstin,
    );
    if (details == null) return;
    final name = details.customer;
    final gstinChanged = details.gstin != normaliseBillCustomerGstin(currentGstin);
    try {
      final res = await widget.rest.post('/bills/customer-name', {
        'table_name': _name,
        'customer': name,
        if (gstinChanged) 'customer_gstin': details.gstin.isEmpty ? null : details.gstin,
      });
      // The server's answer when it gave one: it normalises again, and `null`
      // is how it says the name was cleared.
      final saved = res is Map && res.containsKey('customer') ? '${res['customer'] ?? ''}' : name;
      // A server a release behind answers the name and silently ignores a field
      // it has never heard of. Its answer then has no `customer_gstin`, and the
      // person must hear that the GSTIN did not stick rather than find out from
      // the paper.
      final gstinIgnored = gstinChanged && res is Map && !res.containsKey('customer_gstin');
      final savedGstin = res is Map && res.containsKey('customer_gstin') ? '${res['customer_gstin'] ?? ''}' : details.gstin;
      messenger.showSnackBar(SnackBar(
          content: Text([
        saved.isEmpty
            ? 'Name cleared — the bill will print without a guest name.'
            : "Name updated — this table's bill now prints for $saved.",
        if (gstinIgnored)
          'The GSTIN was not saved: this server has not finished updating.'
        else if (gstinChanged)
          savedGstin.isEmpty ? 'Customer GSTIN removed.' : 'Customer GSTIN: $savedGstin.',
      ].join(' '))));
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text(_billCustomerDetailsFailure(e, settled: false))));
    }
  }

  /// ROUND 2 ITEM 1 — "on top of a clicked table these details can be updated".
  ///
  /// The guest's name and GSTIN, directly under the table's name, with the edit
  /// beside them. It USED to be a button in the bill-controls wrap halfway down
  /// the sheet, which is not where the client looks, and which a phone had to
  /// scroll past the orders to reach.
  ///
  /// Shown to anyone who may edit it (so an unnamed table can be named), and to
  /// everyone else only when there is something to read. Neither the name nor
  /// the GSTIN is money, so a waiter's scoping does not remove them (C4).
  Widget? _billCustomerHeader(ScaffoldMessengerState messenger, TextTheme text) {
    if (!_occupied || _bill == null) return null;
    final name = billCustomerNameSeed(_bill!['customer']);
    final gstin = _s(_bill!, 'customer_gstin', '').trim();
    final mayEdit = _mayEditBillCustomerName(widget.profile, _scope);
    if (!mayEdit && name.isEmpty && gstin.isEmpty) return null;
    return ForkCard(
      key: const ValueKey('table-bill-customer-header'),
      inset: true,
      padding: const EdgeInsets.fromLTRB(14, 10, 8, 10),
      child: Row(children: [
        Icon(Icons.person_outline, size: 18, color: AppColors.textSecondary),
        const SizedBox(width: 10),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(name.isEmpty ? 'No guest name on the bill' : name,
                key: const ValueKey('table-bill-customer'),
                style: name.isEmpty ? text.bodySmall : text.titleSmall,
                maxLines: 2,
                overflow: TextOverflow.ellipsis),
            if (gstin.isNotEmpty) ...[
              const SizedBox(height: 2),
              Text('GSTIN $gstin', key: const ValueKey('table-bill-customer-gstin'), style: text.bodySmall),
            ],
          ]),
        ),
        if (mayEdit) ...[
          const SizedBox(width: 8),
          ForkButton.ghost(
            key: const ValueKey('table-bill-customer-name'),
            label: 'Edit name / GSTIN',
            icon: Icons.edit_outlined,
            dense: true,
            onPressed: () => _editBillCustomerName(messenger),
          ),
        ],
      ]),
    );
  }

  // Even split: divide the total payable N ways and show each share.
  Future<void> _splitBill(ScaffoldMessengerState messenger) async {
    final ctrl = TextEditingController(text: '2');
    final n = await showDialog<int>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Split bill evenly'),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          keyboardType: TextInputType.number,
          decoration: const InputDecoration(labelText: 'Number of ways', border: OutlineInputBorder()),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, int.tryParse(ctrl.text.trim()) ?? 0), child: const Text('Split')),
        ],
      ),
    );
    if (n == null || n < 2) return;
    try {
      final res = await widget.rest.post('/bills/split', {'table_name': _name, 'mode': 'even', 'parts': n});
      if (res is! Map) return;
      final parts = (res['parts'] as List?) ?? const [];
      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: Text('Split $n ways · ${_money(res['grand_total'])}'),
          content: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            for (final p in parts)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 4),
                child: Row(children: [
                  Expanded(child: Text(_s(p as Map, 'label'))),
                  Text(_money(p['total']), style: const TextStyle(fontWeight: FontWeight.bold)),
                ]),
              ),
          ]),
          actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Done'))],
        ),
      );
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Merge another occupied table's orders into this one (combine checks).
  Future<void> _mergeBill(ScaffoldMessengerState messenger) async {
    List tables = const [];
    try { tables = await widget.rest.getList('/get-tables'); } catch (_) {}
    final others = tables.where((t) {
      final m = t as Map;
      final n = _s(m, 'table_name');
      final occ = m['occupied'] == true || m['is_occupied'] == true;
      return n.isNotEmpty && n != _name && occ;
    }).map((t) => _s(t as Map, 'table_name')).toList();
    if (others.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('No other occupied tables to merge.')));
      return;
    }
    if (!mounted) return;
    final src = await showDialog<String>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: Text('Merge which table into $_name?'),
        children: [
          for (final n in others)
            SimpleDialogOption(onPressed: () => Navigator.pop(ctx, n), child: Text('Table $n')),
        ],
      ),
    );
    if (src == null || src.isEmpty) return;
    try {
      final res = await widget.rest.post('/bills/merge', {'from_table': src, 'to_table': _name});
      // CLIENT ITEM 6: merged into this table after its bill was printed (the
      // "same guests, one more round" case) — the paper is short until it is
      // reprinted, and the line offers exactly that.
      final reprint = ReprintNeeded.parse(res, fallbackTable: _name);
      if (reprint == null) {
        messenger.showSnackBar(SnackBar(content: Text('Merged Table $src into $_name.')));
      } else if (mounted) {
        // This sheet IS that table: the reprint is its own Print, next-party
        // line and all.
        await askToReprint(context, widget.rest, reprint,
            messenger: messenger,
            lead: 'Merged Table $src into $_name.',
            printHere: reprint.table == _name ? () => _thermalPrint(messenger) : null);
      }
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  /// MOVE THE WHOLE PARTY to another table — items 10/21.
  ///
  /// One call, `POST /tables/move`, because a party half-moved is worse than a
  /// party not moved: their orders on one table and their seating on another
  /// means the bill splits, the floor lies about who is sitting where, and the
  /// covers behind APC are counted against a table nobody is at. The server does
  /// the whole thing in one transaction (MoveTableParty) and this screen never
  /// issues a partial sequence of its own.
  ///
  /// The destination list is FREE tables only. An occupied destination is what
  /// Merge is for — putting two parties on one bill — and the server refuses it
  /// by name, but offering it here and then explaining the refusal would be a
  /// worse way to teach the same thing than not offering it.
  Future<void> _moveTable(ScaffoldMessengerState messenger) async {
    List rows = const [];
    try {
      rows = await widget.rest.getList('/get-tables');
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Could not read the floor plan — $e')));
      return;
    }
    final covers = _int(widget.table['covers']) ?? 1;
    final free = rows.where((t) {
      final m = t as Map;
      final n = _s(m, 'table_name');
      if (n.isEmpty || n == _name) return false;
      if (_tableSeated(m)) return false;
      // The server enforces this too (assertCoversFitTable, the same rule
      // seating uses). Filtering here means the list only ever offers tables the
      // party actually fits in, rather than teaching capacity through a refusal.
      final max = _int(m['max_capacity']) ?? _int(m['capacity']) ?? 1;
      return max >= covers;
    }).toList();
    if (free.isEmpty) {
      messenger.showSnackBar(SnackBar(
          content: Text('No free table seats $covers right now. Free one up, or raise its max seats.')));
      return;
    }
    if (!mounted) return;
    final dest = await showDialog<String>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: Text('Move the party at $_name to…'),
        children: [
          for (final t in free)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, _s(t as Map, 'table_name')),
              child: ListTile(
                dense: true,
                leading: const Icon(Icons.table_restaurant),
                title: Text('Table ${_s(t, 'table_name')}'),
                subtitle: Text(_seatsLabel(t)),
              ),
            ),
        ],
      ),
    );
    if (dest == null || dest.isEmpty || !mounted) return;
    // Named consequences, because this moves money as well as people.
    final ok = await _confirm(
      context,
      'Move everything from $_name to $dest?',
      'The guests, their $covers cover${covers == 1 ? '' : 's'}, every order and the '
      'running bill move together. $_name becomes free.',
    );
    if (!ok) return;
    try {
      final res = await widget.rest.post('/tables/move', {'from_table': _name, 'to_table': dest});
      final moved = res is Map ? (_int(res['moved_orders']) ?? 0) : 0;
      messenger.showSnackBar(SnackBar(
          content: Text('Moved $_name to $dest — $moved order${moved == 1 ? '' : 's'} came with them.')));
      _popAndReload();
    } catch (e) {
      // The server refuses rather than half-applying, so the floor is exactly as
      // it was and the message is the whole story.
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  /// MOVE ONE KOT to the table it should have been rung in on — item 22.
  ///
  /// This is the mis-key correction, and it is NOT [_moveTable]: the party at
  /// this table stays exactly where they are, and only the ticket leaves.
  ///
  /// WHAT THE KITCHEN SEES is the half that makes this safe, so the confirm says
  /// it before anything happens. If the docket has already printed, the pass is
  /// holding paper for the wrong table — so the server prints a CORRECTION
  /// carrying the same KOT number, and the snackbar reports which number, so
  /// whoever pressed the button can go and say it. If it was never printed there
  /// is nothing on the pass to correct and nothing prints; the ordinary trigger
  /// will print it at the right table when it fires.
  Future<void> _moveKot(ScaffoldMessengerState messenger) async {
    List all = const [];
    try {
      all = await widget.rest.getList('/orders');
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Could not read this table\'s orders — $e')));
      return;
    }
    // This table's LIVE tickets. A settled or cancelled order is not a kitchen
    // ticket any more and the server refuses to move one.
    //
    // `/orders` rows name their table `table` — every other reader of this
    // endpoint in the app says so. This filter read `table_name` (the
    // `/get-tables` spelling), matched nothing against the real server, and
    // reported "No live order on this table to move." on every table.
    final mine = all.where((o) {
      final m = o as Map;
      return _s(m, 'table') == _name && _orderSection(_s(m, 'status')) != 2;
    }).toList();
    if (mine.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('No live order on this table to move.')));
      return;
    }
    if (!mounted) return;
    // One ticket needs no picker; several do, and each row has to say enough to
    // tell them apart — what is on it, what it is worth, and whether the kitchen
    // has already been told.
    var order = mine.length == 1 ? mine.first as Map : null;
    order ??= await showDialog<Map>(
        context: context,
        builder: (ctx) => SimpleDialog(
          title: Text('Which order on $_name?'),
          children: [
            for (final o in mine)
              SimpleDialogOption(
                onPressed: () => Navigator.pop(ctx, o as Map),
                child: ListTile(
                  dense: true,
                  leading: Icon(_orderBarked(o) ? Icons.receipt_long : Icons.hourglass_empty),
                  title: Text(_kotSummary(o)),
                  subtitle: Text(_orderBarked(o)
                      ? 'The kitchen has this one'
                      : 'Not sent to the kitchen yet'),
                ),
              ),
          ],
        ),
      );
    if (order == null || !mounted) return;

    List rows = const [];
    try {
      rows = await widget.rest.getList('/get-tables');
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('Could not read the floor plan — $e')));
      return;
    }
    // ANY other real table, seated or not. Unlike a party move, an occupied
    // destination is the ordinary case here: the guests this food belongs to are
    // usually already sitting somewhere with a bill of their own.
    final others = rows.where((t) {
      final m = t as Map;
      final n = _s(m, 'table_name');
      return n.isNotEmpty && n != _name;
    }).toList();
    if (others.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('There is no other table to move it to.')));
      return;
    }
    if (!mounted) return;
    final dest = await showDialog<String>(
      context: context,
      builder: (ctx) => SimpleDialog(
        title: const Text('Move this order to…'),
        children: [
          for (final t in others)
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, _s(t as Map, 'table_name')),
              child: ListTile(
                dense: true,
                leading: Icon(_tableSeated(t) ? Icons.people : Icons.table_restaurant),
                title: Text('Table ${_s(t, 'table_name')}'),
                subtitle: Text(_tableSeated(t) ? 'Seated' : 'Free — this will seat it'),
              ),
            ),
        ],
      ),
    );
    if (dest == null || dest.isEmpty || !mounted) return;
    final barked = _orderBarked(order);
    final ok = await _confirm(
      context,
      'Move this order to $dest?',
      barked
          ? 'The kitchen already has a docket for $_name, so a correction docket '
            'prints for $dest with the same KOT number. $_name keeps its guests '
            'and its other orders.'
          : 'The kitchen has not been sent this order yet, so nothing prints now — '
            'it will print for $dest when it is sent.',
    );
    if (!ok) return;
    try {
      final res = await widget.rest.post(
        '/tables/move-order',
        {'order_id': _s(order, 'id'), 'to_table': dest},
      );
      final print = res is Map ? res['print'] : null;
      final kotNo = print is Map ? print['kot_no'] : null;
      final printed = print is Map && print['printed'] == true;
      messenger.showSnackBar(SnackBar(
        content: Text(printed
            ? 'Moved to $dest. Correction docket KOT-$kotNo is printing — tell the pass.'
            : 'Moved to $dest. Nothing was on the pass for it, so no docket printed.'),
      ));
      _popAndReload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Refund the most recent settled bill for this table (admin only).
  Future<void> _refundBill(ScaffoldMessengerState messenger) async {
    final reasonCtrl = TextEditingController();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Refund last settled bill?'),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          const Text('Refunds the most recent settled bill for this table. This cannot be undone.'),
          const SizedBox(height: 12),
          TextField(controller: reasonCtrl, decoration: const InputDecoration(labelText: 'Reason (optional)', border: OutlineInputBorder())),
        ]),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: FilledButton.styleFrom(backgroundColor: AppColors.danger),
            child: const Text('Refund'),
          ),
        ],
      ),
    );
    if (ok != true) return;
    try {
      final res = await widget.rest.post('/bills/refund', {
        'table_name': _name,
        if (reasonCtrl.text.trim().isNotEmpty) 'reason': reasonCtrl.text.trim(),
      });
      final gw = res is Map ? '${res['gateway']}' : '';
      final amt = res is Map ? _money(res['amount']) : '';
      final note = gw == 'manual'
          ? ' — process the Razorpay refund from your dashboard'
          : gw == 'failed'
              ? ' — gateway refund failed, process it manually'
              : '';
      messenger.showSnackBar(SnackBar(content: Text('Refunded $amt$note.')));
      await _loadBill();
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _approveAndClose(ScaffoldMessengerState messenger) async {
    final orderIds = (_bill?['order_ids'] as List?) ?? [];
    if (orderIds.isEmpty) return;
    final oid = '${orderIds.first}';
    try {
      await widget.rest.post('/bills/order/$oid/admin-approve-payment');
      await widget.rest.post('/bills/order/$oid/close');
      messenger.showSnackBar(const SnackBar(content: Text('Payment approved — table freed.')));
      _popAndReload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  void _viewImage(String url) {
    showDialog<void>(
      context: context,
      builder: (_) => Dialog(
        child: InteractiveViewer(child: Image.network(url)),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final messenger = ScaffoldMessenger.of(context);
    final text = Theme.of(context).textTheme;
    final items = _occupied && _bill != null ? ((_bill!['items'] as List?) ?? const []) : const [];

    // 1.8 — the bill's lines split by KOT, or null to draw them flat.
    final kotGroups = items.isEmpty ? null : tableKotGroups(_bill, _tableOrders);
    final mayCancelKot = _mayCancelKot(widget.profile);

    // One line of the open order: "2 × Paneer Tikka", its kitchen note, its
    // amount where this reader may see money, and its note / edit actions.
    // Shared by the per-KOT blocks and the flat list.
    Widget itemRow(Map m) {
      final qty = num.tryParse('${m['quantity'] ?? 1}') ?? 1;
      final price = num.tryParse('${m['price'] ?? 0}') ?? 0;
      final name = _s(m, 'name');
      final note = _s(m, 'note', '');
      final hasNote = note.isNotEmpty;
      return Padding(
        padding: const EdgeInsets.only(bottom: 8),
        child: ForkCard(
          inset: true,
          padding: const EdgeInsets.fromLTRB(14, 8, 6, 8),
          child: Row(children: [
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('${qty.toInt()} × $name', style: text.titleSmall),
                if (hasNote)
                  Padding(
                    padding: const EdgeInsets.only(top: 3),
                    child: Row(children: [
                      Icon(Icons.sticky_note_2_outlined, size: 12, color: AppColors.textTertiary),
                      const SizedBox(width: 5),
                      Expanded(
                        child: Text(note,
                            style: text.bodySmall!
                                .copyWith(fontSize: 11, fontStyle: FontStyle.italic)),
                      ),
                    ]),
                  ),
              ]),
            ),
            // ITEM 19: the per-dish amounts down the right of an
            // open order. The line itself stays — "2 x Paneer Tikka"
            // with its kitchen note is the ticket, and a waiter who
            // cannot read the ticket cannot work the table.
            if (_scope.money) ...[
              const SizedBox(width: 10),
              Text(_money(price * qty), style: text.titleSmall),
            ],
            // Any staff can add/edit a kitchen note on an item, anytime.
            IconButton(
              icon: Icon(Icons.sticky_note_2_outlined, size: 18,
                  color: hasNote ? AppColors.copperHi : AppColors.textSecondary),
              tooltip: hasNote ? 'Edit note' : 'Add note',
              visualDensity: VisualDensity.compact,
              onPressed: () => _editBillItemNote(messenger, name, price.toDouble(), note),
            ),
            // Admin can fix wrongly-added / wrong-table items.
            if (_isAdmin)
              PopupMenuButton<String>(
                icon: const Icon(Icons.more_vert, size: 18),
                tooltip: 'Edit item',
                onSelected: (v) {
                  if (v == 'remove') _removeBillItem(messenger, name, price.toDouble());
                  if (v == 'move') _moveBillItem(messenger, name, price.toDouble());
                },
                itemBuilder: (_) => const [
                  PopupMenuItem(value: 'remove', child: Text('Remove from bill')),
                  PopupMenuItem(value: 'move', child: Text('Move to another table')),
                ],
              ),
          ]),
        ),
      );
    }

    // Bill-math line: quiet label left, right-aligned amount.
    Widget billRow(String k, String v) => Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: Row(children: [
            Expanded(child: Text(k, style: text.bodyMedium)),
            Text(v, style: text.titleSmall),
          ]),
        );

    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Row(children: [
              // "Table 12 (next party)" for a next-party seat (client item 6) -
              // the number the waiter tapped, in the words the web uses too.
              Expanded(child: Text('Table ${tableSentenceNameOf(widget.table)}', style: text.headlineMedium)),
              StatusChip(label: _state.label, color: _state.color),
            ]),
            const SizedBox(height: 10),
            Wrap(spacing: 6, runSpacing: 6, children: [
              // ...and the name its KOT and bill will print, so the paper the
              // cashier holds can be matched to this tile.
              if (isNextPartyRow(widget.table))
                InfoChip(
                    key: const ValueKey('next-party-bill-name'),
                    icon: Icons.receipt_long_outlined,
                    label: 'Bill reads $_name'),
              if (_seats.isNotEmpty) InfoChip(icon: Icons.event_seat_outlined, label: _seats),
              if (_clubbedWith.isNotEmpty)
                InfoChip(icon: Icons.link, label: 'Clubbed with ${_clubbedWith.join(' + ')}'),
              // ---- REQUIREMENTS D2 AND D1, in that order -------------------
              //
              // D2 first because it is the table's headline: how long this party
              // has been running, from their FIRST order to the moment the bill
              // is settled. `first_order_at` and the settlement instants are all
              // read off /bill-for-table — the server's own timestamps, not a
              // duration this screen inferred from anything.
              //
              // WHY THE END IS THE APPROVAL AND NOT THE CLOSE. A bill's
              // `admin_approved_at` / `waiter_confirmed_at` is the moment the
              // money is confirmed, which is what "bill settlement" means to the
              // person reading this chip. It is also the last instant this sheet
              // can see: a settled table stops having an open bill, so the sheet
              // stops being opened for it at all. Falling through to nothing —
              // an empty `toIso` — simply leaves the chip ticking, which is the
              // correct reading of a table that has not been settled yet.
              if (_occupied && _bill != null) ...[
                _LiveElapsed(
                  key: const ValueKey('table-open-for'),
                  // THE SERVER'S CLOCK, not this sheet's subtraction — and the
                  // two did not agree. This screen stopped the span at
                  // `admin_approved_at` / `waiter_confirmed_at`; the server stops
                  // it at the bill's CLOSE, on the stated grounds that a bill
                  // whose payment method has been recorded is not a bill that has
                  // been paid. One table, one manager, two figures, until one of
                  // us gave way — and the one that holds the whole picture and
                  // exists exactly once is the one that should not have.
                  clock: _tableClock,
                  fromIso: _s(_bill!, 'first_order_at', ''),
                  toIso: _settledAt,
                  label: (_tableClock?.running ?? _settledAt.isEmpty) ? 'On table' : 'Took',
                  icon: Icons.timelapse_outlined,
                  escalates: false,
                ),
                // D1 — THE KITCHEN PREP TIMER, and the one a waiter is actually
                // standing there asking about: how long has the kitchen had the
                // LATEST ticket for this table. It escalates on the kitchen's own
                // thresholds (see [_elapsedColor]), so "the pass is late" reads
                // the same here as it does on the pass.
                //
                // Only when it differs from the D2 chip. On a table that has
                // ordered once the two spans are the same span, and two chips
                // saying "14m" with different words in front of them is how a
                // screen teaches people to stop reading it.
                if (_s(_bill!, 'last_order_at', '') != _s(_bill!, 'first_order_at', ''))
                  _LiveElapsed(
                    key: const ValueKey('table-latest-order'),
                    // The same server reading, restarted at the latest ticket.
                    // /bill-for-table carries ONE clock for the seating, so this
                    // shortens it by the gap between the bill's own
                    // `first_order_at` and `last_order_at` — two of the server's
                    // timestamps, differenced against each other. No device clock
                    // enters it, which is the only property this has to keep.
                    clock: _tableClock?.rebasedTo(_s(_bill!, 'last_order_at', '')),
                    fromIso: _s(_bill!, 'last_order_at', ''),
                    toIso: _settledAt,
                    label: 'Latest order',
                    icon: Icons.soup_kitchen_outlined,
                  ),
              ],
            ]),
            // ROUND 2 ITEM 1 — the name and GSTIN on this table's bill, at the top.
            if (_billCustomerHeader(messenger, text) case final header?) ...[
              const SizedBox(height: 12),
              header,
            ],
            const SizedBox(height: 16),
            // 6.7 — "Add order" and "Print bill" live HERE, above the QR, the
            // orders and the bill, at hero size. See [_orderAndPrintActions].
            ..._orderAndPrintActions(messenger, text),
            // ITEM 17: THE GUEST QR IS GONE FOR A WAITER, and this is the whole
            // of why the two controls they came here for can be at the top —
            // the code, its URL and "Print QR" were 250-odd vertical pixels of
            // setup artefact sitting between the table's name and its actions.
            // The printed sheet is already on the table; nobody scans a phone
            // held by a waiter.
            if (_scope.guestQr)
            Center(
              child: Column(children: [
                // Deliberately paper-white: the QR mirrors the printed sheet and
                // must stay high-contrast for scanners.
                Container(
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(10)),
                  child: QrImageView(data: _orderUrl, size: 170),
                ),
                const SizedBox(height: 8),
                Text('Customers scan to order & pay', style: text.bodySmall),
                // The code the guest must type after scanning. Shown ONLY while
                // the require-table-OTP setting is on (see [_tableOtp]) — with
                // the gate off there is no code to read out and the row is gone
                // entirely rather than showing a stale or empty one.
                if (_otp.isNotEmpty) ...[
                  const SizedBox(height: 10),
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                    decoration: BoxDecoration(
                      color: AppColors.tint(AppColors.copper),
                      borderRadius: AppRadius.controlAll,
                      border: Border.all(color: AppColors.edge(AppColors.copper)),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      Icon(Icons.lock_outline, size: 14, color: AppColors.copperHi),
                      const SizedBox(width: 7),
                      Text('OTP $_otp',
                          style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w700,
                              letterSpacing: 2,
                              color: AppColors.copperHi)),
                    ]),
                  ),
                  const SizedBox(height: 4),
                  Text('Read this out — guests enter it before they can order',
                      style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
                ],
                const SizedBox(height: 4),
                SelectableText(_orderUrl,
                    textAlign: TextAlign.center,
                    style: text.bodySmall!.copyWith(fontSize: 10.5, color: AppColors.textTertiary)),
                const SizedBox(height: 10),
                ForkButton.ghost(
                  label: 'Print QR',
                  icon: Icons.print,
                  dense: true,
                  onPressed: () => _printTableQr(_name, _orderUrl),
                ),
              ]),
            ),
            if (_scope.guestQr) const SizedBox(height: 20),
            // ITEM 14: the "No waiter assigned / Waiter: X" row, with its
            // Assign / Change / Remove controls. Who covers a table is a
            // floor-manager decision, and the row's own answer to a waiter was
            // always either their own name or somebody else's.
            if (_scope.assignWaiter) _waiterRow(messenger),
            if (_occupied && _bill != null) ...[
              if (items.isNotEmpty) ...[
                const SizedBox(height: 20),
                SectionHeader(title: 'Orders', count: items.length),
                // 1.8 — ONE BLOCK PER KOT, each under its own "KOT 5 · 14:57"
                // header, instead of one long list the kitchen's tickets could
                // not be found in. [tableKotGroups] answers null when it cannot
                // account for every order on the bill, and the flat list below
                // is then drawn exactly as before.
                if (kotGroups != null)
                  for (final g in kotGroups)
                    _TableKotBlock(
                      group: g,
                      itemRow: itemRow,
                      // 1.3 — on a real KOT only, and only for whoever may cancel.
                      onCancel: g.numbered && mayCancelKot && !_isCancelled(_s(g.order!, 'status', ''))
                          ? () => _cancelKot(g)
                          : null,
                    )
                else
                  ...items.map((it) => itemRow(it as Map)),
              ],
              const SizedBox(height: 12),
              // ITEM 19: THE RUNNING BILL AND THE PER-TABLE APC.
              //
              // The whole block goes for a waiter, not the total alone. Subtotal,
              // comps, discount, service charge, tax, TOTAL PAYABLE, covers, APC
              // and target APC are the same figure said seven ways, and the APC
              // insight card underneath it ("Below target - push to upsell") is
              // that figure again as an instruction. Leaving any one of them is
              // leaving the number.
              //
              // COVERS GO WITH IT, and that is deliberate rather than sloppy:
              // covers only appear here as the divisor beside the APC they
              // produce, so a lone "4 covers" under a heading called Bill reads
              // as a fragment of a bill the reader cannot see.
              if (_scope.money) ...[
              const SectionHeader(title: 'Bill'),
              ForkCard(
                inset: true,
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  billRow('Subtotal', _money(_bill!['subtotal'] ?? _bill!['total_amt'])),
                  // COMPED FOOD, SHOWN RATHER THAN SIMPLY ABSENT (migration 034).
                  // `nc_total` is deliberately NOT part of the subtotal — that is
                  // the entire point of a non-chargeable — so without this line
                  // the dish would just quietly not appear and neither the guest
                  // nor the waiter could tell a comp from a missing item.
                  if (_bn('nc_total') > 0)
                    billRow('Non-chargeable (given away)', _money(_bill!['nc_total'])),
                  if (_bn('discount') > 0)
                    billRow('Discount${_s(_bill!, 'discount_type') == 'percent' ? ' (${_bn('discount_value').toStringAsFixed(_bn('discount_value') % 1 == 0 ? 0 : 1)}%)' : ''}', '− ${_money(_bill!['discount'])}'),
                  // Only a charge that is charged. A removed one (a recorded
                  // waiver) shows no row at all — the client asked for exactly
                  // that ("don't show service charge opted out when removed").
                  // The manager's waiver card below still says who took it off,
                  // and is where it is put back.
                  if (_bn('service_charge') > 0) billRow('Service charge', _money(_bill!['service_charge'])),
                  if (_bn('tax_total') > 0) billRow('Tax', _money(_bill!['tax_total'])),
                  // What the server rounded the total to the rupee by (backend
                  // migration 048) — the line on the guest's paper, shown only
                  // when it is not zero. Read, never computed here.
                  if (billRoundOff(_bill!['round_off']) != null)
                    billRow('Round off', billRoundOffMoney(billRoundOff(_bill!['round_off'])!)),
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 8),
                    child: Divider(),
                  ),
                  Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
                    Expanded(child: Text('TOTAL PAYABLE', style: text.labelSmall)),
                    Text(_money(_bill!['grand_total'] ?? _bill!['total_amt']), style: text.displaySmall),
                  ]),
                  const SizedBox(height: 14),
                  Row(children: [
                    MicroStat(value: '${_bill!['covers'] ?? '—'}', label: 'covers'),
                    const SizedBox(width: 24),
                    MicroStat(value: _money(_bill!['apc']), label: 'apc'),
                    if ((_bill!['target_apc'] ?? 0) != 0) ...[
                      const SizedBox(width: 24),
                      MicroStat(value: _money(_bill!['target_apc']), label: 'target apc'),
                    ],
                  ]),
                ]),
              ),
              _apcInsight(),
              ],
              // NOT INSIDE EITHER GATE, AND THAT IS ON PURPOSE.
              //
              // GONE FOR A WAITER — see [FloorScope.managerOnlyAsks], which also
              // records what that costs. 1.8.6 shipped this visible-but-inert on
              // purpose so a waiter would fetch a manager rather than argue with
              // a guest about a screen with no such option; the V3 requirements
              // ask for it to be completely hidden, accompanying text included,
              // and that is the client's call to make.
              //
              // For everyone else it is unchanged, including the money scoping
              // inside it: the already-waived card prints what came off the
              // charge and charge + tax, and `showsMoney` still drops those two
              // lines while leaving the reason, the names and the reverse
              // control standing.
              if (_scope.managerOnlyAsks)
              misServiceChargeBlock(
                context,
                rest: widget.rest,
                profile: widget.profile,
                bill: _bill!,
                tableName: _name,
                showsMoney: _scope.money,
                onChanged: () async {
                  await _loadBill();
                  widget.reload();
                },
              ),
              const SizedBox(height: 14),
              Wrap(spacing: 8, runSpacing: 8, children: [
                // ITEM 18: merge, split, discount and coupon, plus the admin
                // refund that already sat beside them. Every one of them changes
                // or re-presents what the guest owes. The reprint without the
                // service charge that used to sit here is part of the waiver
                // block above now (client item 6): on its own it could not take
                // the charge off, and it was one of two steps that are one act.
                //
                // "Print bill" used to lead this list. 6.7 moved it, with the
                // same gate and the same preview-first handler, to the top of the
                // sheet beside "Add order" — see [_orderAndPrintActions].
                // Comping is a MANAGER act (migration 034's own permission), and
                // for a manager this is unchanged: dimmed and SAYING SO IN ITS
                // OWN LABEL when they lack the permission, because this button
                // sits in a wrap of eight where a separate sentence beside it
                // would read as belonging to the row rather than to the control.
                // Never an enabled button that 403s under a guest's nose.
                //
                // A WAITER NO LONGER SEES IT AT ALL — see
                // [FloorScope.managerOnlyAsks] for what that reverses and what
                // it costs. Note the gate is the ROLE and not the permission: a
                // tenant that granted its waiters the non-chargeable UUID would
                // otherwise get an ENABLED comp button, which is the one outcome
                // the requirement rules out however the grants are configured.
                //
                // The only thing scoped inside the label is the branch that IS a
                // figure: what has already been comped off this bill.
                if (_scope.managerOnlyAsks)
                ForkButton.ghost(
                  key: const ValueKey('table-comps'),
                  label: !_mayDo(widget.profile, Capability.compItem, _permNonChargeable)
                      ? 'Comp an item — manager only'
                      : _bn('nc_total') > 0 && _scope.money
                          ? 'Comps · ${_money(_bill!['nc_total'])}'
                          : 'Comp an item',
                  icon: Icons.card_giftcard,
                  dense: true,
                  onPressed: _mayDo(widget.profile, Capability.compItem, _permNonChargeable)
                      ? _comps
                      : null,
                ),
                if (_scope.billOps) ...[
                // 6.5's "Edit guest name" used to lead this wrap. Round 2 item 1
                // moved it, with the same gate, to the top of the sheet — see
                // [_billCustomerHeader].
                ForkButton.ghost(
                  label: _bn('discount') > 0 ? 'Edit discount' : 'Discount',
                  icon: Icons.percent,
                  dense: true,
                  onPressed: () => _setDiscount(messenger),
                ),
                ForkButton.ghost(
                  label: _s(_bill!, 'coupon_code').isNotEmpty ? 'Coupon: ${_s(_bill!, 'coupon_code')}' : 'Coupon',
                  icon: Icons.local_offer,
                  dense: true,
                  onPressed: () => _applyCoupon(messenger),
                ),
                ForkButton.ghost(
                  label: 'Split',
                  icon: Icons.call_split,
                  dense: true,
                  onPressed: () => _splitBill(messenger),
                ),
                ForkButton.ghost(
                  label: 'Merge',
                  icon: Icons.merge_type,
                  dense: true,
                  onPressed: () => _mergeBill(messenger),
                ),
                if (_isAdmin)
                  ForkButton.ghost(
                    label: 'Refund',
                    icon: Icons.undo,
                    dense: true,
                    onPressed: () => _refundBill(messenger),
                  ),
                ],
              ]),
              const SizedBox(height: 12),
              // ITEM 18 AGAIN, WEARING A DIFFERENT HAT. "Approve payment &
              // close" runs admin-approve-payment AND close — it settles the
              // bill and frees the table — so it goes where Settle went. It also
              // prints the amount and the guest's payment screenshot, which item
              // 19 would take off the screen anyway.
              if (_scope.settle && _bill!['payment_status'] == 'pending_approval')
                _paymentReview(messenger),
            ],
            // 6.7: a waiter's Add order / Print bill moved to the top of the
            // sheet, which leaves them nothing under this heading — so no heading.
            if (_scope.seat || _scope.editSeating) ...[
              const SizedBox(height: 20),
              const SectionHeader(title: 'Actions'),
            ],

            // ---- everyone else: the sheet exactly as it shipped -------------
            if (_scope.seat && !_occupied)
              // Scaled down rather than clipped: this sheet is now opened from a
              // phone-width floor plan, where a full-size label of this length
              // overflows its own button by ~20px.
              Center(
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  child: ForkButton(
                    label: 'Seat guests & take order',
                    icon: Icons.event_seat,
                    onPressed: () => _seat(messenger),
                  ),
                ),
              ),
            if (_scope.seat && _occupied) ...[
              // 6.7: "Add order" moved out of this row to the top of the sheet.
              Wrap(alignment: WrapAlignment.center, spacing: 10, runSpacing: 10, children: [
                if (_scope.settle)
                  ForkButton(
                    label: 'Settle bill',
                    icon: Icons.payments,
                    onPressed: () => _settle(messenger),
                  ),
              ]),
              // THE TWO MOVES — items 10/21 and 22. Side by side because they are
              // two answers to the same "this is on the wrong table", and
              // choosing between them IS the decision: Move table takes the
              // guests and everything of theirs; Move an order takes one ticket
              // and leaves the guests where they are.
              //
              // Gated with Merge and the rest of billOps, and for Merge's exact
              // reason: both of these carry a running bill from one table to
              // another, which is a change to what a guest owes and where it is
              // owed. A waiter who mis-keys a ticket asks the same person they
              // would ask to split or discount one.
              if (_scope.billOps) ...[
                const SizedBox(height: 10),
                Wrap(alignment: WrapAlignment.center, spacing: 10, runSpacing: 10, children: [
                  ForkButton.ghost(
                    label: 'Move table',
                    icon: Icons.swap_horiz,
                    onPressed: () => _moveTable(messenger),
                  ),
                  ForkButton.ghost(
                    label: 'Move an order',
                    icon: Icons.move_down,
                    onPressed: () => _moveKot(messenger),
                  ),
                ]),
              ],
              // ITEM 20. Freeing an occupied table without taking the money is a
              // write-off however it is labelled, and it is one tap with no
              // confirmation.
              if (_scope.release) ...[
                const SizedBox(height: 10),
                Center(
                  child: FittedBox(
                    fit: BoxFit.scaleDown,
                    child: ForkButton.ghost(
                      label: 'Release without payment',
                      icon: Icons.logout,
                      onPressed: () => _release(messenger),
                    ),
                  ),
                ),
              ],
            ],
            // ITEM 15 AND REQUIREMENT D5: editing the seat count is a change to
            // the SHAPE of the room (PATCH /table/:name {capacity,max_capacity}),
            // so it is a floor-plan act and [FloorScope.editSeating] is now false
            // on the service surface for everyone, not only for a waiter. Delete
            // used to sit directly below this and has gone to the Floor header —
            // see this class's own header.
            if (_scope.editSeating) ...[
              const SizedBox(height: 10),
              Center(
                child: ForkButton.ghost(
                  label: 'Edit seating',
                  icon: Icons.event_seat_outlined,
                  dense: true,
                  onPressed: () => _editSeating(messenger),
                ),
              ),
            ],
          ]),
        ),
      ),
    );
  }

  // Change the seat count and the MAX this table can take with extra chairs.
  // The max is what the seating suggester sizes parties against.
  Future<void> _editSeating(ScaffoldMessengerState messenger) async {
    final seats = await showDialog<_TableSeating>(
      context: context,
      builder: (_) => _TableSeatingDialog(existing: widget.table),
    );
    if (seats == null) return;
    try {
      final res = await widget.rest.patch('/table/${Uri.encodeComponent(_name)}', {
        'capacity': seats.capacity,
        'max_capacity': seats.maxCapacity,
      });
      // Keep the open sheet honest without waiting for the list to refetch.
      if (mounted) {
        setState(() {
          widget.table['capacity'] = res is Map ? (res['capacity'] ?? seats.capacity) : seats.capacity;
          widget.table['max_capacity'] =
              res is Map ? (res['max_capacity'] ?? seats.maxCapacity) : seats.maxCapacity;
        });
      }
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _seat(ScaffoldMessengerState messenger) async {
    // Read off the theme BEFORE any await - the outcome snackbar below is shown
    // after the occupy round-trip, and BuildContext must not cross that gap.
    final unattendedColour = Theme.of(context).colorScheme.error;
    final covers = await _askCovers(context);
    if (covers == null) return;
    try {
      final res = await widget.rest.post('/occupy-table', {'table_name': _name, 'num_covers': covers});
      // Seating is what makes the seater this table's waiter. Say whether it
      // actually happened: the reported failure was silent on BOTH ends — the
      // server skipped the assignment without logging and this screen never
      // asked — so a floor with no waiter on any table looked normal for weeks.
      final assignment = TableAssignmentOutcome.parse(res is Map ? res['assignment'] : null);
      if (assignment != null) {
        messenger.showSnackBar(SnackBar(
          content: Text('Seated $_name · ${assignment.message}'),
          backgroundColor: assignment.leftTableUnattended
              ? unattendedColour
              : null,
        ));
      }
      if (!mounted) return;
      Navigator.of(context).pop();
      await Navigator.of(context).push(
        MaterialPageRoute(builder: (_) => OrderEntryScreen(rest: widget.rest, tableName: _name)),
      );
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _addOrder() async {
    // ITEM 16. A reader with no seating control opening the pad on a FREE table
    // is the case "occupancy follows the order" describes: the send occupies it
    // (and records its covers), so nothing here has to be pressed first. For
    // everyone else this is false and the flow is the shipped one — they seat,
    // then order.
    final occupyOnSend = !_scope.seat && !_occupied;
    Navigator.of(context).pop();
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => OrderEntryScreen(
          rest: widget.rest,
          tableName: _name,
          occupyOnSend: occupyOnSend,
        ),
      ),
    );
    widget.reload();
  }

  /// REQUIREMENT 6.7: "ADD ORDER" AND "PRINT BILL", HIGHER UP AND BIGGER.
  ///
  /// These are the two things anyone opens a table's sheet to do while the
  /// party is ordering, and they used to sit under the Actions heading at the
  /// very bottom — below every order line, the bill card and the bill controls —
  /// so on a busy table they were a scroll away. They now lead the sheet,
  /// directly under the table's name and chips, full width and at
  /// [kForkButtonLargeHeight].
  ///
  /// ONLY THE PLACE AND THE SIZE CHANGED. Each button keeps the gate and the
  /// handler it had where it came from: a waiter's print is still the direct
  /// one with requirement C3's one-print rule; a manager's is still the
  /// preview-first one gated by [FloorScope.billOps]; both open [_addOrder].
  List<Widget> _orderAndPrintActions(ScaffoldMessengerState messenger, TextTheme text) {
    Widget full(Widget child) => SizedBox(width: double.infinity, child: child);
    return [
      // ---- ITEM 17: THE TWO CONTROLS A WAITER CAME HERE FOR ----------
      //
      // This is the busiest screen in the app, and for a waiter it now
      // opens on the two things they do at a table: take the order, and
      // print the bill. Full width, full size, first — where the QR block
      // used to be. Everything a waiter has lost from this sheet (the QR,
      // the assign-waiter row, the bill card, the eight bill controls, the
      // seat/settle/release/edit/delete row) is what makes room for them.
      //
      // ADD ORDER SHOWS WHETHER OR NOT THE TABLE IS OCCUPIED — item 16.
      // A waiter has no "seat guests" button any more, so placing the
      // order is how a table starts. POST /orders provisions the seating
      // server-side; nothing here has to be pressed first.
      if (!_scope.seat) ...[
        full(ForkButton(
          key: const ValueKey('table-add-order'),
          label: 'Add order',
          icon: Icons.add,
          large: true,
          onPressed: _addOrder,
        )),
        // Nothing to print until something has been ordered — an empty
        // table has no bill, and a button that answers "No open bill to
        // print for this table" is a button that wasted a walk.
        //
        // REQUIREMENT C3: AND NOTHING TO PRINT A SECOND TIME. Once this
        // waiter has printed, the control is gone and a sentence stands
        // where it was. The sentence is not decoration — a waiter handed a
        // blank space where a button was will go and press it on the next
        // tablet, and a guest asking for their bill again needs to hear
        // what happens next rather than watch somebody prod a dead screen.
        if (_occupied) ...[
          const SizedBox(height: 10),
          if (_printScope.print)
            full(ForkButton.ghost(
              key: const ValueKey('table-print-bill'),
              label: 'Print bill',
              icon: Icons.receipt_long,
              large: true,
              onPressed: () => _printBillWithoutPreview(messenger),
            ))
          else
            ForkCard(
              key: const ValueKey('table-print-spent'),
              inset: true,
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              child: Row(children: [
                Icon(Icons.receipt_long_outlined, size: 16, color: AppColors.textSecondary),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    'Bill printed. A manager reprints it and settles the table '
                    'from here — ask one if the guest needs another copy.',
                    style: text.bodySmall,
                  ),
                ),
              ]),
            ),
        ],
        const SizedBox(height: 16),
      ],
      // ---- everyone else: the same two controls, same gates as shipped ----
      //
      // "Add order" came out of the Settle row (occupied tables only — a free
      // table is still seated first). "Print bill" came out of the bill-ops
      // wrap and still previews the receipt first, then prints via the server
      // (unified ESC/POS format → thermal printer agent), matching the web bill.
      if (_scope.seat && _occupied) ...[
        full(ForkButton(
          key: const ValueKey('table-manager-add-order'),
          label: 'Add order',
          icon: Icons.add,
          large: true,
          onPressed: _addOrder,
        )),
        if (_bill != null && _scope.billOps) ...[
          const SizedBox(height: 10),
          full(ForkButton.ghost(
            key: const ValueKey('table-manager-print-bill'),
            label: 'Print bill',
            icon: Icons.receipt_long,
            large: true,
            onPressed: () => _previewBill(messenger),
          )),
        ],
        const SizedBox(height: 16),
      ],
    ];
  }

  Future<void> _settle(ScaffoldMessengerState messenger) async {
    final orderIds = (_bill?['order_ids'] as List?) ?? [];
    if (orderIds.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('No orders to settle on this table.')));
      return;
    }
    final done = await showDialog<bool>(
      context: context,
      builder: (_) => _PaymentSheet(
        rest: widget.rest,
        profile: widget.profile,
        orderId: '${orderIds.first}',
        tableName: _name,
        fallbackTotal: _money(_bill?['grand_total'] ?? _bill?['total_amt']),
      ),
    );
    if (done == true) _popAndReload();
  }

  /// Comp a dish off this table's bill (migration 034).
  ///
  /// It works off the table's ORDERS, not off the merged bill lines above:
  /// the comp route addresses one line of one order and `/bill-for-table`
  /// deliberately merges lines for printing, so the ids simply are not there.
  Future<void> _comps() async {
    await misOpenComps(
      context,
      rest: widget.rest,
      profile: widget.profile,
      tableName: _name,
      orderIds: [for (final id in (_bill?['order_ids'] as List?) ?? const []) '$id'],
    );
    // The bill total changes when a line comes off it, so re-read rather than
    // leave the sheet showing what the guest owed a minute ago.
    await _loadBill();
    widget.reload();
  }

  Future<void> _release(ScaffoldMessengerState messenger) async {
    try {
      await widget.rest.post('/release-table', {'table_name': _name});
      _popAndReload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

}

/// The bill logo as PNG bytes off a `{logo_base64}` response — the shape both
/// GET /restaurant/logo/bill and GET /restaurant/logo answer with — or null when
/// there is none or it is not base64. Tolerates a `data:` URL prefix.
///
/// The `width` / `height` /restaurant/logo/bill sends beside it are the raster's
/// size in printer dots, which the PNG's own header already carries, so they
/// are not read here: [_BillPreviewDialog] draws those pixels as dots, at the
/// paper's scale and never enlarged.
@visibleForTesting
Uint8List? billLogoBytes(dynamic response) {
  if (response is! Map) return null;
  var b64 = '${response['logo_base64'] ?? ''}'.trim();
  final comma = b64.startsWith('data:') ? b64.indexOf(',') : -1;
  if (comma >= 0) b64 = b64.substring(comma + 1);
  if (b64.isEmpty) return null;
  try {
    final bytes = base64Decode(b64);
    return bytes.isEmpty ? null : bytes;
  } catch (_) {
    return null;
  }
}

/// What the bill preview reads off GET /restaurant/settings and GET
/// /restaurant/profile besides the bill itself: the identity lines under the
/// name, which roll the paper is cut from, the sentence above the QR (the
/// tenant's own and the server's default), and whether the QR block prints at
/// all. See [_BillPreviewDialog].
typedef _BillPaper = ({List<String> headerLines, bool narrow, String qrNote, String qrNoteDefault, bool showQr});

/// DOES THE CUSTOMER BILL CARRY THE FEEDBACK / VALET QR — the owner's
/// `bill_show_qr` switch (migration 047), read off a GET /restaurant/settings
/// answer. Both the Settings card and the bill preview read it through here, so
/// the two can never disagree about a tenant.
///
/// DEFAULT ON, AND A MISSING KEY READS AS ON. The column is NULL for every
/// restaurant that predates the migration, GetRestaurantSettings maps NULL to
/// true, and an older backend that has never heard of the key omits it. So this
/// is `!= false`, never `== true`: the two differ for precisely the tenants who
/// have never been asked the question, and those tenants' paper has always
/// carried the QR. routes/bills.ts gates the print the same way.
@visibleForTesting
bool billShowsQr(Map settings) => settings['bill_show_qr'] != false;

/// The POST /restaurant/settings body the "Bill details" card saves.
///
/// EVERY KEY IS SENT, EMPTY OR NOT. '' is how a text field is CLEARED (clearing
/// the note restores the built-in valet line), and the backend presence-checks
/// rather than truthiness-checks for exactly this reason. `bill_show_qr` is
/// always an explicit boolean because only a boolean writes — anything else is
/// read as "not in this request" and leaves the stored switch alone.
///
/// The note is sent even while the QR is off. It is not printed then, but it is
/// the owner's sentence and turning the QR back on should bring it back, not a
/// blank that silently fell back to the default.
@visibleForTesting
Map<String, dynamic> billDetailsSettingsBody({
  required String legalName,
  required String gstin,
  required String qrNote,
  required bool showQr,
}) =>
    {
      'bill_legal_name': legalName.trim(),
      'bill_gstin': gstin.trim(),
      'bill_qr_note': qrNote.trim(),
      'bill_show_qr': showQr,
    };

/// The sentence the paper prints straight under the grand total whenever the
/// guest is being charged for service — routes/bills.ts's `serviceChargeNote`,
/// word for word, which is also the sentence the web print page carries. The
/// SERVER owns the wording and decides when it prints; this copy exists only so
/// the preview shows the footer the paper will, and changes when that one does.
const String billServiceChargeNote =
    'A Voluntary Service Charge is included to support our staff. If you prefer '
    'not to contribute, please inform your server before payment and it will be removed.';

/// The line above the QR when the tenant has set none and the settings read
/// carried no `bill_qr_note_default` either — escpos.ts `DEFAULT_BILL_QR_NOTE`.
const String _billQrNoteFallback = 'For calling Valet kindly scan the below QR code';

/// DOES THIS OPEN BILL CHARGE THE GUEST FOR SERVICE — in EITHER shape? The
/// paper's disclaimer hangs off exactly that (routes/bills.ts hands escpos.ts
/// `serviceChargeNote` iff `service_charge_applied`), and so does the preview's.
///
/// Asking only about `service_charge` would repeat F2's root cause 3 on this
/// screen: a tenant carrying the charge as a line in Outlets.default_tax has
/// `service_charge` = 0 while the guest is charged, because the charge arrives
/// among `taxes`. The name test is SERVICE_CHARGE_NAME in billing_math.ts — the
/// one matcher the server bills by — and this is the same predicate as the web
/// print page's `billChargesForService`. A live waiver took the charge off both
/// legs before this bill was computed, so a waived bill never carries the
/// sentence — and, like its paper, shows no service-charge line either.
@visibleForTesting
bool billPrintsServiceChargeNote(Map bill) {
  if (bill['service_charge_waived'] == true) return false;
  if (_numOf(bill['service_charge']) > 0) return true;
  final serviceLine = RegExp(r'service\s*charge', caseSensitive: false);
  return ((bill['taxes'] as List?) ?? const []).any(
      (t) => t is Map && serviceLine.hasMatch('${t['name'] ?? ''}') && _numOf(t['amount']) > 0);
}

/// Receipt-style preview of a table's bill, shown before it is sent to the
/// thermal printer. Renders the same data web/Flutter already display
/// (/bill-for-table). Returns `true` from the dialog when the user taps Print.
///
/// THIS DIALOG DOES NO MONEY ARITHMETIC. It renders the ladder the billing layer
/// computed, rung for rung, exactly as the thermal renderer does with a supplied
/// `grandTotal` (escpos.ts: "the renderer's job is to show the number the guest
/// is actually charged, and a second rounding in the renderer is how a printed
/// total comes to disagree with the settled one"). A second implementation of
/// the totals ladder, in a second language, is how the paper and the till come
/// to disagree — and this one already had. See [build].
///
/// IT IS LAID OUT THE WAY THE PAPER IS, block for block (escpos.ts, kind
/// "bill"), because the client's own printed bill is the reference both follow:
/// the logo at two thirds of the roll; the name bold at body size over the legal
/// name, address, phone and GSTIN; a solid rule; the `Name:` slot; Date with the
/// table in bold, then Cashier on the left and Bill No. on the right; a HEAVY
/// rule either side of the Item / Qty. / Price / Amount table; the ladder
/// right-aligned on the Amount column; Round off and a larger bold Grand Total
/// between thin rules; then the disclaimer in bold and the QR. The paper's white
/// margins are kept too — the text sits inside the roll's edges, not against the
/// edge of the sheet.
///
/// Layout still does the aligning, in the app's proportional type: the columns
/// are the renderer's column COUNTS turned into shares of the text area, so a
/// figure sits under the heading it belongs to on every platform without a
/// monospace font.
class _BillPreviewDialog extends StatelessWidget {
  final Map bill;
  final String restaurantName;
  // Legal entity / address / phone / GSTIN, already resolved and already
  // filtered to the ones this tenant has. Empty for a tenant that has set none,
  // in which case the header is just the trading name — same as before these
  // fields existed.
  final List<String> headerLines;

  /// The bill logo as PNG bytes, or null when the tenant has none. See
  /// [billLogoBytes].
  final Uint8List? logo;
  final String tableName;

  /// ROUND 2 ITEM 4 — "Reprint has to mention reprint on top once the bill has
  /// been reprinted and it should show the same on the preview as well."
  ///
  /// True when this bill has ALREADY been printed at least once, so the print
  /// this preview leads to is a reprint — the thermal renderer stamps REPRINT at
  /// the very top of exactly that print, and a preview that did not would be
  /// previewing a different slip. False for a first print, which carries no
  /// banner on paper or here.
  final bool reprint;

  /// True when the tenant prints on the 58mm roll (`bill_paper_width`): 32
  /// columns, no margins, the narrow item table. False is the 80mm roll, which
  /// is also what an unreadable setting means on the server.
  final bool narrow;

  /// The sentence above the QR — the tenant's own, or the server's default.
  /// Empty falls back to [_billQrNoteFallback], as escpos.ts does.
  final String qrNote;

  /// Whether the paper ends with the QR block — the sentence, the code, and
  /// the rule that separates them from the disclaimer. False when the owner has
  /// switched the QR off ([billShowsQr]): /print/bill then hands escpos.ts no
  /// feedback URL, and the renderer prints that whole block only when it has
  /// one. True is the default paper.
  final bool showQr;

  /// Who the paper names as the cashier. Empty prints no "Cashier:" label, the
  /// same rule the renderer obeys for an unknown one.
  final String cashier;

  /// The restaurant wall clock the "Date:" line shows; null means now.
  final DateTime? printedAt;

  const _BillPreviewDialog({
    required this.bill,
    required this.restaurantName,
    this.headerLines = const <String>[],
    this.logo,
    required this.tableName,
    this.reprint = false,
    this.narrow = false,
    this.qrNote = '',
    this.showQr = true,
    this.cashier = '',
    this.printedAt,
  });

  static double _n(dynamic v) => (v is num) ? v.toDouble() : (double.tryParse('${v ?? ''}') ?? 0);

  /// A percentage as the renderer's template literal prints it: "10", "2.5".
  static String _pct(double p) => p % 1 == 0 ? '${p.toInt()}' : '$p';

  // ------------------------------------------------------------ the geometry

  /// Printer dots per Font A column — escpos.ts `DOTS_PER_COL` (576 / 48).
  static const int _dotsPerCol = 12;

  /// Font A columns across the bill's text area — escpos.ts `W`: the 80mm
  /// roll's 48 less `billMarginCols`' 2 either side, the 58mm roll's 32 with
  /// none.
  int get _cols => narrow ? 32 : 44;

  /// escpos.ts `billColumns(W)` — Item, Qty., Price, Amount — summing to
  /// [_cols]. The totals ladder right-aligns on the same Amount column.
  ({int item, int qty, int price, int amount}) get _table =>
      narrow ? (item: 11, qty: 4, price: 8, amount: 9) : (item: 20, qty: 5, price: 9, amount: 10);

  /// The white either side of the text, as a share of the paper's width. An
  /// 80mm roll prints 72mm (576 dots) and the bill keeps 2 columns (3mm) more
  /// inside that each side: 7mm of 80. A 58mm roll prints 48mm and keeps no
  /// margin: 5mm of 58.
  double get _edgeShare => narrow ? 5 / 58 : 7 / 80;

  /// The roll's dots across (bill_logo.ts `BILL_LOGO_DOTS`).
  int get _rollDots => narrow ? 384 : 576;

  // ------------------------------------------------------------------ the ink

  static const double _body = 12.5;
  static const Color _inkColor = Colors.black87;
  static const TextStyle _ink = TextStyle(fontSize: _body, height: 1.3, color: _inkColor);

  /// Figures in even widths, so a column of amounts lines up digit for digit
  /// the way the printer's fixed-pitch font lines them up.
  static const TextStyle _figures = TextStyle(
      fontSize: _body, height: 1.3, color: _inkColor, fontFeatures: [FontFeature.tabularFigures()]);

  /// A SOLID RULE, as the paper now draws its separators (escpos.ts `billRule`):
  /// a thin stroke between blocks and one twice as heavy either side of the item
  /// table, full ink, across the text area and not into the margins. Never the
  /// theme's divider — that is white-on-dark and would vanish on paper.
  static Widget _rule({bool thick = false}) => Container(
        margin: const EdgeInsets.symmetric(vertical: 6),
        height: thick ? 2.4 : 1.2,
        color: _inkColor,
      );

  /// A left run and a right run on one line, the right one flush with the text
  /// area's edge — escpos.ts `twoCol`. [boldRight] is the paper's `ESC E` on
  /// the right-hand run only (the table on the Date row).
  static Widget _twoCol(String left, String right, {bool boldRight = false}) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 1),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Flexible(child: Text(left)),
            const SizedBox(width: 8),
            Flexible(
              child: Text(right,
                  textAlign: TextAlign.right,
                  style: boldRight ? const TextStyle(fontWeight: FontWeight.bold) : null),
            ),
          ],
        ),
      );

  /// A figure in its column, right-aligned. Scaled down rather than wrapped
  /// when a five-figure amount is wider than its share of a narrow sheet: a
  /// figure broken across two lines is a different figure.
  static Widget _figure(String s, [TextStyle style = _figures]) => FittedBox(
        fit: BoxFit.scaleDown,
        alignment: Alignment.centerRight,
        child: Text(s, maxLines: 1, style: style),
      );

  /// One line of the item table — the heading or a dish. The name wraps inside
  /// its column with a column of gutter before Qty., as `wrapText(…, COL_ITEM
  /// - 1)` wraps it on the paper, and its continuation lines stay under it.
  Widget _itemRow(double col, String item, String qty, String price, String amount) {
    final t = _table;
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 1),
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Expanded(flex: t.item, child: Padding(padding: EdgeInsets.only(right: col), child: Text(item))),
        Expanded(flex: t.qty, child: _figure(qty)),
        Expanded(flex: t.price, child: _figure(price)),
        Expanded(flex: t.amount, child: _figure(amount)),
      ]),
    );
  }

  /// One rung of the totals ladder, as escpos.ts `ladder` lays it out: the label
  /// RIGHT-ALIGNED against the Amount column, the figure right-aligned inside
  /// that column under the line amounts it sums. The figure's cell grows past
  /// the column (with a column of space before it) when the figure is wider, as
  /// `max(AMT, value.length + 1)` does on the paper. Several [labels] share the
  /// label cell a few columns apart — "Total Qty: 19   Sub Total".
  Widget _ladder(double col, List<String> labels, String value, {TextStyle? style}) {
    final s = style ?? _ink;
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 1),
      child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
        Expanded(
          child: labels.length == 1
              ? Text(labels.single, textAlign: TextAlign.right, style: s)
              : Wrap(
                  alignment: WrapAlignment.end,
                  spacing: 3 * col,
                  children: [for (final l in labels) Text(l, style: s)],
                ),
        ),
        Container(
          constraints: BoxConstraints(minWidth: _table.amount * col),
          padding: EdgeInsets.only(left: col),
          alignment: Alignment.centerRight,
          child: Text(value, maxLines: 1, style: s.merge(const TextStyle(fontFeatures: [FontFeature.tabularFigures()]))),
        ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    // PAPER ARTIFACT: the receipt body deliberately stays white with black
    // ink — it mirrors what the thermal printer produces. Only the dialog
    // chrome around it is dark.
    final items = (bill['items'] as List?) ?? const [];
    // EVERY RUNG BELOW IS THE SERVER'S NUMBER, RENDERED VERBATIM. Nothing here
    // is derived, re-based or re-rounded.
    //
    // WHAT THIS USED TO DO, AND WHY IT WAS THE F2 BUG WRITTEN A SECOND TIME. For
    // a "reprint without service charge" the dialog rebuilt the ladder itself:
    // it zeroed `service_charge` — the restaurant_percent leg — and then
    // recomputed every tax line at its own percentage on the smaller base. On a
    // tenant carrying the charge as a LINE IN Outlets.default_tax (the tax_line
    // shape, which is the shipped seed and therefore most tenants) that charge
    // IS one of the tax lines, so it was faithfully recomputed and kept, and the
    // "without" preview came out to the same paisa as the "with" one. Once the
    // server math was fixed the paper showed less than this sheet did — a
    // receipt-shaped artifact, routinely turned toward a guest, contradicting
    // the slip it claims to preview.
    //
    // THE CHARGE COMING OFF IS THE SERVER'S ANSWER NOW, IN BOTH SHAPES: a
    // recorded service-charge waiver (migration 036), which openBillChargeConfig
    // applies to this very read, to the print and to settle alike — so screen,
    // paper and drawer are one number, and the bill can say who allowed it.
    final subtotal = _n(bill['subtotal'] ?? bill['total_amt']);
    final discount = _n(bill['discount']);
    final serviceCharge = _n(bill['service_charge']);
    // Only the lines that carry money, as escpos.ts filters `taxLines`.
    final taxes = ((bill['taxes'] as List?) ?? const []).whereType<Map>().where((t) => _n(t['amount']) > 0).toList();
    final grandTotal = _n(bill['grand_total'] ?? bill['total_amt']);
    // The round-off the billing layer DISCLOSED (backend migration 048: every
    // bill is rounded to the rupee in computeBillCharges), printed only when it
    // is not zero — the renderer's rule for a supplied grand total. Read off the
    // same payload as the total; nothing is re-rounded here.
    final roundOff = billRoundOff(bill['round_off']);
    final billNo = _s(bill, 'bill_no', '');
    // The customer slot — `Name:` / `Customer GSTIN:`.
    final customerLines = billCustomerLines(bill);
    // The label the paper gives the charge line: the configured percentage. It
    // labels a charge that is charged and nothing else — a removed charge has
    // no line to label. A label, never a figure.
    final scPct = _n(bill['service_charge_percent']);
    final scLabel = scPct > 0 ? 'Service Charge ${_pct(scPct)}%' : 'Service Charge';
    // Quantities as the paper counts them (a whole number, at least one a line).
    // A count of dishes, not money.
    final totalQty = items.fold<int>(0, (s, it) => s + math.max(1, _n((it as Map)['quantity'] ?? 1).round()));
    final subText = subtotal.toStringAsFixed(2);
    final stamp = printedAt ?? RestaurantTime.nowWall();
    String two(int v) => v.toString().padLeft(2, '0');
    final date = '${two(stamp.day)}/${two(stamp.month)}/${stamp.year} ${two(stamp.hour)}:${two(stamp.minute)}';
    final chargesService = billPrintsServiceChargeNote(bill);
    final note = qrNote.trim().isEmpty ? _billQrNoteFallback : qrNote.trim();
    // What the comped lines were worth, disclosed under the total exactly as
    // escpos.ts discloses it — never a rung of the ladder. Null with no comp.
    final ncValue = NcSettle.paperNcValue(items);

    return Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        width: 400,
        constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(context).height * 0.85),
        padding: const EdgeInsets.all(18),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.borderStrong),
        ),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          const SectionHeader(title: 'Bill preview'),
          Flexible(
            child: LayoutBuilder(builder: (context, box) {
              // The sheet is the roll; the text area is the roll less its white
              // edges. `col` is one Font A column of that area in pixels, and
              // `dotsPerPx` turns the printer's dots into this sheet's pixels —
              // never below 1, so nothing is ever drawn larger than it arrived.
              final edge = box.maxWidth * _edgeShare;
              final area = math.max(1.0, box.maxWidth - 2 * edge);
              final col = area / _cols;
              final dotsPerPx = math.max(1.0, _cols * _dotsPerCol / area);
              return Container(
                decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(10)),
                padding: EdgeInsets.fromLTRB(edge, 14, edge, 18),
                child: SingleChildScrollView(
                  child: DefaultTextStyle(
                    style: _ink,
                    child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                      // ROUND 2 ITEM 4 — REPRINT, above everything including the
                      // logo, because that is where the roll prints it. Large, bold
                      // and boxed so it cannot be read past on a copy turned toward
                      // a guest.
                      if (reprint) ...[
                        Container(
                          key: const ValueKey('bill-preview-reprint'),
                          padding: const EdgeInsets.symmetric(vertical: 4),
                          decoration: BoxDecoration(border: Border.all(color: Colors.black87, width: 2)),
                          child: const Text('REPRINT',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                  fontSize: 24, fontWeight: FontWeight.w900, letterSpacing: 4, color: Colors.black)),
                        ),
                        const SizedBox(height: 8),
                      ],
                      // 5.1 — the logo across the top, where the roll prints it,
                      // at the size the roll prints it. GET /restaurant/logo/bill
                      // answers with the raster the printer receives, already
                      // fitted inside two thirds of the roll and 240 dots tall
                      // (bill_logo.ts), so its pixels ARE dots: `scale` draws one
                      // dot as 1/dotsPerPx of a pixel and the logo takes the same
                      // share of this sheet it takes of the paper. The same box
                      // fits the branding-PNG fallback, which arrives unfitted,
                      // the way the roll would fit it. Contained and never
                      // enlarged — a one-bit raster blown up is a blur.
                      if (logo != null) ...[
                        Center(
                          child: ConstrainedBox(
                            constraints: BoxConstraints(
                              maxWidth: math.min(area, _rollDots * 2 / 3 / dotsPerPx),
                              maxHeight: 240 / dotsPerPx,
                            ),
                            child: Image.memory(
                              logo!,
                              key: const ValueKey('bill-preview-logo'),
                              scale: dotsPerPx,
                              fit: BoxFit.contain,
                              gaplessPlayback: true,
                              // A logo that will not decode is left off, not drawn
                              // as a broken-image box on a paper-styled preview.
                              errorBuilder: (_, _, _) => const SizedBox.shrink(),
                            ),
                          ),
                        ),
                        // The blank line the renderer feeds after the raster.
                        const SizedBox(height: _body * 1.3),
                      ],
                      // The restaurant name, BOLD AT BODY SIZE — the size of the
                      // address under it, as the paper now prints it, and not the
                      // headline it used to be over a logo that already names the
                      // restaurant.
                      Text(restaurantName,
                          textAlign: TextAlign.center,
                          style: const TextStyle(fontSize: _body, fontWeight: FontWeight.bold, color: _inkColor)),
                      // Registered entity, address, phone, GSTIN — only the ones
                      // set. 5.1: in full ink at body size, centred like the name.
                      // They were 11px black54 once — the faintest type on the
                      // sheet, for the lines the requirement names as the ones that
                      // must be clearly visible.
                      for (final l in headerLines)
                        Text(l, textAlign: TextAlign.center, style: const TextStyle(fontSize: _body, color: _inkColor)),
                      _rule(),
                      // ROUND 2 ITEM 1 — THE CUSTOMER SLOT, where the client's real
                      // bill has it: its own ruled-off block straight under the
                      // restaurant header and above the date / cashier block.
                      // "Name: <name>", or a bare "Name:" for a walk-in exactly as
                      // the paper leaves the slot blank; "Customer GSTIN:" only
                      // when set. See [billCustomerLines].
                      for (final l in customerLines)
                        Text(l,
                            key: ValueKey('bill-preview-customer-${l.startsWith('Customer GSTIN') ? 'gstin' : 'name'}'),
                            style: _ink),
                      _rule(),
                      // The date and the table on one line, the table in bold —
                      // it is what a server matches the slip to. Then Cashier on
                      // the left and Bill No. on the right, the client's order;
                      // either alone prints alone, and neither prints a bare label.
                      _twoCol('Date: $date', 'Dine In: ${tableName.isEmpty ? 'N/A' : tableName}', boldRight: true),
                      if (cashier.isNotEmpty && billNo.isNotEmpty)
                        _twoCol('Cashier: $cashier', 'Bill No.: $billNo')
                      else if (billNo.isNotEmpty)
                        Text('Bill No.: $billNo')
                      else if (cashier.isNotEmpty)
                        Text('Cashier: $cashier'),
                      _rule(thick: true),
                      // The item table between its two heavy rules.
                      //
                      // THE KITCHEN NOTE IS NOT DRAWN HERE, and this dialog is the
                      // reason the rule needs restating on the client at all.
                      //
                      // The thermal renderer stopped printing it on the bill in
                      // 1.9.0 (escpos.ts, the block in its bill item loop): a note
                      // is an instruction to the chef — "no salt", "allergy:
                      // peanuts" — and on a guest's copy it is at best noise on a
                      // tax document and at worst a medical detail handed across a
                      // table. This sheet is the LAST THING SOMEONE SEES BEFORE
                      // TAPPING PRINT, is styled as paper on purpose, and is
                      // routinely turned toward the guest to confirm the total. It
                      // showing a line the slip does not is the same disclosure
                      // through a different surface, plus a preview that lies
                      // about what is about to come out.
                      //
                      // The note is NOT lost: it still prints on the kitchen
                      // docket, and the waiter's running-bill sheet
                      // (widgets/table_bill.dart) still shows it, because there
                      // the reader is staff and the allergy is the point.
                      _itemRow(col, 'Item', 'Qty.', 'Price', 'Amount'),
                      _rule(thick: true),
                      ...items.map((it) {
                        final m = it as Map;
                        final qty = _n(m['quantity'] ?? 1);
                        final price = _n(m['price']);
                        // The price point rides with the dish, as escpos.ts
                        // `itemLabel` prints it: "Paneer Tikka (Half)".
                        final variation = '${m['variation'] ?? ''}'.trim();
                        final name = _s(m, 'name');
                        // A COMPED LINE (migration 034) reads "<dish> (NC)" at
                        // 0.00, as the paper prints it, so the Amount column
                        // adds up to the Sub Total under it.
                        return _itemRow(
                          col,
                          NcSettle.lineLabel(variation.isEmpty ? name : '$name ($variation)', m['nc']),
                          '${qty % 1 == 0 ? qty.toInt() : qty}',
                          price.toStringAsFixed(2),
                          NcSettle.lineAmount(price, qty, m['nc']).toStringAsFixed(2),
                        );
                      }),
                      _rule(thick: true),
                      // THE LADDER, in the right-hand block. "Total Qty: N   Sub
                      // Total" is one rung when it fits the text area and two on
                      // the 58mm roll, by the paper's own test.
                      if ('Total Qty: $totalQty   Sub Total'.length <= _cols - math.max(_table.amount, subText.length + 1))
                        _ladder(col, ['Total Qty: $totalQty', 'Sub Total'], subText)
                      else ...[
                        _ladder(col, ['Total Qty: $totalQty'], ''),
                        _ladder(col, ['Sub Total'], subText),
                      ],
                      if (discount > 0)
                        _ladder(col, [_s(bill, 'coupon_code', '').trim().isEmpty ? 'Discount' : 'Coupon ${_s(bill, 'coupon_code')}'],
                            '-${discount.toStringAsFixed(2)}'),
                      // A charge only when one is charged. A waived bill prints
                      // no service-charge line — escpos.ts prints none either
                      // since the client asked for a removed charge not to be
                      // shown on the bill.
                      if (serviceCharge > 0) _ladder(col, [scLabel], serviceCharge.toStringAsFixed(2)),
                      ...taxes.map((m) {
                        final pct = _n(m['percentage']);
                        final label = pct > 0 ? '${_s(m, 'name', 'Tax')} ${_pct(pct)}%' : _s(m, 'name', 'Tax');
                        return _ladder(col, [label], _n(m['amount']).toStringAsFixed(2));
                      }),
                      _rule(),
                      if (roundOff != null) _ladder(col, ['Round off'], billRoundOffPaper(roundOff)),
                      // The one figure bigger than the rest: bold and tall, as the
                      // paper's double-height Grand Total row is.
                      _ladder(col, ['Grand Total'], _money(grandTotal),
                          style: const TextStyle(fontSize: 17, height: 1.25, fontWeight: FontWeight.w800, color: Colors.black)),
                      _rule(),
                      // Beside the ladder, never in it — escpos.ts's order.
                      if (ncValue != null) ...[
                        KeyedSubtree(
                          key: const ValueKey('bill-preview-nc-value'),
                          child: _ladder(col, ['NC value (not charged)'], ncValue.toStringAsFixed(2)),
                        ),
                        _rule(),
                      ],
                      // THE FOOTER. The disclaimer first, bold, straight under the
                      // total it is about — a guest reads it before deciding what
                      // to pay — and only when the guest is being charged for
                      // service ([billPrintsServiceChargeNote]).
                      if (chargesService)
                        Text(billServiceChargeNote,
                            key: const ValueKey('bill-preview-service-charge-note'),
                            textAlign: TextAlign.center,
                            style: const TextStyle(fontSize: _body, fontWeight: FontWeight.bold, color: _inkColor)),
                      // Then the QR, under the tenant's sentence. A STAND-IN, not
                      // a code: the link is minted by the server at print time
                      // (feedbackUrlForTable — the table's waiter and outlet), and
                      // a scannable square drawn from a guess is a square a guest
                      // could scan. The old "Thanks" line is gone from the paper,
                      // so it is gone from here.
                      //
                      // ALL OF IT, OR NONE OF IT. With the owner's QR switch off
                      // the paper has no sentence, no code, and no rule between
                      // them and the disclaimer either — escpos.ts draws that rule
                      // inside the same `if (opts.feedbackUrl)` — so the sheet ends
                      // exactly where the roll is cut.
                      if (showQr) ...[
                        if (chargesService) _rule(),
                        Text(note, key: const ValueKey('bill-preview-qr-note'), textAlign: TextAlign.center),
                        const SizedBox(height: 6),
                        Center(
                          child: Container(
                            key: const ValueKey('bill-preview-qr'),
                            width: 92,
                            height: 92,
                            decoration: BoxDecoration(border: Border.all(color: Colors.black26)),
                            child: const Icon(Icons.qr_code_2, size: 64, color: Colors.black38),
                          ),
                        ),
                      ],
                    ]),
                  ),
                ),
              );
            }),
          ),
          const SizedBox(height: 14),
          Row(mainAxisAlignment: MainAxisAlignment.end, children: [
            ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(context, false)),
            const SizedBox(width: 8),
            ForkButton(
              label: 'Print',
              icon: Icons.print,
              onPressed: () => Navigator.pop(context, true),
            ),
          ]),
        ]),
      ),
    );
  }
}

Future<bool> _confirm(BuildContext context, String title, String message) async {
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: Text(title),
      content: Text(message),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Confirm')),
      ],
    ),
  );
  return ok == true;
}

// [initial] pre-fills the field (a rename should open on the current name);
// callers that omit it get the same empty box as before.
Future<String?> _askText(BuildContext context, String title, String label, {String initial = ''}) async {
  final ctrl = TextEditingController(text: initial);
  final result = await showDialog<String>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: Text(title),
      content: TextField(
        controller: ctrl,
        autofocus: true,
        decoration: InputDecoration(labelText: label),
        onSubmitted: (v) => Navigator.pop(ctx, v),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(ctx, ctrl.text), child: const Text('Save')),
      ],
    ),
  );
  ctrl.dispose();
  return result;
}

/// Add/edit a single menu item: name, price, and a category (existing or new).
class _MenuItemDialog extends StatefulWidget {
  final Map? existing;
  final List<String> categories;
  final List<String> sections;
  final RestClient rest;
  const _MenuItemDialog({this.existing, required this.categories, required this.sections, required this.rest});

  @override
  State<_MenuItemDialog> createState() => _MenuItemDialogState();
}

class _MenuItemDialogState extends State<_MenuItemDialog> {
  late final TextEditingController _name;
  late final TextEditingController _price;
  late final TextEditingController _blurb;
  late final TextEditingController _newCat;
  String? _category;
  bool _addingNewCat = false;
  String? _imageUrl;
  bool _uploading = false;
  bool _available = true;
  String _station = ''; // '' = unassigned (KOT routing section)
  late List<Map<String, dynamic>> _modifiers;
  late List<Map<String, dynamic>> _recipe;
  List _inventory = const [];

  static const _newCatSentinel = '+ New category';
  // Same hard cap the backend's sanitizeMenuBlurb() enforces, so the counter in
  // this field is the truth and nothing is silently trimmed on save.
  static const _blurbMax = 500;

  @override
  void initState() {
    super.initState();
    _name = TextEditingController(text: _s(widget.existing ?? const {}, 'name', ''));
    final p = widget.existing?['price'];
    _price = TextEditingController(text: p == null ? '' : '$p');
    _blurb = TextEditingController(text: _s(widget.existing ?? const {}, 'blurb', ''));
    _newCat = TextEditingController();
    final img = _s(widget.existing ?? const {}, 'image_url', '');
    if (img.isNotEmpty) _imageUrl = img;
    _available = widget.existing?['available'] != false;
    _station = _s(widget.existing ?? const {}, 'station', '');
    _modifiers = ((widget.existing?['modifiers'] as List?) ?? []).map<Map<String, dynamic>>((g) {
      final m = g as Map;
      return {
        'name': '${m['name'] ?? ''}',
        'multi': m['multi'] == true,
        'required': m['required'] == true,
        'options': ((m['options'] as List?) ?? [])
            .map<Map<String, dynamic>>((o) => {'name': '${(o as Map)['name'] ?? ''}', 'price': o['price'] ?? 0})
            .toList(),
      };
    }).toList();
    _recipe = ((widget.existing?['recipe'] as List?) ?? []).map<Map<String, dynamic>>((r) {
      final m = r as Map;
      return {'inventory_id': '${m['inventory_id'] ?? ''}', 'qty': m['qty'] ?? 1};
    }).toList();
    final cur = _s(widget.existing ?? const {}, 'category', '');
    if (cur.isNotEmpty && widget.categories.contains(cur)) {
      _category = cur;
    } else if (widget.categories.isNotEmpty) {
      _category = widget.categories.first;
    } else {
      _addingNewCat = true;
    }
    // Inventory list for the recipe ingredient picker.
    widget.rest.getList('/inventory').then((inv) {
      if (mounted) setState(() => _inventory = inv);
    }).catchError((_) {});
  }

  @override
  void dispose() {
    _name.dispose();
    _price.dispose();
    _blurb.dispose();
    _newCat.dispose();
    super.dispose();
  }

  Future<void> _pickImage() async {
    final picked = await FilePicker.pickFiles(type: FileType.image, withData: true);
    final bytes = picked?.files.single.bytes;
    if (bytes == null) return;
    setState(() => _uploading = true);
    try {
      final ext = (picked!.files.single.extension ?? 'jpg').toLowerCase();
      final ct = ext == 'png' ? 'image/png' : 'image/jpeg';
      final res = await widget.rest.post('/menu/upload-image', {
        'image_base64': base64Encode(bytes),
        'content_type': ct,
      });
      final url = (res is Map) ? res['image_url'] as String? : null;
      if (mounted && url != null) setState(() => _imageUrl = url);
      if (mounted && url == null) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Image upload failed.')));
      }
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _uploading = false);
    }
  }

  void _submit() {
    final name = _name.text.trim();
    final category = _addingNewCat ? _newCat.text.trim() : (_category ?? '');
    if (name.isEmpty || category.isEmpty) return;
    Navigator.pop(context, <String, dynamic>{
      if (widget.existing?['id'] != null) 'id': widget.existing!['id'],
      'name': name,
      'price': double.tryParse(_price.text.trim()) ?? 0,
      'category': category,
      // Guest-facing blurb (stored as `blurb` inside the menu description JSON).
      // Always sent because this dialog always shows the current text: "" clears
      // it, which is what an owner who empties the field means.
      'blurb': _blurb.text.trim(),
      'image_url': _imageUrl ?? '',
      'available': _available,
      'station': _station.trim().isEmpty ? null : _station.trim(),
      'modifiers': _cleanModifiers(),
      'recipe': _recipe
          .where((r) => '${r['inventory_id']}'.isNotEmpty && (double.tryParse('${r['qty']}') ?? 0) > 0)
          .map((r) => {'inventory_id': r['inventory_id'], 'qty': double.tryParse('${r['qty']}') ?? 0})
          .toList(),
    });
  }

  Widget _recipeEditor() {
    final text = Theme.of(context).textTheme;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        Expanded(child: Text('RECIPE · AUTO-DEDUCT STOCK', style: text.labelSmall, overflow: TextOverflow.ellipsis)),
        Opacity(
          opacity: _inventory.isEmpty ? 0.45 : 1,
          child: ForkButton.subtle(
            label: 'Ingredient',
            icon: Icons.add,
            onPressed: _inventory.isEmpty
                ? null
                : () => setState(() => _recipe.add({'inventory_id': '', 'qty': 1})),
          ),
        ),
      ]),
      const SizedBox(height: 4),
      if (_inventory.isEmpty)
        Text('Add inventory items first to build a recipe.', style: text.bodySmall)
      else
        for (int i = 0; i < _recipe.length; i++)
          // Keyed on the row itself (see [_groupCard]): the quantity box is an
          // initialValue field, so without it removing a row left its quantity
          // on screen beside the next ingredient.
          Row(key: ObjectKey(_recipe[i]), children: [
            Expanded(
              flex: 3,
              child: DropdownButtonFormField<String>(
                initialValue: ('${_recipe[i]['inventory_id']}').isEmpty ? null : '${_recipe[i]['inventory_id']}',
                isExpanded: true,
                decoration: const InputDecoration(labelText: 'Ingredient', isDense: true),
                items: [
                  for (final inv in _inventory)
                    DropdownMenuItem(value: '${(inv as Map)['id']}', child: Text('${inv['name']} (${inv['stock'] ?? 0}${inv['unit'] ?? ''})', overflow: TextOverflow.ellipsis)),
                ],
                onChanged: (v) => setState(() => _recipe[i]['inventory_id'] = v ?? ''),
              ),
            ),
            const SizedBox(width: 8),
            Expanded(
              flex: 2,
              child: TextFormField(
                initialValue: '${_recipe[i]['qty'] ?? ''}',
                keyboardType: const TextInputType.numberWithOptions(decimal: true),
                decoration: const InputDecoration(labelText: 'Qty/unit', isDense: true),
                onChanged: (v) => _recipe[i]['qty'] = double.tryParse(v) ?? 0,
              ),
            ),
            IconButton(
              icon: const Icon(Icons.close, size: 16),
              tooltip: 'Remove ingredient',
              onPressed: () => setState(() => _recipe.removeAt(i)),
            ),
          ]),
    ]);
  }

  List<Map<String, dynamic>> _cleanModifiers() => _modifiers
      .where((g) => '${g['name']}'.trim().isNotEmpty)
      .map((g) => {
            'name': '${g['name']}'.trim(),
            'multi': g['multi'] == true,
            'required': g['required'] == true,
            'options': ((g['options'] as List?) ?? [])
                .where((o) => '${(o as Map)['name']}'.trim().isNotEmpty)
                .map((o) => {
                      'name': '${(o as Map)['name']}'.trim(),
                      'price': (o['price'] is num) ? o['price'] : (double.tryParse('${o['price']}') ?? 0),
                    })
                .toList(),
          })
      .where((g) => (g['options'] as List).isNotEmpty)
      .toList();

  Widget _modifierEditor() {
    final text = Theme.of(context).textTheme;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        Expanded(child: Text('MODIFIERS / VARIANTS', style: text.labelSmall, overflow: TextOverflow.ellipsis)),
        ForkButton.subtle(
          label: 'Group',
          icon: Icons.add,
          onPressed: () => setState(() => _modifiers.add({
                'name': '',
                'multi': false,
                'required': false,
                'options': [
                  {'name': '', 'price': 0},
                ],
              })),
        ),
      ]),
      const SizedBox(height: 4),
      for (int gi = 0; gi < _modifiers.length; gi++) _groupCard(gi),
    ]);
  }

  Widget _groupCard(int gi) {
    final g = _modifiers[gi];
    final options = g['options'] as List;
    // THE ROWS ARE KEYED ON THEIR OWN MAPS — found by the item 3 (2.0.1) sweep.
    // These boxes are `TextFormField(initialValue:)`, which reads the value once,
    // when the field is first built. Unkeyed, removing a group or an option that
    // was not the last one shifted the list under fields that kept their text:
    // the removed "Medium +40" stayed on screen, "Large +80" vanished, and a
    // price typed into the box reading +40 was saved as Large's. Each map is its
    // own object (never a const literal), so ObjectKey follows the row itself.
    return Padding(
      key: ObjectKey(g),
      padding: const EdgeInsets.only(bottom: 8),
      child: ForkCard(
        inset: true,
        padding: const EdgeInsets.all(12),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Expanded(
              child: TextFormField(
                initialValue: '${g['name'] ?? ''}',
                decoration: const InputDecoration(labelText: 'Group (e.g. Size)', isDense: true),
                onChanged: (v) => g['name'] = v,
              ),
            ),
            const SizedBox(width: AppSpacing.sm),
            ForkIconButton(
              icon: Icons.delete_outline,
              tooltip: 'Remove group',
              onPressed: () => setState(() => _modifiers.removeAt(gi)),
            ),
          ]),
          Row(children: [
            Expanded(
              child: CheckboxListTile(
                contentPadding: EdgeInsets.zero,
                dense: true,
                value: g['multi'] == true,
                onChanged: (v) => setState(() => g['multi'] = v ?? false),
                title: const Text('Multi', style: TextStyle(fontSize: 12)),
              ),
            ),
            Expanded(
              child: CheckboxListTile(
                contentPadding: EdgeInsets.zero,
                dense: true,
                value: g['required'] == true,
                onChanged: (v) => setState(() => g['required'] = v ?? false),
                title: const Text('Required', style: TextStyle(fontSize: 12)),
              ),
            ),
          ]),
          for (int oi = 0; oi < options.length; oi++)
            Row(key: ObjectKey(options[oi]), children: [
              Expanded(
                flex: 3,
                child: TextFormField(
                  initialValue: '${(options[oi] as Map)['name'] ?? ''}',
                  decoration: const InputDecoration(labelText: 'Option', isDense: true),
                  onChanged: (v) => (options[oi] as Map)['name'] = v,
                ),
              ),
              const SizedBox(width: 8),
              Expanded(
                flex: 2,
                child: TextFormField(
                  initialValue: '${(options[oi] as Map)['price'] ?? ''}',
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(labelText: '+₹', isDense: true),
                  onChanged: (v) => (options[oi] as Map)['price'] = double.tryParse(v) ?? 0,
                ),
              ),
              IconButton(
                icon: const Icon(Icons.close, size: 16),
                tooltip: 'Remove option',
                onPressed: () => setState(() => options.removeAt(oi)),
              ),
            ]),
          const SizedBox(height: 4),
          Align(
            alignment: Alignment.centerLeft,
            child: ForkButton.subtle(
              label: 'Add option',
              icon: Icons.add,
              onPressed: () => setState(() => options.add({'name': '', 'price': 0})),
            ),
          ),
        ]),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final options = [...widget.categories, _newCatSentinel];
    return Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        width: 440,
        padding: const EdgeInsets.all(22),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.borderStrong),
        ),
        child: ConstrainedBox(
          constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(context).height * 0.85),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('MENU', style: text.labelSmall),
            const SizedBox(height: 6),
            Text(widget.existing == null ? 'Add menu item' : 'Edit menu item', style: text.titleMedium),
            const SizedBox(height: AppSpacing.lg),
            Flexible(
              child: SingleChildScrollView(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
        // Photo picker + preview (shown to customers while ordering).
        GestureDetector(
          onTap: _uploading ? null : _pickImage,
          child: Container(
            height: 120,
            width: double.infinity,
            decoration: BoxDecoration(
              color: AppColors.inset,
              borderRadius: AppRadius.tileAll,
              border: Border.all(color: AppColors.border),
              image: (_imageUrl != null && _imageUrl!.isNotEmpty)
                  ? DecorationImage(image: NetworkImage(_imageUrl!), fit: BoxFit.cover)
                  : null,
            ),
            child: _uploading
                ? const Center(child: CircularProgressIndicator())
                : (_imageUrl == null || _imageUrl!.isEmpty)
                    ? Center(
                        child: Column(mainAxisSize: MainAxisSize.min, children: [
                          Icon(Icons.add_a_photo, color: AppColors.textSecondary),
                          SizedBox(height: 4),
                          Text('Add photo', style: TextStyle(color: AppColors.textSecondary, fontSize: 12)),
                        ]))
                    : Align(
                        alignment: Alignment.topRight,
                        child: IconButton(
                          icon: const CircleAvatar(radius: 14, backgroundColor: Colors.black54, child: Icon(Icons.close, size: 16, color: Colors.white)),
                          onPressed: () => setState(() => _imageUrl = null),
                        ),
                      ),
          ),
        ),
        const SizedBox(height: 10),
        TextField(controller: _name, autofocus: true, decoration: const InputDecoration(labelText: 'Item name')),
        TextField(
          controller: _price,
          keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(labelText: 'Price', prefixText: '₹ '),
        ),
        const SizedBox(height: 8),
        if (!_addingNewCat)
          DropdownButtonFormField<String>(
            initialValue: _category,
            isExpanded: true,
            decoration: const InputDecoration(labelText: 'Category'),
            items: options.map((c) => DropdownMenuItem(value: c, child: Text(c))).toList(),
            onChanged: (v) => setState(() {
              if (v == _newCatSentinel) {
                _addingNewCat = true;
              } else {
                _category = v;
              }
            }),
          )
        else
          TextField(
            controller: _newCat,
            autofocus: true,
            decoration: InputDecoration(
              labelText: 'New category',
              suffixIcon: widget.categories.isEmpty
                  ? null
                  : IconButton(
                      icon: const Icon(Icons.close),
                      onPressed: () => setState(() => _addingNewCat = false),
                    ),
            ),
          ),
          const SizedBox(height: 10),
          // A few lines about the dish, shown when a guest opens the item on the
          // ordering page. Plain text only — the backend strips markup, collapses
          // blank runs and caps the text at 500 chars, so the counter below is
          // exactly the limit that will be stored. Blank = no description.
          TextField(
            controller: _blurb,
            minLines: 2,
            maxLines: 4,
            maxLength: _blurbMax,
            textCapitalization: TextCapitalization.sentences,
            keyboardType: TextInputType.multiline,
            decoration: const InputDecoration(
              labelText: 'Description',
              alignLabelWithHint: true,
              helperText: 'Shown to guests when they open this item. Leave blank for none.',
            ),
          ),
          const SizedBox(height: 4),
          SwitchListTile(
            contentPadding: EdgeInsets.zero,
            value: _available,
            onChanged: (v) => setState(() => _available = v),
            title: const Text('Available'),
            subtitle: Text(_available ? 'Customers can order this' : 'Shown as Sold out'),
          ),
          const SizedBox(height: AppSpacing.md),
          Align(
            alignment: Alignment.centerLeft,
            child: Text('KITCHEN SECTION · KOT ROUTING', style: text.labelSmall),
          ),
          const SizedBox(height: 6),
          _SectionSelector(
            value: _station,
            sections: widget.sections,
            onChanged: (v) => _station = v,
          ),
          const SizedBox(height: AppSpacing.lg),
          _modifierEditor(),
          const SizedBox(height: AppSpacing.md),
          _recipeEditor(),
                ]),
              ),
            ),
            const SizedBox(height: AppSpacing.lg),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(context)),
              const SizedBox(width: AppSpacing.sm),
              ForkButton(label: 'Save', icon: Icons.check, onPressed: _submit),
            ]),
          ]),
        ),
      ),
    );
  }
}

Future<int?> _askCovers(BuildContext context) async {
  final covers = TextEditingController(text: '2');
  final result = await showDialog<int>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: const Text('How many people?'),
      content: TextField(
        controller: covers,
        keyboardType: TextInputType.number,
        autofocus: true,
        decoration: const InputDecoration(labelText: 'Number of people'),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
        FilledButton(
          onPressed: () => Navigator.pop(ctx, int.tryParse(covers.text.trim()) ?? 1),
          child: const Text('Seat'),
        ),
      ],
    ),
  );
  covers.dispose();
  return result;
}

Future<void> _printTableQr(String tableName, String url) async {
  final doc = pw.Document();
  doc.addPage(
    pw.Page(
      build: (ctx) => pw.Center(
        child: pw.Column(mainAxisAlignment: pw.MainAxisAlignment.center, children: [
          pw.Text('Scan to order — Table $tableName',
              style: pw.TextStyle(fontSize: 22, fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 24),
          pw.BarcodeWidget(barcode: pw.Barcode.qrCode(), data: url, width: 260, height: 260),
          pw.SizedBox(height: 16),
          pw.Text(url, style: const pw.TextStyle(fontSize: 9)),
        ]),
      ),
    ),
  );
  await Printing.layoutPdf(onLayout: (PdfPageFormat format) => doc.save());
}

/// The entrance poster. Same shape as [_printTableQr] deliberately: a host who
/// has printed table QRs should recognise this sheet without being taught it.
Future<void> _printQueueQr(String url) async {
  final doc = pw.Document();
  doc.addPage(
    pw.Page(
      build: (ctx) => pw.Center(
        child: pw.Column(mainAxisAlignment: pw.MainAxisAlignment.center, children: [
          pw.Text('Tables are full — scan to join the queue',
              style: pw.TextStyle(fontSize: 22, fontWeight: pw.FontWeight.bold)),
          pw.SizedBox(height: 8),
          pw.Text('Browse the menu and pre-order while you wait',
              style: const pw.TextStyle(fontSize: 12)),
          pw.SizedBox(height: 24),
          pw.BarcodeWidget(barcode: pw.Barcode.qrCode(), data: url, width: 260, height: 260),
          pw.SizedBox(height: 16),
          pw.Text(url, style: const pw.TextStyle(fontSize: 9)),
        ]),
      ),
    ),
  );
  await Printing.layoutPdf(onLayout: (PdfPageFormat format) => doc.save());
}

/// What [allocateTableNames] worked out: the names to create, the ones in that
/// range it stepped over because the floor already has them, and — when it could
/// not deliver the run that was asked for — the reason, in words.
class TableNameRun {
  /// Names to create, in order.
  final List<String> names;

  /// Names inside the scanned range that already exist. Reported rather than
  /// swallowed — "I asked for 5 and got T4..T8" needs the reason on screen.
  final List<String> skipped;

  /// Empty when the run is exactly what was asked for. Otherwise the sentence to
  /// put in front of the owner: a seed whose number cannot be counted from, or a
  /// scan that ran out of free numbers before filling the request.
  ///
  /// It exists because the alternative is a create that reports success having
  /// written nothing. An empty [names] must never be left for the caller to
  /// interpret — silence on a create is the worst failure there is.
  final String problem;

  /// True when every name asked for was allocated.
  bool get complete => problem.isEmpty;

  const TableNameRun(this.names, this.skipped, {this.problem = ''});
}

/// How many candidate numbers past the request one run may examine.
///
/// The scan has to be bounded: a floor with a long unbroken run of taken numbers
/// must still finish, and the loop must never depend on eventually finding a
/// gap. It scales with the request because asking for more tables is also asking
/// to step over more of them — a flat bound short-changed big runs first.
/// Examining a few thousand candidates is a set lookup each; the cost is the
/// user waiting for nothing, not the CPU.
int _tableScanWindow(int count) => 500 + 100 * count;

/// A run's names as something a person can read. A scan that stepped over
/// hundreds of taken names is not made clearer by printing every one of them —
/// and the full paragraph does not fit the dialog it is shown in.
String _tableNameList(List<String> names, {int show = 12}) => names.length <= show
    ? names.join(', ')
    : '${names.take(show).join(', ')} … and ${names.length - show} more';

/// Splits [seed] into a prefix and its trailing number ("T1" -> "T" + 1,
/// "Patio 4" -> "Patio " + 4) and returns the next [count] FREE numbers from
/// there, stepping over every name already in [existing]. Adding five tables
/// from "T1" on a floor that already has T1..T3 yields T4..T8, not five
/// collisions — that skipping is the explicit requirement.
///
/// A seed with no trailing number gets one appended ("Bar" -> Bar1, Bar2, …),
/// and zero padding is kept ("T01" -> T02, T03) because that is how the floor
/// was numbered to begin with. Matching is case-insensitive, the way the
/// backend resolves a table name.
TableNameRun allocateTableNames(String seed, int count, Iterable<String> existing) {
  final trimmed = seed.trim();
  if (trimmed.isEmpty || count < 1) return const TableNameRun([], []);
  final match = RegExp(r'^(.*?)(\d+)$').firstMatch(trimmed);
  final prefix = match?.group(1) ?? trimmed;
  final digits = match?.group(2) ?? '1';
  final window = _tableScanWindow(count);
  // A trailing number can be unusable in two ways, and BOTH used to end as a
  // silent no-op: too many digits for an int at all (tryParse null, which the
  // old `?? 1` quietly renumbered from one), or close enough to the top of the
  // range that `start + count + window` wraps NEGATIVE — which made `n < limit`
  // false on the first pass, so the loop never ran and the caller was handed an
  // empty run it read as "one table, nothing skipped" and reported as success.
  final start = int.tryParse(digits);
  if (start == null || start + count + window < start) {
    return TableNameRun(
      const [],
      const [],
      problem: 'No tables were numbered: the number at the end of "$trimmed" is too large to '
          'count on from. Start the run from a smaller number.',
    );
  }
  final width = digits.length;
  final taken = {
    for (final n in existing)
      if (n.trim().isNotEmpty) n.trim().toLowerCase(),
  };
  final names = <String>[];
  final skipped = <String>[];
  final limit = start + count + window;
  var n = start;
  for (; names.length < count && n < limit; n++) {
    final candidate = '$prefix${'$n'.padLeft(width, '0')}';
    if (!taken.add(candidate.toLowerCase())) {
      skipped.add(candidate);
      continue;
    }
    names.add(candidate);
  }
  if (names.length == count) return TableNameRun(names, skipped);
  // The scan hit its bound with the request unfilled. Say exactly that: a short
  // run and a long Skipped list otherwise read as "nothing matched", and the
  // owner has no way to tell it from a floor that is genuinely full.
  // Named from the first candidate actually examined, not the seed: a seed with
  // no number of its own ("Bar") starts the scan at "Bar1".
  final first = '$prefix${'$start'.padLeft(width, '0')}';
  final last = '$prefix${'${n - 1}'.padLeft(width, '0')}';
  return TableNameRun(
    names,
    skipped,
    problem: 'Only ${names.length} of the $count asked for could be numbered: every other name from '
        '"$first" up to "$last" is already on the floor. Start the run from a higher number.',
  );
}

/// Adds one table, or a numbered run of them. [existing] is every table name on
/// the floor — it drives both the live preview in the dialog and the allocator,
/// DELETING A TABLE, FROM THE ONE PLACE IT NOW LIVES — requirements C7 and H8.
///
/// WHERE IT WAS AND WHY IT MOVED. The control was a small red "Delete table" at
/// the bottom of the per-table sheet: the same sheet a waiter opens to add an
/// order and a manager opens to settle a bill, which makes it the most-opened
/// surface in the app, with an irreversible floor edit parked one scroll below
/// the things people actually came for. H8 asks for it out of the ubiquitous
/// views and into the Floor header; C7 asks for it to be restricted by role.
/// Both are now true, and the role half is [FloorScope.deleteTable] ANDed with
/// [FloorSurface.plan], so it is not merely off the sheet — the sheet no longer
/// has a code path that reaches it, for anybody.
///
/// "THE UI MUST BE EXPLICIT ABOUT WHAT THE ACTION DOES" (H8, verbatim). The old
/// confirmation said "This removes the table from the floor", which is true and
/// tells the reader nothing they were worried about. This one answers the three
/// questions somebody hovering over a red button is actually asking, and every
/// answer below is a fact about RemoveTable rather than reassurance:
///
///   * WHAT SURVIVES — past orders and bills do. A table carrying history is
///     soft-deleted precisely so those records keep their table, so the day's
///     takings and every report built on them are untouched.
///   * WHAT GOES — the tile, on every device; the waiter assignment on it; and
///     the ordering QR printed for it stops resolving.
///   * WHAT IT WILL REFUSE — an occupied table, or one with an open bill. The
///     server blocks both ("Settle or release the table before deleting it"),
///     which is the answer a manager needs BEFORE they walk to the table, not
///     after. So the picker says which tables are busy and does not offer them.
Future<void> _deleteTableFromHeader(
    BuildContext context, RestClient rest, List rows, VoidCallback reload) async {
  final messenger = ScaffoldMessenger.of(context);
  // Deliberately only the ones the server would accept. Offering a busy table
  // and collecting a 400 teaches staff that this screen guesses.
  final deletable = <Map>[
    for (final r in rows)
      if (!_tableSeated(r as Map) && _s(r, 'table_name').isNotEmpty) r,
  ];
  final busy = rows.length - deletable.length;
  if (deletable.isEmpty) {
    messenger.showSnackBar(SnackBar(
        content: Text(busy == 0
            ? 'There are no tables to delete.'
            : 'Every table is in use. A table can only be deleted once it has been '
                'settled or released.')));
    return;
  }
  final name = await showDialog<String>(
    context: context,
    builder: (ctx) {
      final text = Theme.of(ctx).textTheme;
      return AlertDialog(
        backgroundColor: AppColors.surface,
        title: const Text('Delete which table?'),
        content: SizedBox(
          width: 360,
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(
                busy == 0
                    ? 'Pick the table to remove from the floor plan.'
                    : 'Pick the table to remove from the floor plan. '
                        '$busy in use ${busy == 1 ? 'is' : 'are'} not listed — a table '
                        'can only be deleted once it has been settled or released.',
                style: text.bodySmall),
            const SizedBox(height: AppSpacing.md),
            Flexible(
              child: SingleChildScrollView(
                child: Column(children: [
                  for (final t in deletable)
                    ListTile(
                      key: ValueKey('delete-pick-${_s(t, 'table_name')}'),
                      dense: true,
                      contentPadding: EdgeInsets.zero,
                      leading: const Icon(Icons.table_restaurant, size: 18),
                      title: Text(_s(t, 'table_name'), style: text.titleSmall),
                      subtitle: Text(
                        [
                          if (_seatsLabel(t).isNotEmpty) _seatsLabel(t),
                          if (_s(t, 'section', '').trim().isNotEmpty) 'in ${_s(t, 'section')}',
                        ].join(' · '),
                        style: text.bodySmall,
                      ),
                      onTap: () => Navigator.pop(ctx, _s(t, 'table_name')),
                    ),
                ]),
              ),
            ),
          ]),
        ),
        actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel'))],
      );
    },
  );
  if (name == null || name.isEmpty || !context.mounted) return;
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => AlertDialog(
      backgroundColor: AppColors.surface,
      title: Text('Delete table $name permanently?'),
      content: Text(
        '$name disappears from the floor plan on every device, for everyone. '
        'Any waiter assigned to it is unassigned, and the ordering QR code '
        'printed for $name stops working.\n\n'
        'Its past orders and bills are NOT deleted — they stay in your history, '
        'your reports and the takings for the day, exactly as they are.\n\n'
        'This cannot be undone from this screen. Creating a table called $name '
        'again does not bring the old one back.',
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Keep it')),
        FilledButton(
          key: const ValueKey('floor-delete-confirm'),
          onPressed: () => Navigator.pop(ctx, true),
          style: FilledButton.styleFrom(backgroundColor: AppColors.danger),
          child: Text('Delete $name'),
        ),
      ],
    ),
  );
  if (ok != true) return;
  try {
    await rest.delete('/table/${Uri.encodeComponent(name)}');
    messenger.showSnackBar(SnackBar(content: Text('$name removed from the floor plan.')));
    reload();
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

/// so a run never asks the server for a name that is already taken.
///
/// The permission is the backend's `Table Added` gate on POST /add-table, which
/// a run reuses one row at a time: bulk adding is the same write, repeated, and
/// gets no new authority. Placing tables into a zone that does not exist yet
/// additionally needs the section grant, which is why the dialog only ever
/// offers zones that are already on the floor.
Future<void> _addTable(BuildContext context, RestClient rest, VoidCallback reload,
    {List<String> sections = const [], List<String> existing = const []}) async {
  final messenger = ScaffoldMessenger.of(context);
  final seats = await showDialog<_TableSeating>(
    context: context,
    builder: (_) => _TableSeatingDialog(sections: sections, existingNames: existing),
  );
  if (seats == null) return;
  // A single table keeps the old path exactly — the name typed is the name
  // created, so "Patio" stays "Patio" instead of becoming "Patio1".
  final run = seats.count <= 1
      ? TableNameRun([seats.name], const [])
      : allocateTableNames(seats.name, seats.count, existing);

  final created = <String>[];
  var failedName = '';
  var error = '';
  for (final name in run.names) {
    try {
      await rest.post('/add-table', {
        'table': {
          'name': name,
          'capacity': seats.capacity,
          'max_capacity': seats.maxCapacity,
          // Omitted when Unassigned so the backend stores null.
          if (seats.section.trim().isNotEmpty) 'section': seats.section.trim(),
        },
      });
      created.add(name);
    } catch (e) {
      // Stop at the first rejection rather than firing the rest at a server
      // that just refused: a partial batch has to be reported, not continued.
      failedName = name;
      error = '$e';
      break;
    }
  }
  if (created.isNotEmpty) reload();
  if (!context.mounted) return;

  // One table, nothing skipped and nothing to explain: behave exactly as before
  // — silent on success, a snackbar on failure. Anything else gets the run
  // report, and `run.problem` is explicitly part of "anything else": a run that
  // allocated no names at all lands here with both lists empty, and taking the
  // quiet path would report success having created nothing.
  if (run.names.length <= 1 && run.skipped.isEmpty && run.complete) {
    if (error.isNotEmpty) messenger.showSnackBar(SnackBar(content: Text(error)));
    return;
  }
  final notAttempted = run.names.skip(created.length + (failedName.isEmpty ? 0 : 1)).toList();
  await _detailSheet(
    context,
    eyebrow: 'Floor',
    title: created.isEmpty
        ? 'No tables were added'
        : 'Added ${created.length} table${created.length == 1 ? '' : 's'}',
    children: [
      // First, above the lists: why the run is not what was asked for.
      if (run.problem.isNotEmpty) _kv('Numbering', run.problem),
      if (created.isNotEmpty) _kv('Created', _tableNameList(created)),
      if (run.skipped.isNotEmpty) _kv('Skipped', '${_tableNameList(run.skipped)} — already on the floor'),
      if (failedName.isNotEmpty) _kv('Failed', '$failedName — $error'),
      if (notAttempted.isNotEmpty) _kv('Not attempted', _tableNameList(notAttempted)),
      if (seats.section.trim().isNotEmpty) _kv('Section', seats.section.trim()),
      _kv('Seating', _seatsLabel({'capacity': seats.capacity, 'max_capacity': seats.maxCapacity})),
    ],
  );
}

/// What [_TableSeatingDialog] hands back: the table's name (add mode only), its
/// normal seat count, and the MAX it can take once extra chairs go in.
class _TableSeating {
  final String name;
  final int capacity;
  final int maxCapacity;
  /// Zone the new table lands in. Empty = Unassigned (the field is then omitted
  /// from the request so the backend stores null).
  final String section;

  /// How many tables to create from [name] onwards (add mode only). 1 is the
  /// plain single add; more runs [allocateTableNames].
  final int count;
  const _TableSeating({
    required this.name,
    required this.capacity,
    required this.maxCapacity,
    this.section = '',
    this.count = 1,
  });
}

/// Add a table, or edit an existing one's seating. `existing` null == add mode.
/// The max defaults to the seat count (so it stays inert until an owner raises
/// it) and can never sit below it.
class _TableSeatingDialog extends StatefulWidget {
  final Map? existing;
  /// Zones already on the floor, so a new table can be placed straight into one.
  final List<String> sections;

  /// Every table name already on the floor, for the run preview. Named
  /// [existingNames] because [existing] is the row being edited.
  final List<String> existingNames;
  const _TableSeatingDialog({this.existing, this.sections = const [], this.existingNames = const []});

  @override
  State<_TableSeatingDialog> createState() => _TableSeatingDialogState();
}

/// The most tables one run may create. High enough for a real floor being set
/// up in one go, low enough that a slipped keystroke ("100" for "10") cannot
/// fire a hundred writes at the server.
const int _maxTableRun = 50;

class _TableSeatingDialogState extends State<_TableSeatingDialog> {
  late final TextEditingController _name;
  late final TextEditingController _capacity;
  late final TextEditingController _max;
  final _count = TextEditingController(text: '1');
  // True once the max has been typed into by hand — before that it tracks the
  // seat count, so the common "no extra chairs" case needs no thought.
  bool _maxTouched = false;
  String _section = '';
  String? _error;

  bool get _adding => widget.existing == null;

  @override
  void initState() {
    super.initState();
    final e = widget.existing;
    final cap = _int(e?['capacity']) ?? 4;
    // Legacy rows carry no max — the server coalesces it to the seat count, so
    // pre-fill the same value instead of showing a blank.
    final max = _int(e?['max_capacity']) ?? cap;
    _name = TextEditingController(text: e == null ? '' : _s(e, 'table_name', ''));
    _capacity = TextEditingController(text: '$cap');
    _max = TextEditingController(text: '$max');
    _maxTouched = !_adding && max > cap;
    _capacity.addListener(() {
      if (_maxTouched) return;
      final c = _capacity.text.trim();
      if (_max.text != c) _max.text = c;
    });
    // The preview has to answer "what will this actually create?" before the
    // run happens, so it re-derives on every keystroke in either field.
    if (_adding) {
      _name.addListener(_refreshPreview);
      _count.addListener(_refreshPreview);
    }
  }

  void _refreshPreview() => setState(() {});

  @override
  void dispose() {
    _name.dispose();
    _capacity.dispose();
    _max.dispose();
    _count.dispose();
    super.dispose();
  }

  /// How many tables the run field is asking for, clamped to what a run may do.
  /// Blank or unparseable reads as 1 — the plain single add.
  int get _runCount {
    final n = int.tryParse(_count.text.trim()) ?? 1;
    if (n < 1) return 1;
    return n > _maxTableRun ? _maxTableRun : n;
  }

  void _submit() {
    final name = _name.text.trim();
    if (_adding && name.isEmpty) {
      setState(() => _error = 'Give the table a name (e.g. T7).');
      return;
    }
    // "12 #2" is the server's to make (client item 6): its own sentence,
    // before the request rather than after it — for every name a run makes.
    if (_adding &&
        (isReservedPartyName(name) ||
            allocateTableNames(name, _runCount, widget.existingNames).names.any(isReservedPartyName))) {
      setState(() => _error = reservedTableNameError);
      return;
    }
    final cap = int.tryParse(_capacity.text.trim());
    final max = int.tryParse(_max.text.trim());
    if (cap == null || cap < 1 || max == null || max < 1) {
      setState(() => _error = 'Seats and max must be whole numbers of 1 or more.');
      return;
    }
    if (max < cap) {
      setState(() => _error = 'Max capacity cannot be below the seat count ($cap).');
      return;
    }
    final typed = int.tryParse(_count.text.trim());
    if (_adding && (typed == null || typed < 1 || typed > _maxTableRun)) {
      setState(() => _error = 'How many must be a whole number from 1 to $_maxTableRun.');
      return;
    }
    Navigator.pop(
      context,
      _TableSeating(
        name: name,
        capacity: cap,
        maxCapacity: max,
        section: _section,
        count: _adding ? _runCount : 1,
      ),
    );
  }

  /// Spells out the run before it is committed: the names that will be created
  /// and the ones being stepped over, so "why did I get T4 when I typed T1?"
  /// is answered in the dialog rather than after the writes.
  Widget _runPreview(TextTheme text) {
    final run = allocateTableNames(_name.text, _runCount, widget.existingNames);
    if (run.names.isEmpty && run.skipped.isEmpty && run.complete) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(top: 10),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // A run that cannot be numbered says so HERE, before the writes — the
        // owner gets to fix the seed instead of reading about it afterwards.
        if (run.problem.isNotEmpty)
          Text(run.problem, style: text.bodySmall!.copyWith(fontSize: 11.5, color: AppColors.warning)),
        if (run.names.isNotEmpty)
          Text('Creates ${_tableNameList(run.names)}',
              style: text.bodySmall!.copyWith(fontSize: 11.5, color: AppColors.copperHi)),
        if (run.skipped.isNotEmpty)
          Padding(
            padding: const EdgeInsets.only(top: 3),
            child: Text('Skips ${_tableNameList(run.skipped)} — already on the floor',
                style: text.bodySmall!.copyWith(fontSize: 11.5, color: AppColors.textTertiary)),
          ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    // 340 is the design width, but an AlertDialog on a phone is narrower than
    // that — forcing it there overflows the fields sideways.
    final room = MediaQuery.sizeOf(context).width - 80;
    final width = room < 340 ? (room < 220 ? 220.0 : room) : 340.0;
    return AlertDialog(
      title: Text(_adding ? 'Add table' : 'Seating for ${_s(widget.existing!, 'table_name')}'),
      content: SizedBox(
        width: width,
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          if (_adding) ...[
            Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Expanded(
                child: TextField(
                  controller: _name,
                  autofocus: true,
                  decoration: const InputDecoration(labelText: 'Table name (e.g. T7)'),
                ),
              ),
              const SizedBox(width: AppSpacing.md),
              // The run counter. Numbering carries on from the name typed left
              // of it and skips whatever is taken, so an owner setting up a
              // floor types T1 / 12 instead of the dialog twelve times.
              SizedBox(
                width: 88,
                child: TextField(
                  controller: _count,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(labelText: 'How many'),
                ),
              ),
            ]),
            _runPreview(text),
          ],
          TextField(
            controller: _capacity,
            autofocus: !_adding,
            keyboardType: TextInputType.number,
            decoration: const InputDecoration(labelText: 'Seats (the usual cover count)'),
          ),
          TextField(
            controller: _max,
            keyboardType: TextInputType.number,
            onChanged: (_) => _maxTouched = true,
            decoration: const InputDecoration(labelText: 'Max capacity (with extra chairs)'),
          ),
          // Drop the table straight into a zone. Only offered when adding, and
          // only lists zones that already exist — creating a NEW zone needs the
          // "Manage Table Sections" permission, so it belongs on the floor screen.
          if (_adding && widget.sections.isNotEmpty) ...[
            const SizedBox(height: 12),
            DropdownButtonFormField<String>(
              initialValue: _section,
              dropdownColor: AppColors.cardRaised,
              decoration: const InputDecoration(labelText: 'Section', isDense: true),
              items: [
                const DropdownMenuItem(value: '', child: Text('Unassigned')),
                for (final sec in widget.sections)
                  DropdownMenuItem(value: sec, child: Text(sec)),
              ],
              onChanged: (v) => setState(() => _section = v ?? ''),
            ),
          ],
          const SizedBox(height: 10),
          Text(
            _adding && _runCount > 1
                ? 'Seats, max capacity and section apply to every table in the run. '
                    'A party larger than the max is offered a combination of adjacent '
                    'tables instead — staff always confirm the suggestion.'
                : 'A party larger than the max is offered a combination of adjacent '
                    'tables instead — staff always confirm the suggestion.',
            style: text.bodySmall!.copyWith(fontSize: 11.5, color: AppColors.textTertiary),
          ),
          if (_error != null) ...[
            const SizedBox(height: 8),
            Text(_error!, style: text.bodySmall!.copyWith(color: AppColors.danger)),
          ],
        ]),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
        FilledButton(
          onPressed: _submit,
          child: Text(_adding ? (_runCount > 1 ? 'Add $_runCount tables' : 'Add') : 'Save'),
        ),
      ],
    );
  }
}

// The settle screen now lives in mis_capture.dart as `_PaymentSheet`: the same
// three calls (record payment -> approve -> close) and the same payment-proof
// rule, plus the tenders, tips and till that migrations 037/038 record. It was
// MOVED rather than duplicated - two settle screens on one till is how a bill
// gets taken twice.

// ------------------------------------------------------------- order stages ----

// Cancelled is a TERMINAL stage: once an order is cancelled nothing may modify
// it again. The one sanctioned reversal is an undo from the Audit Log, so every
// mutating affordance is hidden/disabled and the server refuses anything that
// still slips through.
bool _isCancelled(String status) => status.trim().toLowerCase() == 'cancelled';

// Single wording for the terminal note so it never drifts between surfaces.
const String _cancelledNote =
    'This order was cancelled. Cancelled orders are final — reverse it from the Audit Log if this was a mistake.';

// The same note, trimmed for the inline captions that sit under a row/ticket.
const String _cancelledCaption = 'Cancelled — final. Reverse it from the Audit Log if this was a mistake.';

// One-line caption for each pickable stage in the change-stage sheet.
String _stageHint(String stage) => switch (stage) {
      'Barked' => 'Announce the order to the kitchen',
      'Preparing' => 'Kitchen is cooking this order',
      'Served' => 'All items delivered to the table',
      'Cancelled' => 'Void this order',
      _ => '',
    };

Future<void> _changeOrderStatus(
  BuildContext context,
  RestClient rest,
  String orderId,
  String current,
  VoidCallback reload, {
  bool barked = true,
  /// Whose permissions decide whether a cancel can carry a reason. Optional so
  /// a caller that has no profile to hand keeps the behaviour it always had.
  Profile? profile,
  /// What the order is worth, for the void form's headline. Display only.
  String value = '',
}) async {
  // Un-barked orders must pass the Barked step before they can be cooked/served —
  // BUT a Pending order isn't approved to the kitchen yet, so it can't be barked
  // until it's accepted (Preparing). Don't offer 'Barked' while Pending.
  final isPending = current.toLowerCase() == 'pending';
  final stages = <String>[
    if (!barked && !isPending) 'Barked',
    'Preparing',
    if (barked) 'Served',
    'Cancelled',
  ];
  final messenger = ScaffoldMessenger.of(context);
  // A settled bill is view-once: its order status is locked and cannot change.
  final cur = current.toLowerCase();
  if (cur == 'paid' || cur == 'closed') {
    messenger.showSnackBar(const SnackBar(content: Text('This bill is settled and locked — its status cannot be changed.')));
    return;
  }
  // Cancelled is terminal: offer NO stage options at all — just the note and a
  // way out. The audit-log undo is the only sanctioned reversal.
  if (_isCancelled(cur)) {
    await showDialog<void>(
      context: context,
      builder: (ctx) {
        final text = Theme.of(ctx).textTheme;
        return Dialog(
          backgroundColor: AppColors.surface,
          shape: RoundedRectangleBorder(
            borderRadius: AppRadius.cardAll,
            side: BorderSide(color: AppColors.borderStrong),
          ),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 400),
            child: Padding(
              padding: const EdgeInsets.all(AppSpacing.xl),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Order stage', style: text.titleMedium),
                  const SizedBox(height: AppSpacing.sm),
                  Wrap(
                    spacing: 8,
                    runSpacing: 6,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      Text('NOW', style: text.labelSmall),
                      StatusChip(label: current, color: _stageColor(current), dense: true),
                    ],
                  ),
                  const SizedBox(height: AppSpacing.lg),
                  Container(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: AppColors.tint(AppColors.danger),
                      borderRadius: AppRadius.cardAll,
                      border: Border.all(color: AppColors.edge(AppColors.danger)),
                    ),
                    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Icon(Icons.lock_outline, size: 16, color: AppColors.danger),
                      const SizedBox(width: AppSpacing.sm),
                      Expanded(child: Text(_cancelledNote, style: text.bodySmall)),
                    ]),
                  ),
                  const SizedBox(height: AppSpacing.lg),
                  Row(mainAxisAlignment: MainAxisAlignment.end, children: [
                    ForkButton.ghost(label: 'Close', dense: true, onPressed: () => Navigator.pop(ctx)),
                  ]),
                ],
              ),
            ),
          ),
        );
      },
    );
    return;
  }
  final picked = await showDialog<String>(
    context: context,
    builder: (ctx) {
      String? sel;
      final text = Theme.of(ctx).textTheme;
      return StatefulBuilder(
        builder: (ctx2, setSheet) => Dialog(
          backgroundColor: AppColors.surface,
          shape: RoundedRectangleBorder(
            borderRadius: AppRadius.cardAll,
            side: BorderSide(color: AppColors.borderStrong),
          ),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 400),
            child: Padding(
              padding: const EdgeInsets.all(AppSpacing.xl),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Order stage', style: text.titleMedium),
                  const SizedBox(height: AppSpacing.sm),
                  Wrap(
                    spacing: 8,
                    runSpacing: 6,
                    crossAxisAlignment: WrapCrossAlignment.center,
                    children: [
                      Text('NOW', style: text.labelSmall),
                      StatusChip(label: current, color: _stageColor(current), dense: true),
                      if (!barked) const InfoChip(icon: Icons.campaign_outlined, label: 'Not barked'),
                    ],
                  ),
                  const SizedBox(height: AppSpacing.lg),
                  for (final s in stages)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 10),
                      child: ForkCard(
                        selected: sel == s,
                        onTap: () => setSheet(() => sel = s),
                        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                        child: Row(children: [
                          StatusChip(label: s, color: _stageColor(s), dense: true),
                          const SizedBox(width: AppSpacing.md),
                          Expanded(
                            child: Text(_stageHint(s),
                                style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                          ),
                          AnimatedSwitcher(
                            duration: AppDurations.fast,
                            child: sel == s
                                ? Icon(Icons.check_circle,
                                    key: ValueKey('on'), size: 16, color: AppColors.copperHi)
                                : Icon(Icons.circle_outlined,
                                    key: ValueKey('off'), size: 16, color: AppColors.textTertiary),
                          ),
                        ]),
                      ),
                    ),
                  const SizedBox(height: AppSpacing.sm),
                  Row(mainAxisAlignment: MainAxisAlignment.end, children: [
                    ForkButton.ghost(
                        label: 'Cancel', dense: true, onPressed: () => Navigator.pop(ctx2)),
                    const SizedBox(width: AppSpacing.sm),
                    AnimatedOpacity(
                      duration: AppDurations.fast,
                      opacity: sel == null ? 0.45 : 1,
                      child: ForkButton(
                        label: 'Confirm',
                        icon: Icons.check,
                        dense: true,
                        onPressed: sel == null ? null : () => Navigator.pop(ctx2, sel),
                      ),
                    ),
                  ]),
                ],
              ),
            ),
          ),
        ),
      );
    },
  );
  if (picked == null || picked == current) return;
  // A2 — EVERY CANCEL IS PROMPTED FOR A REASON, whoever is making it. Which
  // ROUTE it then travels on still depends on what this user holds, and
  // [_cancelOrder] is the one place that decides; see [misCancelReason] for why
  // the prompt and the route are deliberately two different questions.
  if (picked == 'Cancelled') {
    // The stage sheet above was awaited, so the screen may be gone; a reason
    // form opened against a dead context is a form nobody can dismiss.
    if (!context.mounted) return;
    if (await _cancelOrder(context, rest: rest, profile: profile, orderId: orderId, value: value)) {
      reload();
    }
    return;
  }
  try {
    if (picked == 'Barked') {
      await rest.post('/orders/$orderId/bark');
    } else {
      await rest.patch('/orders/$orderId/status', {'status': picked});
    }
    reload();
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

// ---------------------------------------------------------- kitchen display ----

// Kitchen display: live tickets (station-filterable, with course holds) plus an
// expo/pass view consolidating each table's ready-vs-pending items.
Widget kdsModule(RestClient rest, Profile p) => _KdsHome(rest: rest);

// True when the order item is a HELD course (waiting to be fired).
// The one held-course predicate, shared with the local KOT copy's totals.
bool _itemHeld(Map m) => kotLineHeld(m);

// "Barked" step: un-barked orders sit greyed with idle timers until the expo
// barks them to the kitchen. Missing field (older backend) counts as barked.
bool _orderBarked(Map o) => !o.containsKey('barked_at') || o['barked_at'] != null;

// Small uppercase station tag for an order item (KOT routing) — the quiet
// recessed InfoChip pill from the template.
Widget _stationBadge(String station) => InfoChip(label: station.toUpperCase());

/// Column count for the kitchen board. Deliberately COARSER than the 4/3/2/1
/// grid the rest of the app uses: a ticket's whole point is its item list, every
/// line of which must stay readable at arm's length without a tap, so a column
/// is never allowed below ~500px — the width a "12 × Paneer Butter Masala"
/// line plus its station tag, timer and serve controls actually needs. The board
/// therefore tops out at 3 across where Orders would already be at 4.
int _kdsColumns(double width) => width >= 1620 ? 3 : (width >= 1100 ? 2 : 1);

class _KdsHome extends StatefulWidget {
  final RestClient rest;
  const _KdsHome({required this.rest});

  @override
  State<_KdsHome> createState() => _KdsHomeState();
}

class _KdsHomeState extends State<_KdsHome> {
  bool _expo = false;
  String _station = 'All';
  // Locked mode: dedicate this tablet to a single section. Other chips + the
  // Tickets/Expo switch hide, and only the locked section's items show — until
  // staff explicitly unlock.
  bool _locked = false;
  // Managed kitchen sections (from /restaurant/settings) — drive the filter
  // chips even before any ticket carries the station. Best-effort: on failure
  // the chips fall back to ticket-derived stations only.
  List<String> _managed = const [];
  // Which outlet these tickets come from + the live count per outlet, so an
  // empty board can say "they're in the other branch" instead of just "none"
  // (the KDS reads the same outlet-scoped /orders as the Orders grid).
  Map<String, dynamic> _scope = const {};

  @override
  void initState() {
    super.initState();
    widget.rest.getMap('/restaurant/settings').then((s) {
      final list = ((s['kitchen_sections'] as List?) ?? const [])
          .map((e) => '$e'.trim())
          .where((e) => e.isNotEmpty)
          .toList();
      if (mounted && list.isNotEmpty) setState(() => _managed = list);
    }).catchError((_) {});
    _loadOrdersScope(widget.rest).then((s) {
      if (mounted && s.isNotEmpty) setState(() => _scope = s);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(children: [
      // The Tickets/Expo switch hides while locked so the tablet stays pinned to
      // its zone's tickets.
      if (!_locked)
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 14, 16, 0),
          child: Row(children: [
            ForkTabs(
              tabs: const ['Tickets', 'Expo / Pass'],
              selected: _expo ? 1 : 0,
              onSelected: (i) => setState(() => _expo = i == 1),
            ),
            const Spacer(),
          ]),
        ),
      Expanded(child: (!_locked && _expo) ? _ExpoView(rest: widget.rest) : _ticketsView()),
    ]);
  }

  Widget _ticketsView() => AsyncView<List>(
        load: () => widget.rest.getList('/orders'),
        // The KDS is a wall-mounted board nobody touches, so it must refresh
        // itself — a new, barked or served order used to sit invisible until staff
        // left the module and came back. There is no realtime push for the kitchen
        // anywhere in the product, so polling is the only honest option; the fix
        // was making the poll SILENT (AsyncView.pollEvery), because ticking a
        // plain reload swapped the whole board for the loading skeleton every ten
        // seconds and threw a scrolled-to cook back to ticket one.
        pollEvery: const Duration(seconds: 10),
        builder: (context, rows, reload) {
          // Pending orders are NOT yet approved → they must not reach the kitchen.
          final active = rows.where((o) {
            final s = _s(o as Map, 'status', 'Preparing').toLowerCase();
            return s != 'closed' && s != 'paid' && s != 'cancelled' && s != 'pending';
          }).toList();
          // Chips = union of the MANAGED section list (settings order first)
          // and the stations present on active tickets (legacy labels).
          final stations = <String>{};
          for (final o in active) {
            for (final it in ((o as Map)['items'] as List? ?? const [])) {
              final st = _s(it as Map, 'station');
              if (st.isNotEmpty) stations.add(st);
            }
          }
          final seen = {for (final m in _managed) m.toLowerCase()};
          final extras = stations.where((s) => !seen.contains(s.toLowerCase())).toList()..sort();
          final chips = ['All', ..._managed, ...extras];
          // While locked, keep the locked section selected even if its chip has
          // temporarily no active tickets (so the lock doesn't snap back to All).
          final selected = _locked && _station != 'All'
              ? _station
              : (chips.contains(_station) ? _station : 'All');
          final text = Theme.of(context).textTheme;
          bool itemMatches(Map it) => selected == 'All' || _s(it, 'station').toLowerCase() == selected.toLowerCase();
          final visible = active
              .where((o) => ((o as Map)['items'] as List? ?? const []).any((it) => itemMatches(it as Map)))
              .toList();
          return Column(children: [
            if (_locked && selected != 'All')
              // Locked banner: only this section shows; other chips are hidden.
              Container(
                width: double.infinity,
                margin: const EdgeInsets.fromLTRB(16, 12, 16, 0),
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                decoration: BoxDecoration(
                  color: AppColors.tint(AppColors.copper),
                  borderRadius: AppRadius.controlAll,
                  border: Border.all(color: AppColors.edge(AppColors.copper)),
                ),
                child: Row(children: [
                  Icon(Icons.lock, size: 16, color: AppColors.copperHi),
                  const SizedBox(width: AppSpacing.sm),
                  Expanded(
                    child: Text('LOCKED TO ${selected.toUpperCase()}',
                        overflow: TextOverflow.ellipsis,
                        style: text.labelSmall!.copyWith(color: AppColors.copperHi)),
                  ),
                  ForkButton.ghost(
                    label: 'Unlock',
                    icon: Icons.lock_open,
                    dense: true,
                    onPressed: () => setState(() => _locked = false),
                  ),
                ]),
              )
            else if (chips.length > 1)
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
                child: Row(children: [
                  Expanded(
                    child: ForkTabs(
                      tabs: chips,
                      selected: chips.indexOf(selected),
                      onSelected: (i) => setState(() => _station = chips[i]),
                    ),
                  ),
                  const SizedBox(width: AppSpacing.sm),
                  // Lock the current section for a dedicated single-zone tablet.
                  ForkIconButton(
                    icon: Icons.lock_outline,
                    tooltip: selected == 'All' ? 'Pick a section to lock' : 'Lock to $selected',
                    onPressed: selected == 'All' ? null : () => setState(() => _locked = true),
                  ),
                ]),
              ),
            Expanded(
              child: visible.isEmpty
                  ? (selected == 'All'
                      ? _outletScopeEmpty(
                          context,
                          scope: _scope,
                          noun: 'kitchen tickets',
                          icon: Icons.soup_kitchen_outlined,
                          title: 'No active kitchen tickets',
                          caption: 'Approved orders appear here for the kitchen to work.',
                          mentionHistory: false,
                        )
                      : _empty('No active tickets for $selected.'))
                  : ListView(
                      padding: const EdgeInsets.all(16),
                      children: [
                        _dashGrid([
                          for (final o in visible)
                            _KdsCard(
                              key: ValueKey('kds-${(o as Map)['id']}'),
                              order: o,
                              rest: widget.rest,
                              reload: reload,
                              station: selected,
                            ),
                        ], _kdsColumns(MediaQuery.sizeOf(context).width)),
                      ],
                    ),
            ),
          ]);
        },
      );
}

// Expo/pass screen: one card per active table with ready-vs-pending counts and
// item chips coloured by state (green served / amber preparing / grey held).
// The pass refreshes itself on the same silent ten-second tick as the ticket
// board (AsyncView.pollEvery) — it is the same wall-mounted screen on another
// tab, and it had the identical skeleton flash. Stateless because the timer now
// belongs to the view it refreshes, which is also what stops it from firing
// against a disposed State once staff switch back to Tickets.
class _ExpoView extends StatelessWidget {
  final RestClient rest;
  const _ExpoView({required this.rest});

  // Per-item pass chip — tinted pill whose state always ships with a label
  // (· HOLD / · NOT BARKED), never colour alone.
  Widget _expoChip(Map it) {
    final status = _s(it, 'status', 'preparing');
    final color = status == 'served'
        ? AppColors.success
        : (status == 'held' || status == 'unbarked' ? AppColors.neutral : AppColors.warning);
    final station = _s(it, 'station');
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
      decoration: BoxDecoration(
        color: AppColors.tint(color),
        border: Border.all(color: AppColors.edge(color)),
        borderRadius: BorderRadius.circular(999),
      ),
      child: Text(
        '${it['qty'] ?? 1}× ${it['name'] ?? ''}'
        '${station.isNotEmpty ? ' · ${station.toUpperCase()}' : ''}'
        '${status == 'held' ? ' · HOLD' : (status == 'unbarked' ? ' · NOT BARKED' : '')}',
        style: TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w600,
          letterSpacing: 0.2,
          color: Color.lerp(color, Colors.white, 0.25),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) => AsyncView<Map<String, dynamic>>(
        load: () => rest.getMap('/kds/expo'),
        pollEvery: const Duration(seconds: 10),
        builder: (context, data, reload) {
          final tables = (data['tables'] as List?) ?? [];
          if (tables.isEmpty) return _empty('No active tables on the pass.');
          final text = Theme.of(context).textTheme;
          return RefreshIndicator(
            onRefresh: () async => reload(),
            // Same coarse tiling as the ticket board: a pass card is read the
            // same way a ticket is, and every item chip stays on it.
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.all(16),
              children: [
                _dashGrid([
                  for (final r in tables)
                    Builder(builder: (context) {
                      final t = r as Map;
                      final items = (t['items'] as List?) ?? [];
                      final ready = (t['ready_count'] as num?)?.toInt() ?? 0;
                      final pending = (t['pending_count'] as num?)?.toInt() ?? 0;
                      return ForkCard(
                        padding: const EdgeInsets.all(16),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Row(children: [
                            Expanded(
                              child: Text('Table ${_s(t, 'table')}',
                                  style: text.titleMedium, overflow: TextOverflow.ellipsis),
                            ),
                            StatusChip(label: '$ready ready', color: AppColors.success, dense: true),
                            const SizedBox(width: 6),
                            StatusChip(
                                label: '$pending pending',
                                color: pending > 0 ? AppColors.warning : AppColors.neutral,
                                dense: true),
                          ]),
                          const SizedBox(height: AppSpacing.md),
                          Wrap(spacing: 6, runSpacing: 6, children: [for (final it in items) _expoChip(it as Map)]),
                        ]),
                      );
                    }),
                ], _kdsColumns(MediaQuery.sizeOf(context).width)),
              ],
            ),
          );
        },
      );
}

// Live elapsed (ms) for a timing timer map, mirroring the backend computation.
int _elapsedMs(Map t) {
  final startStr = t['started_at'];
  if (startStr == null) return 0;
  final start = DateTime.tryParse('$startStr')?.millisecondsSinceEpoch;
  if (start == null) return 0;
  final nowMs = DateTime.now().millisecondsSinceEpoch;
  final end = t['ended_at'] != null ? (DateTime.tryParse('${t['ended_at']}')?.millisecondsSinceEpoch ?? nowMs) : nowMs;
  int paused = (t['paused_ms'] is num) ? (t['paused_ms'] as num).toInt() : 0;
  if (t['paused'] == true && t['pause_started_at'] != null) {
    final ps = DateTime.tryParse('${t['pause_started_at']}')?.millisecondsSinceEpoch;
    if (ps != null) paused += nowMs - ps;
  }
  final e = end - start - paused;
  return e < 0 ? 0 : e;
}

String _fmtDur(int ms) {
  final s = (ms / 1000).floor();
  final m = s ~/ 60;
  final sec = s % 60;
  return m > 0 ? '${m}m ${sec.toString().padLeft(2, '0')}s' : '${sec}s';
}

// A kitchen ticket with live order + per-item timers, pause/resume, mark-served,
// station tags and held-course firing. [station] filters the visible items.
class _KdsCard extends StatefulWidget {
  final Map order;
  final RestClient rest;
  final VoidCallback reload;
  final String station;
  const _KdsCard({super.key, required this.order, required this.rest, required this.reload, this.station = 'All'});

  @override
  State<_KdsCard> createState() => _KdsCardState();
}

class _KdsCardState extends State<_KdsCard> {
  Timer? _ticker;

  @override
  void initState() {
    super.initState();
    _ticker = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _ticker?.cancel();
    super.dispose();
  }

  Map get _timing => (widget.order['timing'] as Map?) ?? const {};
  Map get _orderTimer => (_timing['order'] as Map?) ?? const {};
  Map get _itemTimers => (_timing['items'] as Map?) ?? const {};

  Future<void> _post(String path) async {
    try {
      await widget.rest.post(path);
      widget.reload();
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Fire a held course item: fired_at is stamped and its prep timer starts.
  Future<void> _fire(String orderId, String itemId) async {
    try {
      await widget.rest.post('/orders/$orderId/fire', {'item_ids': [itemId]});
      widget.reload();
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final o = widget.order;
    final id = '${o['id']}';
    final items = ((o['items'] as List?) ?? [])
        .where((it) => widget.station == 'All' || _s(it as Map, 'station').toLowerCase() == widget.station.toLowerCase())
        .toList();
    final status = _s(o, 'status', 'Preparing');
    // Terminal stage: the ticket is a record only — no fire/serve/hold/bark.
    // (The tickets list already filters cancelled orders out; this keeps the
    // card safe if it is ever rendered from another feed.)
    final cancelled = _isCancelled(status);
    // Un-barked tickets are greyed with idle timers until the expo barks them.
    final barked = _orderBarked(o);
    final orderPaused = _orderTimer['paused'] == true;
    final orderMs = _elapsedMs(_orderTimer);
    final text = Theme.of(context).textTheme;
    // Elapsed escalation: quiet under 10 minutes, warning past 10, danger past
    // 15 — idle (un-barked / paused) timers stay neutral.
    // The thresholds moved to [_elapsedColor] so the floor's D2 timers and this
    // one cannot drift apart; the rule itself is unchanged, including the
    // un-barked / paused case staying neutral.
    final timerColor = _elapsedColor(orderMs, idle: !barked || orderPaused);
    // B1 — the number the kitchen calls this ticket by. It is the handle for a
    // reprint, a cancellation and a move, and until now the board never showed
    // it: a cook holding a docket that says "KOT 218" had no way to find the
    // matching card. Empty when the backend sends no `kot_nos` (tenant without
    // the migration, or an older server), and the identity line below is then
    // omitted entirely rather than drawn blank.
    final kotLabel = _kotLabel(o);
    // A3 — the wall-clock instant the ticket was PLACED. The chip in the header
    // counts elapsed minutes, which answers "how late is this" but never "when
    // did this land": at a shift handover, or when the pass is reconciling
    // against a stack of printed dockets, elapsed time is useless and the clock
    // time is the only thing that matches the paper. Deliberately the SAME
    // formatter the Orders module uses for the same field, so one ticket reads
    // identically on both screens.
    final placedLabel = _fmtTime(_s(o, 'created_at', ''));
    // Ticket lines read at arm's length across the pass.
    final lineStyle = text.bodyLarge!.copyWith(fontSize: 15, height: 1.35);
    final qtyStyle = text.bodyLarge!.copyWith(fontSize: 15, fontWeight: FontWeight.w600, color: AppColors.copperHi);

    final card = ForkCard(
      padding: const EdgeInsets.all(16),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // Expanded, not Flexible + Spacer: on a narrow docket column the table
        // name gives way to the timer and the stage, never the reverse.
        Row(children: [
          Expanded(
            child: Text('Table ${_s(o, 'table')}',
                style: text.titleMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
          ),
          const SizedBox(width: AppSpacing.sm),
          if (barked)
            StatusChip(
              label: orderPaused ? '${_fmtDur(orderMs)} · held' : _fmtDur(orderMs),
              color: timerColor,
              dense: true,
            )
          else
            const InfoChip(icon: Icons.campaign_outlined, label: 'Idle timer'),
          const SizedBox(width: AppSpacing.sm),
          AnimatedSwitcher(
            duration: AppDurations.base,
            switchInCurve: Curves.easeOut,
            switchOutCurve: Curves.easeIn,
            child: StatusChip(
              // Cancelled outranks the bark state — the terminal stage must read
              // first on the ticket.
              key: ValueKey(cancelled || barked ? status : 'Not barked'),
              label: cancelled || barked ? status : 'Not barked',
              color: cancelled || barked ? _stageColor(status) : AppColors.neutral,
              dense: true,
            ),
          ),
        ]),
        // Ticket identity: which KOT this is, and when it was placed. Sits on
        // its own line under the header because the header row already gives
        // way to the timer and the stage, and a fourth chip there would start
        // eating the table name — the one thing on a kitchen card that must
        // never truncate.
        //
        // Each half appears only when its data does, so a card whose order
        // carries neither gains nothing at all and renders exactly as before.
        if (kotLabel.isNotEmpty || placedLabel.isNotEmpty)
          Padding(
            padding: const EdgeInsets.only(top: AppSpacing.sm),
            child: Wrap(
              spacing: AppSpacing.sm,
              runSpacing: 6,
              children: [
                if (kotLabel.isNotEmpty)
                  InfoChip(icon: Icons.receipt_long_outlined, label: kotLabel),
                if (placedLabel.isNotEmpty)
                  InfoChip(icon: Icons.access_time, label: 'Placed $placedLabel'),
              ],
            ),
          ),
        const SizedBox(height: AppSpacing.md),
        if (_s(o, 'order_type', 'dine_in') != 'dine_in')
          Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: Row(children: [
              InfoChip(
                icon: _s(o, 'order_type') == 'delivery' ? Icons.pedal_bike_outlined : Icons.shopping_bag_outlined,
                label: _s(o, 'order_type') == 'delivery' ? 'DELIVERY' : 'TAKEAWAY',
              ),
              const SizedBox(width: AppSpacing.sm),
              Expanded(
                child: Text(
                  [
                    if (_s(o, 'customer').isNotEmpty && _s(o, 'customer') != 'Guest') _s(o, 'customer'),
                    if (_s(o, 'customer_phone').isNotEmpty) _s(o, 'customer_phone'),
                    if (_s(o, 'delivery_address').isNotEmpty) _s(o, 'delivery_address'),
                  ].join(' · '),
                  style: text.bodySmall,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ]),
          ),
        if (_s(o, 'note').isNotEmpty)
          Container(
            width: double.infinity,
            margin: const EdgeInsets.only(bottom: 10),
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            decoration: BoxDecoration(
              color: AppColors.tint(AppColors.warning),
              borderRadius: AppRadius.controlAll,
              border: Border.all(color: AppColors.warning.withValues(alpha: 0.18)),
            ),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Icon(Icons.sticky_note_2_outlined, size: 14, color: AppColors.warning),
              const SizedBox(width: 7),
              Expanded(
                child: Text(
                  _s(o, 'note'),
                  style: text.bodySmall!.copyWith(color: Color.lerp(AppColors.warning, Colors.white, 0.45)),
                ),
              ),
            ]),
          ),
        ...items.map((it) {
          final m = it as Map;
          final iid = '${m['id']}';
          final t = (_itemTimers[iid] as Map?) ?? const {};
          final served = t['ended_at'] != null;
          final paused = t['paused'] == true;
          final held = !served && _itemHeld(m);
          final ms = _elapsedMs(t);
          final itemNote = _s(m, 'note', '');
          final stationLabel = _s(m, 'station');
          return Padding(
            padding: const EdgeInsets.symmetric(vertical: 2),
            child: AnimatedOpacity(
              duration: AppDurations.base,
              curve: Curves.easeOut,
              opacity: (held || !barked || cancelled) ? 0.55 : 1,
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Expanded(
                    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text('${m['quantity'] ?? 1} ×', style: qtyStyle),
                      const SizedBox(width: 7),
                      // Narrowing the ticket must never cost the chef a dish
                      // name: the name WRAPS onto as many lines as it needs
                      // (no ellipsis, no "+3 more") and the tags flow after it.
                      // The card grows downwards instead — a docket is tall.
                      Expanded(
                        child: Wrap(
                          spacing: 6,
                          runSpacing: 4,
                          crossAxisAlignment: WrapCrossAlignment.center,
                          children: [
                            Text('${m['name'] ?? ''}',
                                style: lineStyle.copyWith(
                                  decoration: served ? TextDecoration.lineThrough : null,
                                  color: (served || held) ? AppColors.textSecondary : null,
                                )),
                            if (stationLabel.isNotEmpty) _stationBadge(stationLabel),
                          ],
                        ),
                      ),
                    ]),
                  ),
                  if (cancelled)
                    // Cancelled is final — no per-item fire / pause / serve.
                    const SizedBox.shrink()
                  else if (!barked)
                    // Nothing cooks (and nothing ages) before the bark.
                    const SizedBox.shrink()
                  else if (held)
                    // Held courses do not age; the timer starts when fired.
                    ForkButton(
                      label: 'Fire',
                      icon: Icons.local_fire_department,
                      dense: true,
                      onPressed: () => _fire(id, iid),
                    )
                  else ...[
                    Text(
                      _fmtDur(ms),
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                        letterSpacing: 0.2,
                        color: served ? AppColors.success : AppColors.textSecondary,
                      ),
                    ),
                    if (!served) ...[
                      IconButton(
                        visualDensity: VisualDensity.compact,
                        icon: Icon(paused ? Icons.play_arrow : Icons.pause, size: 18, color: AppColors.textSecondary),
                        tooltip: paused ? 'Resume item' : 'Pause item',
                        onPressed: () => _post('/orders/$id/items/$iid/${paused ? 'resume' : 'pause'}'),
                      ),
                      IconButton(
                        visualDensity: VisualDensity.compact,
                        icon: Icon(Icons.check, size: 18, color: AppColors.success),
                        tooltip: 'Item served',
                        // `undo=0` states the intent instead of letting the
                        // server infer it from state. This branch only renders
                        // for an UNSERVED item, so the tap means serve — and if
                        // it is queued offline and replayed after someone else
                        // served it, it must stay a serve rather than becoming
                        // an un-serve. The undo control below posts /unserve,
                        // which was always explicit.
                        onPressed: () => _post('/orders/$id/items/$iid/serve?undo=0'),
                      ),
                    ] else ...[
                      // A served item used to render a DEAD icon, so a mis-tapped
                      // tick could never be walked back. It is now the undo control.
                      // Once the whole order is Served the server refuses the undo,
                      // so the button is disabled rather than failing on tap.
                      Builder(builder: (_) {
                        final orderServed = status.toLowerCase() != 'preparing' && status.toLowerCase() != 'pending';
                        return IconButton(
                          visualDensity: VisualDensity.compact,
                          icon: Icon(Icons.check_circle,
                              size: 18,
                              color: orderServed ? AppColors.textSecondary : AppColors.success),
                          tooltip: orderServed
                              ? 'The whole order is served — individual items can no longer be undone'
                              : 'Undo served',
                          onPressed: orderServed ? null : () => _post('/orders/$id/items/$iid/unserve'),
                        );
                      }),
                    ],
                  ],
                ]),
                // ROUND 2 ITEM 2 — the hold hangs UNDER the dish, in the note's
                // slot and style and ahead of the note, the way the docket prints
                // it. It was a HOLD chip beside the name; on paper it is now a
                // line under the dish, and the pass should read one shape.
                if (held)
                  Padding(
                    key: ValueKey('kds-item-hold-$iid'),
                    padding: const EdgeInsets.only(left: 8, bottom: 2),
                    child: Row(children: [
                      Icon(Icons.front_hand_outlined, size: 13, color: AppColors.warning),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Text(
                          kotHoldLine,
                          style: text.bodySmall!.copyWith(
                            fontStyle: FontStyle.italic,
                            fontWeight: FontWeight.w600,
                            color: Color.lerp(AppColors.warning, Colors.white, 0.35),
                          ),
                        ),
                      ),
                    ]),
                  ),
                if (itemNote.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(left: 8, bottom: 2),
                    child: Row(children: [
                      Icon(Icons.sticky_note_2_outlined, size: 13, color: AppColors.warning),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Text(
                          itemNote,
                          style: text.bodySmall!.copyWith(
                            fontStyle: FontStyle.italic,
                            color: Color.lerp(AppColors.warning, Colors.white, 0.35),
                          ),
                        ),
                      ),
                    ]),
                  ),
              ]),
            ),
          );
        }),
        const SizedBox(height: 14),
        // Bump / serve / hold stay ON the ticket — a chef mid-service cannot be
        // sent through a sheet — so on a narrow docket column they wrap onto a
        // second line instead of being squeezed or dropped.
        Row(crossAxisAlignment: CrossAxisAlignment.center, children: [
          if (cancelled)
            // Read-only footer: the caption replaces every stage action, and the
            // reason travels with it. Printing the KOT stays available (no write).
            Expanded(
              child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Icon(Icons.lock_outline, size: 14, color: AppColors.danger),
                const SizedBox(width: 6),
                Expanded(
                  child: Text(_cancelledCaption,
                      style: text.bodySmall!.copyWith(color: AppColors.danger)),
                ),
              ]),
            )
          else
            Expanded(
              child: Wrap(
                spacing: AppSpacing.sm,
                runSpacing: 8,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [
                  if (!barked)
                    ForkButton(
                      label: 'Bark to kitchen',
                      icon: Icons.campaign,
                      onPressed: () => _barkOrder(ScaffoldMessenger.of(context), widget.rest, id, widget.reload),
                    )
                  else if (status.toLowerCase() == 'preparing')
                    ForkButton(
                      label: 'Mark Served',
                      icon: Icons.room_service_outlined,
                      onPressed: () =>
                          _advanceOrder(ScaffoldMessenger.of(context), widget.rest, id, 'Served', widget.reload),
                    )
                  else
                    ForkButton.ghost(
                      label: 'Back to Preparing',
                      icon: Icons.undo,
                      onPressed: () =>
                          _advanceOrder(ScaffoldMessenger.of(context), widget.rest, id, 'Preparing', widget.reload),
                    ),
                  if (barked)
                    ForkButton.ghost(
                      label: orderPaused ? 'Resume' : 'Hold',
                      icon: orderPaused ? Icons.play_arrow : Icons.pause,
                      onPressed: () => _post('/orders/$id/${orderPaused ? 'resume' : 'pause'}'),
                    ),
                ],
              ),
            ),
          const SizedBox(width: AppSpacing.sm),
          // THE REPRINT. Barking now prints the docket by itself, so this is no
          // longer how a ticket reaches the kitchen — it is how a kitchen with a
          // jammed or out-of-paper printer asks for the SAME docket again. It
          // carries the number already on paper, because the server keys a KOT
          // on its contents (migration 029) and an unchanged order resolves to
          // the ticket it already minted.
          //
          // Shown only once the order is barked (before that there is no docket
          // to reprint) and only where thermal printing can actually happen:
          // winspool does not exist on Android, and a control that cannot work
          // on the platform showing it is a bug, not a convenience.
          if (barked && PrinterService.instance.supported) ...[
            ForkIconButton(
              icon: Icons.replay_outlined,
              tooltip: 'Reprint kitchen docket',
              onPressed: () => _reprintKot(ScaffoldMessenger.of(context), widget.rest, id),
            ),
            const SizedBox(width: AppSpacing.sm),
          ],
          ForkIconButton(
            icon: Icons.print_outlined,
            tooltip: 'Print KOT (local PDF copy)',
            onPressed: () => _printKot({...o, 'items': items}),
          ),
        ]),
      ]),
    );

    // Subtle urgency glow once the ticket ages into warning/danger — always
    // paired with the labelled timer chip above (never colour alone).
    return AnimatedContainer(
      duration: AppDurations.slow,
      curve: Curves.easeOut,
      decoration: BoxDecoration(
        borderRadius: AppRadius.cardAll,
        boxShadow: [
          if (timerColor != AppColors.neutral)
            BoxShadow(
              color: timerColor.withValues(alpha: 0.09),
              blurRadius: 22,
              spreadRadius: 1,
            ),
        ],
      ),
      child: card,
    );
  }
}

/// CANCEL AN ORDER — requirement A2's single entry point.
///
/// THE ONE RULE, WRITTEN ONCE. Every way of cancelling an order in this app
/// comes through here: the Decline on a pending ticket, and the stage sheet's
/// "Cancelled". There used to be two paths with the permission test written out
/// at each of them, which is precisely the shape that let a cancel escape
/// without a reason — a second call site added later would have inherited "no
/// prompt" by omission, the same way the fifteen controls on the table sheet
/// inherited "visible".
///
/// THE PROMPT IS UNCONDITIONAL; THE ROUTE IS NOT. See [misCancelReason] for why
/// those are two different questions and why routing every cancel through the
/// strict void would break cancelling on a floor with no wifi.
///
/// Returns true when the order was cancelled, false when the user backed out or
/// the write failed — so the caller reloads only when something changed.
Future<bool> _cancelOrder(
  BuildContext context, {
  required RestClient rest,
  required Profile? profile,
  required String orderId,
  String what = 'this order',
  String value = '',
}) async {
  final messenger = ScaffoldMessenger.of(context);
  // WHOEVER CAN GIVE THE FULLER ANSWER IS ASKED FOR IT. The void form records a
  // kind, a reason AND an authoriser against the order in one transaction, which
  // is what the Void KOT report is built to read.
  if (profile != null && _mayDo(profile, Capability.voidOrder, _permVoidOrder)) {
    return misVoidOrder(context, rest: rest, profile: profile, orderId: orderId,
        what: what, value: value);
  }
  final why = await misCancelReason(context, what: what, value: value);
  // BACKING OUT CANCELS NOTHING. "Mandatory" has to cut both ways: a dialog that
  // cancelled the order anyway when it was dismissed would be a prompt in name.
  if (why == null) return false;
  try {
    // `reason` and `cancel_kind` are ADDITIVE on a route that is on the offline
    // allowlist and stays there. A server that does not read them behaves
    // exactly as it does today; one that does gets the banner text for the
    // cancellation slip and the reason for the control report.
    await rest.patch('/orders/$orderId/status', {
      'status': 'Cancelled',
      'reason': why.reason,
      'cancel_kind': why.kind,
    });
    return true;
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
    return false;
  }
}

Future<void> _advanceOrder(
  ScaffoldMessengerState messenger,
  RestClient rest,
  String orderId,
  String status,
  VoidCallback reload,
) async {
  try {
    await rest.patch('/orders/$orderId/status', {'status': status});
    reload();
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

// Bark an order to the kitchen: stamps barked_at and starts the prep timers
// (they stay idle until the bark).
Future<void> _barkOrder(
  ScaffoldMessengerState messenger,
  RestClient rest,
  String orderId,
  VoidCallback reload,
) async {
  try {
    final res = await rest.post('/orders/$orderId/bark');
    reload();
    // WHAT THE WAITER IS TOLD. Barking now also prints the docket, and "barked"
    // and "the kitchen has paper" are different facts — a bare tick that meant
    // either one would be the same silent-drop shape durable printing was built
    // to remove. So the response's own report is read back: the KOT number when
    // there is one, and an explicit warning when the docket did not go out.
    final map = res is Map ? res : const {};
    final kotNo = map['kot_no'];
    if (map['kot_printed'] == true) {
      messenger.showSnackBar(SnackBar(
          content: Text(kotNo == null ? 'Sent to the kitchen.' : 'Sent to the kitchen - KOT-$kotNo')));
    } else if (map['kot_skipped'] == 'disabled') {
      // Auto-print is deliberately off for this restaurant; nothing is wrong.
      messenger.showSnackBar(const SnackBar(content: Text('Sent to the kitchen.')));
    } else if (map.containsKey('kot_printed')) {
      messenger.showSnackBar(const SnackBar(
          content: Text('Sent to the kitchen, but the docket did not print. Use Reprint.')));
    }
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

/// Ask the server for one order's kitchen docket again.
///
/// A REPRINT IN THE STRICT SENSE. POST /print/kot/order/:id rebuilds the docket
/// from the order's own lines and re-resolves its ticket key, so an unchanged
/// order comes back with the number already on paper (`reprint: true`) instead
/// of burning the next one in the day's series. That is what lets a jammed
/// printer be answered without the pass ending up with two numbers for one
/// order.
Future<void> _reprintKot(
  ScaffoldMessengerState messenger,
  RestClient rest,
  String orderId,
) async {
  try {
    final res = await rest.post('/print/kot/order/$orderId');
    final map = res is Map ? res : const {};
    final kotNo = map['kot_no'];
    final tickets = (map['tickets'] as num?)?.toInt() ?? 1;
    final where = tickets > 1 ? ' ($tickets station tickets)' : '';
    messenger.showSnackBar(SnackBar(
        content: Text(kotNo == null ? 'Docket sent to the printer$where' : 'KOT-$kotNo sent again$where')));
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

// THE HOLD LINE, THE NOTE LINE AND THE ITEM BLOCK now live in
// models/kot_copy.dart (kotHoldLine, kotNoteLine, kotDocket, kotCopyRows): pure,
// so the kitchen board, this copy and their tests read one definition.

/// THE LOCAL KOT COPY AS A PDF — [kotCopyRows] drawn in the pdf package's
/// default font, in a column as wide as an 80mm roll prints (72mm).
///
/// ONE TYPE SIZE FOR EVERY LINE, as on the reference docket, where emphasis is
/// WEIGHT: "KOT", the service mode, the table and each dish name are bold, and
/// nothing is set larger or in italics. 10pt is the docket's own standard size
/// (28 dots per em at the printer's 203 dpi is 9.9pt), so the copy matches the
/// paper the client approved rather than a document. It does NOT follow the
/// restaurant's KOT text size — that setting sizes the kitchen docket, and this
/// is a copy for whoever pressed the button.
///
/// A character the default font cannot draw (a rupee sign, say) prints as the
/// pdf package's placeholder box rather than failing the copy.
///
/// `pageFormat` is whatever the print dialog chose: on A4 the column sits at the
/// top left; on a roll it fills the paper.
@visibleForTesting
pw.Document kotCopyPdf(
  List<KotCopyRow> rows, {
  PdfPageFormat pageFormat = PdfPageFormat.a4,
  bool compress = true,
}) {
  const size = 10.0;
  const regular = pw.TextStyle(fontSize: size);
  final bold = pw.TextStyle(fontSize: size, fontWeight: pw.FontWeight.bold);
  // THE COLUMNS ARE SIZED TO WHAT THEY HOLD, as the docket's are: the number
  // column to the widest dish number (so item 100 cannot print over its dish),
  // the quantity column to the widest quantity or "Qty". A digit in the default
  // font is 0.56em wide; the gutter after the number is 0.4em, as on the docket.
  var numChars = 1;
  var qtyChars = 3;
  for (final r in rows) {
    if (r.kind != KotCopyKind.columns) continue;
    if (r.text.isNotEmpty) numChars = math.max(numChars, r.no.length);
    qtyChars = math.max(qtyChars, r.qty.length);
  }
  final numW = numChars * 0.56 * size + 0.4 * size;
  final qtyW = qtyChars * 0.6 * size;
  pw.Widget draw(KotCopyRow r) {
    switch (r.kind) {
      case KotCopyKind.rule:
        // 0.8pt is two and a half dots on a 203 dpi roll: a thinner dash can
        // drop out entirely when the page is scaled onto thermal paper.
        return pw.Divider(height: 8, thickness: 0.8, borderStyle: pw.BorderStyle.dashed);
      case KotCopyKind.line:
        return pw.Container(
          alignment: r.centred ? pw.Alignment.center : pw.Alignment.centerLeft,
          padding: const pw.EdgeInsets.symmetric(vertical: 1),
          child: pw.Text(r.text,
              style: r.bold ? bold : regular, textAlign: r.centred ? pw.TextAlign.center : pw.TextAlign.left),
        );
      case KotCopyKind.under:
        return pw.Padding(
          padding: pw.EdgeInsets.only(left: numW, bottom: 1),
          child: pw.Text(r.text, style: regular),
        );
      case KotCopyKind.columns:
        final qty = pw.SizedBox(width: qtyW, child: pw.Text(r.qty, style: regular, textAlign: pw.TextAlign.right));
        return pw.Padding(
          padding: const pw.EdgeInsets.symmetric(vertical: 1),
          child: r.text.isEmpty
              // The heading and the totals: the left cell runs into the name
              // column ("No.Item", "Total Qty"), as it does on the docket.
              ? pw.Row(children: [pw.Expanded(child: pw.Text(r.no, style: regular)), qty])
              : pw.Row(crossAxisAlignment: pw.CrossAxisAlignment.start, children: [
                  pw.SizedBox(width: numW, child: pw.Text(r.no, style: regular)),
                  pw.Expanded(child: pw.Text(r.text, style: r.bold ? bold : regular)),
                  qty,
                ]),
        );
    }
  }

  final doc = pw.Document(compress: compress);
  doc.addPage(
    pw.Page(
      pageFormat: pageFormat,
      build: (ctx) => pw.Align(
        alignment: pw.Alignment.topLeft,
        child: pw.SizedBox(
          width: math.min(72 * PdfPageFormat.mm, pageFormat.availableWidth),
          child: pw.Column(
            crossAxisAlignment: pw.CrossAxisAlignment.stretch,
            mainAxisSize: pw.MainAxisSize.min,
            children: [for (final r in rows) draw(r)],
          ),
        ),
      ),
    ),
  );
  return doc;
}

/// A LOCAL PDF copy of one order's kitchen ticket, laid out like the reference
/// docket the backend renders (escpos.ts `layoutKot`) so a chef reads the same
/// shape whichever came off the printer — see models/kot_copy.dart for the line
/// order and for what it leaves out.
///
/// IT DELIBERATELY CARRIES NO "KOT - n" NUMBER, and says so on the paper.
/// The day-scoped ticket number is allocated server-side, inside the same
/// transaction that memoises it (migration 029 / AllocateKotNumber), because
/// that is the only place it can be made unique per outlet-day, gapless under
/// concurrent tills, and stable across a reprint. A number invented on this
/// device would satisfy none of those and would collide with the real series the
/// moment a second till printed. So this copy is honest about being unnumbered
/// rather than quietly printing a number the kitchen cannot trust.
///
/// This ticket also covers ONE ORDER — the lines the board is showing for it,
/// station filter and all — whereas a thermal KOT covers the table's whole
/// running order set.
Future<void> _printKot(Map order) async {
  // Printed tickets leave the screen, so they carry the zone explicitly.
  final rows = kotCopyRows(order, stamp: RestaurantTime.stampNow());
  await Printing.layoutPdf(
      onLayout: (PdfPageFormat format) => kotCopyPdf(rows, pageFormat: format).save());
}

/// A quantity as a person writes it: 5 not 5.0, 2.5 stays 2.5.
String _stockNum(double? v) {
  if (v == null) return '';
  return v == v.roundToDouble() ? '${v.round()}' : '$v';
}

/// Stock tint, in the shared status voice: label + tint, never colour alone.
/// Top-level so a drill-down sheet tints an item exactly as its row does.
///
/// The STATUS ITSELF is never computed here. It comes from the server, which
/// decides it from the quantity, the item's unit AND its reorder level (the
/// backend's inventory_units module). This app deliberately holds no copy of
/// that rule — a second copy is how the old one drifted, and it is why 5000 mg
/// of potato used to read "In Stock" while 5 kg of it read "Low Stock".
Color _inventoryStockColor(String status) {
  final s = status.toLowerCase();
  if (s.contains('out')) return AppColors.danger;
  if (s.contains('low')) return AppColors.warning;
  return AppColors.success;
}

/// The ledger movements for ONE item, asked for only when its sheet opens.
///
/// GET /inventory returns levels and no history, and putting a second call on
/// the module's load would slow a screen that renders perfectly without it. So
/// the history is fetched here, once, and a failure degrades to a sentence
/// rather than taking the sheet down — the levels above it are still the answer
/// to most of why the sheet was opened.
class _ItemMovements extends StatefulWidget {
  const _ItemMovements({required this.rest, required this.inventoryId, required this.unit});

  final RestClient rest;
  final String inventoryId;
  final String unit;

  @override
  State<_ItemMovements> createState() => _ItemMovementsState();
}

class _ItemMovementsState extends State<_ItemMovements> {
  static const int _max = 6;

  List<Map> _rows = const [];
  bool _loading = true;
  bool _failed = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      // The route's own default window is 30 days; stating it keeps the heading
      // above this list honest if that default ever moves.
      final from = RestaurantTime.isoDate(
          RestaurantTime.nowWall().subtract(const Duration(days: 29)));
      final r = await widget.rest.getMap('/inventory/movements?from=$from');
      final mine = <Map>[
        for (final m in (r['movements'] as List?) ?? const [])
          if (m is Map && '${m['inventory_id']}' == widget.inventoryId) m,
      ];
      if (!mounted) return;
      setState(() {
        _rows = mine.length > _max ? mine.sublist(0, _max) : mine;
        _loading = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _failed = true;
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    if (_loading) {
      return const Padding(
        padding: EdgeInsets.symmetric(vertical: AppSpacing.sm),
        child: Column(children: [
          SkeletonBox(height: 14, radius: 6),
          SizedBox(height: AppSpacing.sm),
          SkeletonBox(height: 14, radius: 6),
        ]),
      );
    }
    if (_failed) {
      return Text('Movement history is unavailable right now.',
          style: text.bodySmall?.copyWith(color: AppColors.textTertiary));
    }
    if (_rows.isEmpty) {
      return Text('Nothing received, issued or wasted in this window.',
          style: text.bodySmall?.copyWith(color: AppColors.textTertiary));
    }
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      for (final r in _rows)
        _detailRow(
          context,
          // The reason is the whole point of a wastage line, so it rides with
          // the kind rather than being dropped for width.
          [
            _s(r, 'kind', 'movement'),
            if (_s(r, 'reason', '').isNotEmpty) _s(r, 'reason', ''),
          ].join(' · '),
          '${_numOf(r['delta']) > 0 ? '+' : ''}${_score(r['delta'])}'
          '${widget.unit.isEmpty ? '' : ' ${widget.unit}'}',
          trailing: _s(r, 'created_at', '').isEmpty ? null : RestaurantTime.day(_s(r, 'created_at')),
        ),
    ]);
  }
}

/// One stock item in full: what the row shows, plus the two things it has no
/// column for — the expiry and the recent ledger — and the two stock actions
/// the row's own menu already offers.
///
/// The jump is offered only for an item that is actually short: a purchase
/// order is the next step for those and for nothing else, and an always-on jump
/// would be an affordance pointing nowhere useful.
Future<void> _inventoryItemSheet(
    BuildContext context, RestClient rest, Map item, VoidCallback reload) {
  final text = Theme.of(context).textTheme;
  final status = _s(item, 'status', 'In Stock');
  final colour = _inventoryStockColor(status);
  final short = colour != AppColors.success;
  final unit = _s(item, 'unit', '');
  final category = _s(item, 'category', '').trim();
  final expiry = _s(item, 'expiry_date', '').trim();
  final reorderApplied = double.tryParse('${item['reorder_applied'] ?? ''}');

  String? expiryNote;
  final due = expiry.isEmpty ? null : DateTime.tryParse(expiry);
  if (due != null) {
    final now = RestaurantTime.nowWall();
    final days = DateTime(due.year, due.month, due.day)
        .difference(DateTime(now.year, now.month, now.day))
        .inDays;
    expiryNote = days < 0 ? '${-days}d ago' : (days == 0 ? 'today' : 'in ${days}d');
  }

  return _detailSheet(
    context,
    eyebrow: 'Inventory',
    title: _s(item, 'name'),
    jumpTo: short ? 'Purchase Orders' : null,
    children: [
      Align(alignment: Alignment.centerLeft, child: StatusChip(label: status, color: colour)),
      const SizedBox(height: AppSpacing.md),
      _detailRow(context, 'On hand', '${item['stock'] ?? 0}${unit.isEmpty ? '' : ' $unit'}'),
      // What the badge above was decided against, in this item's own unit, so
      // "Low Stock" on 50 g is explicable instead of mysterious. Suppressed for
      // a unit the server could not classify (basis 'legacy'), where there is no
      // meaningful level to quote.
      if (reorderApplied != null && _s(item, 'reorder_basis', '') != 'legacy')
        _detailRow(
          context,
          _s(item, 'reorder_basis', '') == 'item' ? 'Reorder at' : 'Reorder at (default)',
          '${_stockNum(reorderApplied)}${unit.isEmpty ? '' : ' $unit'}',
        ),
      _detailRow(context, 'Category', category.isEmpty ? 'Uncategorised' : category),
      _detailRow(context, 'Expiry', expiry.isEmpty ? 'Not set' : RestaurantTime.day(expiry),
          trailing: expiryNote),
      const SizedBox(height: AppSpacing.lg),
      Text('MOVEMENTS · LAST 30 DAYS', style: text.labelSmall),
      const SizedBox(height: 6),
      _ItemMovements(rest: rest, inventoryId: '${item['id'] ?? ''}', unit: unit),
      const SizedBox(height: AppSpacing.lg),
      // Closed first: both of these open a dialog of their own, and stacking a
      // second one over a sheet that is about to be stale reads as a bug.
      Builder(
        builder: (ctx) => Wrap(spacing: AppSpacing.sm, runSpacing: AppSpacing.sm, children: [
          ForkButton.ghost(
            label: 'Receive stock',
            icon: Icons.add,
            dense: true,
            onPressed: () {
              Navigator.pop(ctx);
              _receiveStock(context, rest, item, reload);
            },
          ),
          ForkButton.ghost(
            label: 'Record wastage',
            icon: Icons.delete_outline,
            dense: true,
            onPressed: () {
              Navigator.pop(ctx);
              _recordWastage(context, rest, item, reload);
            },
          ),
          // Editing the threshold goes through its OWN endpoint, never through
          // the add-item upsert: that one writes "Quantity" from the form, so it
          // would stamp a stale stock figure over any movement recorded while
          // this sheet was open. A threshold edit must not move stock.
          ForkButton.ghost(
            label: 'Reorder level',
            icon: Icons.speed_outlined,
            dense: true,
            onPressed: () {
              Navigator.pop(ctx);
              _setReorderLevel(context, rest, item, reload);
            },
          ),
        ]),
      ),
    ],
  );
}

/// A named set of stock items — a category, or everything at one status — with
/// each line a way into that item's own sheet.
Future<void> _inventoryListSheet(
  BuildContext context,
  RestClient rest,
  VoidCallback reload, {
  required String eyebrow,
  required String title,
  required List<Map> items,
  List<Widget> lead = const [],
  String? jumpTo,
}) {
  final text = Theme.of(context).textTheme;
  return _detailSheet(
    context,
    eyebrow: eyebrow,
    title: title,
    jumpTo: jumpTo,
    children: [
      ...lead,
      if (items.isEmpty)
        Text('Nothing in this set.', style: text.bodySmall?.copyWith(color: AppColors.textTertiary))
      else
        Builder(
          builder: (ctx) => Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            for (final it in items)
              _TapRow(
                onTap: () {
                  Navigator.pop(ctx);
                  _inventoryItemSheet(context, rest, it, reload);
                },
                child: _detailRow(
                  context,
                  _s(it, 'name'),
                  '${it['stock'] ?? 0} ${_s(it, 'unit', '')}'.trim(),
                  trailing: _s(it, 'status', 'In Stock'),
                ),
              ),
          ]),
        ),
    ],
  );
}

Widget inventoryModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () async {
        final items = await rest.getList('/inventory');
        // Managed inventory categories drive the add-item picker + the manage
        // dialog. Optional — items still render if settings can't be read.
        List<String> categories = const [];
        try {
          final s = await rest.getMap('/restaurant/settings');
          categories = ((s['inventory_categories'] as List?) ?? const [])
              .map((e) => '$e'.trim())
              .where((e) => e.isNotEmpty)
              .toList();
        } catch (_) {/* categories unavailable — items still render */}
        return {'items': items, 'categories': categories};
      },
      builder: (context, data, reload) {
        final rows = (data['items'] as List?) ?? const [];
        final categories = List<String>.from(data['categories'] as List? ?? const []);
        final text = Theme.of(context).textTheme;
        final narrow = MediaQuery.sizeOf(context).width < 760;

        List<Map> atStatus(Color want) => [
              for (final r in rows)
                if (_inventoryStockColor(_s(r as Map, 'status', 'In Stock')) == want) r,
            ];
        final low = atStatus(AppColors.warning);
        final out = atStatus(AppColors.danger);
        final lowCount = low.length;
        final outCount = out.length;

        // --- Sections -------------------------------------------------------
        // Stock is segregated by CATEGORY, which is the tenant's own stored
        // roster (`inventory_categories` on the restaurant settings, managed by
        // the Categories dialog and cascaded on rename by
        // POST /inventory-categories/rename) — not a grouping invented on this
        // device. Same shape as the floor's zones: the roster is unioned with
        // the labels the items themselves carry, so a category that exists but
        // holds nothing still gets a heading, and an item labelled with a
        // category that has since left the roster is never hidden.
        //
        // Keyed case-insensitively because that is how the rename/dedupe path
        // treats a category name; the first spelling seen wins the casing.
        // Uncategorised always renders LAST, so nothing is buried.
        final byKey = <String, List<Map>>{};
        final sectionLabel = <String, String>{};
        for (final r in rows) {
          final m = r as Map;
          final c = _s(m, 'category', '').trim();
          final key = c.toLowerCase();
          byKey.putIfAbsent(key, () => <Map>[]).add(m);
          if (c.isNotEmpty) sectionLabel.putIfAbsent(key, () => c);
        }
        for (final c in categories) {
          final name = c.trim();
          if (name.isEmpty) continue;
          byKey.putIfAbsent(name.toLowerCase(), () => <Map>[]);
          sectionLabel.putIfAbsent(name.toLowerCase(), () => name);
        }
        final namedKeys = byKey.keys.where((k) => k.isNotEmpty).toList()..sort();
        final orderedKeys = <String>[...namedKeys, if (byKey.containsKey('')) ''];

        // Flattened in render order so the list stays lazy: one entry per
        // heading, one per item. [item] null marks the heading.
        final entries = <({String key, Map? item})>[];
        for (final key in orderedKeys) {
          entries.add((key: key, item: null));
          for (final m in byKey[key] ?? const <Map>[]) {
            entries.add((key: key, item: m));
          }
        }

        String labelOf(String key) =>
            key.isEmpty ? 'Uncategorised' : (sectionLabel[key] ?? key);

        int shortIn(String key) => [
              for (final m in byKey[key] ?? const <Map>[])
                if (_inventoryStockColor(_s(m, 'status', 'In Stock')) != AppColors.success) m,
            ].length;

        // One category, whole: every item in it with its level, each a way into
        // that item's own sheet. This is what a section heading "opens".
        Future<void> openSection(String key) {
          final members = byKey[key] ?? const <Map>[];
          final short = shortIn(key);
          return _inventoryListSheet(
            context,
            rest,
            reload,
            eyebrow: 'Stock section',
            title: labelOf(key),
            items: members,
            lead: [
              _detailRow(context, 'Items', '${members.length}'),
              _detailRow(context, 'Need restocking', '$short'),
              const SizedBox(height: AppSpacing.md),
            ],
            jumpTo: short == 0 ? null : 'Purchase Orders',
          );
        }

        // How the tracked total splits across the roster — the one figure the
        // page holds but never states, because reading it means scrolling every
        // heading. Each line opens that section.
        Future<void> sectionBreakdown() => _detailSheet(
              context,
              eyebrow: 'Inventory',
              title: '${rows.length} items tracked',
              children: [
                Builder(
                  builder: (ctx) => Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                    for (final key in orderedKeys)
                      _TapRow(
                        onTap: () {
                          Navigator.pop(ctx);
                          openSection(key);
                        },
                        child: _detailRow(
                          context,
                          labelOf(key),
                          '${(byKey[key] ?? const <Map>[]).length}',
                          trailing: shortIn(key) == 0 ? null : '${shortIn(key)} short',
                        ),
                      ),
                  ]),
                ),
              ],
            );

        // Manage the tenant's inventory categories (add/rename/delete). Rename
        // cascades onto items server-side, so reload to refresh when changed.
        Future<void> manageCategories() async {
          final changed = await showDialog<bool>(
            context: context,
            builder: (_) => _InventoryCategoriesDialog(rest: rest, isAdmin: p.isAdmin, initial: categories),
          );
          if (changed == true) reload();
        }

        return Scaffold(
        backgroundColor: Colors.transparent,
        floatingActionButton: FloatingActionButton.extended(
          onPressed: () => _addInventory(context, rest, categories, p.isAdmin, reload),
          icon: const Icon(Icons.add),
          label: const Text('Add item'),
        ),
        body: Column(children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
            // Wrap, not Row+Spacer: the buttons are non-flex, so a Row hands
            // them unbounded width and overflows once a 1.3x scale grows the
            // labels past a phone width. A Wrap drops them to a second run.
            child: Wrap(
              alignment: WrapAlignment.end,
              spacing: AppSpacing.sm,
              runSpacing: AppSpacing.sm,
              children: [
                ForkButton.ghost(
                  label: 'Categories',
                  icon: Icons.category_outlined,
                  dense: true,
                  onPressed: manageCategories,
                ),
                ForkButton.ghost(
                  label: 'Vendors',
                  icon: Icons.local_shipping_outlined,
                  dense: true,
                  onPressed: () => _manageVendors(context, rest),
                ),
              ],
            ),
          ),
          Expanded(
            // Sections created before any stock is entered are a real state —
            // don't hide the roster behind "no inventory", the way the floor
            // plan hid an empty zone before it read the section list.
            child: rows.isEmpty && namedKeys.isEmpty
                ? const EmptyState(
                    icon: Icons.inventory_2_outlined,
                    title: 'No inventory yet',
                    caption: 'Add your first stock item to start tracking levels.',
                  )
                : ListView.builder(
                    padding: AppSpacing.pageNarrow,
                    itemCount: entries.length + 1,
                    itemBuilder: (c, i) {
                      if (i == 0) {
                        // Low-stock summary from the rows already loaded.
                        return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          _dashGrid([
                            StatCard(
                              value: '${rows.length}',
                              caption: 'ITEMS TRACKED',
                              // The page only answers "how is stock spread across
                              // the categories?" by scrolling the whole list, so
                              // the tile that states the total carries the split.
                              onTap: sectionBreakdown,
                            ),
                            StatCard(
                              value: '$lowCount',
                              caption: 'LOW STOCK',
                              tag: lowCount > 0 ? 'Lo' : null,
                              tagColor: AppColors.warning,
                              // Zero low items has no list behind it. An inert
                              // tile is honest; a tap onto "Nothing in this set"
                              // is not.
                              onTap: lowCount == 0
                                  ? null
                                  : () => _inventoryListSheet(
                                        context,
                                        rest,
                                        reload,
                                        eyebrow: 'Inventory',
                                        title: 'Low stock',
                                        items: low,
                                        jumpTo: 'Purchase Orders',
                                      ),
                            ),
                            StatCard(
                              value: '$outCount',
                              caption: 'OUT OF STOCK',
                              tag: outCount > 0 ? 'Out' : null,
                              tagColor: AppColors.danger,
                              onTap: outCount == 0
                                  ? null
                                  : () => _inventoryListSheet(
                                        context,
                                        rest,
                                        reload,
                                        eyebrow: 'Inventory',
                                        title: 'Out of stock',
                                        items: out,
                                        jumpTo: 'Purchase Orders',
                                      ),
                            ),
                          ], narrow ? 1 : 3),
                          const SizedBox(height: AppSpacing.xxl),
                          SectionHeader(
                            title: 'Stock levels',
                            count: rows.length,
                            trailing: Text(
                              '${namedKeys.length} section${namedKeys.length == 1 ? '' : 's'}',
                              style: text.bodySmall,
                            ),
                          ),
                          Text(
                            'Grouped by category — manage the list with Categories above.',
                            style: text.bodySmall,
                          ),
                        ]);
                      }
                      final entry = entries[i - 1];
                      final it = entry.item;
                      if (it == null) {
                        final members = byKey[entry.key] ?? const <Map>[];
                        final short = shortIn(entry.key);
                        final header = SectionHeader(
                          title: labelOf(entry.key),
                          count: members.length,
                          padding: const EdgeInsets.only(bottom: 8),
                          trailing: short == 0
                              ? null
                              : StatusChip(
                                  label: '$short need${short == 1 ? 's' : ''} restocking',
                                  color: AppColors.warning,
                                  dense: true,
                                ),
                        );
                        return Padding(
                          padding: const EdgeInsets.only(top: AppSpacing.lg),
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            // A saved-but-empty category has no section to open,
                            // so its heading stays inert rather than offering a
                            // tap onto an empty list.
                            if (members.isEmpty)
                              header
                            else
                              _TapRow(onTap: () => openSection(entry.key), child: header),
                            // A category on the roster with nothing in it is a
                            // real, saved category — say so rather than letting
                            // the empty heading read as a glitch.
                            if (members.isEmpty)
                              Padding(
                                padding: const EdgeInsets.only(bottom: 10),
                                child: Text('Nothing in this section yet.', style: text.bodySmall),
                              ),
                          ]),
                        );
                      }
                      final status = _s(it, 'status', 'In Stock');
                      final color = _inventoryStockColor(status);
                      final attention = color != AppColors.success;
                      final card = ForkCard(
                        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                        // The row states the level; the sheet adds the expiry and
                        // the ledger it has no column for. The "..." menu keeps
                        // both stock actions exactly where they were — a card tap
                        // never moves stock.
                        onTap: () => _inventoryItemSheet(context, rest, it, reload),
                        child: Row(children: [
                          AnimatedContainer(
                            duration: AppDurations.base,
                            curve: Curves.easeOut,
                            width: 38,
                            height: 38,
                            decoration: BoxDecoration(
                              color: attention ? AppColors.tint(color) : AppColors.inset,
                              borderRadius: AppRadius.controlAll,
                              border: Border.all(color: attention ? AppColors.edge(color) : AppColors.border),
                            ),
                            child: Icon(Icons.inventory_2_outlined,
                                size: 16, color: attention ? color : AppColors.textTertiary),
                          ),
                          const SizedBox(width: AppSpacing.md),
                          Expanded(
                            // The category chip that used to sit under the name
                            // is now the heading this row lives under, so it is
                            // not repeated on every card.
                            child: Text(_s(it, 'name'),
                                style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                          ),
                          const SizedBox(width: AppSpacing.md),
                          // The stat and the pill are non-flex by default, so a
                          // Row hands them unbounded width and the card
                          // overflows on a phone. Flexed as a pair, they get a
                          // bound to ellipsise against and the name keeps its
                          // share.
                          Flexible(
                            child: Row(mainAxisSize: MainAxisSize.min, children: [
                              Flexible(
                                child: MicroStat(
                                  value: '${it['stock'] ?? 0} ${_s(it, 'unit', '')}'.trim(),
                                  label: 'on hand',
                                  alignEnd: true,
                                ),
                              ),
                              const SizedBox(width: 14),
                              Flexible(child: StatusChip(label: status, color: color, dense: narrow)),
                            ]),
                          ),
                          PopupMenuButton<String>(
                            tooltip: 'Stock',
                            iconColor: AppColors.textSecondary,
                            onSelected: (v) {
                              if (v == 'receive') _receiveStock(context, rest, it, reload);
                              if (v == 'wastage') _recordWastage(context, rest, it, reload);
                            },
                            itemBuilder: (_) => const [
                              PopupMenuItem(value: 'receive', child: Text('Receive stock')),
                              PopupMenuItem(value: 'wastage', child: Text('Record wastage')),
                            ],
                          ),
                        ]),
                      );
                      // Tinted ring once an item needs attention — always paired
                      // with the labelled StatusChip above (never colour alone).
                      return Padding(
                        padding: const EdgeInsets.only(bottom: 10),
                        child: AnimatedContainer(
                          duration: AppDurations.slow,
                          curve: Curves.easeOut,
                          decoration: BoxDecoration(
                            borderRadius: AppRadius.cardAll,
                            boxShadow: [
                              if (attention)
                                BoxShadow(
                                  color: color.withValues(alpha: 0.09),
                                  blurRadius: 22,
                                  spreadRadius: 1,
                                ),
                            ],
                          ),
                          child: card,
                        ),
                      );
                    },
                  ),
          ),
        ]),
      );
      },
    );

// Receive stock for an item (purchase) → increments + logs a movement.
Future<void> _receiveStock(BuildContext context, RestClient rest, Map item, VoidCallback reload) async {
  final messenger = ScaffoldMessenger.of(context);
  final qty = TextEditingController();
  final cost = TextEditingController();
  List vendors = const [];
  try { final v = await rest.getMap('/vendors'); vendors = (v['vendors'] as List?) ?? const []; } catch (_) {}
  if (!context.mounted) return;
  String? vendorId;
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setLocal) => AlertDialog(
        title: Text('Receive · ${_s(item, 'name')}'),
        content: Column(mainAxisSize: MainAxisSize.min, children: [
          TextField(controller: qty, autofocus: true, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Quantity received', border: OutlineInputBorder())),
          const SizedBox(height: 8),
          if (vendors.isNotEmpty)
            DropdownButtonFormField<String>(
              initialValue: vendorId,
              isExpanded: true,
              decoration: const InputDecoration(labelText: 'Vendor (optional)', border: OutlineInputBorder()),
              items: [for (final v in vendors) DropdownMenuItem(value: '${(v as Map)['id']}', child: Text(_s(v, 'name')))],
              onChanged: (x) => setLocal(() => vendorId = x),
            ),
          const SizedBox(height: 8),
          TextField(controller: cost, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Unit cost (optional)', border: OutlineInputBorder())),
        ]),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Receive')),
        ],
      ),
    ),
  );
  if (ok != true) return;
  final q = double.tryParse(qty.text.trim()) ?? 0;
  if (q <= 0) { messenger.showSnackBar(const SnackBar(content: Text('Enter a valid quantity.'))); return; }
  final c = double.tryParse(cost.text.trim()) ?? 0;
  final body = <String, dynamic>{'inventory_id': item['id'], 'qty': q};
  if (vendorId != null) body['vendor_id'] = vendorId;
  if (c > 0) body['unit_cost'] = c;
  try {
    await rest.post('/inventory/receive', body);
    reload();
  } catch (e) { messenger.showSnackBar(SnackBar(content: Text('$e'))); }
}

// Record wastage for an item → decrements + logs a movement.
Future<void> _recordWastage(BuildContext context, RestClient rest, Map item, VoidCallback reload) async {
  final messenger = ScaffoldMessenger.of(context);
  final qty = TextEditingController();
  final reason = TextEditingController();
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: Text('Wastage · ${_s(item, 'name')}'),
      content: Column(mainAxisSize: MainAxisSize.min, children: [
        TextField(controller: qty, autofocus: true, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Quantity wasted', border: OutlineInputBorder())),
        const SizedBox(height: 8),
        TextField(controller: reason, decoration: const InputDecoration(labelText: 'Reason (optional)', border: OutlineInputBorder())),
      ]),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), style: FilledButton.styleFrom(backgroundColor: AppColors.danger), child: const Text('Log wastage')),
      ],
    ),
  );
  if (ok != true) return;
  final q = double.tryParse(qty.text.trim()) ?? 0;
  if (q <= 0) { messenger.showSnackBar(const SnackBar(content: Text('Enter a valid quantity.'))); return; }
  try {
    await rest.post('/inventory/wastage', {'inventory_id': item['id'], 'qty': q, if (reason.text.trim().isNotEmpty) 'reason': reason.text.trim()});
    reload();
  } catch (e) { messenger.showSnackBar(SnackBar(content: Text('$e'))); }
}

Future<void> _manageVendors(BuildContext context, RestClient rest) =>
    showModalBottomSheet<void>(context: context, isScrollControlled: true, builder: (_) => _VendorsSheet(rest: rest));

class _VendorsSheet extends StatefulWidget {
  final RestClient rest;
  const _VendorsSheet({required this.rest});
  @override
  State<_VendorsSheet> createState() => _VendorsSheetState();
}

class _VendorsSheetState extends State<_VendorsSheet> {
  List _vendors = const [];
  bool _loading = true;
  final _name = TextEditingController();
  final _phone = TextEditingController();

  @override
  void initState() { super.initState(); _load(); }

  @override
  void dispose() { _name.dispose(); _phone.dispose(); super.dispose(); }

  Future<void> _load() async {
    try {
      final v = await widget.rest.getMap('/vendors');
      if (mounted) setState(() { _vendors = (v['vendors'] as List?) ?? const []; _loading = false; });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _add() async {
    final messenger = ScaffoldMessenger.of(context);
    if (_name.text.trim().isEmpty) return;
    try {
      await widget.rest.post('/vendors', {'name': _name.text.trim(), if (_phone.text.trim().isNotEmpty) 'phone': _phone.text.trim()});
      _name.clear(); _phone.clear();
      await _load();
    } catch (e) { messenger.showSnackBar(SnackBar(content: Text('$e'))); }
  }

  Future<void> _del(String id) async {
    final messenger = ScaffoldMessenger.of(context);
    try { await widget.rest.delete('/vendors/$id'); await _load(); }
    catch (e) { messenger.showSnackBar(SnackBar(content: Text('$e'))); }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return Container(
      decoration: BoxDecoration(
        color: AppColors.surface,
        borderRadius: BorderRadius.vertical(top: Radius.circular(AppRadius.card)),
        border: Border(top: BorderSide(color: AppColors.borderStrong)),
      ),
      padding: EdgeInsets.only(
          left: AppSpacing.xl,
          right: AppSpacing.xl,
          top: AppSpacing.xl,
          bottom: AppSpacing.xl + MediaQuery.of(context).viewInsets.bottom),
      child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        const SectionHeader(title: 'Vendors', padding: EdgeInsets.only(bottom: 12)),
        Row(children: [
          Expanded(child: TextField(controller: _name, decoration: const InputDecoration(hintText: 'Vendor name', isDense: true, border: OutlineInputBorder()))),
          const SizedBox(width: AppSpacing.sm),
          SizedBox(width: 110, child: TextField(controller: _phone, decoration: const InputDecoration(hintText: 'Phone', isDense: true, border: OutlineInputBorder()))),
          const SizedBox(width: AppSpacing.sm),
          ForkButton(label: 'Add', icon: Icons.add, onPressed: _add),
        ]),
        const SizedBox(height: AppSpacing.md),
        if (_loading)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: AppSpacing.md),
            child: Column(children: [
              for (var i = 0; i < 3; i++)
                const Padding(
                  padding: EdgeInsets.only(bottom: AppSpacing.sm),
                  child: Row(children: [
                    SkeletonBox(width: 32, height: 32, radius: 8),
                    SizedBox(width: AppSpacing.md),
                    Expanded(child: SkeletonBox(height: 12)),
                  ]),
                ),
            ]),
          )
        else if (_vendors.isEmpty)
          Padding(
            padding: const EdgeInsets.all(AppSpacing.md),
            child: Text('No vendors yet — add your first supplier above.', style: text.bodySmall),
          )
        else
          Flexible(
            child: ListView(shrinkWrap: true, children: [
              for (final v in _vendors)
                Padding(
                  padding: const EdgeInsets.only(bottom: AppSpacing.sm),
                  child: ForkCard(
                    inset: true,
                    padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                    child: Row(children: [
                      Container(
                        width: 34,
                        height: 34,
                        decoration: BoxDecoration(
                          color: AppColors.inset,
                          borderRadius: AppRadius.controlAll,
                          border: Border.all(color: AppColors.border),
                        ),
                        child: Icon(Icons.local_shipping_outlined, size: 16, color: AppColors.copper),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      Expanded(
                        child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(_s(v as Map, 'name'),
                                  style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                              if (_s(v, 'phone').isNotEmpty) ...[
                                const SizedBox(height: 2),
                                Text(_s(v, 'phone'), style: text.bodySmall),
                              ],
                            ]),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      ForkIconButton(
                        icon: Icons.delete_outline,
                        tooltip: 'Delete vendor',
                        onPressed: () => _del('${v['id']}'),
                      ),
                    ]),
                  ),
                ),
            ]),
          ),
      ]),
    );
  }
}

String _guestInitials(String name) {
  final parts = name.trim().split(RegExp(r'\s+')).where((s) => s.isNotEmpty).toList();
  if (parts.isEmpty) return '?';
  return parts.length == 1
      ? parts.first.substring(0, 1)
      : '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}';
}

/// The three ways the guest book can be ranked — server sort key, the label the
/// owner reads, and the figure the leaderboards put beside a name.
const List<List<String>> _customerSorts = [
  ['recent', 'Most recent'],
  ['spend', 'Most spent'],
  ['visits', 'Most visited'],
];

/// The server's own segmentation. Counts come off `segment_counts`, which spans
/// the whole filtered set rather than the loaded page.
const List<List<String>> _customerSegments = [
  ['all', 'All guests'],
  ['new', 'New'],
  ['regular', 'Regular'],
  ['high-spend', 'High spend'],
  ['dormant', 'Dormant'],
];

String _customerSortLabel(String key) =>
    _customerSorts.firstWhere((s) => s[0] == key, orElse: () => const ['', ''])[1];

String _customerSegmentLabel(String key) =>
    _customerSegments.firstWhere((s) => s[0] == key, orElse: () => const ['', ''])[1];

/// The one figure a ranking is about, so a "most spent" list is never headed by
/// a number that came from a different measure.
String _customerRankValue(Map m, String sort) => switch (sort) {
      'spend' => _money(m['total_spend']),
      'visits' => '${_int(m['visits']) ?? 0} visit${(_int(m['visits']) ?? 0) == 1 ? '' : 's'}',
      _ => _s(m, 'last_visit', '').isEmpty ? 'never' : _fmtDay(_s(m, 'last_visit', '')),
    };

/// The guest book: an overview band ranking the whole filtered set three ways,
/// and the full list underneath sorted and segmented by the same controls.
///
/// EVERY ranking and every page comes from GET /customers/segments, which sorts
/// and pages in SQL. Re-sorting a loaded page in the client would produce a
/// "most spent" list that is really "most spent among the first fifty", and it
/// would start lying the moment a restaurant has more guests than one page.
Widget customersModule(RestClient rest, Profile p) => _CustomersView(rest: rest);

class _CustomersView extends StatefulWidget {
  final RestClient rest;
  const _CustomersView({required this.rest});
  @override
  State<_CustomersView> createState() => _CustomersViewState();
}

class _CustomersViewState extends State<_CustomersView> with CachePrimedScreen {
  static const int _pageSize = 50;
  // How many names a leaderboard card shows.
  static const int _leaderSize = 5;

  final List<Map> _rows = [];
  final Set<String> _ids = {};
  final ScrollController _scroll = ScrollController();
  final TextEditingController _searchField = TextEditingController();

  // Leaderboards, keyed by sort. Each is its own server-ranked request over the
  // SAME segment and search as the list, so the band answers "who tops this
  // filter" and not "who tops the page".
  final Map<String, List<Map>> _leaders = {};
  // Per-ranking failures, so a card that could not be built says why instead of
  // rendering as an empty leaderboard.
  final Map<String, String> _leaderErrors = {};
  bool _leadersLoading = false;

  bool _loading = true;
  bool _loadingMore = false;
  bool _hasMore = false;
  int _total = 0;
  String? _error;
  // Per-segment counts, and the search they were taken under.
  //
  // The server computes `segment_counts` over the set AFTER its own segment
  // filter, so a response for segment=regular reports 0 dormant guests — true of
  // that response, and a flat lie on a tab that is meant to say how many dormant
  // guests exist. So only an UNSEGMENTED response updates these, and they are
  // only shown while the search they were taken under is still in force.
  Map<String, int> _counts = const {};
  String? _countsQuery;
  String _spendBasis = '';

  String _sort = 'recent';
  String _segment = 'all';
  String _query = '';
  Timer? _debounce;

  @override
  void initState() {
    super.initState();
    _scroll.addListener(_onScroll);
    unawaited(primeFromCache(
      // The list AND the three leaderboards: painting the band as loading
      // skeletons next to an instant list would read as half a screen.
      fetch: () async {
        final page = await _fetchPage(offset: 0);
        final leaders = await _fetchLeaders();
        return (page: page, leaders: leaders);
      },
      apply: (d) {
        _applyPage(d.page, append: false);
        _applyLeaders(d.leaders);
        _loading = false;
        _error = null;
      },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  @override
  void dispose() {
    _debounce?.cancel();
    _scroll.dispose();
    _searchField.dispose();
    super.dispose();
  }

  String _query4(String sort, {required int limit, required int offset, bool meta = false}) {
    final q = _query.trim();
    return '/customers/segments?limit=$limit&offset=$offset&sort=$sort'
        '${meta ? '&meta=1' : ''}'
        '${_segment == 'all' ? '' : '&segment=${Uri.encodeQueryComponent(_segment)}'}'
        '${q.isEmpty ? '' : '&search=${Uri.encodeQueryComponent(q)}'}';
  }

  /// One page's GET under the CURRENT filters, side-effect free — replayable
  /// against the persisted cache at boot and the network path of every [_load].
  Future<Map<String, dynamic>> _fetchPage({required int offset}) =>
      widget.rest.getMap(_query4(_sort, limit: _pageSize, offset: offset, meta: true));

  /// Merge one page — field assignment only, shared by the cache prime and the
  /// network load so the two paths cannot drift.
  void _applyPage(Map<String, dynamic> res, {required bool append}) {
    final page = <Map>[for (final r in (res['customers'] as List?) ?? const []) if (r is Map) r];
    if (!append) {
      _rows.clear();
      _ids.clear();
    }
    var added = 0;
    for (final r in page) {
      final id = _s(r, 'customer_id', '');
      if (id.isNotEmpty && !_ids.add(id)) continue;
      _rows.add(r);
      added++;
    }
    _total = _int(res['total']) ?? _rows.length;
    _hasMore = res['has_more'] == true && (!append || added > 0);
    if (_s(res, 'segment', 'all') == 'all') {
      _counts = <String, int>{
        for (final e in ((res['segment_counts'] as Map?) ?? const {}).entries)
          '${e.key}': _int(e.value) ?? 0,
      };
      _countsQuery = _query;
    }
    _spendBasis = _s(res, 'spend_basis', '');
  }

  /// One page of the list. [append] extends it; otherwise the list restarts at
  /// offset 0 and the three leaderboards are re-ranked under the new filters.
  /// [silent] keeps what is on screen up while the refetch is in flight.
  Future<void> _load({bool append = false, bool silent = false}) async {
    if (append && (_loadingMore || !_hasMore)) return;
    final gen = bumpCacheGen();
    if (!silent) {
      setState(() {
        if (append) {
          _loadingMore = true;
        } else {
          _loading = true;
          _error = null;
        }
      });
    }
    final offset = append ? _rows.length : 0;
    try {
      final res = await _fetchPage(offset: offset);
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _applyPage(res, append: append);
        _loading = false;
        _loadingMore = false;
        _error = null;
        markCacheLive();
      });
      if (!append) await _loadLeaders(gen);
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      // Only a SILENT refresh keeps the list up behind the offline pill: a
      // loud non-append failure means a filter just changed, and old rows
      // under a new filter would describe neither.
      if (silent && _rows.isNotEmpty) {
        setState(() { _loading = false; _loadingMore = false; markCacheOffline(); });
        return;
      }
      setState(() {
        _error = '$e';
        _loading = false;
        _loadingMore = false;
        if (append) _hasMore = false;
      });
    }
  }

  /// The three server-ranked reads, side-effect free. Each ranking is awaited
  /// on its own so one failure costs one card. A failed card SAYS it failed —
  /// it must not fall back to an empty list, which reads identically to "no
  /// guests match" and would hide a broken endpoint.
  Future<({Map<String, List<Map>> out, Map<String, String> failed})> _fetchLeaders() async {
    final out = <String, List<Map>>{};
    final failed = <String, String>{};
    Future<void> rank(List<String> s) async {
      try {
        final rows = await widget.rest.getList(_query4(s[0], limit: _leaderSize, offset: 0));
        out[s[0]] = [for (final r in rows) if (r is Map) r];
      } catch (e) {
        failed[s[0]] = '$e';
      }
    }

    await Future.wait([for (final s in _customerSorts) rank(s)]);
    return (out: out, failed: failed);
  }

  void _applyLeaders(({Map<String, List<Map>> out, Map<String, String> failed}) d) {
    _leaders
      ..clear()
      ..addAll(d.out);
    _leaderErrors
      ..clear()
      ..addAll(d.failed);
    _leadersLoading = false;
  }

  /// The overview band. Re-ranked whenever the page-one list is (re)loaded.
  Future<void> _loadLeaders(int gen) async {
    setState(() => _leadersLoading = true);
    final d = await _fetchLeaders();
    if (!mounted || !cacheGenIs(gen)) return;
    setState(() => _applyLeaders(d));
  }

  void _onScroll() {
    if (!_scroll.hasClients || _loading || _loadingMore || !_hasMore) return;
    final pos = _scroll.position;
    if (pos.pixels >= pos.maxScrollExtent - 400) _load(append: true);
  }

  /// Sort, segment and search all share one rule: the request restarts at offset
  /// 0, the loaded rows are dropped, and the leaderboards are re-ranked. A list
  /// that kept its old rows under a new sort would be ordered by neither.
  void _applyFilter(VoidCallback change) {
    setState(() {
      change();
      _rows.clear();
      _ids.clear();
      _total = 0;
      _hasMore = false;
      _leaders.clear();
      _leaderErrors.clear();
    });
    _load();
  }

  void _onSearchChanged(String v) {
    _debounce?.cancel();
    _debounce = Timer(const Duration(milliseconds: 300), () {
      final next = v.trim();
      if (!mounted || next == _query) return;
      _applyFilter(() => _query = next);
    });
  }

  /// The number on a segment tab, or null when there is no honest one to show.
  ///
  /// The active tab reports the server's `total` for exactly what is listed
  /// below it. The others can only use counts captured from an unsegmented
  /// response taken under the same search — anything else would be a number
  /// describing a different question.
  int? _segmentCount(String seg) {
    if (seg == _segment) return _total;
    final usable = _countsQuery != null && _countsQuery == _query;
    if (!usable || _counts.isEmpty) return null;
    if (seg == 'all') return _counts.values.reduce((a, b) => a + b);
    return _counts[seg];
  }

  void _guestSheet(Map m) {
    final visits = _int(m['visits']) ?? 0;
    final since = _int(m['days_since_last_visit']);
    final rating = m['avg_rating'];
    final feedbacks = _int(m['feedbacks']) ?? 0;
    _detailSheet(
      context,
      eyebrow: 'Guest book · ${_customerSegmentLabel(_s(m, 'segment', 'all'))}',
      title: _s(m, 'name', 'Guest'),
      children: [
        _kv('Phone', _s(m, 'phone', '')),
        _kv('Email', _s(m, 'email', '')),
        // Straight off the Bookings table on every read, so a booking made a
        // second ago is already in the count — the guest book must never show
        // a guest who just reserved as someone who has never interacted.
        _kv('Bookings made', '${_int(m['bookings_made']) ?? 0}'),
        _kv('Visits', '$visits'),
        _kv('Bills', '${_int(m['bills']) ?? 0}'),
        _kv('Total spent', _money(m['total_spend'])),
        _kv('Average per visit', _money(m['avg_spend_per_visit'])),
        _kv('Of which tax', _money(m['total_tax'])),
        _kv('Of which service charge', _money(m['total_service_charge'])),
        _kv('Pre-tax spend', _money(m['pre_tax_spend'])),
        _kv('Last visit',
            _s(m, 'last_visit', '').isEmpty ? 'Never' : _fmtDay(_s(m, 'last_visit', ''))),
        _kv('Days since', since == null ? '—' : '$since'),
        // Never a bare 0 for "we have no ratings" — the count says which it is.
        _kv('Guest rating',
            rating == null || feedbacks == 0 ? 'No feedback yet' : '${_score(rating)} / 5 from $feedbacks'),
        if (_spendBasis.isNotEmpty) ...[
          const SizedBox(height: 12),
          Text(_spendBasis, style: Theme.of(context).textTheme.bodySmall),
        ],
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final loaded = _rows.length;
    if (Gaia.of(context)) return cacheStaleOverlay(_gaiaBody(context));
    return cacheStaleOverlay(Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
        child: SectionHeader(
          title: 'Guest book',
          // The server's count for the current filters, not how many rows have
          // been paged in.
          count: _loading && loaded == 0 ? null : _total,
          padding: const EdgeInsets.only(bottom: 12),
          trailing: loaded == 0 || loaded >= _total ? null : TickTag('$loaded loaded'),
        ),
      ),
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 10),
        child: TextField(
          controller: _searchField,
          decoration: const InputDecoration(
            prefixIcon: Icon(Icons.search, size: 18),
            hintText: 'Find a guest by name, phone or email…',
            isDense: true,
          ),
          onChanged: _onSearchChanged,
        ),
      ),
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          // One sort control. It orders the leaderboard band AND the list below
          // it, so the two can never disagree about what "most spent" means.
          ForkTabs(
            tabs: [for (final s in _customerSorts) s[1]],
            selected: _customerSorts.indexWhere((s) => s[0] == _sort).clamp(0, _customerSorts.length - 1),
            onSelected: (i) {
              final next = _customerSorts[i][0];
              if (next == _sort) return;
              _applyFilter(() => _sort = next);
            },
          ),
          const SizedBox(height: 10),
          Wrap(spacing: 8, runSpacing: 8, children: [
            for (final seg in _customerSegments)
              _SegmentChip(
                label: seg[1],
                count: _segmentCount(seg[0]),
                selected: _segment == seg[0],
                onTap: () {
                  if (_segment == seg[0]) return;
                  _applyFilter(() => _segment = seg[0]);
                },
              ),
          ]),
        ]),
      ),
      Expanded(child: _body(context)),
    ]));
  }

  // ── GAIA: the BOKEH treatment ─────────────────────────────────────
  //
  // The mockup's own caption is the whole design: "Brightness follows spend and
  // recency: a guest who dined this month glows, a name that only ever booked
  // stays dim." So the guest book becomes a field of out-of-focus light with
  // the people as the points in front of it, and how brightly a guest burns is
  // the DATA — not decoration.
  //
  // Nothing about the loading is different. Same paged GET, same debounce, same
  // three server-side rankings, same three failure states, same guest sheet on
  // a tap. Only the drawing changes.

  /// The brightness rule, applied to the fields `/customers/segments` returns.
  GaiaBokehTone _toneOf(Map m) => gaiaBokehTone(
        visits: _int(m['visits']) ?? 0,
        spend: _numOf(m['total_spend']),
        daysSinceLastVisit: _int(m['days_since_last_visit']),
      );

  Widget _gaiaBody(BuildContext context) {
    final loaded = _rows.length;
    // The field never takes a pointer, so every tap still reaches the list.
    return LayoutBuilder(builder: (context, box) => Stack(children: [
      Positioned.fill(
        child: GaiaBokehBackdrop(
          blobs: GaiaBokehBlob.customers,
          scroll: _scroll,
        ),
      ),
      Positioned.fill(
        child: ListView(
          controller: _scroll,
          padding: _gaiaPagePadding(box.maxWidth),
          children: [
            GaiaPageHeader(
              wordmark: 'Guests',
              meta: _loading && loaded == 0
                  ? 'Loading'
                  : '$_total ${_total == 1 ? 'guest' : 'guests'}'
                      '${loaded == 0 || loaded >= _total ? '' : ' \u00b7 $loaded loaded'}',
              title: 'Guest',
              titleEmphasis: 'book.',
              sub: _spendBasis.isEmpty ? null : 'Spend basis \u00b7 $_spendBasis',
            ),
            GaiaSearchField(
              controller: _searchField,
              hint: 'Find a guest by name, phone or email',
              onChanged: _onSearchChanged,
              onClear: () {
                _searchField.clear();
                _onSearchChanged('');
              },
            ),
            const SizedBox(height: 14),
            Wrap(spacing: 6, runSpacing: 8, children: [
              for (final seg in _customerSegments)
                _GaiaSegmentPill(
                  // The count stays part of the label, so selection is never
                  // the only thing colour is carrying — the same contract the
                  // Rustic `_SegmentChip` holds.
                  label: _segmentCount(seg[0]) == null
                      ? seg[1]
                      : '${seg[1]} \u00b7 ${_segmentCount(seg[0])}',
                  selected: _segment == seg[0],
                  onTap: () {
                    if (_segment == seg[0]) return;
                    _applyFilter(() => _segment = seg[0]);
                  },
                ),
            ]),
            const SizedBox(height: GaiaSpacing.xxl),
            // The three server-ranked leaderboards, kept in full. The mockup
            // shows one ("Most spent") as a hero block; dropping the other two
            // would drop a real answer the screen already computes, so all
            // three render as hero blocks and the loading and per-ranking
            // failure states come with them.
            for (final srt in _customerSorts) ...[
              _gaiaLeader(context, srt[0], srt[1]),
              const SizedBox(height: GaiaSpacing.section),
            ],
            GaiaTabs(
              tabs: [for (final srt in _customerSorts) srt[1]],
              selected: _customerSorts
                  .indexWhere((srt) => srt[0] == _sort)
                  .clamp(0, _customerSorts.length - 1),
              onSelected: (i) {
                final next = _customerSorts[i][0];
                if (next == _sort) return;
                _applyFilter(() => _sort = next);
              },
            ),
            const SizedBox(height: 6),
            ..._gaiaList(context),
            const SizedBox(height: GaiaSpacing.xxl),
            Text(
              'Brightness follows spend and recency: a guest who dined this '
              'month glows, a name that only ever booked stays dim. Every row '
              'prints the figures that decided it.',
              style: GaiaType.italNote(),
            ),
            const SizedBox(height: GaiaSpacing.xl),
            _gaiaPagingFoot(context),
          ],
        ),
      ),
    ]));
  }

  List<Widget> _gaiaList(BuildContext context) {
    if (_loading && _rows.isEmpty) {
      return [
        for (var i = 0; i < 6; i++)
          const Padding(
            padding: EdgeInsets.only(top: 12),
            child: SkeletonBox(height: 62, radius: GaiaRadius.edge),
          ),
      ];
    }
    if (_error != null && _rows.isEmpty) {
      return [
        const SizedBox(height: 28),
        Text("Couldn't load the guest book", style: GaiaType.mid()),
        const SizedBox(height: 8),
        Text(_error!, style: GaiaType.detail(color: GaiaColors.coral)),
        const SizedBox(height: 16),
        Align(
          alignment: Alignment.centerLeft,
          child: GaiaButton(label: 'Retry', dense: true, onPressed: _load),
        ),
      ];
    }
    if (_rows.isEmpty) {
      return [
        const SizedBox(height: 28),
        Text(
          _query.isEmpty && _segment == 'all'
              ? 'No guests on record yet.'
              : 'No guests match these filters.',
          style: GaiaType.italNote(),
        ),
      ];
    }
    return [
      for (var i = 0; i < _rows.length; i++)
        Builder(builder: (context) {
          final m = _rows[i];
          final visits = _int(m['visits']) ?? 0;
          final last = _s(m, 'last_visit', '');
          final phone = _s(m, 'phone', '');
          return GaiaBokehRow(
            first: i == 0,
            initials: _guestInitials(_s(m, 'name', 'Guest')),
            tone: _toneOf(m),
            title: _s(m, 'name', 'Guest'),
            // The two facts the glow is made of, in words, on every row.
            detail: '${last.isEmpty ? 'never visited' : 'last visit ${_fmtDay(last)}'}'
                '${phone.isEmpty || phone == '\u2014' ? '' : ' \u00b7 $phone'}',
            value: _money(m['total_spend']),
            valueUnit: '$visits ${visits == 1 ? 'visit' : 'visits'}',
            valueColor: visits == 0 ? GaiaColors.text3AA : null,
            onTap: () => _guestSheet(m),
          );
        }),
    ];
  }

  /// One ranking of the whole filtered set, drawn as a constellation: the
  /// leader lit large, the runners-up beside them.
  Widget _gaiaLeader(BuildContext context, String sort, String title) {
    final rows = _leaders[sort] ?? const <Map>[];
    final failed = _leaderErrors[sort];
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      GaiaSectionHeader(
        title: title,
        padding: const EdgeInsets.only(bottom: 12),
        trailing: sort == _sort
            ? Text('SORTING THE LIST',
                style: GaiaType.pill(color: GaiaColors.champagneDim))
            : null,
      ),
      if (failed != null)
        Text("Couldn't rank: $failed", style: GaiaType.detail(color: GaiaColors.coral))
      else if (_leadersLoading && rows.isEmpty)
        const SkeletonBox(height: 88, radius: GaiaRadius.edge)
      else if (rows.isEmpty)
        Text('Nothing to rank under these filters.', style: GaiaType.detail())
      else ...[
        GestureDetector(
          onTap: () => _guestSheet(rows.first),
          behavior: HitTestBehavior.opaque,
          child: MouseRegion(
            cursor: SystemMouseCursors.click,
            child: Row(children: [
              GaiaBokehAvatar(
                initials: _guestInitials(_s(rows.first, 'name', 'Guest')),
                tone: _toneOf(rows.first),
                size: 72,
              ),
              const SizedBox(width: 22),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(_s(rows.first, 'name', 'Guest'),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: GaiaType.serif(size: 30, weight: 500, height: 1)),
                    const SizedBox(height: 6),
                    Text(_customerRankValue(rows.first, sort),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: GaiaType.detail()),
                  ],
                ),
              ),
            ]),
          ),
        ),
        if (rows.length > 1) ...[
          const SizedBox(height: 16),
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              for (var i = 1; i < rows.length; i++)
                Expanded(
                  child: GestureDetector(
                    onTap: () => _guestSheet(rows[i]),
                    behavior: HitTestBehavior.opaque,
                    child: MouseRegion(
                      cursor: SystemMouseCursors.click,
                      child: Padding(
                        padding: EdgeInsets.only(right: i == rows.length - 1 ? 0 : 8),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            GaiaBokehAvatar(
                              initials: _guestInitials(_s(rows[i], 'name', 'Guest')),
                              tone: _toneOf(rows[i]),
                              size: 34,
                              halo: false,
                            ),
                            const SizedBox(height: 8),
                            Text(_s(rows[i], 'name', 'Guest'),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: GaiaType.sans(size: 12.5)),
                            Text(_customerRankValue(rows[i], sort),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: GaiaType.sans(
                                    size: 11, color: GaiaColors.text3AA)),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ],
      ],
    ]);
  }

  Widget _gaiaPagingFoot(BuildContext context) {
    if (_loadingMore) {
      return Text('Loading the next $_pageSize\u2026', style: GaiaType.detail());
    }
    if (_hasMore) {
      return Align(
        alignment: Alignment.centerLeft,
        child: GaiaButton(
          label: 'Load more (${_rows.length} of $_total)',
          kind: GaiaButtonKind.ghost,
          dense: true,
          onPressed: () => _load(append: true),
        ),
      );
    }
    return Text(
      _error ?? 'All $_total shown',
      style: GaiaType.detail(color: _error == null ? null : GaiaColors.coral),
    );
  }

  Widget _body(BuildContext context) {
    if (_loading && _rows.isEmpty) {
      return ListView(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
        children: [
          for (var i = 0; i < 6; i++)
            const Padding(
              padding: EdgeInsets.only(bottom: 8),
              child: SkeletonBox(height: 78, radius: AppRadius.card),
            ),
        ],
      );
    }
    if (_error != null && _rows.isEmpty) {
      return EmptyState(
        icon: Icons.error_outline,
        title: "Couldn't load the guest book",
        caption: _error!,
        action: ForkButton(label: 'Retry', icon: Icons.refresh, dense: true, onPressed: _load),
      );
    }
    if (_rows.isEmpty) {
      return _empty(_query.isEmpty && _segment == 'all'
          ? 'No guests on record yet.'
          : 'No guests match these filters.');
    }

    final text = Theme.of(context).textTheme;
    final width = MediaQuery.sizeOf(context).width;
    final cols = width >= 1500 ? 4 : (width >= 1120 ? 3 : (width >= 720 ? 2 : 1));
    final bandCols = width >= 1120 ? 3 : (width >= 760 ? 2 : 1);

    return ListView(
      controller: _scroll,
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
      children: [
        SectionHeader(
          title: 'Overview',
          trailing: TickTag(_segment == 'all' && _query.isEmpty
              ? 'across all $_total guests'
              : 'across the $_total matching'),
        ),
        _dashGrid([
          for (final s in _customerSorts) _leaderCard(context, s[0], s[1]),
        ], bandCols),
        const SizedBox(height: 20),
        SectionHeader(
          title: '${_customerSegmentLabel(_segment)} · ${_customerSortLabel(_sort).toLowerCase()}',
          count: _total,
        ),
        _dashGrid([for (final m in _rows) _guestCard(context, m)], cols),
        const SizedBox(height: 12),
        _pagingFoot(context, text),
      ],
    );
  }

  /// One ranking of the whole filtered set. Says so in as many words, because a
  /// top-five that silently meant "of the page" would be indistinguishable.
  Widget _leaderCard(BuildContext context, String sort, String title) {
    final text = Theme.of(context).textTheme;
    final rows = _leaders[sort] ?? const <Map>[];
    return ForkCard(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      selected: sort == _sort,
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Expanded(child: Text(title, style: text.titleSmall)),
          if (sort == _sort) const TickTag('sorting the list'),
        ]),
        const SizedBox(height: 8),
        if (_leaderErrors.containsKey(sort))
          Text("Couldn't rank: ${_leaderErrors[sort]}",
              style: text.bodySmall?.copyWith(color: AppColors.danger))
        else if (_leadersLoading && rows.isEmpty)
          const SkeletonBox(height: 84, radius: AppRadius.card)
        else if (rows.isEmpty)
          Text('Nothing to rank under these filters.', style: text.bodySmall)
        else
          for (var i = 0; i < rows.length; i++)
            InkWell(
              onTap: () => _guestSheet(rows[i]),
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 4),
                child: Row(children: [
                  SizedBox(
                    width: 18,
                    child: Text('${i + 1}', style: text.labelSmall),
                  ),
                  Expanded(
                    child: Text(_s(rows[i], 'name', 'Guest'),
                        style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                  ),
                  const SizedBox(width: AppSpacing.sm),
                  Text(_customerRankValue(rows[i], sort),
                      style: TextStyle(fontSize: 11, color: AppColors.textSecondary)),
                ]),
              ),
            ),
      ]),
    );
  }

  Widget _guestCard(BuildContext context, Map m) {
    final text = Theme.of(context).textTheme;
    final name = _s(m, 'name', 'Guest');
    final phone = _s(m, 'phone', '');
    final visits = _int(m['visits']) ?? 0;
    final last = _s(m, 'last_visit', '');
    final segment = _s(m, 'segment', '');
    return ForkCard(
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
      onTap: () => _guestSheet(m),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          InitialsAvatar(initials: _guestInitials(name)),
          const SizedBox(width: AppSpacing.md),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
              Text(name, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
              const SizedBox(height: 2),
              Text(phone.isEmpty ? '—' : phone,
                  style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            ]),
          ),
        ]),
        const SizedBox(height: 10),
        // Wrapped rather than spaced across a Row: a lifetime spend can run to
        // seven figures, and three intrinsic-width stats on one line overflow
        // the narrowest column this grid produces.
        Wrap(spacing: AppSpacing.lg, runSpacing: 8, children: [
          MicroStat(value: _money(m['total_spend']), label: 'Spent'),
          MicroStat(value: '$visits', label: 'Visits'),
          MicroStat(value: last.isEmpty ? 'never' : _fmtDay(last), label: 'Last'),
        ]),
        if (segment.isNotEmpty && segment != '—') ...[
          const SizedBox(height: 8),
          Align(
            alignment: Alignment.centerLeft,
            child: InfoChip(icon: Icons.sell_outlined, label: _customerSegmentLabel(segment)),
          ),
        ],
      ]),
    );
  }

  Widget _pagingFoot(BuildContext context, TextTheme text) {
    if (_loadingMore) {
      return Row(mainAxisAlignment: MainAxisAlignment.center, children: [
        SizedBox(
          width: 13,
          height: 13,
          child: CircularProgressIndicator(strokeWidth: 2, color: AppColors.copper),
        ),
        const SizedBox(width: AppSpacing.sm),
        Text('Loading the next $_pageSize…', style: text.bodySmall),
      ]);
    }
    if (_hasMore) {
      return Center(
        child: ForkButton.ghost(
          label: 'Load more (${_rows.length} of $_total)',
          icon: Icons.expand_more,
          dense: true,
          onPressed: () => _load(append: true),
        ),
      );
    }
    return Center(
      child: Text(
        _error ?? 'All $_total shown',
        textAlign: TextAlign.center,
        style: text.bodySmall?.copyWith(color: _error == null ? null : AppColors.danger),
      ),
    );
  }
}

/// `.pill` / `.pill.champ` — the Gaia half of [_SegmentChip]. Same contract:
/// the count is part of the label, so selection is never colour alone.
class _GaiaSegmentPill extends StatelessWidget {
  const _GaiaSegmentPill({
    required this.label,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) => GestureDetector(
        onTap: onTap,
        behavior: HitTestBehavior.opaque,
        child: MouseRegion(
          cursor: SystemMouseCursors.click,
          child: GaiaPill(label,
              color: selected ? GaiaColors.champagne : null),
        ),
      );
}

/// A segment filter pill carrying its own server-side count.
class _SegmentChip extends StatelessWidget {
  const _SegmentChip({
    required this.label,
    required this.count,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final int? count;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: MouseRegion(
        cursor: SystemMouseCursors.click,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 6),
          decoration: BoxDecoration(
            color: selected ? AppColors.tint(AppColors.copper) : AppColors.inset,
            borderRadius: BorderRadius.circular(999),
            border: Border.all(color: selected ? AppColors.edge(AppColors.copper) : AppColors.border),
          ),
          child: Text(
            // The count is part of the label, so selection is never the only
            // thing colour is carrying.
            count == null ? label : '$label · $count',
            style: TextStyle(
              fontSize: 11.5,
              fontWeight: selected ? FontWeight.w600 : FontWeight.w500,
              color: selected ? AppColors.copperHi : AppColors.textSecondary,
            ),
          ),
        ),
      ),
    );
  }
}

// Month-by-month business summary, up to 3 years back.
Widget historyModule(RestClient rest, Profile p) => _HistoryModule(rest: rest);

/// Holds History's reporting window. It opens WIDER than the 30-day default the
/// other modules use — a month-by-month table cut to one month is a single row,
/// which looks like a broken screen — but it is the same control, so a range
/// picked here reads exactly like a range picked in Accounting.
class _HistoryModule extends StatefulWidget {
  const _HistoryModule({required this.rest});
  final RestClient rest;
  @override
  State<_HistoryModule> createState() => _HistoryModuleState();
}

class _HistoryModuleState extends State<_HistoryModule> {
  // A year back, unless this session already chose something here. `has` is
  // what tells "nothing chosen" from "chose the 30-day default" — without it,
  // an owner who deliberately narrowed History would be bounced back to a year.
  DateRange _range = DateRangeMemory.of(
    'history',
    fallback: DateRange.normalized(addDaysToKey(todayKey(), -364), todayKey()),
  );

  void _setRange(DateRange next) {
    setState(() => _range = next);
    DateRangeMemory.remember('history', next);
  }

  @override
  Widget build(BuildContext context) => _historyBody(
        widget.rest,
        _range,
        _setRange,
        key: ValueKey('history-${_range.from}-${_range.to}'),
      );
}

Widget _historyBody(
  RestClient rest,
  DateRange range,
  ValueChanged<DateRange> onRange, {
  Key? key,
}) => AsyncView<Map<String, dynamic>>(
      key: key,
      // The endpoint's series is "the last N months", so a range is served by
      // asking for enough months to reach `from` and keeping the ones inside the
      // window. 36 is the endpoint's own ceiling; a longer range simply shows
      // what the server retains, which the chip states rather than hides.
      load: () => rest.getMap('/analytics/history?months=${monthsSpanned(range, max: 36)}'),
      builder: (context, data, reload) {
        // Trim to the SELECTED window. A month is kept when it overlaps the range
        // at all: an owner who picks 10 Aug - 20 Sep is asking about both months,
        // and dropping a partly-covered one would silently subtract real trade
        // from the totals below.
        final fromMonth = range.from.substring(0, 7);
        final toMonth = range.to.substring(0, 7);
        final series = ((data['series'] as List?) ?? []).where((r) {
          final m = '${(r as Map)['month'] ?? ''}';
          return m.compareTo(fromMonth) >= 0 && m.compareTo(toMonth) <= 0;
        }).toList();
        double num0(dynamic v) => (v is num) ? v.toDouble() : (double.tryParse('${v ?? ''}') ?? 0);
        String money(double v) => '₹${v.toStringAsFixed(0)}';
        const names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        String pretty(String ym) {
          final p = ym.split('-');
          if (p.length != 2) return ym;
          final i = (int.tryParse(p[1]) ?? 0) - 1;
          return i >= 0 && i < 12 ? '${names[i]} ${p[0]}' : ym;
        }

        final withData = series.where((r) {
          final m = r as Map;
          return num0(m['revenue']) > 0 || num0(m['orders']) > 0 || num0(m['feedback_count']) > 0 || num0(m['new_customers']) > 0;
        }).toList();
        final totalRev = series.fold<double>(0, (s, r) => s + num0((r as Map)['revenue']));
        final totalBills = series.fold<double>(0, (s, r) => s + num0((r as Map)['bills']));
        final totalCust = series.fold<double>(0, (s, r) => s + num0((r as Map)['new_customers']));
        // Chart the most recent 12 months with any activity (chronological).
        final chart = withData.take(12).toList().reversed
            .map((r) => (label: pretty('${(r as Map)['month']}'), value: num0(r['revenue'])))
            .toList();

        final text = Theme.of(context).textTheme;
        return RefreshIndicator(
          onRefresh: () async => reload(),
          child: ListView(padding: AppSpacing.pageNarrow, children: [
            SectionHeader(
              title: 'History',
              trailing: InfoChip(icon: Icons.calendar_today_outlined, label: range.label()),
            ),
            const SizedBox(height: AppSpacing.sm),
            // Every figure below is cut on this window, so it sits above them.
            Row(children: [Expanded(child: DateRangeChip(value: range, onChanged: onRange))]),
            const SizedBox(height: AppSpacing.md),
            // Every card on this screen opens the record behind it. The three
            // headline totals break down month by month; each month card opens
            // the settled bills that actually made it up.
            Wrap(spacing: 12, runSpacing: 12, children: [
              _statCard(context, 'Total revenue', money(totalRev), Icons.payments,
                  onTap: () => _detailSheet(
                        context,
                        eyebrow: 'History',
                        title: 'Revenue by month',
                        children: [
                          for (final r in withData)
                            _detailRow(context, pretty('${(r as Map)['month']}'), money(num0(r['revenue'])),
                                trailing: '${r['bills'] ?? 0} bills'),
                          if (withData.isEmpty) Text('No months with revenue yet.', style: text.bodySmall),
                        ],
                      )),
              _statCard(context, 'Bills', totalBills.toStringAsFixed(0), Icons.receipt_long,
                  onTap: () => _detailSheet(
                        context,
                        eyebrow: 'History',
                        title: 'Bills by month',
                        children: [
                          for (final r in withData)
                            _detailRow(context, pretty('${(r as Map)['month']}'), '${r['bills'] ?? 0}',
                                trailing: 'avg ${money(num0(r['avg_bill']))}'),
                          if (withData.isEmpty) Text('No bills closed yet.', style: text.bodySmall),
                        ],
                      )),
              _statCard(context, 'New customers', totalCust.toStringAsFixed(0), Icons.people,
                  onTap: () => _detailSheet(
                        context,
                        eyebrow: 'History',
                        title: 'New customers by month',
                        children: [
                          for (final r in withData)
                            _detailRow(context, pretty('${(r as Map)['month']}'), '${r['new_customers'] ?? 0}',
                                trailing: '${r['orders'] ?? 0} orders'),
                          if (withData.isEmpty) Text('No customers recorded yet.', style: text.bodySmall),
                        ],
                      )),
            ]),
            const SizedBox(height: AppSpacing.xxl),
            if (chart.isNotEmpty) ...[
              // STRATA owns this screen. Under Gaia the chart becomes the
              // stacked area — one stratum here, because a month's revenue is
              // one number and inventing a composition it does not have would
              // be a picture of data the backend never sent.
              _chartCard(
                context,
                'Revenue by month',
                Gaia.of(context)
                    ? GaiaStrataChart(
                        series: [
                          GaiaStrataSeries(
                            label: 'Revenue',
                            values: [for (final d in chart) d.value],
                          ),
                        ],
                        format: money,
                        axisLabels: [chart.first.label, chart.last.label],
                        showKey: false,
                        emptyMessage: 'No revenue in this window.',
                      )
                    : _barChart(context, chart, money),
              ),
              const SizedBox(height: AppSpacing.xxl),
            ],
            if (withData.isEmpty)
              const EmptyState(
                icon: Icons.hourglass_empty,
                title: 'No activity yet',
                caption: 'Month-by-month history builds up as bills close.',
              )
            else
              SectionHeader(title: 'Month by month', count: withData.length),
            // The month list, as strata. A month IS a part of the window's
            // total, so `share` mode is legitimate here and the band height is
            // that month's share of the revenue above it — the mockup's "read
            // the strata top down, thickness is share", applied to the one
            // series on this screen where the parts genuinely sum to the whole.
            if (Gaia.of(context) && withData.isNotEmpty)
              GaiaStrataList(
                mode: GaiaStrataMode.share,
                extent: GaiaStrataList.extentFor(withData.length),
                caption: 'Newest on top. Drawn from closed_at, the same basis'
                    ' every report uses, so this page and Accounting never'
                    ' disagree.',
                strata: [
                  for (final r in withData)
                    () {
                      final m = r as Map;
                      final fb = num0(m['feedback_count']);
                      return GaiaStratum(
                        label: pretty('${m['month']}'),
                        value: num0(m['revenue']),
                        display: money(num0(m['revenue'])),
                        tagLabel: '${m['bills'] ?? 0} cheques',
                        tagColor: num0(m['bills']) > 0
                            ? GaiaColors.champagneDim
                            : null,
                        caption: 'Average cheque ${money(num0(m['avg_bill']))}'
                            ' · ${m['orders'] ?? 0} orders'
                            '${fb > 0 ? ' · ${fb.toStringAsFixed(0)} feedback' : ''}',
                        onTap: () => showModalBottomSheet<void>(
                          context: context,
                          showDragHandle: true,
                          isScrollControlled: true,
                          backgroundColor: AppColors.surface,
                          builder: (_) => _MonthDetailSheet(
                            rest: rest,
                            month: m,
                            title: pretty('${m['month']}'),
                          ),
                        ),
                      );
                    }(),
                ],
              ),
            if (!Gaia.of(context))
            ...withData.map((r) {
              final m = r as Map;
              final fb = num0(m['feedback_count']);
              // The card is a control, not a summary: it opens the month's own
              // detail — the metric breakdown AND the settled bills that made
              // it, each of which opens the bill itself.
              return Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: ForkCard(
                  padding: const EdgeInsets.fromLTRB(16, 14, 12, 14),
                  onTap: () => showModalBottomSheet<void>(
                    context: context,
                    showDragHandle: true,
                    isScrollControlled: true,
                    backgroundColor: AppColors.surface,
                    builder: (_) => _MonthDetailSheet(
                      rest: rest,
                      month: m,
                      title: pretty('${m['month']}'),
                    ),
                  ),
                  child: Row(children: [
                    Expanded(
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text(pretty('${m['month']}'), style: text.titleSmall),
                        const SizedBox(height: 8),
                        Wrap(spacing: 6, runSpacing: 6, children: [
                          InfoChip(icon: Icons.receipt_long_outlined, label: '${m['bills'] ?? 0} bills'),
                          InfoChip(icon: Icons.restaurant_menu, label: '${m['orders'] ?? 0} orders'),
                          InfoChip(icon: Icons.equalizer, label: 'avg ${money(num0(m['avg_bill']))}'),
                          if (fb > 0)
                            InfoChip(icon: Icons.star_outline, label: '$fb feedback · ${m['avg_rating'] ?? '—'}/5'),
                        ]),
                      ]),
                    ),
                    const SizedBox(width: AppSpacing.md),
                    Text(money(num0(m['revenue'])), style: text.displaySmall!.copyWith(fontSize: 20)),
                    Icon(Icons.chevron_right, size: 18, color: AppColors.textTertiary),
                  ]),
                ),
              );
            }),
          ]),
        );
      },
    );

/// First and last calendar day of a "YYYY-MM" bucket, as the `from`/`to` the
/// bills endpoint expects. Null when the bucket isn't a month.
({String from, String to})? _monthRange(String ym) {
  final parts = ym.split('-');
  if (parts.length != 2) return null;
  final y = int.tryParse(parts[0]);
  final m = int.tryParse(parts[1]);
  if (y == null || m == null || m < 1 || m > 12) return null;
  // Day 0 of the NEXT month is the last day of this one (leap years included).
  final last = DateTime.utc(y, m + 1, 0).day;
  final mm = m.toString().padLeft(2, '0');
  return (from: '$y-$mm-01', to: '$y-$mm-${last.toString().padLeft(2, '0')}');
}

/// What a History month card opens: the month's own metrics, then the settled
/// bills that produced them — each of which opens the bill in full.
class _MonthDetailSheet extends StatelessWidget {
  final RestClient rest;
  final Map month;
  final String title;
  const _MonthDetailSheet({required this.rest, required this.month, required this.title});

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final ym = '${month['month']}';
    final range = _monthRange(ym);
    final tat = month['avg_tat_min'];
    final feedback = _numOf(month['feedback_count']);
    return SafeArea(
      child: ConstrainedBox(
        constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(context).height * 0.9),
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
          child: SingleChildScrollView(
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              Row(children: [
                Expanded(
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text('MONTH', style: text.labelSmall),
                    const SizedBox(height: 4),
                    Text(title, style: text.headlineMedium),
                  ]),
                ),
                Text(_money(month['revenue']), style: text.displaySmall!.copyWith(fontSize: 22)),
              ]),
              const SizedBox(height: AppSpacing.lg),
              ForkCard(
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  SectionHeader(title: 'Month totals', padding: const EdgeInsets.only(bottom: 6)),
                  _kv('Revenue', _money(month['revenue'])),
                  _kv('Bills', '${month['bills'] ?? 0}'),
                  _kv('Orders', '${month['orders'] ?? 0}'),
                  _kv('Avg bill', _money(month['avg_bill'])),
                  _kv('Discounts', _money(month['discounts'])),
                  _kv('Feedback', feedback > 0 ? '${month['feedback_count']} (avg ${month['avg_rating'] ?? '—'}/5)' : '0'),
                  _kv('New customers', '${month['new_customers'] ?? 0}'),
                  _kv('Avg TAT', tat != null ? '${_numOf(tat).toStringAsFixed(0)} min' : '—'),
                ]),
              ),
              const SizedBox(height: AppSpacing.lg),
              SectionHeader(title: 'Settled bills', padding: const EdgeInsets.only(bottom: 6)),
              Text('Every bill closed in $title — tap one for its items, taxes, payment and who closed it.',
                  style: text.bodySmall),
              const SizedBox(height: AppSpacing.md),
              if (range == null)
                Text('No date range for "$ym".', style: text.bodySmall)
              else
                _ClosedBillsList(
                  rest: rest,
                  pageSize: 10,
                  filter: _ClosedBillFilter(from: range.from, to: range.to),
                  emptyCaption: 'No bills were closed in $title.',
                ),
            ]),
          ),
        ),
      ),
    );
  }
}

Widget bookingsModule(RestClient rest, Profile p) => _BookingsView(rest: rest, profile: p);

/// GAIA page padding for a full-page screen.
///
/// The design has ONE gutter — 24px — and the mockup is a 430px phone, so on a
/// 2240px till a `.kv` row would put its label and its figure most of a metre
/// apart and a line of body copy would run to 300 characters. Past a reading
/// measure the extra width goes into the margins instead: the column stays the
/// width the type was drawn for, and the coverflow's fan still has ~900px to
/// open into, which is more than it needs.
EdgeInsets _gaiaPagePadding(double width, {double bottom = 40}) {
  const measure = 900.0;
  final side = width <= measure + GaiaSpacing.gutter * 2
      ? GaiaSpacing.gutter
      : (width - measure) / 2;
  return EdgeInsets.fromLTRB(side, GaiaSpacing.gutter, side, bottom);
}

/// Translate a Rustic Fork semantic ink into its GAIA counterpart.
///
/// The two systems agree on WHAT the four states mean and disagree on the hue:
/// Rustic's success is an olive (#8FB27C), Gaia's is sage (#9BC4A0). Module
/// code decides a status colour once, in Rustic terms, and this maps it — so a
/// screen keeps ONE status rule and neither design has to restate it.
///
/// Colour is never the carrier on either side: every call site here also ships
/// the status word.
Color _gaiaStatusInk(Color rustic) {
  if (rustic == AppColors.success) return GaiaColors.sage;
  if (rustic == AppColors.danger) return GaiaColors.coral;
  if (rustic == AppColors.warning) return GaiaColors.amber;
  if (rustic == AppColors.neutral) return GaiaColors.text3AA;
  // Everything else is the accent — AppColors.copper, which the shell bridge
  // has already turned champagne.
  return GaiaColors.champagne;
}

class _BookingsView extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  const _BookingsView({required this.rest, required this.profile});

  @override
  State<_BookingsView> createState() => _BookingsViewState();
}

class _BookingsViewState extends State<_BookingsView> {
  // Which slice of bookings to show, sent as GET /get-bookings?window=. The
  // backend windows on the exact same slot-end boundary it always used, so
  // 'upcoming' (the default) is byte-identical to the legacy behaviour; 'past'
  // and 'all' let a booking still be reached after its slot ends instead of
  // silently disappearing (bug B / reservation-notification follow-ups).
  String _window = 'upcoming';

  bool get _isUpcoming => _window == 'upcoming';

  /// GAIA only. Which booking the coverflow has at the front, and the scroll
  /// controller used to bring it back into view when a list row picks one.
  /// Both are inert under Rustic Fork, which draws a grid and has no focus.
  int _flowIndex = 0;
  final ScrollController _flowScroll = ScrollController();

  @override
  void dispose() {
    _flowScroll.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(children: [
      // The window selector lives outside the AsyncView so it stays visible
      // (and switching feels instant) even while the chosen slice is loading.
      //
      // Gaia draws its own tab strip inside the page, under the masthead, so
      // this Rustic header would be a second copy of the same control.
      if (!Gaia.of(context)) Padding(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
        // Until the New-booking button existed the app could only ASSIGN
        // tables to bookings created elsewhere — walking in with a party of 8
        // and a phone in hand, there was simply no way to book at all, which a
        // tester reported as "it does not let you book for 8". Creation rides
        // the same seating suggester as assignment, so a party no single table
        // fits gets offered a clubbed set (6 + 2) up front.
        //
        // Two layouts on purpose. Sharing one Row squeezed the SegmentedButton
        // on phones until its labels wrapped LETTER BY LETTER ("U-pc-o-mi-ng")
        // — the selector needs the full width there, so below the app's shared
        // narrow breakpoint the button drops onto its own line instead.
        // 760 = the app-wide narrow edge (kNarrowWidth in home_shell.dart —
        // not importable here without a cycle; modules spell it inline).
        child: MediaQuery.sizeOf(context).width < 760
            ? Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                Align(alignment: Alignment.centerLeft, child: _windowSelector()),
                const SizedBox(height: 10),
                Align(
                  alignment: Alignment.centerRight,
                  child: ForkButton(
                    label: 'New booking',
                    icon: Icons.add,
                    dense: true,
                    onPressed: () => _newBooking(context),
                  ),
                ),
              ])
            : Row(children: [
                Expanded(child: Align(alignment: Alignment.centerLeft, child: _windowSelector())),
                const SizedBox(width: 10),
                ForkButton(
                  label: 'New booking',
                  icon: Icons.add,
                  dense: true,
                  onPressed: () => _newBooking(context),
                ),
              ]),
      ),
      Expanded(
        child: AsyncView<List>(
          // Re-keyed so switching the window (or creating a booking) remounts
          // and refetches.
          key: ValueKey('bookings-$_window-$_createdTick'),
          load: () => widget.rest.getList('/get-bookings?window=$_window'),
          builder: _list,
        ),
      ),
    ]);
  }

  // Bumped after a successful create so the AsyncView refetches.
  int _createdTick = 0;

  Widget _windowSelector() => SegmentedButton<String>(
        segments: const [
          ButtonSegment(value: 'upcoming', label: Text('Upcoming'), icon: Icon(Icons.event_available, size: 15)),
          ButtonSegment(value: 'past', label: Text('Past'), icon: Icon(Icons.history, size: 15)),
          ButtonSegment(value: 'all', label: Text('All'), icon: Icon(Icons.event_note, size: 15)),
        ],
        selected: {_window},
        showSelectedIcon: false,
        onSelectionChanged: (s) => setState(() => _window = s.first),
      );

  /// Create a booking from the app. Party bigger than every single table gets
  /// the seating suggester's clubbed combinations (same dialog the assign flow
  /// uses); a fitting party picks from the suggested singles. Nothing is ever
  /// clubbed without an explicit staff choice.
  Future<void> _newBooking(BuildContext context) async {
    final messenger = ScaffoldMessenger.of(context);
    final form = await showDialog<Map<String, dynamic>>(
      context: context,
      builder: (_) => const _NewBookingDialog(),
    );
    if (form == null || !context.mounted) return;

    final party = form['party'] as int;
    final at = form['at'] as DateTime;
    final iso = at.toIso8601String();
    const durationMins = 120; // the backend's default booking window

    // Ask the suggester what can hold this party at that time.
    Map<String, dynamic>? suggestion;
    try {
      suggestion = await widget.rest.getMap(
        '/tables/seating-suggestion?party=$party&at=${Uri.encodeQueryComponent(iso)}&duration=$durationMins');
    } catch (_) {/* fall through — the picker below degrades to free tables */}
    if (!context.mounted) return;

    List<String>? names;
    final singles = ((suggestion?['single'] as List?) ?? const []).cast<Map>();
    if (singles.isNotEmpty) {
      // A single table fits: a plain choice, least friction.
      names = await showDialog<List<String>>(
        context: context,
        builder: (ctx) => SimpleDialog(
          title: Text('Table for $party'),
          children: [
            for (final t in singles)
              SimpleDialogOption(
                onPressed: () => Navigator.pop(ctx, <String>[_s(t, 'table_name', '')]),
                child: Row(children: [
                  Icon(Icons.table_restaurant_outlined, size: 16, color: AppColors.textSecondary),
                  const SizedBox(width: 10),
                  Expanded(child: Text(_s(t, 'table_name', ''))),
                  Text(_seatsLabel(t),
                      style: Theme.of(ctx).textTheme.bodySmall!.copyWith(fontSize: 11.5)),
                ]),
              ),
          ],
        ),
      );
    } else if (suggestion != null) {
      // No single table fits — offer the clubbed combinations (or the manual
      // override across every free table).
      names = await showDialog<List<String>>(
        context: context,
        builder: (_) => _SeatingSuggestionDialog(suggestion: suggestion!, party: party),
      );
    }
    if (names == null || names.isEmpty || !context.mounted) return;

    try {
      await widget.rest.post('/add-booking', {
        'customer': {'name': form['name'], 'number': form['phone']},
        'booking': {
          'table_name': names.first,
          if (names.length > 1) 'combined_table_names': names.sublist(1),
          'date': iso,
          'duration': '$durationMins',
          'number_of_people': '$party',
          if ((form['source'] as String).isNotEmpty) 'source': form['source'],
        },
      });
      messenger.showSnackBar(SnackBar(
          content: Text('Booked ${names.join(' + ')} for $party — ${form['name']}')));
      if (mounted) setState(() => _createdTick++);
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Widget _list(BuildContext context, List rows, VoidCallback reload) {
        final rest = widget.rest;
        final p = widget.profile;
        final messenger = ScaffoldMessenger.of(context);
        final reservationUrl = '${AppConfig.orderBaseUrl}/reserve/${p.restaurantUsername}';

        void showReservationQr() {
          showDialog<void>(
            context: context,
            builder: (ctx) => AlertDialog(
              title: const Text('Guest reservation link'),
              content: SizedBox(
                width: 280,
                child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                  Center(
                    child: Container(
                      padding: const EdgeInsets.all(8),
                      color: Colors.white,
                      child: QrImageView(data: reservationUrl, size: 200),
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text('Share so guests can book a table online',
                      textAlign: TextAlign.center, style: TextStyle(fontSize: 12, color: AppColors.textSecondary)),
                  const SizedBox(height: 6),
                  SelectableText(reservationUrl, textAlign: TextAlign.center, style: const TextStyle(fontSize: 11)),
                ]),
              ),
              actions: [
                TextButton.icon(
                  onPressed: () => _printTableQr('Reservations', reservationUrl),
                  icon: const Icon(Icons.print),
                  label: const Text('Print'),
                ),
                FilledButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close')),
              ],
            ),
          );
        }

        Future<void> setStatus(String id, String status) async {
          try {
            await rest.patch('/booking/$id/status', {'status': status});
            reload();
          } catch (e) {
            messenger.showSnackBar(SnackBar(content: Text('$e')));
          }
        }

        Future<void> deleteBooking(String id) async {
          if (!await _confirm(context, 'Delete booking', 'Remove this booking?')) return;
          try {
            await rest.delete('/booking/$id');
            reload();
          } catch (e) {
            messenger.showSnackBar(SnackBar(content: Text('$e')));
          }
        }

        // Assign the booking's table(s). When no single free table can hold the
        // party the server's seating suggester proposes adjacent tables to club
        // ("Party of 8 needs 2 tables — combine T1 + T2?") — a SUGGESTION only:
        // staff accept it, pick their own set, or walk away. Nothing is ever
        // assigned without a confirmation.
        Future<void> assignTable(Map b) async {
          final id = _s(b, 'booking_id');
          final party = _int(b['number_of_people']) ?? 0;
          final at = _s(b, 'booking_date_time', '');
          final mins = _int(b['duration_mins']) ?? 0;
          Map<String, dynamic>? suggestion;
          if (party > 0) {
            final q = StringBuffer('/tables/seating-suggestion?party=$party');
            if (at.isNotEmpty) q.write('&at=${Uri.encodeQueryComponent(at)}');
            if (mins > 0) q.write('&duration=$mins');
            try {
              suggestion = await rest.getMap(q.toString());
            } catch (_) {/* fall back to the plain picker below */}
          }
          if (!context.mounted) return;
          List<String>? names;
          final s = suggestion;
          // A single free table still fits: the ordinary picker is less friction.
          final fitsAlone = s != null && ((s['single'] as List?) ?? const []).isNotEmpty;
          if (s != null && !fitsAlone) {
            names = await showDialog<List<String>>(
              context: context,
              builder: (_) => _SeatingSuggestionDialog(suggestion: s, party: party),
            );
          } else {
            final one = await _pickTable(context, rest);
            if (one != null && one.isNotEmpty) names = [one];
          }
          if (names == null || names.isEmpty) return;
          try {
            await rest.patch('/booking/$id/table', {
              'table_name': names.first,
              // Always explicit: a single pick un-clubs a previously joined set.
              'combined_table_names': names.skip(1).toList(),
            });
            reload();
          } catch (e) {
            messenger.showSnackBar(SnackBar(content: Text('$e')));
          }
        }

        // Booking-stage tint — always paired with the labelled StatusChip.
        Color bookingColor(String s) {
          final l = s.toLowerCase();
          if (l.contains('confirm')) return AppColors.success;
          if (l.contains('seat')) return AppColors.copper;
          if (l.contains('cancel') || l.contains('no')) return AppColors.danger;
          if (l.contains('request') || l.contains('pend')) return AppColors.warning;
          return AppColors.neutral;
        }

        String initialsOf(String name) {
          final parts = name.trim().split(RegExp(r'\s+')).where((s) => s.isNotEmpty).toList();
          if (parts.isEmpty) return '?';
          return parts.length == 1
              ? parts.first.substring(0, 1)
              : '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}';
        }

        // Everything a card cannot hold, plus every stage change. Actions live
        // here rather than on the card so a mis-tap in a dense grid cannot
        // cancel somebody's reservation.
        //
        // Hoisted out of the per-card loop it used to live in so the Gaia
        // coverflow opens the SAME sheet with the SAME five actions. One action
        // surface for both designs; there is no second copy to drift.
        void openDetail(BuildContext c, Map b) {
          final id = _s(b, 'booking_id');
          final status = _s(b, 'status', 'Requested');
          final when = _fmtDmy(_s(b, 'booking_date_time', ''));
          final tableNames = _strList(b['table_names']);
          final table = tableNames.isNotEmpty ? tableNames.join(' + ') : _s(b, 'table_name', '');
          final notes = _s(b, 'notes', '');
          final online = _s(b, 'source', '').toLowerCase() == 'online';
          _detailSheet(
            c,
            eyebrow: status,
            title: _s(b, 'customer_name', 'Guest'),
            children: [
              _kv('When', when.isEmpty ? '\u2014' : when),
              _kv('Party', '${b['number_of_people'] ?? '\u2014'}'),
              _kv('Table', table.isEmpty ? 'Not assigned' : (tableNames.length > 1 ? '$table (clubbed)' : table)),
              _kv('Source', online ? 'Online' : 'In-house'),
              if (_s(b, 'customer_phone').isNotEmpty) _kv('Phone', _s(b, 'customer_phone')),
              if (notes.isNotEmpty) _kv('Notes', notes),
              const SizedBox(height: 12),
              Wrap(spacing: 8, runSpacing: 8, children: [
                ForkButton.ghost(
                  label: 'Assign / combine tables',
                  icon: Icons.table_restaurant_outlined,
                  dense: true,
                  onPressed: () {
                    Navigator.of(c).pop();
                    assignTable(b);
                  },
                ),
                ForkButton.ghost(
                  label: 'Mark confirmed',
                  icon: Icons.check,
                  dense: true,
                  onPressed: () {
                    Navigator.of(c).pop();
                    setStatus(id, 'Confirmed');
                  },
                ),
                ForkButton.ghost(
                  label: 'Mark seated',
                  icon: Icons.event_seat,
                  dense: true,
                  onPressed: () {
                    Navigator.of(c).pop();
                    setStatus(id, 'Seated');
                  },
                ),
                ForkButton.ghost(
                  label: 'Cancel booking',
                  icon: Icons.close,
                  dense: true,
                  onPressed: () {
                    Navigator.of(c).pop();
                    setStatus(id, 'Cancelled');
                  },
                ),
                ForkButton.ghost(
                  label: 'Delete',
                  icon: Icons.delete_outline,
                  dense: true,
                  onPressed: () {
                    Navigator.of(c).pop();
                    deleteBooking(id);
                  },
                ),
              ]),
            ],
          );
        }

        // A reservation notification asked us to focus one booking.
        final focus = _focusOf(context, 'Bookings');
        final focusId = focus?.idOf(const ['booking_id']);
        final focusFound = focusId != null && rows.any((b) => _s(b as Map, 'booking_id') == focusId);
        // The focused booking first so it is on screen without scrolling; with
        // nothing focused the server's earliest-first order already stands.
        // The parentheses are load-bearing: a bare cascade binds to the WHOLE
        // conditional, so the unfocused branch sorted `rows` itself with a
        // comparator that returns 0 for every pair — and List.sort leaves
        // insertion sort above 32 elements, permuting the queue it was handed.
        final ordered = focusId == null
            ? rows
            : ([...rows]..sort((a, b) {
                final fa = _s(a as Map, 'booking_id') == focusId ? 0 : 1;
                final fb = _s(b as Map, 'booking_id') == focusId ? 0 : 1;
                return fa - fb;
              }));

        final banner = focus == null
            ? null
            : _focusBanner(
                context,
                found: focusFound,
                message: focusFound
                    ? 'Showing the booking from your notification.'
                    : !_isUpcoming
                        ? "That booking isn't here — it may have been deleted, or belong to another outlet."
                        : "That booking isn't in the upcoming list — its time slot has already passed.",
                actions: focusFound || !_isUpcoming
                    ? const []
                    : [
                        ForkButton.ghost(
                          label: 'Show all bookings',
                          icon: Icons.history,
                          dense: true,
                          onPressed: () => setState(() => _window = 'all'),
                        ),
                      ],
              );

        final list = ordered.isEmpty
            ? Column(children: [
                if (banner != null) Padding(padding: const EdgeInsets.fromLTRB(16, 14, 16, 0), child: banner),
                Expanded(
                  child: _empty(_window == 'past'
                      ? 'No past bookings.'
                      : _window == 'all'
                          ? 'No bookings yet.'
                          : 'No upcoming bookings. New reservations will appear here.'),
                ),
              ])
            : Builder(builder: (c) {
          // Tiles, not full-width rows: a booking is a short record (who, when,
          // party size, which table) and a wide row spent most of its width on
          // nothing. Detail moves into the tap. Eager build is fine here -- the
          // list is upcoming bookings, not the whole history.
          final width = MediaQuery.sizeOf(c).width;
          final cols = width >= 1500 ? 4 : (width >= 1120 ? 3 : (width >= 720 ? 2 : 1));
          final cards = <Widget>[];
          for (var i = 0; i < ordered.length; i++) {
            final b = ordered[i] as Map;
            final id = _s(b, 'booking_id');
            final status = _s(b, 'status', 'Requested');
            final when = _fmtDmy(_s(b, 'booking_date_time', ''));
            // Clubbed bookings hold several tables — read as "T1 + T2".
            final tableNames = _strList(b['table_names']);
            final table = tableNames.isNotEmpty ? tableNames.join(' + ') : _s(b, 'table_name', '');
            final notes = _s(b, 'notes', '');
            final online = _s(b, 'source', '').toLowerCase() == 'online';
            final isRequested = status.toLowerCase() == 'requested';
            final name = _s(b, 'customer_name', 'Guest');
            final focused = focusId != null && id == focusId;
            final text = Theme.of(c).textTheme;
            final chips = <Widget>[
              if (focused) const InfoChip(icon: Icons.notifications_active, label: 'From your notification'),
              InfoChip(icon: Icons.calendar_today_outlined, label: when.isEmpty ? '\u2014' : when),
              if (table.isNotEmpty)
                InfoChip(
                  icon: tableNames.length > 1 ? Icons.link : Icons.table_restaurant_outlined,
                  label: tableNames.length > 1 ? '$table (clubbed)' : table,
                ),
              if (online) const InfoChip(icon: Icons.language, label: 'Online'),
            ];

            cards.add(ForkCard(
              selected: isRequested || focused,
              onTap: () => openDetail(c, b),
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  InitialsAvatar(initials: initialsOf(name)),
                  const SizedBox(width: AppSpacing.sm),
                  Expanded(
                    child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(name, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                          const SizedBox(height: 2),
                          Text('Party of ${b['number_of_people'] ?? '\u2014'}',
                              style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                        ]),
                  ),
                  const SizedBox(width: AppSpacing.sm),
                  AnimatedSwitcher(
                    duration: AppDurations.base,
                    switchInCurve: Curves.easeOut,
                    switchOutCurve: Curves.easeIn,
                    child: StatusChip(
                      key: ValueKey('booking-$id-$status'),
                      label: status,
                      color: bookingColor(status),
                      dense: true,
                    ),
                  ),
                ]),
                const SizedBox(height: 10),
                // When and where: the two things you scan a booking grid for.
                Wrap(spacing: 6, runSpacing: 6, children: chips),
                if (notes.isNotEmpty) ...[
                  const SizedBox(height: 8),
                  Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Icon(Icons.sticky_note_2_outlined, size: 12, color: AppColors.textTertiary),
                    const SizedBox(width: 5),
                    Expanded(
                      child: Text(notes,
                          style: text.bodySmall!.copyWith(
                              fontSize: 11, fontStyle: FontStyle.italic, color: AppColors.textTertiary),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis),
                    ),
                  ]),
                ],
                // Confirm/decline stays on the tile: an unconfirmed booking is
                // the reason this screen gets opened at all.
                if (isRequested) ...[
                  const SizedBox(height: 10),
                  Row(children: [
                    Expanded(
                      child: ForkButton.ghost(
                        label: 'Decline',
                        icon: Icons.close,
                        dense: true,
                        onPressed: () => setStatus(id, 'Cancelled'),
                      ),
                    ),
                    const SizedBox(width: AppSpacing.sm),
                    Expanded(
                      child: ForkButton(
                        label: 'Confirm',
                        icon: Icons.check,
                        dense: true,
                        onPressed: () => setStatus(id, 'Confirmed'),
                      ),
                    ),
                  ]),
                ],
              ]),
            ));
          }
          return ListView(
            padding: AppSpacing.pageNarrow,
            children: [
              if (banner != null) ...[banner, const SizedBox(height: 12)],
              _dashGrid(cards, cols),
            ],
          );
        });

        // ── GAIA: the COVERFLOW treatment ──────────────────────────────
        //
        // The mockup gives Bookings a coverflow and, under it, a key/value
        // block describing the card at the front. That is a beautiful way to
        // read the NEXT party and a bad way to find the 8pm one out of forty,
        // so this keeps the mockup's flow AND a full hairline index below it:
        // the flow is the hero, the list is still how a host finds someone,
        // and tapping a row flies the flow to that booking. Nothing is
        // reachable in one design and not the other — the same openDetail
        // sheet, the same five stage changes, the same reservation QR.
        if (Gaia.of(context)) {
          final flowIndex = ordered.isEmpty ? 0 : _flowIndex.clamp(0, ordered.length - 1);
          final focusedBooking = ordered.isEmpty ? null : ordered[flowIndex] as Map;
          // Covers, not bookings: "18 covers" is the number a host is actually
          // holding tables for.
          var covers = 0;
          for (final r in ordered) {
            covers += _int((r as Map)['number_of_people']) ?? 0;
          }

          void goTo(int i) {
            setState(() => _flowIndex = i);
            // A row two screens down just changed what the flow shows; without
            // this you would tap and see nothing move.
            if (_flowScroll.hasClients && _flowScroll.offset > 8) {
              _flowScroll.animateTo(0,
                  duration: const Duration(milliseconds: 260), curve: Curves.easeOutCubic);
            }
          }

          String whenOf(Map b) => _fmtDmy(_s(b, 'booking_date_time', ''));
          String tableOf(Map b) {
            final names = _strList(b['table_names']);
            if (names.isNotEmpty) return names.join(' + ');
            final one = _s(b, 'table_name', '');
            return one == '\u2014' ? '' : one;
          }

          final title = switch (_window) {
            'past' => ('Past', 'seatings.'),
            'all' => ('Every', 'seating.'),
            _ => ('Tonight\u2019s', 'seatings.'),
          };

          return LayoutBuilder(builder: (context, box) => ListView(
            controller: _flowScroll,
            padding: _gaiaPagePadding(box.maxWidth),
            children: [
              GaiaPageHeader(
                wordmark: p.restaurantName,
                meta: '${rows.length} ${_window == 'upcoming' ? 'upcoming' : _window}',
                title: title.$1,
                titleEmphasis: title.$2,
                sub: ordered.isEmpty
                    ? 'Nothing booked'
                    : '${ordered.length} ${ordered.length == 1 ? 'party' : 'parties'} \u00b7 $covers covers',
              ),
              Row(children: [
                Expanded(
                  child: GaiaTabs(
                    tabs: const ['Upcoming', 'Past', 'All'],
                    selected: const ['upcoming', 'past', 'all'].indexOf(_window),
                    onSelected: (i) => setState(() {
                      _window = const ['upcoming', 'past', 'all'][i];
                      _flowIndex = 0;
                    }),
                  ),
                ),
                const SizedBox(width: 12),
                GaiaButton(
                  label: 'Share link',
                  kind: GaiaButtonKind.subtle,
                  onPressed: showReservationQr,
                ),
              ]),
              if (banner != null) ...[const SizedBox(height: 16), banner],
              if (ordered.isEmpty) ...[
                const SizedBox(height: 40),
                Center(
                  child: Text(
                    _window == 'past'
                        ? 'No past bookings.'
                        : _window == 'all'
                            ? 'No bookings yet.'
                            : 'No upcoming bookings. New reservations will appear here.',
                    textAlign: TextAlign.center,
                    style: GaiaType.italNote(),
                  ),
                ),
                const SizedBox(height: 28),
                Center(
                  child: GaiaButton(label: 'New booking', onPressed: () => _newBooking(context)),
                ),
              ] else ...[
                const SizedBox(height: 24),
                GaiaCoverflow(
                  itemCount: ordered.length,
                  index: flowIndex,
                  onIndexChanged: (i) => setState(() => _flowIndex = i),
                  onActivate: (i) => openDetail(context, ordered[i] as Map),
                  semanticsBuilder: (i) {
                    final b = ordered[i] as Map;
                    return '${_s(b, 'customer_name', 'Guest')}, party of '
                        '${b['number_of_people'] ?? 'unknown'}, ${whenOf(b)}, '
                        '${_s(b, 'status', 'Requested')}';
                  },
                  itemBuilder: (context, i) {
                    final b = ordered[i] as Map;
                    final table = tableOf(b);
                    final notes = _s(b, 'notes', '');
                    return GaiaCoverflowCard(
                      who: _s(b, 'customer_name', 'Guest'),
                      when: whenOf(b).isEmpty ? 'No time set' : whenOf(b),
                      detail: [
                        'Party of ${b['number_of_people'] ?? '\u2014'}'
                            '${table.isEmpty ? '' : ' \u00b7 $table'}',
                        if (notes.isNotEmpty)
                          notes
                        else if (_s(b, 'source', '').toLowerCase() == 'online')
                          'Booked online'
                        else if (_s(b, 'customer_phone').isNotEmpty)
                          _s(b, 'customer_phone'),
                      ],
                      footLeft: table.isEmpty ? 'No table' : table,
                      footRight: _s(b, 'status', 'Requested'),
                      // Colour is a second reading of the word beside it, never
                      // the carrier — same contract as StatusChip.
                      footRightColor: _gaiaStatusInk(bookingColor(_s(b, 'status', 'Requested'))),
                    );
                  },
                ),
                GaiaCoverflowIndex(
                  count: ordered.length,
                  index: flowIndex,
                  onTap: goTo,
                ),
                const SizedBox(height: GaiaSpacing.xxl),
                if (focusedBooking != null) ...[
                  GaiaKeyValue(
                    first: true,
                    label: '${_s(focusedBooking, 'customer_name', 'Guest')} \u00b7 '
                        'party of ${focusedBooking['number_of_people'] ?? '\u2014'}',
                    sub: whenOf(focusedBooking).isEmpty ? null : whenOf(focusedBooking),
                    value: _s(focusedBooking, 'status', 'Requested'),
                    serifValue: false,
                  ),
                  GaiaKeyValue(
                    label: 'Table',
                    value: tableOf(focusedBooking).isEmpty
                        ? 'Not assigned'
                        : (_strList(focusedBooking['table_names']).length > 1
                            ? '${tableOf(focusedBooking)} (clubbed)'
                            : tableOf(focusedBooking)),
                    serifValue: false,
                  ),
                  GaiaKeyValue(
                    label: 'Channel',
                    value: _s(focusedBooking, 'source', '').toLowerCase() == 'online'
                        ? 'Online \u00b7 reservation link'
                        : 'In-house',
                    serifValue: false,
                  ),
                  if (_s(focusedBooking, 'customer_phone').isNotEmpty)
                    GaiaKeyValue(
                      label: 'Phone',
                      value: _s(focusedBooking, 'customer_phone'),
                      serifValue: false,
                    ),
                  if (_s(focusedBooking, 'notes').isNotEmpty)
                    GaiaKeyValue(
                      label: 'Notes',
                      value: _s(focusedBooking, 'notes'),
                      serifValue: false,
                    ),
                  const SizedBox(height: GaiaSpacing.xl),
                  // Confirm/decline stays on the FRONT of the screen for a
                  // requested booking: an unconfirmed booking is the reason
                  // this screen gets opened at all.
                  if (_s(focusedBooking, 'status', 'Requested').toLowerCase() == 'requested')
                    Row(children: [
                      Expanded(
                        child: GaiaButton(
                          label: 'Decline',
                          kind: GaiaButtonKind.ghost,
                          dense: true,
                          onPressed: () =>
                              setStatus(_s(focusedBooking, 'booking_id'), 'Cancelled'),
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: GaiaButton(
                          label: 'Confirm',
                          dense: true,
                          onPressed: () =>
                              setStatus(_s(focusedBooking, 'booking_id'), 'Confirmed'),
                        ),
                      ),
                    ])
                  else ...[
                    // Two rows, not the mockup's one. Its `.btns` grid puts
                    // three buttons across a 430px phone, and a Gaia button
                    // label is uppercase at .2em tracking: "MOVE TABLE" and
                    // "DETAILS" both came out as "MOVE ..." and "DETAI...".
                    // A truncated verb is not a control.
                    Row(children: [
                      Expanded(
                        child: GaiaButton(
                          label: 'Move table',
                          kind: GaiaButtonKind.ghost,
                          dense: true,
                          onPressed: () => assignTable(focusedBooking),
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: GaiaButton(
                          label: 'Details',
                          kind: GaiaButtonKind.ghost,
                          dense: true,
                          onPressed: () => openDetail(context, focusedBooking),
                        ),
                      ),
                    ]),
                    const SizedBox(height: 12),
                    Row(children: [
                      Expanded(
                        child: GaiaButton(
                          label: 'New booking',
                          dense: true,
                          onPressed: () => _newBooking(context),
                        ),
                      ),
                    ]),
                  ],
                ],
                const SizedBox(height: GaiaSpacing.xxl),
                // The scan path. Everything the flow holds, one hairline row
                // each, in the server's order — which is what a host reads at
                // 20:00 with a phone in one hand.
                GaiaSectionHeader(title: 'Every booking', count: ordered.length),
                for (var i = 0; i < ordered.length; i++)
                  Builder(builder: (context) {
                    final b = ordered[i] as Map;
                    final table = tableOf(b);
                    return GaiaListRow(
                      first: i == 0,
                      title: _s(b, 'customer_name', 'Guest'),
                      detail: 'Party of ${b['number_of_people'] ?? '\u2014'}'
                          '${whenOf(b).isEmpty ? '' : ' \u00b7 ${whenOf(b)}'}',
                      value: table.isEmpty ? '\u2014' : table,
                      valueUnit: _s(b, 'status', 'Requested'),
                      dotColor: i == flowIndex
                          ? GaiaColors.champagne
                          : _gaiaStatusInk(bookingColor(_s(b, 'status', 'Requested'))),
                      onTap: () => goTo(i),
                    );
                  }),
                const SizedBox(height: GaiaSpacing.xxl),
                Text(
                  'Bookings taken by phone land here too. The guest reservation '
                  'link opens the same list from the other side.',
                  style: GaiaType.italNote(),
                ),
              ],
            ],
          ));
        }

        return Column(children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
            child: SectionHeader(
              title: 'Bookings',
              count: rows.length,
              padding: EdgeInsets.zero,
              trailing: ForkButton.ghost(
                label: 'Share reservation link',
                icon: Icons.qr_code_2,
                dense: true,
                onPressed: showReservationQr,
              ),
            ),
          ),
          Expanded(child: list),
        ]);
  }
}

/// Staff-facing seating suggester: "Party of 8 needs 2 tables — combine
/// T1 + T2?". Shows the server's best clubbing of adjacent (consecutively
/// numbered) FREE tables, the runners-up, and a manual override built from every
/// free table. Pops the chosen table names, primary first — or null. It decides
/// nothing on its own: closing the dialog assigns nothing.
/// The "New booking" form: who, how many, when. Table choice happens AFTER
/// this dialog, driven by the seating suggester, so the form never offers a
/// table the party cannot use.
class _NewBookingDialog extends StatefulWidget {
  const _NewBookingDialog();

  @override
  State<_NewBookingDialog> createState() => _NewBookingDialogState();
}

class _NewBookingDialogState extends State<_NewBookingDialog> {
  final _name = TextEditingController();
  final _phone = TextEditingController();
  final _source = TextEditingController();
  int _party = 2;
  late DateTime _at;
  String? _err;

  @override
  void initState() {
    super.initState();
    // Default to the next full hour — the common "they are on the phone now"
    // case books for later today.
    final now = DateTime.now();
    _at = DateTime(now.year, now.month, now.day, now.hour + 1);
  }

  @override
  void dispose() {
    _name.dispose();
    _phone.dispose();
    _source.dispose();
    super.dispose();
  }

  Future<void> _pickDateTime() async {
    final d = await showDatePicker(
      context: context,
      initialDate: _at,
      firstDate: DateTime.now().subtract(const Duration(days: 1)),
      lastDate: DateTime.now().add(const Duration(days: 90)),
    );
    if (d == null || !mounted) return;
    final t = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(_at));
    if (t == null || !mounted) return;
    setState(() => _at = DateTime(d.year, d.month, d.day, t.hour, t.minute));
  }

  void _save() {
    final name = _name.text.trim();
    // Same rule POST /add-booking enforces server-side (normalizeMobile10):
    // exactly 10 digits once formatting is stripped, so the dialog can never
    // submit something the API will 400.
    final digits = _phone.text.replaceAll(RegExp(r'[^0-9]'), '');
    final phone = digits.length == 12 && digits.startsWith('91')
        ? digits.substring(2)
        : digits.length == 11 && digits.startsWith('0')
            ? digits.substring(1)
            : digits;
    if (name.isEmpty) { setState(() => _err = 'Customer name is required'); return; }
    if (phone.length != 10) { setState(() => _err = 'Enter a 10-digit mobile number'); return; }
    if (_at.isBefore(DateTime.now().subtract(const Duration(minutes: 1)))) {
      setState(() => _err = 'Pick a future date and time');
      return;
    }
    Navigator.pop(context, <String, dynamic>{
      'name': name,
      'phone': phone,
      'party': _party,
      'at': _at,
      'source': _source.text.trim(),
    });
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return AlertDialog(
      title: const Text('New booking'),
      content: SingleChildScrollView(
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          TextField(controller: _name, decoration: const InputDecoration(labelText: 'Customer name'), textCapitalization: TextCapitalization.words),
          const SizedBox(height: 10),
          TextField(controller: _phone, decoration: const InputDecoration(labelText: 'Mobile (10 digits)'), keyboardType: TextInputType.phone),
          const SizedBox(height: 10),
          Row(children: [
            Text('Party', style: text.titleSmall),
            const Spacer(),
            IconButton(onPressed: _party > 1 ? () => setState(() => _party--) : null, icon: const Icon(Icons.remove_circle_outline)),
            Text('$_party', style: text.titleMedium),
            IconButton(onPressed: _party < 30 ? () => setState(() => _party++) : null, icon: const Icon(Icons.add_circle_outline)),
          ]),
          InkWell(
            onTap: _pickDateTime,
            borderRadius: AppRadius.controlAll,
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Row(children: [
                Icon(Icons.schedule, size: 16, color: AppColors.textSecondary),
                const SizedBox(width: 8),
                Text('${_fmtDmy(_at.toIso8601String())} · ${TimeOfDay.fromDateTime(_at).format(context)}', style: text.titleSmall),
                const Spacer(),
                Text('Change', style: text.bodySmall!.copyWith(color: AppColors.copperHi)),
              ]),
            ),
          ),
          const SizedBox(height: 4),
          TextField(controller: _source, decoration: const InputDecoration(labelText: 'Source (optional)', hintText: 'Phone, walk-in, EazyDiner…')),
          if (_err != null) ...[
            const SizedBox(height: 10),
            Text(_err!, style: text.bodySmall!.copyWith(color: AppColors.danger)),
          ],
        ]),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
        FilledButton(onPressed: _save, child: const Text('Choose table')),
      ],
    );
  }
}

class _SeatingSuggestionDialog extends StatefulWidget {
  final Map suggestion;
  final int party;
  const _SeatingSuggestionDialog({required this.suggestion, required this.party});

  @override
  State<_SeatingSuggestionDialog> createState() => _SeatingSuggestionDialogState();
}

class _SeatingSuggestionDialogState extends State<_SeatingSuggestionDialog> {
  // Staff asked to pick their own tables instead of taking a suggestion.
  bool _override = false;
  final _picked = <String>{};

  List<Map> get _combos => ((widget.suggestion['combinations'] as List?) ?? const []).cast<Map>();
  List<Map> get _free => ((widget.suggestion['free_tables'] as List?) ?? const []).cast<Map>();
  String get _noneReason => _s(widget.suggestion, 'none_reason', '');
  List<String> get _unnumbered => _strList(widget.suggestion['unnumbered_free_tables']);

  // Free tables in server order, filtered to the manual selection.
  List<String> get _pickedInOrder => _free
      .map((t) => _s(t, 'table_name', ''))
      .where((n) => n.isNotEmpty && _picked.contains(n))
      .toList();

  int get _pickedSeats => _free
      .where((t) => _picked.contains(_s(t, 'table_name', '')))
      .fold(0, (sum, t) => sum + (_int(t['max_capacity']) ?? _int(t['capacity']) ?? 0));

  static List<String> _namesOf(Map combo) => _strList(combo['table_names']);

  // One proposed combination: the tables, their pooled seats, and the accept.
  Widget _comboCard(Map combo, {required bool primary}) {
    final text = Theme.of(context).textTheme;
    final names = _namesOf(combo);
    final seats = _int(combo['total_capacity']) ?? 0;
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: primary ? AppColors.tint(AppColors.copper) : AppColors.inset,
        borderRadius: AppRadius.cardAll,
        border: Border.all(color: primary ? AppColors.edge(AppColors.copper) : AppColors.border),
      ),
      child: Row(children: [
        Icon(names.length > 1 ? Icons.link : Icons.table_restaurant_outlined,
            size: 16, color: primary ? AppColors.copperHi : AppColors.textSecondary),
        const SizedBox(width: 10),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text(names.join(' + '),
                style: primary ? text.titleSmall!.copyWith(color: AppColors.copperHi) : text.titleSmall,
                maxLines: 2,
                overflow: TextOverflow.ellipsis),
            const SizedBox(height: 2),
            Text('$seats seats · party of ${widget.party}', style: text.bodySmall!.copyWith(fontSize: 11.5)),
          ]),
        ),
        const SizedBox(width: 10),
        if (primary)
          ForkButton(
            label: 'Accept',
            icon: Icons.check,
            dense: true,
            onPressed: () => Navigator.pop(context, names),
          )
        else
          ForkButton.ghost(label: 'Use', dense: true, onPressed: () => Navigator.pop(context, names)),
      ]),
    );
  }

  // Manual override — every free table, tap to add it to the party's set.
  Widget _overridePicker() {
    final text = Theme.of(context).textTheme;
    if (_free.isEmpty) {
      return Text('No tables are free for this slot.', style: text.bodySmall!.copyWith(color: AppColors.danger));
    }
    final chosen = _pickedInOrder;
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, mainAxisSize: MainAxisSize.min, children: [
      for (final t in _free)
        Builder(builder: (_) {
          final name = _s(t, 'table_name', '');
          final on = _picked.contains(name);
          return InkWell(
            onTap: name.isEmpty
                ? null
                : () => setState(() => on ? _picked.remove(name) : _picked.add(name)),
            borderRadius: AppRadius.controlAll,
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
              child: Row(children: [
                Icon(on ? Icons.check_box : Icons.check_box_outline_blank,
                    size: 18, color: on ? AppColors.copperHi : AppColors.textTertiary),
                const SizedBox(width: 10),
                Expanded(child: Text(name, style: text.titleSmall)),
                Text(_seatsLabel(t), style: text.bodySmall!.copyWith(fontSize: 11.5)),
              ]),
            ),
          );
        }),
      const SizedBox(height: 10),
      Row(children: [
        Expanded(
          child: Text(
            chosen.isEmpty
                ? 'Pick one or more tables.'
                : '${chosen.join(' + ')} · $_pickedSeats seats for ${widget.party}',
            style: text.bodySmall!.copyWith(
              fontSize: 11.5,
              color: chosen.isNotEmpty && _pickedSeats < widget.party ? AppColors.warning : AppColors.textSecondary,
            ),
          ),
        ),
        const SizedBox(width: 10),
        ForkButton(
          label: 'Assign',
          icon: Icons.check,
          dense: true,
          onPressed: chosen.isEmpty ? null : () => Navigator.pop(context, chosen),
        ),
      ]),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final combos = _combos;
    final best = combos.isEmpty ? null : combos.first;
    return AlertDialog(
      title: Text(best == null
          ? 'No table fits a party of ${widget.party}'
          : 'Party of ${widget.party} needs ${_namesOf(best).length} tables'),
      content: SizedBox(
        width: 420,
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (best != null) ...[
              Text('Combine ${_namesOf(best).join(' + ')}?',
                  style: text.bodyMedium!.copyWith(color: AppColors.textSecondary)),
              const SizedBox(height: 10),
              _comboCard(best, primary: true),
              if (combos.length > 1) ...[
                const SizedBox(height: 6),
                Text('Other options', style: text.labelSmall),
                const SizedBox(height: 6),
                for (final c in combos.skip(1)) _comboCard(c, primary: false),
              ],
            ] else ...[
              // The server's own words for why nothing fits — never one we invent.
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: AppColors.tint(AppColors.warning),
                  borderRadius: AppRadius.cardAll,
                  border: Border.all(color: AppColors.edge(AppColors.warning)),
                ),
                child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Icon(Icons.info_outline, size: 16, color: AppColors.warning),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      _noneReason.isEmpty || _noneReason == '—'
                          ? 'No free table or adjacent group can seat ${widget.party} at that time.'
                          : _noneReason,
                      style: text.bodySmall,
                    ),
                  ),
                ]),
              ),
            ],
            if (_unnumbered.isNotEmpty && best == null) ...[
              const SizedBox(height: 8),
              Text('${_unnumbered.join(', ')} cannot be clubbed automatically — no number in the name.',
                  style: text.bodySmall!.copyWith(fontSize: 11.5, color: AppColors.textTertiary)),
            ],
            const SizedBox(height: 12),
            if (!_override)
              Align(
                alignment: Alignment.centerLeft,
                child: ForkButton.ghost(
                  label: best == null ? 'Choose tables manually' : 'Choose different tables',
                  icon: Icons.tune,
                  dense: true,
                  onPressed: () => setState(() => _override = true),
                ),
              )
            else ...[
              Text('Free tables', style: text.labelSmall),
              const SizedBox(height: 6),
              _overridePicker(),
            ],
          ]),
        ),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
      ],
    );
  }
}

// Resolve a service-recovery ticket (low-rating feedback) with an optional note.
Future<void> _resolveRecovery(BuildContext context, RestClient rest, String id, VoidCallback reload) async {
  final messenger = ScaffoldMessenger.of(context);
  final noteCtrl = TextEditingController();
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: const Text('Resolve recovery ticket'),
      content: TextField(
        controller: noteCtrl,
        minLines: 1,
        maxLines: 3,
        decoration: const InputDecoration(labelText: 'How was it resolved? (optional)', border: OutlineInputBorder()),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Mark resolved')),
      ],
    ),
  );
  if (ok != true) return;
  try {
    await rest.post('/feedback/recovery/$id/resolve', {if (noteCtrl.text.trim().isNotEmpty) 'note': noteCtrl.text.trim()});
    reload();
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

// Per-waiter feedback QR: each employee gets a QR/link that pre-fills the
// feedback form with their eid (Employees.id) so responses are attributed to
// them. The link targets the dashboard-hosted /feedback page (orderBaseUrl) and
// carries rid=<slug> + oid=<outletId> + eid=<employeeId>, matching the contract
// the printed bill QR and post-payment redirect already use.
/// [feedback] is the loaded response list, used only to answer "is this waiter's
/// QR actually being scanned, and what do they score?" behind a button on each
/// row. The card itself stays untappable on purpose: it holds a selectable URL,
/// and a gesture over the whole card would fight selecting it.
Widget _employeeFeedbackQrSection(Profile p, List employees, List feedback) {
  final rows = employees.whereType<Map>().where((e) => '${e['id'] ?? e['employee_id'] ?? ''}'.isNotEmpty).toList();
  if (rows.isEmpty) return const SizedBox.shrink();
  String urlFor(String eid) =>
      '${AppConfig.orderBaseUrl}/feedback?rid=${p.restaurantUsername}&oid=${p.outletId}&eid=$eid';
  return ForkCard(
    padding: EdgeInsets.zero,
    child: Builder(
      builder: (context) => Theme(
        data: Theme.of(context).copyWith(dividerColor: Colors.transparent),
        child: ExpansionTile(
          shape: const Border(),
          collapsedShape: const Border(),
          iconColor: AppColors.copperHi,
          collapsedIconColor: AppColors.textTertiary,
          tilePadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
          leading: Container(
            width: 36,
            height: 36,
            decoration: BoxDecoration(
              color: AppColors.inset,
              borderRadius: AppRadius.controlAll,
              border: Border.all(color: AppColors.border),
            ),
            child: Icon(Icons.qr_code_2, size: 18, color: AppColors.copper),
          ),
          title: Text('Per-waiter feedback QR', style: Theme.of(context).textTheme.titleSmall),
          subtitle: Padding(
            padding: const EdgeInsets.only(top: 2),
            child: Text('A QR/link per waiter — feedback scanned here is tagged to them',
                style: Theme.of(context).textTheme.bodySmall),
          ),
          childrenPadding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
          children: [
            for (final e in rows)
              Builder(builder: (context) {
                final eid = '${e['id'] ?? e['employee_id'] ?? ''}';
                final name = '${_s(e, 'emp_Fname', '')} ${_s(e, 'emp_Lname', '')}'.trim();
                final label = name.isEmpty ? _s(e, 'employee_Username') : name;
                final url = urlFor(eid);
                final text = Theme.of(context).textTheme;
                return Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: ForkCard(
                    inset: true,
                    padding: const EdgeInsets.all(12),
                    child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      // Paper exception: the QR keeps a white quiet zone so it
                      // stays scannable — printed-output styling, black on white.
                      Container(
                        padding: const EdgeInsets.all(6),
                        decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(6),
                        ),
                        child: QrImageView(data: url, size: 96, backgroundColor: Colors.white),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      Expanded(
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Text(label, style: text.titleSmall),
                          const SizedBox(height: 2),
                          Text('@${_s(e, 'employee_Username')}', style: text.bodySmall),
                          const SizedBox(height: 6),
                          SelectableText(url, style: text.bodySmall!.copyWith(fontSize: 11)),
                          const SizedBox(height: 6),
                          // Wrapped, not a Row: at 1.3x on a phone these two
                          // buttons are wider than the column they sit in.
                          Wrap(spacing: AppSpacing.sm, runSpacing: AppSpacing.sm, children: [
                            ForkButton.subtle(
                              label: 'Copy link',
                              icon: Icons.copy,
                              onPressed: () async {
                                await Clipboard.setData(ClipboardData(text: url));
                                if (context.mounted) {
                                  ScaffoldMessenger.of(context).showSnackBar(
                                      const SnackBar(content: Text('Feedback link copied')));
                                }
                              },
                            ),
                            ForkButton.subtle(
                              label: 'Their feedback',
                              icon: Icons.reviews_outlined,
                              onPressed: () => _waiterFeedbackSheet(context, label, eid, feedback),
                            ),
                          ]),
                        ]),
                      ),
                    ]),
                  ),
                );
              }),
          ],
        ),
      ),
    ),
  );
}

// --- Feedback drill-downs ----------------------------------------------------
// Every figure on the Feedback tab opens what is behind it, computed from the
// two payloads the module already holds — the `/feedback` rows and
// `/feedback/summary`. Nothing here fetches again.
//
// One honesty constraint runs through all of them: `/feedback` returns the
// newest 100 responses while the summary is computed over every response ever
// recorded. Any figure derived from the rows says so, rather than quietly
// presenting a sample as the whole history.

/// How many responses landed on each whole star, 1..5. `overall_rating` is the
/// mean of the per-question scores, so it is rounded to the star a guest would
/// read off the page. Unrated rows are not counted at all.
List<int> _ratingSpread(List items) {
  final out = List<int>.filled(5, 0);
  for (final m in items.whereType<Map>()) {
    final raw = _numOf(m['overall_rating']);
    if (raw <= 0) continue;
    final star = raw.round();
    out[(star < 1 ? 1 : (star > 5 ? 5 : star)) - 1]++;
  }
  return out;
}

String _pctOf(num part, num whole) => whole > 0 ? '${(part / whole * 100).toStringAsFixed(0)}%' : '—';

/// Everything the "Responses" tile counts but cannot show: where the responses
/// came in from, how many carried words rather than only stars, and the stretch
/// of time the list actually covers.
Future<void> _feedbackVolumeSheet(BuildContext context, Map sum, List items) {
  final rows = items.whereType<Map>().toList();
  final total = _int(sum['totalResponses']) ?? rows.length;
  final withComment = rows.where((m) => _s(m, 'comments', '').isNotEmpty).length;
  final withNps = rows.where((m) => m['nps'] != null).length;
  final bySource = <String, int>{};
  for (final m in rows) {
    final src = _s(m, 'source', '').trim();
    final key = src.isEmpty || src == '—' ? 'Not recorded' : src;
    bySource[key] = (bySource[key] ?? 0) + 1;
  }
  final sources = bySource.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
  // The server sends the rows newest-first, so the ends of the list are the
  // ends of the window.
  final newest = rows.isEmpty ? '' : _s(rows.first, 'submitted_at', '');
  final oldest = rows.isEmpty ? '' : _s(rows.last, 'submitted_at', '');

  return _detailSheet(
    context,
    eyebrow: 'Responses',
    title: '$total in total',
    children: [
      _detailRow(context, 'All time', '$total'),
      _detailRow(context, 'Last 30 days', '${_int(sum['last30DaysResponses']) ?? 0}'),
      _detailRow(context, 'Loaded below', '${rows.length}'),
      if (newest.isNotEmpty) _detailRow(context, 'Newest', _fmtTime(newest)),
      if (oldest.isNotEmpty && rows.length > 1) _detailRow(context, 'Oldest loaded', _fmtTime(oldest)),
      Padding(
        padding: const EdgeInsets.only(top: 14, bottom: 2),
        child: Text('OF THE ${rows.length} LOADED', style: Theme.of(context).textTheme.labelSmall),
      ),
      _detailRow(context, 'Left a comment', '$withComment', trailing: _pctOf(withComment, rows.length)),
      _detailRow(context, 'Answered "would recommend"', '$withNps', trailing: _pctOf(withNps, rows.length)),
      if (sources.isNotEmpty) ...[
        Padding(
          padding: const EdgeInsets.only(top: 14, bottom: 2),
          child: Text('WHERE THEY CAME IN', style: Theme.of(context).textTheme.labelSmall),
        ),
        for (final s in sources)
          _detailRow(context, s.key, '${s.value}', trailing: _pctOf(s.value, rows.length)),
      ],
    ],
  );
}

/// The spread and the per-question averages behind a single average score. The
/// tile can only show the mean, and a 4.0 made of straight 4s is a different
/// restaurant from a 4.0 made of 5s and 1s.
Future<void> _feedbackRatingSheet(BuildContext context, Map sum, List items) {
  final spread = _ratingSpread(items);
  final rated = spread.fold<int>(0, (a, b) => a + b);
  final cats = (sum['categoryAverages'] as Map?) ?? const {};
  final catRows = cats.entries.map((e) {
    final v = (e.value as Map?) ?? const {};
    return (label: _s(v, 'label', '${e.key}'), avg: v['average']);
  }).toList()
    ..sort((a, b) => _numOf(a.avg).compareTo(_numOf(b.avg)));
  final unhappy = spread[0] + spread[1];

  return _detailSheet(
    context,
    eyebrow: 'Average rating',
    title: '${sum['averageRating'] ?? '—'} / 5',
    children: [
      _detailRow(context, 'Responses scored', '$rated'),
      _detailRow(context, 'At 2 stars or below', '$unhappy', trailing: _pctOf(unhappy, rated)),
      Padding(
        padding: const EdgeInsets.only(top: 14, bottom: 2),
        child: Text('HOW THE SCORES FALL', style: Theme.of(context).textTheme.labelSmall),
      ),
      for (var star = 5; star >= 1; star--)
        _detailRow(context, '$star star${star == 1 ? '' : 's'}', '${spread[star - 1]}',
            trailing: _pctOf(spread[star - 1], rated)),
      Padding(
        padding: const EdgeInsets.only(top: 14, bottom: 2),
        child: Text('BY QUESTION — WORST FIRST', style: Theme.of(context).textTheme.labelSmall),
      ),
      if (catRows.isEmpty)
        Text('No per-question ratings have been recorded.', style: Theme.of(context).textTheme.bodySmall)
      else
        for (final c in catRows)
          _detailRow(context, c.label, c.avg == null ? '—' : '${_score(c.avg)} / 5'),
      Padding(
        padding: const EdgeInsets.only(top: 8),
        child: Text(
          'The spread is over the responses loaded below. The question averages come from '
          'every response ever recorded, so the two need not add up.',
          style: Theme.of(context).textTheme.bodySmall!.copyWith(color: AppColors.textTertiary, height: 1.35),
        ),
      ),
    ],
  );
}

/// Who is still waiting to be called back. Reached from the "Recovery" tile,
/// which is ALWAYS tappable: at zero this sheet explains what service recovery
/// is and when a ticket lands here, because a tile whose caption names a
/// concept the owner may not know yet cannot be the thing that explains it by
/// staying silent. (It used to go inert at zero, and that read as a broken
/// control, not a considered one.)
Future<void> _recoveryQueueSheet(BuildContext context, List tickets) {
  final rows = tickets.whereType<Map>().toList();
  final worst = [...rows]..sort((a, b) => _numOf(a['overall_rating']).compareTo(_numOf(b['overall_rating'])));
  final text = Theme.of(context).textTheme;
  return _detailSheet(
    context,
    eyebrow: 'Service recovery',
    title: rows.isEmpty ? 'All clear' : '${rows.length} open',
    children: [
      if (rows.isEmpty) ...[
        Text(
          'No guest is waiting on a follow-up right now.',
          style: text.bodyMedium,
        ),
        const SizedBox(height: AppSpacing.sm),
        Text(
          'Any feedback scored 2 out of 5 or below opens a recovery ticket here '
          'the moment it arrives, and the manager bell is pinged at the same '
          'time. Tickets stay in this queue until someone follows the guest up '
          'and marks them resolved with a note.',
          style: text.bodySmall,
        ),
      ] else ...[
        Text('Low-rating feedback that nobody has followed up yet, lowest score first.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.sm),
        for (final t in worst)
          _detailRow(
            context,
            _s(t, 'customer_name', 'Guest'),
            '${_score(t['overall_rating'])} / 5',
            trailing: _fmtTime(_s(t, 'submitted_at')),
          ),
      ],
    ],
  );
}

/// The full record behind a recovery ticket.
///
/// Not a re-print of the card: the recovery reader returns only
/// `{key,label,rating,follow_up_answer}` per question, so the card cannot show
/// the QUESTION that was asked, the follow-up prompt, the recommend score or
/// the source. Those live on the matching row in the main feedback list, which
/// is joined here by id, and the ticket's own resolution fields are shown too.
Future<void> _recoveryTicketSheet(BuildContext context, Map ticket, List items) {
  final id = '${ticket['id'] ?? ''}';
  final full = items.whereType<Map>().where((m) => '${m['id'] ?? ''}' == id).firstOrNull;
  final cats = ((full ?? ticket)['category_ratings'] as List?)?.whereType<Map>().toList() ?? const <Map>[];
  final comment = _s(ticket, 'comments', '');
  final text = Theme.of(context).textTheme;

  Widget head(String s) => Padding(
        padding: const EdgeInsets.only(top: 14, bottom: 2),
        child: Text(s, style: text.labelSmall),
      );

  return _detailSheet(
    context,
    eyebrow: 'Recovery ticket · ${_s(ticket, 'recovery_status', 'open')}',
    title: _s(ticket, 'customer_name', 'Guest'),
    children: [
      _detailRow(context, 'Overall', '${_score(ticket['overall_rating'])} / 5'),
      _detailRow(context, 'Submitted', _fmtTime(_s(ticket, 'submitted_at'))),
      if (full != null && full['nps'] != null)
        _detailRow(context, 'Would recommend', '${_numOf(full['nps']).toStringAsFixed(0)} / 10'),
      if (full != null && _s(full, 'source').isNotEmpty) _detailRow(context, 'Came in via', _s(full, 'source')),
      if (comment.isNotEmpty) ...[
        head('IN THEIR WORDS'),
        Text('"$comment"', style: text.bodyMedium!.copyWith(fontStyle: FontStyle.italic)),
      ],
      head('QUESTION BY QUESTION'),
      if (cats.isEmpty)
        Text('No per-question ratings were recorded.', style: text.bodySmall)
      else
        for (final c in cats) ...[
          _detailRow(context, _s(c, 'label', _s(c, 'key')), '${_score(c['rating'])} / 5'),
          if (_s(c, 'question').isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(left: 8, bottom: 2),
              child: Text(_s(c, 'question'), style: text.labelSmall),
            ),
          if (_s(c, 'follow_up').isNotEmpty || _s(c, 'follow_up_answer').isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(left: 8, bottom: 6),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                if (_s(c, 'follow_up').isNotEmpty) Text(_s(c, 'follow_up'), style: text.labelSmall),
                Text(_s(c, 'follow_up_answer', '').isEmpty ? '— not answered' : _s(c, 'follow_up_answer'),
                    style: text.bodySmall),
              ]),
            ),
        ],
      if (full == null)
        Padding(
          padding: const EdgeInsets.only(top: 10),
          child: Text(
            'The original response is older than the list below, so the question wording and the '
            'recommend score could not be attached.',
            style: text.bodySmall!.copyWith(color: AppColors.textTertiary, height: 1.35),
          ),
        ),
      head('FOLLOW-UP'),
      _detailRow(context, 'Status', _s(ticket, 'recovery_status', 'open')),
      if (_s(ticket, 'recovery_resolved_at', '').isNotEmpty)
        _detailRow(context, 'Resolved', _fmtTime(_s(ticket, 'recovery_resolved_at'))),
      if (_s(ticket, 'recovery_resolved_by', '').isNotEmpty)
        _detailRow(context, 'Resolved by', _s(ticket, 'recovery_resolved_by')),
      if (_s(ticket, 'recovery_note', '').isNotEmpty) Text(_s(ticket, 'recovery_note'), style: text.bodySmall),
      // "Resolve" stays on the card. It closes a ticket, and closing one is not
      // what tapping a row to read it should resolve to.
    ],
  );
}

/// How one waiter's own QR is actually performing. Reached from a button on the
/// QR card rather than the card itself — that card holds a selectable URL, and
/// a tap gesture over it would fight text selection.
Future<void> _waiterFeedbackSheet(BuildContext context, String name, String eid, List items) {
  final mine = items.whereType<Map>().where((m) => '${m['employee_id'] ?? ''}' == eid).toList();
  final scored = mine.where((m) => _numOf(m['overall_rating']) > 0).toList();
  final avg = scored.isEmpty
      ? null
      : scored.fold<double>(0, (a, m) => a + _numOf(m['overall_rating'])) / scored.length;
  final spread = _ratingSpread(mine);
  final text = Theme.of(context).textTheme;

  return _detailSheet(
    context,
    eyebrow: 'Feedback tagged to this waiter',
    title: name,
    children: [
      if (mine.isEmpty)
        Text(
          'No loaded response is tagged to them. Either their QR has not been scanned yet, or their '
          'responses are older than the newest ${items.length} shown on this page.',
          style: text.bodySmall,
        )
      else ...[
        _detailRow(context, 'Responses', '${mine.length}'),
        _detailRow(context, 'Average', avg == null ? '—' : '${avg.toStringAsFixed(2)} / 5'),
        _detailRow(context, 'At 2 stars or below', '${spread[0] + spread[1]}',
            trailing: _pctOf(spread[0] + spread[1], scored.length)),
        Padding(
          padding: const EdgeInsets.only(top: 14, bottom: 2),
          child: Text('MOST RECENT', style: text.labelSmall),
        ),
        for (final m in mine.take(6))
          _detailRow(
            context,
            _s(m, 'customer_name', 'Guest'),
            '${_score(m['overall_rating'])} / 5',
            trailing: _fmtTime(_s(m, 'submitted_at')),
          ),
        if (mine.length > 6)
          Padding(
            padding: const EdgeInsets.only(top: 6),
            child: Text('and ${mine.length - 6} more in the list below.', style: text.bodySmall),
          ),
      ],
    ],
  );
}

Widget feedbackModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () async {
        final summary = await rest.getMap('/feedback/summary');
        final raw = await rest.get('/feedback');
        final items = raw is Map ? (raw['items'] as List? ?? []) : (raw as List? ?? []);
        final recovery = await rest.getMap('/feedback/recovery').catchError((_) => <String, dynamic>{});
        // Employees drive the per-waiter feedback QR section; tolerate no access.
        final usersRes = await rest.getMap('/restaurant/users').catchError((_) => <String, dynamic>{});
        return {
          'summary': summary,
          'items': items,
          'tickets': (recovery['tickets'] as List?) ?? [],
          'employees': (usersRes['users'] as List?) ?? [],
        };
      },
      builder: (context, data, reload) {
        final sum = (data['summary'] as Map?) ?? {};
        final items = (data['items'] as List?) ?? [];
        final tickets = (data['tickets'] as List?) ?? [];
        final employees = (data['employees'] as List?) ?? [];
        final text = Theme.of(context).textTheme;
        final avgRating = double.tryParse('${sum['averageRating'] ?? 0}') ?? 0;
        // GAIA: the BOKEH treatment. Same four payloads, same sheets, same
        // recovery actions — a different drawing. It is a separate widget only
        // because the field behind it needs a ScrollController to drift
        // against, and this builder is a function with nowhere to keep one.
        if (Gaia.of(context)) {
          return _GaiaFeedbackBody(
            rest: rest,
            profile: p,
            summary: sum,
            items: items,
            tickets: tickets,
            employees: employees,
            reload: reload,
          );
        }
        // A low-rating alert asked us to focus one response.
        final focus = _focusOf(context, 'Feedback');
        final focusId = focus?.idOf(const ['feedback_id']);
        bool isFocused(Map m) => focusId != null && '${m['id']}' == focusId;
        final focusFound = focusId != null &&
            (items.any((m) => isFocused(m as Map)) || tickets.any((m) => isFocused(m as Map)));
        String initialsOf(String name) {
          final parts = name.trim().split(RegExp(r'\s+')).where((s) => s.isNotEmpty).toList();
          if (parts.isEmpty) return '?';
          return parts.length == 1
              ? parts.first.substring(0, 1)
              : '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}';
        }

        return ListView(padding: AppSpacing.pageNarrow, children: [
          if (focus != null)
            _focusBanner(
              context,
              found: focusFound,
              message: focusFound
                  ? 'Highlighted the response from your notification.'
                  : "That response isn't in this list — it may have been removed, or belong to another outlet.",
            ),
          Wrap(spacing: 12, runSpacing: 12, children: [
            _statCard(context, 'Responses', '${sum['totalResponses'] ?? 0}', Icons.reviews,
                onTap: () => _feedbackVolumeSheet(context, sum, items)),
            SizedBox(
              width: 200,
              child: StatCard(
                value: '${sum['averageRating'] ?? 0}',
                unit: '/ 5',
                caption: 'AVG RATING',
                chart: Align(
                  alignment: Alignment.centerLeft,
                  child: DonutGauge(fraction: (avgRating / 5).clamp(0.0, 1.0), size: 46),
                ),
                onTap: () => _feedbackRatingSheet(context, sum, items),
              ),
            ),
            SizedBox(
              width: 200,
              child: StatCard(
                value: '${tickets.length}',
                caption: 'RECOVERY',
                tag: tickets.isNotEmpty ? 'Open' : null,
                tagColor: AppColors.danger,
                // Always opens the queue. This tile used to go inert at zero,
                // and a real owner read that as a broken control — "recovery
                // is not clickable" — because nothing on the tile says what
                // RECOVERY even is. The sheet now owns the empty case: it
                // explains what lands here and when, instead of eating the tap.
                onTap: () => _recoveryQueueSheet(context, tickets),
              ),
            ),
          ]),
          const SizedBox(height: AppSpacing.xxl),
          _employeeFeedbackQrSection(p, employees, items),
          const SizedBox(height: AppSpacing.xxl),
          if (tickets.isNotEmpty) ...[
            SectionHeader(
              title: 'Service recovery',
              count: tickets.length,
              trailing: StatusChip(label: 'Needs follow-up', color: AppColors.danger, dense: true),
            ),
            ...tickets.map((t) {
              final m = t as Map;
              final cats = (m['category_ratings'] as List?) ?? [];
              return Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: ForkCard(
                  selected: isFocused(m),
                  // Opens the full response — the question wording, the
                  // follow-up prompts and the recommend score the recovery
                  // reader does not return. "Resolve" keeps its own button so
                  // reading a complaint can never close it.
                  onTap: () => _recoveryTicketSheet(context, m, items),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    _recordHeadRow(
                      context,
                      leading: InitialsAvatar(
                          initials: '${m['overall_rating'] ?? '-'}', color: AppColors.danger),
                      identity: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text(_s(m, 'customer_name', 'Guest'),
                            style: text.titleSmall, maxLines: 2, overflow: TextOverflow.ellipsis),
                        const SizedBox(height: 2),
                        // Not the raw ISO date: submitted_at is a UTC instant,
                        // so slicing at the "T" dates a 1am review to the
                        // previous day in Asia/Kolkata.
                        Text(_fmtTime(_s(m, 'submitted_at')), style: text.bodySmall),
                      ]),
                      trailing: [
                        StatusChip(label: 'Low rating', color: AppColors.danger, dense: true),
                        ForkButton(
                          label: 'Resolve',
                          dense: true,
                          onPressed: () => _resolveRecovery(context, rest, '${m['id']}', reload),
                        ),
                      ],
                    ),
                    if (_s(m, 'comments').isNotEmpty)
                      Padding(
                        padding: const EdgeInsets.only(top: 8),
                        child: Text('"${_s(m, 'comments')}"',
                            style: text.bodyMedium!.copyWith(fontStyle: FontStyle.italic)),
                      ),
                    ...cats.map((c) {
                      final cm = c as Map;
                      final ans = _s(cm, 'follow_up_answer');
                      return Padding(
                        padding: const EdgeInsets.only(top: 6),
                        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          InfoChip(icon: Icons.star_outline, label: '${_s(cm, 'label')} · ${cm['rating']}/5'),
                          if (ans.isNotEmpty) ...[
                            const SizedBox(width: AppSpacing.sm),
                            Expanded(child: Text(ans, style: text.bodySmall)),
                          ],
                        ]),
                      );
                    }),
                  ]),
                ),
              );
            }),
            const SizedBox(height: AppSpacing.lg),
          ],
          SectionHeader(title: 'All feedback', count: items.length),
          if (items.isEmpty)
            _empty('No feedback yet.')
          else
            StatefulBuilder(builder: (context, setLocal) => Column(
              mainAxisSize: MainAxisSize.min,
              children: [
            ...items.map((it) {
              final m = it as Map;
              final guest = _s(m, 'customer_name', 'Guest');
              final id = '${m['id'] ?? ''}';
              final open = _feedbackOpenId == id && id.isNotEmpty;
              final cats = (m['category_ratings'] as List?) ?? const [];
              final nps = m['nps'];
              final comment = _s(m, 'comments', '');
              return Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: ForkCard(
                  selected: isFocused(m),
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                  // Tapping opens the full question-by-question breakdown; the
                  // collapsed row alone can't show WHY a score is what it is.
                  onTap: id.isEmpty ? null : () => setLocal(() => _feedbackOpenId = open ? '' : id),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                    Row(children: [
                      InitialsAvatar(initials: initialsOf(guest)),
                      const SizedBox(width: AppSpacing.md),
                      Expanded(
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                          Text(guest, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                          const SizedBox(height: 2),
                          Text(comment.isNotEmpty ? comment : '${cats.length} question${cats.length == 1 ? '' : 's'} answered',
                              style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
                        ]),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      Column(crossAxisAlignment: CrossAxisAlignment.end, mainAxisSize: MainAxisSize.min, children: [
                        MicroStat(value: '${_score(m['overall_rating'])} / 5', label: 'Rating', alignEnd: true),
                        const SizedBox(height: 4),
                        Text(_fmtTime(_s(m, 'submitted_at')).toUpperCase(), style: text.labelSmall),
                      ]),
                      if (id.isNotEmpty) ...[
                        const SizedBox(width: 4),
                        Icon(open ? Icons.expand_less : Icons.expand_more, size: 18, color: AppColors.textSecondary),
                      ],
                    ]),
                    if (open) ...[
                      const SizedBox(height: AppSpacing.md),
                      const Divider(height: 1),
                      const SizedBox(height: AppSpacing.md),
                      if (cats.isEmpty)
                        Text('No per-question ratings were recorded.', style: text.bodySmall)
                      else
                        ...cats.map((c) {
                          final cm = c as Map;
                          final r = _numOf(cm['rating']);
                          final followUp = _s(cm, 'follow_up');
                          final answer = _s(cm, 'follow_up_answer');
                          return Padding(
                            padding: const EdgeInsets.only(bottom: 8),
                            child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                              Row(children: [
                                Expanded(
                                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                                    Text(_s(cm, 'label', _s(cm, 'key')), style: text.bodyMedium),
                                    if (_s(cm, 'question').isNotEmpty)
                                      Text(_s(cm, 'question'), style: text.labelSmall),
                                  ]),
                                ),
                                StatusChip(
                                  label: '${r.toStringAsFixed(0)}/5',
                                  color: r <= 2 ? AppColors.danger : (r >= 4 ? AppColors.success : AppColors.warning),
                                  dense: true,
                                ),
                              ]),
                              if (followUp.isNotEmpty)
                                Padding(
                                  padding: const EdgeInsets.only(left: 8, top: 4),
                                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                                    Text(followUp, style: text.labelSmall),
                                    Text(answer.isNotEmpty ? answer : '— not answered', style: text.bodySmall),
                                  ]),
                                ),
                            ]),
                          );
                        }),
                      const SizedBox(height: 4),
                      Wrap(spacing: 12, runSpacing: 4, children: [
                        InfoChip(label: 'Overall ${_score(m['overall_rating'])}/5 (avg of ${cats.length})'),
                        if (nps != null) InfoChip(label: 'Recommend ${_numOf(nps).toStringAsFixed(0)}/10'),
                        if (_s(m, 'source').isNotEmpty) InfoChip(label: 'Via ${_s(m, 'source')}'),
                      ]),
                      if (comment.isNotEmpty) ...[
                        const SizedBox(height: 8),
                        Text(comment, style: text.bodySmall),
                      ],
                    ],
                  ]),
                ),
              );
            }),
              ],
            )),
        ]);
      },
    );

/// GAIA's Feedback screen — the mockup's screen 09.
///
/// The bokeh field, a conic ring for the average, the recovery queue and the
/// full response list as lit rows. Every action the Rustic screen has is here:
/// the three summary drill-downs, the per-waiter QR block (rendered by the very
/// same `_employeeFeedbackQrSection`), the recovery ticket sheet, Resolve, and
/// the question-by-question expansion on a tap.
///
/// Stateful for one reason: [GaiaBokehBackdrop] drifts against a
/// [ScrollController], and `feedbackModule` is a function with nowhere to keep
/// one without leaking it on every rebuild.
class _GaiaFeedbackBody extends StatefulWidget {
  const _GaiaFeedbackBody({
    required this.rest,
    required this.profile,
    required this.summary,
    required this.items,
    required this.tickets,
    required this.employees,
    required this.reload,
  });

  final RestClient rest;
  final Profile profile;
  final Map summary;
  final List items;
  final List tickets;
  final List employees;
  final VoidCallback reload;

  @override
  State<_GaiaFeedbackBody> createState() => _GaiaFeedbackBodyState();
}

class _GaiaFeedbackBodyState extends State<_GaiaFeedbackBody> {
  final ScrollController _scroll = ScrollController();

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  /// Brightness follows how recently a guest spoke, NOT what they scored.
  ///
  /// Deliberate: the score already has the biggest figure on the row, and
  /// dimming a complaint would be the one place this style could actually lie
  /// about the data. An unnamed response dims because there is less of a person
  /// there, which is the same rule the guest book uses.
  GaiaBokehTone _tone(Map m) {
    if (_s(m, 'customer_name', '').isEmpty) return GaiaBokehTone.dim;
    final at = DateTime.tryParse(_s(m, 'submitted_at', ''));
    if (at == null) return GaiaBokehTone.cool;
    return DateTime.now().toUtc().difference(at.toUtc()).inDays <= 30
        ? GaiaBokehTone.warm
        : GaiaBokehTone.cool;
  }

  String _who(Map m) {
    final n = _s(m, 'customer_name', '');
    return n.isEmpty ? 'Anonymous' : n;
  }

  @override
  Widget build(BuildContext context) {
    final sum = widget.summary;
    final items = widget.items;
    final tickets = widget.tickets;
    final avg = double.tryParse('${sum['averageRating'] ?? 0}') ?? 0;

    final focus = _focusOf(context, 'Feedback');
    final focusId = focus?.idOf(const ['feedback_id']);
    bool isFocused(Map m) => focusId != null && '${m['id']}' == focusId;
    final focusFound = focusId != null &&
        (items.any((m) => isFocused(m as Map)) || tickets.any((m) => isFocused(m as Map)));

    return LayoutBuilder(builder: (context, box) => Stack(children: [
      Positioned.fill(
        child: GaiaBokehBackdrop(
          blobs: GaiaBokehBlob.feedback,
          scroll: _scroll,
        ),
      ),
      Positioned.fill(
        child: ListView(
          controller: _scroll,
          padding: _gaiaPagePadding(box.maxWidth),
          children: [
            GaiaPageHeader(
              wordmark: widget.profile.restaurantName,
              meta: '${sum['totalResponses'] ?? 0} responses',
              title: 'What guests',
              titleEmphasis: 'said.',
              sub: 'Ratings, recovery queue and per-waiter QR',
            ),
            if (focus != null) ...[
              _focusBanner(
                context,
                found: focusFound,
                message: focusFound
                    ? 'Highlighted the response from your notification.'
                    : "That response isn't in this list — it may have been removed, or belong to another outlet.",
              ),
              const SizedBox(height: GaiaSpacing.xl),
            ],
            Row(children: [
              GaiaRing(
                fraction: avg / 5,
                value: avg == 0 ? '\u2014' : avg.toStringAsFixed(2),
                unit: '/5',
              ),
              const SizedBox(width: GaiaSpacing.xl),
              Expanded(
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  // Each of the three keeps the drill-down its Rustic stat card
                  // had. A figure that used to open a sheet must not go inert
                  // because the box around it changed.
                  _tappableKv(
                    first: true,
                    label: 'Responses',
                    value: '${sum['totalResponses'] ?? 0}',
                    onTap: () => _feedbackVolumeSheet(context, sum, items),
                  ),
                  _tappableKv(
                    label: 'Average rating',
                    value: '${sum['averageRating'] ?? 0}',
                    onTap: () => _feedbackRatingSheet(context, sum, items),
                  ),
                  _tappableKv(
                    label: 'Recovery queue',
                    value: '${tickets.length}',
                    valueColor:
                        tickets.isEmpty ? GaiaColors.sage : GaiaColors.coral,
                    onTap: () => _recoveryQueueSheet(context, tickets),
                  ),
                ]),
              ),
            ]),
            const SizedBox(height: GaiaSpacing.xxl),
            if (tickets.isNotEmpty) ...[
              GaiaSectionHeader(
                title: 'Service recovery',
                count: tickets.length,
                trailing: const GaiaStatusChip(
                    label: 'Needs follow-up', color: GaiaColors.coral, dense: true),
              ),
              for (var i = 0; i < tickets.length; i++)
                Builder(builder: (context) {
                  final m = tickets[i] as Map;
                  return GaiaBokehRow(
                    first: i == 0,
                    selected: isFocused(m),
                    initials: '${m['overall_rating'] ?? '-'}',
                    tone: GaiaBokehTone.dim,
                    title: _who(m),
                    detail: _s(m, 'comments').isEmpty
                        ? _fmtTime(_s(m, 'submitted_at'))
                        : '"${_s(m, 'comments')}"',
                    // Reading a complaint must never close it, so Resolve keeps
                    // its own control — same rule the Rustic card holds.
                    trailing: GaiaButton(
                      label: 'Resolve',
                      kind: GaiaButtonKind.ghost,
                      dense: true,
                      onPressed: () => _resolveRecovery(
                          context, widget.rest, '${m['id']}', widget.reload),
                    ),
                    onTap: () => _recoveryTicketSheet(context, m, items),
                  );
                }),
              const SizedBox(height: GaiaSpacing.xxl),
            ],
            GaiaSectionHeader(title: 'All feedback', count: items.length),
            if (items.isEmpty)
              Text('No feedback yet.', style: GaiaType.italNote())
            else
              for (var i = 0; i < items.length; i++)
                Builder(builder: (context) {
                  final m = items[i] as Map;
                  final id = '${m['id'] ?? ''}';
                  final open = _feedbackOpenId == id && id.isNotEmpty;
                  final cats = (m['category_ratings'] as List?) ?? const [];
                  final comment = _s(m, 'comments', '');
                  return Column(mainAxisSize: MainAxisSize.min, children: [
                    GaiaBokehRow(
                      first: i == 0,
                      selected: isFocused(m),
                      initials: _guestInitials(_who(m)),
                      tone: _tone(m),
                      title: _who(m),
                      detail: comment.isNotEmpty
                          ? comment
                          : '${cats.length} question${cats.length == 1 ? '' : 's'} answered'
                              '${_fmtTime(_s(m, 'submitted_at')).isEmpty ? '' : ' \u00b7 ${_fmtTime(_s(m, 'submitted_at'))}'}',
                      value: _score(m['overall_rating']),
                      valueTail: '/5',
                      trailing: id.isEmpty
                          ? null
                          : Icon(open ? Icons.expand_less : Icons.expand_more,
                              size: 18, color: GaiaColors.text2),
                      onTap: id.isEmpty
                          ? null
                          : () => setState(
                              () => _feedbackOpenId = open ? '' : id),
                    ),
                    if (open) _expansion(m, cats),
                  ]);
                }),
            const SizedBox(height: GaiaSpacing.xxl),
            _employeeFeedbackQrSection(widget.profile, widget.employees, items),
            const SizedBox(height: GaiaSpacing.xxl),
            Text(
              'The AI question bank regenerates nightly; the questions guests '
              'see come from it.',
              style: GaiaType.italNote(),
            ),
          ],
        ),
      ),
    ]));
  }

  Widget _tappableKv({
    required String label,
    required String value,
    required VoidCallback onTap,
    Color? valueColor,
    bool first = false,
  }) =>
      GestureDetector(
        onTap: onTap,
        behavior: HitTestBehavior.opaque,
        child: MouseRegion(
          cursor: SystemMouseCursors.click,
          child: GaiaKeyValue(
            first: first,
            label: label,
            value: value,
            valueColor: valueColor,
            serifValue: true,
          ),
        ),
      );

  /// The question-by-question breakdown. Same content the Rustic card expands
  /// to — the collapsed row alone cannot show WHY a score is what it is.
  Widget _expansion(Map m, List cats) {
    final nps = m['nps'];
    return Padding(
      padding: const EdgeInsets.only(left: 58, bottom: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          if (cats.isEmpty)
            Text('No per-question ratings were recorded.', style: GaiaType.detail())
          else
            for (final c in cats)
              Builder(builder: (context) {
                final cm = c as Map;
                final r = _numOf(cm['rating']);
                final followUp = _s(cm, 'follow_up');
                final answer = _s(cm, 'follow_up_answer');
                return Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Row(children: [
                        Expanded(
                          child: Text(_s(cm, 'label', _s(cm, 'key')),
                              style: GaiaType.body()),
                        ),
                        const SizedBox(width: 10),
                        GaiaStatusChip(
                          label: '${r.toStringAsFixed(0)}/5',
                          color: r <= 2
                              ? GaiaColors.coral
                              : (r >= 4 ? GaiaColors.sage : GaiaColors.amber),
                          dense: true,
                        ),
                      ]),
                      if (_s(cm, 'question').isNotEmpty)
                        Text(_s(cm, 'question'),
                            style: GaiaType.sans(
                                size: 11.5, color: GaiaColors.text3AA)),
                      if (followUp.isNotEmpty)
                        Padding(
                          padding: const EdgeInsets.only(top: 4),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(followUp,
                                  style: GaiaType.sans(
                                      size: 11.5, color: GaiaColors.text3AA)),
                              Text(
                                  answer.isEmpty ? '\u2014 not answered' : answer,
                                  style: GaiaType.detail()),
                            ],
                          ),
                        ),
                    ],
                  ),
                );
              }),
          Wrap(spacing: 6, runSpacing: 6, children: [
            GaiaPill('Overall ${_score(m['overall_rating'])}/5 of ${cats.length}'),
            if (nps != null)
              GaiaPill('Recommend ${_numOf(nps).toStringAsFixed(0)}/10'),
            if (_s(m, 'source').isNotEmpty) GaiaPill('Via ${_s(m, 'source')}'),
          ]),
        ],
      ),
    );
  }
}

/// The narrowest one [CopperColumns] column can be — 48px of column plus the
/// chart's own fixed 8px gap.
///
/// This is geometry, not taste. That chart lays its columns out with `Expanded`
/// and a `SizedBox(width: 8)` between each pair, and gives the value + axis label
/// no `maxLines`. So a column narrower than its own labels wraps them, and a
/// wrapped label overflows the fixed 140px box and paints over the card below
/// (Flex clips nothing, so a release build shows no stripes — just the mess the
/// owner reported). Worse, once the gaps alone exceed the width — 38 columns on a
/// 292px phone — every `Expanded` gets zero width and the whole Row overflows
/// sideways: the "Sales — daily" chart at the Quarter/Year presets rendered as
/// solid nothing. 48px carries the widest label these charts actually produce (a
/// 9-glyph money figure at 10px ≈ 47px, `dd/mm` at 9.5px ≈ 26px) on one line.
const double _kColumnMinSlot = 56;

/// How many [CopperColumns] columns fit honestly across [width]. n columns cost
/// `n * 48 + (n - 1) * 8`, so the count is `(width + 8) / 56` floored.
int _columnsThatFit(double width) =>
    !width.isFinite || width <= 0 ? 0 : ((width + 8) / _kColumnMinSlot).floor();

/// A chronological series drawn as columns where they fit, and as a barcode where
/// they do not.
///
/// Above the width its columns need this is EXACTLY the [CopperColumns] the
/// desktop has always drawn — same values, same labels, same taps — so nothing
/// moves on a wide window. Below it the series is redrawn as a [CopperBarcode],
/// which is the one chart in the system that cannot overflow by construction: it
/// derives its own mark count from the width it is handed and resamples the
/// series into that many bars (365 readings render clean at 292px). The first and
/// last labels are printed under the strip so the time axis is not lost, and
/// hover/tap still report a real reading rather than an interpolated fiction.
Widget _columnSeries(
  BuildContext context,
  List<({String label, double value})> data, {
  required String Function(double) fmt,
  ValueChanged<int>? onTap,
  String Function(int index)? tooltipBuilder,
}) =>
    LayoutBuilder(
      builder: (context, box) {
        if (data.length <= _columnsThatFit(box.maxWidth)) {
          return CopperColumns(
            values: [for (final d in data) d.value],
            labels: [for (final d in data) d.label],
            valueFormatter: fmt,
            tooltipBuilder: tooltipBuilder,
            onTap: onTap,
          );
        }
        final text = Theme.of(context).textTheme;
        // 120 + 6 + the label line lands on the same ~140px the column chart
        // occupies, so swapping between the two does not jump the page.
        return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          CopperBarcode(
            values: [for (final d in data) d.value],
            height: 120,
            onTap: onTap,
            tooltipBuilder: tooltipBuilder,
          ),
          const SizedBox(height: 6),
          Row(children: [
            Expanded(
              child: Text(data.first.label,
                  style: text.labelSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            ),
            Expanded(
              child: Text('${data.length} points',
                  textAlign: TextAlign.center,
                  style: text.labelSmall,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis),
            ),
            Expanded(
              child: Text(data.last.label,
                  textAlign: TextAlign.end,
                  style: text.labelSmall,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis),
            ),
          ]),
        ]);
      },
    );

// Single-hue copper chart for (label, value) rows. Long chronological series
// render as template CopperColumns; short/ranked data reads best as an HBarRow
// list (label always beside value — nothing is colour-alone).
Widget _barChart(
  BuildContext context,
  List<({String label, double value})> data,
  String Function(double) fmt, {
  String title = 'Data point',
}) {
  if (data.isEmpty) {
    return Text('No data yet.', style: Theme.of(context).textTheme.bodySmall);
  }
  final total = data.fold<double>(0, (a, d) => a + d.value);
  // Hovering names the mark and its value; clicking opens the same figures with
  // the context a bare bar cannot carry (share of total, rank). Every chart
  // built through this helper gets both, so interactivity cannot drift between
  // one analytics panel and the next.
  String hint(int i) => '${data[i].label} · ${fmt(data[i].value)}';
  void open(int i) {
    final d = data[i];
    final share = total > 0 ? d.value / total * 100 : 0;
    final ranked = [...data]..sort((a, b) => b.value.compareTo(a.value));
    final rank = ranked.indexWhere((e) => e.label == d.label) + 1;
    _detailSheet(
      context,
      eyebrow: title,
      title: d.label,
      children: [
        _kv('Value', fmt(d.value)),
        _kv('Share of total', total > 0 ? '${share.toStringAsFixed(1)}%' : '—'),
        _kv('Rank', rank > 0 ? '$rank of ${data.length}' : '—'),
        _kv('Total across all', fmt(total)),
      ],
    );
  }

  if (data.length >= 10) {
    return _columnSeries(context, data, fmt: fmt, tooltipBuilder: hint, onTap: open);
  }
  final maxV = data.map((d) => d.value).fold<double>(0, (a, b) => b > a ? b : a);
  return Column(children: [
    for (var i = 0; i < data.length; i++)
      HBarRow(
        label: data[i].label,
        fraction: maxV > 0 ? (data[i].value / maxV).clamp(0.0, 1.0) : 0,
        value: fmt(data[i].value),
        tooltip: hint(i),
        onTap: () => open(i),
      ),
  ]);
}

// --- STRATA (Analytics, History) ---------------------------------------------
//
// The Gaia halves of the two chart helpers above. Both are opt-in at the CALL
// SITE and both fall straight back to `_barChart` under Rustic Fork, so the
// shipped look is byte-identical and only Analytics and History — the two
// sections the design allocates STRATA to — pick it up.
//
// WHY THERE IS NO AUTOMATIC SWITCH. "Thickness is share" is an arithmetic
// claim, and it is only TRUE when the series is a partition: revenue by month
// adds up to the window, covers by table add up to the covers. Average per
// cover by staff does not add up to anything — three waiters averaging ₹900
// are not ₹2,700 of something — so drawing them as shares of a bar would
// invent a proportion out of nothing. Only the call site knows which it has,
// so only the call site may ask. `_strataArea` is safe for any series (it
// draws values on one linear scale, no proportion claimed); `_strataShare` is
// the one that makes the claim.

/// A chronological series as the stacked area (`.strata-chart`), or the
/// existing bar chart when Gaia is off. No proportion is claimed: each point
/// is drawn at its value on one shared scale, with the peak labelled.
Widget _strataArea(
  BuildContext context,
  List<({String label, double value})> data,
  String Function(double) fmt, {
  String label = 'Revenue',
}) {
  if (!Gaia.of(context)) return _barChart(context, data, fmt);
  if (data.isEmpty) {
    return Text('No data yet.', style: Theme.of(context).textTheme.bodySmall);
  }
  return GaiaStrataChart(
    series: [
      GaiaStrataSeries(label: label, values: [for (final d in data) d.value]),
    ],
    format: fmt,
    axisLabels: [data.first.label, data.last.label],
    showKey: false,
  );
}

/// A PARTITION as strata bands, thickness = share (`.stratum`).
///
/// [shown] is what the screen lists; [total] is the true whole. They differ
/// whenever a chart is topped at eight rows, and that gap is exactly where a
/// share chart usually starts lying — eight of forty tables drawn as eight
/// slices of a pie reports each table at roughly five times its real share. So
/// the remainder is drawn as its own band rather than dropped.
Widget _strataShare(
  BuildContext context,
  List<({String label, double value})> shown,
  String Function(double) fmt, {
  required double total,
  String remainderLabel = 'Everything else',
  String? caption,
}) {
  final listed = shown.fold<double>(0, (a, d) => a + d.value);
  final rest = total - listed;
  return GaiaStrataList(
    mode: GaiaStrataMode.share,
    extent: GaiaStrataList.extentFor(shown.length + 1, headroom: 260),
    caption: caption,
    strata: [
      for (final d in shown)
        GaiaStratum(label: d.label, value: d.value, display: fmt(d.value)),
      // Only when there IS a remainder, and only when it is positive — a
      // negative remainder means `total` and `shown` disagree, and inventing a
      // band for that would hide a real inconsistency instead of showing it.
      if (rest > 0.5)
        GaiaStratum(
          label: remainderLabel,
          value: rest,
          display: fmt(rest),
          caption: 'The rows not listed above, kept in so every percentage on'
              ' this strata is a share of the real total.',
        ),
    ],
  );
}

Widget _chartCard(BuildContext context, String title, Widget child, {VoidCallback? onDownload}) => ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        SectionHeader(
          title: title,
          padding: const EdgeInsets.only(bottom: 12),
          trailing: onDownload == null ? null : _dlButton(onDownload),
        ),
        child,
      ]),
    );

Color _kpiColor(String s) {
  switch (s) {
    case 'blue': return AppColors.info;
    case 'green': return AppColors.success;
    case 'amber': return AppColors.warning;
    case 'red': return AppColors.danger;
    default: return AppColors.textSecondary;
  }
}

String _kpiStatusLabel(String s) {
  switch (s) {
    case 'blue': return 'EXCELLENT';
    case 'green': return 'ON TARGET';
    case 'amber': return 'WATCH';
    case 'red': return 'ACTION';
    default: return 'NO DATA';
  }
}

// --- KPI drill-down (tap a KPI tile → detail sheet with a chart) --------------

// One-line plain-English meaning per KPI key (shown at the top of the sheet).
const Map<String, String> _kpiMeaning = {
  'profit_margin': 'Share of revenue left after expenses.',
  'revpash': 'Revenue per available seat-hour — how hard seats work.',
  'discount_utilization': 'Share of bills that carried a discount.',
  'offer_redemption': 'How often live offers/coupons are redeemed.',
  'menu_bad_share': 'Share of dishes flagged BAD (low popularity & value).',
  'forecast_mape': 'Demand-forecast error — lower is a sharper forecast.',
  'labour_cost': 'Staff cost as a share of revenue.',
  'happiness_efficiency': 'Guest happiness weighed against staff effort.',
  'avg_rating': 'Average guest rating from feedback.',
  'nps': 'Net promoter score — promoters minus detractors.',
  'complaint_rate': 'Share of feedback that was a complaint.',
  'churn_rate': 'Share of regulars who have gone quiet.',
  'wait_time': 'Average guest wait before being seated.',
  'table_turnaround': 'Average time a table is occupied per visit.',
  'processing_time': 'Average kitchen/order processing time.',
  'booking_fill': 'How full reservations run against capacity.',
  'booking_no_show': 'Share of reservations that never showed.',
  'valet_retrieval': 'Average valet car-retrieval time.',
  'supplier_on_time': 'Share of supplier deliveries that arrived on time.',
  'supplier_score': 'Blended supplier quality + reliability score.',
  'low_stock': 'Ingredients at or below their reorder point.',
  'food_cost_pct': 'Ingredient cost as a share of revenue.',
  'food_cost_variance': 'Gap between expected and actual food cost.',
  'campaign_roi': 'Return on marketing-campaign spend.',
};

enum _KpiChartKind { pie, bar, columns, none }

// A tap-through detail sheet for a single KPI or stat tile: header (label + big
// value + status), the plain-English explainer, then a drill-down chart (either
// an explicit [series] from the caller or the KPI→chart registry), a
// legend/value list, and an optional "view full records" link.
class _KpiDrilldownSheet extends StatelessWidget {
  final Map kpi;
  final Map adv;
  final VoidCallback? onViewRecords; // switches the analytics view to the KPI's home slice
  final String? viewRecordsLabel;

  // --- generic stat-tile mode (plain numeric cards) --------------------------
  // Explainer row from GET /analytics/metric-explainers: {title, what, how, tip}.
  // Null (older backend / unmapped tile) simply renders no explainer.
  final Map? explainer;

  // Explicit breakdown rows. Non-null takes precedence over the KPI registry
  // and is rendered in the order given (time-series must stay chronological),
  // so callers sort first. Empty = no chart, explainer only — never a dead tap.
  final List<({String label, double value})>? series;
  final _KpiChartKind seriesKind;

  // Formats every rendered value (money / duration / count). Defaults to a
  // plain number.
  final String Function(double)? valueFormat;

  // One extra line of context under the number ("36 tickets timed · median …").
  final String? note;

  // Stat tiles have no health status, so their chip is suppressed.
  final bool showStatus;

  const _KpiDrilldownSheet({
    required this.kpi,
    required this.adv,
    this.onViewRecords,
    this.viewRecordsLabel,
    this.explainer,
    this.series,
    this.seriesKind = _KpiChartKind.bar,
    this.valueFormat,
    this.note,
    this.showStatus = true,
  });

  static double _n(dynamic v) => (v is num) ? v.toDouble() : (double.tryParse('${v ?? ''}') ?? 0);
  static List _list(dynamic v) => (v is List) ? v : const [];
  static String _fmtNum(double v) => v == v.roundToDouble() ? v.toStringAsFixed(0) : v.toStringAsFixed(1);

  // Resolve the KPI key to a chart kind + the (label, value) rows that feed it.
  (_KpiChartKind, List<({String label, double value})>) _data() {
    final key = _s(kpi, 'key');
    List<({String label, double value})> pos(Iterable<({String label, double value})> it) =>
        it.where((e) => e.value > 0).toList();
    switch (key) {
      case 'profit_margin':
        {
          final profit = (adv['profit'] as Map?) ?? {};
          final p = _n(profit['revenue']) - _n(profit['expenses']);
          return (_KpiChartKind.pie, pos([
            (label: 'Profit', value: p),
            (label: 'Expenses', value: _n(profit['expenses'])),
          ]));
        }
      case 'discount_utilization':
      case 'offer_redemption':
        {
          final offers = _list(adv['offers']);
          final o = pos(offers.map((e) => (label: _s(e as Map, 'code'), value: _n(e['used']))));
          if (o.isNotEmpty) return (_KpiChartKind.pie, o);
          final d = (adv['discounts'] as Map?) ?? {};
          return (_KpiChartKind.bar, pos([
            (label: 'Discount bills', value: _n(d['discount_bills'])),
            (label: 'All bills', value: _n(d['total_bills'])),
            (label: 'Redemptions', value: _n(d['redemptions'])),
          ]));
        }
      case 'avg_rating':
      case 'nps':
        return (_KpiChartKind.bar, pos(_list(adv['staff']).map((e) => (label: _s(e as Map, 'name'), value: _n(e['avg_rating'])))));
      case 'complaint_rate':
        return (_KpiChartKind.bar, pos(_list(adv['staff']).map((e) => (label: _s(e as Map, 'name'), value: _n(e['complaint_pct'])))));
      case 'churn_rate':
        {
          final atRisk = _list((adv['churn'] as Map?)?['at_risk']);
          return (_KpiChartKind.bar, pos(atRisk.map((e) => (label: _s(e as Map, 'customer'), value: _n(e['spend'])))));
        }
      case 'campaign_roi':
        // ROI can be negative, so keep every campaign (the bar builder handles it).
        return (_KpiChartKind.bar, _list(adv['campaigns']).map((e) => (label: _s(e as Map, 'name'), value: _n(e['roi_pct']))).toList());
      case 'menu_bad_share':
        {
          final counts = <String, int>{'STAR': 0, 'GREAT': 0, 'MID': 0, 'BAD': 0};
          for (final m in _list(adv['menu_classes'])) {
            final c = _s(m as Map, 'class', 'MID');
            counts[c] = (counts[c] ?? 0) + 1;
          }
          return (_KpiChartKind.pie, pos(counts.entries.map((e) => (label: e.key, value: e.value.toDouble()))));
        }
      case 'low_stock':
        return (_KpiChartKind.bar, pos(_list(adv['stock_alerts']).map((e) => (label: _s(e as Map, 'name'), value: _n(e['qty'])))));
      case 'table_turnaround':
      case 'revpash':
        {
          final byTable = _list((adv['tat'] as Map?)?['by_table']);
          return (_KpiChartKind.bar, pos(byTable.map((e) => (label: _s(e as Map, 'table_name'), value: _n(e['avg_min'])))));
        }
      case 'forecast_mape':
        return (_KpiChartKind.bar, pos(_list(adv['demand_forecast']).map((e) => (label: _s(e as Map, 'name'), value: _n(e['forecast_next_week'])))));
      case 'food_cost_pct':
      case 'food_cost_variance':
        return (_KpiChartKind.pie, pos(_list(adv['suppliers']).map((e) => (label: _s(e as Map, 'vendor'), value: _n(e['spend'])))));
      default:
        return (_KpiChartKind.none, const []);
    }
  }

  // Composition breakdown (formerly a multi-hue pie): a copper donut carries
  // the leading share, then an HBarRow list on the sequential copper ramp —
  // every share is labelled beside its value, nothing is colour-alone.
  Widget _pie(BuildContext context, List<({String label, double value})> data) {
    final text = Theme.of(context).textTheme;
    final fmt = valueFormat ?? _fmtNum;
    final total = data.fold<double>(0, (s, e) => s + e.value);
    final top = data.first;
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      if (total > 0) ...[
        Row(children: [
          DonutGauge(fraction: top.value / total, size: 64),
          const SizedBox(width: AppSpacing.lg),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(top.label, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
              const SizedBox(height: 2),
              Text('${(top.value / total * 100).round()}% of the total', style: text.bodySmall),
            ]),
          ),
        ]),
        const SizedBox(height: AppSpacing.md),
      ],
      for (var i = 0; i < data.length; i++)
        HBarRow(
          label: data[i].label,
          fraction: total > 0 ? (data[i].value / total).clamp(0.0, 1.0) : 0,
          value: fmt(data[i].value),
          sub: total > 0 ? '${(data[i].value / total * 100).round()}%' : null,
          color: AppColors.copperRamp[i % AppColors.copperRamp.length],
        ),
    ]);
  }

  // Ranked magnitudes (formerly a vertical bar chart) as an HBarRow list —
  // single-hue copper; negative values keep their label + signed value with
  // an empty bar, so nothing is hidden.
  Widget _bar(BuildContext context, List<({String label, double value})> data) {
    final fmt = valueFormat ?? _fmtNum;
    final maxV = data.map((e) => e.value).fold<double>(0, (a, b) => b > a ? b : a);
    return Column(children: [
      for (final d in data)
        HBarRow(
          label: d.label,
          fraction: maxV > 0 ? (d.value / maxV).clamp(0.0, 1.0) : 0,
          value: fmt(d.value),
        ),
    ]);
  }

  // Chronological series (revenue by day, APC by month) — vertical columns keep
  // the time axis readable where a ranked bar list would scramble it.
  Widget _columns(BuildContext context, List<({String label, double value})> data) {
    final fmt = valueFormat ?? _fmtNum;
    // Through the shared chooser: this sheet is the NARROWEST surface a column
    // chart is drawn on (a bottom sheet's own 18px padding takes it to 324px on a
    // 360px phone), so it is the last place that can afford to assume 14 columns
    // fit.
    return _columnSeries(
      context,
      data,
      fmt: fmt,
      tooltipBuilder: (i) => '${data[i].label} · ${fmt(data[i].value)}',
      // Already inside the KPI's own detail view, so a tap surfaces the reading
      // rather than opening a second sheet on top of this one.
      onTap: (i) => ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('${data[i].label}: ${fmt(data[i].value)}')),
      ),
    );
  }

  // The plain-English explainer block: what the number is, how it is computed,
  // and the backend's one-line tip. Falls back to the KPI meaning registry.
  Widget? _explainerBlock(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final what = explainer == null ? '' : _s(explainer!, 'what', '');
    final how = explainer == null ? '' : _s(explainer!, 'how', '');
    final tip = explainer == null ? '' : _s(explainer!, 'tip', '');
    final fallback = _kpiMeaning[_s(kpi, 'key')];
    if (what.isEmpty && how.isEmpty && tip.isEmpty) {
      return fallback == null ? null : Text(fallback, style: text.bodySmall);
    }
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      if (what.isNotEmpty)
        Text(what, style: text.bodyMedium!.copyWith(color: AppColors.textPrimary)),
      if (how.isNotEmpty) ...[
        const SizedBox(height: 6),
        Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Icon(Icons.functions, size: 13, color: AppColors.textTertiary),
          const SizedBox(width: 7),
          Expanded(child: Text(how, style: text.bodySmall)),
        ]),
      ],
      if (tip.isNotEmpty) ...[
        const SizedBox(height: 6),
        Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Icon(Icons.lightbulb_outline, size: 13, color: AppColors.copper),
          const SizedBox(width: 7),
          Expanded(
            child: Text(tip, style: text.bodySmall!.copyWith(color: AppColors.copperHi)),
          ),
        ]),
      ],
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final color = _kpiColor(_s(kpi, 'status', 'grey'));
    final v = kpi['value'];
    final unit = _s(kpi, 'unit', '');
    final valueText = v == null ? '—' : '$v$unit';
    final meaning = _explainerBlock(context);
    // An explicit series wins over the registry and keeps the caller's order
    // (chronological for columns); registry rows are ranked biggest-first.
    final (kind, dataRaw) = series != null ? (seriesKind, series!) : _data();
    final data = series != null ? dataRaw : ([...dataRaw]..sort((a, b) => b.value.compareTo(a.value)));
    final shown = data.take(kind == _KpiChartKind.columns ? 14 : 8).toList();
    // An all-zero series has no shape to draw (and would divide by its own zero
    // maximum), so it falls through to the explainer-only body.
    final hasChart = kind != _KpiChartKind.none && shown.any((e) => e.value > 0);

    return SafeArea(
      child: ConstrainedBox(
        constraints: BoxConstraints(maxHeight: MediaQuery.of(context).size.height * 0.82),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Container(
            width: 40,
            height: 4,
            margin: const EdgeInsets.symmetric(vertical: 10),
            decoration: BoxDecoration(color: AppColors.textSecondary.withValues(alpha: 0.4), borderRadius: BorderRadius.circular(2)),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(18, 0, 10, 12),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Expanded(
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text(_s(kpi, 'label').toUpperCase(), style: text.labelSmall),
                  const SizedBox(height: 6),
                  Text(valueText, style: text.displaySmall),
                  if (note != null) ...[
                    const SizedBox(height: 6),
                    Text(note!, style: text.bodySmall!.copyWith(fontSize: 11.5)),
                  ],
                  if (showStatus) ...[
                    const SizedBox(height: 6),
                    StatusChip(label: _kpiStatusLabel(_s(kpi, 'status', 'grey')), color: color, dense: true),
                  ],
                ]),
              ),
              ForkIconButton(icon: Icons.close, tooltip: 'Close', onPressed: () => Navigator.pop(context)),
            ]),
          ),
          Container(height: 1, color: AppColors.divider),
          Flexible(
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(18),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                if (meaning != null) ...[
                  meaning,
                  const SizedBox(height: AppSpacing.lg),
                ],
                if (hasChart) ...[
                  const SectionHeader(title: 'Breakdown', padding: EdgeInsets.only(bottom: 10)),
                  kind == _KpiChartKind.pie
                      ? _pie(context, shown)
                      : kind == _KpiChartKind.columns
                          ? _columns(context, shown)
                          : _bar(context, shown),
                ] else ...[
                  Text('No detailed breakdown yet for this metric.', style: text.bodySmall),
                ],
                if (onViewRecords != null) ...[
                  const SizedBox(height: AppSpacing.md),
                  Align(
                    alignment: Alignment.centerLeft,
                    child: ForkButton.ghost(
                      label: viewRecordsLabel ?? 'View full records',
                      icon: Icons.list_alt,
                      dense: true,
                      onPressed: onViewRecords,
                    ),
                  ),
                ],
              ]),
            ),
          ),
        ]),
      ),
    );
  }
}

// --- Analytics view filter ("show only this slice") --------------------------
