// --- Accounting & reporting --------------------------------------------------
Widget accountingModule(RestClient rest, Profile p) => _AccountingView(rest: rest, profile: p);

class _AccountingView extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  const _AccountingView({required this.rest, required this.profile});
  @override
  State<_AccountingView> createState() => _AccountingViewState();
}

class _AccountingViewState extends State<_AccountingView> with CachePrimedScreen {
  // The shared reporting window (see services/date_range.dart). Replaces a
  // private Day/Week/Month/Quarter/Half-year/Year tab row that could name six
  // spans and no CALENDAR RANGE at all — "1-15 August", the thing an owner
  // reconciling a fortnight actually asks for, was unaskable here.
  //
  // Restored from this session's memory so switching to Menu and back does not
  // silently reset the period the owner was reasoning about.
  DateRange _range = DateRangeMemory.of('accounting');
  bool _loading = true;
  bool _hasData = false;
  String? _error;
  Map<String, dynamic> _sales = {};
  Map<String, dynamic> _gst = {};
  Map<String, dynamic> _pnl = {};
  List _expenses = [];
  String _payrollMonth = RestaurantTime.thisMonthIso();
  Map<String, dynamic> _payroll = {};
  Map<String, dynamic> _discounts = {};
  // Scheduled report delivery. Not scoped to the period tabs above: a schedule
  // is a standing instruction, not a figure cut over the selected window.
  List _schedules = [];
  List _deliveries = [];

  // Settled-bill browser. The list is paged by _ClosedBillsList itself; this
  // state only holds what the user filters it by. The term is applied on a
  // short debounce so typing doesn't fire a request per keystroke.
  final TextEditingController _billSearch = TextEditingController();
  Timer? _billDebounce;
  String _billTerm = '';
  String? _billMethod;

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: _fetch,
      apply: (d) { _apply(d); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  @override
  void dispose() {
    _billDebounce?.cancel();
    _billSearch.dispose();
    _scroll.dispose();
    super.dispose();
  }

  // The 'Settled bills' header and the page's scroll position, so picking dates
  // from THAT header's chip lands the owner back on the bills after the reload
  // instead of at the top of the page (see revealAfterPaint).
  final GlobalKey _settledBillsKey = GlobalKey(debugLabel: 'accounting-settled-bills');
  final ScrollController _scroll = ScrollController();

  // Adopt a window the owner picked, remember it for the session, refetch.
  // ONE window for the whole page whichever chip set it: the top control and the
  // Settled bills header both land here. `revealBills` only decides where the
  // page is scrolled once the new figures are up.
  Future<void> _setRange(DateRange next, {bool revealBills = false}) async {
    // Read BEFORE the reload: the skeleton detaches the list from the controller.
    final offset = _scroll.hasClients ? _scroll.offset : null;
    setState(() => _range = next);
    DateRangeMemory.remember('accounting', next);
    await _load();
    if (revealBills && mounted) revealAfterPaint(_settledBillsKey, controller: _scroll, offset: offset);
  }

  /// Side-effect-free GET composition over the CURRENT window/month — replayable
  /// against the persisted cache at boot and the network path of every [_load].
  Future<List<Map<String, dynamic>>> _fetch() {
    final q = _range.reportQuery;
    return Future.wait([
      widget.rest.getMap('/reports/sales?$q'),
      widget.rest.getMap('/reports/gst?$q'),
      widget.rest.getMap('/reports/pnl?$q'),
      widget.rest.getMap('/expenses?$q'),
      widget.rest.getMap('/payroll?month=$_payrollMonth').catchError((_) => <String, dynamic>{}),
      widget.rest.getMap('/reports/discounts?$q').catchError((_) => <String, dynamic>{}),
      widget.rest.getMap('/reports/schedules').catchError((_) => <String, dynamic>{}),
      widget.rest.getMap('/reports/deliveries?limit=20').catchError((_) => <String, dynamic>{}),
    ]);
  }

  void _apply(List<Map<String, dynamic>> res) {
    _sales = res[0];
    _gst = res[1];
    _pnl = res[2];
    _expenses = (res[3]['expenses'] as List?) ?? [];
    _payroll = res[4];
    _discounts = res[5];
    _schedules = (res[6]['schedules'] as List?) ?? [];
    _deliveries = (res[7]['deliveries'] as List?) ?? [];
    _hasData = true;
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) {
      setState(() {
        _loading = true;
        _error = null;
      });
    }
    try {
      final res = await _fetch();
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _apply(res);
        _loading = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      // Only a SILENT refresh keeps the figures up behind the offline pill: a
      // loud load here means the window or payroll month just changed, and old
      // figures under a new window label would be a silent tally mismatch —
      // the error screen is the honest outcome for that.
      if (silent && _hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() {
        _error = '$e';
        _loading = false;
      });
    }
  }

  double _n(dynamic v) => (v is num) ? v.toDouble() : (double.tryParse('${v ?? ''}') ?? 0);
  String _ddmm(String iso) {
    final pcs = iso.split('-');
    return pcs.length == 3 ? '${pcs[2]}/${pcs[1]}' : iso;
  }

  void _shiftPayrollMonth(int delta) {
    final p = _payrollMonth.split('-');
    final d = DateTime(int.parse(p[0]), int.parse(p[1]) + delta, 1);
    setState(() => _payrollMonth = '${d.year}-${d.month.toString().padLeft(2, '0')}');
    _load();
  }

  Future<void> _editPayrollProfile(Map row) async {
    final messenger = ScaffoldMessenger.of(context);
    final prof = (row['profile'] as Map?) ?? {};
    String payType = '${prof['pay_type'] ?? 'monthly'}';
    final base = TextEditingController(text: '${prof['base_salary'] ?? ''}');
    final rate = TextEditingController(text: '${prof['hourly_rate'] ?? ''}');
    final allow = TextEditingController(text: '${prof['allowances'] ?? ''}');
    final deduct = TextEditingController(text: '${prof['deductions'] ?? ''}');
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setDlg) => AlertDialog(
        title: Text('Salary — ${_s(row, 'name')}'),
        content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          DropdownButtonFormField<String>(
            initialValue: payType,
            items: const [
              DropdownMenuItem(value: 'monthly', child: Text('Monthly salary')),
              DropdownMenuItem(value: 'hourly', child: Text('Hourly (from attendance)')),
            ],
            onChanged: (v) => setDlg(() => payType = v ?? 'monthly'),
            decoration: const InputDecoration(labelText: 'Pay type', border: OutlineInputBorder()),
          ),
          const SizedBox(height: 8),
          if (payType == 'monthly')
            TextField(controller: base, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Base salary / month', border: OutlineInputBorder()))
          else
            TextField(controller: rate, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Rate / hour', border: OutlineInputBorder())),
          const SizedBox(height: 8),
          TextField(controller: allow, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Allowances / month', border: OutlineInputBorder())),
          const SizedBox(height: 8),
          TextField(controller: deduct, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Deductions / month', border: OutlineInputBorder())),
        ])),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Save')),
        ],
      )),
    );
    if (ok != true) return;
    try {
      await widget.rest.put('/payroll/profile', {
        'emp_id': row['emp_id'],
        'pay_type': payType,
        'base_salary': double.tryParse(base.text.trim()) ?? 0,
        'hourly_rate': double.tryParse(rate.text.trim()) ?? 0,
        'allowances': double.tryParse(allow.text.trim()) ?? 0,
        'deductions': double.tryParse(deduct.text.trim()) ?? 0,
      });
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _payEmployee(Map row) async {
    final messenger = ScaffoldMessenger.of(context);
    final amount = row['computed_pay'];
    if (amount == null) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Record salary payment'),
        content: Text('Pay ${_money(amount)} to ${_s(row, 'name')} for $_payrollMonth?\n\nThis also books a "Payroll" expense.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Pay')),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await widget.rest.post('/payroll/pay', {'emp_id': row['emp_id'], 'period': _payrollMonth, 'amount': amount});
      messenger.showSnackBar(const SnackBar(content: Text('Salary recorded + Payroll expense booked.')));
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _addExpense() async {
    final messenger = ScaffoldMessenger.of(context);
    final cat = TextEditingController(text: 'General');
    final amount = TextEditingController();
    final vendor = TextEditingController();
    final note = TextEditingController();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Add expense'),
        content: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(controller: cat, decoration: const InputDecoration(labelText: 'Category', border: OutlineInputBorder())),
            const SizedBox(height: 8),
            TextField(controller: amount, autofocus: true, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Amount', border: OutlineInputBorder())),
            const SizedBox(height: 8),
            TextField(controller: vendor, decoration: const InputDecoration(labelText: 'Vendor (optional)', border: OutlineInputBorder())),
            const SizedBox(height: 8),
            TextField(controller: note, decoration: const InputDecoration(labelText: 'Note (optional)', border: OutlineInputBorder())),
          ]),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Add')),
        ],
      ),
    );
    if (ok != true) return;
    final amt = double.tryParse(amount.text.trim()) ?? 0;
    if (amt <= 0) {
      messenger.showSnackBar(const SnackBar(content: Text('Enter a valid amount.')));
      return;
    }
    try {
      await widget.rest.post('/expenses', {
        'amount': amt,
        'category': cat.text.trim().isEmpty ? 'General' : cat.text.trim(),
        if (vendor.text.trim().isNotEmpty) 'vendor': vendor.text.trim(),
        if (note.text.trim().isNotEmpty) 'note': note.text.trim(),
      });
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _deleteExpense(String id) async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await widget.rest.delete('/expenses/$id');
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _exportPdf() async {
    ScaffoldMessenger.of(context)
        .showSnackBar(const SnackBar(content: Text('Preparing the PDF…')));
    // The SELECTED window, not a default: an export that quietly disagrees with
    // the figures on screen is worse than no export — it is the copy that gets
    // filed, and nothing on the page would say the two are different periods.
    final r = _range;
    final doc = pw.Document();
    String money(dynamic v) {
      final n = v is num ? v : num.tryParse('${v ?? ''}');
      return n == null ? '-' : 'Rs ${n.toStringAsFixed(2)}';
    }

    pw.Widget kv(String k, dynamic v, {bool bold = false}) => pw.Padding(
          padding: const pw.EdgeInsets.symmetric(vertical: 2),
          child: pw.Row(mainAxisAlignment: pw.MainAxisAlignment.spaceBetween, children: [
            pw.Text(k, style: pw.TextStyle(fontSize: 11, fontWeight: bold ? pw.FontWeight.bold : pw.FontWeight.normal)),
            pw.Text(money(v), style: pw.TextStyle(fontSize: 11, fontWeight: bold ? pw.FontWeight.bold : pw.FontWeight.normal)),
          ]),
        );

    final byRate = (_gst['by_rate'] as List?) ?? [];
    doc.addPage(pw.MultiPage(build: (ctx) => [
          pw.Center(child: pw.Text(widget.profile.restaurantName, style: pw.TextStyle(fontSize: 18, fontWeight: pw.FontWeight.bold))),
          pw.Center(child: pw.Text('Financial report · ${r.from} to ${r.to}', style: const pw.TextStyle(fontSize: 10))),
          pw.SizedBox(height: 12),
          pw.Text('Profit & Loss', style: pw.TextStyle(fontSize: 14, fontWeight: pw.FontWeight.bold)),
          pw.Divider(),
          kv('Gross sales', _pnl['gross_sales']),
          kv('Refunds', _pnl['refunds']),
          kv('Tax collected (pass-through)', _pnl['tax_collected']),
          kv('Revenue ex-tax (after refunds)', _pnl['net_revenue']),
          kv('Total expenses', _pnl['total_expenses']),
          kv('Net profit', _pnl['net_profit'], bold: true),
          pw.SizedBox(height: 16),
          pw.Text('GST / Tax collected', style: pw.TextStyle(fontSize: 14, fontWeight: pw.FontWeight.bold)),
          pw.Divider(),
          ...byRate.map((t) {
            final m = t as Map;
            return kv('${m['name']} (${m['percentage']}%)  on ${money(m['taxable'])}', m['tax']);
          }),
          kv('Total tax', _gst['total_tax'], bold: true),
          pw.SizedBox(height: 16),
          pw.Text('Sales', style: pw.TextStyle(fontSize: 14, fontWeight: pw.FontWeight.bold)),
          pw.Divider(),
          // Gross and Net in the client's words. The old "Net sales (after
          // refunds)" line was Gross less refunds, tax and all — it is still
          // here, named for what it is. Which key each line reads is decided
          // (and tested) in models/gross_net.dart, not here.
          for (final line in accountingSalesPdfLines(_sales)) kv(line.label, line.value, bold: line.bold),
        ]));
    await Printing.layoutPdf(onLayout: (PdfPageFormat format) => doc.save());
  }

  // --- Drill-downs -----------------------------------------------------------
  // Every headline figure on this page opens the arithmetic behind it. All of it
  // is assembled from the four reports already loaded by [_load], so a
  // drill-down costs no round-trip.
  //
  // One house rule runs through all of them: the SERVICE CHARGE IS NOT TAX. The
  // server keeps `total_service_charge` out of `total_tax` and out of `by_rate`,
  // and every sheet below keeps them on separate lines with separate wording —
  // collapsing the two once booked ₹31,733.92 of owner income as GST.

  Widget _sheetHead(String label) => Padding(
        padding: const EdgeInsets.only(top: 14, bottom: 2),
        child: Text(label.toUpperCase(), style: Theme.of(context).textTheme.labelSmall),
      );

  Widget _sheetNote(String body) => Padding(
        padding: const EdgeInsets.only(top: 6),
        child: Text(body,
            style: Theme.of(context).textTheme.bodySmall!.copyWith(color: AppColors.textTertiary, height: 1.35)),
      );

  String _billsWord(int n) => '$n bill${n == 1 ? '' : 's'}';

  /// "1–15 Aug · 15 days" — every sheet says which window it is describing,
  /// because the control above it can be changed while a sheet is open.
  String get _windowLabel =>
      '${_range.label()} · ${_range.days} day${_range.days == 1 ? '' : 's'}';

  Future<void> _netSalesSheet() {
    final gross = _n(_sales['total_sales']);
    final refunds = _n(_sales['total_refund']);
    final bills = _n(_sales['bill_count']).round();
    final methods = ((_sales['by_method'] as List?) ?? const []).whereType<Map>().toList();
    final words = readAccountingSales(_sales);
    return _detailSheet(
      context,
      eyebrow: '${words.headlineLabel} · $_windowLabel',
      title: _money(words.headlineValue),
      children: [
        _detailRow(context, 'Gross sales', _money(gross), trailing: _billsWord(bills)),
        _detailRow(context, 'Refunds', refunds > 0 ? '− ${_money(refunds)}' : _money(0)),
        _detailRow(context, 'Gross after refunds', _money(_sales['net_sales'])),
        _detailRow(context, 'Average bill', bills > 0 ? _money(gross / bills) : '—'),
        _sheetHead('What sits inside gross sales'),
        _detailRow(context, 'Tax collected', _money(_sales['total_tax'])),
        _detailRow(context, 'Service charge', _money(_sales['total_service_charge'])),
        if (billRoundOff(words.roundOff) != null)
          _detailRow(context, 'Round off', billRoundOffMoney(billRoundOff(words.roundOff)!)),
        if (words.netSales != null) _detailRow(context, 'Net sales', _money(words.netSales)),
        _sheetNote('Gross sales is what guests actually paid, so it still carries both. The tax is '
            'pass-through — it is owed onward to the government. The service charge is NOT tax: the '
            'restaurant keeps it, and the reports count it as income.'),
        _sheetNote('Net sales is the item total less discounts — before service charge, tax and '
            'round off, and before refunds — the figure the Sales Summary calls Net.'),
        if (methods.isNotEmpty) ...[
          _sheetHead('By payment method'),
          for (final m in methods)
            _detailRow(context, PaymentModes.reportName(m), _money(m['sales']),
                trailing: _billsWord(_int(m['bills']) ?? 0)),
        ],
      ],
    );
  }

  Future<void> _taxSheet() {
    final byRate = ((_gst['by_rate'] as List?) ?? const []).whereType<Map>().toList();
    final totalTax = _n(_gst['total_tax']);
    final service = _n(_gst['total_service_charge']);
    // Only the sales report carries the refunded share. Both reports are cut
    // over the same settled bills in the same window, so the two figures are
    // describing the same money.
    final refundedTax = _n(_sales['total_refunded_tax']);
    return _detailSheet(
      context,
      eyebrow: 'Tax collected · $_windowLabel',
      title: _money(totalTax),
      children: [
        if (byRate.isEmpty)
          _sheetNote('No tax was charged on any settled bill in this window.')
        else
          for (final t in byRate)
            _detailRow(
              context,
              '${_s(t, 'name', 'Tax')} · ${_numOf(t['percentage'])}%',
              _money(t['tax']),
              trailing: 'on ${_money(t['taxable'])}',
            ),
        _detailRow(context, 'Total tax', _money(totalTax)),
        if (refundedTax > 0) ...[
          _detailRow(context, 'Inside refunded bills', '− ${_money(refundedTax)}'),
          _detailRow(context, 'Tax actually kept', _money(totalTax - refundedTax)),
          _sheetNote('A refund reverses a tax-inclusive amount, so that share of the tax was never '
              'the restaurant\'s to remit.'),
        ],
        _sheetHead('Not tax — shown separately'),
        _detailRow(context, 'Service charge', _money(service)),
        _sheetNote('The service charge is the restaurant\'s own income, not a levy collected for '
            'anyone else. It is deliberately kept out of every figure above and out of the GST '
            'breakdown on the page — booking it as tax would overstate what is owed and understate '
            'what was earned.'),
        _sheetHead('Turnover'),
        _detailRow(context, 'Taxable turnover (ex-tax)', _money(_gst['total_taxable'])),
      ],
    );
  }

  Future<void> _expensesSheet() {
    final byCat = ((_pnl['expenses_by_category'] as List?) ?? const []).whereType<Map>().toList();
    final total = _n(_pnl['total_expenses']);
    return _detailSheet(
      context,
      eyebrow: 'Expenses · $_windowLabel',
      title: _money(total),
      children: [
        if (byCat.isEmpty)
          _sheetNote('Nothing was booked as an expense in this window.')
        else
          for (final c in byCat)
            _detailRow(
              context,
              _s(c, 'category', 'General'),
              _money(c['amount']),
              trailing: total > 0 ? '${(_n(c['amount']) / total * 100).toStringAsFixed(1)}%' : null,
            ),
        _detailRow(context, 'Total expenses', _money(total),
            trailing: '${_expenses.length} entr${_expenses.length == 1 ? 'y' : 'ies'}'),
        _sheetNote('Salaries paid from the payroll section below are booked here automatically, '
            'under "Payroll".'),
      ],
    );
  }

  Future<void> _netProfitSheet() {
    final net = _n(_pnl['net_profit']);
    return _detailSheet(
      context,
      eyebrow: 'Net profit · $_windowLabel',
      title: _money(net),
      children: [
        _detailRow(context, 'Gross sales', _money(_pnl['gross_sales'])),
        _detailRow(context, 'Refunds', '− ${_money(_pnl['refunds'])}'),
        _detailRow(context, 'Tax kept out', '− ${_money(_pnl['tax_collected'])}'),
        _detailRow(context, 'Revenue ex-tax (after refunds)', _money(_pnl['net_revenue'])),
        _detailRow(context, 'Expenses', '− ${_money(_pnl['total_expenses'])}'),
        _detailRow(context, 'Net profit', _money(net)),
        _sheetHead('Read this carefully'),
        _detailRow(context, 'Service charge earned', _money(_pnl['service_charge'])),
        _sheetNote('Tax is subtracted because it is pass-through — collected for the government, '
            'never revenue. The service charge is the opposite: it is NOT tax, it stays inside '
            'revenue above, and the line here is only telling you how much of that revenue it was.'),
      ],
    );
  }

  Future<void> _methodSheet(Map m) {
    final sales = _n(m['sales']);
    final bills = _int(m['bills']) ?? 0;
    final total = _n(_sales['total_sales']);
    return _detailSheet(
      context,
      eyebrow: 'Payment method · $_windowLabel',
      title: PaymentModes.reportName(m),
      children: [
        _detailRow(context, 'Taken this way', _money(sales)),
        _detailRow(context, 'Share of gross sales', total > 0 ? '${(sales / total * 100).toStringAsFixed(1)}%' : '—'),
        _detailRow(context, 'Bills', '$bills'),
        _detailRow(context, 'Average bill', bills > 0 ? _money(sales / bills) : '—'),
        _sheetNote('The settled-bill list below can be filtered to this method to see the bills '
            'themselves.'),
      ],
    );
  }

  Future<void> _taxRateSheet(Map t) {
    final tax = _n(t['tax']);
    final taxable = _n(t['taxable']);
    final totalTax = _n(_gst['total_tax']);
    return _detailSheet(
      context,
      eyebrow: 'Tax rate · $_windowLabel',
      title: '${_s(t, 'name', 'Tax')} · ${_numOf(t['percentage'])}%',
      children: [
        _detailRow(context, 'Taxable base', _money(taxable)),
        _detailRow(context, 'Rate', '${_numOf(t['percentage'])}%'),
        _detailRow(context, 'Tax charged', _money(tax)),
        _detailRow(context, 'Share of all tax', totalTax > 0 ? '${(tax / totalTax * 100).toStringAsFixed(1)}%' : '—'),
        _sheetNote('This base excludes the service charge. That charge is the restaurant\'s income, '
            'not a taxable levy, and it is reported on its own line — never as a rate here.'),
      ],
    );
  }

  Future<void> _discountsSheet() {
    final estimated = _n(_discounts['estimated_bills']);
    final given = _n(_discounts['total_discount']);
    final billCount = _int(_discounts['bill_count']) ?? 0;
    final discounted = _int(_discounts['discounted_bills']) ?? 0;
    final notes = ((_discounts['notes'] as List?) ?? const []).map((e) => '$e').where((s) => s.isNotEmpty);
    return _detailSheet(
      context,
      eyebrow: 'Discounts given · $_windowLabel',
      title: '${estimated > 0 ? '≈' : ''}${_money(given)}',
      children: [
        _detailRow(context, 'Manual discounts', _money(_discounts['manual_discount'])),
        _detailRow(context, 'Coupons & vouchers', _money(_discounts['coupon_discount'])),
        _detailRow(context, 'Total given', _money(given)),
        _sheetHead('Reach'),
        _detailRow(context, 'Bills discounted', '$discounted of $billCount'),
        _detailRow(context, 'Share of bills',
            billCount > 0 ? '${(discounted / billCount * 100).toStringAsFixed(1)}%' : '—'),
        _detailRow(context, 'Sales in the same window', _money(_discounts['total_sales'])),
        if (_n(_discounts['gift_redemption_total']) > 0)
          _detailRow(context, 'Gift vouchers redeemed', _money(_discounts['gift_redemption_total'])),
        if (estimated > 0)
          _sheetNote('${estimated.round()} bill(s) stored the discount as a bare percentage, so the '
              'money value is reconstructed and the totals above are approximate.'),
        // "after", not "net of": Net is the defined word for the item total less
        // discounts (models/gross_net.dart), and these bill totals are Gross.
        _sheetNote('Bill totals are already stored after discount, so every sales, tax and profit '
            'figure on this page reflects these. Never subtract this again.'),
        for (final n in notes) _sheetNote(n),
      ],
    );
  }

  Future<void> _couponSheet(Map c) {
    final amount = _n(c['amount']);
    final uses = _int(c['uses']) ?? 0;
    final total = _n(_discounts['total_discount']);
    return _detailSheet(
      context,
      eyebrow: '${'${c['kind']}' == 'gift' ? 'Gift voucher' : 'Coupon'} · $_windowLabel',
      title: _s(c, 'code'),
      children: [
        _detailRow(context, 'Given away', _money(amount)),
        _detailRow(context, 'Times redeemed', '$uses'),
        _detailRow(context, 'Average per use', uses > 0 ? _money(amount / uses) : '—'),
        _detailRow(context, 'Share of all discount', total > 0 ? '${(amount / total * 100).toStringAsFixed(1)}%' : '—'),
      ],
    );
  }

  Future<void> _expenseSheet(Map e) {
    final vendor = _s(e, 'vendor', '');
    final note = _s(e, 'note', '');
    final total = _n(_pnl['total_expenses']);
    final amount = _n(e['amount']);
    return _detailSheet(
      context,
      eyebrow: 'Expense · ${_s(e, 'category', 'General')}',
      title: _money(amount),
      children: [
        _detailRow(context, 'Category', _s(e, 'category', 'General')),
        _detailRow(context, 'Spent on', _s(e, 'spent_on')),
        if (vendor.isNotEmpty) _detailRow(context, 'Vendor', vendor),
        _detailRow(context, 'Share of expenses', total > 0 ? '${(amount / total * 100).toStringAsFixed(1)}%' : '—'),
        if (_s(e, 'created_at', '').isNotEmpty) _detailRow(context, 'Booked', _fmtTime(_s(e, 'created_at'))),
        if (_s(e, 'created_by', '').isNotEmpty) _detailRow(context, 'Booked by', _s(e, 'created_by')),
        if (note.isNotEmpty) ...[_sheetHead('Note'), _sheetNote(note)],
        // Deleting stays on the row's own button. A sheet reached by tapping a
        // row must not put a destructive control under the reading finger.
      ],
    );
  }

  Future<void> _payrollSheet(Map r) {
    final prof = (r['profile'] as Map?) ?? const {};
    final hourly = '${prof['pay_type']}' == 'hourly';
    final paid = r['paid'] == true;
    final allowances = _n(prof['allowances']);
    final deductions = _n(prof['deductions']);
    return _detailSheet(
      context,
      eyebrow: 'Payroll · $_payrollMonth',
      title: _s(r, 'name'),
      children: [
        _detailRow(context, 'Role', _s(r, 'role')),
        if (prof.isEmpty)
          _sheetNote('No salary is set for this employee, so nothing can be computed. Use "Set '
              'salary" on the row to add one.')
        else ...[
          _detailRow(context, 'Pay type', hourly ? 'Hourly' : 'Monthly'),
          if (hourly) ...[
            _detailRow(context, 'Rate', '${_money(prof['hourly_rate'])} / hour'),
            _detailRow(context, 'Hours worked', '${r['hours_worked'] ?? 0}'),
            _detailRow(context, 'Earned', _money(_n(prof['hourly_rate']) * _n(r['hours_worked']))),
          ] else
            _detailRow(context, 'Base salary', _money(prof['base_salary'])),
          if (allowances != 0) _detailRow(context, 'Allowances', '+ ${_money(allowances)}'),
          if (deductions != 0) _detailRow(context, 'Deductions', '− ${_money(deductions)}'),
          _detailRow(context, paid ? 'Was due' : 'Due now', r['computed_pay'] == null ? '—' : _money(r['computed_pay'])),
        ],
        _sheetHead('This month'),
        _detailRow(context, 'Status', paid ? 'Paid' : 'Not paid yet'),
        if (paid) ...[
          _detailRow(context, 'Paid', _money(r['paid_amount'])),
          if (_s(r, 'paid_at', '').isNotEmpty) _detailRow(context, 'Paid on', _fmtTime(_s(r, 'paid_at'))),
        ],
        _sheetNote('Recording a payment also books a "Payroll" expense, so it lands in the expense '
            'total and in net profit above.'),
      ],
    );
  }

  // Download the Tally-compatible XML for the selected range and let the user
  // save it (parity with the web accounting page).
  Future<void> _exportTally() async {
    final messenger = ScaffoldMessenger.of(context);
    final r = _range;
    try {
      final xml = await widget.rest.getText('/reports/tally.xml?${r.reportQuery}');
      final path = await FilePicker.saveFile(
        dialogTitle: 'Save Tally XML',
        fileName: 'tally-${r.from}-to-${r.to}.xml',
        type: FileType.custom,
        allowedExtensions: const ['xml'],
        bytes: Uint8List.fromList(utf8.encode(xml)),
      );
      messenger.showSnackBar(SnackBar(content: Text(path == null ? 'Export cancelled.' : 'Saved Tally XML.')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load reports',
        error: '$_error',
        onRetry: _load,
      );
    }

    String money(double v) => '₹${v.toStringAsFixed(0)}';
    final byDay = ((_sales['by_day'] as List?) ?? [])
        .map((d) => (label: _ddmm('${(d as Map)['date']}'), value: _n(d['sales'])))
        .toList();
    final byMethod = (_sales['by_method'] as List?) ?? [];
    final byRate = (_gst['by_rate'] as List?) ?? [];
    final byCoupon = (_discounts['by_coupon'] as List?) ?? [];
    final hasDiscounts = _n(_discounts['discounted_bills']) > 0 || byCoupon.isNotEmpty;

    final text = Theme.of(context).textTheme;
    final width = MediaQuery.sizeOf(context).width;
    final narrow = width < 760;
    final cols = width >= 1100 ? 4 : (narrow ? 1 : 2);
    // The period is now the shared DateRangeChip: the same six one-tap presets
    // an owner files against, PLUS a calendar, because /reports/* has always
    // taken from/to dates and the six fixed spans were the only thing stopping
    // this module from expressing "1-15 August".

    // Dense financial table row — label in the quiet voice, amount right.
    //
    // [onTap] opens the row's own breakdown. The affordance is _TapRow's cursor
    // and hover wash rather than a chevron: these rows already carry an
    // unbounded money string beside an ellipsised label, and every pixel a
    // trailing glyph took would come out of the label at 1.3x on a phone.
    Widget moneyRow(String label, String amount, {String? sub, Widget? trailing, VoidCallback? onTap}) {
      final row = Padding(
        padding: const EdgeInsets.symmetric(vertical: 7),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(label, style: text.bodyMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
              if (sub != null) ...[
                const SizedBox(height: 2),
                Text(sub, style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
              ],
            ]),
          ),
          const SizedBox(width: AppSpacing.md),
          Flexible(
            child: Text(amount,
                style: text.titleSmall, maxLines: 1, softWrap: false, overflow: TextOverflow.fade),
          ),
          if (trailing != null) ...[const SizedBox(width: AppSpacing.sm), trailing],
        ]),
      );
      return onTap == null ? row : _TapRow(onTap: onTap, child: row);
    }

    // Rows in this section open their own detail — said once per card rather
    // than decorating every row. Self-aligning, because the expense card's
    // Column centres its children and this line belongs at the left margin
    // with the labels it describes.
    Widget tapHint() => Align(
          alignment: Alignment.centerLeft,
          child: Padding(
            padding: const EdgeInsets.only(top: 2, bottom: 2),
            child: Text('Tap a row for its breakdown.', style: text.bodySmall),
          ),
        );

    Widget detailsFooter() => Row(mainAxisSize: MainAxisSize.min, children: [
          Text('DETAILS', style: text.labelSmall!.copyWith(color: AppColors.copper)),
          Icon(Icons.chevron_right, size: 14, color: AppColors.copper),
        ]);
    Widget hairline() => Container(height: 1, color: AppColors.divider);

    String initialsOf(String name) {
      final parts = name.trim().split(RegExp(r'\s+')).where((s) => s.isNotEmpty).toList();
      if (parts.isEmpty) return '?';
      return parts.length == 1
          ? parts.first.substring(0, 1)
          : '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}';
    }

    final payrollRows = (_payroll['rows'] as List?) ?? [];
    final netProfitUp = _n(_pnl['net_profit']) >= 0;

    return cacheStaleOverlay(RefreshIndicator(
      onRefresh: _load,
      child: ListView(controller: _scroll, padding: AppSpacing.pageNarrow, children: [
        // The two exports drop below the period control on a phone, and wrap
        // again between themselves if they still do not fit. Side by side on one
        // line they wanted 410px of a 358px column at 1.3x.
        Builder(builder: (_) {
          final tabs = Align(
            alignment: Alignment.centerLeft,
            child: DateRangeChip(value: _range, onChanged: _setRange),
          );
          final exports = Wrap(
            alignment: WrapAlignment.end,
            spacing: AppSpacing.sm,
            runSpacing: AppSpacing.sm,
            children: [
              ForkButton.ghost(
                  label: 'Tally XML', icon: Icons.description_outlined, dense: true, onPressed: _exportTally),
              ForkButton.ghost(
                  label: 'Export PDF', icon: Icons.picture_as_pdf_outlined, dense: true, onPressed: _exportPdf),
            ],
          );
          if (!narrow) {
            return Row(children: [
              Expanded(child: tabs),
              const SizedBox(width: AppSpacing.sm),
              exports,
            ]);
          }
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            tabs,
            const SizedBox(height: AppSpacing.sm),
            exports,
          ]);
        }),
        const SizedBox(height: AppSpacing.lg),
        // Each headline opens the arithmetic under it. The captions say GST but
        // the tax sheet is careful to name the service charge separately — it is
        // income, not a levy, and the two must never read as one bucket.
        _dashGrid([
          // NET, in the client's word: after discount, before service charge,
          // tax and round off. This card used to show net_sales — Gross less
          // refunds, tax and all — under this caption; that figure is on the
          // sheet behind it, named for what it is.
          StatCard(
            value: money(readAccountingSales(_sales).headlineValue ?? 0),
            caption: readAccountingSales(_sales).headlineLabel.toUpperCase(),
            footer: detailsFooter(),
            onTap: _netSalesSheet,
          ),
          StatCard(
            value: money(_n(_gst['total_tax'])),
            caption: 'GST COLLECTED',
            footer: detailsFooter(),
            onTap: _taxSheet,
          ),
          StatCard(
            value: money(_n(_pnl['total_expenses'])),
            caption: 'EXPENSES',
            footer: detailsFooter(),
            onTap: _expensesSheet,
          ),
          StatCard(
            value: money(_n(_pnl['net_profit'])),
            caption: 'NET PROFIT',
            tag: netProfitUp ? 'Up' : 'Dn',
            tagColor: netProfitUp ? AppColors.success : AppColors.danger,
            footer: detailsFooter(),
            onTap: _netProfitSheet,
          ),
        ], cols),
        const SizedBox(height: AppSpacing.xl),
        if (byDay.isNotEmpty) ...[
          _chartCard(context, 'Sales — daily', _barChart(context, byDay, money)),
          const SizedBox(height: AppSpacing.lg),
        ],
        if (byMethod.isNotEmpty) ...[
          ForkCard(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              SectionHeader(title: 'By payment method', padding: const EdgeInsets.only(bottom: 12)),
              Builder(builder: (_) {
                final rows = byMethod.map((m) => m as Map).toList()
                  ..sort((a, b) => _n(b['sales']).compareTo(_n(a['sales'])));
                final maxV = rows.fold<double>(0, (a, m) => _n(m['sales']) > a ? _n(m['sales']) : a);
                return Column(children: [
                  for (final m in rows)
                    HBarRow(
                      label: PaymentModes.reportName(m),
                      sub: '${m['bills'] ?? 0} bills',
                      fraction: maxV > 0 ? (_n(m['sales']) / maxV).clamp(0.0, 1.0) : 0,
                      value: money(_n(m['sales'])),
                      tooltip: '${PaymentModes.reportName(m)} · ${_money(m['sales'])}',
                      onTap: () => _methodSheet(m),
                    ),
                ]);
              }),
            ]),
          ),
          const SizedBox(height: AppSpacing.lg),
        ],
        if (byRate.isNotEmpty) ...[
          ForkCard(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              SectionHeader(title: 'GST breakdown', padding: const EdgeInsets.only(bottom: 6)),
              tapHint(),
              for (var i = 0; i < byRate.length; i++) ...[
                if (i > 0) hairline(),
                moneyRow(
                  '${_s(byRate[i] as Map, 'name', 'Tax')} · ${(byRate[i] as Map)['percentage'] ?? 0}%',
                  _money((byRate[i] as Map)['tax']),
                  sub: 'Taxable ${_money((byRate[i] as Map)['taxable'])}',
                  onTap: () => _taxRateSheet(byRate[i] as Map),
                ),
              ],
              // Service charge is deliberately absent from the rates above: it
              // is income, not tax. Named here so its absence reads as a
              // decision rather than a missing row.
              if (_n(_gst['total_service_charge']) > 0) ...[
                hairline(),
                moneyRow(
                  'Service charge — not tax',
                  _money(_gst['total_service_charge']),
                  sub: 'Kept by the restaurant, excluded from every rate above',
                  onTap: _taxSheet,
                ),
              ],
            ]),
          ),
          const SizedBox(height: AppSpacing.lg),
        ],
        if (hasDiscounts) ...[
          ForkCard(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              SectionHeader(title: 'Discounts & offers', padding: const EdgeInsets.only(bottom: 6)),
              Text('Bill totals are stored after discount — sales above already reflect these.',
                  style: text.bodySmall),
              const SizedBox(height: AppSpacing.sm),
              moneyRow(
                'Total given',
                '${_n(_discounts['estimated_bills']) > 0 ? '≈' : ''}${_money(_discounts['total_discount'])}',
                sub:
                    '${_discounts['discounted_bills'] ?? 0} of ${_discounts['bill_count'] ?? 0} bills · manual ${_money(_discounts['manual_discount'])} · coupons ${_money(_discounts['coupon_discount'])}',
                onTap: _discountsSheet,
              ),
              for (final c in byCoupon) ...[
                hairline(),
                moneyRow(
                  '${_s(c as Map, 'code')}${'${c['kind']}' == 'gift' ? ' · Gift voucher' : ''}',
                  _money(c['amount']),
                  sub: '${c['uses'] ?? 0} uses',
                  onTap: () => _couponSheet(c),
                ),
              ],
            ]),
          ),
          const SizedBox(height: AppSpacing.lg),
        ],
        // --- Settled bills ---------------------------------------------------
        // Past bills had no home in the app at all. Scoped to the same period as
        // every other figure on this page so the list and the totals above can
        // never disagree about which days they are describing.
        const SizedBox(height: AppSpacing.sm),
        // The pill here used to be a static InfoChip dressed as the date control
        // (same icon, same dates, no tap). It is now the live control, on the
        // SAME window as the chip at the top.
        SectionHeader(
          key: _settledBillsKey,
          title: 'Settled bills',
          trailing: SectionRangeChip(value: _range, onChanged: (r) => _setRange(r, revealBills: true)),
          padding: const EdgeInsets.only(bottom: 6),
        ),
        Text('Every bill closed in this period, newest first — tap one for its items, taxes, payment and who closed it.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.md),
        Row(children: [
          Expanded(
            child: TextField(
              controller: _billSearch,
              decoration: InputDecoration(
                isDense: true,
                hintText: 'Search bill no, table, customer…',
                prefixIcon: Icon(Icons.search, size: 18, color: AppColors.textTertiary),
                suffixIcon: _billTerm.isEmpty
                    ? null
                    : IconButton(
                        icon: const Icon(Icons.close, size: 16),
                        tooltip: 'Clear search',
                        onPressed: () {
                          _billDebounce?.cancel();
                          _billSearch.clear();
                          setState(() => _billTerm = '');
                        },
                      ),
              ),
              onChanged: (v) {
                _billDebounce?.cancel();
                _billDebounce = Timer(const Duration(milliseconds: 350), () {
                  if (mounted) setState(() => _billTerm = v.trim());
                });
              },
              onSubmitted: (v) {
                _billDebounce?.cancel();
                setState(() => _billTerm = v.trim());
              },
            ),
          ),
          if (byMethod.isNotEmpty) ...[
            const SizedBox(width: AppSpacing.sm),
            SizedBox(
              width: 180,
              child: DropdownButtonFormField<String>(
                initialValue: _billMethod,
                isExpanded: true,
                dropdownColor: AppColors.cardRaised,
                decoration: const InputDecoration(labelText: 'Payment method', isDense: true),
                items: [
                  const DropdownMenuItem<String>(value: null, child: Text('All methods')),
                  for (final m in byMethod)
                    DropdownMenuItem<String>(
                      value: _s(m as Map, 'method', ''),
                      child: Text(PaymentModes.reportName(m), overflow: TextOverflow.ellipsis),
                    ),
                ],
                onChanged: (v) => setState(() => _billMethod = (v ?? '').isEmpty ? null : v),
              ),
            ),
          ],
        ]),
        const SizedBox(height: AppSpacing.md),
        Builder(builder: (_) {
          final r = _range;
          return _ClosedBillsList(
            rest: widget.rest,
            // Accounting is where a cash-up is reconciled, so it is where a bill
            // rung on the wrong till gets moved.
            profile: widget.profile,
            filter: _ClosedBillFilter(
              from: r.from,
              to: r.to,
              search: _billTerm,
              paymentMethod: _billMethod,
            ),
            emptyCaption: _billTerm.isEmpty && _billMethod == null
                ? 'No bills were closed in ${_range.label()}.'
                : 'No settled bill in ${_range.label()} matches that filter.',
          );
        }),
        const SizedBox(height: AppSpacing.xxl),
        SectionHeader(
          title: 'Expenses',
          count: _expenses.length,
          trailing: ForkButton.ghost(label: 'Add', icon: Icons.add, dense: true, onPressed: _addExpense),
        ),
        if (_expenses.isEmpty)
          Text('No expenses in this period.', style: text.bodySmall)
        else
          ForkCard(
            child: Column(children: [
              tapHint(),
              for (var i = 0; i < _expenses.length; i++) ...[
                if (i > 0) hairline(),
                moneyRow(
                  '${_s(_expenses[i] as Map, 'category', 'General')}${_s(_expenses[i] as Map, 'vendor').isNotEmpty ? ' · ${_s(_expenses[i] as Map, 'vendor')}' : ''}',
                  _money((_expenses[i] as Map)['amount']),
                  sub:
                      '${_s(_expenses[i] as Map, 'spent_on')}${_s(_expenses[i] as Map, 'note').isNotEmpty ? ' · ${_s(_expenses[i] as Map, 'note')}' : ''}',
                  // Delete keeps its own button. The row tap opens the record;
                  // a destructive action is never what a row tap resolves to.
                  onTap: () => _expenseSheet(_expenses[i] as Map),
                  trailing: ForkIconButton(
                    icon: Icons.delete_outline,
                    tooltip: 'Delete expense',
                    onPressed: () => _deleteExpense('${(_expenses[i] as Map)['id']}'),
                  ),
                ),
              ],
            ]),
          ),
        const SizedBox(height: AppSpacing.xxl),
        SectionHeader(
          title: 'Payroll',
          trailing: Row(mainAxisSize: MainAxisSize.min, children: [
            ForkIconButton(icon: Icons.chevron_left, tooltip: 'Previous month', onPressed: () => _shiftPayrollMonth(-1)),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 10),
              child: Text(_payrollMonth, style: text.titleSmall),
            ),
            ForkIconButton(icon: Icons.chevron_right, tooltip: 'Next month', onPressed: () => _shiftPayrollMonth(1)),
          ]),
          padding: const EdgeInsets.only(bottom: 6),
        ),
        Text('Due ${_money(_payroll['total_due'])} · Paid ${_money(_payroll['total_paid'])} — paying books a "Payroll" expense. '
            'Tap anyone for how their pay was worked out.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.md),
        if (payrollRows.isNotEmpty)
          ForkCard(
            child: Column(children: [
              for (var i = 0; i < payrollRows.length; i++) ...[
                if (i > 0) hairline(),
                Builder(builder: (_) {
                  final r = payrollRows[i] as Map;
                  final prof = r['profile'] as Map?;
                  final paid = r['paid'] == true;
                  final pay = r['computed_pay'];
                  final hourly = '${prof?['pay_type']}' == 'hourly';
                  // Tapping opens how the figure was arrived at — rate, hours,
                  // allowances, deductions. Editing and paying stay on their own
                  // buttons.
                  return _TapRow(
                    onTap: () => _payrollSheet(r),
                    child: Padding(
                      padding: const EdgeInsets.symmetric(vertical: 8),
                      child: _recordHeadRow(
                        context,
                        leading: InitialsAvatar(initials: initialsOf(_s(r, 'name', ''))),
                        identity: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Text('${_s(r, 'name')} · ${_s(r, 'role')}',
                              style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                          const SizedBox(height: 2),
                          Text(
                            prof == null
                                ? 'No salary set'
                                : hourly
                                    ? '${_money(prof['hourly_rate'])}/h · ${r['hours_worked'] ?? 0}h worked'
                                    : 'Monthly ${_money(prof['base_salary'])}',
                            style: text.bodySmall,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ]),
                        trailing: [
                          if (paid)
                            StatusChip(
                                label: 'Paid ${_money(r['paid_amount'])}', color: AppColors.success, dense: narrow)
                          else ...[
                            Text(pay != null ? _money(pay) : '—', style: text.titleSmall),
                            ForkIconButton(
                                icon: Icons.edit_outlined,
                                tooltip: 'Set salary',
                                onPressed: () => _editPayrollProfile(r)),
                            if (pay != null && (pay as num) > 0)
                              ForkButton(
                                label: 'Pay',
                                icon: Icons.payments_outlined,
                                dense: true,
                                onPressed: () => _payEmployee(r),
                              ),
                          ],
                        ],
                      ),
                    ),
                  );
                }),
              ],
            ]),
          ),
        const SizedBox(height: AppSpacing.xxl),
        _ScheduledReportsCard(
          rest: widget.rest,
          schedules: _schedules,
          deliveries: _deliveries,
          reload: _load,
        ),
      ]),
    ));
  }
}

// --- Scheduled report delivery ----------------------------------------------
// The server builds these on its own and files each run's CSV against a
// delivery row; the notification bell only says one is ready and points here.
// That split is the backend's: GET /notifications is readable by every
// authenticated employee, so no figure travels in the bell — which is why the
// file is downloaded from this card and nowhere else.
//
// Only sales, P&L and GST can be scheduled. Those are the three reports scoped
// to the restaurant's own calendar day, so "yesterday" means the same thing
// here as in the file; the backend admits nothing else.
const Map<String, String> _reportKeyLabels = {
  'sales': 'Sales',
  'pnl': 'Profit & loss',
  'gst': 'GST / tax',
};

const Map<String, String> _reportFrequencyLabels = {
  'daily': 'Every day',
  'weekly': 'Every week',
  'monthly': 'Every month',
};

// What each frequency actually covers, spelled out in the editor: a report that
// runs at 08:00 covers YESTERDAY, and that is the kind of thing an owner
// otherwise discovers by reconciling a file against the wrong day.
const Map<String, String> _reportPeriodNotes = {
  'daily': 'Covers the previous day.',
  'weekly': 'Covers the seven days ending the day before it runs.',
  'monthly': 'Covers the whole previous calendar month.',
};

// 0 = Sunday, matching the backend's weekday column.
const List<String> _weekdayNames = [
  'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday',
];

/// A delivery's status as the owner should read it. `claimed` means the run has
/// been taken and nothing else may take it; `abandoned` is an occurrence that
/// came due while the server was down past its catch-up window — recorded as a
/// row rather than silently skipped, which is the whole point of the history.
({String label, Color color}) _deliveryStatus(String status) {
  switch (status) {
    case 'delivered':
      return (label: 'Delivered', color: AppColors.success);
    case 'rendered':
      return (label: 'Building', color: AppColors.info);
    case 'claimed':
      return (label: 'Queued', color: AppColors.neutral);
    case 'failed':
      return (label: 'Failed', color: AppColors.danger);
    case 'abandoned':
      return (label: 'Missed', color: AppColors.warning);
  }
  return (label: status, color: AppColors.neutral);
}

class _ScheduledReportsCard extends StatefulWidget {
  final RestClient rest;
  final List schedules;
  final List deliveries;
  final VoidCallback reload;
  const _ScheduledReportsCard({
    required this.rest,
    required this.schedules,
    required this.deliveries,
    required this.reload,
  });

  @override
  State<_ScheduledReportsCard> createState() => _ScheduledReportsCardState();
}

class _ScheduledReportsCardState extends State<_ScheduledReportsCard> {
  bool _busy = false;

  // "All outlets (combined)" is a READ-ONLY view — the backend rejects every
  // non-GET request while it is active. This list is one of the few that widens
  // in that mode (it returns every outlet's schedules), so leaving the write
  // controls up would offer a button whose only possible outcome is a 400.
  bool get _allOutlets => widget.rest.auth.selectedOutletId == 'all';

  // "Every day at 08:00 Asia/Kolkata" — the zone is named because the hour is
  // the RESTAURANT's wall clock, not the clock on whichever machine is reading
  // this. An owner in another state would otherwise read it as their own.
  String _whenLabel(Map s) {
    final at = '${_two(_int(s['hour_local']) ?? 0)}:${_two(_int(s['minute_local']) ?? 0)} ${RestaurantTime.zone}';
    final frequency = _s(s, 'frequency', 'daily');
    if (frequency == 'weekly') {
      final wd = _int(s['weekday']) ?? 0;
      final name = wd >= 0 && wd < _weekdayNames.length ? _weekdayNames[wd] : 'week';
      return 'Every $name at $at';
    }
    if (frequency == 'monthly') {
      return 'Day ${_int(s['day_of_month']) ?? 1} of every month at $at';
    }
    return 'Every day at $at';
  }

  static String _two(int n) => n.toString().padLeft(2, '0');

  String _periodLabel(Map d) {
    final from = _s(d, 'period_from', '');
    final to = _s(d, 'period_to', '');
    if (from.isEmpty || to.isEmpty) return '';
    return from == to ? _fmtDay(from) : '${_fmtDay(from)} – ${_fmtDay(to)}';
  }

  /// Whether a delivery came from "Run now" rather than from its schedule.
  bool _isManualRun(Object? occurrenceKey) {
    if (occurrenceKey is! String || occurrenceKey.isEmpty) return true;
    return occurrenceKey.startsWith('manual:');
  }

  // Create and edit share one form: the backend takes the same shape on POST
  // and PATCH, and merges an omitted field onto the existing row.
  Future<void> _scheduleDialog({Map? existing}) async {
    final messenger = ScaffoldMessenger.of(context);
    final name = TextEditingController(text: existing == null ? '' : _s(existing, 'name', ''));
    String reportKey = _s(existing ?? const {}, 'report_key', 'sales');
    if (!_reportKeyLabels.containsKey(reportKey)) reportKey = 'sales';
    String frequency = _s(existing ?? const {}, 'frequency', 'daily');
    if (!_reportFrequencyLabels.containsKey(frequency)) frequency = 'daily';
    int weekday = _int(existing?['weekday']) ?? 1;
    int dayOfMonth = _int(existing?['day_of_month']) ?? 1;
    int hour = _int(existing?['hour_local']) ?? 8;
    int minute = _int(existing?['minute_local']) ?? 0;
    // The quarter-hours plus whatever this row already holds. A schedule saved
    // from another client at, say, :07 must still open in the dropdown rather
    // than crash it with a value no item carries.
    final minuteOptions = (<int>{0, 15, 30, 45, minute}.toList()..sort());
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDlg) => Dialog(
          backgroundColor: Colors.transparent,
          child: Container(
            width: 400,
            padding: const EdgeInsets.all(22),
            decoration: BoxDecoration(
              gradient: AppColors.cardGradient,
              borderRadius: AppRadius.cardAll,
              border: Border.all(color: AppColors.borderStrong),
            ),
            child: SingleChildScrollView(
              child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text('SCHEDULED REPORT', style: Theme.of(ctx).textTheme.labelSmall),
                const SizedBox(height: 6),
                Text(existing == null ? 'New schedule' : 'Edit schedule', style: Theme.of(ctx).textTheme.titleMedium),
                const SizedBox(height: AppSpacing.lg),
                TextField(
                  controller: name,
                  autofocus: true,
                  decoration: const InputDecoration(labelText: 'Name (e.g. Morning sales)', isDense: true),
                ),
                const SizedBox(height: AppSpacing.sm),
                DropdownButtonFormField<String>(
                  initialValue: reportKey,
                  dropdownColor: AppColors.cardRaised,
                  borderRadius: AppRadius.controlAll,
                  decoration: const InputDecoration(labelText: 'Report', isDense: true),
                  items: [
                    for (final e in _reportKeyLabels.entries)
                      DropdownMenuItem(value: e.key, child: Text(e.value)),
                  ],
                  onChanged: (v) => setDlg(() => reportKey = v ?? 'sales'),
                ),
                const SizedBox(height: AppSpacing.sm),
                DropdownButtonFormField<String>(
                  initialValue: frequency,
                  dropdownColor: AppColors.cardRaised,
                  borderRadius: AppRadius.controlAll,
                  decoration: const InputDecoration(labelText: 'How often', isDense: true),
                  items: [
                    for (final e in _reportFrequencyLabels.entries)
                      DropdownMenuItem(value: e.key, child: Text(e.value)),
                  ],
                  onChanged: (v) => setDlg(() => frequency = v ?? 'daily'),
                ),
                if (frequency == 'weekly') ...[
                  const SizedBox(height: AppSpacing.sm),
                  DropdownButtonFormField<int>(
                    initialValue: weekday,
                    dropdownColor: AppColors.cardRaised,
                    borderRadius: AppRadius.controlAll,
                    decoration: const InputDecoration(labelText: 'Day of the week', isDense: true),
                    items: [
                      for (var i = 0; i < _weekdayNames.length; i++)
                        DropdownMenuItem(value: i, child: Text(_weekdayNames[i])),
                    ],
                    onChanged: (v) => setDlg(() => weekday = v ?? 1),
                  ),
                ],
                if (frequency == 'monthly') ...[
                  const SizedBox(height: AppSpacing.sm),
                  DropdownButtonFormField<int>(
                    initialValue: dayOfMonth,
                    dropdownColor: AppColors.cardRaised,
                    borderRadius: AppRadius.controlAll,
                    // Capped at 28 by the backend so "the 31st" can never skip
                    // February outright.
                    decoration: const InputDecoration(labelText: 'Day of the month (1–28)', isDense: true),
                    items: [
                      for (var i = 1; i <= 28; i++) DropdownMenuItem(value: i, child: Text('$i')),
                    ],
                    onChanged: (v) => setDlg(() => dayOfMonth = v ?? 1),
                  ),
                ],
                const SizedBox(height: AppSpacing.sm),
                Row(children: [
                  Expanded(
                    child: DropdownButtonFormField<int>(
                      initialValue: hour,
                      dropdownColor: AppColors.cardRaised,
                      borderRadius: AppRadius.controlAll,
                      decoration: const InputDecoration(labelText: 'Hour', isDense: true),
                      items: [
                        for (var i = 0; i < 24; i++) DropdownMenuItem(value: i, child: Text(_two(i))),
                      ],
                      onChanged: (v) => setDlg(() => hour = v ?? 8),
                    ),
                  ),
                  const SizedBox(width: AppSpacing.sm),
                  Expanded(
                    child: DropdownButtonFormField<int>(
                      initialValue: minute,
                      dropdownColor: AppColors.cardRaised,
                      borderRadius: AppRadius.controlAll,
                      decoration: const InputDecoration(labelText: 'Minute', isDense: true),
                      items: [
                        for (final m in minuteOptions) DropdownMenuItem(value: m, child: Text(_two(m))),
                      ],
                      onChanged: (v) => setDlg(() => minute = v ?? 0),
                    ),
                  ),
                ]),
                const SizedBox(height: AppSpacing.sm),
                Text(
                  'Runs at ${_two(hour)}:${_two(minute)} on the restaurant\'s clock (${RestaurantTime.zone}). '
                  '${_reportPeriodNotes[frequency] ?? ''}',
                  style: Theme.of(ctx).textTheme.bodySmall,
                ),
                // The hour above is a wall clock and needs no offset table, but
                // the run times listed on the card do — say so rather than let
                // them quietly fall back to device time.
                if (!RestaurantTime.zoneCovered) ...[
                  const SizedBox(height: 4),
                  Text(
                    'This build cannot resolve ${RestaurantTime.zone}\'s UTC offset, so past run times are shown in device time. The report itself still runs on the restaurant\'s clock.',
                    style: Theme.of(ctx).textTheme.bodySmall,
                  ),
                ],
                const SizedBox(height: AppSpacing.xl),
                Row(mainAxisAlignment: MainAxisAlignment.end, children: [
                  ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
                  const SizedBox(width: AppSpacing.sm),
                  ForkButton(
                    label: existing == null ? 'Create' : 'Save',
                    icon: Icons.check,
                    onPressed: () => Navigator.pop(ctx, true),
                  ),
                ]),
              ]),
            ),
          ),
        ),
      ),
    );
    if (ok != true) return;
    if (name.text.trim().isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('Give the schedule a name.')));
      return;
    }
    // weekday and day_of_month are sent only for the frequency that uses them;
    // the backend nulls the other one so a schedule switched from monthly to
    // weekly cannot keep a stale day behind it.
    final body = <String, dynamic>{
      'name': name.text.trim(),
      'report_key': reportKey,
      'frequency': frequency,
      'hour_local': hour,
      'minute_local': minute,
      if (frequency == 'weekly') 'weekday': weekday,
      if (frequency == 'monthly') 'day_of_month': dayOfMonth,
    };
    setState(() => _busy = true);
    try {
      if (existing == null) {
        await widget.rest.post('/reports/schedules', body);
      } else {
        await widget.rest.patch('/reports/schedules/${existing['id']}', body);
      }
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _setEnabled(Map s, bool enabled) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await widget.rest.patch('/reports/schedules/${s['id']}', {'enabled': enabled});
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  // Queues one extra run outside the schedule. It does NOT render here: the
  // server picks it up on its next sweep, which is why the message points at
  // the history rather than promising a file.
  //
  // 409 is not a failure. The server buckets a manual run to the restaurant's
  // own minute and refuses a second one inside it, so the click that got there
  // first IS queued — reporting that as an error would push the owner into
  // clicking again, and claiming a second run was queued would be a lie.
  Future<void> _runNow(Map s) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await widget.rest.post('/reports/schedules/${s['id']}/run-now');
      messenger.showSnackBar(
          const SnackBar(content: Text('Queued — it appears under Recent deliveries once the server has built it.')));
      widget.reload();
    } catch (e) {
      if (e is ApiException && e.status == 409) {
        messenger.showSnackBar(const SnackBar(
            content: Text('Already queued a moment ago — that run is still on its way, so nothing extra was queued. '
                'Watch Recent deliveries.')));
        // The earlier run is a delivery row that may have appeared since this
        // page loaded, so refresh instead of leaving the owner with no sign of it.
        widget.reload();
      } else {
        messenger.showSnackBar(SnackBar(content: Text('$e')));
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _delete(Map s) async {
    final messenger = ScaffoldMessenger.of(context);
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete this schedule?'),
        // The server archives rather than destroys: the delivery rows are both
        // the history and what stops an occurrence going out twice.
        content: Text('"${_s(s, 'name')}" stops running. Reports it already produced stay in the history and can still be downloaded.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: FilledButton.styleFrom(backgroundColor: AppColors.danger),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (ok != true) return;
    setState(() => _busy = true);
    try {
      await widget.rest.delete('/reports/schedules/${s['id']}');
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  // Same route as the Tally export: pull the stored file and hand it to the
  // platform save dialog. The figures live only in this file — never in the
  // notification that announced it.
  Future<void> _download(Map d) async {
    final messenger = ScaffoldMessenger.of(context);
    final fileName = _s(d, 'artifact_name', 'report.csv');
    try {
      final csv = await widget.rest.getText('/reports/deliveries/${d['id']}/download');
      final path = await FilePicker.saveFile(
        dialogTitle: 'Save $fileName',
        fileName: fileName,
        type: FileType.custom,
        allowedExtensions: const ['csv'],
        bytes: Uint8List.fromList(utf8.encode(csv)),
      );
      messenger.showSnackBar(SnackBar(content: Text(path == null ? 'Download cancelled.' : 'Saved $fileName')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final schedules = [for (final s in widget.schedules) if (s is Map) s];
    final deliveries = [for (final d in widget.deliveries) if (d is Map) d];
    // Delivery rows outlive their schedule (they are the history), so a row
    // whose schedule has since been deleted names the report instead of a
    // schedule that is no longer there.
    final nameById = <String, String>{
      for (final s in schedules) _s(s, 'id', ''): _s(s, 'name', 'Report'),
    }..remove('');
    Widget hairline() => Container(height: 1, color: AppColors.divider);

    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      SectionHeader(
        title: 'Scheduled reports',
        count: schedules.length,
        trailing: _allOutlets
            ? null
            : ForkButton.ghost(
                label: 'New schedule',
                icon: Icons.add,
                dense: true,
                onPressed: _busy ? null : () => _scheduleDialog(),
              ),
        padding: const EdgeInsets.only(bottom: 6),
      ),
      Text(
        'The server builds these on its own — nobody has to open the app. Each run files a CSV you download below, and the notification bell says when one is ready.',
        style: text.bodySmall,
      ),
      // Said once, here, rather than left to each row's controls to discover a
      // rejection at a time. The downloads below are reads and stay available.
      if (_allOutlets) ...[
        const SizedBox(height: AppSpacing.sm),
        Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Icon(Icons.lock_outline, size: 14, color: AppColors.textTertiary),
          const SizedBox(width: 6),
          Expanded(
            child: Text(
              'All outlets (combined) is a read-only view: every outlet\'s schedules are listed here and none of them can be '
              'changed from it. Switch to a single outlet to create, edit, pause, delete or run one.',
              style: text.bodySmall,
            ),
          ),
        ]),
      ],
      const SizedBox(height: AppSpacing.md),
      if (schedules.isEmpty)
        Text('No scheduled reports yet.', style: text.bodySmall)
      else
        for (final s in schedules)
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: _scheduleRow(context, s),
          ),
      if (deliveries.isNotEmpty) ...[
        const SizedBox(height: AppSpacing.lg),
        SectionHeader(
          title: 'Recent deliveries',
          count: deliveries.length,
          padding: const EdgeInsets.only(bottom: 6),
        ),
        ForkCard(
          child: Column(children: [
            for (var i = 0; i < deliveries.length; i++) ...[
              if (i > 0) hairline(),
              _deliveryRow(context, deliveries[i], nameById),
            ],
          ]),
        ),
      ],
    ]);
  }

  Widget _scheduleRow(BuildContext context, Map s) {
    final text = Theme.of(context).textTheme;
    final on = s['enabled'] != false;
    final failures = _int(s['consecutive_failures']) ?? 0;
    final lastStatus = _s(s, 'last_status', '');
    final lastError = _s(s, 'last_error', '');
    final lastRun = _s(s, 'last_run_at', '');
    return ForkCard(
      padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
        _recordHeadRow(
          context,
          leading: Container(
            width: 38,
            height: 38,
            decoration: BoxDecoration(
              color: AppColors.inset,
              borderRadius: AppRadius.controlAll,
              border: Border.all(color: AppColors.border),
            ),
            child: Icon(Icons.event_repeat_outlined,
                size: 16, color: on ? AppColors.textSecondary : AppColors.textTertiary),
          ),
          identity: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text(_s(s, 'name', 'Scheduled report'),
                style: text.titleMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
            const SizedBox(height: 3),
            Text('${_reportKeyLabels[_s(s, 'report_key', '')] ?? _s(s, 'report_key')} · ${_whenLabel(s)}',
                style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
          ]),
          trailing: [
            StatusChip(
              label: on ? 'On' : 'Paused',
              color: on ? AppColors.success : AppColors.neutral,
              dense: true,
            ),
            if (lastStatus.isNotEmpty)
              StatusChip(
                label: 'Last run ${_deliveryStatus(lastStatus).label.toLowerCase()}',
                color: _deliveryStatus(lastStatus).color,
                dense: true,
              ),
            // Run now and every item in the menu writes, so in the combined
            // view they are dropped rather than shown against a row this mode
            // cannot act on — the note under the section header says why.
            if (!_allOutlets) ...[
              ForkButton.ghost(
                label: 'Run now',
                icon: Icons.play_arrow_outlined,
                dense: true,
                onPressed: _busy ? null : () => _runNow(s),
              ),
              PopupMenuButton<String>(
                iconColor: AppColors.textSecondary,
                enabled: !_busy,
                onSelected: (v) {
                  if (v == 'edit') _scheduleDialog(existing: s);
                  if (v == 'toggle') _setEnabled(s, !on);
                  if (v == 'delete') _delete(s);
                },
                itemBuilder: (_) => [
                  const PopupMenuItem(value: 'edit', child: Text('Edit')),
                  PopupMenuItem(value: 'toggle', child: Text(on ? 'Pause' : 'Resume')),
                  const PopupMenuItem(value: 'delete', child: Text('Delete')),
                ],
              ),
            ],
          ],
        ),
        if (lastRun.isNotEmpty || failures > 0) ...[
          const SizedBox(height: 12),
          Wrap(spacing: AppSpacing.xl, runSpacing: AppSpacing.sm, children: [
            if (lastRun.isNotEmpty) MicroStat(value: _fmtTime(lastRun), label: 'last run'),
            if (failures > 0) MicroStat(value: '$failures', label: 'failures in a row'),
          ]),
        ],
        if (lastError.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.sm),
          Text(_capped(lastError, 200), style: text.bodySmall!.copyWith(color: AppColors.danger)),
        ],
        // The server pauses a schedule that keeps failing rather than raising
        // the same alarm every morning, so say that is what happened.
        if (!on && failures > 0) ...[
          const SizedBox(height: AppSpacing.sm),
          Text('Paused automatically after repeated failures — fix the cause, then resume it.', style: text.bodySmall),
        ],
      ]),
    );
  }

  Widget _deliveryRow(BuildContext context, Map d, Map<String, String> nameById) {
    final text = Theme.of(context).textTheme;
    final status = _deliveryStatus(_s(d, 'status', ''));
    final title = nameById['${d['schedule_id']}'] ?? 'Deleted schedule';
    final when = _s(d, 'delivered_at', '').isNotEmpty ? _s(d, 'delivered_at') : _s(d, 'created_at', '');
    final error = _s(d, 'error', '');
    final hasFile = _s(d, 'artifact_name', '').isNotEmpty;
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text(title, style: text.bodyMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
            const SizedBox(height: 2),
            Text(
              [
                _periodLabel(d),
                if (when.isNotEmpty) _fmtTime(when),
                // A "Run now" carries a `manual:`-prefixed key bucketed to the
                // minute, so repeated clicks collapse through the partial unique
                // index; a scheduled occurrence carries a bare day key. Both are
                // non-null, so presence alone does not tell them apart — reading
                // it that way labelled every manual run as scheduled. Null still
                // counts as manual: that is what one stored before the key existed.
                if (_isManualRun(d['occurrence_key'])) 'run manually',
                if (d['artifact_truncated'] == true) 'file truncated',
              ].where((p) => p.isNotEmpty).join(' · '),
              style: text.bodySmall,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
            ),
            if (error.isNotEmpty) ...[
              const SizedBox(height: 2),
              Text(_capped(error, 160), style: text.bodySmall!.copyWith(color: AppColors.danger)),
            ],
          ]),
        ),
        const SizedBox(width: AppSpacing.sm),
        StatusChip(label: status.label, color: status.color, dense: true),
        if (hasFile) ...[
          const SizedBox(width: AppSpacing.sm),
          ForkIconButton(
            icon: Icons.download_outlined,
            tooltip: 'Download ${_s(d, 'artifact_name')}',
            onPressed: () => _download(d),
          ),
        ],
      ]),
    );
  }
}

// --- Settled (closed) bills -------------------------------------------------
// A settled bill used to be invisible everywhere in the app. Two call sites
// share this block: Accounting's "Settled bills" section and the per-month
// drill-down in History.
//
// Money is rendered ONLY from the four fields the backend guarantees add up —
// `taxable_base + service_charge + tax_total == grand_total` — and the service
// charge is NEVER shown inside the tax list (the backend keeps it out of
// `taxes[]`; so does every row here). The identity is displayed rather than
// assumed, so a bill that ever stopped balancing is visible instead of silent.

/// Filter for `GET /bills/closed`. Blank fields are dropped so the backend
/// keeps its own defaults rather than being handed empty strings.
class _ClosedBillFilter {
  final String? from;
  final String? to;
  final String? paymentMethod;
  final String? search;
  const _ClosedBillFilter({this.from, this.to, this.paymentMethod, this.search});

  String query({required int limit, required int offset}) {
    final parts = <String>['limit=$limit', 'offset=$offset'];
    void add(String key, String? value) {
      final v = value?.trim() ?? '';
      if (v.isNotEmpty) parts.add('$key=${Uri.encodeQueryComponent(v)}');
    }

    add('from', from);
    add('to', to);
    add('payment_method', paymentMethod);
    add('search', search);
    return parts.join('&');
  }
}

/// When the bill actually closed. `settled_at` is authoritative; `closed_at`
/// then `created_at` cover rows written before it existed.
String _billWhen(Map b) {
  for (final k in const ['settled_at', 'closed_at', 'created_at']) {
    final v = _s(b, k, '');
    if (v.isNotEmpty) return v;
  }
  return '';
}

/// Bill title: "Bill #57 · T1" (either half degrades on its own).
String _billTitle(Map b) {
  final no = _s(b, 'bill_no', '');
  final table = _s(b, 'table_name', '');
  final left = no.isEmpty ? 'Bill' : 'Bill #$no';
  return table.isEmpty ? left : '$left · $table';
}

void _openClosedBill(BuildContext context, RestClient rest, Map bill, [Profile? profile, VoidCallback? onChanged]) {
  final id = _s(bill, 'id', '');
  if (id.isEmpty) return;
  showModalBottomSheet<void>(
    context: context,
    showDragHandle: true,
    isScrollControlled: true,
    backgroundColor: AppColors.surface,
    builder: (_) => _ClosedBillSheet(
      rest: rest,
      billId: id,
      title: _billTitle(bill),
      profile: profile,
      onChanged: onChanged,
    ),
  );
}

/// One row in the settled-bill list. Tapping it opens the full bill.
///
/// [onChanged] is told when the name / GSTIN on this bill was edited — from the
/// row's own control (with the server's answer) or from the sheet (without).
Widget _closedBillRow(BuildContext context, RestClient rest, Map b,
    [Profile? profile, void Function(Map<String, dynamic>? saved)? onChanged]) {
  final text = Theme.of(context).textTheme;
  final method = _s(b, 'payment_method', '');
  final refunded = b['refunded'] == true;
  final covers = _int(b['covers']);
  final when = _billWhen(b);
  return Padding(
    padding: const EdgeInsets.only(bottom: 8),
    child: ForkCard(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      onTap: () => _openClosedBill(context, rest, b, profile, onChanged == null ? null : () => onChanged(null)),
      child: Row(children: [
        Container(
          width: 36,
          height: 36,
          decoration: BoxDecoration(
            color: AppColors.inset,
            borderRadius: AppRadius.controlAll,
            border: Border.all(color: AppColors.border),
          ),
          child: Icon(Icons.receipt_long_outlined, size: 16, color: AppColors.copper),
        ),
        const SizedBox(width: AppSpacing.md),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(_billTitle(b), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            const SizedBox(height: 4),
            Wrap(spacing: 6, runSpacing: 4, children: [
              if (when.isNotEmpty) InfoChip(icon: Icons.schedule, label: _fmtTime(when)),
              if (covers != null && covers > 0) InfoChip(icon: Icons.people_outline, label: '$covers covers'),
              if (method.isNotEmpty && method != '—')
                InfoChip(icon: Icons.payments_outlined, label: NcSettle.isMethod(method) ? kNcSettleLabel : method),
              if (refunded) const InfoChip(icon: Icons.undo, label: 'Refunded'),
              // ROUND 2 ITEM 1 — who the bill was for, so a correction is visible
              // on the row it was made from.
              if (billCustomerNameSeed(b['customer']).isNotEmpty)
                InfoChip(icon: Icons.person_outline, label: billCustomerNameSeed(b['customer'])),
              if (_s(b, 'customer_gstin', '').isNotEmpty)
                InfoChip(icon: Icons.business_outlined, label: 'GSTIN ${_s(b, 'customer_gstin')}'),
            ]),
          ]),
        ),
        const SizedBox(width: AppSpacing.md),
        // ROUND 2 ITEM 1 — "Edit name / GSTIN" per past bill, behind the reprint
        // gate (the widget draws nothing for anyone else).
        if (onChanged != null && _maySetSettledBillCustomer(profile))
          _EditSettledBillCustomerButton(
            key: ValueKey('closed-bill-row-edit-customer-${_s(b, 'id', '')}'),
            rest: rest,
            bill: b,
            profile: profile,
            compact: true,
            onSaved: onChanged,
          ),
        Text(_money(b['grand_total']), style: text.titleSmall),
        const SizedBox(width: 4),
        Icon(Icons.chevron_right, size: 18, color: AppColors.textTertiary),
      ]),
    ),
  );
}

/// Paged, newest-first list of closed bills. Owns its own paging (limit/offset)
/// so both call sites get "Load more" without repeating the plumbing.
class _ClosedBillsList extends StatefulWidget {
  final RestClient rest;
  final _ClosedBillFilter filter;
  final int pageSize;
  final String emptyCaption;

  /// Whose permissions decide whether a settled bill may be MOVED to another
  /// till (migration 038). Optional: a surface with no profile to hand shows the
  /// bill exactly as it always did, read-only.
  final Profile? profile;

  const _ClosedBillsList({
    required this.rest,
    required this.filter,
    required this.emptyCaption,
    this.profile,
    this.pageSize = 15,
  });

  @override
  State<_ClosedBillsList> createState() => _ClosedBillsListState();
}

// CachePrimedScreen here is for the boot-time prime and the request-generation
// guard; the staleness pill stays with the parent Accounting screen (this list
// is embedded mid-scroll, and it primes from the same store in the same boot).
class _ClosedBillsListState extends State<_ClosedBillsList> with CachePrimedScreen {
  final List<Map> _rows = [];
  bool _loading = true;
  bool _hasMore = false;
  String? _error;
  int _total = 0;

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: () => _fetchPage(offset: 0),
      apply: (res) { _applyPage(res, append: false); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  @override
  void didUpdateWidget(covariant _ClosedBillsList old) {
    super.didUpdateWidget(old);
    final was = old.filter.query(limit: old.pageSize, offset: 0);
    final now = widget.filter.query(limit: widget.pageSize, offset: 0);
    // _load bumps the generation, which also strands a boot prime or an older
    // filter's page still in flight — the guard that keeps a slow stale
    // response from painting over the newer filter's rows.
    if (was != now) _load();
  }

  Future<Map<String, dynamic>> _fetchPage({required int offset}) =>
      widget.rest.getMap('/bills/closed?${widget.filter.query(limit: widget.pageSize, offset: offset)}');

  void _applyPage(Map<String, dynamic> res, {required bool append}) {
    final page = ((res['bills'] as List?) ?? const []).map((e) => e as Map).toList();
    if (!append) _rows.clear();
    _rows.addAll(page);
    _total = _int(res['total']) ?? _rows.length;
    _hasMore = res['has_more'] == true;
  }

  Future<void> _load({bool append = false, bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) {
      setState(() {
        _loading = true;
        if (!append) _error = null;
      });
    }
    final offset = append ? _rows.length : 0;
    try {
      final res = await _fetchPage(offset: offset);
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _applyPage(res, append: append);
        _loading = false;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      // A failed silent refresh with rows on screen keeps them (the build
      // already prefers rows over the error state when both exist).
      setState(() {
        if (silent && _rows.isNotEmpty) {
          markCacheOffline();
        } else {
          _error = '$e';
        }
        _loading = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    if (_loading && _rows.isEmpty) {
      return Column(children: [
        for (var i = 0; i < 3; i++)
          const Padding(
            padding: EdgeInsets.only(bottom: 8),
            child: SkeletonBox(height: 60, radius: AppRadius.card),
          ),
      ]);
    }
    if (_error != null && _rows.isEmpty) {
      return EmptyState(
        icon: Icons.error_outline,
        title: "Couldn't load settled bills",
        caption: _error!,
        action: ForkButton(label: 'Retry', icon: Icons.refresh, dense: true, onPressed: _load),
      );
    }
    if (_rows.isEmpty) {
      return EmptyState(
        icon: Icons.receipt_long_outlined,
        title: 'No settled bills',
        caption: widget.emptyCaption,
      );
    }
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      for (final b in _rows)
        _closedBillRow(context, widget.rest, b, widget.profile, (saved) {
          if (!mounted) return;
          // From the row: the server's answer repaints this row in place. From
          // the sheet: re-read the page quietly, keeping what is on screen.
          if (saved == null) {
            _load(silent: true);
          } else {
            setState(() => b.addAll(saved));
          }
        }),
      if (_hasMore)
        Padding(
          padding: const EdgeInsets.only(top: 4),
          child: Center(
            child: ForkButton.ghost(
              label: _loading ? 'Loading…' : 'Load more (${_rows.length} of $_total)',
              icon: Icons.expand_more,
              dense: true,
              onPressed: _loading ? null : () => _load(append: true),
            ),
          ),
        )
      else if (_total > 0)
        Padding(
          padding: const EdgeInsets.only(top: 4),
          child: Center(child: Text('All $_total shown', style: text.bodySmall)),
        ),
    ]);
  }
}

/// REPRINT A SETTLED BILL — E5, and the control this app was missing.
///
/// The web dashboard has had this on its accounting screen since V3 shipped;
/// this app read closed bills and could not reprint one. So the same person
/// looking at the same bill had a button on a laptop and no button on the till,
/// which reads as a broken till rather than as a decision anybody made.
///
/// THE SERVER DOES THE WORK, INCLUDING SAYING "REPRINT". POST /print/bill/settled
/// re-renders the receipt from the stored bill and stamps `** REPRINT **` at the
/// top itself (escpos.ts). Nothing here composes a receipt, because a second
/// renderer is how two copies of one bill end up disagreeing about the total.
///
/// FAILURES ARE THE SERVER'S SENTENCE, VERBATIM. ApiException carries `details`
/// precisely for this — who may reprint, why a bill cannot be. Rewriting it here
/// would put a worse sentence in front of the person who has to act on it.
/// Who may reprint a settled bill — null (a read-only surface) never may. Named
/// so round 2's "Edit name / GSTIN" on the same bill asks the same question
/// rather than a copy of it; see [_maySetSettledBillCustomer].
bool _mayReprintSettledBill(Profile? p) => p != null && _holdsAction(p, _analyticsPermissionId);

class _ReprintSettledBillButton extends StatefulWidget {
  final RestClient rest;
  final String billId;

  /// Null on a read-only surface (the Reports drill-down), where no write
  /// control belongs at all.
  final Profile? profile;

  const _ReprintSettledBillButton({
    required this.rest,
    required this.billId,
    this.profile,
  });

  @override
  State<_ReprintSettledBillButton> createState() => _ReprintSettledBillButtonState();
}

class _ReprintSettledBillButtonState extends State<_ReprintSettledBillButton> {
  bool _sending = false;

  Future<void> _send() async {
    // Captured BEFORE the await: reading it off `context` afterwards is the
    // use-after-dispose this sheet can actually hit, because a reprint is
    // exactly the moment somebody swipes the sheet away.
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _sending = true);
    try {
      final res = await widget.rest.post('/print/bill/settled', {'bill_id': widget.billId});
      // `destination` is additive and null on an unrouted outlet, so the
      // message degrades to the general one rather than saying "Printing at ".
      final dest = res is Map ? '${res['destination'] ?? ''}'.trim() : '';
      if (!mounted) return;
      messenger.showSnackBar(SnackBar(
        content: Text(dest.isEmpty ? 'Reprint sent to the printer.' : 'Reprinting at $dest.'),
      ));
    } catch (e) {
      if (!mounted) return;
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      // Guarded: the finally runs even when the widget went away mid-flight.
      if (mounted) setState(() => _sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    // A UI convenience only — /print/bill/settled re-checks ACCOUNTING_PERM
    // itself, so a wrong answer here costs an affordance, never a boundary.
    if (!_mayReprintSettledBill(widget.profile)) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(top: AppSpacing.lg),
      child: OutlinedButton.icon(
        onPressed: _sending ? null : _send,
        icon: const Icon(Icons.print_outlined, size: 18),
        label: Text(_sending ? 'Sending…' : 'Reprint bill'),
      ),
    );
  }
}

/// Full detail of one settled bill: every line item, the money breakdown, the
/// payment (and its split parts), and who handled it when.
class _ClosedBillSheet extends StatelessWidget {
  final RestClient rest;
  final String billId;
  final String title;

  /// Present only where a till correction belongs — see [misBillCounterAction].
  final Profile? profile;

  /// Told when the name / GSTIN on this bill changed, so the list behind the
  /// sheet repaints its row too.
  final VoidCallback? onChanged;

  const _ClosedBillSheet({
    required this.rest,
    required this.billId,
    required this.title,
    this.profile,
    this.onChanged,
  });

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: ConstrainedBox(
        constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(context).height * 0.9),
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
          child: AsyncView<Map<String, dynamic>>(
            load: () => rest.getMap('/bills/closed/$billId'),
            builder: (context, bill, reload) => SingleChildScrollView(
              child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                _closedBillBody(context, bill, title),
                // OUTSIDE `_closedBillBody`, and that is the whole point: the
                // same body is what a Reports drill-down renders, and the
                // reports pack must stay read-only. A control added in there
                // would put a write inside a fraud-control document.
                //
                // The reprint joins them here for the same reason: it puts
                // paper in somebody's hand, which is a write in every sense that
                // matters to an auditor reading the pack.
                if (profile != null) ...[
                  _ReprintSettledBillButton(
                    rest: rest,
                    billId: billId,
                    profile: profile,
                  ),
                  // ROUND 2 ITEM 1 — beside the reprint, behind the same gate:
                  // correct who the bill was for, then reprint it.
                  _EditSettledBillCustomerButton(
                    key: const ValueKey('closed-bill-edit-customer'),
                    rest: rest,
                    bill: {...bill, 'id': billId},
                    profile: profile,
                    onSaved: (_) {
                      reload();
                      onChanged?.call();
                    },
                  ),
                  misBillCounterAction(
                    context,
                    rest: rest,
                    profile: profile!,
                    billId: billId,
                    onChanged: reload,
                  ),
                ],
              ]),
            ),
          ),
        ),
      ),
    );
  }
}

/// [reportWords] is for the Reports drill-down (`_misOpenBill`): the row it opens
/// from calls these figures Item total, Net and Gross (client item 1), so the
/// ladder here says the same — as the web's MIS drill-down does. History and the
/// settled-bill browser keep the receipt's words ("Items subtotal", "Taxable
/// base", "Grand total"), because there the thing being read IS the receipt.
/// Only the words change; every figure is the same key either way.
Widget _closedBillBody(BuildContext context, Map bill, String fallbackTitle, {bool reportWords = false}) {
  final text = Theme.of(context).textTheme;
  final items = ((bill['items'] as List?) ?? const []).map((e) => e as Map).toList();
  // `taxes[]` carries the per-rate lines ONLY — the service charge has its own
  // field and gets its own row below, never a line in here.
  final taxes = ((bill['taxes'] as List?) ?? const []).map((e) => e as Map).toList();
  final splits = ((bill['payment_splits'] as List?) ?? const []).map((e) => e as Map).toList();
  final orders = ((bill['orders'] as List?) ?? const []).map((e) => e as Map).toList();

  final taxable = _numOf(bill['taxable_base']);
  final service = _numOf(bill['service_charge']);
  final taxTotal = _numOf(bill['tax_total']);
  final grand = _numOf(bill['grand_total']);
  final discount = _numOf(bill['discount_amount']);
  final subtotal = _numOf(bill['items_subtotal']);
  final refunded = bill['refunded'] == true;
  final servicePct = _numOf(bill['service_charge_percent']);
  final coupon = _s(bill, 'coupon_code', '');
  final method = _s(bill, 'payment_method', '');
  // The NC marker is not a mode and has one name everywhere (migration 052).
  final methodShown = NcSettle.isMethod(method) ? kNcSettleLabel : method;
  final ncSettled = NcSettle.settlement(bill);
  final covers = _int(bill['covers']);
  // What rounded the settled total to the rupee (backend migration 048), as
  // recorded at settle. Null on a bill that needed none or was settled before
  // rounding existed.
  final roundOff = billRoundOff(bill['round_off']);
  // The contract's invariant, shown rather than trusted — with the round-off as
  // its fourth rung, or every rounded bill would read as not adding up.
  final balances = (taxable + service + taxTotal + (roundOff ?? 0) - grand).abs() < 0.05;

  Widget rule() => Container(height: 1, color: AppColors.divider);
  Widget money(String label, String value, {String? sub, bool strong = false, Color? tint}) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 6),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(label,
                  style: strong ? text.titleSmall : text.bodyMedium,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis),
              if (sub != null) ...[
                const SizedBox(height: 2),
                Text(sub, style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
              ],
            ]),
          ),
          const SizedBox(width: AppSpacing.md),
          Text(value,
              style: strong
                  ? text.displaySmall!.copyWith(fontSize: 20, color: tint ?? AppColors.textPrimary)
                  : text.titleSmall!.copyWith(color: tint)),
        ]),
      );

  Widget card(String heading, List<Widget> children, {Widget? trailing}) => Padding(
        padding: const EdgeInsets.only(bottom: AppSpacing.md),
        child: ForkCard(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            SectionHeader(title: heading, padding: const EdgeInsets.only(bottom: 6), trailing: trailing),
            ...children,
          ]),
        ),
      );

  String who(String key) => _s(bill, key, '');
  Widget? handled(String label, String byKey, String atKey) {
    final by = who(byKey);
    final at = _s(bill, atKey, '');
    if (by.isEmpty && at.isEmpty) return null;
    final when = at.isEmpty ? '' : _fmtTime(at);
    return _kv(label, by.isEmpty ? when : (when.isEmpty ? by : '$by · $when'));
  }

  final trail = <Widget>[
    ?handled('Opened', 'created_by', 'created_at'),
    if (_s(bill, 'seated_at', '').isNotEmpty) _kv('Seated', _fmtTime(_s(bill, 'seated_at'))),
    ?handled('Waiter confirmed', 'waiter_confirmed_by', 'waiter_confirmed_at'),
    ?handled('Admin approved', 'admin_approved_by', 'admin_approved_at'),
    ?handled('Closed', 'closed_by', 'closed_at'),
    if (_s(bill, 'settled_at', '').isNotEmpty) _kv('Settled', _fmtTime(_s(bill, 'settled_at'))),
    if (_s(bill, 'discount_applied_at', '').isNotEmpty)
      _kv('Discount applied', _fmtTime(_s(bill, 'discount_applied_at'))),
    if (_s(bill, 'left_at', '').isNotEmpty) _kv('Table released', _fmtTime(_s(bill, 'left_at'))),
    ?handled('Refunded', 'refunded_by', 'refunded_at'),
  ];

  return Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
    Row(children: [
      Expanded(
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('SETTLED BILL', style: text.labelSmall),
          const SizedBox(height: 4),
          Text(_s(bill, 'bill_no', '').isEmpty ? fallbackTitle : _billTitle(bill),
              style: text.headlineMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
        ]),
      ),
      if (refunded)
        StatusChip(label: 'Refunded ${_money(bill['refund_amount'])}', color: AppColors.danger)
      else
        StatusChip(label: method.isEmpty ? 'Closed' : methodShown, color: AppColors.success),
    ]),
    // ROUND 2 ITEM 1 — `Name:` and `Customer GSTIN:` directly under the header
    // and above the date, the slot the printed bill carries them in, worded as
    // the paper words them (a walk-in's slot is a bare `Name:`, as on the
    // paper). They replace the bare name chip.
    for (final l in billCustomerLines(bill)) ...[
      const SizedBox(height: 4),
      Text(l, style: text.bodyMedium),
    ],
    const SizedBox(height: 10),
    Wrap(spacing: 6, runSpacing: 6, children: [
      if (_billWhen(bill).isNotEmpty) InfoChip(icon: Icons.schedule, label: _fmtTime(_billWhen(bill))),
      if (covers != null && covers > 0) InfoChip(icon: Icons.people_outline, label: '$covers covers'),
      if (_numOf(bill['apc']) > 0) InfoChip(icon: Icons.equalizer, label: 'APC ${_money(bill['apc'])}'),
      if (_s(bill, 'payment_proof_screenshot_url', '').isNotEmpty)
        const InfoChip(icon: Icons.image_outlined, label: 'Payment proof attached'),
    ]),
    const SizedBox(height: AppSpacing.lg),
    if (items.isNotEmpty)
      card('Items', [
        for (var i = 0; i < items.length; i++) ...[
          if (i > 0) rule(),
          money(
            // A comped line is its own line at 0.00 — the paper's words.
            NcSettle.lineLabel(_s(items[i], 'name', 'Item'), items[i]['nc']),
            _money(items[i]['line_total'] ?? (_numOf(items[i]['price']) * (_int(items[i]['quantity']) ?? 1))),
            sub: '${_int(items[i]['quantity']) ?? 1} × ${_money(items[i]['price'])}'
                '${_s(items[i], 'note', '').isEmpty ? '' : ' · ${_s(items[i], 'note')}'}',
          ),
        ],
      ]),
    card('Money', [
      if (subtotal > 0) money(reportWords ? kItemTotal : 'Items subtotal', _money(subtotal)),
      if (discount > 0)
        money('Discount', '− ${_money(discount)}',
            sub: coupon.isEmpty
                ? _s(bill, 'discount_type', 'Manual')
                : 'Coupon $coupon · ${_s(bill, 'discount_type', 'coupon')}',
            tint: AppColors.success),
      rule(),
      money(reportWords ? kNet : 'Taxable base', _money(taxable)),
      if (service != 0)
        money('Service charge', _money(service),
            sub: servicePct > 0
                ? '${servicePct.toStringAsFixed(servicePct % 1 == 0 ? 0 : 2)}% of ${reportWords ? 'net' : 'the taxable base'}'
                : null),
      // Taxes are listed rate by rate. The service charge above is deliberately
      // NOT one of them.
      for (final t in taxes)
        money('${_s(t, 'name', 'Tax')} ${_numOf(t['percentage'])}%', _money(t['amount'])),
      if (taxes.isNotEmpty || taxTotal != 0) money('Tax total', _money(taxTotal)),
      if (roundOff != null) money('Round off', billRoundOffMoney(roundOff)),
      rule(),
      money(reportWords ? kGross : 'Grand total', _money(grand), strong: true, tint: AppColors.copperHi),
      // Beside the ladder, never in it: what the comped lines were worth.
      if (_numOf(bill['nc_total']) > 0) money('NC value (not charged)', _money(bill['nc_total'])),
      const SizedBox(height: 6),
      Row(children: [
        Icon(balances ? Icons.check_circle_outline : Icons.error_outline,
            size: 13, color: balances ? AppColors.success : AppColors.danger),
        const SizedBox(width: 6),
        Expanded(
          child: Text(
            '${_money(taxable)} ${reportWords ? 'net' : 'base'} + ${_money(service)} service + ${_money(taxTotal)} tax'
            '${roundOff == null ? '' : ' ${roundOff < 0 ? '−' : '+'} ${_money(roundOff.abs())} round off'} = ${_money(grand)}',
            style: text.bodySmall!.copyWith(color: balances ? AppColors.textTertiary : AppColors.danger),
          ),
        ),
      ]),
    ]),
    card('Payment', [
      money(method.isEmpty ? 'Method not recorded' : methodShown, _money(grand)),
      // A BILL SETTLED AS NC says why it took nothing, and on whose say-so.
      if (ncSettled != null) ...[
        rule(),
        money(
          'Settled as non-chargeable',
          _money(ncSettled.value),
          sub: '${ncSettled.kind.isEmpty ? '' : '${ncSettled.kind} · '}authorised by ${ncSettled.authorisedBy}'
              '${ncSettled.reason.isEmpty ? '' : ' · ${ncSettled.reason}'} · given away, before tax',
          tint: AppColors.warning,
        ),
        if ((ncSettled.wouldHaveCharged ?? 0) > 0)
          money('Would have been (incl. tax)', _money(ncSettled.wouldHaveCharged),
              sub: 'Information only — in no report'),
      ],
      // Split payments: each part is its own tender, so they are named
      // individually rather than collapsed into the headline method.
      for (final sp in splits) ...[
        rule(),
        money(
          _s(sp, 'method', _s(sp, 'payment_method', 'Split part')),
          _money(sp['amount'] ?? sp['value']),
          sub: _s(sp, 'reference', '').isEmpty ? 'Split part' : 'Ref ${_s(sp, 'reference')}',
        ),
      ],
      if (refunded) ...[
        rule(),
        money('Refunded', '− ${_money(bill['refund_amount'])}',
            sub: _s(bill, 'refund_reason', '').isEmpty
                ? _s(bill, 'refund_ref', 'No reason recorded')
                : _s(bill, 'refund_reason'),
            tint: AppColors.danger),
      ],
    ]),
    if (orders.isNotEmpty)
      card('Orders on this bill', [
        for (var i = 0; i < orders.length; i++) ...[
          if (i > 0) rule(),
          money(
            '${_s(orders[i], 'status', 'Order')} · ${_int(orders[i]['item_count']) ?? 0} items',
            _money(orders[i]['subtotal']),
            sub: _fmtTime(_s(orders[i], 'created_at', '')),
          ),
        ],
      ]),
    if (trail.isNotEmpty) card('Handled by', trail),
  ]);
}

// --- Attendance / working hours ---------------------------------------------
// --- Waitlist / queue (staff) ----------------------------------------------
Widget waitlistModule(RestClient rest, Profile p) => _WaitlistView(rest: rest, profile: p);

class _WaitlistView extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  const _WaitlistView({required this.rest, required this.profile});
  @override
  State<_WaitlistView> createState() => _WaitlistViewState();
}

class _WaitlistViewState extends State<_WaitlistView> with CachePrimedScreen {
  bool _loading = true;
  // Set by the first payload to land (cached or live). Tracked separately from
  // _entries because an empty queue is a legitimate payload, not "no data".
  bool _hasData = false;
  String? _error;
  List _entries = const [];
  // Parties already SEATED whose held pre-order still needs a yes/no. Seating no
  // longer places it (backend contract), so without this list an un-answered
  // pre-order would only ever be visible in the seat response — gone on the next
  // refresh, or invisible to the colleague on the other terminal.
  List _pendingPreorders = const [];
  List<String> _freeTables = const [];
  String? _busyId;
  Timer? _poll;

  /// 0 = Queue (everyone), 1 = Walk-ins (called, awaiting a table),
  /// 2 = Reservations (a pointer to Bookings — this endpoint holds walk-ins only).
  int _tab = 0;

  /// The table lists [_previewRows] until the footer link asks for the rest, so
  /// a forty-party Saturday does not push the rail off the bottom of the page.
  bool _showAll = false;
  static const int _previewRows = 8;

  /// Below this the right rail stacks under the main column instead of beside it.
  static const double _twoColumnMin = 1000;
  static const double _railWidth = 320;

  /// GAIA only. Which party the coverflow has at the front. Inert under Rustic
  /// Fork, which opens on the QR hero and has no notion of a focused party.
  int _flowIndex = 0;

  // The queue table. Fixed cells are multiplied by the system text scale so a
  // 1.3x label still fits its own box; the two free-text columns flex, which is
  // what keeps the row from ever overflowing.
  static const List<String> _cols = [
    'Position', 'Party', 'Name', 'Phone', 'People', 'Wait Time', 'Status', 'Actions',
  ];
  static const List<int> _colFlex = [0, 0, 3, 3, 0, 0, 0, 0];
  static const List<double> _colWidth = [56, 42, 0, 0, 60, 74, 100, 56];
  static const double _colGap = 8;
  static const double _fixedCols = 56 + 42 + 60 + 74 + 100 + 56;

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: _fetch,
      apply: (d) { _apply(d); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
    _poll = Timer.periodic(const Duration(seconds: 10), (_) => _load(silent: true));
  }

  @override
  void dispose() {
    _poll?.cancel();
    super.dispose();
  }

  /// The GETs this board is made of, with no side effects — replayable against
  /// the persisted cache at boot (see [CachePrimedScreen]) and the network path
  /// of every [_load].
  Future<({List entries, List pending, List tables})> _fetch() async {
    final w = await widget.rest.getMap('/waitlist');
    List tables = const [];
    try { tables = await widget.rest.getList('/get-tables'); } catch (_) {}
    // Best-effort: an older backend without the route must not blank the queue.
    Map<String, dynamic> pending = const <String, dynamic>{};
    try { pending = await widget.rest.getMap('/waitlist/pending-preorders'); } catch (_) {}
    return (
      entries: (w['entries'] as List?) ?? const [],
      pending: (pending['entries'] as List?) ?? const [],
      tables: tables,
    );
  }

  /// Field assignment only — called inside setState by both the cache prime
  /// and the network load, so the two paths cannot drift.
  void _apply(({List entries, List pending, List tables}) d) {
    _entries = d.entries;
    _pendingPreorders = d.pending;
    _freeTables = [
      for (final t in d.tables)
        if (!((t as Map)['occupied'] == true || t['booked'] == true || t['reserved'] == true)) _s(t, 'table_name'),
    ].where((s) => s.isNotEmpty && s != '—').toList();
    _hasData = true;
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) setState(() { _loading = true; _error = null; });
    try {
      final d = await _fetch();
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _apply(d);
        _loading = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      // With a queue already on screen (saved or live), a failed refresh keeps
      // it up behind the offline pill — a 10s-poll board that swapped itself
      // for an error page on one dropped request would be unusable at the door.
      if (_hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() { _error = '$e'; _loading = false; });
    }
  }

  Future<void> _act(String id, Future<dynamic> Function() fn, {String? ok}) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busyId = id);
    try {
      await fn();
      if (ok != null) messenger.showSnackBar(SnackBar(content: Text(ok)));
      await _load(silent: true);
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busyId = null);
    }
  }

  Future<void> _seat(Map e) async {
    final messenger = ScaffoldMessenger.of(context);
    // Captured before the table-picker dialog and the seat round-trip, for the
    // same reason as the tables sheet: no BuildContext across an async gap.
    final unattendedColour = Theme.of(context).colorScheme.error;
    if (_freeTables.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('No free tables — free one first.')));
      return;
    }
    String? pick = _freeTables.first;
    final chosen = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setLocal) => AlertDialog(
        title: Text('Seat ${e['name']} (party of ${e['party_size']})'),
        content: DropdownButtonFormField<String>(
          initialValue: pick,
          isExpanded: true,
          decoration: const InputDecoration(labelText: 'Table', border: OutlineInputBorder()),
          items: [for (final t in _freeTables) DropdownMenuItem(value: t, child: Text(t))],
          onChanged: (x) => setLocal(() => pick = x),
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, pick), child: const Text('Seat')),
        ],
      )),
    );
    if (chosen == null) return;
    // Seating never places the held pre-order any more — the server hands it back
    // as `pending_preorder` and someone must answer for it. Ask right here, while
    // the party is still standing in front of the host.
    Map? held;
    await _act('${e['id']}', () async {
      final r = await widget.rest.post('/waitlist/${e['id']}/seat', {'table_name': chosen});
      held = r is Map ? r['pending_preorder'] as Map? : null;
      // WHO is serving this table, said in the same breath as "seated". The host
      // is standing with the party right now, which is the cheapest moment there
      // will ever be to fix a table that came out of seating with no waiter.
      final assignment = TableAssignmentOutcome.parse(r is Map ? r['assignment'] : null);
      messenger.showSnackBar(SnackBar(
        content: Text('Seated at $chosen'
            '${held == null ? '' : ' · confirm their pre-order'}'
            '${assignment == null ? '' : ' · ${assignment.message}'}'),
        backgroundColor: assignment != null && assignment.leftTableUnattended
            ? unattendedColour
            : null,
      ));
    });
    final pre = held;
    if (pre == null || !mounted) return;
    await _resolvePreorder(
      id: '${e['id']}',
      partyName: _s(e, 'name'),
      tableName: chosen,
      items: (pre['items'] as List?)?.whereType<Map>().toList() ?? const <Map>[],
      subtotal: _numOf(pre['subtotal']),
    );
  }

  /// Ask, then act on a party's held pre-order.
  ///
  /// Confirm places it as a real order on the table; decline leaves the items on
  /// the queue entry so the guest can change them from their own page. Dismissing
  /// the dialog decides nothing — the pre-order stays `pending` and keeps showing
  /// in the "Pre-orders to confirm" list above the queue.
  Future<void> _resolvePreorder({
    required String id,
    required String partyName,
    required String tableName,
    required List<Map> items,
    required double subtotal,
  }) async {
    final choice = await showDialog<String>(
      context: context,
      builder: (ctx) => _PreorderConfirmDialog(
        partyName: partyName,
        tableName: tableName,
        items: items,
        subtotal: subtotal,
      ),
    );
    if (choice == null || !mounted) return;
    if (choice == 'confirm') {
      await _act(id, () => widget.rest.post('/waitlist/$id/preorder/confirm'),
          ok: 'Pre-order sent to the kitchen for $tableName');
    } else {
      await _act(id, () => widget.rest.post('/waitlist/$id/preorder/decline'),
          ok: '$partyName can change their pre-order before it is placed');
    }
  }

  // "Pre-orders to confirm": seated parties whose held items are still waiting on
  // a yes/no. Survives a refresh and a dismissed dialog, and is visible to every
  // terminal — the queue list itself only holds parties who are still waiting.
  List<Widget> _pendingPreorderSection() {
    if (_pendingPreorders.isEmpty) return const [];
    return [
      SectionHeader(title: 'Pre-orders to confirm', count: _pendingPreorders.length),
      for (final raw in _pendingPreorders) _pendingCard(raw as Map),
      const SizedBox(height: AppSpacing.xl),
    ];
  }

  Widget _pendingCard(Map e) {
    final text = Theme.of(context).textTheme;
    final id = '${e['id']}';
    final items = (e['pre_order'] as List?)?.whereType<Map>().toList() ?? const <Map>[];
    // The held lines carry the price they were picked at; the server re-prices on
    // confirm, so this is an indication, not the final bill.
    final subtotal = items.fold<double>(0, (s, it) {
      final q = _int(it['quantity']) ?? 1;
      return s + _numOf(it['price']) * (q <= 0 ? 1 : q);
    });
    final table = _s(e, 'table_name', '');
    final busy = _busyId == id;
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: ForkCard(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Container(
              width: 40,
              height: 40,
              decoration: BoxDecoration(
                color: AppColors.tint(AppColors.copper),
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: AppColors.edge(AppColors.copper)),
              ),
              child: Icon(Icons.restaurant_menu, size: 18, color: AppColors.copperHi),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(
              child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(_s(e, 'name'), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                    const SizedBox(height: 6),
                    Wrap(spacing: 6, runSpacing: 6, children: [
                      if (table.isNotEmpty && table != '—')
                        InfoChip(icon: Icons.table_restaurant_outlined, label: table),
                      InfoChip(icon: Icons.restaurant_menu, label: '${items.length}-item pre-order'),
                      if (_s(e, 'phone', '').isNotEmpty)
                        InfoChip(icon: Icons.phone_outlined, label: _s(e, 'phone', '')),
                      if (subtotal > 0) InfoChip(icon: Icons.payments_outlined, label: _money(subtotal)),
                    ]),
                  ]),
            ),
            const SizedBox(width: AppSpacing.md),
            MicroStat(value: '${e['minutes_since_seated'] ?? 0}m', label: 'seated', alignEnd: true),
          ]),
          const SizedBox(height: AppSpacing.md),
          Row(children: [
            ForkButton(
              label: 'Review pre-order',
              icon: Icons.fact_check_outlined,
              dense: true,
              onPressed: busy
                  ? null
                  : () => _resolvePreorder(
                        id: id,
                        partyName: _s(e, 'name'),
                        tableName: table,
                        items: items,
                        subtotal: subtotal,
                      ),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(
              child: Text('Nothing reaches the kitchen until you confirm.',
                  style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
            ),
          ]),
        ]),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load the waitlist',
        error: '$_error',
        onRetry: _load,
      );
    }
    // A queue notification asked us to focus one party. The queue only holds
    // parties still waiting, so a party that has been seated / removed is simply
    // not here any more — say so instead of showing an unexplained list.
    final focus = _focusOf(context, 'Waitlist');
    final focusId = focus?.idOf(const ['waitlist_id']);
    final focusFound = focusId != null && _entries.any((e) => '${(e as Map)['id']}' == focusId);
    final banner = focus == null
        ? null
        : _focusBanner(
            context,
            found: focusFound,
            message: focusFound
                ? 'Showing the party from your notification.'
                : 'That party has left the queue — it was seated, cancelled or marked a no-show.',
          );
    // The focused party first so it needs no scrolling; otherwise the server's
    // position order stands. Parenthesised for the same reason as Bookings: a
    // bare cascade binds to the whole conditional, so the unfocused branch
    // sorted the STATE list `_entries` in place with an all-equal comparator,
    // and List.sort permutes above 32 entries — position 14 at the head.
    final ordered = focusId == null
        ? _entries
        : ([..._entries]..sort((a, b) {
            final fa = '${(a as Map)['id']}' == focusId ? 0 : 1;
            final fb = '${(b as Map)['id']}' == focusId ? 0 : 1;
            return fa - fb;
          }));

    // A seated party's un-answered pre-order outlives the queue itself, so this
    // section renders whether or not anyone is still waiting.
    final pendingSection = _pendingPreorderSection();
    // Called = notified, on their way to a table. The one real sub-list this
    // endpoint supports: GET /waitlist returns waiting + called and nothing else.
    final called = [for (final e in ordered) if (_s(e as Map, 'status', 'waiting') == 'called') e];

    return cacheStaleOverlay(RefreshIndicator(
      onRefresh: _load,
      child: LayoutBuilder(builder: (context, c) {
        final wide = c.maxWidth >= _twoColumnMin;
        final mainWidth = wide ? c.maxWidth - _railWidth - AppSpacing.xl : c.maxWidth;
        final gaia = Gaia.of(context);
        final main = <Widget>[
          ?banner,
          // GAIA: the COVERFLOW treatment.
          //
          // Rustic opens this screen on the entrance QR, because the queue used
          // to be a thing you set up. The mockup opens it on the PEOPLE — the
          // party at the front, big enough to read across a lobby, with the
          // next two fanned behind. That is the right hero for a host standing
          // at the door at 20:00, so under Gaia the QR steps back into the
          // right-hand rail (where `_joinCard` already lives, unchanged) and
          // the queue takes the top of the page.
          //
          // Everything below this line is untouched: the stat strip, the
          // pending pre-orders, and the full queue TABLE with its per-row
          // actions menu. The flow is the hero; the table is still how you find
          // party number nineteen, and every action is still on it.
          if (gaia) ..._gaiaQueueHero(ordered)
          else _hero(mainWidth),
          const SizedBox(height: AppSpacing.lg),
          _statStrip(ordered, mainWidth),
          const SizedBox(height: AppSpacing.xl),
          ...pendingSection,
          _queuePanel(ordered, called, focusId, mainWidth),
        ];
        final rail = <Widget>[
          _joinCard(),
          const SizedBox(height: AppSpacing.lg),
          _summaryCard(ordered, called),
          const SizedBox(height: AppSpacing.lg),
          _toBeSeatedCard(called),
        ];
        return ListView(padding: AppSpacing.pageNarrow, children: [
          if (wide)
            Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: main)),
              const SizedBox(width: AppSpacing.xl),
              SizedBox(
                width: _railWidth,
                child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: rail),
              ),
            ])
          else ...[
            ...main,
            const SizedBox(height: AppSpacing.xl),
            ...rail,
          ],
          const SizedBox(height: AppSpacing.xl),
          _closingBanner(c.maxWidth),
        ]);
      }),
    ));
  }

  String get _queueUrl => '${AppConfig.orderBaseUrl}/queue/${widget.profile.restaurantUsername}';

  /// The system text scale, floored at 1. Every fixed column in the queue table
  /// is multiplied by it — a box that does not grow with its own label is how
  /// the 1.3x header overflow happened in the first place.
  double get _scale {
    final s = MediaQuery.textScalerOf(context).scale(1);
    return s < 1 ? 1 : s;
  }

  int _guestCount(List entries) {
    var total = 0;
    for (final raw in entries) {
      final n = _int((raw as Map)['party_size']) ?? 1;
      total += n < 1 ? 1 : n;
    }
    return total;
  }

  // color: null = the active accent (AppColors.copper is a getter now, so it
  // cannot be a const default).
  Widget _roundBadge(IconData icon, {Color? color, double size = 34}) {
    final c = color ?? AppColors.copper;
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: AppColors.tint(c),
        border: Border.all(color: AppColors.edge(c)),
      ),
      child: Icon(icon, size: size * 0.48, color: Color.lerp(c, Colors.white, 0.25)),
    );
  }

  // The Party cell. It used to be the same groups icon on every row — 42px of a
  // desktop table carrying no information — while the phone layout showed
  // "2-item pre-order · 2 in party" as chips. So the form factor most hosts
  // actually use was the one that could not tell a party holding a pre-order
  // from a plain one without opening the menu on each of up to 40 rows.
  // The icon now states which it is, and a party bigger than the booking carries
  // its member count, so the column earns its width.
  Widget _partyCell(List<Map> preItems, List<Map> members) {
    final hasPre = preItems.isNotEmpty;
    final badge = _roundBadge(
      hasPre ? Icons.restaurant_menu : Icons.groups_outlined,
      color: hasPre ? AppColors.copperHi : AppColors.copper,
      size: 30,
    );
    final bits = [
      if (hasPre) '${preItems.length}-item pre-order',
      if (members.isNotEmpty) '${members.length} in party',
    ];
    if (bits.isEmpty) {return badge;}
    return Tooltip(
      message: bits.join(' · '),
      waitDuration: const Duration(milliseconds: 250),
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          badge,
          if (members.isNotEmpty)
            Positioned(
              right: -2,
              bottom: -2,
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                decoration: BoxDecoration(
                  color: AppColors.surface,
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: AppColors.edge(AppColors.copper)),
                ),
                child: Text('${members.length}',
                    style: TextStyle(
                        fontSize: 9, fontWeight: FontWeight.w700, color: AppColors.copperHi)),
              ),
            ),
        ],
      ),
    );
  }

  // The entrance "Join the queue" QR — how a walk-in gets INTO the queue when
  // tables are full. The motif is ornament only: it is dropped whole below 620px
  // rather than squeezed in beside the copy it would otherwise crowd.
  /// The GAIA masthead + coverflow that replaces `_hero` under the Gaia design.
  ///
  /// Returns a LIST so the caller can splice it into the existing column
  /// without a nesting change, which keeps the Rustic path byte-identical.
  List<Widget> _gaiaQueueHero(List ordered) {
    final flowIndex = ordered.isEmpty ? 0 : _flowIndex.clamp(0, ordered.length - 1);
    final focused = ordered.isEmpty ? null : ordered[flowIndex] as Map;
    final guests = _guestCount(ordered);
    final free = _freeTables.length;

    String waitOf(Map e) {
      final m = _int(e['minutes_waiting']) ?? 0;
      if (m < 60) return '$m min';
      final h = m ~/ 60;
      return '${h}h ${m % 60}m';
    }

    List<Map> preOf(Map e) =>
        (e['pre_order'] as List?)?.whereType<Map>().toList() ?? const <Map>[];
    List<Map> memOf(Map e) =>
        (e['party_members'] as List?)?.whereType<Map>().toList() ?? const <Map>[];

    return [
      GaiaPageHeader(
        wordmark: widget.profile.restaurantName,
        meta: ordered.isEmpty
            ? 'Queue empty'
            : '${ordered.length} in queue \u00b7 $guests ${guests == 1 ? 'guest' : 'guests'}',
        title: 'The',
        titleEmphasis: 'queue.',
        sub: ordered.isEmpty
            ? '$free ${free == 1 ? 'table' : 'tables'} free'
            : '${(guests / ordered.length).toStringAsFixed(1)} average party '
                '\u00b7 $free ${free == 1 ? 'table' : 'tables'} free',
      ),
      if (ordered.isEmpty)
        // `.cf.dash` — the mockup's own "Nobody yet" placeholder, kept because
        // an empty coverflow would otherwise read as a screen that failed to
        // load rather than a door with no queue behind it.
        GaiaCoverflow(
          itemCount: 1,
          index: 0,
          onIndexChanged: (_) {},
          dashedBuilder: (_) => true,
          itemBuilder: (context, i) => const GaiaCoverflowCard(
            who: 'Next',
            when: 'Nobody yet',
            detail: [
              'The public queue page refreshes itself while it is open, and '
                  'this board polls every ten seconds.',
            ],
            footLeft: '\u2014',
            footRight: 'Empty',
            dim: true,
          ),
        )
      else ...[
        GaiaCoverflow(
          itemCount: ordered.length,
          index: flowIndex,
          onIndexChanged: (i) => setState(() => _flowIndex = i),
          onActivate: (i) {
            final e = ordered[i] as Map;
            _partyDetails(e, preOf(e), memOf(e));
          },
          semanticsBuilder: (i) {
            final e = ordered[i] as Map;
            return '${_s(e, 'name')}, party of ${e['party_size'] ?? 1}, '
                'position ${e['position'] ?? i + 1}, waiting ${waitOf(e)}';
          },
          itemBuilder: (context, i) {
            final e = ordered[i] as Map;
            final called = _s(e, 'status', 'waiting') == 'called';
            final pre = preOf(e);
            return GaiaCoverflowCard(
              who: _s(e, 'name'),
              when: called
                  ? 'Notified \u00b7 on their way'
                  : 'Waiting \u00b7 position ${e['position'] ?? i + 1}',
              whenColor: called ? GaiaColors.amber : null,
              detail: [
                'Party of ${e['party_size'] ?? 1}'
                    '${_s(e, 'phone', '').isEmpty ? '' : ' \u00b7 ${_s(e, 'phone', '')}'}',
                if (pre.isNotEmpty)
                  '${pre.length}-item pre-order held'
                else
                  'Joined from the queue page',
              ],
              footLeft: waitOf(e),
              footRight: called ? 'Seat now' : 'Call',
            );
          },
        ),
        GaiaCoverflowIndex(
          count: ordered.length,
          index: flowIndex,
          onTap: (i) => setState(() => _flowIndex = i),
        ),
        const SizedBox(height: GaiaSpacing.xl),
        if (focused != null)
          Row(children: [
            Expanded(
              child: GaiaButton(
                label: _s(focused, 'status', 'waiting') == 'called'
                    ? 'Party details'
                    : 'Call',
                kind: GaiaButtonKind.ghost,
                dense: true,
                onPressed: _busyId == '${focused['id']}'
                    ? null
                    : () {
                        if (_s(focused, 'status', 'waiting') == 'called') {
                          _partyDetails(focused, preOf(focused), memOf(focused));
                        } else {
                          _act('${focused['id']}',
                              () => widget.rest.post('/waitlist/${focused['id']}/call'),
                              ok: 'Notified ${_s(focused, 'name')}');
                        }
                      },
              ),
            ),
            const SizedBox(width: 12),
            Expanded(
              flex: 2,
              child: GaiaButton(
                label: 'Seat at a table',
                dense: true,
                onPressed:
                    _busyId == '${focused['id']}' ? null : () => _seat(focused),
              ),
            ),
          ]),
      ],
    ];
  }

  Widget _hero(double w) {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Container(
          width: 44,
          height: 44,
          decoration: BoxDecoration(
            color: AppColors.tint(AppColors.copper),
            borderRadius: AppRadius.tileAll,
            border: Border.all(color: AppColors.edge(AppColors.copper)),
          ),
          child: Icon(Icons.qr_code_2, size: 21, color: AppColors.copperHi),
        ),
        const SizedBox(width: AppSpacing.lg),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Entrance “Join the queue” QR', style: text.titleMedium),
            const SizedBox(height: 6),
            Text(
                'Display this at your door. When all tables are full, guests scan it to join this waitlist — and can browse the menu and pre-order while they wait.',
                style: text.bodySmall),
          ]),
        ),
        if (w >= 620) ...[
          const SizedBox(width: AppSpacing.lg),
          const _QueueMotif(),
        ],
      ]),
    );
  }

  /// Four figures, all read off data this screen already holds.
  ///
  /// The reference's "estimated wait" and "tables free in the next 30 min" are
  /// deliberately NOT here: GET /waitlist carries no turn-time and /get-tables no
  /// ETA, so both would have been invented. What IS true is shown instead — how
  /// long the parties in the queue have actually been waiting, and how many
  /// tables are free right now.
  Widget _statStrip(List ordered, double w) {
    final mins = [for (final e in ordered) _int((e as Map)['minutes_waiting']) ?? 0]..sort();
    final guests = _guestCount(ordered);
    final avg = ordered.isEmpty ? 0.0 : guests / ordered.length;
    final s = _scale;
    final cols = w >= 900 * s ? 4 : (w >= 520 * s ? 2 : 1);
    return _dashGrid([
      _statTile(
        figure: '${ordered.length}',
        unit: 'Groups',
        caption: 'Current queue',
        icon: Icons.groups_outlined,
        // The panel below caps the queue at eight rows, so the figure and the
        // list disagree the moment a ninth party joins. The sheet is the whole of
        // it, and unlike a tab switch it is observable however short the queue.
        onTap: ordered.isEmpty ? null : () => _wholeQueue(ordered),
      ),
      _statTile(
        figure: mins.isEmpty ? '0' : (mins.first == mins.last ? '${mins.first}' : '${mins.first}–${mins.last}'),
        unit: 'Min',
        caption: 'Waited so far, shortest to longest',
        icon: Icons.schedule,
        onTap: ordered.isEmpty ? null : () => _longestWaits(ordered),
      ),
      _statTile(
        figure: '${_freeTables.length}',
        unit: 'Free',
        caption: 'Tables ready to seat now',
        icon: Icons.table_restaurant_outlined,
        // Tappable even at zero: "which tables" is the question either way, and
        // the sheet carries the jump to the floor plan that answers it.
        onTap: _freeTablesSheet,
      ),
      _statTile(
        figure: avg == 0 ? '0' : avg.toStringAsFixed(avg % 1 == 0 ? 0 : 1),
        unit: 'People',
        caption: 'Average party size',
        icon: Icons.person_outline,
        onTap: ordered.isEmpty ? null : () => _partySizeSpread(ordered),
      ),
    ], cols);
  }

  Widget _statTile({
    required String figure,
    required String unit,
    required String caption,
    required IconData icon,
    VoidCallback? onTap,
  }) {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
      onTap: onTap,
      child: Row(children: [
        Expanded(
          child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text.rich(
                  TextSpan(text: figure, style: text.displaySmall!.copyWith(fontSize: 22), children: [
                    TextSpan(
                        text: '  $unit',
                        style: text.bodySmall!.copyWith(fontSize: 11, fontWeight: FontWeight.w500)),
                  ]),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                const SizedBox(height: 4),
                Text(caption.toUpperCase(), style: text.labelSmall, maxLines: 2, overflow: TextOverflow.ellipsis),
              ]),
        ),
        const SizedBox(width: AppSpacing.md),
        _roundBadge(icon),
      ]),
    );
  }

  // ---- the tabbed queue panel ----------------------------------------------

  Widget _queuePanel(List ordered, List called, String? focusId, double w) {
    final text = Theme.of(context).textTheme;
    final s = _scale;
    final rows = _tab == 1 ? called : ordered;
    // Below this the eight columns cannot hold a phone number, so the row becomes
    // a stacked record instead of a grid nobody can read. See _entryRow.
    final table = w >= _fixedCols * s + _colGap * (_cols.length - 1) + 220;
    final capped = _showAll || rows.length <= _previewRows ? rows : rows.sublist(0, _previewRows);

    return ForkCard(
      padding: EdgeInsets.zero,
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 14, 16, 12),
          child: Wrap(
            alignment: WrapAlignment.spaceBetween,
            crossAxisAlignment: WrapCrossAlignment.center,
            spacing: AppSpacing.md,
            runSpacing: AppSpacing.sm,
            children: [
              ForkTabs(
                tabs: ['Queue (${ordered.length})', 'Walk-ins', 'Reservations'],
                selected: _tab,
                onSelected: (i) => setState(() {
                  _tab = i;
                  _showAll = false;
                }),
              ),
              Text(_tabCaption(), style: text.bodySmall!.copyWith(fontSize: 11)),
            ],
          ),
        ),
        Divider(height: 1, thickness: 1, color: AppColors.divider),
        if (_tab == 2)
          _reservationsPanel()
        else if (rows.isEmpty)
          _emptyPanel()
        else ...[
          if (table) _headerRow(s),
          for (var i = 0; i < capped.length; i++)
            _entryRow(
              capped[i] as Map,
              table: table,
              s: s,
              focused: focusId != null && '${(capped[i] as Map)['id']}' == focusId,
              last: i == capped.length - 1 && rows.length <= _previewRows,
            ),
          if (rows.length > _previewRows) _viewAllFooter(rows.length),
        ],
      ]),
    );
  }

  String _tabCaption() => switch (_tab) {
        1 => 'Notified — waiting for a table',
        2 => 'Booked ahead, not a walk-in',
        _ => 'Everyone still in the queue',
      };

  Widget _headerRow(double s) => Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 9),
        decoration: BoxDecoration(
          color: AppColors.inset,
          border: Border(bottom: BorderSide(color: AppColors.divider)),
        ),
        child: _tableRow([
          for (var i = 0; i < _cols.length; i++)
            Text(
              _cols[i],
              textAlign: i == _cols.length - 1 ? TextAlign.right : TextAlign.left,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                letterSpacing: 0.3,
                color: AppColors.textTertiary,
              ),
            ),
        ], s),
      );

  /// Header and body share this one spec, which is the only reason the columns
  /// line up. Every cell is either flexible (ellipsises) or a fixed box that
  /// scales with the text — nothing here can push the row past its parent.
  Widget _tableRow(List<Widget> cells, double s) => Row(
        children: [
          for (var i = 0; i < cells.length; i++) ...[
            if (i > 0) const SizedBox(width: _colGap),
            if (_colFlex[i] > 0)
              Expanded(flex: _colFlex[i], child: cells[i])
            else
              SizedBox(width: _colWidth[i] * s, child: cells[i]),
          ],
        ],
      );

  /// The row's own box, plus the tap that opens the party.
  ///
  /// Opening a read-only sheet is the ONLY thing a row tap does. Every action —
  /// call, seat, no-show, remove — stays in the "..." menu, whose button sits
  /// inside this shell and wins the gesture arena as the deeper recognizer, so
  /// reaching for the menu can never fire the row.
  Widget _rowShell({
    required bool focused,
    required bool last,
    required Widget child,
    VoidCallback? onTap,
  }) {
    final shell = Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      decoration: BoxDecoration(
        color: focused ? AppColors.tint(AppColors.copper) : null,
        border: last ? null : Border(bottom: BorderSide(color: AppColors.divider)),
      ),
      child: child,
    );
    return onTap == null ? shell : _TapRow(onTap: onTap, child: shell);
  }

  Widget _entryRow(Map e, {required bool table, required double s, required bool focused, required bool last}) {
    final text = Theme.of(context).textTheme;
    final status = _s(e, 'status', 'waiting');
    final called = status == 'called';
    final phone = _s(e, 'phone', '');
    final preItems = (e['pre_order'] as List?)?.whereType<Map>().toList() ?? const <Map>[];
    final members = (e['party_members'] as List?)?.whereType<Map>().toList() ?? const <Map>[];
    // Status is never colour alone — the chip always ships its label.
    final chip = StatusChip(
      label: called ? 'Notified' : (status == 'waiting' ? 'Waiting' : status),
      color: called
          ? AppColors.warning
          : status == 'waiting'
              ? AppColors.info
              : AppColors.neutral,
      dense: true,
    );

    if (table) {
      return _rowShell(
        focused: focused,
        last: last,
        onTap: () => _partyDetails(e, preItems, members),
        child: _tableRow([
          Align(alignment: Alignment.centerLeft, child: _positionCell(e, called)),
          Align(alignment: Alignment.centerLeft, child: _partyCell(preItems, members)),
          Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text(_s(e, 'name'), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            if (focused)
              Text('From your notification',
                  style: text.bodySmall!.copyWith(fontSize: 10.5, color: AppColors.copperHi),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis),
          ]),
          // Mandatory at join now, so it is always there to call back on — right
          // next to the party size where staff look.
          Text(phone.isEmpty ? '—' : phone, style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
          Text('${e['party_size'] ?? 1}',
              style: text.bodyMedium!.copyWith(color: AppColors.textPrimary),
              maxLines: 1,
              overflow: TextOverflow.ellipsis),
          Text('${e['minutes_waiting'] ?? 0}m',
              style: text.bodyMedium!.copyWith(color: AppColors.textPrimary),
              maxLines: 1,
              overflow: TextOverflow.ellipsis),
          Align(alignment: Alignment.centerLeft, child: chip),
          Align(alignment: Alignment.centerRight, child: _actionsMenu(e, preItems, members)),
        ], s),
      );
    }

    // Phone degradation: eight columns at 390px would give each about 35px — less
    // than a phone number needs — so the row unpacks into a record instead. Every
    // field is still here, at full width, in a Wrap that can only ever drop to a
    // new run.
    return _rowShell(
      focused: focused,
      last: last,
      onTap: () => _partyDetails(e, preItems, members),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          _positionCell(e, called),
          const SizedBox(width: AppSpacing.md),
          Expanded(child: Text(_s(e, 'name'), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis)),
          const SizedBox(width: AppSpacing.sm),
          _actionsMenu(e, preItems, members),
        ]),
        const SizedBox(height: AppSpacing.sm),
        Wrap(spacing: 6, runSpacing: 6, children: [
          if (focused) const InfoChip(icon: Icons.notifications_active, label: 'From your notification'),
          chip,
          InfoChip(icon: Icons.groups_outlined, label: 'Party of ${e['party_size'] ?? 1}'),
          if (phone.isNotEmpty) InfoChip(icon: Icons.phone_outlined, label: phone),
          InfoChip(icon: Icons.schedule, label: '${e['minutes_waiting'] ?? 0}m waited'),
          if (preItems.isNotEmpty)
            InfoChip(icon: Icons.restaurant_menu, label: '${preItems.length}-item pre-order'),
          if (members.isNotEmpty) InfoChip(icon: Icons.person_outline, label: '${members.length} in party'),
        ]),
      ]),
    );
  }

  // Queue position — swaps to the warning bell once the party is called.
  Widget _positionCell(Map e, bool called) {
    final text = Theme.of(context).textTheme;
    return AnimatedSwitcher(
      duration: AppDurations.base,
      switchInCurve: Curves.easeOut,
      switchOutCurve: Curves.easeIn,
      child: called
          ? Container(
              key: const ValueKey('called'),
              width: 40,
              height: 40,
              decoration: BoxDecoration(
                color: AppColors.tint(AppColors.warning),
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: AppColors.edge(AppColors.warning)),
              ),
              child: Icon(Icons.notifications_active, size: 18, color: AppColors.warning),
            )
          : Container(
              key: ValueKey('pos-${e['position']}'),
              width: 40,
              height: 40,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: AppColors.inset,
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: AppColors.border),
              ),
              child: Text('${e['position'] ?? '–'}',
                  maxLines: 1,
                  overflow: TextOverflow.clip,
                  style: text.titleMedium!.copyWith(color: AppColors.copperHi)),
            ),
    );
  }

  /// Every row action, in one menu.
  ///
  /// Order is the safety rule: the harmless work is on top, the two ways to drop
  /// a party from the queue are last and behind a divider, so the item under the
  /// cursor when the menu opens is never destructive. Remove also asks first —
  /// it is the one that takes a guest's place away with no undo.
  Widget _actionsMenu(Map e, List<Map> preItems, List<Map> members) {
    final id = '${e['id']}';
    final busy = _busyId == id;
    final status = _s(e, 'status', 'waiting');
    final name = _s(e, 'name');
    // The trigger is an InkWell, which asserts on a Material ancestor — and a
    // module is mounted straight under the shell, with no Scaffold of its own.
    // Transparent Material: no pixels, just the ink surface the well demands.
    return Material(
      type: MaterialType.transparency,
      child: PopupMenuButton<String>(
        tooltip: 'Actions',
        enabled: !busy,
        position: PopupMenuPosition.under,
        itemBuilder: (_) => [
          if (status == 'waiting') _menuItem('call', Icons.notifications_outlined, 'Call'),
          _menuItem('seat', Icons.event_seat_outlined, 'Seat', color: AppColors.success),
          _menuItem('details', Icons.badge_outlined, 'Party details'),
          const PopupMenuDivider(),
          _menuItem('no_show', Icons.do_not_disturb_on_outlined, 'No-show', color: AppColors.danger),
          _menuItem('remove', Icons.close, 'Remove', color: AppColors.danger),
        ],
        onSelected: (v) {
          switch (v) {
            case 'call':
              _act(id, () => widget.rest.post('/waitlist/$id/call'), ok: 'Notified $name');
            case 'seat':
              _seat(e);
            case 'details':
              _partyDetails(e, preItems, members);
            case 'no_show':
              _act(id, () => widget.rest.post('/waitlist/$id/cancel', {'status': 'no_show'}));
            case 'remove':
              _confirmRemove(e);
          }
        },
        child: Container(
          width: 34,
          height: 34,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            borderRadius: AppRadius.controlAll,
            border: Border.all(color: AppColors.border),
          ),
          child: Icon(Icons.more_horiz,
              size: 18, color: busy ? AppColors.textTertiary : AppColors.textSecondary),
        ),
      ),
    );
  }

  PopupMenuItem<String> _menuItem(String value, IconData icon, String label,
      // Nullable because AppColors.textSecondary is a getter now (the device
      // scheme), and a default must be const — null means "secondary ink".
      {Color? color}) {
    color ??= AppColors.textSecondary;
    final fg = color == AppColors.textSecondary
        ? AppColors.textPrimary
        : Color.lerp(color, Colors.white, 0.25)!;
    return PopupMenuItem<String>(
      value: value,
      child: Row(mainAxisSize: MainAxisSize.min, children: [
        Icon(icon, size: 16, color: color == AppColors.textSecondary ? AppColors.textSecondary : fg),
        const SizedBox(width: 10),
        ChipLabel(label, style: TextStyle(fontSize: 13, fontWeight: FontWeight.w500, color: fg)),
      ]),
    );
  }

  Future<void> _confirmRemove(Map e) async {
    final id = '${e['id']}';
    final name = _s(e, 'name');
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text('Remove $name from the queue?'),
        content: const Text(
            'They lose their place in line. Use No-show instead if they were called and never turned up.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Keep them')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Remove')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    await _act(id, () => widget.rest.post('/waitlist/$id/cancel', {'status': 'cancelled'}),
        ok: '$name removed from the queue');
  }

  /// The pre-order lines and the party members — what the row itself has no
  /// column for. Reached from the row's "..." menu.
  Future<void> _partyDetails(Map e, List<Map> preItems, List<Map> members) {
    final text = Theme.of(context).textTheme;
    final phone = _s(e, 'phone', '');
    return _detailSheet(
      context,
      eyebrow: 'In the queue',
      title: _s(e, 'name'),
      children: [
        _detailRow(context, 'Party size', '${e['party_size'] ?? 1}'),
        _detailRow(context, 'Phone', phone.isEmpty ? '—' : phone),
        _detailRow(context, 'Waiting', '${e['minutes_waiting'] ?? 0}m'),
        _detailRow(context, 'Position', '${e['position'] ?? '–'}'),
        if (preItems.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.md),
          Text('PRE-ORDER', style: text.labelSmall),
          for (final it in preItems)
            _detailRow(
              context,
              '${_s(it, 'name')} ×${_int(it['quantity']) ?? 1}',
              _numOf(it['price']) > 0 ? _money(it['price']) : '—',
              trailing: _s(it, 'note', '').isEmpty ? null : _s(it, 'note', ''),
            ),
        ],
        if (members.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.md),
          Text('PARTY MEMBERS', style: text.labelSmall),
          for (final mm in members) _detailRow(context, _s(mm, 'name'), _s(mm, 'phone', '—')),
        ],
      ],
    );
  }

  /// [_partyDetails] from anywhere holding a raw queue entry — a row, a rail
  /// line, or a line inside one of the drill-down sheets below.
  Future<void> _openParty(Map e) => _partyDetails(
        e,
        (e['pre_order'] as List?)?.whereType<Map>().toList() ?? const <Map>[],
        (e['party_members'] as List?)?.whereType<Map>().toList() ?? const <Map>[],
      );

  /// A sheet whose lines each open a party. The pop comes first so the party
  /// sheet replaces this one instead of stacking a second dialog over it.
  Future<void> _partyListSheet({
    required String eyebrow,
    required String title,
    required List<Map> parties,
    required String Function(Map) valueOf,
    String? Function(Map)? trailingOf,
    List<Widget> lead = const [],
  }) =>
      _detailSheet(
        context,
        eyebrow: eyebrow,
        title: title,
        children: [
          ...lead,
          Builder(
            builder: (ctx) => Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              for (final e in parties)
                _TapRow(
                  onTap: () {
                    Navigator.pop(ctx);
                    _openParty(e);
                  },
                  child: _detailRow(context, _s(e, 'name'), valueOf(e),
                      trailing: trailingOf?.call(e)),
                ),
            ]),
          ),
        ],
      );

  /// Who has actually been standing longest. The panel is ordered by POSITION,
  /// which is arrival order and not the same thing once parties are called and
  /// seated out of turn — so the range on the tile has no ranking behind it
  /// anywhere else on the page.
  Future<void> _longestWaits(List ordered) {
    final by = [...ordered.whereType<Map>()]
      ..sort((a, b) => (_int(b['minutes_waiting']) ?? 0).compareTo(_int(a['minutes_waiting']) ?? 0));
    return _partyListSheet(
      eyebrow: 'Waiting longest first',
      title: 'Who has waited how long',
      parties: by,
      valueOf: (e) => '${e['minutes_waiting'] ?? 0}m',
      trailingOf: (e) => 'position ${e['position'] ?? '–'}',
    );
  }

  /// Every party and its headcount — how the "guests waiting" total is made up.
  /// The whole queue, in order. The tile and the summary row that count it used
  /// to `setState(_tab = 0; _showAll = true)`, which is a no-op whenever the tab
  /// is already Queue and the list already fits inside the eight-row preview —
  /// i.e. for any restaurant with a short queue, tapping the headline figure did
  /// nothing at all. Every other figure on this rail opens a sheet; so does this.
  Future<void> _wholeQueue(List ordered) => _partyListSheet(
        eyebrow: 'In the queue',
        title: '${ordered.length} ${ordered.length == 1 ? 'group' : 'groups'} waiting',
        parties: [...ordered.whereType<Map>()],
        valueOf: (e) => '${e['minutes_waiting'] ?? 0}m',
        trailingOf: (e) => 'waited',
      );

  Future<void> _guestsWaiting(List ordered) => _partyListSheet(
        eyebrow: 'In the queue',
        title: '${_guestCount(ordered)} guests waiting',
        parties: [...ordered.whereType<Map>()],
        valueOf: (e) => '${e['party_size'] ?? 1}',
        trailingOf: (e) => 'people',
      );

  /// How many groups of each size are in the queue. An average of 3.4 says
  /// nothing about whether that is a room full of pairs or one large booking,
  /// which is the difference that decides which table to free next.
  Future<void> _partySizeSpread(List ordered) {
    final counts = <int, int>{};
    for (final raw in ordered) {
      final n = _int((raw as Map)['party_size']) ?? 1;
      final size = n < 1 ? 1 : n;
      counts[size] = (counts[size] ?? 0) + 1;
    }
    final sizes = counts.keys.toList()..sort();
    return _detailSheet(
      context,
      eyebrow: 'In the queue',
      title: 'Party sizes',
      children: [
        for (final size in sizes)
          _detailRow(context, '$size ${size == 1 ? 'person' : 'people'}',
              '${counts[size]}', trailing: counts[size] == 1 ? 'group' : 'groups'),
      ],
    );
  }

  /// WHICH tables are free, not just how many — and the way to the floor plan
  /// when the answer is "none".
  Future<void> _freeTablesSheet() {
    final text = Theme.of(context).textTheme;
    return _detailSheet(
      context,
      eyebrow: 'Right now',
      title: _freeTables.isEmpty
          ? 'No table is free'
          : '${_freeTables.length} table${_freeTables.length == 1 ? '' : 's'} ready',
      jumpTo: 'Tables',
      children: [
        if (_freeTables.isEmpty)
          Text(
              'Every table is occupied, booked or reserved. Free one on the floor '
              'plan and the next party in the queue can be seated.',
              style: text.bodySmall)
        else
          for (final t in _freeTables) _detailRow(context, t, 'Free'),
      ],
    );
  }

  /// The held lines behind the "pre-orders to confirm" count. The cards above
  /// the queue show only how MANY items each party is holding; this is what
  /// they actually picked, which is what the yes/no is about.
  Future<void> _heldPreorders() {
    final text = Theme.of(context).textTheme;
    return _detailSheet(
      context,
      eyebrow: 'Waiting on a yes or no',
      title: 'Held pre-orders',
      children: [
        for (final raw in _pendingPreorders.whereType<Map>()) ...[
          Text(
            [_s(raw, 'name'), if (_s(raw, 'table_name', '').isNotEmpty) _s(raw, 'table_name', '')]
                .join(' · '),
            style: text.titleSmall,
          ),
          for (final it in (raw['pre_order'] as List?)?.whereType<Map>() ?? const <Map>[])
            _detailRow(context, '${_s(it, 'name')} ×${_int(it['quantity']) ?? 1}',
                _numOf(it['price']) > 0 ? _money(it['price']) : '—'),
          const SizedBox(height: AppSpacing.md),
        ],
      ],
    );
  }

  Widget _emptyPanel() => EmptyState(
        icon: Icons.hourglass_empty,
        title: _tab == 1 ? 'Nobody waiting for a table' : 'Queue is empty',
        caption: _tab == 1
            ? 'Parties you call appear here until you seat them.'
            : 'Walk-ins who scan the entrance QR appear here in arrival order.',
      );

  // Reservations are booked ahead and live in Bookings — this endpoint holds
  // walk-ins only. The jump is hidden outright when Bookings is not reachable for
  // this user, and carries no target: only keys the destination reads may travel.
  Widget _reservationsPanel() {
    final nav = ModuleNavigator.of(context);
    final canOpen = nav?.canOpen('Bookings') ?? false;
    return EmptyState(
      icon: Icons.event_available_outlined,
      title: 'Reservations are booked ahead',
      caption: 'This queue holds walk-ins. Tables booked in advance have their own arrival times.',
      action: canOpen
          ? ForkButton(
              label: 'Open Bookings',
              icon: Icons.arrow_forward,
              dense: true,
              onPressed: () => nav!.openModule('Bookings'),
            )
          : null,
    );
  }

  Widget _viewAllFooter(int total) => Padding(
        padding: const EdgeInsets.fromLTRB(16, 10, 16, 12),
        child: Align(
          alignment: Alignment.centerLeft,
          child: ForkButton.subtle(
            label: _showAll ? 'Show fewer' : 'View all waitlist ($total)',
            icon: _showAll ? Icons.expand_less : Icons.arrow_forward,
            onPressed: () => setState(() => _showAll = !_showAll),
          ),
        ),
      );

  // ---- right rail -----------------------------------------------------------

  Widget _joinCard() {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [
          _roundBadge(Icons.qr_code_2, size: 30),
          const SizedBox(width: AppSpacing.md),
          Expanded(child: Text('Join the queue', style: text.titleSmall)),
        ]),
        const SizedBox(height: AppSpacing.lg),
        // Paper exception: the QR keeps its white quiet zone so it stays
        // scannable — printed-output styling, black on white.
        // Tapping the code enlarges it for the door. The card is the artifact;
        // the hero's "Preview guest experience" button opens the live page. Two
        // controls, two outcomes — they used to be the same dialog.
        Center(
          child: _TapRow(
            onTap: _queuePoster,
            child: Container(
              padding: const EdgeInsets.all(8),
              decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(8)),
              child: QrImageView(data: _queueUrl, size: 160, backgroundColor: Colors.white),
            ),
          ),
        ),
        const SizedBox(height: 6),
        Text('Tap the code to enlarge or print it',
            textAlign: TextAlign.center,
            style: text.bodySmall!.copyWith(fontSize: 10.5, color: AppColors.textTertiary)),
        const SizedBox(height: AppSpacing.md),
        Text('Scan to join waitlist', textAlign: TextAlign.center, style: text.titleSmall),
        const SizedBox(height: 2),
        Text('Browse menu & pre-order while you wait',
            textAlign: TextAlign.center, style: text.bodySmall),
        const SizedBox(height: AppSpacing.md),
        ForkCard(
          inset: true,
          padding: const EdgeInsets.fromLTRB(12, 6, 6, 6),
          child: Row(children: [
            // Selectable, not truncated: the whole URL has to be readable off the
            // screen when someone is typing it onto a printed sign.
            Expanded(
              child: SelectableText(_queueUrl, style: text.bodySmall!.copyWith(fontSize: 11)),
            ),
            const SizedBox(width: 6),
            ForkIconButton(icon: Icons.copy, tooltip: 'Copy the join link', onPressed: _copyLink),
          ]),
        ),
      ]),
    );
  }

  Future<void> _copyLink() async {
    final messenger = ScaffoldMessenger.of(context);
    // Claiming "copied" before knowing it worked is a lie a host only discovers
    // when they paste nothing into their WhatsApp. Report the failure instead.
    try {
      await Clipboard.setData(ClipboardData(text: _queueUrl));
      messenger.showSnackBar(const SnackBar(content: Text('Queue link copied')));
    } catch (_) {
      messenger.showSnackBar(const SnackBar(
          content: Text('Could not copy the link — select it and copy manually.')));
    }
  }

  /// Only figures GET /waitlist actually supports. "Served today" and "no-shows
  /// today" are not here on purpose: the endpoint returns waiting + called rows
  /// and nothing else, so both would have been guesses.
  Widget _summaryCard(List ordered, List called) => ForkCard(
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          const SectionHeader(title: 'Queue summary', padding: EdgeInsets.only(bottom: 10)),
          // Each figure drills into the set it counts; a figure counting nothing
          // stays inert rather than offering a tap onto an empty sheet.
          _summaryRow('Total in queue', '${ordered.length}', 'groups',
              onTap: ordered.isEmpty ? null : () => _wholeQueue(ordered)),
          _summaryRow('Guests waiting', '${_guestCount(ordered)}', 'people',
              onTap: ordered.isEmpty ? null : () => _guestsWaiting(ordered)),
          _summaryRow('Notified', '${called.length}', 'groups',
              onTap: called.isEmpty ? null : () => setState(() { _tab = 1; _showAll = false; })),
          _summaryRow('Pre-orders to confirm', '${_pendingPreorders.length}', 'holds',
              onTap: _pendingPreorders.isEmpty ? null : _heldPreorders),
        ]),
      );

  Widget _summaryRow(String label, String figure, String unit, {VoidCallback? onTap}) {
    final text = Theme.of(context).textTheme;
    final row = Padding(
      padding: const EdgeInsets.symmetric(vertical: 6),
      child: Wrap(
        alignment: WrapAlignment.spaceBetween,
        crossAxisAlignment: WrapCrossAlignment.center,
        spacing: AppSpacing.md,
        runSpacing: 2,
        children: [
          Text(label, style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
          Text.rich(
            TextSpan(text: figure, style: text.titleSmall, children: [
              TextSpan(text: ' $unit', style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
            ]),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
        ],
      ),
    );
    return onTap == null ? row : _TapRow(onTap: onTap, child: row);
  }

  Widget _toBeSeatedCard(List called) {
    final text = Theme.of(context).textTheme;
    final shown = called.length > 4 ? called.sublist(0, 4) : called;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        SectionHeader(
          title: 'Walk-ins to be seated',
          count: called.isEmpty ? null : called.length,
          padding: const EdgeInsets.only(bottom: 4),
          trailing: called.isEmpty
              ? null
              : ForkButton.subtle(
                  label: 'View all',
                  onPressed: () => setState(() {
                    _tab = 1;
                    _showAll = false;
                  }),
                ),
        ),
        // Said once, for the whole card: the dot beside each row is decoration on
        // top of this sentence, never the only thing carrying the state.
        Text('Notified — waiting for a table.', style: text.bodySmall!.copyWith(fontSize: 11)),
        const SizedBox(height: AppSpacing.md),
        if (shown.isEmpty)
          Text('Nobody has been called yet. Call a party from the queue and they show up here.',
              style: text.bodySmall)
        else
          for (final raw in shown) _seatSoonRow(raw as Map),
      ]),
    );
  }

  Widget _seatSoonRow(Map e) {
    final text = Theme.of(context).textTheme;
    // The rail line carries a name and a headcount; the party sheet carries the
    // phone to call them back on and whatever they pre-ordered. Read-only, like
    // the queue row — seating still happens from the row's "..." menu.
    return _TapRow(
      onTap: () => _openParty(e),
      child: Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Row(children: [
        InitialsAvatar(initials: _guestInitials(_s(e, 'name', '')), size: 30),
        const SizedBox(width: AppSpacing.md),
        Expanded(
          child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(_s(e, 'name'), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                Text('Party of ${e['party_size'] ?? 1} · ${e['minutes_waiting'] ?? 0}m ago',
                    style: text.bodySmall!.copyWith(fontSize: 11),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis),
              ]),
        ),
        const SizedBox(width: AppSpacing.sm),
        Container(
          width: 8,
          height: 8,
          decoration: BoxDecoration(color: AppColors.warning, shape: BoxShape.circle),
        ),
      ]),
      ),
    );
  }

  // ---- closing banner -------------------------------------------------------

  Widget _closingBanner(double w) {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        _roundBadge(Icons.emoji_emotions_outlined, size: 40),
        const SizedBox(width: AppSpacing.lg),
        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('Keep your guests happy while they wait', style: text.titleMedium),
            const SizedBox(height: 6),
            Text(
                'From the queue page a party can browse your menu, hold a pre-order, and be notified the moment their table is ready.',
                style: text.bodySmall),
            const SizedBox(height: AppSpacing.md),
            Align(
              alignment: Alignment.centerLeft,
              child: ForkButton(
                label: 'Preview guest experience',
                icon: Icons.open_in_new,
                dense: true,
