/// "Send this party's pre-order to the kitchen?" — the ask that seating a queued
/// party now requires.
///
/// The items were picked at the door, possibly a long time before the table came
/// free, so firing them the instant a table is assigned takes the decision away
/// from the guest. Pops `'confirm'` (place it), `'decline'` (leave it for the
/// guest to change) or null — dismissing decides NOTHING and the pre-order stays
/// pending in the "Pre-orders to confirm" list.
class _PreorderConfirmDialog extends StatelessWidget {
  final String partyName;
  final String tableName;
  final List<Map> items;
  final double subtotal;
  const _PreorderConfirmDialog({
    required this.partyName,
    required this.tableName,
    required this.items,
    required this.subtotal,
  });

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final count = items.fold<int>(0, (s, it) {
      final q = _int(it['quantity']) ?? 1;
      return s + (q <= 0 ? 1 : q);
    });
    return AlertDialog(
      title: Text('Send $partyName’s pre-order?'),
      content: SizedBox(
        width: 380,
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Wrap(spacing: 6, runSpacing: 6, children: [
              if (tableName.isNotEmpty && tableName != '—')
                InfoChip(icon: Icons.table_restaurant_outlined, label: tableName),
              InfoChip(icon: Icons.restaurant_menu, label: '$count item${count == 1 ? '' : 's'}'),
            ]),
            const SizedBox(height: AppSpacing.md),
            Text('They picked these while waiting. Nothing has gone to the kitchen yet.',
                style: text.bodySmall),
            const SizedBox(height: AppSpacing.md),
            if (items.isEmpty)
              Text('The held pre-order is empty.', style: text.bodySmall)
            else
              ForkCard(
                inset: true,
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                child: Column(children: [
                  for (final it in items)
                    Padding(
                      padding: const EdgeInsets.symmetric(vertical: 5),
                      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Expanded(
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Text('${_s(it, 'name')}  ×${_int(it['quantity']) ?? 1}', style: text.bodyLarge),
                            if (_s(it, 'note', '').isNotEmpty)
                              Padding(
                                padding: const EdgeInsets.only(top: 2),
                                child: Text(_s(it, 'note', ''),
                                    style: text.bodySmall!
                                        .copyWith(fontSize: 11, fontStyle: FontStyle.italic)),
                              ),
                          ]),
                        ),
                        const SizedBox(width: 10),
                        Text(_money(_numOf(it['price']) * ((_int(it['quantity']) ?? 1).clamp(1, 999))),
                            style: text.titleSmall),
                      ]),
                    ),
                  if (subtotal > 0) ...[
                    const Padding(padding: EdgeInsets.symmetric(vertical: 6), child: Divider()),
                    Row(children: [
                      Expanded(child: Text('SUBTOTAL', style: text.labelSmall)),
                      Text(_money(subtotal), style: text.titleSmall),
                    ]),
                  ],
                ]),
              ),
            const SizedBox(height: AppSpacing.md),
            // True of the server: ConfirmWaitlistPreorder re-prices from the menu,
            // so a price change since they picked is always honoured.
            Text('Prices are re-checked against the menu when you confirm.',
                style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
          ]),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context, 'decline'),
          child: const Text('Let them change it'),
        ),
        FilledButton(
          onPressed: items.isEmpty ? null : () => Navigator.pop(context, 'confirm'),
          child: const Text('Confirm & send'),
        ),
      ],
    );
  }
}

/// Ornament for the waitlist hero and closing banners: a line of people
/// tapering away along an arc, drawn rather than shipped as an asset.
///
/// Fixed-size and hit-test transparent. It is dropped entirely at narrow widths
/// by its callers — decoration never gets to bid for the width the copy needs.
class _QueueMotif extends StatelessWidget {
  const _QueueMotif({this.width = 132, this.height = 88});

  final double width;
  final double height;

  @override
  Widget build(BuildContext context) => IgnorePointer(
        child: SizedBox(
          width: width,
          height: height,
          child: CustomPaint(painter: _QueueMotifPainter()),
        ),
      );
}

class _QueueMotifPainter extends CustomPainter {
  // Head + body per figure, fading back along the queue.
  static const List<double> _alphas = [0.32, 0.24, 0.16, 0.10];

  @override
  void paint(Canvas canvas, Size size) {
    final floor = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.2
      ..color = AppColors.copper.withValues(alpha: 0.20);
    canvas.drawArc(
      Rect.fromLTWH(size.width * 0.02, size.height * 0.20, size.width * 0.96, size.height * 1.05),
      3.34,
      2.60,
      false,
      floor,
    );
    for (var i = 0; i < _alphas.length; i++) {
      final t = i / (_alphas.length - 1);
      final cx = size.width * (0.17 + t * 0.66);
      final cy = size.height * (0.60 + (t - 0.5).abs() * 0.20);
      final r = size.height * (0.16 - t * 0.028);
      canvas.drawCircle(
        Offset(cx, cy - r * 1.45),
        r * 0.52,
        Paint()..color = AppColors.copperHi.withValues(alpha: _alphas[i]),
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset(cx, cy + r * 0.45), width: r * 1.5, height: r * 1.7),
          Radius.circular(r * 0.6),
        ),
        Paint()..color = AppColors.copper.withValues(alpha: _alphas[i] * 0.85),
      );
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

// --- Subscription & billing -------------------------------------------------
Widget billingModule(RestClient rest, Profile p) => _BillingView(rest: rest);

class _BillingView extends StatefulWidget {
  final RestClient rest;
  const _BillingView({required this.rest});
  @override
  State<_BillingView> createState() => _BillingViewState();
}

class _BillingViewState extends State<_BillingView> with CachePrimedScreen {
  bool _loading = true;
  bool _hasData = false;
  bool _busy = false;
  String? _error;
  Map<String, dynamic> _info = {};

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: () => widget.rest.getMap('/billing'),
      apply: (info) { _info = info; _hasData = true; _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) setState(() { _loading = true; _error = null; });
    try {
      final info = await widget.rest.getMap('/billing');
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() { _info = info; _hasData = true; _loading = false; _error = null; markCacheLive(); });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      if (_hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() { _error = '$e'; _loading = false; });
    }
  }

  String _cents(dynamic cents) {
    final n = num.tryParse('${cents ?? 0}') ?? 0;
    return '₹${(n / 100).toStringAsFixed(0)}';
  }

  // Time left to [iso], null when absent/unparseable. Deliberately a Duration and
  // not a day count: Duration.inDays truncates toward zero, which collapses
  // "ends in 20 hours" and "ended 20 hours ago" into the same 0.
  Duration? _timeUntil(String? iso) {
    if (iso == null || iso.isEmpty) return null;
    final dt = DateTime.tryParse(iso);
    if (dt == null) return null;
    return dt.difference(DateTime.now());
  }

  String _plural(int n, String unit) => '$n $unit${n == 1 ? '' : 's'}';

  // Rounded UP, so a period with 20 hours left reads as "1 day" rather than "0".
  int _daysLeft(Duration d) => (d.inMinutes / Duration.minutesPerDay).ceil();

  // Rounded DOWN on the overdue side, so "overdue by N days" only claims whole
  // elapsed days and stays silent for the first 24 hours.
  int _daysLate(Duration d) => (-d.inMinutes / Duration.minutesPerDay).floor();

  Future<void> _choose(Map plan) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      final r = await widget.rest.post('/billing/change-plan', {'plan_id': plan['id']});
      final mode = (r is Map ? '${r['mode'] ?? ''}' : '');
      String msg;
      if (mode == 'downgrade_scheduled') {
        msg = 'Scheduled — switches to ${plan['name']} at period end.';
      } else if (mode == 'noop') {
        msg = "You're already on ${plan['name']}.";
      } else if (r is Map && r['invoice'] != null) {
        msg = 'Invoice created for ${plan['name']}. Pay it from the web dashboard, or your provider will confirm.';
      } else {
        msg = 'Switched to ${plan['name']}.';
      }
      messenger.showSnackBar(SnackBar(content: Text(msg)));
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load billing',
        error: '$_error',
        onRetry: _load,
      );
    }
    if (_info['configured'] == false) {
      return const EmptyState(
        icon: Icons.credit_card_off_outlined,
        title: 'Billing not set up',
        caption: "Billing isn't set up for this workspace yet.",
      );
    }
    final sub = _info['subscription'] as Map?;
    final plan = _info['plan'] as Map?;
    final pending = _info['pending_plan'] as Map?;
    final plans = (_info['plans'] as List?) ?? const [];
    final invoices = (_info['invoices'] as List?) ?? const [];
    final status = '${sub?['status'] ?? ''}';
    final currentPlanId = sub?['plan_id'];
    final trialLeft = status == 'trial' ? _timeUntil(_s(sub ?? const {}, 'trial_ends_at', '')) : null;
    final periodLeft = _timeUntil(_s(sub ?? const {}, 'current_period_end', ''));
    // A period end in the past is never a countdown — but it is not a failure
    // yet either. The charge is presented on the due date and settles
    // asynchronously (a UPI/card mandate can take hours to confirm), and the
    // platform re-tries a soft decline on a nightly cycle, so the first hours
    // past the boundary are a renewal IN FLIGHT, not a renewal that failed.
    //
    // 48 hours: long enough to cover the initial presentation plus one nightly
    // retry, short enough that a genuinely dead card is called out within two
    // days. The server's own verdict always wins — once it manages to invoice a
    // lapsed subscription it flips the status to past_due/suspended, and that
    // escalates immediately whatever the clock says.
    const graceAfterPeriodEnd = Duration(hours: 48);
    final lapsed = status == 'active' && periodLeft != null && periodLeft.isNegative;
    final renewing = lapsed && -periodLeft <= graceAfterPeriodEnd;
    final overdue = status == 'past_due' || status == 'suspended' || (lapsed && !renewing);
    const labels = {
      'accounting': 'Accounting & cash', 'analytics': 'Analytics', 'inventory': 'Inventory & purchasing',
      'valet': 'Valet', 'coupons': 'Coupons', 'attendance': 'Attendance', 'multi_outlet': 'Multi-outlet',
    };

    final text = Theme.of(context).textTheme;
    final narrow = MediaQuery.sizeOf(context).width < 760;
    String renewal() {
      if (overdue) {
        final late = periodLeft == null ? 0 : _daysLate(periodLeft);
        return late >= 1 ? 'Payment overdue by ${_plural(late, 'day')}' : 'Payment overdue';
      }
      // Inside the grace window the honest statement is that the period ended
      // and the charge has not confirmed — not that anything went wrong.
      if (renewing) return 'Renewing — payment not confirmed yet';
      if (status != 'active' || periodLeft == null) return '';
      final days = _daysLeft(periodLeft);
      return days <= 0 ? 'Renews today' : 'Renews in ${_plural(days, 'day')}';
    }

    String trial() {
      if (trialLeft == null) return '';
      if (trialLeft.isNegative) return 'Trial expired';
      final days = _daysLeft(trialLeft);
      return days <= 0 ? 'Trial ends today' : 'Trial — ${_plural(days, 'day')} left';
    }

    final subCaption = [
      trial(),
      renewal(),
      if (sub == null) 'Unlimited starter (no plan assigned).',
    ].where((s) => s.isNotEmpty).join(' · ');

    return cacheStaleOverlay(RefreshIndicator(
      onRefresh: _load,
      child: ListView(padding: AppSpacing.pageNarrow, children: [
        StatCard(
          value: '${plan?['name'] ?? 'No plan'}',
          caption: subCaption.isEmpty ? 'CURRENT PLAN' : 'CURRENT PLAN · ${subCaption.toUpperCase()}',
          tag: status.isNotEmpty ? status : null,
          tagColor: overdue ? AppColors.danger : (renewing ? AppColors.warning : AppColors.copperHi),
          // Overdue outranks a scheduled downgrade: the plan may be about to be
          // cut off, which is the one thing the owner must see first. A renewal
          // still inside its grace window ranks the same way but says the
          // milder, true thing — nothing has failed yet.
          footer: overdue
              ? Row(mainAxisSize: MainAxisSize.min, children: [
                  StatusChip(label: 'Renewal failed', color: AppColors.danger, dense: true),
                  const SizedBox(width: AppSpacing.sm),
                  Flexible(
                    child: Text('This subscription did not renew. Settle it to keep your plan.',
                        style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
                  ),
                ])
              : renewing
                  ? Row(mainAxisSize: MainAxisSize.min, children: [
                      StatusChip(label: 'Renewing', color: AppColors.warning, dense: true),
                      const SizedBox(width: AppSpacing.sm),
                      Flexible(
                        child: Text('The billing period ended and the payment has not confirmed yet.',
                            style: text.bodySmall, maxLines: 2, overflow: TextOverflow.ellipsis),
                      ),
                    ])
                  : pending == null
                  ? null
                  : Row(mainAxisSize: MainAxisSize.min, children: [
                      StatusChip(label: 'Scheduled', color: AppColors.warning, dense: true),
                      const SizedBox(width: AppSpacing.sm),
                      Flexible(
                        child: Text('Switches to ${pending['name']} at period end.',
                            style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                      ),
                    ]),
        ),
        const SizedBox(height: AppSpacing.xxl),
        SectionHeader(title: 'Plans', count: plans.length),
        ...plans.map((pl) {
          final m = pl as Map;
          final isCurrent = m['id'] == currentPlanId && status == 'active';
          final fmap = (m['features'] as Map?) ?? const {};
          final features = <String>[];
          labels.forEach((k, v) { if (fmap[k] != false) features.add(v); });
          final limits = (m['limits'] as Map?) ?? const {};
          final price = m['price_cents'];
          return Padding(
            padding: const EdgeInsets.only(bottom: AppSpacing.md),
            child: ForkCard(
              selected: isCurrent,
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  Expanded(child: Text(_s(m, 'name'), style: text.titleMedium)),
                  const SizedBox(width: AppSpacing.md),
                  MicroStat(
                    value: (num.tryParse('$price') ?? 0) == 0 ? 'Free' : '${_cents(price)}/mo',
                    label: 'per month',
                    alignEnd: true,
                  ),
                ]),
                const SizedBox(height: AppSpacing.sm),
                if (features.isNotEmpty) Text(features.join(' · '), style: text.bodySmall),
                const SizedBox(height: 4),
                Wrap(spacing: 6, runSpacing: 6, children: [
                  InfoChip(
                    icon: Icons.badge_outlined,
                    label: limits['employees'] != null ? 'Up to ${limits['employees']} staff' : 'Unlimited staff',
                  ),
                  InfoChip(
                    icon: Icons.storefront_outlined,
                    label: limits['outlets'] != null ? 'Up to ${limits['outlets']} outlet(s)' : 'Unlimited outlets',
                  ),
                ]),
                const SizedBox(height: AppSpacing.md),
                Align(
                  alignment: Alignment.centerRight,
                  child: isCurrent
                      ? StatusChip(label: 'Current plan', color: AppColors.copper)
                      : ForkButton(
                          label: 'Choose',
                          icon: Icons.arrow_forward,
                          dense: true,
                          onPressed: _busy ? null : () => _choose(m),
                        ),
                ),
              ]),
            ),
          );
        }),
        if (invoices.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.lg),
          SectionHeader(title: 'Invoices', count: invoices.length),
          ...invoices.map((iv) {
            final m = iv as Map;
            final ivStatus = _s(m, 'status');
            return Padding(
              padding: const EdgeInsets.only(bottom: 10),
              child: ForkCard(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                child: Row(children: [
                  Container(
                    width: 36,
                    height: 36,
                    decoration: BoxDecoration(
                      color: AppColors.inset,
                      borderRadius: AppRadius.controlAll,
                      border: Border.all(color: AppColors.border),
                    ),
                    child: Icon(Icons.receipt_long_outlined, size: 16, color: AppColors.copper),
                  ),
                  const SizedBox(width: AppSpacing.md),
                  Expanded(
                    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text(_cents(m['amount_cents']), style: text.titleSmall),
                      if (_s(m, 'note', '').isNotEmpty) ...[
                        const SizedBox(height: 2),
                        Text(_s(m, 'note', ''), style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                      ],
                    ]),
                  ),
                  const SizedBox(width: AppSpacing.md),
                  StatusChip(label: ivStatus, color: _stageColor(ivStatus), dense: narrow),
                ]),
              ),
            );
          }),
        ],
      ]),
    ));
  }
}

// --- Cash register / day-close ---------------------------------------------
Widget cashModule(RestClient rest, Profile p) => _CashView(rest: rest);

class _CashView extends StatefulWidget {
  final RestClient rest;
  const _CashView({required this.rest});
  @override
  State<_CashView> createState() => _CashViewState();
}

class _CashViewState extends State<_CashView> with CachePrimedScreen {
  // Z-report hunting is its own question, so this screen keeps its own window —
  // the same control everywhere else uses, remembered separately. Before this
  // the past-sessions list had NO date filter at all: it showed whatever the
  // endpoint's default returned, with nothing on screen saying which days.
  DateRange _range = DateRangeMemory.of('cash');

  void _setRange(DateRange next) {
    setState(() => _range = next);
    DateRangeMemory.remember('cash', next);
    _load();
  }

  bool _loading = true;
  // First payload landed — _current may legitimately be null (no open session).
  bool _hasData = false;
  bool _busy = false;
  String? _error;
  Map<String, dynamic>? _current;
  List _history = const [];

  final _floatCtl = TextEditingController();
  final _countedCtl = TextEditingController();
  final _payoutCtl = TextEditingController();
  final _notesCtl = TextEditingController();

  // ------------------------------------------------- denomination tally ---
  //
  // Indian denominations, notes then coins, biggest first. ₹2000 is still legal
  // tender, so a drawer can genuinely hold one; ₹20 and ₹10 exist as BOTH a note
  // and a coin, which is why this is a list of (value, isCoin) rather than a map
  // keyed by value.
  static const List<(int, bool)> _denominations = [
    (2000, false), (500, false), (200, false), (100, false), (50, false), (20, false), (10, false),
    (20, true), (10, true), (5, true), (2, true), (1, true),
  ];

  // One count field per denomination.
  //
  // READ THIS BEFORE "FIXING" IT: the per-denomination counts are a COUNTING AID
  // and are NOT PERSISTED — deliberately, because there is nowhere to put them.
  // `CashSessions` has no denomination column and no JSON column (base schema,
  // and none of the migrations after it touch the table), and POST /cash/close
  // reads only `counted_cash`, `cash_payouts` and `notes` — any other body key is
  // silently dropped, so posting a breakdown would return 200 and lose it. What
  // this tally does is compute the TOTAL and put it in the existing
  // `counted_cash` field, which is the number the backend stores and computes the
  // variance from. Storing the breakdown would need a new nullable jsonb column
  // and a migration, which is a separate, scoped change.
  late final List<TextEditingController> _denomCtls =
      [for (var _ in _denominations) TextEditingController()];

  /// Collapsible, because it is eleven fields; open by default because counting
  /// the drawer IS closing the drawer.
  bool _showDenoms = true;

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: _fetch,
      apply: (d) { _apply(d); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  @override
  void dispose() {
    _floatCtl.dispose();
    _countedCtl.dispose();
    _payoutCtl.dispose();
    _notesCtl.dispose();
    for (final c in _denomCtls) {
      c.dispose();
    }
    super.dispose();
  }

  double _d(String s) => double.tryParse(s.trim()) ?? 0;

  int _denomCount(int i) => int.tryParse(_denomCtls[i].text.trim()) ?? 0;

  /// What the counts add up to — the figure that goes into `counted_cash`.
  double get _denomTotal {
    var total = 0.0;
    for (var i = 0; i < _denominations.length; i++) {
      final n = _denomCount(i);
      if (n > 0) total += n * _denominations[i].$1;
    }
    return total;
  }

  bool get _denomEntered {
    for (var i = 0; i < _denominations.length; i++) {
      if (_denomCount(i) > 0) return true;
    }
    return false;
  }

  // The tally drives the Counted-cash field while it holds any counts, so the
  // number submitted is the one the closer actually counted rather than a second,
  // hand-typed figure that could disagree with it. Clearing every count leaves
  // the field alone, so typing the total straight in still works.
  void _denomChanged() {
    setState(() {
      if (_denomEntered) _countedCtl.text = _denomTotal.toStringAsFixed(0);
    });
  }

  void _clearDenoms() {
    for (final c in _denomCtls) {
      c.clear();
    }
  }

  /// Side-effect-free GET composition — replayable against the persisted cache
  /// at boot and the network path of every [_load].
  Future<({Map<String, dynamic>? current, List history})> _fetch() async {
    // The OPEN drawer is "right now" and takes no window; the history does.
    final cur = await widget.rest.getMap('/cash/current');
    final hist = await widget.rest
        .getMap('/cash/sessions?${_range.reportQuery}')
        .catchError((_) => <String, dynamic>{});
    return (
      current: cur['session'] is Map ? Map<String, dynamic>.from(cur['session'] as Map) : null,
      history: (hist['sessions'] as List?) ?? const [],
    );
  }

  void _apply(({Map<String, dynamic>? current, List history}) d) {
    _current = d.current;
    _history = d.history;
    _hasData = true;
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) setState(() { _loading = true; _error = null; });
    try {
      final d = await _fetch();
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _apply(d);
        _loading = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      if (_hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() { _error = '$e'; _loading = false; });
    }
  }

  Future<void> _open() async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await widget.rest.post('/cash/open', {'opening_float': _d(_floatCtl.text)});
      _floatCtl.clear();
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _close() async {
    final messenger = ScaffoldMessenger.of(context);
    if (_countedCtl.text.trim().isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('Enter the counted cash first.')));
      return;
    }
    setState(() => _busy = true);
    try {
      final res = await widget.rest.post('/cash/close', {
        'counted_cash': _d(_countedCtl.text),
        'cash_payouts': _d(_payoutCtl.text),
        'notes': _notesCtl.text.trim(),
      });
      _countedCtl.clear();
      _payoutCtl.clear();
      _notesCtl.clear();
      _clearDenoms();
      final v = res is Map ? (num.tryParse('${res['variance'] ?? 0}') ?? 0) : 0;
      messenger.showSnackBar(SnackBar(
        content: Text(v == 0 ? 'Drawer balanced 🎯' : 'Variance ${_money(v)} (${v > 0 ? 'over' : 'short'})'),
      ));
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load cash sessions',
        error: '$_error',
        onRetry: _load,
      );
    }
    final cur = _current;
    final closed = _history.where((s) => (s as Map)['status'] == 'closed').toList();
    final text = Theme.of(context).textTheme;
    final narrow = MediaQuery.sizeOf(context).width < 760;
    return cacheStaleOverlay(RefreshIndicator(
      onRefresh: _load,
      child: ListView(padding: AppSpacing.pageNarrow, children: [
        AnimatedSwitcher(
          duration: AppDurations.base,
          switchInCurve: Curves.easeOut,
          switchOutCurve: Curves.easeIn,
          child: cur == null
              ? KeyedSubtree(key: const ValueKey('cash-closed'), child: _openCard())
              : KeyedSubtree(key: const ValueKey('cash-open'), child: _openSessionCard(cur)),
        ),
        const SizedBox(height: AppSpacing.xxl),
        SectionHeader(
          title: 'Past sessions',
          count: closed.length,
          trailing: InfoChip(icon: Icons.calendar_today_outlined, label: _range.label()),
        ),
        const SizedBox(height: AppSpacing.sm),
        Row(children: [Expanded(child: DateRangeChip(value: _range, onChanged: _setRange))]),
        const SizedBox(height: AppSpacing.md),
        if (closed.isEmpty)
          // Names the window rather than saying "yet": with a filter on screen,
          // "no closed sessions yet" would read as "this restaurant has never
          // closed a drawer", which is a different and alarming claim.
          Text('No closed sessions in ${_range.label()}.', style: text.bodySmall)
        else
          ...closed.map((s) {
            final m = s as Map;
            final v = num.tryParse('${m['variance'] ?? 0}') ?? 0;
            final vColor = v == 0 ? AppColors.success : (v > 0 ? AppColors.warning : AppColors.danger);
            final vLabel = v == 0 ? 'Balanced' : (v > 0 ? 'Over' : 'Short');
            return Padding(
              padding: const EdgeInsets.only(bottom: 10),
              child: ForkCard(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                child: Row(children: [
                  Container(
                    width: 38,
                    height: 38,
                    decoration: BoxDecoration(
                      color: AppColors.inset,
                      borderRadius: AppRadius.controlAll,
                      border: Border.all(color: AppColors.border),
                    ),
                    child: Icon(Icons.point_of_sale, size: 16, color: AppColors.textTertiary),
                  ),
                  const SizedBox(width: AppSpacing.md),
                  Expanded(
                    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text(_fmtTime(_s(m, 'closed_at', '')),
                          style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                      const SizedBox(height: 4),
                      Text(
                        'Float ${_money(m['opening_float'])} · sales ${_money(m['cash_sales'])} · expected ${_money(m['expected_cash'])} · counted ${_money(m['counted_cash'])}',
                        style: text.bodySmall,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ]),
                  ),
                  const SizedBox(width: AppSpacing.md),
                  MicroStat(value: '${v > 0 ? '+' : ''}${_money(v)}', label: 'variance', alignEnd: true),
                  const SizedBox(width: 14),
                  StatusChip(label: vLabel, color: vColor, dense: narrow),
                ]),
              ),
            );
          }),
      ]),
    ));
  }

  Widget _openCard() {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Container(
            width: 36,
            height: 36,
            decoration: BoxDecoration(
              color: AppColors.inset,
              borderRadius: AppRadius.controlAll,
              border: Border.all(color: AppColors.border),
            ),
            child: Icon(Icons.lock_open, size: 16, color: AppColors.copper),
          ),
          const SizedBox(width: AppSpacing.md),
          Expanded(child: Text('Open register', style: text.titleMedium)),
          StatusChip(label: 'Closed', color: AppColors.neutral, dense: true),
        ]),
        const SizedBox(height: AppSpacing.sm),
        Text('No register is open for this outlet. Enter the starting float to begin.', style: text.bodySmall),
        const SizedBox(height: AppSpacing.md),
        TextField(controller: _floatCtl, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Opening float (₹)', border: OutlineInputBorder())),
        const SizedBox(height: AppSpacing.md),
        Align(
          alignment: Alignment.centerRight,
          child: ForkButton(
            label: _busy ? '…' : 'Open register',
            icon: Icons.lock_open,
            onPressed: _busy ? null : _open,
          ),
        ),
      ]),
    );
  }

  // Count the drawer note by note and coin by coin, then check the tally against
  // what the register expects. The counts themselves are NOT saved — see
  // `_denomCtls` for why that is the honest ceiling here — so the section says so
  // rather than implying a record it cannot keep.
  Widget _denomTally(num expected) {
    final text = Theme.of(context).textTheme;
    final total = _denomTotal;
    final diff = total - expected;
    final diffColor = diff == 0
        ? AppColors.success
        : (diff > 0 ? AppColors.warning : AppColors.danger);
    // Never colour alone: the chip always spells out which way it is out.
    final diffLabel = diff == 0 ? 'Balanced' : (diff > 0 ? 'Over' : 'Short');

    Widget line(int i) {
      final (value, coin) = _denominations[i];
      final n = _denomCount(i);
      return Padding(
        padding: const EdgeInsets.only(bottom: AppSpacing.sm),
        child: Row(children: [
          SizedBox(
            width: 66,
            child: Text('₹$value',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: text.bodyMedium!.copyWith(color: AppColors.textPrimary)),
          ),
          Expanded(
            child: TextField(
              // ₹20 and ₹10 are each a note AND a coin, so the row's own label is
              // not a unique handle for it — the kind that reads unique until the
              // first ₹10-coin subtotal renders as "₹10" too.
              key: ValueKey('denom-${coin ? 'coin' : 'note'}-$value'),
              controller: _denomCtls[i],
              keyboardType: TextInputType.number,
              inputFormatters: [FilteringTextInputFormatter.digitsOnly],
              onChanged: (_) => _denomChanged(),
              style: text.bodyMedium!.copyWith(color: AppColors.textPrimary),
              decoration: const InputDecoration(
                isDense: true,
                hintText: '0',
                border: OutlineInputBorder(),
              ),
            ),
          ),
          const SizedBox(width: AppSpacing.sm),
          SizedBox(
            width: 84,
            child: Text(n == 0 ? '—' : '₹${n * value}',
                textAlign: TextAlign.end,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: text.bodySmall),
          ),
        ]),
      );
    }

    Widget summaryRow(String label, Widget value) => Padding(
          padding: const EdgeInsets.symmetric(vertical: 4),
          child: Row(children: [
            Expanded(child: Text(label, style: text.bodyMedium)),
            const SizedBox(width: AppSpacing.sm),
            value,
          ]),
        );

    return ForkCard(
      inset: true,
      padding: const EdgeInsets.all(AppSpacing.md),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(Icons.calculate_outlined, size: 15, color: AppColors.copper),
          const SizedBox(width: AppSpacing.sm),
          Expanded(child: Text('COUNT THE DRAWER', style: text.labelSmall)),
          ForkButton.subtle(
            label: _showDenoms ? 'Hide' : 'Show',
            onPressed: () => setState(() => _showDenoms = !_showDenoms),
          ),
        ]),
        if (_showDenoms) ...[
          const SizedBox(height: AppSpacing.sm),
          Text('Enter how many of each — the total fills in Counted cash below. '
              'The per-denomination counts are a counting aid and are not saved with the session.',
              style: text.bodySmall),
          const SizedBox(height: AppSpacing.md),
          Text('NOTES', style: text.labelSmall),
          const SizedBox(height: AppSpacing.sm),
          for (var i = 0; i < _denominations.length; i++)
            if (!_denominations[i].$2) line(i),
          const SizedBox(height: AppSpacing.xs),
          Text('COINS', style: text.labelSmall),
          const SizedBox(height: AppSpacing.sm),
          for (var i = 0; i < _denominations.length; i++)
            if (_denominations[i].$2) line(i),
        ],
        Container(height: 1, margin: const EdgeInsets.symmetric(vertical: 6), color: AppColors.divider),
        summaryRow('Counted from tally', Text(_money(total), style: text.titleMedium)),
        summaryRow('Expected in drawer', Text(_money(expected), style: text.titleSmall)),
        if (_denomEntered)
          summaryRow(
            'Difference',
            StatusChip(label: '$diffLabel ${_money(diff.abs())}', color: diffColor, dense: true),
          ),
      ]),
    );
  }

  Widget _openSessionCard(Map<String, dynamic> cur) {
    final expected = num.tryParse('${cur['live_expected'] ?? 0}') ?? 0;
    final text = Theme.of(context).textTheme;
    Widget row(String k, String v, {bool strong = false}) => Padding(
          padding: const EdgeInsets.symmetric(vertical: 5),
          child: Row(children: [
            Expanded(child: Text(k, style: text.bodyMedium)),
            const SizedBox(width: AppSpacing.md),
            Text(v, style: strong ? text.titleMedium : text.titleSmall),
          ]),
        );
    return Column(children: [
      ForkCard(
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Container(
              width: 36,
              height: 36,
              decoration: BoxDecoration(
                color: AppColors.tint(AppColors.success),
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: AppColors.edge(AppColors.success)),
              ),
              child: Icon(Icons.lock_open, size: 16, color: AppColors.success),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(
              child: Text('Open since ${_fmtTime(_s(cur, 'opened_at', ''))}',
                  style: text.titleMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
            ),
            StatusChip(label: 'Open', color: AppColors.success, dense: true),
          ]),
          const SizedBox(height: AppSpacing.md),
          row('Opening float', _money(cur['opening_float'])),
          row('Cash sales (settled)', _money(cur['live_cash_sales'])),
          row('Cash refunds', '− ${_money(cur['live_cash_refunds'])}'),
          Container(height: 1, margin: const EdgeInsets.symmetric(vertical: 6), color: AppColors.divider),
          row('Expected in drawer', _money(expected), strong: true),
        ]),
      ),
      const SizedBox(height: AppSpacing.md),
      ForkCard(
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Container(
              width: 36,
              height: 36,
              decoration: BoxDecoration(
                color: AppColors.inset,
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: AppColors.border),
              ),
              child: Icon(Icons.lock_outline, size: 16, color: AppColors.copper),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(child: Text('Close & count down', style: text.titleMedium)),
          ]),
          const SizedBox(height: AppSpacing.md),
          // Payouts are subtracted here because the server subtracts them when it
          // computes the variance it STORES: expected = float + sales - refunds -
          // payouts, variance = counted - expected (CloseCashSession). Comparing
          // the tally against live_expected alone, which does not net payouts off,
          // shows "Balanced" on a drawer the server then records as short by
          // exactly the payout — the one reading a cash screen must never give.
          _denomTally(expected - _d(_payoutCtl.text)),
          const SizedBox(height: AppSpacing.md),
          TextField(controller: _countedCtl, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Counted cash (₹)', border: OutlineInputBorder())),
          const SizedBox(height: 10),
          // Rebuild on edit so the tally above re-nets against the new payout
          // rather than sitting on a figure the closer has already superseded.
          TextField(controller: _payoutCtl, onChanged: (_) => setState(() {}), keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Cash paid out (₹)', border: OutlineInputBorder())),
          const SizedBox(height: 10),
          TextField(controller: _notesCtl, decoration: const InputDecoration(labelText: 'Notes (optional)', border: OutlineInputBorder())),
          const SizedBox(height: AppSpacing.md),
          Align(
            alignment: Alignment.centerRight,
            child: ForkButton(
              label: _busy ? '…' : 'Close register',
              icon: Icons.lock_outline,
              onPressed: _busy ? null : _close,
            ),
          ),
        ]),
      ),
    ]);
  }
}

// --- Purchase orders --------------------------------------------------------
Widget purchaseOrdersModule(RestClient rest, Profile p) => _PurchaseOrdersView(rest: rest);

class _PurchaseOrdersView extends StatefulWidget {
  final RestClient rest;
  const _PurchaseOrdersView({required this.rest});
  @override
  State<_PurchaseOrdersView> createState() => _PurchaseOrdersViewState();
}

class _PurchaseOrdersViewState extends State<_PurchaseOrdersView> with CachePrimedScreen {
  bool _loading = true;
  // First payload landed (cached or live) — an empty PO list is data too.
  bool _hasData = false;
  String? _error;
  List _orders = const [];
  List _vendors = const [];
  List _inventory = const [];

  /// Why the inventory read came back empty-handed, when it FAILED rather than
  /// genuinely holding nothing. "New PO" needs the difference: an empty stock
  /// list means "add items first", a failed read means "retry / check access" —
  /// and swallowing the error used to make both look identical.
  String? _inventoryError;

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: _fetch,
      apply: (d) { _apply(d); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  /// The screen's GET composition, side-effect free — replayable against the
  /// persisted cache at boot and the network path of every [_load].
  Future<({List orders, List vendors, List inventory, String? inventoryError})> _fetch() async {
    final o = await widget.rest.getMap('/purchase-orders');
    List vend = const [];
    List inv = const [];
    String? invError;
    try { final v = await widget.rest.getMap('/vendors'); vend = (v['vendors'] as List?) ?? const []; } catch (_) {}
    try { inv = await widget.rest.getList('/inventory'); } catch (e) { invError = '$e'; }
    return (
      orders: (o['orders'] as List?) ?? const [],
      vendors: vend,
      inventory: inv,
      inventoryError: invError,
    );
  }

  void _apply(({List orders, List vendors, List inventory, String? inventoryError}) d) {
    _orders = d.orders;
    _vendors = d.vendors;
    _inventory = d.inventory;
    _inventoryError = d.inventoryError;
    _hasData = true;
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) setState(() { _loading = true; _error = null; });
    try {
      final d = await _fetch();
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _apply(d);
        _loading = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      // Data already on screen (saved or live): keep it behind the offline
      // pill rather than trading the list for an error page.
      if (_hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() { _error = '$e'; _loading = false; });
    }
  }

  // PO status voice: draft=neutral, ordered/sent=info, received=success,
  // cancelled=danger — always paired with the labelled StatusChip.
  Color _statusColor(String s) {
    switch (s) {
      case 'received': return AppColors.success;
      case 'ordered': return AppColors.info;
      case 'cancelled': return AppColors.danger;
      default: return AppColors.neutral;
    }
  }

  Future<void> _setStatus(Map po, String status) async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await widget.rest.post('/purchase-orders/${po['id']}/status', {'status': status});
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _delete(Map po) async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await widget.rest.delete('/purchase-orders/${po['id']}');
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  /// The whole PO: who it is with, what was asked for, what actually arrived,
  /// what it cost and when each step happened.
  ///
  /// `GET /purchase-orders` already returns the same record `GET
  /// /purchase-orders/:id` does — same `mapPurchaseOrder` on the server — so
  /// this reads the row in hand rather than fetching it again.
  ///
  /// Only the two forward-moving actions are repeated here. Cancel and Delete
  /// stay on the card alone: a sheet the owner opened to READ must not put a
  /// destructive control under the next tap.
  Future<void> _openPo(Map po) {
    final text = Theme.of(context).textTheme;
    final status = _s(po, 'status', 'draft');
    final items = (po['items'] as List?)?.whereType<Map>().toList() ?? const <Map>[];
    final ordered = items.fold<double>(0, (s, it) => s + _numOf(it['qty_ordered']));
    final received = items.fold<double>(0, (s, it) => s + _numOf(it['qty_received']));
    final quality = _int(po['quality_rating']);
    final notes = _s(po, 'notes', '');
    final expected = _s(po, 'expected_date', '');
    final canReceive = status == 'ordered' || status == 'draft';

    String qty(double v) => v == v.roundToDouble() ? v.toStringAsFixed(0) : v.toStringAsFixed(2);

    // Built through a Builder so the button closes the SHEET's route: these
    // children are handed to _detailSheet as widgets, so a captured page context
    // would be popping from outside the dialog it lives in.
    Widget action(Widget Function(BuildContext) build) => Padding(
          padding: const EdgeInsets.only(top: AppSpacing.sm),
          child: Builder(builder: build),
        );

    return _detailSheet(
      context,
      eyebrow: 'Purchase order · $status',
      title: _s(po, 'vendor_name', 'Unassigned vendor'),
      // Inventory reads no focus key, so nothing is forwarded — a target it
      // cannot resolve would land the owner there under a "not in this list".
      jumpTo: 'Inventory',
      children: [
        _detailRow(context, 'Status', status),
        _detailRow(context, 'Total cost', _money(po['total_cost'])),
        _detailRow(context, 'Received', '${qty(received)} of ${qty(ordered)}',
            trailing: ordered > 0 ? '${(received / ordered * 100).toStringAsFixed(0)}%' : null),
        if (quality != null && quality > 0) _detailRow(context, 'Delivery quality', '$quality of 5'),
        Padding(
          padding: const EdgeInsets.only(top: 14, bottom: 2),
          child: Text('LINES (${items.length})', style: text.labelSmall),
        ),
        if (items.isEmpty)
          Text('This order has no lines.', style: text.bodySmall)
        else
          for (final it in items)
            _detailRow(
              context,
              _s(it, 'name', 'Item'),
              _money(_numOf(it['qty_ordered']) * _numOf(it['unit_cost'])),
              // What was asked for and what turned up, on the same line — a
              // short delivery is the thing a PO is opened to check.
              trailing: '${qty(_numOf(it['qty_ordered']))} × ${_money(it['unit_cost'])}'
                  ' · ${qty(_numOf(it['qty_received']))} in',
            ),
        Padding(
          padding: const EdgeInsets.only(top: 14, bottom: 2),
          child: Text('DATES', style: text.labelSmall),
        ),
        if (_s(po, 'created_at', '').isNotEmpty) _detailRow(context, 'Raised', _fmtTime(_s(po, 'created_at'))),
        if (_s(po, 'created_by', '').isNotEmpty) _detailRow(context, 'Raised by', _s(po, 'created_by')),
        if (_s(po, 'ordered_at', '').isNotEmpty) _detailRow(context, 'Placed', _fmtTime(_s(po, 'ordered_at'))),
        if (expected.isNotEmpty) _detailRow(context, 'Expected', expected),
        if (_s(po, 'received_at', '').isNotEmpty) _detailRow(context, 'Received on', _fmtTime(_s(po, 'received_at'))),
        if (notes.isNotEmpty) ...[
          Padding(
            padding: const EdgeInsets.only(top: 14, bottom: 2),
            child: Text('NOTES', style: text.labelSmall),
          ),
          Text(notes, style: text.bodySmall),
        ],
        if (status == 'draft')
          action((ctx) => ForkButton.ghost(
                label: 'Place this order',
                icon: Icons.send_outlined,
                dense: true,
                onPressed: () {
                  Navigator.pop(ctx);
                  _setStatus(po, 'ordered');
                },
              )),
        if (canReceive)
          action((ctx) => ForkButton(
                label: 'Receive stock',
                icon: Icons.inventory_2_outlined,
                dense: true,
                onPressed: () {
                  Navigator.pop(ctx);
                  _receivePo(po);
                },
              )),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load purchase orders',
        error: '$_error',
        onRetry: _load,
      );
    }
    return cacheStaleOverlay(Scaffold(
      backgroundColor: Colors.transparent,
      // ALWAYS live. A FloatingActionButton with a null onPressed keeps its
      // full colour (FABs have no disabled look), so gating it on inventory
      // rendered a button that LOOKED tappable and silently ate the tap — a
      // real owner reported exactly that. _createPo now owns the empty case
      // and says out loud why a PO cannot be raised yet.
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _createPo,
        icon: const Icon(Icons.add),
        label: const Text('New PO'),
      ),
      body: RefreshIndicator(
        onRefresh: _load,
        child: _orders.isEmpty
            ? ListView(children: const [
                SizedBox(height: 80),
                EmptyState(
                  icon: Icons.local_shipping_outlined,
                  title: 'No purchase orders yet',
                  caption: 'Raise a PO to restock from your vendors — received stock updates inventory automatically.',
                ),
              ])
            : ListView.builder(
                padding: AppSpacing.pageNarrow,
                itemCount: _orders.length + 1,
                itemBuilder: (c, i) => i == 0
                    ? SectionHeader(title: 'Purchase orders', count: _orders.length)
                    : _poCard(_orders[i - 1] as Map),
              ),
      ),
    ));
  }

  Widget _poCard(Map po) {
    final status = _s(po, 'status', 'draft');
    final items = (po['items'] as List?) ?? const [];
    final ordered = items.fold<double>(0, (s, it) => s + (num.tryParse('${(it as Map)['qty_ordered'] ?? 0}') ?? 0));
    final received = items.fold<double>(0, (s, it) => s + (num.tryParse('${(it as Map)['qty_received'] ?? 0}') ?? 0));
    final canReceive = status == 'ordered' || status == 'draft';
    final text = Theme.of(context).textTheme;
    final narrow = MediaQuery.sizeOf(context).width < 760;
    return Padding(
      padding: const EdgeInsets.only(bottom: 14),
      child: ForkCard(
        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
        // The card summarises; the sheet is where the lines, the short
        // deliveries and the dates live. The action row below keeps its own
        // buttons, so this tap never resolves to Cancel or Delete.
        onTap: () => _openPo(po),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          _recordHeadRow(
            context,
            leading: Container(
              width: 40,
              height: 40,
              decoration: BoxDecoration(
                color: AppColors.inset,
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: AppColors.border),
              ),
              child: Icon(Icons.local_shipping_outlined, size: 16, color: AppColors.textTertiary),
            ),
            identity: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text(_s(po, 'vendor_name', 'Unassigned vendor'),
                  style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
              const SizedBox(height: 6),
              Wrap(spacing: 6, runSpacing: 6, children: [
                InfoChip(icon: Icons.inventory_2_outlined, label: '${items.length} item(s)'),
                InfoChip(
                  icon: Icons.call_received,
                  label: '${received.toStringAsFixed(0)}/${ordered.toStringAsFixed(0)} received',
                ),
              ]),
            ]),
            trailing: [
              MicroStat(value: _money(po['total_cost']), label: 'total', alignEnd: true),
              AnimatedSwitcher(
                duration: AppDurations.base,
                switchInCurve: Curves.easeOut,
                switchOutCurve: Curves.easeIn,
                child: StatusChip(
                  key: ValueKey('po-${po['id']}-$status'),
                  label: status,
                  color: _statusColor(status),
                  dense: narrow,
                ),
              ),
            ],
          ),
          const SizedBox(height: AppSpacing.md),
          Wrap(spacing: AppSpacing.sm, runSpacing: AppSpacing.sm, children: [
            if (status == 'draft')
              ForkButton.ghost(label: 'Place', icon: Icons.send_outlined, dense: true, onPressed: () => _setStatus(po, 'ordered')),
            if (canReceive)
              ForkButton(label: 'Receive', icon: Icons.inventory_2_outlined, dense: true, onPressed: () => _receivePo(po)),
            if (status != 'received' && status != 'cancelled')
              ForkButton.subtle(label: 'Cancel', icon: Icons.block, onPressed: () => _setStatus(po, 'cancelled')),
            if (status != 'received')
              ForkButton.subtle(label: 'Delete', icon: Icons.delete_outline, onPressed: () => _delete(po)),
          ]),
        ]),
      ),
    );
  }

  Future<void> _createPo() async {
    // A PO line IS an inventory item, so with none loaded the form has nothing
    // to offer. Say which of the two situations this is — nothing in stock yet,
    // or a read that failed — instead of the dead-looking tap this used to be.
    if (_inventory.isEmpty) {
      final nav = ModuleNavigator.of(context);
      final failed = _inventoryError != null;
      await showDialog<void>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('New purchase order'),
          content: Text(
            failed
                ? 'Your inventory could not be loaded, and every purchase-order '
                    'line must name an inventory item.\n\n$_inventoryError'
                : 'Every purchase-order line names an inventory item, and this '
                    'outlet has none yet. Add the ingredients you stock in '
                    'Inventory first — then raise a PO to order them from a vendor.',
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close')),
            if (failed)
              FilledButton(
                onPressed: () { Navigator.pop(ctx); _load(); },
                child: const Text('Retry'),
              )
            else if (nav?.canOpen('Inventory') ?? false)
              FilledButton(
                onPressed: () { Navigator.pop(ctx); nav!.openModule('Inventory'); },
                child: const Text('Open Inventory'),
              ),
          ],
        ),
      );
      return;
    }
    final messenger = ScaffoldMessenger.of(context);
    String? vendorId;
    String? pickId;
    final List<Map<String, dynamic>> lines = [];
    final qtyCtl = TextEditingController();
    final costCtl = TextEditingController();
    final result = await showDialog<String>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setLocal) {
        return AlertDialog(
          title: const Text('New purchase order'),
          content: SizedBox(width: 440, child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            if (_vendors.isNotEmpty)
              DropdownButtonFormField<String>(
                initialValue: vendorId, isExpanded: true,
                decoration: const InputDecoration(labelText: 'Vendor (optional)', border: OutlineInputBorder()),
                items: [for (final v in _vendors) DropdownMenuItem(value: '${(v as Map)['id']}', child: Text(_s(v, 'name')))],
                onChanged: (x) => setLocal(() => vendorId = x),
              ),
            const SizedBox(height: 8),
            DropdownButtonFormField<String>(
              initialValue: pickId, isExpanded: true,
              decoration: const InputDecoration(labelText: 'Item', border: OutlineInputBorder()),
              items: [for (final it in _inventory) DropdownMenuItem(value: '${(it as Map)['id']}', child: Text(_s(it, 'name')))],
              onChanged: (x) => setLocal(() => pickId = x),
            ),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(child: TextField(controller: qtyCtl, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Qty', border: OutlineInputBorder()))),
              const SizedBox(width: 8),
              Expanded(child: TextField(controller: costCtl, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Unit cost', border: OutlineInputBorder()))),
              const SizedBox(width: 4),
              IconButton(
                icon: const Icon(Icons.add_circle),
                onPressed: () {
                  if (pickId == null) return;
                  final item = _inventory.firstWhere((i) => '${(i as Map)['id']}' == pickId, orElse: () => null);
                  final q = double.tryParse(qtyCtl.text.trim()) ?? 0;
                  if (item == null || q <= 0) return;
                  final m = item as Map;
                  final c = double.tryParse(costCtl.text.trim()) ?? 0;
                  setLocal(() {
                    lines.removeWhere((l) => l['inventory_id'] == '${m['id']}');
                    lines.add({'inventory_id': '${m['id']}', 'name': _s(m, 'name'), 'qty_ordered': q, 'unit_cost': c});
                    pickId = null; qtyCtl.clear(); costCtl.clear();
                  });
                },
              ),
            ]),
            const SizedBox(height: 8),
            for (final l in lines)
              ListTile(
                dense: true,
                title: Text('${l['name']}'),
                subtitle: Text('${l['qty_ordered']} × ${_money(l['unit_cost'])}'),
                trailing: IconButton(icon: const Icon(Icons.delete, size: 18), onPressed: () => setLocal(() => lines.removeWhere((x) => x['inventory_id'] == l['inventory_id']))),
              ),
          ]))),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
            TextButton(onPressed: lines.isEmpty ? null : () => Navigator.pop(ctx, 'draft'), child: const Text('Save draft')),
            FilledButton(onPressed: lines.isEmpty ? null : () => Navigator.pop(ctx, 'ordered'), child: const Text('Place order')),
          ],
        );
      }),
    );
    if (result == null) return;
    try {
      await widget.rest.post('/purchase-orders', {
        'vendor_id': ?vendorId,
        'items': lines,
        'status': result,
      });
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _receivePo(Map po) async {
    final messenger = ScaffoldMessenger.of(context);
    final items = (po['items'] as List?) ?? const [];
    final ctls = <String, TextEditingController>{};
    for (final it in items) {
      final m = it as Map;
      final ordered = num.tryParse('${m['qty_ordered'] ?? 0}') ?? 0;
      final rec = num.tryParse('${m['qty_received'] ?? 0}') ?? 0;
      final remaining = ordered - rec;
      ctls['${m['inventory_id']}'] = TextEditingController(text: remaining > 0 ? remaining.toStringAsFixed(0) : '');
    }
    int qualityRating = 0; // 0 = not rated; 1–5 feeds the supplier score
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(builder: (ctx, setDlg) => AlertDialog(
        title: const Text('Receive stock'),
        content: SizedBox(width: 440, child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [
          for (final it in items)
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: Row(children: [
                Expanded(child: Text(_s(it as Map, 'name'))),
                SizedBox(
                  width: 90,
                  child: TextField(
                    controller: ctls['${(it)['inventory_id']}'],
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(hintText: 'Qty', border: OutlineInputBorder()),
                  ),
                ),
              ]),
            ),
          const Divider(),
          Row(children: [
            const Expanded(child: Text('Delivery quality', style: TextStyle(fontSize: 13))),
            DropdownButton<int>(
              value: qualityRating,
              items: const [
                DropdownMenuItem(value: 0, child: Text('Not rated')),
                DropdownMenuItem(value: 5, child: Text('★★★★★')),
                DropdownMenuItem(value: 4, child: Text('★★★★')),
                DropdownMenuItem(value: 3, child: Text('★★★')),
                DropdownMenuItem(value: 2, child: Text('★★')),
                DropdownMenuItem(value: 1, child: Text('★')),
              ],
              onChanged: (v) => setDlg(() => qualityRating = v ?? 0),
            ),
          ]),
          Align(alignment: Alignment.centerLeft, child: Text('Feeds the supplier score in Analytics.', style: TextStyle(fontSize: 11, color: AppColors.textSecondary))),
        ]))),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Confirm')),
        ],
      )),
    );
    if (ok != true) return;
    final lines = <Map<String, dynamic>>[];
    ctls.forEach((id, c) {
      final q = double.tryParse(c.text.trim()) ?? 0;
      if (q > 0) lines.add({'inventory_id': id, 'qty_received': q});
    });
    if (lines.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('Enter quantities to receive.')));
      return;
    }
    try {
      await widget.rest.post('/purchase-orders/${po['id']}/receive', {'lines': lines, if (qualityRating >= 1) 'quality_rating': qualityRating});
      messenger.showSnackBar(const SnackBar(content: Text('Stock received.')));
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }
}

Widget attendanceModule(RestClient rest, Profile p) => _AttendanceView(rest: rest, profile: p);

class _AttendanceView extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  const _AttendanceView({required this.rest, required this.profile});
  @override
  State<_AttendanceView> createState() => _AttendanceViewState();
}

class _AttendanceViewState extends State<_AttendanceView> with CachePrimedScreen {
  bool _loading = true;
  bool _hasData = false;
  bool _busy = false;
  String? _error;
  Map<String, dynamic> _me = {};
  List _team = [];
  List _pending = [];

  /// The window GET /attendance actually summarised, as it sent it back. The
  /// team cards are totals over this range, so the detail has to name it rather
  /// than let "last 30 days" in a heading stand in for the server's answer.
  String _from = '';
  String _to = '';

  bool get _isManager =>
      widget.profile.role == 'admin' || widget.profile.roleAll.contains('admin') ||
      widget.profile.role == 'manager' || widget.profile.roleAll.contains('manager');

  /// Per-employee punctuality, keyed by employee id, resolved at most once per
  /// screen and only when a sheet that shows it is actually opened.
  ///
  /// GET /attendance carries hours and shift counts but nothing to judge a START
  /// TIME against — "late" needs a baseline, and the median first clock-in that
  /// defines it is computed by /analytics/advanced. That is a second request, so
  /// it is not paid on page load for a screen whose own data is already here.
  Future<({Map<String, Map> byEmp, String? error})>? _punctualityOnce;

  /// The advanced-analytics read is gated on the SAME action id the backend
  /// guards it with, so a login without it is told plainly rather than sent to
  /// collect a 403.
  bool get _canReadPunctuality =>
      _holdsAction(widget.profile, _analyticsPermissionId) && widget.profile.featureEnabled('analytics');

  /// Resolves to a RESULT, never to an error. The future is created while a
  /// sheet's children are being built and is only subscribed to a frame later,
  /// when the dialog mounts — so a failure landing in that gap (offline, an
  /// instant 403) would be an unhandled async error rather than the message the
  /// builder is there to show.
  Future<({Map<String, Map> byEmp, String? error})> _punctuality() =>
      _punctualityOnce ??= widget.rest.getMap('/analytics/advanced?days=30').then(
        (m) => (
          byEmp: <String, Map>{
            for (final r in (m['staff_attendance'] as List?) ?? const [])
              // emp_id is what StaffAttendanceStat carries; employee_id is read
              // too so a row from the other staff-analytics shape still keys.
              if (r is Map) '${r['emp_id'] ?? r['employee_id'] ?? ''}': r,
          }..remove(''),
          error: null,
        ),
        onError: (Object e) => (byEmp: <String, Map>{}, error: '$e'),
      );

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: _fetch,
      apply: (d) { _apply(d); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  /// Side-effect-free GET composition — replayable against the persisted cache
  /// at boot and the network path of every [_load].
  Future<({Map<String, dynamic> me, List team, List pending, String from, String to})> _fetch() async {
    final me = await widget.rest.getMap('/attendance/me');
    List team = const [];
    List pending = const [];
    var from = '';
    var to = '';
    if (_isManager) {
      final t = await widget.rest.getMap('/attendance').catchError((_) => <String, dynamic>{});
      team = (t['rows'] as List?) ?? const [];
      pending = (t['pending'] as List?) ?? const [];
      from = _s(t, 'from', '');
      to = _s(t, 'to', '');
    }
    return (me: me, team: team, pending: pending, from: from, to: to);
  }

  void _apply(({Map<String, dynamic> me, List team, List pending, String from, String to}) d) {
    _me = d.me;
    _team = d.team;
    _pending = d.pending;
    _from = d.from;
    _to = d.to;
    _hasData = true;
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) setState(() { _loading = true; _error = null; });
    try {
      final d = await _fetch();
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _apply(d);
        _loading = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      if (_hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() { _error = '$e'; _loading = false; });
    }
  }

  String _hm(int mins) => '${mins ~/ 60}h ${mins % 60}m';

  /// Length of a shift in minutes — an open one measured to now. A duration is
  /// a difference between two instants, so it is computed on the raw
  /// timestamps; only the clock TIMES either side of it are rendered in the
  /// restaurant's zone.
  int? _shiftMinutes(String clockIn, String clockOut) {
    final from = DateTime.tryParse(clockIn.trim());
    if (from == null) return null;
    final to = clockOut.trim().isEmpty ? DateTime.now() : DateTime.tryParse(clockOut.trim());
    if (to == null) return null;
    final mins = to.toUtc().difference(from.toUtc()).inMinutes;
    return mins < 0 ? 0 : mins;
  }

  /// Approve or reject a pending clock-in. The backend gates both on the
  /// existing 'Review Attendance' permission — this is the same call the row
  /// buttons make, kept in one place so the detail sheet cannot drift from it.
  Future<void> _review(Map m, bool ok) async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await widget.rest.post('/attendance/${m['id']}/${ok ? 'approve' : 'reject'}');
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  /// Punctuality for one employee, filled in when the analytics read lands.
  ///
  /// A [FutureBuilder] INSIDE the sheet rather than an await before it opens:
  /// everything else on these sheets is already in hand, and making the tap wait
  /// on the network to show data the screen already holds is the worse trade.
  ///
  /// [baselineOnly] is the shift view — just the median start this person's
  /// clock-ins are measured against, so a single shift can be read against it.
  /// The full block is the roll-up view, and every verdict in it ("late", "absent")
  /// is the SERVER's: none is recomputed here, because a threshold duplicated in
  /// the client is a threshold that will one day disagree with the payslip.
  Widget _punctualityBlock(String empId, {bool baselineOnly = false}) {
    if (empId.isEmpty) return const SizedBox.shrink();
    final text = Theme.of(context).textTheme;
    if (!_canReadPunctuality) {
      return Text('Punctuality needs the analytics permission, which this login does not hold.',
          style: text.bodySmall);
    }
    return FutureBuilder<({Map<String, Map> byEmp, String? error})>(
      future: _punctuality(),
      builder: (context, snap) {
        final small = Theme.of(context).textTheme.bodySmall;
        final done = snap.data;
        if (done == null) return Text('Reading punctuality…', style: small);
        // Reported, never swallowed: an empty block here is indistinguishable
        // from "this person is never late", which is the opposite claim.
        if (done.error != null) {
          return Text("Punctuality couldn't be loaded: ${done.error}", style: small);
        }
        final r = done.byEmp[empId];
        final typical = r == null ? '' : _s(r, 'typical_start', '');
        final hasBaseline = typical.isNotEmpty && typical != '—';
        if (baselineOnly) {
          return Text(
            hasBaseline
                ? 'This person usually starts around $typical — the median first clock-in '
                    'over the last 30 days, in restaurant time.'
                : 'No usual start time yet: too few worked days in the last 30 to set a '
                    'baseline, so this clock-in cannot be called early or late.',
            style: small,
          );
        }
        if (r == null) {
          return Text('No punctuality record in the last 30 days.', style: small);
        }
        final late = _int(r['late_shifts']) ?? 0;
        final latePct = r['late_pct'];
        final absent = _int(r['absent_days']) ?? 0;
        final excused = _int(r['leave_days']) ?? 0;
        final present = _int(r['days_present']) ?? 0;
        return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          _kv('Usual start', hasBaseline ? typical : 'No baseline yet'),
          _kv('Late starts',
              hasBaseline
                  ? '$late${latePct == null ? '' : ' · ${_numOf(latePct).toStringAsFixed(0)}% of shifts'}'
                  : '—'),
          _kv('Days present', '$present'),
          _kv('Excused by leave', '$excused'),
          _kv('Absent, unexplained', '$absent'),
          const SizedBox(height: 10),
          Text(
            'Late is measured against this person\'s own usual start, not a rota — '
            'there is no scheduled start time in the system to compare against. '
            'Approved leave is already taken out of the absent count.',
            style: small,
          ),
        ]);
      },
    );
  }

  /// The full record behind a pending-approval card: who, when they clocked in
  /// (restaurant time, spelled out with its offset), whether the shift is still
  /// open, how long it has run, the baseline it can be read against — and the
  /// review actions themselves, so the decision can be made from the detail
  /// rather than from the summary row.
  void _pendingSheet(Map m) {
    final clockIn = _s(m, 'clock_in', '');
    final clockOut = _s(m, 'clock_out', '');
    final mins = _shiftMinutes(clockIn, clockOut);
    // 16h is the cap payroll and staff analytics both credit a single shift at,
    // so past it this screen's length and every other figure for the same shift
    // stop agreeing. Almost always a missed clock-out rather than a real shift.
    final runaway = clockOut.isEmpty && mins != null && mins > 16 * 60;
    _detailSheet(
      context,
      eyebrow: 'Attendance · pending approval',
      title: _s(m, 'name', 'Employee'),
      children: [
        _kv('Clocked in', clockIn.isEmpty ? '—' : RestaurantTime.stamp(clockIn)),
        _kv('Clocked out', clockOut.isEmpty ? 'Still on shift' : RestaurantTime.stamp(clockOut)),
        _kv('Length', mins == null ? '—' : '${_hm(mins)}${clockOut.isEmpty ? ' so far' : ''}'),
        _kv('Status', 'Awaiting approval'),
        const SizedBox(height: 14),
        _punctualityBlock(_s(m, 'emp_id', ''), baselineOnly: true),
        if (runaway) ...[
          const SizedBox(height: 10),
          Text(
            'Still open after more than 16 hours. Payroll and staff analytics both '
            'credit a shift at 16 hours, so approving this as it stands records a '
            'length nothing else will agree with — check for a missed clock-out first.',
            style: Theme.of(context).textTheme.bodySmall?.copyWith(color: AppColors.warning),
          ),
        ],
        const SizedBox(height: 14),
        Text(
          'Approving keeps the clock-in time above exactly as recorded — the '
          'decision is stamped separately.',
          style: Theme.of(context).textTheme.bodySmall,
        ),
        const SizedBox(height: 10),
        Wrap(spacing: 8, runSpacing: 8, children: [
          ForkButton(
            label: 'Approve',
            icon: Icons.check,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _review(m, true);
            },
          ),
          ForkButton.ghost(
            label: 'Reject',
            icon: Icons.close,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _review(m, false);
            },
          ),
        ]),
      ],
    );
  }

  /// A team member's roll-up. GET /attendance summarises per EMPLOYEE — total
  /// minutes, shift count, whether one is open — so this states exactly that
  /// and the window it covers. There is no per-shift endpoint behind it and no
  /// action a manager can take on a total, so none is offered.
  ///
  /// The punctuality block is what stops this from being the row read twice:
  /// hours and shifts are on the card, but whether those shifts started on time
  /// and how many open days went unexplained are not, and cannot be — they come
  /// from a different read (see [_punctualityBlock]).
  void _teamSheet(Map m) {
    final mins = (num.tryParse('${m['minutes'] ?? 0}') ?? 0).toInt();
    final shifts = (num.tryParse('${m['shifts'] ?? 0}') ?? 0).toInt();
    final open = m['open'] == true;
    final range = (_from.isEmpty || _to.isEmpty) ? '' : '${_fmtDay(_from)} – ${_fmtDay(_to)}';
    _detailSheet(
      context,
      eyebrow: 'Attendance · team hours',
      title: _s(m, 'name', 'Employee'),
      children: [
        _kv('Hours', _hm(mins)),
        _kv('Shifts', '$shifts'),
        _kv('Average shift', shifts == 0 ? '—' : _hm(mins ~/ shifts)),
        _kv('Right now', open ? 'On shift' : 'Off shift'),
        if (range.isNotEmpty) _kv('Period', range),
        const SizedBox(height: 14),
        Text(
          'Totals count approved shifts only — a pending or rejected clock-in '
          'adds nothing here. An open shift is counted up to this moment.',
          style: Theme.of(context).textTheme.bodySmall,
        ),
        const SizedBox(height: AppSpacing.lg),
        SectionHeader(title: 'Punctuality — last 30 days', padding: const EdgeInsets.only(bottom: 8)),
        _punctualityBlock(_s(m, 'emp_id', '')),
      ],
    );
  }

  /// The people behind a summary tile. Each row opens that person's own detail,
  /// so the tile leads to the set AND the set leads on — a list that dead-ends
  /// is the same complaint one level down.
  void _peopleSheet({
    required String eyebrow,
    required String title,
    required String note,
    required List rows,
    required String Function(Map) subOf,
    required String Function(Map) trailingOf,
    required void Function(Map) open,
  }) {
    _detailSheet(
      context,
      eyebrow: eyebrow,
      title: title,
      children: [
        Text(note, style: Theme.of(context).textTheme.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        for (final x in rows)
          if (x is Map)
            _sheetRecordRow(
              context,
              title: _s(x, 'name', 'Employee'),
              sub: subOf(x),
              trailing: trailingOf(x),
              onTap: () {
                // Replace rather than stack: two dialogs deep, "Close" would
                // drop the reader back onto a list they have finished with.
                Navigator.of(context).pop();
                open(x);
              },
            ),
      ],
    );
  }

  /// My own day. The card above states the total and the strip below states
  /// "clocked in since 18:40"; what neither can hold is the FULL stamp with its
  /// offset, what the total does and does not count, and my own punctuality.
  void _mySheet() {
    final clockedIn = _me['clocked_in'] == true;
    final since = _s(_me, 'since', '');
    final mins = (num.tryParse('${_me['today_minutes'] ?? 0}') ?? 0).toInt();
    _detailSheet(
      context,
      eyebrow: 'Attendance · my day',
      title: RestaurantTime.day(RestaurantTime.todayIso()),
      children: [
        _kv('Hours today', _hm(mins)),
        _kv('Right now', clockedIn ? 'On shift' : 'Off shift'),
        _kv('Since', since.isEmpty ? '—' : RestaurantTime.stamp(since)),
        _kv('Timezone', RestaurantTime.zoneLabel()),
        if (_me['pending_approval'] == true) _kv('Approval', 'One clock-in today is awaiting review'),
        const SizedBox(height: 14),
        Text(
          'Every shift you started today is added together. A rejected clock-in is '
          'left out; an open shift is counted up to this moment, so this figure '
          'keeps rising while you are on it.',
          style: Theme.of(context).textTheme.bodySmall,
        ),
        const SizedBox(height: AppSpacing.lg),
        SectionHeader(title: 'My punctuality — last 30 days', padding: const EdgeInsets.only(bottom: 8)),
        _punctualityBlock(widget.profile.employeeId),
        const SizedBox(height: 14),
        Align(
          alignment: Alignment.centerLeft,
          child: ForkButton(
            label: clockedIn ? 'Clock out' : 'Clock in',
            icon: clockedIn ? Icons.logout : Icons.login,
            dense: true,
            onPressed: _busy
                ? null
                : () {
                    Navigator.of(context).pop();
                    _toggle(!clockedIn);
                  },
          ),
        ),
      ],
    );
  }

  Future<void> _toggle(bool clockIn) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await widget.rest.post(clockIn ? '/attendance/clock-in' : '/attendance/clock-out');
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load attendance',
        error: '$_error',
        onRetry: _load,
      );
    }
    final clockedIn = _me['clocked_in'] == true;
    final todayMins = (num.tryParse('${_me['today_minutes'] ?? 0}') ?? 0).toInt();
    final sinceLabel = _fmtClock(_s(_me, 'since'));
    final text = Theme.of(context).textTheme;
    final narrow = MediaQuery.sizeOf(context).width < 760;
    final onShiftNow = _team.where((t) => (t as Map)['open'] == true).length;

    String initialsOf(String name) {
      final parts = name.trim().split(RegExp(r'\s+')).where((s) => s.isNotEmpty).toList();
      if (parts.isEmpty) return '?';
      return parts.length == 1
          ? parts.first.substring(0, 1)
          : '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}';
    }

    return cacheStaleOverlay(RefreshIndicator(
      onRefresh: _load,
      child: ListView(padding: AppSpacing.pageNarrow, children: [
        _dashGrid([
          StatCard(
            value: _hm(todayMins),
            caption: 'HOURS TODAY',
            tag: clockedIn ? 'On shift' : null,
            tagColor: AppColors.copperHi,
            onTap: _mySheet,
          ),
          if (_isManager)
            StatCard(
              value: '${_pending.length}',
              caption: 'PENDING APPROVALS',
              tag: _pending.isNotEmpty ? 'Review' : null,
              tagColor: AppColors.warning,
              // Nothing waiting is nothing to open. An empty list behind a tap
              // is the dead end the tap was added to remove, so at zero this
              // reads as the plain number it is — no cursor, no lift, no chevron.
              onTap: _pending.isEmpty
                  ? null
                  : () => _peopleSheet(
                        eyebrow: 'Attendance · pending approval',
                        title: '${_pending.length} clock-in${_pending.length == 1 ? '' : 's'} awaiting review',
                        note: 'Each one is already recorded — approving confirms the time as '
                            'clocked, it does not set it. Open a name to review it.',
                        rows: _pending,
                        subOf: (x) {
                          final t = _fmtTime(_s(x, 'clock_in', ''));
                          return x['clock_out'] == null
                              ? 'In $t · still on shift'
                              : 'In $t · out ${_fmtTime(_s(x, 'clock_out', ''))}';
                        },
                        trailingOf: (x) {
                          final mins = _shiftMinutes(_s(x, 'clock_in', ''), _s(x, 'clock_out', ''));
                          return mins == null ? '' : _hm(mins);
                        },
                        open: _pendingSheet,
                      ),
            ),
          if (_isManager)
            StatCard(
              value: '$onShiftNow',
              caption: 'ON SHIFT NOW',
              onTap: onShiftNow == 0
                  ? null
                  : () => _peopleSheet(
                        eyebrow: 'Attendance · on shift',
                        title: '$onShiftNow on shift now',
                        note: 'Clocked in with no clock-out yet, over ${_from.isEmpty ? 'the summarised window' : '${_fmtDay(_from)} – ${_fmtDay(_to)}'}. '
                            'Hours shown are this window\'s total, not the open shift alone.',
                        rows: [for (final t in _team) if ((t as Map)['open'] == true) t],
                        subOf: (x) => '${x['shifts'] ?? 0} shift${_int(x['shifts']) == 1 ? '' : 's'} in the window',
                        trailingOf: (x) => _hm((num.tryParse('${x['minutes'] ?? 0}') ?? 0).toInt()),
                        open: _teamSheet,
                      ),
            ),
        ], narrow ? 1 : (_isManager ? 3 : 1)),
        const SizedBox(height: 14),
        ForkCard(
          // Same detail as the tile above it. The clock button keeps its own tap
          // — a control inside a tappable card still wins its own gesture — so
          // this adds a way to read the day without changing how to record it.
          onTap: _mySheet,
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              AnimatedContainer(
                duration: AppDurations.base,
                curve: Curves.easeOut,
                width: 40,
                height: 40,
                decoration: BoxDecoration(
                  color: clockedIn ? AppColors.tint(AppColors.copper) : AppColors.inset,
                  borderRadius: AppRadius.controlAll,
                  border: Border.all(color: clockedIn ? AppColors.edge(AppColors.copper) : AppColors.border),
                ),
                child: Icon(clockedIn ? Icons.work_outline : Icons.work_off_outlined,
                    size: 16, color: clockedIn ? AppColors.copper : AppColors.textTertiary),
              ),
              const SizedBox(width: AppSpacing.md),
              Expanded(
                child: Text(
                  clockedIn ? 'Clocked in${sinceLabel.isNotEmpty ? ' · since $sinceLabel' : ''}' : 'Not clocked in',
                  style: text.titleMedium,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(width: AppSpacing.md),
              AnimatedSwitcher(
                duration: AppDurations.base,
                switchInCurve: Curves.easeOut,
                switchOutCurve: Curves.easeIn,
                child: StatusChip(
                  key: ValueKey('me-shift-$clockedIn'),
                  label: clockedIn ? 'On shift' : 'Off shift',
                  color: clockedIn ? AppColors.copper : AppColors.neutral,
                  dense: narrow,
                ),
              ),
            ]),
            if (_me['pending_approval'] == true)
              Padding(
                padding: const EdgeInsets.only(top: AppSpacing.sm),
                child: Row(children: [
                  Icon(Icons.hourglass_top, size: 13, color: AppColors.warning),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text('Awaiting admin approval — your clock-in time is already recorded.',
                        style: text.bodySmall!.copyWith(color: AppColors.warning)),
                  ),
                ]),
              ),
            const SizedBox(height: AppSpacing.md),
            Align(
              alignment: Alignment.centerRight,
              child: ForkButton(
                label: _busy ? '…' : (clockedIn ? 'Clock out' : 'Clock in'),
                icon: clockedIn ? Icons.logout : Icons.login,
                onPressed: _busy ? null : () => _toggle(!clockedIn),
              ),
            ),
          ]),
        ),
        if (_isManager && _pending.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.xxl),
          SectionHeader(title: 'Pending approval', count: _pending.length, padding: const EdgeInsets.only(bottom: 4)),
          Text('Approving keeps the employee\'s original clock-in time.', style: text.bodySmall),
          const SizedBox(height: AppSpacing.md),
          ..._pending.map((x) {
            final m = x as Map;
            final label = _fmtTime(_s(m, 'clock_in'));
            return Padding(
              padding: const EdgeInsets.only(bottom: 10),
              child: ForkCard(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                // The row shows a start time and a state; the shift itself —
                // full timestamps, how long it has run, and the same review
                // actions — is one tap away.
                onTap: () => _pendingSheet(m),
                // The two review buttons are non-flex, so on a 390px phone at
                // 1.3x they took 43px more than the row had and the name column
                // could not give it back. Stacked, both halves get the width.
                child: _recordHeadRow(
                  context,
                  leading: InitialsAvatar(initials: initialsOf(_s(m, 'name', '')), color: AppColors.warning),
                  identity: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                    Text(_s(m, 'name', 'Employee'),
                        style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                    const SizedBox(height: 6),
                    Wrap(spacing: 6, runSpacing: 6, children: [
                      if (label.isNotEmpty) InfoChip(icon: Icons.login, label: 'In $label'),
                      AnimatedSwitcher(
                        duration: AppDurations.base,
                        switchInCurve: Curves.easeOut,
                        switchOutCurve: Curves.easeIn,
                        child: m['clock_out'] == null
                            ? StatusChip(
                                key: ValueKey('att-${m['id']}-on'),
                                label: 'On shift',
                                color: AppColors.copper,
                                dense: true)
                            : StatusChip(
                                key: ValueKey('att-${m['id']}-ended'),
                                label: 'Shift ended',
                                color: AppColors.neutral,
                                dense: true),
                      ),
                    ]),
                  ]),
                  trailing: [
                    ForkButton(label: 'Approve', icon: Icons.check, dense: true, onPressed: () => _review(m, true)),
                    ForkButton.ghost(label: 'Reject', icon: Icons.close, dense: true, onPressed: () => _review(m, false)),
                  ],
                ),
              ),
            );
          }),
        ],
        if (_isManager) ...[
          const SizedBox(height: AppSpacing.xxl),
          SectionHeader(title: 'Team hours — last 30 days', count: _team.length),
          if (_team.isEmpty)
            Text('No attendance recorded yet.', style: text.bodySmall)
          else
            ..._team.map((x) {
              final m = x as Map;
              final mins = (num.tryParse('${m['minutes'] ?? 0}') ?? 0).toInt();
              final open = m['open'] == true;
              return Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: ForkCard(
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                  // Tap for the roll-up behind the two figures on the row.
                  onTap: () => _teamSheet(m),
                  // Same trap as the pending row: an hours total long enough to
                  // matter ("16460h 54m") plus a chip is more than the trailing
                  // slot has on a phone, and neither can shrink.
                  child: _recordHeadRow(
                    context,
                    leading: InitialsAvatar(initials: initialsOf(_s(m, 'name', ''))),
                    identity: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                      Text(_s(m, 'name', 'Employee'),
                          style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                      const SizedBox(height: 6),
                      Wrap(spacing: 6, runSpacing: 6, children: [
                        InfoChip(icon: Icons.event_repeat, label: '${m['shifts'] ?? 0} shifts'),
                      ]),
                    ]),
                    trailing: [
                      MicroStat(value: _hm(mins), label: 'hours', alignEnd: true),
                      if (open) StatusChip(label: 'On shift', color: AppColors.copper, dense: true),
                    ],
                  ),
                ),
              );
            }),
        ],
      ]),
    ));
  }
}

// --- Multi-outlet management -------------------------------------------------
Widget outletsModule(RestClient rest, Profile p) => _OutletsView(rest: rest, profile: p);

class _OutletsView extends StatefulWidget {
  final RestClient rest;
  final Profile profile;
  const _OutletsView({required this.rest, required this.profile});
  @override
  State<_OutletsView> createState() => _OutletsViewState();
}

class _OutletsViewState extends State<_OutletsView> with CachePrimedScreen {
  bool _loading = true;
  bool _hasData = false;
  String? _error;
  List _outlets = [];
  Map<String, dynamic> _rollup = {};

  @override
  void initState() {
    super.initState();
    unawaited(primeFromCache(
      fetch: _fetch,
      apply: (d) { _apply(d); _loading = false; _error = null; },
      refresh: () => _load(silent: true),
      fallback: _load,
    ));
  }

  /// Side-effect-free GET composition — replayable against the persisted cache
  /// at boot and the network path of every [_load].
  Future<({List outlets, Map<String, dynamic> rollup})> _fetch() async {
    final outlets = await widget.rest.getMap('/outlets');
    final rollup = await widget.rest.getMap('/outlets/rollup?days=30').catchError((_) => <String, dynamic>{});
    return (outlets: (outlets['outlets'] as List?) ?? [], rollup: rollup);
  }

  void _apply(({List outlets, Map<String, dynamic> rollup}) d) {
    _outlets = d.outlets;
    _rollup = d.rollup;
    _hasData = true;
  }

  Future<void> _load({bool silent = false}) async {
    final gen = bumpCacheGen();
    if (!silent) {
      setState(() {
        _loading = true;
        _error = null;
      });
    }
    try {
      final d = await _fetch();
      if (!mounted || !cacheGenIs(gen)) return;
      setState(() {
        _apply(d);
        _loading = false;
        _error = null;
        markCacheLive();
      });
    } catch (e) {
      if (!mounted || !cacheGenIs(gen)) return;
      if (_hasData) {
        setState(() { _loading = false; markCacheOffline(); });
        return;
      }
      setState(() {
        _error = '$e';
        _loading = false;
      });
    }
  }

  Future<void> _outletDialog({Map? existing}) async {
    final messenger = ScaffoldMessenger.of(context);
    final name = TextEditingController(text: existing == null ? '' : _s(existing, 'outlet_name'));
    final addr = TextEditingController(text: existing == null ? '' : _s(existing, 'outlet_add'));
    final phone = TextEditingController(text: existing == null ? '' : _s(existing, 'outlet_phone'));
    final hours = TextEditingController(text: existing == null ? '' : _s(existing, 'outlet_hours'));
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => Dialog(
        backgroundColor: Colors.transparent,
        child: Container(
          width: 400,
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            gradient: AppColors.cardGradient,
            borderRadius: AppRadius.cardAll,
            border: Border.all(color: AppColors.borderStrong),
          ),
          child: SingleChildScrollView(
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('MULTI-OUTLET', style: Theme.of(ctx).textTheme.labelSmall),
              const SizedBox(height: 6),
              Text(existing == null ? 'Add outlet' : 'Edit outlet', style: Theme.of(ctx).textTheme.titleMedium),
              const SizedBox(height: AppSpacing.lg),
              TextField(controller: name, autofocus: true, decoration: const InputDecoration(labelText: 'Outlet name', isDense: true)),
              const SizedBox(height: AppSpacing.sm),
              TextField(controller: addr, decoration: const InputDecoration(labelText: 'Address (optional)', isDense: true)),
              const SizedBox(height: AppSpacing.sm),
              TextField(controller: phone, keyboardType: TextInputType.phone, decoration: const InputDecoration(labelText: 'Phone (optional)', isDense: true)),
              const SizedBox(height: AppSpacing.sm),
              TextField(controller: hours, decoration: const InputDecoration(labelText: 'Hours (optional)', isDense: true)),
              const SizedBox(height: AppSpacing.xl),
              Row(mainAxisAlignment: MainAxisAlignment.end, children: [
                ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
                const SizedBox(width: AppSpacing.sm),
                ForkButton(
                  label: existing == null ? 'Add' : 'Save',
                  icon: Icons.check,
                  onPressed: () => Navigator.pop(ctx, true),
                ),
              ]),
            ]),
          ),
        ),
      ),
    );
    if (ok != true) return;
    if (name.text.trim().isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('Outlet name is required.')));
      return;
    }
    final body = {
      'name': name.text.trim(),
      'address': addr.text.trim(),
      'phone': phone.text.trim(),
      'hours': hours.text.trim(),
    };
    try {
      if (existing == null) {
        await widget.rest.post('/outlets', body);
      } else {
        await widget.rest.put('/outlets/${existing['id']}', body);
      }
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _toggleActive(Map o) async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await widget.rest.post('/outlets/${o['id']}/active', {'active': o['is_active'] == false});
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  Future<void> _delete(Map o) async {
    final messenger = ScaffoldMessenger.of(context);
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete outlet?'),
        content: Text('Delete "${_s(o, 'outlet_name')}"? Only possible if it has no orders/bills.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), style: FilledButton.styleFrom(backgroundColor: AppColors.danger), child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await widget.rest.delete('/outlets/${o['id']}');
      await _load();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Only admins/managers may switch the app into another outlet (mirrors the
  // app-bar outlet switcher gate in home_shell).
  bool get _canSwitchOutlet {
    final p = widget.profile;
    return p.role == 'admin' ||
        p.roleAll.contains('admin') ||
        p.role == 'manager' ||
        p.roleAll.contains('manager');
  }

  // The outlet the app is currently scoped to. A null selection means the
  // session's home outlet (the default one); 'all' is the combined read-only
  // view, where no single outlet is "active".
  bool _isCurrentOutlet(Map o) {
    final sel = widget.rest.auth.selectedOutletId;
    if (sel == null || sel.isEmpty) return o['is_default'] == true;
    if (sel == 'all') return false;
    return '${o['id']}' == sel;
  }

  // Switch the whole app into [o]: persist the outlet + set X-Outlet-Id (via
  // AuthController.selectOutlet), rejoin the realtime printer subscription for
  // that outlet, and refetch so this view's active indicator + rollup update.
  // Other modules re-scope to this outlet the next time they are opened.
  Future<void> _switchToOutlet(Map o) async {
    final messenger = ScaffoldMessenger.of(context);
    final id = '${o['id']}';
    if (id.isEmpty || _isCurrentOutlet(o)) return;
    widget.rest.auth.selectOutlet(id);
    try {
      await PrinterService.instance.stop();
      await PrinterService.instance.start(widget.rest.auth);
    } catch (_) {/* printer agent optional */}
    if (!mounted) return;
    messenger.showSnackBar(SnackBar(
        content: Text('Now viewing ${_s(o, 'outlet_name', 'this outlet')}. Other modules will show this outlet\'s data.')));
    await _load();
  }

  /// Everything the card ellipses — address, phone, hours, 30-day revenue, what
  /// "Main" means — plus the actions that already exist for this outlet. Tap
  /// used to switch the whole app straight from the card; switching is now a
  /// named button here (and still on the card), because re-scoping every other
  /// module is not what a stray tap on a list should do.
  ///
  /// Nothing new is offered: switching keeps the admin/manager gate the app-bar
  /// switcher holds, and edit / activate / delete are the same calls the card's
  /// menu makes, which the backend gates on its own.
  void _outletSheet(Map o, {double? revenue, int? orders}) {
    final isDefault = o['is_default'] == true;
    final active = o['is_active'] != false;
    final current = _isCurrentOutlet(o);
    _detailSheet(
      context,
      eyebrow: 'Multi-outlet',
      title: _s(o, 'outlet_name', 'Outlet'),
      children: [
        _kv('Status', current ? 'Viewing now' : (active ? 'Active' : 'Inactive')),
        _kv('Role', isDefault ? 'Main outlet — the default this login lands on' : 'Branch'),
        _kv('Address', _s(o, 'outlet_add', '—')),
        _kv('Phone', _s(o, 'outlet_phone', '—')),
        _kv('Hours', _s(o, 'outlet_hours', '—')),
        _kv('Revenue (30d)', revenue == null ? 'Not in the roll-up' : '₹${revenue.toStringAsFixed(0)}'),
        _kv('Orders (30d)', orders == null ? 'Not in the roll-up' : '$orders'),
        _kv('Average order', (revenue == null || orders == null || orders == 0)
            ? '—'
            : '₹${(revenue / orders).toStringAsFixed(0)}'),
        const SizedBox(height: 14),
        Wrap(spacing: 8, runSpacing: 8, children: [
          if (_canSwitchOutlet && !current)
            ForkButton(
              label: 'Switch to this outlet',
              icon: Icons.login,
              dense: true,
              onPressed: () {
                Navigator.of(context).pop();
                _switchToOutlet(o);
              },
            ),
          ForkButton.ghost(
            label: 'Edit',
            icon: Icons.edit_outlined,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _outletDialog(existing: o);
            },
          ),
          // The main outlet can be neither deactivated nor deleted — the card's
          // own menu hides both for exactly that reason.
          if (!isDefault)
            ForkButton.ghost(
              label: active ? 'Deactivate' : 'Activate',
              icon: active ? Icons.pause_circle_outline : Icons.play_circle_outline,
              dense: true,
              onPressed: () {
                Navigator.of(context).pop();
                _toggleActive(o);
              },
            ),
          if (!isDefault)
            ForkButton.ghost(
              label: 'Delete',
              icon: Icons.delete_outline,
              dense: true,
              onPressed: () {
                Navigator.of(context).pop();
                _delete(o);
              },
            ),
        ]),
      ],
    );
  }

  /// The 30-day roll-up keyed by outlet id — the join both the cards and the
  /// stat drill-downs read, so a branch cannot be ranked on one figure here and
  /// shown another there.
  Map<String, Map> get _rollupById => <String, Map>{
        for (final o in (_rollup['outlets'] as List?) ?? const [])
          if (o is Map) _s(o, 'outlet_id', ''): o,
      }..remove('');

  /// Every branch behind one group figure, ranked by it, each row opening that
  /// outlet's own detail — the tile leads to the set and the set leads on.
  ///
  /// A branch the roll-up did not return says so rather than reading as a zero
  /// nobody reported, and it sorts last instead of claiming the bottom rank.
  void _branchesSheet({
    required String title,
    required String note,
    required double Function(Map roll) rankBy,
    required String Function(Map? roll) trailingOf,
    required String Function(Map? roll) subOf,
  }) {
    final roll = _rollupById;
    final rows = [for (final o in _outlets) if (o is Map) o];
    rows.sort((a, b) {
      final ra = roll['${a['id']}'], rb = roll['${b['id']}'];
      if (ra == null || rb == null) return ra == null ? (rb == null ? 0 : 1) : -1;
      return rankBy(rb).compareTo(rankBy(ra));
    });
    _detailSheet(
      context,
      eyebrow: 'Multi-outlet · last 30 days',
      title: title,
      children: [
        Text(note, style: Theme.of(context).textTheme.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        for (final o in rows)
          _sheetRecordRow(
            context,
            title: _s(o, 'outlet_name', 'Outlet'),
            badge: _isCurrentOutlet(o)
                ? StatusChip(label: 'Viewing', color: AppColors.copper, dense: true)
                : (o['is_active'] == false
                    ? StatusChip(label: 'Inactive', color: AppColors.neutral, dense: true)
                    : null),
            sub: subOf(roll['${o['id']}']),
            trailing: trailingOf(roll['${o['id']}']),
            onTap: () {
              Navigator.of(context).pop();
              final r = roll['${o['id']}'];
              _outletSheet(o, revenue: r == null ? null : _numOf(r['revenue']), orders: r == null ? null : _int(r['orders']));
            },
          ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) return _loadingSkeleton();
    if (_error != null) {
      return LoadErrorState(
        whatFailed: 'Could not load outlets',
        error: '$_error',
        onRetry: _load,
      );
    }

    final text = Theme.of(context).textTheme;
    final narrow = MediaQuery.sizeOf(context).width < 760;
    final outletHint =
        _canSwitchOutlet ? 'Tap an outlet for details and to switch' : 'Tap an outlet for details';
    final totals = (_rollup['totals'] as Map?) ?? {};
    final rollupOutlets = (_rollup['outlets'] as List?) ?? [];
    String money(double v) => '₹${v.toStringAsFixed(0)}';
    double n(dynamic v) => (v is num) ? v.toDouble() : (double.tryParse('${v ?? ''}') ?? 0);
    final compare = rollupOutlets
        .map((o) => (label: _s(o as Map, 'name', 'Outlet'), value: n(o['revenue'])))
        .toList();
    // Keyed on outlet_id, which the roll-up does carry. Keyed on NAME — as this
    // was — two branches sharing a name collapse onto one entry and both cards
    // show the second one's takings.
    final rollupById = <String, Map>{
      for (final o in rollupOutlets)
        if (o is Map) _s(o, 'outlet_id', ''): o,
    }..remove('');

    final outletCards = _outlets.map<Widget>((x) {
      final o = x as Map;
      final isDefault = o['is_default'] == true;
      final active = o['is_active'] != false;
      final current = _isCurrentOutlet(o);
      final roll = rollupById['${o['id']}'];
      final rev = roll == null ? null : n(roll['revenue']);
      // Already fetched with the revenue and never shown until now — a branch's
      // order count is half of what "how is it doing" means.
      final orders = roll == null ? null : (_int(roll['orders']) ?? 0);
      return ForkCard(
        // Copper selection ring marks the outlet the app is scoped to — always
        // paired with the labelled "Viewing" chip (never colour alone).
        selected: current,
        // Every outlet opens its detail — including the one being viewed, which
        // had no tap at all before. Switching lives inside it, and on the card's
        // own "Open" button for whoever is allowed to switch.
        onTap: () => _outletSheet(o, revenue: rev, orders: orders),
        padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
          Row(children: [
            AnimatedContainer(
              duration: AppDurations.base,
              curve: Curves.easeOut,
              width: 38,
              height: 38,
              decoration: BoxDecoration(
                color: current ? AppColors.tint(AppColors.copper) : AppColors.inset,
                borderRadius: AppRadius.controlAll,
                border: Border.all(color: current ? AppColors.edge(AppColors.copper) : AppColors.border),
              ),
              child: Icon(Icons.store_mall_directory_outlined,
                  size: 16,
                  color: current
                      ? AppColors.copper
                      : (active ? AppColors.textSecondary : AppColors.textTertiary)),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                Row(children: [
                  Flexible(
                    child: Text(_s(o, 'outlet_name', 'Outlet'),
                        style: text.titleMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
                  ),
                  if (isDefault) ...[
                    const SizedBox(width: 8),
                    TickTag('Main', color: AppColors.copper),
                  ],
                ]),
                if (_s(o, 'outlet_add').isNotEmpty) ...[
                  const SizedBox(height: 3),
                  Text(_s(o, 'outlet_add'), style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                ],
              ]),
            ),
            const SizedBox(width: AppSpacing.sm),
            AnimatedSwitcher(
              duration: AppDurations.base,
              switchInCurve: Curves.easeOut,
              switchOutCurve: Curves.easeIn,
              child: current
                  ? StatusChip(
                      key: ValueKey('outlet-${o['id']}-viewing'),
                      label: 'Viewing',
                      color: AppColors.copper,
                      dense: true)
                  : !active
                      ? StatusChip(
                          key: ValueKey('outlet-${o['id']}-inactive'),
                          label: 'Inactive',
                          color: AppColors.neutral,
                          dense: true)
                      : StatusChip(
                          key: ValueKey('outlet-${o['id']}-active'),
                          label: 'Active',
                          color: AppColors.success,
                          dense: true),
            ),
            PopupMenuButton<String>(
              iconColor: AppColors.textSecondary,
              onSelected: (v) {
                if (v == 'edit') _outletDialog(existing: o);
                if (v == 'toggle') _toggleActive(o);
                if (v == 'delete') _delete(o);
              },
              itemBuilder: (_) => [
                const PopupMenuItem(value: 'edit', child: Text('Edit')),
                if (!isDefault) PopupMenuItem(value: 'toggle', child: Text(active ? 'Deactivate' : 'Activate')),
                if (!isDefault) const PopupMenuItem(value: 'delete', child: Text('Delete')),
              ],
            ),
          ]),
          const SizedBox(height: 12),
          // A Wrap inside the flex, not a row of non-flex stats behind a Spacer.
          // Phone and hours are free text with no length cap on the way in, and
          // MicroStat's ChipLabel only ellipsises when something above it sets a
          // width — which a Row full of intrinsic children never does. Four
          // stats and a button did not fit 390px at 1.3x. Both free-text values
          // are also cut to a glanceable length here; the sheet has them whole.
          Row(children: [
            Expanded(
              child: Wrap(spacing: AppSpacing.xl, runSpacing: AppSpacing.sm, children: [
                if (rev != null) MicroStat(value: money(rev), label: 'revenue (30d)'),
                if (orders != null) MicroStat(value: '$orders', label: 'orders (30d)'),
                if (_s(o, 'outlet_phone').isNotEmpty)
                  MicroStat(value: _capped(_s(o, 'outlet_phone'), 20), label: 'phone'),
                if (_s(o, 'outlet_hours').isNotEmpty)
                  MicroStat(value: _capped(_s(o, 'outlet_hours'), 20), label: 'hours'),
              ]),
            ),
            if (_canSwitchOutlet && !current) ...[
              const SizedBox(width: AppSpacing.sm),
              ForkButton.ghost(label: 'Open', icon: Icons.login, dense: true, onPressed: () => _switchToOutlet(o)),
            ],
          ]),
        ]),
      );
    }).toList();

    return cacheStaleOverlay(RefreshIndicator(
      onRefresh: _load,
      child: ListView(padding: AppSpacing.pageNarrow, children: [
        SectionHeader(
          title: 'Outlets',
          count: _outlets.length,
          trailing: ForkButton(label: 'Add outlet', icon: Icons.add, dense: true, onPressed: () => _outletDialog()),
        ),
        _dashGrid([
          // Deliberately inert. Its drill-down would be the list of branches —
          // which is the grid at the bottom of this very page, already carrying
          // each outlet's status and already opening each one's detail. A tap
          // here would show the same set twice and teach nothing.
          StatCard(value: '${totals['outlets'] ?? _outlets.length}', caption: 'BRANCHES'),
          StatCard(
            value: money(n(totals['revenue'])),
            caption: 'REVENUE (30D)',
            // Nothing in the roll-up is nothing to break down: the read is
            // optional (it 403s without the outlet-admin permission) and a
            // failed one must not leave a tap that opens an empty list.
            onTap: rollupOutlets.isEmpty
                ? null
                : () => _branchesSheet(
                      title: 'Revenue by branch',
                      note: 'Every branch of this restaurant, best-earning first. Cancelled '
                          'orders are already excluded. Share is of the group total.',
                      rankBy: (r) => n(r['revenue']),
                      trailingOf: (r) => r == null ? '' : money(n(r['revenue'])),
                      subOf: (r) {
                        if (r == null) return 'Not in the 30-day roll-up';
                        final total = n(totals['revenue']);
                        final share = total <= 0 ? '' : '${(n(r['revenue']) / total * 100).toStringAsFixed(0)}% of group · ';
                        final ord = _int(r['orders']) ?? 0;
                        return '$share$ord order${ord == 1 ? '' : 's'}';
                      },
                    ),
          ),
          StatCard(
            value: '${totals['orders'] ?? 0}',
            caption: 'ORDERS (30D)',
            onTap: rollupOutlets.isEmpty
                ? null
                : () => _branchesSheet(
                      title: 'Orders by branch',
                      note: 'Every branch of this restaurant, busiest first. Cancelled orders '
                          'are already excluded, so this is orders actually served.',
                      rankBy: (r) => (_int(r['orders']) ?? 0).toDouble(),
                      trailingOf: (r) => r == null ? '' : '${_int(r['orders']) ?? 0}',
                      subOf: (r) {
                        if (r == null) return 'Not in the 30-day roll-up';
                        final ord = _int(r['orders']) ?? 0;
                        final total = _int(totals['orders']) ?? 0;
                        final share = total <= 0 ? '' : '${(ord / total * 100).toStringAsFixed(0)}% of group · ';
                        return '${share}average ${ord == 0 ? '—' : money(n(r['revenue']) / ord)} per order';
                      },
                    ),
          ),
        ], narrow ? 1 : 3),
        const SizedBox(height: AppSpacing.lg),
        if (compare.length > 1) ...[
          _chartCard(context, 'Revenue by outlet — last 30 days', _barChart(context, compare, money)),
          const SizedBox(height: AppSpacing.lg),
        ],
        // The hint drops UNDER the title on a narrow window. SectionHeader lays
        // its trailing slot out at intrinsic width, and this sentence wanted
        // 146px more than a 390px phone has — pushing the header off the right
        // edge. Below the title it has the whole width and needs no truncating.
        SectionHeader(
          title: 'Manage outlets',
          padding: EdgeInsets.only(top: 8, bottom: narrow ? 4 : 10),
          trailing: narrow ? null : Text(outletHint, style: text.bodySmall),
        ),
        if (narrow)
          Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: Text(outletHint, style: text.bodySmall),
          ),
        _dashGrid(outletCards, narrow ? 1 : 2),
      ]),
    ));
  }
}

// Next valet step for a given status string → (state code, button label).
({int next, String label})? _valetNext(String status) {
  switch (status) {
    case 'Vehicle added':
      return (next: 2, label: 'Mark parked');
    case 'Parked':
      return (next: 3, label: 'Customer wants car');
    case 'Request to bring car (from customer)':
      return (next: 4, label: 'Accept request');
    case 'Request accepted (from valet)':
      return (next: 5, label: 'Car at entrance');
    case 'Car arrived at entrance':
      return (next: 6, label: 'Customer took car');
    default:
      return null;
  }
}

// A valet metadata chip. Every field behind one of these is FREE TEXT with no
// length limit on the way in — the parking-location field is a bare TextField,
// and a real attendant types "Basement level 3, pillar B14, nose out" into it —
// while the tile that shows it is one column of a grid (~340px, less on a
// phone).
//
// The cap here is about MEANING, not layout: a chip carrying a whole sentence
// tells the reader nothing at a glance, so the value is trimmed to a glanceable
// length and the full one is one tap away on the detail sheet. Fitting it to
// the column is [InfoChip]'s own job now — it ellipsises (see ChipLabel), and
// the scale-down wrapper that used to sit here would shrink the type twice.
Widget _valetChip(IconData icon, String label, {int max = 26}) =>
    InfoChip(icon: icon, label: _capped(label, max));

Widget valetModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () => rest.getMap('/valet-info'),
      builder: (context, data, reload) {
        final messenger = ScaffoldMessenger.of(context);
        final bays = (data['bays'] as List?) ?? [];
        final vehicles = (data['bookings'] as List?) ?? [];
        final active = vehicles.where((v) => (v as Map)['active'] != false).toList();

        Future<void> post(String path, Map<String, dynamic> body) async {
          try {
            await rest.post(path, body);
            reload();
          } catch (e) {
            messenger.showSnackBar(SnackBar(content: Text('$e')));
          }
        }

        // [bayId] pre-selects a bay — set when the check-in is started from an
        // empty bay's own sheet, so the attendant doesn't re-pick what they
        // just tapped.
        Future<void> checkIn({String? bayId}) async {
          final res = await showDialog<Map<String, dynamic>>(
            context: context,
            builder: (_) => _ValetCheckInDialog(bays: bays, initialBayId: bayId),
          );
          if (res != null) await post('/create_valet_record', res);
        }

        Future<void> assignBay(String id) async {
          if (bays.isEmpty) {
            messenger.showSnackBar(const SnackBar(content: Text('Add a parking bay first.')));
            return;
          }
          final bayId = await showDialog<String>(
            context: context,
            builder: (ctx) => SimpleDialog(
              title: const Text('Assign bay'),
              children: [
                for (final b in bays)
                  SimpleDialogOption(
                    onPressed: () => Navigator.pop(ctx, '${(b as Map)['Bay_id']}'),
                    child: Text(_s(b, 'Bay_name')),
                  ),
              ],
            ),
          );
          if (bayId != null) await post('/update_valet_bay', {'booking_id': id, 'bay_id': bayId});
        }

        Future<void> addBay() async {
          final name = TextEditingController();
          final cap = TextEditingController(text: '10');
          final ok = await showDialog<bool>(
            context: context,
            builder: (ctx) => AlertDialog(
              title: const Text('Add parking bay'),
              content: Column(mainAxisSize: MainAxisSize.min, children: [
                TextField(controller: name, autofocus: true, decoration: const InputDecoration(labelText: 'Bay name (e.g. Front Lot)')),
                TextField(controller: cap, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Capacity')),
              ]),
              actions: [
                TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
                FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Add')),
              ],
            ),
          );
          name.dispose();
          if (ok != true) return;
          await post('/add-valet-bay', {'Bay_name': name.text.trim(), 'total_capacity': int.tryParse(cap.text.trim()) ?? 0});
        }

        Future<void> deleteBay(Map b) async {
          if (!await _confirm(context, 'Delete bay', 'Delete "${_s(b, 'Bay_name')}"?')) return;
          await post('/delete-valet-bay', {'Bay_id': '${b['Bay_id']}'});
        }

        // --- Valet ops depth (Wave D) ---------------------------------------

        // Parking location — so ANY attendant can retrieve the car.
        Future<void> editLocation(Map m) async {
          final id = _s(m, 'booking_id');
          final c = TextEditingController(text: _s(m, 'parking_location', ''));
          final ok = await showDialog<bool>(
            context: context,
            builder: (ctx) => AlertDialog(
              title: const Text('Parking location'),
              content: TextField(
                controller: c,
                autofocus: true,
                decoration: const InputDecoration(labelText: 'e.g. P2 / Level 1 / Slot 14', border: OutlineInputBorder(), isDense: true),
              ),
              actions: [
                TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
                FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Save')),
              ],
            ),
          );
          final v = c.text.trim();
          c.dispose();
          if (ok == true) await post('/valet/$id/ops', {'parking_location': v});
        }

        // Digital key log: take = keys with me, hand over = keys leave my hands.
        Future<void> keysAction(Map m) async {
          final id = _s(m, 'booking_id');
          final holder = _s(m, 'key_holder', '');
          await post('/valet/$id/keys', {'action': holder.isEmpty ? 'take' : 'handover'});
        }

        // Damage/condition notes (+ optional photo) at drop-off or later.
        Future<void> editCondition(Map m) async {
          final id = _s(m, 'booking_id');
          final c = TextEditingController(text: _s(m, 'condition_notes', ''));
          XFile? photo;
          final ok = await showDialog<bool>(
            context: context,
            builder: (ctx) => StatefulBuilder(
              builder: (ctx, setLocal) => AlertDialog(
                title: const Text('Vehicle condition'),
                content: Column(mainAxisSize: MainAxisSize.min, children: [
                  TextField(
                    controller: c,
                    autofocus: true,
                    maxLines: 3,
                    decoration: const InputDecoration(labelText: 'Notes (scratches, dents...)', border: OutlineInputBorder(), isDense: true),
                  ),
                  const SizedBox(height: 10),
                  Align(
                    alignment: Alignment.centerLeft,
                    child: ForkButton.ghost(
                      label: photo == null ? 'Attach photo (optional)' : 'Photo attached',
                      icon: Icons.camera_alt,
                      onPressed: () async {
                        final shot = await ImagePicker().pickImage(source: ImageSource.camera, maxWidth: 1600, imageQuality: 80);
                        if (shot != null) setLocal(() => photo = shot);
                      },
                    ),
                  ),
                ]),
                actions: [
                  TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
                  FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Save')),
                ],
              ),
            ),
          );
          final notes = c.text.trim();
          c.dispose();
          if (ok != true) return;
          final body = <String, dynamic>{'condition_notes': notes};
          if (photo != null) {
            body['condition_photo_base64'] = base64Encode(await photo!.readAsBytes());
            body['condition_photo_content_type'] = 'image/jpeg';
          }
          await post('/valet/$id/ops', body);
        }

        // Retrieval ETA quoted to the guest (quick-set from the card).
        Future<void> setEta(String id, int mins) => post('/valet/$id/ops', {'eta_minutes': mins});

        // Valet fee → the table's open POS bill.
        Future<void> chargeToTable(Map m) async {
          final id = _s(m, 'booking_id');
          List targets = [];
          try {
            final r = await rest.getMap('/valet/charge-targets');
            targets = (r['tables'] as List?) ?? [];
          } catch (_) {}
          if (!context.mounted) return;
          if (targets.isEmpty) {
            messenger.showSnackBar(const SnackBar(content: Text('No occupied tables to charge right now.')));
            return;
          }
          String? tableName = _s(targets.first as Map, 'table_name', '');
          final amount = TextEditingController();
          final ok = await showDialog<bool>(
            context: context,
            builder: (ctx) => StatefulBuilder(
              builder: (ctx, setLocal) => AlertDialog(
                title: const Text('Charge valet fee to table'),
                content: Column(mainAxisSize: MainAxisSize.min, children: [
                  DropdownButtonFormField<String>(
                    initialValue: tableName,
                    isExpanded: true,
                    decoration: const InputDecoration(labelText: 'Occupied table', border: OutlineInputBorder(), isDense: true),
                    items: [
                      for (final t in targets)
                        DropdownMenuItem(value: _s(t as Map, 'table_name', ''), child: Text(_s(t, 'table_name'))),
                    ],
                    onChanged: (v) => setLocal(() => tableName = v),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: amount,
                    autofocus: true,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(labelText: 'Fee amount', border: OutlineInputBorder(), isDense: true),
                  ),
                ]),
                actions: [
                  TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
                  FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Charge')),
                ],
              ),
            ),
          );
          final amt = num.tryParse(amount.text.trim());
          amount.dispose();
          if (ok != true) return;
          if (tableName == null || tableName!.isEmpty || amt == null || amt <= 0) {
            messenger.showSnackBar(const SnackBar(content: Text('Pick a table and a positive amount.')));
            return;
          }
          await post('/valet/$id/charge', {'table_name': tableName, 'amount': amt});
        }

        // Valet stage voice — tint always paired with the labelled StatusChip.
        Color valetColor(String s) {
          final l = s.toLowerCase();
          if (l == 'parked') return AppColors.success;
          if (l.contains('request')) return AppColors.warning;
          if (l.contains('entrance')) return AppColors.copper;
          if (l.contains('took')) return AppColors.neutral;
          return AppColors.info;
        }

        // Short display label for the long backend stage strings (display only —
        // the raw status still drives _valetNext and every rest call).
        String valetLabel(String s) {
          switch (s) {
            case 'Vehicle added':
              return 'Checked in';
            case 'Request to bring car (from customer)':
              return 'Car requested';
            case 'Request accepted (from valet)':
              return 'Request accepted';
            case 'Car arrived at entrance':
              return 'At entrance';
            case 'Customer took car':
              return 'Handed over';
            default:
              return s;
          }
        }

        final text = Theme.of(context).textTheme;

        // Vehicles tile 4/3/2/1 like the Orders grid — a plate, a stage and a
        // handful of chips never needed a full desktop row each.
        final width = MediaQuery.sizeOf(context).width;
        final vehicleCols = width >= 1500 ? 4 : (width >= 1120 ? 3 : (width >= 720 ? 2 : 1));

        // Every ops action reloads the page underneath, so a sheet launched from
        // a vehicle tile steps out of the way first rather than sitting on data
        // it can't refresh (same rule the bay sheet already follows).
        void runFromSheet(VoidCallback action) {
          Navigator.of(context).pop();
          action();
        }

        // --- Clickable bays --------------------------------------------------
        // A bay used to be an inert number on a card. Tapping one now shows what
        // is actually parked in it — vehicle, owner, since when, keys — with the
        // same actions the vehicle list already offers. An empty bay says so and
        // offers a check-in straight into itself.
        void openBay(Map b) {
          final bayId = '${b['Bay_id']}';
          final parked =
              active.map((v) => v as Map).where((v) => '${v['bay_id']}' == bayId).toList();
          showModalBottomSheet<void>(
            context: context,
            showDragHandle: true,
            isScrollControlled: true,
            backgroundColor: AppColors.surface,
            builder: (sheetCtx) {
              // Every action reloads the page underneath, so the sheet steps out
              // of the way first rather than sitting on data it can't refresh.
              void run(VoidCallback action) {
                Navigator.pop(sheetCtx);
                action();
              }

              return SafeArea(
                child: ConstrainedBox(
                  constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(sheetCtx).height * 0.9),
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
                    child: SingleChildScrollView(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Row(children: [
                            Expanded(
                              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                Text('PARKING BAY', style: text.labelSmall),
                                const SizedBox(height: 4),
                                Text(_s(b, 'Bay_name'),
                                    style: text.headlineMedium,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis),
                              ]),
                            ),
                            StatusChip(
                              label: '${b['current_capacity'] ?? 0} / ${b['total_capacity'] ?? 0} occupied',
                              color: parked.isEmpty ? AppColors.success : AppColors.copper,
                            ),
                          ]),
                          const SizedBox(height: AppSpacing.lg),
                          if (parked.isEmpty)
                            EmptyState(
                              icon: Icons.local_parking,
                              title: 'This bay is empty',
                              caption: 'Nothing is parked in ${_s(b, 'Bay_name')} right now.',
                              action: ForkButton(
                                label: 'Check a vehicle in here',
                                icon: Icons.directions_car,
                                onPressed: () => run(() => checkIn(bayId: bayId)),
                              ),
                            )
                          else
                            ...parked.map((m) {
                              final id = _s(m, 'booking_id');
                              final status = _s(m, 'status', 'Vehicle added');
                              final nx = _valetNext(status);
                              final keyHolder = _s(m, 'key_holder', '');
                              final location = _s(m, 'parking_location', '');
                              final notes = _s(m, 'condition_notes', '');
                              final customer = _s(m, 'customer_name', '');
                              final since = _s(m, 'booking_date_time', '');
                              final eta = _int(m['eta_minutes']);
                              return Padding(
                                padding: const EdgeInsets.only(bottom: 12),
                                child: ForkCard(
                                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                    Row(children: [
                                      Expanded(
                                        child: Text(_s(m, 'number_plate', 'Vehicle'),
                                            style: text.titleMedium!
                                                .copyWith(fontFamily: 'monospace', letterSpacing: 2),
                                            maxLines: 1,
                                            overflow: TextOverflow.ellipsis),
                                      ),
                                      StatusChip(label: valetLabel(status), color: valetColor(status)),
                                    ]),
                                    const SizedBox(height: 10),
                                    // Same free-text exposure as the tile — the
                                    // bay sheet is narrower still on a phone.
                                    Wrap(spacing: 6, runSpacing: 6, children: [
                                      if (customer.isNotEmpty && customer != '—')
                                        _valetChip(Icons.person_outline, customer),
                                      if (since.isNotEmpty)
                                        InfoChip(icon: Icons.schedule, label: 'Since ${_fmtTime(since)}'),
                                      if (location.isNotEmpty)
                                        _valetChip(Icons.pin_drop_outlined, location),
                                      _valetChip(Icons.key,
                                          keyHolder.isEmpty ? 'Keys not taken' : 'Keys with $keyHolder',
                                          max: 30),
                                      if (eta != null && eta > 0)
                                        InfoChip(icon: Icons.timer_outlined, label: 'ETA $eta min'),
                                    ]),
                                    if (notes.isNotEmpty) ...[
                                      const SizedBox(height: 10),
                                      Text(notes,
                                          style: text.bodySmall!.copyWith(
                                              fontStyle: FontStyle.italic, color: AppColors.textTertiary)),
                                    ],
                                    const SizedBox(height: 12),
                                    Wrap(spacing: 2, runSpacing: 4, crossAxisAlignment: WrapCrossAlignment.center, children: [
                                      ForkButton.subtle(
                                          label: 'Bay',
                                          icon: Icons.local_parking,
                                          onPressed: () => run(() => assignBay(id))),
                                      ForkButton.subtle(
                                          label: 'Location',
                                          icon: Icons.edit_location_alt,
                                          onPressed: () => run(() => editLocation(m))),
                                      ForkButton.subtle(
                                          label: keyHolder.isEmpty ? 'Take keys' : 'Hand over',
                                          icon: Icons.key,
                                          onPressed: () => run(() => keysAction(m))),
                                      ForkButton.subtle(
                                          label: 'Condition',
                                          icon: Icons.note_alt_outlined,
                                          onPressed: () => run(() => editCondition(m))),
                                      ForkButton.subtle(
                                          label: 'Charge',
                                          icon: Icons.receipt_long,
                                          onPressed: () => run(() => chargeToTable(m))),
                                      if (nx != null)
                                        ForkButton(
                                          label: nx.label,
                                          dense: true,
                                          onPressed: () => run(() =>
                                              post('/update_valet_state', {'booking_id': id, 'state': nx.next})),
                                        ),
                                    ]),
                                  ]),
                                ),
                              );
                            }),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          );
        }

        return Scaffold(
          backgroundColor: Colors.transparent,
          floatingActionButton: FloatingActionButton.extended(
            onPressed: () => checkIn(),
            icon: const Icon(Icons.directions_car),
            label: const Text('Check in vehicle'),
          ),
          // The extended FAB floats over the bottom-right of this list. Without
          // the extra bottom inset it sits on top of the LAST vehicle card's
          // action row — which is exactly where "Call car" lives. Padding, not a
          // stack: the content scrolls clear instead of being covered.
          body: ListView(
            padding: AppSpacing.pageNarrow.add(const EdgeInsets.only(bottom: 96)),
            children: [
            SectionHeader(
              title: 'Parking bays',
              count: bays.length,
              padding: const EdgeInsets.only(bottom: 10),
              trailing: ForkButton.ghost(label: 'Add bay', icon: Icons.add, dense: true, onPressed: addBay),
            ),
            if (bays.isEmpty)
              EmptyState(
                icon: Icons.local_parking,
                title: 'No parking bays yet',
                caption: 'Add a bay to start valet parking.',
                action: ForkButton(label: 'Add parking bay', icon: Icons.add, onPressed: addBay),
              )
            else
              Wrap(spacing: 14, runSpacing: 14, children: [
                for (final r in bays)
                  Builder(builder: (_) {
                    final b = r as Map;
                    final cur = b['current_capacity'];
                    final tot = b['total_capacity'];
                    final ratio = (tot is num && tot > 0 && cur is num) ? (cur / tot).clamp(0.0, 1.0).toDouble() : 0.0;
                    final here = active
                        .map((v) => v as Map)
                        .where((v) => '${v['bay_id']}' == '${b['Bay_id']}')
                        .length;
                    return SizedBox(
                      width: 210,
                      child: ForkCard(
                        padding: const EdgeInsets.fromLTRB(16, 12, 10, 16),
                        onTap: () => openBay(b),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Row(children: [
                            Expanded(
                              child: Text(_s(b, 'Bay_name'),
                                  style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                            ),
                            ForkIconButton(
                              icon: Icons.delete_outline,
                              tooltip: 'Delete bay',
                              onPressed: () => deleteBay(b),
                            ),
                          ]),
                          const SizedBox(height: 8),
                          MicroStat(value: '${cur ?? 0} / ${tot ?? 0}', label: 'occupied'),
                          const SizedBox(height: 10),
                          ClipRRect(
                            borderRadius: BorderRadius.circular(AppRadius.chip),
                            child: LinearProgressIndicator(
                              value: ratio,
                              minHeight: 4,
                              backgroundColor: AppColors.inset,
                              valueColor: AlwaysStoppedAnimation<Color>(AppColors.copper),
                            ),
                          ),
                          const SizedBox(height: 10),
                          Row(children: [
                            Expanded(
                              child: Text(
                                here == 0
                                    ? 'Empty — tap to check a car in'
                                    : 'Tap to see the $here vehicle${here == 1 ? '' : 's'} here',
                                style: text.bodySmall!.copyWith(fontSize: 11),
                                maxLines: 2,
                              ),
                            ),
                            Icon(Icons.chevron_right, size: 16, color: AppColors.textTertiary),
                          ]),
                        ]),
                      ),
                    );
                  }),
              ]),
            const SizedBox(height: AppSpacing.xxl),
            SectionHeader(
              title: 'Vehicles on valet',
              count: active.length,
              padding: const EdgeInsets.only(bottom: 10),
            ),
            if (active.isEmpty)
              const EmptyState(
                icon: Icons.directions_car_outlined,
                title: 'No vehicles on valet',
                caption: 'Checked-in vehicles appear here with their bay, keys and stage.',
              )
            else
              _dashGrid([
                for (final v in active)
                  Builder(builder: (context) {
                    final m = v as Map;
                    final id = _s(m, 'booking_id');
                    final status = _s(m, 'status', 'Vehicle added');
                    final nx = _valetNext(status);
                    final location = _s(m, 'parking_location', '');
                    final keyHolder = _s(m, 'key_holder', '');
                    final notes = _s(m, 'condition_notes', '');
                    final eta = m['eta_minutes'] is num
                        ? (m['eta_minutes'] as num).toInt()
                        : int.tryParse('${m['eta_minutes'] ?? ''}');
                    final requestStage = status == 'Request to bring car (from customer)' ||
                        status == 'Request accepted (from valet)';
                    final customer = _s(m, 'customer_name', '');

                    // Bay / location / keys / condition / charge and the ETA
                    // quote no longer fit beside a plate on a tile, so they move
                    // here rather than being dropped. The stage action stays on
                    // the tile — see below.
                    void openDetail() {
                      _detailSheet(
                        context,
                        eyebrow: 'On valet',
                        title: _s(m, 'number_plate', 'Vehicle'),
                        children: [
                          _kv('Stage', valetLabel(status)),
                          _kv('Owner', customer.isEmpty ? '—' : customer),
                          _kv('Bay', _s(m, 'bay_name', '—')),
                          _kv('Parked at', location.isEmpty ? '—' : location),
                          _kv('Keys', keyHolder.isEmpty ? 'Not taken' : 'With $keyHolder'),
                          _kv('Checked in', _fmtTime(_s(m, 'booking_date_time', '')).isEmpty
                              ? '—'
                              : _fmtTime(_s(m, 'booking_date_time', ''))),
                          if (eta != null && eta > 0) _kv('ETA quoted', '$eta min'),
                          if (notes.isNotEmpty) ...[
                            const SizedBox(height: 10),
                            Text(notes,
                                style: text.bodySmall!.copyWith(
                                    fontStyle: FontStyle.italic, color: AppColors.textTertiary)),
                          ],
                          if (requestStage) ...[
                            const SizedBox(height: 14),
                            Text('QUOTE ETA', style: text.labelSmall),
                            const SizedBox(height: 6),
                            Wrap(spacing: 8, runSpacing: 8, children: [
                              for (final mins in const [5, 10, 15])
                                ForkButton.ghost(
                                  label: '$mins min',
                                  dense: true,
                                  onPressed: () => runFromSheet(() => setEta(id, mins)),
                                ),
                            ]),
                          ],
                          const SizedBox(height: 14),
                          Wrap(spacing: 8, runSpacing: 8, children: [
                            ForkButton.ghost(
                                label: 'Bay',
                                icon: Icons.local_parking,
                                dense: true,
                                onPressed: () => runFromSheet(() => assignBay(id))),
                            ForkButton.ghost(
                                label: 'Location',
                                icon: Icons.edit_location_alt,
                                dense: true,
                                onPressed: () => runFromSheet(() => editLocation(m))),
                            ForkButton.ghost(
                                label: keyHolder.isEmpty ? 'Take keys' : 'Hand over',
                                icon: Icons.key,
                                dense: true,
                                onPressed: () => runFromSheet(() => keysAction(m))),
                            ForkButton.ghost(
                                label: 'Condition',
                                icon: Icons.note_alt_outlined,
                                dense: true,
                                onPressed: () => runFromSheet(() => editCondition(m))),
                            ForkButton.ghost(
                                label: 'Charge',
                                icon: Icons.receipt_long,
                                dense: true,
                                onPressed: () => runFromSheet(() => chargeToTable(m))),
                          ]),
                        ],
                      );
                    }

                    return ForkCard(
                      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                      onTap: openDetail,
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Row(children: [
                          Container(
                            width: 34,
                            height: 34,
                            decoration: BoxDecoration(
                              color: AppColors.inset,
                              borderRadius: AppRadius.controlAll,
                              border: Border.all(color: AppColors.border),
                            ),
                            child: Icon(Icons.directions_car_outlined, size: 16, color: AppColors.copper),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Text(_s(m, 'number_plate', 'Vehicle'),
                                style: text.titleSmall!.copyWith(fontFamily: 'monospace', letterSpacing: 1.5),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis),
                          ),
                          const SizedBox(width: 8),
                          // Cross-fade as the vehicle advances through the flow.
                          AnimatedSwitcher(
                            duration: AppDurations.base,
                            switchInCurve: Curves.easeOut,
                            switchOutCurve: Curves.easeIn,
                            child: StatusChip(
                              key: ValueKey('valet-$id-$status'),
                              label: valetLabel(status),
                              color: valetColor(status),
                              dense: true,
                            ),
                          ),
                        ]),
                        const SizedBox(height: 10),
                        // Where the car is and who holds the keys — the two
                        // things an attendant is asked at the desk.
                        Wrap(spacing: 6, runSpacing: 6, children: [
                          if (customer.isNotEmpty && customer != '—')
                            _valetChip(Icons.person_outline, customer),
                          if (_s(m, 'bay_name', '').isNotEmpty)
                            _valetChip(Icons.local_parking, 'Bay ${_s(m, 'bay_name')}'),
                          if (location.isNotEmpty) _valetChip(Icons.pin_drop_outlined, location),
                          if (keyHolder.isNotEmpty) _valetChip(Icons.key, keyHolder),
                          if (requestStage && eta != null && eta > 0)
                            InfoChip(icon: Icons.schedule, label: 'ETA $eta min'),
                        ]),
                        // The stage action ("Call car", "Car at entrance"…) is
                        // the one control that must never move behind a tap: a
                        // guest is standing at the desk when it is pressed.
                        if (nx != null) ...[
                          const SizedBox(height: 12),
                          Align(
                            alignment: Alignment.centerLeft,
                            child: ForkButton(
                              label: nx.label,
                              dense: true,
                              onPressed: () =>
                                  post('/update_valet_state', {'booking_id': id, 'state': nx.next}),
                            ),
                          ),
                        ],
                      ]),
                    );
                  }),
              ], vehicleCols),
          ]),
        );
      },
    );

// Valet check-in: number plate (required), customer name, optional bay.
class _ValetCheckInDialog extends StatefulWidget {
  final List bays;

  /// Bay to open on — set when the check-in was started from that bay's sheet.
  final String? initialBayId;
  const _ValetCheckInDialog({required this.bays, this.initialBayId});

  @override
  State<_ValetCheckInDialog> createState() => _ValetCheckInDialogState();
}

class _ValetCheckInDialogState extends State<_ValetCheckInDialog> {
  final _plate = TextEditingController();
  final _name = TextEditingController();
  String? _bayId;
  bool _scanning = false;

  @override
  void initState() {
    super.initState();
    // Only honour a bay that is actually in the list, so a stale id can't leave
    // the dropdown holding a value it has no item for.
    final id = widget.initialBayId;
    if (id != null && widget.bays.any((b) => '${(b as Map)['Bay_id']}' == id)) _bayId = id;
  }

  @override
  void dispose() {
    _plate.dispose();
    _name.dispose();
    super.dispose();
  }

  // Flatten OCR lines into one string in TRUE top-to-bottom, left-to-right order
  // (ML Kit blocks aren't always ordered), so a TWO-LINE Indian plate — top row
  // "MH 12", bottom row "AB 1234" — reads as a single sequence before matching.
  String _orderedPlateText(RecognizedText r) {
    final lines = <TextLine>[];
    for (final b in r.blocks) {
      lines.addAll(b.lines);
    }
    lines.sort((a, b) {
      final dy = a.boundingBox.top.compareTo(b.boundingBox.top);
      return dy != 0 ? dy : a.boundingBox.left.compareTo(b.boundingBox.left);
    });
    return lines.map((l) => l.text).join(' ');
  }

  // Pull the most plate-like token out of OCR text. Handles single-line AND
  // two-line Indian plates (segments split across rows) plus the BH series.
  String? _extractPlate(String raw) {
    final up = raw.toUpperCase();
    // Collapse ALL separators so a 2-line plate ("MH12" over "AB1234") and any
    // stray spaces/newlines between segments join into one continuous string.
    final collapsed = up.replaceAll(RegExp(r'[\s\-.]+'), '');
    // Standard format: SS DD LL DDDD (state, 1-2 district digits, 1-3 series
    // letters, 3-4 number digits).
    final std = RegExp(r'[A-Z]{2}\d{1,2}[A-Z]{1,3}\d{3,4}').firstMatch(collapsed);
    if (std != null) return std.group(0)!;
    // Bharat (BH) series: DD BH DDDD LL.
    final bh = RegExp(r'\d{2}BH\d{4}[A-Z]{1,2}').firstMatch(collapsed);
    if (bh != null) return bh.group(0)!;
    // Separator-tolerant match on the original text (multiple spaces / newlines
    // / dashes between any two segments).
    final loose = RegExp(r'[A-Z]{2}[\s\-]*\d{1,2}[\s\-]*[A-Z]{1,3}[\s\-]*\d{3,4}').firstMatch(up);
    if (loose != null) return loose.group(0)!.replaceAll(RegExp(r'[\s\-]'), '');
    // Fallback: the longest alphanumeric token that mixes letters and digits.
    String? best;
    for (final tok in up.split(RegExp(r'[^A-Z0-9]+'))) {
      if (tok.length < 5 || tok.length > 11) continue;
      final hasLetter = RegExp(r'[A-Z]').hasMatch(tok);
      final hasDigit = RegExp(r'\d').hasMatch(tok);
      if (hasLetter && hasDigit && (best == null || tok.length > best.length)) best = tok;
    }
    return best;
  }

  // Capture a photo and OCR the number plate on-device (no network, no keys).
  Future<void> _scanPlate() async {
    setState(() => _scanning = true);
    final messenger = ScaffoldMessenger.of(context);
    TextRecognizer? recognizer;
    try {
      final shot = await ImagePicker().pickImage(source: ImageSource.camera, maxWidth: 1600, imageQuality: 85);
      if (shot == null) {
        if (mounted) setState(() => _scanning = false);
        return;
      }
      recognizer = TextRecognizer();
      final recognized = await recognizer.processImage(InputImage.fromFilePath(shot.path));
      // Try the row-ordered text first (best for two-line plates), then fall
      // back to ML Kit's raw text.
      final plate = _extractPlate(_orderedPlateText(recognized)) ?? _extractPlate(recognized.text);
      if (!mounted) return;
      if (plate != null && plate.isNotEmpty) {
        _plate.text = plate;
        messenger.showSnackBar(SnackBar(content: Text('Detected "$plate" — check it, then Check in.')));
      } else {
        messenger.showSnackBar(const SnackBar(content: Text('Could not read a plate — please type it in.')));
      }
    } catch (e) {
      if (mounted) messenger.showSnackBar(SnackBar(content: Text('Scan failed: $e')));
    } finally {
      await recognizer?.close();
      if (mounted) setState(() => _scanning = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    // Bounded and scrolling rather than a fixed 360x‹content› slab: on a short
    // window the panel used to run past the bottom of the screen and take its
    // own actions with it.
    return Dialog(
      backgroundColor: Colors.transparent,
      child: ConstrainedBox(
        constraints: BoxConstraints(maxWidth: 360, maxHeight: MediaQuery.sizeOf(context).height * 0.85),
        child: Container(
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            gradient: AppColors.cardGradient,
            borderRadius: AppRadius.cardAll,
            border: Border.all(color: AppColors.borderStrong),
          ),
          child: SingleChildScrollView(
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('VALET', style: text.labelSmall),
          const SizedBox(height: 6),
          Text('Check in vehicle', style: text.titleMedium),
          const SizedBox(height: AppSpacing.lg),
          TextField(
            controller: _plate,
            autofocus: true,
            textCapitalization: TextCapitalization.characters,
            style: TextStyle(
              fontFamily: 'monospace',
              fontSize: 15,
              fontWeight: FontWeight.w600,
              letterSpacing: 2,
              color: AppColors.textPrimary,
            ),
            decoration: const InputDecoration(labelText: 'Number plate', isDense: true),
          ),
          const SizedBox(height: AppSpacing.sm),
          Row(children: [
            Expanded(
              child: Text(_scanning ? 'Reading the photo on-device…' : 'Or capture it with the camera',
                  style: text.bodySmall),
            ),
            const SizedBox(width: AppSpacing.sm),
            ForkButton(
              label: _scanning ? 'Reading…' : 'Scan plate',
              icon: Icons.camera_alt_outlined,
              dense: true,
              onPressed: _scanning ? null : _scanPlate,
            ),
          ]),
          const SizedBox(height: AppSpacing.md),
          TextField(
            controller: _name,
            decoration: const InputDecoration(labelText: 'Customer name (optional)', isDense: true),
          ),
          if (widget.bays.isNotEmpty) ...[
            const SizedBox(height: AppSpacing.md),
            DropdownButtonFormField<String>(
              initialValue: _bayId,
              isExpanded: true,
              dropdownColor: AppColors.cardRaised,
              decoration: const InputDecoration(labelText: 'Bay (optional)', isDense: true),
              items: [
                for (final b in widget.bays)
                  DropdownMenuItem(value: '${(b as Map)['Bay_id']}', child: Text(_s(b, 'Bay_name'))),
              ],
              onChanged: (v) => setState(() => _bayId = v),
            ),
          ],
          const SizedBox(height: AppSpacing.xl),
          Row(mainAxisAlignment: MainAxisAlignment.end, children: [
            ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(context)),
            const SizedBox(width: AppSpacing.sm),
            ForkButton(
              label: 'Check in',
              icon: Icons.check,
              onPressed: () {
                final plate = _plate.text.trim();
                if (plate.isEmpty) return;
                Navigator.pop(context, <String, dynamic>{
                  'number_plate': plate,
                  if (_name.text.trim().isNotEmpty) 'customer_name': _name.text.trim(),
                  if (_bayId != null) 'bay_id': _bayId,
                });
              },
            ),
          ]),
            ]),
          ),
        ),
      ),
    );
  }
}

// ------------------------------------------------------------- performance ---

/// The four measures GET /analytics/staff-performance scores, in the order the
/// detail sheet lists them, with the label the owner reads.
///
/// The WEIGHTING is deliberately not here. The server sends the nominal weights
/// and, per employee, the `effective_weights` it renormalised over whatever it
/// could actually measure — so a client that hardcoded "APC is 35%" would print
/// a different sum than the score it sits beside the moment one measure drops
/// out. Everything shown about weight comes off the payload.
const List<List<String>> _perfComponents = [
  ['apc', 'Average per cover'],
  ['rating', 'Guest rating'],
  ['attendance', 'Attendance'],
  ['tat', 'Table turnaround'],
];

/// Colour band for a 0-100 score. Redundant with the number it decorates — the
/// score itself is always the chip's label, so nothing here is colour-only.
Color _perfScoreColor(double score) => score >= 80
    ? AppColors.success
    : score >= 60
        ? AppColors.info
        : score >= 40
            ? AppColors.warning
            : AppColors.danger;

/// True when a component carries a usable score. `available` and a non-null
/// `score` must agree — the server keeps them in step (a raw value with no
/// benchmark to score it against is reported unavailable) and this is the one
/// place the app decides between "here is the number" and "not enough data".
bool _perfMeasured(Map? c) => c != null && c['available'] == true && c['score'] != null;

/// One measure's share of the score, or null when the server did not report one.
///
/// `_numOf` turns anything unreadable into 0.0, which here would be a fabricated
/// figure: "Counts for 0% of this score." printed beside a measure that plainly
/// did count. An older server sends no `effective_weights` at all and a trimmed
/// payload can drop one key, so absent, non-numeric and unparseable all have to
/// come back as unknown — not zero.
double? _perfWeight(Map? effectiveWeights, String key) {
  final raw = effectiveWeights?[key];
  if (raw == null) return null;
  if (raw is num) return raw.toDouble();
  return double.tryParse('$raw'.trim());
}

/// One measure, spelled out: what it scored, what was actually measured, how
/// much of the total it carried — or, when it could not be measured, the
/// server's own sentence explaining why. Never a zero standing in for a blank.
///
/// [effectiveWeight] is null when the server did not report a share for this
/// measure. Unknown is NOT zero: a scored measure plainly counted for something,
/// and printing "Counts for 0% of this score." beside it would be a made-up
/// figure contradicting the score right next to it.
Widget _perfComponentRow(BuildContext context, String label, Map? c, double? effectiveWeight) {
  final text = Theme.of(context).textTheme;
  final measured = _perfMeasured(c);
  final note = '${c?['note'] ?? ''}'.trim();
  final unit = '${c?['unit'] ?? ''}'.trim();
  final sample = _int(c?['sample']) ?? 0;
  final value = c?['value'];
  final pct = effectiveWeight == null ? null : (effectiveWeight * 100).round();

  return Padding(
    padding: const EdgeInsets.symmetric(vertical: 7),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        Expanded(child: Text(label, style: text.titleSmall)),
        const SizedBox(width: AppSpacing.sm),
        if (measured)
          StatusChip(
            label: '${_numOf(c!['score']).round()} / 100',
            color: _perfScoreColor(_numOf(c['score'])),
            dense: true,
          )
        else
          // Never "0". A measure with nothing behind it is excluded from the
          // score, and saying zero would read as "they scored nothing".
          StatusChip(label: 'Not enough data', color: AppColors.neutral, dense: true),
      ]),
      if (measured && value != null) ...[
        const SizedBox(height: 3),
        Text(
          '${_score(value)}${unit.isEmpty ? '' : ' $unit'}'
          '${sample > 0 ? ' · from $sample observation${sample == 1 ? '' : 's'}' : ''}',
          style: text.bodySmall,
        ),
      ],
      if (note.isNotEmpty) ...[
        const SizedBox(height: 3),
        Text(note, style: text.bodySmall?.copyWith(color: AppColors.textTertiary)),
      ],
      const SizedBox(height: 3),
      Text(
        !measured
            ? 'Left out of the score — the measures that could be taken were '
                'reweighted between them to still make 100%.'
            : pct == null
                ? 'It counted towards this score, but the server did not say by how much.'
                : 'Counts for $pct% of this score.',
        style: TextStyle(fontSize: 10.5, color: AppColors.textTertiary),
      ),
    ]),
  );
}

// -------------------------------------------------------------------- leave ---

String _leaveTypeLabel(String t) => switch (t) {
      'sick' => 'Sick leave',
      'casual' => 'Casual leave',
      'unpaid' => 'Unpaid leave',
      'holiday' => 'Holiday',
      _ => t.isEmpty ? 'Leave' : t,
    };

Color _leaveStatusColor(String s) => switch (s) {
      'approved' => AppColors.success,
      'rejected' => AppColors.danger,
      _ => AppColors.warning,
    };

/// "Aug 3" for a single day, "Aug 3 – Aug 7" for a range. Both ends are
/// inclusive restaurant calendar days, which is what the server stores.
String _leaveRange(Map l) {
  final from = _s(l, 'start_day', '');
  final to = _s(l, 'end_day', '');
  if (from.isEmpty) return '—';
  return from == to ? _fmtDay(from) : '${_fmtDay(from)} – ${_fmtDay(to)}';
}

/// Longest span the server will accept in one request (LEAVE_MAX_DAYS). Mirrored
/// here only to WARN before submitting — the server stays the authority, so a
/// cap that moves there loosens on its own instead of leaving this screen
/// refusing something the backend would have taken.
const int _leaveMaxDays = 366;

/// Whole days from [fromKey] to [toKey] inclusive — the same count the server
/// stores as `days`. Both are zone-free "YYYY-MM-DD" keys, so this is plain UTC
/// arithmetic and cannot land on a DST half-day.
int _leaveDayCount(String fromKey, String toKey) {
  final a = DateTime.tryParse('${fromKey}T00:00:00Z');
  final b = DateTime.tryParse('${toKey}T00:00:00Z');
  if (a == null || b == null || b.isBefore(a)) return 0;
  return b.difference(a).inDays + 1;
}

/// Whether [dayKey] falls inside this leave's inclusive range. String compare is
/// exact for "YYYY-MM-DD" and needs no zone of its own — both sides are already
/// restaurant calendar days.
bool _leaveCovers(Map l, String dayKey) {
  final from = _s(l, 'start_day', '');
  final to = _s(l, 'end_day', from);
  return from.isNotEmpty && from.compareTo(dayKey) <= 0 && to.compareTo(dayKey) >= 0;
}

/// File a leave. For yourself this needs no permission (it is a request, not a
/// decision, exactly like clocking in); for anyone else the server requires
/// 'Review Attendance' and will say so.
Future<void> _requestLeave(
  BuildContext context,
  RestClient rest,
  Profile p, {
  required String empId,
  required String empName,
  required VoidCallback reload,
}) async {
  final messenger = ScaffoldMessenger.of(context);
  final today = RestaurantTime.todayIso();
  var type = 'casual';
  var from = today;
  var to = today;
  final reason = TextEditingController();

  final submitted = await showDialog<bool>(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setLocal) {
        Future<void> pick(bool isStart) async {
          final seed = DateTime.tryParse('${isStart ? from : to}T00:00:00') ?? DateTime.now();
          final wall = RestaurantTime.nowWall();
          final picked = await showDatePicker(
            context: ctx,
            initialDate: seed,
            // A leave can be filed for the recent past (someone was off sick
            // yesterday and it was never recorded) and for the year ahead.
            firstDate: DateTime(wall.year - 1, wall.month, wall.day),
            lastDate: DateTime(wall.year + 1, wall.month, wall.day),
          );
          if (picked == null) return;
          final key = RestaurantTime.isoDate(picked);
          setLocal(() {
            if (isStart) {
              from = key;
              // The server rejects an end before the start; move it rather than
              // let the owner submit something that cannot be accepted.
              if (to.compareTo(from) < 0) to = from;
            } else {
              to = key;
              if (to.compareTo(from) < 0) from = to;
            }
          });
        }

        return AlertDialog(
          title: Text('Request leave — $empName'),
          content: SizedBox(
            width: 400,
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              DropdownButtonFormField<String>(
                initialValue: type,
                isExpanded: true,
                dropdownColor: AppColors.cardRaised,
                decoration: const InputDecoration(labelText: 'Type', isDense: true),
                items: const [
                  DropdownMenuItem(value: 'casual', child: Text('Casual leave')),
                  DropdownMenuItem(value: 'sick', child: Text('Sick leave')),
                  DropdownMenuItem(value: 'unpaid', child: Text('Unpaid leave')),
                  DropdownMenuItem(value: 'holiday', child: Text('Holiday')),
                ],
                onChanged: (v) => setLocal(() => type = v ?? 'casual'),
              ),
              const SizedBox(height: AppSpacing.md),
              Row(children: [
                Expanded(
                  child: ForkButton.ghost(
                    label: 'From ${_fmtDay(from)}',
                    icon: Icons.event,
                    dense: true,
                    onPressed: () => pick(true),
                  ),
                ),
                const SizedBox(width: AppSpacing.sm),
                Expanded(
                  child: ForkButton.ghost(
                    label: 'To ${_fmtDay(to)}',
                    icon: Icons.event,
                    dense: true,
                    onPressed: () => pick(false),
                  ),
                ),
              ]),
              const SizedBox(height: 6),
              // The pickers span a year either side, so a range longer than the
              // server accepts is selectable — and a mistyped year used to be
              // submitted only to come back a 400. Say the length up front.
              Builder(builder: (_) {
                final days = _leaveDayCount(from, to);
                final over = days > _leaveMaxDays;
                return Text(
                  over
                      ? '$days days — one request cannot span more than $_leaveMaxDays. '
                          'Shorten the range, or file it in parts.'
                      : '$days day${days == 1 ? '' : 's'}, both ends included.',
                  style: Theme.of(ctx).textTheme.bodySmall?.copyWith(
                      color: over ? AppColors.danger : AppColors.textTertiary),
                );
              }),
              const SizedBox(height: AppSpacing.md),
              TextField(
                controller: reason,
                decoration: const InputDecoration(labelText: 'Reason (optional)', isDense: true),
              ),
            ]),
          ),
          actions: [
            ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
            ForkButton(label: 'Send request', icon: Icons.send, onPressed: () => Navigator.pop(ctx, true)),
          ],
        );
      },
    ),
  );
  if (submitted != true) return;

  try {
    await rest.post('/leaves', {
      // Omitted for yourself so the server takes the actor's own id and asks for
      // no permission; naming someone else is what makes it a managed action.
      if (empId != p.employeeId) 'emp_id': empId,
      'leave_type': type,
      'start_day': from,
      'end_day': to,
      if (reason.text.trim().isNotEmpty) 'reason': reason.text.trim(),
    });
    messenger.showSnackBar(SnackBar(content: Text('Leave requested for $empName.')));
    reload();
  } catch (e) {
    // The backend's message is already a sentence ("X already has an approved
    // leave covering …") — show it rather than a generic failure.
    messenger.showSnackBar(SnackBar(content: Text('$e'), backgroundColor: AppColors.danger));
  }
}

Future<void> _decideLeave(
  BuildContext context,
  RestClient rest,
  Map leave,
  bool approve,
  VoidCallback reload,
) async {
  final messenger = ScaffoldMessenger.of(context);
  final id = _s(leave, 'id', '');
  if (id.isEmpty) return;
  try {
    final res = await rest.post('/leaves/${Uri.encodeComponent(id)}/${approve ? 'approve' : 'reject'}');
    // `changed:false` means someone else already decided it exactly this way —
    // report that honestly instead of claiming this tap did something.
    final changed = (res is Map) ? res['changed'] != false : true;
    messenger.showSnackBar(SnackBar(
      content: Text(changed
          ? 'Leave ${approve ? 'approved' : 'rejected'}.'
          : 'Already ${approve ? 'approved' : 'rejected'} — nothing changed.'),
    ));
    reload();
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e'), backgroundColor: AppColors.danger));
  }
}

/// What a leave's status means for the person's ATTENDANCE record, in words.
///
/// Only an APPROVED leave is subtracted from absences (getStaffAttendanceStats
/// does the subtracting, and it filters on `approved`). So a leave still waiting
/// on a decision over days that have already gone by is, right now, reading as
/// unexplained absence — and that is the one thing the register must not let a
/// reader assume the other way.
String _leaveAbsenceEffect(Map l, String todayKey) {
  final status = _s(l, 'status', 'requested');
  final started = _s(l, 'start_day', '').compareTo(todayKey) <= 0;
  return switch (status) {
    'approved' => 'Approved, so every day in this range is excluded from this '
        'person\'s absence count — an excused day is not an absence.',
    'rejected' => 'Rejected, so none of these days is excused. Any the person did '
        'not clock in for counts as an unexplained absence.',
    _ when started => 'Still awaiting a decision. Attendance only excuses APPROVED '
        'leave, so the days in this range that have already passed are counting as '
        'unexplained absences until somebody decides it.',
    _ => 'Still awaiting a decision. Nothing is excused until it is approved.',
  };
}

/// The whole record behind one leave, with the decisions the viewer is permitted.
///
/// The register row leads with who, what type and when; what it cannot hold is
/// who filed it and who signed it off (with the stamp), the reason in full, and
/// what the status currently means for the absence count.
void _leaveSheet(
  BuildContext context,
  RestClient rest,
  Map l, {
  required bool canReview,
  required VoidCallback reload,
}) {
  final status = _s(l, 'status', 'requested');
  final days = _int(l['days']) ?? 1;
  final reason = _s(l, 'reason', '');
  final filedBy = _s(l, 'requested_by_name', '');
  final decidedBy = _s(l, 'decided_by_name', '');
  final decidedAt = _s(l, 'decided_at', '');
  final createdAt = _s(l, 'created_at', '');
  final text = Theme.of(context).textTheme;
  _detailSheet(
    context,
    eyebrow: 'Leave · $status',
    title: _s(l, 'employee_name', 'Employee'),
    children: [
      _kv('Type', _leaveTypeLabel(_s(l, 'leave_type', ''))),
      _kv('Dates', _leaveRange(l)),
      _kv('Days', '$days day${days == 1 ? '' : 's'}'),
      _kv('Status', status),
      _kv('Reason', reason.isEmpty || reason == '—' ? 'None given' : reason),
      _kv('Filed by', filedBy.isEmpty || filedBy == '—' ? 'Not recorded' : filedBy),
      _kv('Filed on', createdAt.isEmpty ? '—' : RestaurantTime.stamp(createdAt)),
      _kv('Decided by', decidedBy.isEmpty || decidedBy == '—' ? 'Not decided yet' : decidedBy),
      _kv('Decided on', decidedAt.isEmpty ? '—' : RestaurantTime.stamp(decidedAt)),
      const SizedBox(height: 14),
      Text(
        _leaveAbsenceEffect(l, RestaurantTime.todayIso()),
        style: text.bodySmall?.copyWith(
            color: status == 'requested' ? AppColors.warning : AppColors.textSecondary),
      ),
      if (canReview && status == 'requested') ...[
        const SizedBox(height: 14),
        Wrap(spacing: 8, runSpacing: 8, children: [
          ForkButton(
            label: 'Approve',
            icon: Icons.check,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _decideLeave(context, rest, l, true, reload);
            },
          ),
          ForkButton.ghost(
            label: 'Reject',
            icon: Icons.close,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _decideLeave(context, rest, l, false, reload);
            },
          ),
        ]),
      ],
    ],
  );
}

/// One leave in the detail sheet, with its decision controls when the viewer
/// holds 'Review Attendance'.
Widget _leaveRow(
  BuildContext context,
  RestClient rest,
  Map l,
  bool canReview,
  VoidCallback reload,
) {
  final text = Theme.of(context).textTheme;
  final status = _s(l, 'status', 'requested');
  final days = _int(l['days']) ?? 1;
  final reason = _s(l, 'reason', '');
  final requestedBy = _s(l, 'requested_by_name', '');
  final decidedBy = _s(l, 'decided_by_name', '');
  return Padding(
    padding: const EdgeInsets.symmetric(vertical: 6),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        Expanded(
          child: Text('${_leaveTypeLabel(_s(l, 'leave_type', ''))} · ${_leaveRange(l)}',
              style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
        ),
        const SizedBox(width: AppSpacing.sm),
        StatusChip(label: status, color: _leaveStatusColor(status), dense: true),
      ]),
      const SizedBox(height: 3),
      Text(
        '$days day${days == 1 ? '' : 's'}'
        '${requestedBy.isEmpty || requestedBy == '—' ? '' : ' · filed by $requestedBy'}'
        '${decidedBy.isEmpty || decidedBy == '—' ? '' : ' · decided by $decidedBy'}',
        style: text.bodySmall,
      ),
      if (reason.isNotEmpty && reason != '—') ...[
        const SizedBox(height: 2),
        Text(reason, style: text.bodySmall?.copyWith(color: AppColors.textTertiary)),
      ],
      if (canReview && status == 'requested') ...[
        const SizedBox(height: 6),
        Wrap(spacing: 8, runSpacing: 8, children: [
          ForkButton(
            label: 'Approve',
            icon: Icons.check,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _decideLeave(context, rest, l, true, reload);
            },
          ),
          ForkButton.ghost(
            label: 'Reject',
            icon: Icons.close,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _decideLeave(context, rest, l, false, reload);
            },
          ),
        ]),
      ],
    ]),
  );
}

/// Everything known about one team member: who they are, what they scored and
/// WHY, and their leave record with the decisions that can be taken on it.
void _employeeSheet(
  BuildContext context,
  RestClient rest,
  Profile p, {
  required Map employee,
  required String display,
  required List<String> roleLabels,
  required Map? perfRow,
  required Map perfMeta,
  required String perfNote,
  required List<Map> leaves,
  required String leaveNote,
  required bool canReview,
  required VoidCallback reload,
}) {
  final text = Theme.of(context).textTheme;
  final empId = '${employee['employee_id'] ?? employee['id'] ?? ''}';
  final score = perfRow?['score'];
  final components = (perfRow?['components'] as Map?) ?? const {};
  // Absent on an older server, and a trimmed payload can drop a single key. Kept
  // nullable all the way down so a missing share reads as unknown rather than 0%
  // — see [_perfWeight].
  final effective = perfRow?['effective_weights'] as Map?;
  final windowDays = _int(perfMeta['window_days']);
  final measured = _int(perfRow?['components_available']) ?? 0;

  _detailSheet(
    context,
    eyebrow: 'Employees',
    title: display,
    children: [
      _kv('Username', '@${_s(employee, 'employee_Username')}'),
      _kv('Roles', roleLabels.isEmpty ? '—' : roleLabels.join(', ')),
      const SizedBox(height: 14),
      Text('PERFORMANCE', style: text.labelSmall),
      const SizedBox(height: 8),
      if (perfRow == null)
        Text(
          perfNote.isEmpty
              ? 'No performance figures were returned for this person.'
              : perfNote,
          style: text.bodySmall?.copyWith(color: AppColors.textTertiary),
        )
      else ...[
        Row(children: [
          if (score == null)
            StatusChip(label: 'Not enough data', color: AppColors.neutral)
          else
            StatusChip(
              label: '${_numOf(score).round()} / 100',
              color: _perfScoreColor(_numOf(score)),
            ),
          const SizedBox(width: AppSpacing.sm),
          Expanded(
            child: Text(
              score == null
                  ? 'Not one of the four measures below could be taken, so there is '
                      'no score — this is not a score of zero.'
                  : 'Built from $measured of ${_perfComponents.length} measures'
                      '${windowDays == null ? '' : ' over the last $windowDays days'}.',
              style: text.bodySmall,
            ),
          ),
        ]),
        const SizedBox(height: 6),
        for (final c in _perfComponents)
          _perfComponentRow(
            context,
            c[1],
            components[c[0]] as Map?,
            _perfWeight(effective, c[0]),
          ),
      ],
      const SizedBox(height: 14),
      Text('LEAVE', style: text.labelSmall),
      const SizedBox(height: 8),
      if (leaveNote.isNotEmpty)
        Text(leaveNote, style: text.bodySmall?.copyWith(color: AppColors.textTertiary))
      else if (leaves.isEmpty)
        Text('No leave on record in this window.', style: text.bodySmall)
      else
        for (final l in leaves) _leaveRow(context, rest, l, canReview, reload),
      // Filing for yourself always; for someone else only with the permission
      // the server enforces, so this is never a button that 403s.
      if (empId.isNotEmpty && (canReview || empId == p.employeeId)) ...[
        const SizedBox(height: 10),
        Align(
          alignment: Alignment.centerLeft,
          child: ForkButton.ghost(
            label: 'Request leave',
            icon: Icons.event_busy,
            dense: true,
            onPressed: () {
              Navigator.of(context).pop();
              _requestLeave(context, rest, p,
                  empId: empId, empName: display, reload: reload);
            },
          ),
        ),
      ],
    ],
  );
}

// ------------------------------------------------- employee scoring boards ---

/// One roster row plus everything the Employees tab derives from it. Built once
/// and shared by the team cards, the scoring band and the leave register, so a
/// name, a score or a leave count cannot differ between the three surfaces.
class _TeamMember {
  const _TeamMember({
    required this.user,
    required this.empId,
    required this.display,
    required this.initials,
    required this.roleLabels,
    required this.isSuper,
    required this.perfRow,
    required this.leaves,
  });

  final Map user;
  final String empId;
  final String display;
  final String initials;
  final List<String> roleLabels;
  final bool isSuper;

  /// Null when the server returned no performance row for this person at all —
  /// which is NOT the same as a row whose measures all came back empty.
  final Map? perfRow;
  final List<Map> leaves;

  Map? component(String key) => ((perfRow?['components'] as Map?) ?? const {})[key] as Map?;
}

/// The scoring band, left to right: the composite first, then the measures it
/// is built from in the order the detail sheet already lists them. The composite
/// is keyed '' because it is the row itself rather than one of its components.
final List<List<String>> _scoringBoxes = [
  const ['', 'Overall score'],
  ..._perfComponents,
];

/// This member's 0-100 figure for [key], or null when it could not be measured.
///
/// Availability is the SERVER's flag ([_perfMeasured]), never inferred from the
/// number: a component with nothing behind it comes back `available:false` with
/// a null score, and reading that as 0 would rank the person last on a measure
/// nobody could take for them. Every ranking below hangs off this returning null.
double? _memberScore(_TeamMember m, String key) {
  if (key.isEmpty) {
    final s = m.perfRow?['score'];
    return s == null ? null : _numOf(s);
  }
  final c = m.component(key);
  return _perfMeasured(c) ? _numOf(c!['score']) : null;
}

/// The raw reading behind that score, in the measure's own unit.
dynamic _memberValue(_TeamMember m, String key) {
  if (key.isEmpty) return m.perfRow?['score'];
  return m.component(key)?['value'];
}

/// A reading in its own unit. The composite has no unit but a denominator, so
/// it carries the "/ 100" the others must not.
String _perfValueLabel(String key, dynamic value) {
  if (value == null) return '—';
  return switch (key) {
    'apc' => _money(value),
    'rating' => '${_score(value)} ★',
    'attendance' => '${_score(value)}%',
    'tat' => '${_score(value)} min',
    _ => '${_score(value)} / 100',
  };
}

/// What a measure is scored AGAINST, in the server's own figures. Two of the
/// four are relative to the house and two are absolute scales; saying which is
/// what stops "78 / 100" being read as a percentage of something it is not.
String _perfBenchmarkLine(String key, Map benchmarks) {
  final apc = benchmarks['apc'];
  final tat = benchmarks['tat_minutes'];
  return switch (key) {
    'apc' => apc == null ? 'no house average to compare against' : 'house ${_money(apc)} per cover',
    'rating' => 'absolute 1–5 star scale',
    'attendance' => 'presence first, then punctuality',
    'tat' => tat == null ? 'no house median to compare against' : 'house median ${_score(tat)} min',
    _ => 'weighted over the measures each person had',
  };
}

/// The one-line description of what a board actually measures.
String _perfBasisLine(String key) => switch (key) {
      'apc' => 'Pre-tax spend per cover, scored against the house average',
      'rating' => 'Average guest rating, on an absolute 1–5 star scale',
      'attendance' => 'Presence on open days, then punctuality once there is a baseline',
      'tat' => 'Median seated-to-released time against the house median — faster scores higher',
      _ => 'The weighted composite of every measure that could be taken for each person',
    };

/// Why this person is not on a board: the server's own sentence wherever it sent
/// one, so the app never invents a reason it does not have.
String _memberGapReason(_TeamMember m, String key, String perfNote) {
  if (m.perfRow == null) {
    return perfNote.isEmpty
        ? 'No performance row was returned for them in this window.'
        : perfNote;
  }
  if (key.isEmpty) {
    return 'Not one of the ${_perfComponents.length} measures could be taken for them, '
        'so there is no score — this is not a score of zero.';
  }
  final note = '${m.component(key)?['note'] ?? ''}'.trim();
  return note.isEmpty ? 'Nothing measurable on this in the window.' : note;
}

/// Every employee ranked by ONE measure, which is the whole point of the band:
/// who is strong and who is weak on it, with their own reading beside them.
///
/// The people the measure could not be taken for are listed BELOW the ranking
/// rather than sorted into the bottom of it. A missing figure is not a bad one,
/// and the position at the end of a ranked list means "worst" to every reader.
void _metricBoard(
  BuildContext context, {
  required String metricKey,
  required String title,
  required List<_TeamMember> team,
  required Map perf,
  required String perfNote,
  required void Function(_TeamMember) openMember,
}) {
  final text = Theme.of(context).textTheme;
  final windowDays = _int(perf['window_days']);
  final ranked = <_TeamMember>[for (final m in team) if (_memberScore(m, metricKey) != null) m]
    ..sort((a, b) {
      final byScore = _memberScore(b, metricKey)!.compareTo(_memberScore(a, metricKey)!);
      return byScore != 0 ? byScore : a.display.compareTo(b.display);
    });
  final excluded = [for (final m in team) if (_memberScore(m, metricKey) == null) m];

  void jumpToMember(_TeamMember m) {
    Navigator.of(context).pop();
    openMember(m);
  }

  _detailSheet(
    context,
    eyebrow: 'Scoring',
    title: title,
    children: [
      Text(
        '${_perfBasisLine(metricKey)}'
        '${windowDays == null ? '' : ', over the last $windowDays days'}. '
        '${_perfBenchmarkLine(metricKey, (perf['benchmarks'] as Map?) ?? const {})}.',
        style: text.bodySmall,
      ),
      const SizedBox(height: AppSpacing.lg),
      SectionHeader(title: 'Ranked', count: ranked.length),
      if (ranked.isEmpty)
        Text('Nobody could be measured on this in the window.', style: text.bodySmall)
      else
        for (var i = 0; i < ranked.length; i++)
          Builder(builder: (_) {
            final m = ranked[i];
            final s = _memberScore(m, metricKey)!;
            final own = _perfValueLabel(metricKey, _memberValue(m, metricKey));
            return HBarRow(
              label: '${i + 1}. ${m.display}',
              // Against 100, not against the leader: the score already IS the
              // scale, and re-basing it on the best person would make a strong
              // team look weak the moment somebody excelled.
              fraction: (s / 100).clamp(0.0, 1.0),
              value: own,
              sub: 'score ${s.round()}',
              tooltip: '${m.display} — $own · score ${s.round()} / 100',
              onTap: () => jumpToMember(m),
            );
          }),
      if (excluded.isNotEmpty) ...[
        const SizedBox(height: AppSpacing.lg),
        SectionHeader(title: 'Not enough data', count: excluded.length),
        for (final m in excluded)
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: ForkCard(
              inset: true,
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
              onTap: () => jumpToMember(m),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                // A Wrap, not a Row: the chip carries its own intrinsic width and
                // "Not enough data" at a 1.3x text scale is most of a 234px sheet
                // row on its own. Given a Row it overflowed; here it simply drops
                // under the name, which is the reading that must survive.
                Wrap(
                  spacing: AppSpacing.sm,
                  runSpacing: 6,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    Text(m.display,
                        style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                    StatusChip(label: 'Not enough data', color: AppColors.neutral, dense: true),
                  ],
                ),
                const SizedBox(height: 3),
                Text(_memberGapReason(m, metricKey, perfNote),
                    style: text.bodySmall?.copyWith(color: AppColors.textTertiary)),
              ]),
            ),
          ),
      ],
    ],
  );
}

/// The scoring band: one box per measure behind the score, plus the composite.
/// Each carries the team's own figure, what that figure was measured against,
/// and the shape of the spread across the roster — and opens the full ranking.
///
/// Empty when the scores could not be read at all: the reason is already stated
/// once, in words, above the roster, and a band of five dashes underneath it
/// would say the same thing five more times.
List<Widget> _scoringBand(
  BuildContext context, {
  required List<_TeamMember> team,
  required Map perf,
  required String perfNote,
  required int columns,
  required void Function(_TeamMember) openMember,
}) {
  if (team.isEmpty || perfNote.isNotEmpty) return const [];
  final micro = TextStyle(fontSize: 10.5, height: 1.3, color: AppColors.textTertiary);
  final benchmarks = (perf['benchmarks'] as Map?) ?? const {};

  final boxes = <Widget>[];
  for (final spec in _scoringBoxes) {
    final key = spec[0], label = spec[1];
    final measured = <_TeamMember>[for (final m in team) if (_memberScore(m, key) != null) m]
      ..sort((a, b) => _memberScore(b, key)!.compareTo(_memberScore(a, key)!));
    final avg = measured.isEmpty
        ? null
        : measured.fold<double>(0, (s, m) => s + _memberScore(m, key)!) / measured.length;
    // Seven bars is what the narrowest column in this grid can still label; the
    // rest are one tap away on the board, which is where a long roster belongs.
    final shown = measured.length > 7 ? measured.sublist(0, 7) : measured;

    Widget? chart;
    if (avg != null) {
      // A ratio out of a whole (presence, and a composite already expressed as a
      // percentage) reads as a gauge; the three that vary person to person are
      // worth seeing as a spread, so those get the distribution instead.
      chart = key.isEmpty || key == 'attendance'
          // Boxed to the bar chart's own height so the captions underneath sit on
          // one line across the band instead of stepping by 10px.
          ? SizedBox(
              height: 56,
              child: Align(
                alignment: Alignment.centerLeft,
                child: DonutGauge(
                  fraction: (avg / 100).clamp(0.0, 1.0),
                  size: 46,
                  tooltip: '${avg.round()} / 100 averaged over ${measured.length} '
                      'of ${team.length} — best ${_memberScore(measured.first, key)!.round()}',
                ),
              ),
            )
          : WeekdayBars(
              values: [for (final m in shown) _memberScore(m, key)!],
              labels: [for (final m in shown) m.initials],
              // Read-only inside a tappable box — see the tap note below.
              tooltipBuilder: (i) => '${shown[i].display} — '
                  '${_perfValueLabel(key, _memberValue(shown[i], key))} · '
                  'score ${_memberScore(shown[i], key)!.round()} / 100',
            );
    }

    boxes.add(_TappableStat(
      // The BOX is the control and the chart inside it only reads. A per-bar tap
      // would be the deeper hit target and would swallow the box's own tap, so
      // one pixel would open a person and the pixel under it the whole board.
      // Hover names the bar; every click opens the ranking, where the per-person
      // rows are the things that lead anywhere.
      onTap: () => _metricBoard(context,
          metricKey: key,
          title: label,
          team: team,
          perf: perf,
          perfNote: perfNote,
          openMember: openMember),
      child: StatCard(
        value: avg == null ? '—' : '${avg.round()}',
        unit: avg == null ? null : '/ 100',
        caption: '$label — team average',
        chart: chart,
        footer: Text(
          avg == null
              ? 'not measurable for anyone in this window'
              : '${_perfBenchmarkLine(key, benchmarks)} · '
                  '${measured.length} of ${team.length} measured',
          style: micro,
          maxLines: 2,
          overflow: TextOverflow.ellipsis,
        ),
      ),
    ));
  }

  return [
    // No trailing hint: SectionHeader lays its trailing out at intrinsic width,
    // so a sentence there took the whole 390px header and pushed the title off.
    // Each box carries the chevron this app uses everywhere else for "opens".
    const SectionHeader(title: 'Scoring'),
    _dashGrid(boxes, columns),
    const SizedBox(height: 28),
  ];
}

// --------------------------------------------------------- leave register ---

/// One leave in the tab-level register. Unlike [_leaveRow] — which lives inside
/// one person's sheet and so never needs to name them — this row leads with WHO,
/// because the register is read across the roster.
Widget _leaveTeamRow(
  BuildContext context,
  RestClient rest,
  Map l, {
  required bool canReview,
  required VoidCallback reload,
}) {
  final text = Theme.of(context).textTheme;
  final status = _s(l, 'status', 'requested');
  final days = _int(l['days']) ?? 1;
  final reason = _s(l, 'reason', '');
  final filedBy = _s(l, 'requested_by_name', '');
  return Padding(
    padding: const EdgeInsets.only(bottom: 8),
    child: ForkCard(
      inset: true,
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
      // The row summarises; the sheet carries who filed it, who signed it off
      // and when, and what the status means for the absence count. Approve and
      // reject stay on their own buttons below — a decision must never be what
      // a stray tap on a list does.
      onTap: () => _leaveSheet(context, rest, l, canReview: canReview, reload: reload),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // Wrapped for the same reason as the scoring boards: a status chip and a
        // long name do not share one narrow row at a raised text scale.
        Wrap(
          spacing: AppSpacing.sm,
          runSpacing: 6,
          crossAxisAlignment: WrapCrossAlignment.center,
          children: [
            Text(_s(l, 'employee_name', 'Employee'),
                style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
            StatusChip(label: status, color: _leaveStatusColor(status), dense: true),
          ],
        ),
        const SizedBox(height: 3),
        Text(
          '${_leaveTypeLabel(_s(l, 'leave_type', ''))} · ${_leaveRange(l)} · '
          '$days day${days == 1 ? '' : 's'}'
          '${filedBy.isEmpty || filedBy == '—' ? '' : ' · filed by $filedBy'}',
          style: text.bodySmall,
        ),
        if (reason.isNotEmpty && reason != '—') ...[
          const SizedBox(height: 2),
          Text(reason,
              style: text.bodySmall?.copyWith(color: AppColors.textTertiary),
              maxLines: 2,
              overflow: TextOverflow.ellipsis),
        ],
        // Nothing to pop here: unlike the sheet's copy of these controls, this
        // row is on the page itself, so the decision is taken in place.
        if (canReview && status == 'requested') ...[
          const SizedBox(height: 8),
          Wrap(spacing: 8, runSpacing: 8, children: [
            ForkButton(
              label: 'Approve',
              icon: Icons.check,
              dense: true,
              onPressed: () => _decideLeave(context, rest, l, true, reload),
            ),
            ForkButton.ghost(
              label: 'Reject',
              icon: Icons.close,
              dense: true,
              onPressed: () => _decideLeave(context, rest, l, false, reload),
            ),
          ]),
        ],
      ]),
    ),
  );
}

/// File a leave from the register: pick who it is for, then the shared dialog.
/// Only reachable from a section that already required 'Review Attendance', so
/// naming somebody else here can never come back a 403.
Future<void> _requestLeaveForMember(
  BuildContext context,
  RestClient rest,
  Profile p,
  List<_TeamMember> team,
  VoidCallback reload,
) async {
  final pickable = [for (final m in team) if (m.empId.isNotEmpty) m];
  if (pickable.isEmpty) return;
  final chosen = await showDialog<_TeamMember>(
    context: context,
    builder: (ctx) => SimpleDialog(
      backgroundColor: AppColors.cardRaised,
      title: const Text('Request leave for'),
      children: [
        for (final m in pickable)
          SimpleDialogOption(
            onPressed: () => Navigator.pop(ctx, m),
            child: Text(m.display, style: Theme.of(ctx).textTheme.bodyMedium),
          ),
      ],
    ),
  );
  if (chosen == null || !context.mounted) return;
  await _requestLeave(context, rest, p,
      empId: chosen.empId, empName: chosen.display, reload: reload);
}

/// The tab's leave register: who is off today, what is waiting on a decision,
/// and what is booked ahead — over the same window the server paged.
///
/// Empty when leave could not be read at all. That reason is already stated once
/// above the roster, and this section repeating it would print the same sentence
/// twice on one page.
List<Widget> _leaveSection(
  BuildContext context,
  RestClient rest,
  Profile p, {
  required Map leavePage,
  required List<_TeamMember> team,
  required String leaveNote,
  required bool canReview,
  required int metricColumns,
  required VoidCallback reload,
}) {
  if (leaveNote.isNotEmpty) return const [];
  final text = Theme.of(context).textTheme;
  final today = RestaurantTime.todayIso();
  final all = <Map>[for (final l in (leavePage['leaves'] as List?) ?? const []) if (l is Map) l];

  String startOf(Map l) => _s(l, 'start_day', '');
  String nameOf(Map l) => _s(l, 'employee_name', 'Employee');
  bool approved(Map l) => _s(l, 'status', '') == 'approved';

  final onLeave = [for (final l in all) if (approved(l) && _leaveCovers(l, today)) l]
    ..sort((a, b) => nameOf(a).compareTo(nameOf(b)));
  // Strictly after today, so a leave already running is counted once — under
  // "on leave today" — instead of appearing in both registers.
  final ahead = [for (final l in all) if (approved(l) && startOf(l).compareTo(today) > 0) l]
    ..sort((a, b) => startOf(a).compareTo(startOf(b)));
  final pending = [for (final l in all) if (_s(l, 'status', '') == 'requested') l]
    ..sort((a, b) => startOf(a).compareTo(startOf(b)));

  String names(List<Map> ls) {
    if (ls.isEmpty) return '';
    final first = ls.take(2).map(nameOf).join(', ');
    return ls.length > 2 ? '$first +${ls.length - 2}' : first;
  }

  /// The leaves behind one count, each row opening its own record. Null when the
  /// set is empty, which leaves that tile genuinely inert — [_metricTile] then
  /// draws no chevron, no hover lift and no click cursor, because a tap onto
  /// "nothing here" is the dead end these drill-downs exist to remove.
  VoidCallback? openList(String title, String note, List<Map> ls) {
    if (ls.isEmpty) return null;
    return () => _detailSheet(
          context,
          eyebrow: 'Leave',
          title: title,
          children: [
            Text(note, style: text.bodySmall),
            const SizedBox(height: AppSpacing.lg),
            for (final l in ls)
              _sheetRecordRow(
                context,
                title: nameOf(l),
                badge: StatusChip(
                    label: _s(l, 'status', 'requested'),
                    color: _leaveStatusColor(_s(l, 'status', '')),
                    dense: true),
                sub: '${_leaveTypeLabel(_s(l, 'leave_type', ''))} · ${_leaveRange(l)} · '
                    '${_int(l['days']) ?? 1} day${(_int(l['days']) ?? 1) == 1 ? '' : 's'}',
                onTap: () {
                  // Replace rather than stack: from two dialogs deep, "Close"
                  // would drop the reader back onto a list they are done with.
                  Navigator.of(context).pop();
                  _leaveSheet(context, rest, l, canReview: canReview, reload: reload);
                },
              ),
          ],
        );
  }

  return [
    // The filing control sits UNDER the counts rather than in the header's
    // trailing slot: SectionHeader lays trailing out at its intrinsic width, so
    // a labelled button there left the title 25px on a 390px phone at 1.3x.
    SectionHeader(title: 'Leave', count: all.length),
    _dashGrid([
      _metricTile(context,
          label: 'on leave today',
          icon: Icons.beach_access_outlined,
          accent: onLeave.isEmpty ? AppColors.copperHi : AppColors.info,
          value: '${onLeave.length}',
          sub: onLeave.isEmpty ? 'everyone is in' : names(onLeave),
          onTap: openList(
              'On leave today',
              'Approved leave covering ${_fmtDay(today)}. These days are already excluded '
                  'from each person\'s absence count.',
              onLeave)),
      _metricTile(context,
          label: 'awaiting decision',
          icon: Icons.pending_actions,
          accent: pending.isEmpty ? AppColors.copperHi : AppColors.warning,
          value: '${pending.length}',
          sub: pending.isEmpty ? 'nothing to review' : names(pending),
          onTap: openList(
              'Awaiting decision',
              'Filed and not yet decided. Until one is approved its days are NOT excused — '
                  'any that have already passed are counting as unexplained absences.',
              pending)),
      _metricTile(context,
          label: 'booked ahead',
          icon: Icons.event_available,
          value: '${ahead.length}',
          sub: ahead.isEmpty ? 'nothing booked' : 'next ${_leaveRange(ahead.first)}',
          onTap: openList(
              'Booked ahead',
              'Approved leave starting after ${_fmtDay(today)}, earliest first. Leave already '
                  'running is counted under "on leave today" instead.',
              ahead)),
    ], metricColumns),
    const SizedBox(height: AppSpacing.lg),
    if (canReview) ...[
      Align(
        alignment: Alignment.centerLeft,
        child: ForkButton.ghost(
          label: 'Request leave',
          icon: Icons.event_busy,
          dense: true,
          onPressed: () => _requestLeaveForMember(context, rest, p, team, reload),
        ),
      ),
      const SizedBox(height: AppSpacing.lg),
    ],
    if (all.isEmpty)
      Text(
        'No leave on record between ${_fmtDay(_s(leavePage, 'from', ''))} and '
        '${_fmtDay(_s(leavePage, 'to', ''))}.',
        style: text.bodySmall,
      )
    else ...[
      if (pending.isNotEmpty) ...[
        SectionHeader(
            title: 'Awaiting decision', count: pending.length, padding: const EdgeInsets.only(bottom: 10)),
        for (final l in pending) _leaveTeamRow(context, rest, l, canReview: canReview, reload: reload),
        const SizedBox(height: AppSpacing.md),
      ],
      if (onLeave.isNotEmpty) ...[
        SectionHeader(
            title: 'On leave today', count: onLeave.length, padding: const EdgeInsets.only(bottom: 10)),
        for (final l in onLeave) _leaveTeamRow(context, rest, l, canReview: canReview, reload: reload),
        const SizedBox(height: AppSpacing.md),
      ],
      if (ahead.isNotEmpty) ...[
        SectionHeader(
            title: 'Booked ahead', count: ahead.length, padding: const EdgeInsets.only(bottom: 10)),
        for (final l in ahead) _leaveTeamRow(context, rest, l, canReview: canReview, reload: reload),
      ],
      // Rows exist, but none of them is running, waiting or still to come —
      // they are rejected, or approved and already behind us.
      if (pending.isEmpty && onLeave.isEmpty && ahead.isEmpty)
        Text('Nothing current — every leave in this window is decided and past.',
            style: text.bodySmall),
    ],
  ];
}

/// The roster. One compact card per person carrying their performance score;
/// everything behind that score — the four measures, their notes and their
/// weights — plus the leave record and its decisions live in the tap.
///
/// Performance and leave are BOTH optional reads: each is gated on a permission
/// (and a plan feature) this user may not hold, and each is fetched separately
/// so a refusal costs its own section and not the roster. A refusal is reported
/// in words, never swallowed into an empty list that would read as "no leave".
Widget employeesModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () async {
        // Reports the failure instead of hiding it: an empty payload here would
        // be indistinguishable from "this person genuinely has no data".
        Future<Map<String, dynamic>> optional(String path) async {
          try {
            return await rest.getMap(path);
          } catch (e) {
            return <String, dynamic>{'__error': '$e'};
          }
        }

        final canPerf = _holdsAction(p, _analyticsPermissionId) && p.featureEnabled('analytics');
        final canLeave = _holdsAction(p, _attendanceReviewPermissionId) && p.featureEnabled('attendance');
        final results = await Future.wait<dynamic>([
          rest.getMap('/restaurant/users'),
          rest.getList('/roles').catchError((_) => <dynamic>[]),
          p.isAdmin
              ? rest.getMap('/restaurant/password-requests').catchError((_) => <String, dynamic>{})
              : Future<Map<String, dynamic>>.value(<String, dynamic>{}),
          canPerf
              ? optional('/analytics/staff-performance?days=30')
              : Future<Map<String, dynamic>>.value(<String, dynamic>{}),
          // meta=1 for the envelope (and its window), 500 = the server's own cap,
          // which comfortably covers a roster's worth of leave in one page.
          canLeave
              ? optional('/leaves?meta=1&limit=500')
              : Future<Map<String, dynamic>>.value(<String, dynamic>{}),
        ]);
        return {
          'users': ((results[0] as Map)['users'] as List?) ?? [],
          'roles': (results[1] as List?) ?? [],
          'requests': ((results[2] as Map)['requests'] as List?) ?? [],
          'performance': results[3] as Map,
          'leaves': results[4] as Map,
          'can_perf': canPerf,
          'can_leave': canLeave,
        };
      },
      builder: (context, data, reload) {
        final rows = (data['users'] as List?) ?? [];
        final roles = (data['roles'] as List?) ?? [];
        final requests = (data['requests'] as List?) ?? [];
        final perf = (data['performance'] as Map?) ?? const {};
        final leavePage = (data['leaves'] as Map?) ?? const {};
        final canPerf = data['can_perf'] == true;
        final canReview = data['can_leave'] == true;

        // Both sections say WHY they are empty rather than looking like an
        // employee with nothing to show.
        final perfError = _s(perf, '__error', '');
        final perfNote = !canPerf
            ? 'Performance scores need the analytics permission, which this login does not hold.'
            : (perfError.isEmpty ? '' : "Performance scores couldn't be loaded: $perfError");
        final leaveError = _s(leavePage, '__error', '');
        final leaveNote = !canReview
            ? 'Leave records need the Review Attendance permission, which this login does not hold.'
            : (leaveError.isEmpty ? '' : "Leave records couldn't be loaded: $leaveError");

        final perfByEmp = <String, Map>{
          for (final r in (perf['rows'] as List?) ?? const [])
            if (r is Map) '${r['employee_id'] ?? ''}': r,
        }..remove('');
        final leavesByEmp = <String, List<Map>>{};
        for (final l in (leavePage['leaves'] as List?) ?? const []) {
          if (l is! Map) continue;
          final id = '${l['emp_id'] ?? ''}';
          if (id.isEmpty) continue;
          leavesByEmp.putIfAbsent(id, () => <Map>[]).add(l);
        }
        final today = RestaurantTime.todayIso();

        // A CUSTOM role is stored on the employee as its "Roles" uuid, so the chips
        // rendered a raw guid like "d61c1438-4b6f-...". Map it back to the role's
        // name; anything unrecognised (a built-in like "waiter") passes through.
        final roleNameById = <String, String>{
          for (final r in roles)
            '${(r as Map)['id'] ?? ''}'.trim(): '${r['role_name'] ?? ''}'.trim(),
        }..removeWhere((k, v) => k.isEmpty || v.isEmpty);
        // Share the names with screens that only receive a bare role list.
        _cacheCustomRoleNames(roles);
        final text = Theme.of(context).textTheme;

        // Same 4/3/2/1 tiling the Guest book and Orders grids use — a name, a
        // handle, a couple of role chips and a score do not need a full window
        // each, which is what the one-row-per-person list spent on them.
        final width = MediaQuery.sizeOf(context).width;
        final cols = width >= 1500 ? 4 : (width >= 1120 ? 3 : (width >= 720 ? 2 : 1));
        // The scoring boxes each carry a chart, so they need the roomier stat-card
        // breakpoints rather than the dense one-figure tiling the leave counts use.
        final scoreCols = width >= 1500 ? 5 : (width >= 1180 ? 4 : (width >= 900 ? 3 : (width >= 620 ? 2 : 1)));

        // Derived once, then shared: the cards, the scoring boards and the leave
        // register all read the same rows, so none of them can disagree.
        final team = <_TeamMember>[];
        for (final r in rows) {
          final u = r as Map;
          final empId = '${u['employee_id'] ?? u['id'] ?? ''}';
          final roleAll = (u['role_all'] as List?)?.map((e) => '$e').where((s) => s.isNotEmpty).toList() ??
              [_s(u, 'role', 'staff')];
          final name = '${_s(u, 'emp_Fname')} ${_s(u, 'emp_Lname', '')}'.trim();
          final display = name.isEmpty ? _s(u, 'employee_Username') : name;
          team.add(_TeamMember(
            user: u,
            empId: empId,
            display: display,
            initials:
                display.split(RegExp(r'\s+')).where((s) => s.isNotEmpty).take(2).map((s) => s[0]).join(),
            roleLabels: [for (final role in roleAll) roleNameById[role] ?? _roleLabel(role)],
            isSuper: u['is_superadmin'] == true,
            perfRow: perfByEmp[empId],
            leaves: leavesByEmp[empId] ?? const <Map>[],
          ));
        }

        void openMember(_TeamMember m) => _employeeSheet(
              context,
              rest,
              p,
              employee: m.user,
              display: m.display,
              roleLabels: m.roleLabels,
              perfRow: m.perfRow,
              perfMeta: perf,
              perfNote: perfNote,
              leaves: m.leaves,
              leaveNote: leaveNote,
              canReview: canReview,
              reload: reload,
            );

        final cards = <Widget>[];
        for (final member in team) {
          final u = member.user;
          final isSuper = member.isSuper;
          final empId = member.empId;
          final roleLabels = member.roleLabels;
          final display = member.display;
          final initials = member.initials;
          final score = member.perfRow?['score'];
          final myLeaves = member.leaves;
          final pending = myLeaves.where((l) => _s(l, 'status', '') == 'requested').length;
          final onLeaveNow =
              myLeaves.any((l) => _s(l, 'status', '') == 'approved' && _leaveCovers(l, today));

          cards.add(ForkCard(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            onTap: () => openMember(member),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                InitialsAvatar(
                  initials: initials.isEmpty ? '?' : initials,
                  color: isSuper ? AppColors.warning : AppColors.copper,
                ),
                const SizedBox(width: AppSpacing.md),
                Expanded(
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                    Row(children: [
                      Flexible(
                        child: Text(display,
                            style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                      ),
                      if (isSuper) ...[
                        const SizedBox(width: 6),
                        Tooltip(
                          message: 'Superadmin (owner)',
                          child: Icon(Icons.workspace_premium, size: 15, color: AppColors.warning),
                        ),
                      ],
                    ]),
                    const SizedBox(height: 2),
                    Text('@${_s(u, 'employee_Username')}',
                        style: text.bodySmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                  ]),
                ),
                PopupMenuButton<String>(
                  icon: Icon(Icons.more_vert, size: 18, color: AppColors.textSecondary),
                  onSelected: (v) async {
                    if (v == 'roles') {
                      final changed = await showModalBottomSheet<bool>(
                        context: context,
                        showDragHandle: true,
                        isScrollControlled: true,
                        builder: (_) => _ManageRolesSheet(rest: rest, employee: u, customRoles: roles, isSuperadmin: isSuper),
                      );
                      if (changed == true) reload();
                    } else if (v == 'leave') {
                      await _requestLeave(context, rest, p,
                          empId: empId, empName: display, reload: reload);
                    } else if (v == 'password') {
                      await _resetPassword(context, rest, u);
                    } else if (v == 'remove') {
                      await _removeEmployee(context, rest, u, reload);
                    }
                  },
                  itemBuilder: (_) => [
                    const PopupMenuItem(value: 'roles', child: ListTile(leading: Icon(Icons.shield_outlined), title: Text('Manage roles'), dense: true)),
                    if (empId.isNotEmpty && (canReview || empId == p.employeeId))
                      const PopupMenuItem(value: 'leave', child: ListTile(leading: Icon(Icons.event_busy), title: Text('Request leave'), dense: true)),
                    if (p.isAdmin)
                      const PopupMenuItem(value: 'password', child: ListTile(leading: Icon(Icons.password), title: Text('Reset password'), dense: true)),
                    if (p.isAdmin && !isSuper)
                      PopupMenuItem(value: 'remove', child: ListTile(leading: Icon(Icons.person_remove, color: AppColors.danger), title: Text('Remove', style: TextStyle(color: AppColors.danger)), dense: true)),
                  ],
                ),
              ]),
              const SizedBox(height: 10),
              Wrap(spacing: 6, runSpacing: 6, children: [
                // Two chips is what a card column fits; the rest are named in
                // full on the detail sheet rather than overflowing the tile.
                for (final label in roleLabels.take(2)) _roleChip(label),
                if (roleLabels.length > 2) _roleChip('+${roleLabels.length - 2}'),
              ]),
              const SizedBox(height: 10),
              // A Wrap, not a Row: a chip carries its own intrinsic width, and
              // squeezing one into an Expanded makes it clip its OWN label
              // rather than shrink. Two chips side by side do not fit the
              // narrowest column this grid produces, so they flow instead.
              Wrap(spacing: 8, runSpacing: 6, crossAxisAlignment: WrapCrossAlignment.center, children: [
                // Where the scores could not be read at all, the reason is
                // stated ONCE above the grid rather than repeated on every card.
                if (perfNote.isEmpty)
                  score == null
                      ? StatusChip(
                          label: 'Not enough data', color: AppColors.neutral, dense: true)
                      : StatusChip(
                          label: '${_numOf(score).round()} / 100 score',
                          color: _perfScoreColor(_numOf(score)),
                          dense: true),
                if (onLeaveNow)
                  const InfoChip(icon: Icons.beach_access_outlined, label: 'On leave')
                else if (pending > 0)
                  StatusChip(
                      label: '$pending to review', color: AppColors.warning, dense: true),
              ]),
            ]),
          ));
        }

        return Scaffold(
          backgroundColor: Colors.transparent,
          floatingActionButton: FloatingActionButton.extended(
            onPressed: () => _addEmployee(context, rest, reload),
            icon: const Icon(Icons.person_add),
            label: const Text('Add employee'),
          ),
          body: rows.isEmpty
              ? const EmptyState(
                  icon: Icons.badge_outlined,
                  title: 'No employees yet',
                  caption: 'Add your first team member to hand out logins and roles.',
                )
              : ListView(
                  padding: AppSpacing.pageNarrow,
                  children: [
                    if (p.isAdmin && requests.isNotEmpty)
                      _PasswordRequestsBanner(rest: rest, requests: requests, reload: reload),
                    SectionHeader(
                      title: 'Team',
                      count: rows.length,
                      // Flexible, because SectionHeader lays its trailing out at
                      // intrinsic width: on a 390px phone at a 1.3x text scale
                      // this chip took the whole header and left the title 25px.
                      // Bounding it is also what lets ChipLabel ellipsise — it
                      // only shrinks when something above it sets a width.
                      trailing: perfNote.isEmpty && perf.isNotEmpty
                          ? Flexible(
                              child: InfoChip(
                                  icon: Icons.speed,
                                  label: 'Scored over ${_int(perf['window_days']) ?? 30} days'),
                            )
                          : null,
                    ),
                    // Said once, above the grid, rather than on every card.
                    if (perfNote.isNotEmpty || leaveNote.isNotEmpty) ...[
                      Padding(
                        padding: const EdgeInsets.only(bottom: 12),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          if (perfNote.isNotEmpty) Text(perfNote, style: text.bodySmall),
                          if (leaveNote.isNotEmpty) Text(leaveNote, style: text.bodySmall),
                        ]),
                      ),
                    ],
                    _dashGrid(cards, cols),
                    const SizedBox(height: 28),
                    // Added below the roster, not above it: the roster is what
                    // this tab IS, and both sections summarise it.
                    ..._scoringBand(context,
                        team: team,
                        perf: perf,
                        perfNote: perfNote,
                        columns: scoreCols,
                        openMember: openMember),
                    ..._leaveSection(context, rest, p,
                        leavePage: leavePage,
                        team: team,
                        leaveNote: leaveNote,
                        canReview: canReview,
                        metricColumns: _metricCols(width),
                        reload: reload),
                    const SizedBox(height: 76), // clears the FAB
                  ],
                ),
        );
      },
    );

// Admin: set a new password for an employee (also fulfils a forgot-password request).
Future<void> _resetPassword(BuildContext context, RestClient rest, Map employee) async {
  final messenger = ScaffoldMessenger.of(context);
  final ctrl = TextEditingController();
  final name = '${_s(employee, 'emp_Fname')} ${_s(employee, 'emp_Lname', '')}'.trim();
  final pass = await showDialog<String>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: Text('Reset password — ${name.isEmpty ? _s(employee, 'employee_Username') : name}'),
      content: TextField(
        controller: ctrl,
        autofocus: true,
        decoration: const InputDecoration(labelText: 'New password', hintText: 'At least 4 characters', border: OutlineInputBorder()),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(ctx, ctrl.text.trim()), child: const Text('Set password')),
      ],
    ),
  );
  if (pass == null || pass.isEmpty) return;
  final employeeId = '${employee['employee_id'] ?? employee['id'] ?? ''}';
  try {
    await rest.post('/restaurant/users/password', {'employeeId': employeeId, 'password': pass});
    messenger.showSnackBar(const SnackBar(content: Text('Password updated.')));
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

Future<void> _removeEmployee(BuildContext context, RestClient rest, Map employee, VoidCallback reload) async {
  final messenger = ScaffoldMessenger.of(context);
  final name = '${_s(employee, 'emp_Fname')} ${_s(employee, 'emp_Lname', '')}'.trim();
  final ok = await _confirm(context, 'Remove employee', 'Remove ${name.isEmpty ? _s(employee, 'employee_Username') : name}? This cannot be undone.');
  if (!ok) return;
  final employeeId = '${employee['employee_id'] ?? employee['id'] ?? ''}';
  try {
    await rest.delete('/restaurant/users', {'employeeId': employeeId});
    messenger.showSnackBar(const SnackBar(content: Text('Employee removed.')));
    reload();
  } catch (e) {
    messenger.showSnackBar(SnackBar(content: Text('$e')));
  }
}

// Pending forgot-password requests, shown to admins atop the Employees list. Each
// can be fulfilled (set a new password) or dismissed.
class _PasswordRequestsBanner extends StatelessWidget {
  final RestClient rest;
  final List requests;
  final VoidCallback reload;
  const _PasswordRequestsBanner({required this.rest, required this.requests, required this.reload});

  @override
  Widget build(BuildContext context) {
    final messenger = ScaffoldMessenger.of(context);
    final text = Theme.of(context).textTheme;
    // Warning-tinted banner card — tint always paired with its labelled chip.
    return Container(
      margin: const EdgeInsets.only(bottom: 14),
      padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
      decoration: BoxDecoration(
        color: AppColors.tint(AppColors.warning),
        borderRadius: AppRadius.cardAll,
        border: Border.all(color: AppColors.edge(AppColors.warning)),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Icon(Icons.lock_reset, size: 16, color: AppColors.warning),
          const SizedBox(width: 8),
          Expanded(
            child: Text('${requests.length} password reset request${requests.length > 1 ? 's' : ''}',
                style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
          ),
          StatusChip(label: 'Action needed', color: AppColors.warning, dense: true),
        ]),
        const SizedBox(height: 6),
        ...requests.map((r) {
          final req = r as Map;
          return Padding(
            padding: const EdgeInsets.symmetric(vertical: 6),
            child: Row(children: [
              Expanded(
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                  Text(_s(req, 'name'), style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                  const SizedBox(height: 2),
                  Text('@${_s(req, 'username')}', style: text.bodySmall),
                ]),
              ),
              const SizedBox(width: AppSpacing.md),
              ForkButton.ghost(
                label: 'Reset',
                icon: Icons.password,
                dense: true,
                onPressed: () async {
                  await _resetPassword(context, rest, {
                    'employee_id': req['employee_id'],
                    'emp_Fname': _s(req, 'name'),
                    'employee_Username': _s(req, 'username'),
                  });
                  reload();
                },
              ),
              const SizedBox(width: 6),
              ForkIconButton(
                icon: Icons.close,
                tooltip: 'Dismiss',
                onPressed: () async {
                  try {
                    await rest.post('/restaurant/password-requests/${req['id']}/dismiss');
                    reload();
                  } catch (e) {
                    messenger.showSnackBar(SnackBar(content: Text('$e')));
                  }
                },
              ),
            ]),
          );
        }),
      ]),
    );
  }
}

/// The connection card's chip and sentence, from the agent's [PrinterLink].
///
/// THREE STATES, because "Connected" used to cover two. A socket whose transport
/// is up but which the server never put in the outlet's room receives no
/// `bill:print` at all, and showing it green is how a till went a whole lunch
/// printing nothing while every screen said it was fine. Amber is the honest
/// colour for it: the agent is working on it (see PrinterService's watchdog),
/// and if it cannot, it will say so or send the user to sign in.
({String label, Color color, String caption}) printerLinkStatus(PrinterLink link, {required bool unconfigured}) =>
    switch (link) {
      PrinterLink.listening =>
        (label: 'Listening', color: AppColors.success, caption: 'Listening for print jobs in realtime'),
      PrinterLink.joining =>
        (label: 'Connecting', color: AppColors.warning, caption: 'Connected, not receiving jobs yet — retrying'),
      PrinterLink.offline => (
          label: 'Offline',
          color: AppColors.danger,
          caption: unconfigured ? 'Add a printer below and this device starts printing' : 'Not connected to realtime',
        ),
    };

// Built-in thermal printer agent UI: set up the printers, watch the realtime
// connection, and monitor the print queue/log. The PrinterService runs in the
// background (started at login) — this screen just configures and observes it.
//
// THIS SCREEN IS NO LONGER WINDOWS-ONLY. It used to open on "Desktop only",
// because the only transport was the Windows spooler. There is now a second one
// — a raw socket to a network printer's port 9100 (NetworkPrinter) — which needs
// no plugin and works identically on a phone, so an Android tablet configured
// with a printer address is a real print client rather than a viewer. Each half
// of the screen is still gated on the transport it belongs to: the spooler
// controls appear only where a spooler exists, and nothing here offers a control
// that cannot do anything on the device showing it.
Widget printerModule(RestClient rest, Profile p) {
  final svc = PrinterService.instance;
  return AnimatedBuilder(
    animation: svc,
    builder: (context, _) {
      if (!svc.supported) {
        return const EmptyState(
          icon: Icons.print_disabled_outlined,
          title: 'Printing unavailable',
          caption: 'This build has no way to reach a printer.',
        );
      }
      final text = Theme.of(context).textTheme;
      final messenger = ScaffoldMessenger.of(context);
      // A device with no spooler and no network printer cannot print anything,
      // and PrinterService deliberately keeps it out of the outlet's realtime
      // room until it can — so "Offline" here is a setup step, not a fault, and
      // the card below says which.
      final unconfigured = !svc.hasSpooler && svc.networkPrinters.isEmpty;
      final link = printerLinkStatus(svc.linkState, unconfigured: unconfigured);
      return ListView(padding: AppSpacing.pageNarrow, children: [
        // Connection status
        ForkCard(
          padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
          child: Row(children: [
            AnimatedSwitcher(
              duration: AppDurations.base,
              switchInCurve: Curves.easeOut,
              switchOutCurve: Curves.easeIn,
              child: StatusChip(
                key: ValueKey('printer-conn-${svc.linkState.name}'),
                label: link.label,
                color: link.color,
              ),
            ),
            const SizedBox(width: AppSpacing.md),
            Expanded(
              child: Text(
                  link.caption,
                  style: text.bodySmall,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis),
            ),
            if (svc.paused) ...[
              StatusChip(label: 'Paused', color: AppColors.warning, dense: true),
              const SizedBox(width: AppSpacing.sm),
            ],
            ForkIconButton(
              tooltip: svc.paused ? 'Resume printing' : 'Pause printing',
              icon: svc.paused ? Icons.play_arrow : Icons.pause,
              onPressed: () => svc.setPaused(!svc.paused),
            ),
          ]),
        ),
        const SizedBox(height: AppSpacing.xxl),
        _NetworkPrintersCard(svc: svc),
        const SizedBox(height: AppSpacing.xxl),
        const SectionHeader(title: 'Default printer', padding: EdgeInsets.only(bottom: 6)),
        Text(
            'Everything prints here unless a rule below sends it somewhere else. '
            'A dish whose station has no rule still comes out here, so nothing is ever lost.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.md),
        ForkCard(
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Row(children: [
              Expanded(
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12),
                  decoration: BoxDecoration(
                    color: AppColors.inset,
                    borderRadius: AppRadius.inputAll,
                    border: Border.all(color: AppColors.border),
                  ),
                  child: DropdownButton<String>(
                    isExpanded: true,
                    underline: const SizedBox.shrink(),
                    dropdownColor: AppColors.cardRaised,
                    borderRadius: AppRadius.controlAll,
                    // Both transports in one list: a Windows queue and a
                    // `tcp://host:port` printer are the same choice to the
                    // person making it.
                    value: svc.selectedPrinter != null && svc.knowsTarget(svc.selectedPrinter!)
                        ? svc.selectedPrinter
                        : null,
                    hint: Text(
                        svc.selectedPrinter == null || svc.selectedPrinter!.isEmpty
                            ? (svc.targets.isEmpty ? 'No printers set up yet' : 'Select a printer')
                            : PrintTarget.label(svc.selectedPrinter!),
                        style: text.bodyMedium),
                    items: [
                      for (final t in svc.targets)
                        DropdownMenuItem(
                            value: t, child: Text(PrintTarget.label(t), overflow: TextOverflow.ellipsis)),
                    ],
                    onChanged: (v) { if (v != null) svc.setSelectedPrinter(v); },
                  ),
                ),
              ),
              // Only where there is a spooler to enumerate. On a phone this
              // button could only ever report zero.
              if (svc.hasSpooler) ...[
                const SizedBox(width: AppSpacing.sm),
                ForkIconButton(
                  tooltip: 'Discover printers',
                  icon: Icons.refresh,
                  onPressed: () => svc.discoverPrinters(),
                ),
              ],
            ]),
            if (svc.selectedPrinter != null && svc.selectedPrinter!.isNotEmpty)
              Padding(
                padding: const EdgeInsets.only(top: 10),
                child: Row(children: [
                  Icon(Icons.check_circle, size: 14, color: AppColors.success),
                  const SizedBox(width: 6),
                  Expanded(
                      child: Text('Default: ${PrintTarget.label(svc.selectedPrinter!)}',
                          style: text.bodySmall)),
                ]),
              ),
            const SizedBox(height: AppSpacing.md),
            Align(
              alignment: Alignment.centerLeft,
              child: ForkButton.ghost(
                label: 'Print test slip',
                icon: Icons.print_outlined,
                onPressed: () async {
                  // The REASON, not a bare failure: a network printer fails in
                  // ways the owner can fix, and each of them looks the same
                  // behind "print failed".
                  final err = await svc.testPrint();
                  messenger.showSnackBar(SnackBar(content: Text(err ?? 'Test slip sent.')));
                },
              ),
            ),
          ]),
        ),
        const SizedBox(height: AppSpacing.xxl),
        _PrinterRoutingCard(rest: rest, svc: svc),
        const SizedBox(height: AppSpacing.xxl),
        SectionHeader(
          title: 'Print queue',
          count: svc.queue.length,
          padding: const EdgeInsets.only(bottom: 10),
          trailing: svc.queue.isNotEmpty
              ? ForkButton.subtle(label: 'Clear', icon: Icons.clear_all, onPressed: svc.clearQueue)
              : null,
        ),
        if (svc.queue.isEmpty)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 4),
            child: Text('No pending jobs.', style: text.bodySmall),
          )
        else
          ...svc.queue.map((j) => Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: ForkCard(
                  inset: true,
                  padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
                  child: Row(children: [
                    Icon(Icons.receipt_long, size: 15, color: AppColors.copperHi),
                    const SizedBox(width: AppSpacing.md),
                    Expanded(
                      child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                        Text(j.billId, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                        const SizedBox(height: 2),
                        Text('${j.bytes.length} bytes${j.attempts > 0 ? ' · attempt ${j.attempts}' : ''}',
                            style: text.bodySmall),
                        // WHY IT HAS NOT PRINTED. A docket stuck in this queue is
                        // a docket the kitchen never saw; leaving the reason in
                        // the log only means nobody reads it until the table
                        // complains.
                        if (j.lastError != null) ...[
                          const SizedBox(height: 3),
                          Text(j.lastError!,
                              style: text.bodySmall!.copyWith(color: AppColors.danger)),
                        ],
                      ]),
                    ),
                  ]),
                ),
              )),
        const SizedBox(height: AppSpacing.xxl),
        const SectionHeader(title: 'Activity log', padding: EdgeInsets.only(bottom: 10)),
        ForkCard(
          inset: true,
          padding: const EdgeInsets.all(14),
          child: Container(
            constraints: const BoxConstraints(maxHeight: 260),
            child: svc.logs.isEmpty
                ? Text('No activity yet.', style: text.bodySmall)
                : ListView(
                    shrinkWrap: true,
                    children: [
                      for (final l in svc.logs)
                        Text(l,
                            style: TextStyle(
                                fontFamily: 'monospace', fontSize: 11, color: AppColors.textSecondary)),
                    ],
                  ),
          ),
        ),
      ]);
    },
  );
}

/// PRINTERS THIS DEVICE REACHES OVER THE NETWORK — and the reason a phone can
/// print at all.
///
/// THE PROBLEM. `PrinterService.supported` used to be `WinRawPrinter.supported`,
/// so on Android the whole printing module opened on "Desktop only". That was
/// never a statement about the app: the backend renders the finished ESC/POS
/// docket itself (escpos.ts) and pushes the bytes down the `bill:print` socket.
/// A Windows till writes them to a spooler queue. Nothing stopped a phone
/// writing the SAME bytes to a socket — it just had nowhere to write them to.
///
/// THE TRANSPORT. Port 9100 ("RAW"/JetDirect) is a bare TCP stream that a
/// thermal printer treats as its input buffer. `dart:io`'s Socket is the entire
/// driver: no plugin, no platform channel, no pairing, no runtime permission
/// beyond INTERNET, which the app already holds. See NetworkPrinter.
///
/// WHAT IT CANNOT REACH: BLUETOOTH PRINTERS. A handheld belt printer is usually
/// Bluetooth SPP/BLE, not networked, and nothing here can talk to one — that
/// needs a plugin, a pairing flow and the Android 12+ BLUETOOTH_CONNECT runtime
/// permission. The caption below says so in as many words rather than letting an
/// owner discover it by typing an address that can never work.
///
/// SHOWN ON EVERY PLATFORM, because it works on every platform. A Windows till
/// with three USB printers has no need of it and simply leaves it empty; a
/// tablet has nothing else.
class _NetworkPrintersCard extends StatefulWidget {
  const _NetworkPrintersCard({required this.svc});

  final PrinterService svc;

  @override
  State<_NetworkPrintersCard> createState() => _NetworkPrintersCardState();
}

class _NetworkPrintersCardState extends State<_NetworkPrintersCard> {
  /// Add a printer by address, with a TEST that runs BEFORE it is saved.
  ///
  /// The test is the whole point of the dialog. An address is four numbers and a
  /// port; every way of getting it wrong produces the same silence at the pass
  /// hours later, so the owner gets to put paper on the floor while they are
  /// still looking at the box they typed it into.
  Future<void> _add() async {
    final host = TextEditingController();
    final port = TextEditingController(text: '9100');
    String? note;
    var busy = false;

    final saved = await showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setLocal) {
          int portOf() => int.tryParse(port.text.trim()) ?? -1;
          return AlertDialog(
            title: const Text('Add a network printer'),
            content: SizedBox(
              width: 380,
              child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                TextField(
                  controller: host,
                  autofocus: true,
                  keyboardType: TextInputType.url,
                  decoration: const InputDecoration(
                    labelText: 'Printer IP address',
                    hintText: '192.168.1.50',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: port,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Port',
                    hintText: '9100',
                    helperText: 'Almost always 9100.',
                    border: OutlineInputBorder(),
                  ),
                ),
                if (note != null) ...[
                  const SizedBox(height: 10),
                  Text(note!, style: Theme.of(ctx).textTheme.bodySmall),
                ],
              ]),
            ),
            actions: [
              TextButton(onPressed: busy ? null : () => Navigator.pop(ctx, false), child: const Text('Cancel')),
              TextButton(
                onPressed: busy
                    ? null
                    : () async {
                        setLocal(() { busy = true; note = 'Sending a test slip…'; });
                        final err = await widget.svc.testNetworkAddress(host.text, portOf());
                        if (!ctx.mounted) return;
                        setLocal(() {
                          busy = false;
                          note = err ?? 'Test slip sent. If paper came out, save it.';
                        });
                      },
                child: const Text('Test print'),
              ),
              FilledButton(
                onPressed: busy
                    ? null
                    : () async {
                        final err = await widget.svc.addNetworkPrinter(host.text, portOf());
                        if (!ctx.mounted) return;
                        if (err != null) { setLocal(() => note = err); return; }
                        Navigator.pop(ctx, true);
                      },
                child: const Text('Save'),
              ),
            ],
          );
        },
      ),
    );
    if (saved == true && mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final svc = widget.svc;
    final text = Theme.of(context).textTheme;
    final messenger = ScaffoldMessenger.of(context);
    final printers = svc.networkPrinters;
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      SectionHeader(
        title: 'Network printers',
        count: printers.length,
        padding: const EdgeInsets.only(bottom: 6),
        trailing: ForkButton.subtle(label: 'Add', icon: Icons.add, onPressed: _add),
      ),
      Text(
          svc.hasSpooler
              ? 'A printer with an IP address can be printed to directly, without installing it in Windows. '
                  'This is also how a phone or tablet prints — it needs no printer driver at all.'
              : 'This device prints straight to a printer on the same Wi-Fi, using its IP address. '
                  'Add one and this device starts printing dockets like a till does. '
                  'Bluetooth-only printers cannot be reached this way.',
          style: text.bodySmall),
      const SizedBox(height: AppSpacing.md),
      ForkCard(
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          if (printers.isEmpty)
            Text(
                svc.hasSpooler
                    ? 'None added. Windows printers are listed below as usual.'
                    : 'None added yet. Find the printer\'s IP address on its own '
                        'self-test slip or in its network settings, then Add it above.',
                style: text.bodySmall)
          else
            for (final target in printers)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 4),
                child: Row(children: [
                  Icon(Icons.lan_outlined, size: 15, color: AppColors.textSecondary),
                  const SizedBox(width: AppSpacing.md),
                  Expanded(
                    child: Text(PrintTarget.label(target),
                        style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                  ),
                  ForkIconButton(
                    tooltip: 'Print a test slip',
                    icon: Icons.print_outlined,
                    onPressed: () async {
                      final err = await svc.testPrintTo(target);
                      messenger.showSnackBar(SnackBar(content: Text(err ?? 'Test slip sent.')));
                    },
                  ),
                  const SizedBox(width: 4),
                  ForkIconButton(
                    tooltip: 'Remove this printer',
                    icon: Icons.delete_outline,
                    onPressed: () async {
                      await svc.removeNetworkPrinter(target);
                      if (context.mounted) setState(() {});
                    },
                  ),
                ]),
              ),
          const SizedBox(height: AppSpacing.sm),
          Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Icon(Icons.info_outline, size: 14, color: AppColors.textSecondary),
            const SizedBox(width: 6),
            Expanded(
              child: Text(
                  'A test slip proves the connection, not the paper: port 9100 sends no reply, '
                  'so a printer that is out of paper accepts the job in silence — check the roll. '
                  'Every device you set up prints the jobs its rules give it, so if a till is '
                  'already printing everything, give this one only the jobs it should take.',
                  style: text.bodySmall),
            ),
          ]),
        ]),
      ),
    ]);
  }
}

/// WHAT EACH PRINTER PRINTS.
///
/// A restaurant with three printers — one at the pass, one in the bar, one at
/// the till — needs to say which is which. The backend already splits a kitchen
/// ticket into one docket per STATION (escpos.ts buildKotBase64) and stamps each
/// `bill:print` event with that station plus its `kind`, so this screen is only
/// choosing a destination for facts the wire already carries.
///
/// THE STATION LIST IS THE MENU'S, NOT TYPED HERE. A free-text station box is a
/// dead control waiting to happen: one typo and the rule silently never matches,
/// with no way to tell from looking at it. So the choices come from the
/// restaurant's own kitchen sections (Restaurant.kitchen_sections, the same list
/// the menu editor assigns dishes from), unioned with any station this till has
/// actually been sent a docket for — which covers a dish whose station was set
/// before the section list existed.
///
/// THE DESTINATIONS ARE THIS DEVICE'S, whichever transport they use. A rule can
/// name a Windows spooler queue or a `tcp://host:port` network printer, and the
/// dropdown lists whatever this particular device can actually reach — which is
/// why the map is stored per device and per outlet. A tablet in the bar and the
/// till at the front desk see different printers and neither one's rules would
/// mean anything on the other.
class _PrinterRoutingCard extends StatefulWidget {
  const _PrinterRoutingCard({required this.rest, required this.svc});

  final RestClient rest;
  final PrinterService svc;

  @override
  State<_PrinterRoutingCard> createState() => _PrinterRoutingCardState();
}

class _PrinterRoutingCardState extends State<_PrinterRoutingCard> {
  List<String> _menuStations = const [];

  @override
  void initState() {
    super.initState();
    _loadStations();
  }

  /// The kitchen sections, fetched once. A failure costs the SUGGESTIONS, not
  /// the screen: the rules this till has already been given still show, and so
  /// do the stations it has seen dockets for.
  Future<void> _loadStations() async {
    try {
      final settings = await widget.rest.getMap('/restaurant/settings');
      final raw = settings['kitchen_sections'];
      if (raw is List && mounted) {
        setState(() => _menuStations = [
              for (final s in raw)
                if ('$s'.trim().isNotEmpty) '$s'.trim(),
            ]);
      }
    } catch (_) {
      /* suggestions only — the card works without them */
    }
  }

  /// Every station worth offering a rule for, menu order first.
  List<String> get _stations {
    final out = <String>[];
    for (final s in [..._menuStations, ...widget.svc.seenStations]) {
      if (out.any((e) => e.toLowerCase() == s.toLowerCase())) continue;
      out.add(s);
    }
    return out;
  }

  @override
  Widget build(BuildContext context) {
    final svc = widget.svc;
    final text = Theme.of(context).textTheme;
    final roles = <(String, String)>[
      (PrintRole.bill, 'Bills'),
      (PrintRole.anyKot, 'Kitchen dockets (any station)'),
      for (final station in _stations) (PrintRole.kotStation(station), 'Kitchen: $station'),
    ];
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      SectionHeader(
        title: 'What each printer prints',
        count: svc.routes.length,
        padding: const EdgeInsets.only(bottom: 6),
      ),
      Text(
          'Send bills to the till printer and each kitchen station to its own. '
          'One printer can take several jobs — leave everything on Default if a single printer does it all.',
          style: text.bodySmall),
      const SizedBox(height: AppSpacing.md),
      ForkCard(
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          for (final (role, label) in roles) ...[
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Row(children: [
                Icon(
                  role == PrintRole.bill ? Icons.receipt_long_outlined : Icons.soup_kitchen_outlined,
                  size: 15,
                  color: AppColors.textSecondary,
                ),
                const SizedBox(width: AppSpacing.md),
                Expanded(
                  child: Text(label, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                ),
                const SizedBox(width: AppSpacing.sm),
                SizedBox(
                  width: 190,
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 10),
                    decoration: BoxDecoration(
                      color: AppColors.inset,
                      borderRadius: AppRadius.inputAll,
                      border: Border.all(color: AppColors.border),
                    ),
                    child: DropdownButton<String>(
                      isExpanded: true,
                      isDense: true,
                      underline: const SizedBox.shrink(),
                      dropdownColor: AppColors.cardRaised,
                      borderRadius: AppRadius.controlAll,
                      // The stored name only shows as selected when this device
                      // can actually reach it — the same condition printerFor
                      // routes on, so the screen can never claim a destination
                      // the job would not really go to.
                      value: svc.routes[role] != null && svc.knowsTarget(svc.routes[role]!)
                          ? svc.routes[role]
                          : '',
                      items: [
                        const DropdownMenuItem(value: '', child: Text('Default', overflow: TextOverflow.ellipsis)),
                        for (final t in svc.targets)
                          DropdownMenuItem(
                              value: t, child: Text(PrintTarget.label(t), overflow: TextOverflow.ellipsis)),
                      ],
                      onChanged: (v) {
                        if (v == null || v.isEmpty) {
                          svc.clearRoute(role);
                        } else {
                          svc.setRoute(role, v);
                        }
                      },
                    ),
                  ),
                ),
              ]),
            ),
          ],
          if (roles.length <= 2)
            Padding(
              padding: const EdgeInsets.only(top: 8),
              child: Text(
                  'No kitchen stations configured yet. Assign stations to dishes in Menu and they appear here.',
                  style: text.bodySmall),
            ),
          const SizedBox(height: AppSpacing.sm),
          Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            // Not const: AppColors resolves through the appearance controller, so
            // these values change with the active design system.
            Icon(Icons.info_outline, size: 14, color: AppColors.textSecondary),
            const SizedBox(width: 6),
            Expanded(
              child: Text(
                  'Anything without a rule — or whose printer is switched off or uninstalled — prints on the default printer instead of being dropped.',
                  style: text.bodySmall),
            ),
          ]),
        ]),
      ),
    ]);
  }
}

/// A stable identity for the Settings payload: equal payloads give equal keys,
/// in any key order. Used to remount the Settings cards only when the live
/// settings differ from what they were seeded with.
@visibleForTesting
String settingsPayloadKey(Map m) {
  Object? canon(Object? v) {
    if (v is Map) {
      final keys = v.keys.map((k) => '$k').toList()..sort();
      return {for (final k in keys) k: canon(v[k])};
    }
    if (v is List) return [for (final e in v) canon(e)];
    return v;
  }
  try {
    return jsonEncode(canon(m));
  } catch (_) {
    // Not JSON (never the case for this payload): fall back to identity, which
    // remounts on every new payload — the safe direction for a form.
    return '${identityHashCode(m)}';
  }
}

Widget settingsModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () async {
        final prof = await rest.getMap('/restaurant/profile');
        Map brand = {};
        Map settings = {};
        try {
          brand = await rest.getMap('/qr/${p.restaurantUsername}/branding');
        } catch (_) {/* branding optional */}
        try {
          settings = await rest.getMap('/restaurant/settings');
        } catch (_) {/* settings optional */}
        return {
          ...prof,
          'theme_color': brand['theme_color'],
          'logo_url': brand['logo_url'] ?? prof['restaurant_logo_url'],
          'auto_push_orders': settings['auto_push_orders'] ?? true,
          // The zone every timestamp in the app is rendered in.
          'timezone': settings['timezone'] ?? RestaurantTime.defaultZone,
          'currency': settings['currency'] ?? '₹',
          'payment_methods': settings['payment_methods'] ?? [],
          'taxes': settings['taxes'] ?? [],
          'service_charge': settings['service_charge'] ?? 0,
          'discount_approval_threshold': settings['discount_approval_threshold'] ?? 0,
          'bill_reopen_window_min': settings['bill_reopen_window_min'] ?? 240,
          'razorpay_key_id': settings['razorpay_key_id'] ?? '',
          'razorpay_configured': settings['razorpay_configured'] == true,
          // Guest messaging (SMS/WhatsApp): provider secret is write-only.
          'msg_provider': settings['msg_provider'] ?? 'none',
          'msg_sender': settings['msg_sender'] ?? '',
          'msg_key_id': settings['msg_key_id'] ?? '',
          'msg_secret_configured': settings['msg_secret_configured'] == true,
          'msg_reminder_hours': settings['msg_reminder_hours'] ?? 2,
          'msg_webhook_secret': settings['msg_webhook_secret'] ?? '',
          'feedback_config': settings['feedback_config'] ?? {},
          'bill_logo_svg': settings['bill_logo_svg'] ?? '',
          'bill_paper_width': settings['bill_paper_width'] ?? '80mm',
          // The "Bill details" card. THESE WERE NEVER COPIED IN when that card
          // shipped (1.7.4): it read all five off this map, found none of them,
          // and opened blank on every tenant — so pressing Save wrote '' over a
          // legal name, GSTIN and QR sentence the owner had already set. The QR
          // switch saves in that same POST, which would have made the wipe the
          // price of flipping it.
          'bill_legal_name': settings['bill_legal_name'] ?? '',
          'bill_gstin': settings['bill_gstin'] ?? '',
          'bill_qr_note': settings['bill_qr_note'] ?? '',
          'bill_qr_note_default': settings['bill_qr_note_default'] ?? '',
          'bill_qr_note_max': settings['bill_qr_note_max'] ?? 120,
          // Whether the customer bill prints its QR. Absent reads as ON — see
          // [billShowsQr].
          'bill_show_qr': billShowsQr(settings),
          // Walk-in queue: whether waiting guests see the menu / pre-order.
          'queue_show_menu': brand['queue_show_menu'] ?? settings['queue_show_menu'] ?? true,
          // Whether guests must enter the per-table 4-digit OTP before ordering.
          'require_table_otp': settings['require_table_otp'] == true,
          // Whether barking an order also prints its kitchen docket. ABSENT
          // READS AS ON, matching the backend: the column is NULL for every
          // restaurant that predates migration 040, and an older backend that
          // has never heard of the key must not present the feature as off.
          'kot_auto_print': settings['kot_auto_print'] != false,
          // Which kitchen docket prints, and how large the reference docket's
          // type is (migration 050), and whether this backend has the two
          // settings at all. One that has never heard of them prints ONLY the
          // classic docket and ignores a save of them, so the card is not shown
          // there (see kotDocketSettingsSupported) rather than showing a
          // reference / standard choice that backend does not print.
          kotDocketSupportedKey: kotDocketSettingsSupported(settings),
          kotPrintStyleKey: readKotPrintStyle(settings),
          kotTextSizeKey: readKotTextSize(settings),
          // Guest page theme. The resolved config is on both endpoints; the font
          // allowlist, the live/legacy field split and the enum option lists only
          // on /settings (older backends omit them and the editor falls back to
          // the shipped contract).
          'brand_config': settings['brand_config'] ?? brand['brand_config'] ?? const {},
          'brand_fonts': settings['brand_fonts'] ?? const [],
          'brand_fields': settings['brand_fields'] ?? const {},
          'brand_field_options': settings['brand_field_options'] ?? const {},
          'brand_schemes': settings['brand_schemes'] ?? const [],
        };
      },
      // Landing: the template settings idiom — a single centered column of
      // grouped cards under copper-tick section headers. Every card carries
      // its own titleMedium title + gray caption; groups sit 24px apart.
      // EVERY CARD BELOW IS SEEDED FROM `m` ONCE, in its own initState, and saves
      // what it was seeded with plus the owner's edits. AsyncView deliberately
      // keeps this subtree mounted when the live refresh lands over a saved copy
      // (so a page never jumps to the top — see _StaleFrame), which left the cards
      // showing, and SAVING, the saved copy: a payment mode switched off on the
      // web came back on the next time Settings was saved here. Keying the page on
      // the payload remounts the cards exactly when the settings actually changed,
      // and never when the refresh only confirmed what was already on screen.
      builder: (context, m, reload) => KeyedSubtree(
        key: ValueKey<String>('settings:${settingsPayloadKey(m)}'),
        child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 760),
          child: ListView(padding: AppSpacing.pageNarrow, children: [
            const SectionHeader(title: 'Profile'),
            _ProfileEditCard(rest: rest, initial: m, reload: reload),
            const SizedBox(height: AppSpacing.xxl),
            // Sits high on the page on purpose: it governs how every other
            // screen's numbers are dated.
            const SectionHeader(title: 'Time'),
            _TimezoneCard(
              rest: rest,
              initial: _s(m, 'timezone', RestaurantTime.defaultZone),
              reload: reload,
            ),
            const SizedBox(height: AppSpacing.xxl),
            const SectionHeader(title: 'Ordering'),
            _AutoPushCard(rest: rest, initial: m['auto_push_orders'] != false),
            const SizedBox(height: 14),
            _RequireTableOtpCard(rest: rest, initial: m['require_table_otp'] == true),
            const SizedBox(height: 14),
            _KotAutoPrintCard(rest: rest, initial: m['kot_auto_print'] != false),
            const SizedBox(height: 14),
            // Directly under the auto-print switch: both answer "what reaches
            // the kitchen printer", and this one is the recovery control somebody
            // is hunting for while a kitchen printer feeds blank tickets. Only
            // against a backend that has the two settings (the loader's
            // kotDocketSupportedKey): an older one prints classic and stores
            // neither.
            if (m[kotDocketSupportedKey] == true) ...[
