// Set the SVG bill logo: paste markup or load a .svg file. Stored via settings
// and rasterized server-side for the thermal print; shown crisp on digital bills.
class _BillLogoCard extends StatefulWidget {
  final RestClient rest;
  final String initialSvg;
  final String initialPaperWidth;
  final VoidCallback reload;
  const _BillLogoCard({required this.rest, required this.initialSvg, required this.initialPaperWidth, required this.reload});
  @override
  State<_BillLogoCard> createState() => _BillLogoCardState();
}

class _BillLogoCardState extends State<_BillLogoCard> {
  late final TextEditingController _svg;
  late String _paperWidth;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _svg = TextEditingController(text: widget.initialSvg);
    _paperWidth = widget.initialPaperWidth == '58mm' ? '58mm' : '80mm';
  }

  @override
  void dispose() {
    _svg.dispose();
    super.dispose();
  }

  Future<void> _pickFile() async {
    final messenger = ScaffoldMessenger.of(context);
    final picked = await FilePicker.pickFiles(type: FileType.custom, allowedExtensions: ['svg'], withData: true);
    if (picked == null || picked.files.isEmpty) return;
    final bytes = picked.files.first.bytes;
    if (bytes == null) {
      messenger.showSnackBar(const SnackBar(content: Text('Could not read the file.')));
      return;
    }
    final text = utf8.decode(bytes, allowMalformed: true).trim();
    if (!text.toLowerCase().contains('<svg')) {
      messenger.showSnackBar(const SnackBar(content: Text("That file doesn't look like an SVG.")));
      return;
    }
    setState(() => _svg.text = text);
  }

  Future<void> _save({bool clear = false}) async {
    final messenger = ScaffoldMessenger.of(context);
    final value = clear ? '' : _svg.text.trim();
    if (!clear && value.isNotEmpty && !value.toLowerCase().contains('<svg')) {
      messenger.showSnackBar(const SnackBar(content: Text('Enter valid SVG markup (must contain an <svg> tag).')));
      return;
    }
    setState(() => _busy = true);
    try {
      await widget.rest.post('/restaurant/settings', {'bill_logo_svg': value});
      if (clear) _svg.clear();
      messenger.showSnackBar(SnackBar(content: Text(clear ? 'Bill logo cleared.' : 'Bill logo saved.')));
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _savePaperWidth(String v) async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _paperWidth = v);
    try {
      await widget.rest.post('/restaurant/settings', {'bill_paper_width': v});
      messenger.showSnackBar(SnackBar(content: Text('Paper size set to $v.')));
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }

  // Segmented pill choice in the template voice — recessed track, active pill
  // lifted with a hairline border (selection also carries its text label).
  Widget _choice(List<(String, String)> options, String value, ValueChanged<String> onPick) {
    return Container(
      padding: const EdgeInsets.all(3),
      decoration: BoxDecoration(
        color: AppColors.inset,
        borderRadius: AppRadius.controlAll,
        border: Border.all(color: AppColors.border),
      ),
      child: Row(mainAxisSize: MainAxisSize.min, children: [
        for (final (v, label) in options)
          MouseRegion(
            cursor: SystemMouseCursors.click,
            child: GestureDetector(
              onTap: _busy || v == value ? null : () => onPick(v),
              child: AnimatedContainer(
                duration: AppDurations.fast,
                curve: Curves.easeOut,
                padding: const EdgeInsets.symmetric(horizontal: 13, vertical: 5),
                decoration: BoxDecoration(
                  color: v == value ? Colors.white.withValues(alpha: 0.08) : Colors.transparent,
                  borderRadius: BorderRadius.circular(7),
                  border: Border.all(color: v == value ? AppColors.borderStrong : Colors.transparent),
                ),
                child: Text(
                  label,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: v == value ? FontWeight.w600 : FontWeight.w500,
                    letterSpacing: 0.2,
                    color: v == value ? AppColors.textPrimary : AppColors.textSecondary,
                  ),
                ),
              ),
            ),
          ),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final hasLogo = _svg.text.trim().isNotEmpty;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Text('Bill printing', style: text.titleMedium),
        const SizedBox(height: 4),
        Text(
            'Thermal paper size + a vector (SVG) logo printed at the top of the bill (crisp at any size, separate from the customer-page logo). Paste the SVG markup or load a .svg file.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Row(children: [
          Expanded(child: Text('THERMAL PAPER SIZE', style: text.labelSmall)),
          _choice(const [('80mm', '80mm'), ('58mm', '58mm')], _paperWidth, _savePaperWidth),
        ]),
        const Divider(height: 24),
        Row(children: [
          // Paper-white preview tile — the logo prints on paper, so its stand-in
          // stays paper-white by design (dark chrome around it).
          AnimatedContainer(
            duration: AppDurations.base,
            curve: Curves.easeOut,
            width: 56,
            height: 56,
            decoration: BoxDecoration(
              color: const Color(0xFFFAFAF7),
              borderRadius: AppRadius.tileAll,
              border: Border.all(color: hasLogo ? AppColors.edge(AppColors.success) : AppColors.borderStrong),
            ),
            child: Icon(hasLogo ? Icons.receipt_long : Icons.image_outlined,
                size: 22, color: hasLogo ? const Color(0xFF221510) : const Color(0xFF9A978F)),
          ),
          const SizedBox(width: AppSpacing.md),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
              Text(hasLogo ? 'Bill logo is set' : 'No bill logo yet', style: text.titleSmall),
              const SizedBox(height: 3),
              Text('BILL HEADER · SVG', style: text.labelSmall),
            ]),
          ),
          const SizedBox(width: AppSpacing.md),
          AnimatedSwitcher(
            duration: AppDurations.base,
            switchInCurve: Curves.easeOut,
            child: StatusChip(
              key: ValueKey('bill-logo-$hasLogo'),
              label: hasLogo ? 'Set' : 'Empty',
              color: hasLogo ? AppColors.success : AppColors.neutral,
              dense: true,
            ),
          ),
        ]),
        const SizedBox(height: AppSpacing.lg),
        Text('SVG MARKUP', style: text.labelSmall),
        const SizedBox(height: 6),
        TextField(
          controller: _svg,
          minLines: 4,
          maxLines: 10,
          style: const TextStyle(fontFamily: 'monospace', fontSize: 12),
          decoration: const InputDecoration(
            hintText: '<svg xmlns="http://www.w3.org/2000/svg" ...> … </svg>',
            isDense: true,
          ),
          onChanged: (_) => setState(() {}),
        ),
        const SizedBox(height: AppSpacing.lg),
        Wrap(spacing: 8, runSpacing: 8, children: [
          ForkButton.ghost(label: 'Load .svg file', icon: Icons.upload_file, dense: true, onPressed: _busy ? null : _pickFile),
          ForkButton(
            label: _busy ? 'Saving…' : 'Save bill logo',
            icon: Icons.save_outlined,
            dense: true,
            onPressed: _busy ? null : () => _save(),
          ),
          if (hasLogo)
            ForkButton.ghost(
              label: 'Clear',
              icon: Icons.delete_outline,
              dense: true,
              onPressed: _busy ? null : () => _save(clear: true),
            ),
        ]),
      ]),
    );
  }
}

// What the printed bill says about the restaurant, and what it says above the
// feedback/valet QR.
//
// ALL THREE FIELDS ARE OPTIONAL AND THAT IS THE POINT. An Indian bill normally
// carries the registered entity behind the trading name ("… HOSPITALITY LLP")
// and the GST registration, but plenty of tenants have neither — and they must
// get a CLEAN receipt. An unset field prints nothing at all: no orphan "GSTN :"
// label, no blank line standing in for the field that is missing.
//
// The QR sentence used to be a string literal inside the renderer, identical on
// every tenant's paper. Clearing this box restores that built-in line rather
// than printing nothing, so a restaurant that never opens this card sees its
// receipt unchanged.
//
// THE QR ITSELF CAN BE SWITCHED OFF (migration 047) — for a tenant with no valet
// and no use for feedback, whose guests were being handed a code that leads
// nowhere they care about. Off, the paper ends at the total (or the disclaimer):
// no sentence and no code. It saves with the rest of this card rather than on
// the tap like the Ordering switches, because it and the sentence are one
// decision about the bottom of the bill. The sentence box is DISABLED, not
// hidden, while the QR is off: the owner's wording stays visible and is still
// saved, so turning the QR back on brings it back.
//
// Admin-only, like every other write on POST /restaurant/settings.
class _BillIdentityCard extends StatefulWidget {
  final RestClient rest;
  final String initialLegalName;
  final String initialGstin;
  final String initialQrNote;
  // The line the printer falls back to when the note is blank, and the cap the
  // backend enforces. Both come from the settings document rather than being
  // written down again here, so this card can never disagree with escpos.ts.
  final String qrNoteDefault;
  final int qrNoteMax;
  // `bill_show_qr`, already resolved through [billShowsQr] — so a tenant whose
  // settings carry no such key arrives here as true.
  final bool initialShowQr;
  final VoidCallback reload;
  const _BillIdentityCard({
    required this.rest,
    required this.initialLegalName,
    required this.initialGstin,
    required this.initialQrNote,
    required this.qrNoteDefault,
    required this.qrNoteMax,
    this.initialShowQr = true,
    required this.reload,
  });
  @override
  State<_BillIdentityCard> createState() => _BillIdentityCardState();
}

class _BillIdentityCardState extends State<_BillIdentityCard> {
  late final TextEditingController _legalName;
  late final TextEditingController _gstin;
  late final TextEditingController _qrNote;
  late bool _showQr = widget.initialShowQr;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _legalName = TextEditingController(text: widget.initialLegalName);
    _gstin = TextEditingController(text: widget.initialGstin);
    _qrNote = TextEditingController(text: widget.initialQrNote);
  }

  @override
  void dispose() {
    _legalName.dispose();
    _gstin.dispose();
    _qrNote.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      // Every field, empty or not, and the QR switch as an explicit boolean —
      // see [billDetailsSettingsBody] for why each is sent.
      await widget.rest.post(
        '/restaurant/settings',
        billDetailsSettingsBody(
          legalName: _legalName.text,
          gstin: _gstin.text,
          qrNote: _qrNote.text,
          showQr: _showQr,
        ),
      );
      messenger.showSnackBar(const SnackBar(content: Text('Bill details saved.')));
      widget.reload();
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final noteLen = _qrNote.text.characters.length;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Text('Bill details', style: text.titleMedium),
        const SizedBox(height: 4),
        Text(
            'Printed under your restaurant name on every bill, plus the message above the feedback QR code. Leave a field blank and it is left off the receipt entirely.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Text('REGISTERED BUSINESS NAME', style: text.labelSmall),
        const SizedBox(height: 6),
        TextField(
          controller: _legalName,
          decoration: const InputDecoration(
            hintText: 'e.g. Navkrish Hospitality LLP',
            helperText: 'The legal entity behind the trading name.',
            isDense: true,
          ),
        ),
        const SizedBox(height: AppSpacing.lg),
        Text('GSTIN', style: text.labelSmall),
        const SizedBox(height: 6),
        TextField(
          controller: _gstin,
          textCapitalization: TextCapitalization.characters,
          decoration: const InputDecoration(
            hintText: 'e.g. 29AAXFN2701Q1ZF',
            helperText: 'Printed as "GSTN : …". Leave blank if you are not GST registered.',
            isDense: true,
          ),
        ),
        const SizedBox(height: AppSpacing.lg),
        // The QR switch, in the Ordering switches' row idiom: title and caption
        // on the left, the compact switch on the right. Unlike those it does not
        // save on the tap — it rides the Save below with the sentence it governs.
        Row(children: [
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
              Text('Print QR code on the bill', style: text.titleSmall),
              const SizedBox(height: 3),
              Text('The feedback / valet QR at the bottom of every customer bill.', style: text.bodySmall),
            ]),
          ),
          const SizedBox(width: AppSpacing.md),
          SizedBox(
            height: 24,
            child: FittedBox(
              fit: BoxFit.contain,
              child: Switch(
                key: const ValueKey('bill-show-qr-switch'),
                value: _showQr,
                onChanged: _busy ? null : (v) => setState(() => _showQr = v),
              ),
            ),
          ),
        ]),
        const SizedBox(height: AppSpacing.lg),
        Text('MESSAGE ABOVE THE QR CODE', style: text.labelSmall),
        const SizedBox(height: 6),
        TextField(
          key: const ValueKey('bill-qr-note-field'),
          controller: _qrNote,
          // Disabled rather than hidden while the QR is off: nothing prints above
          // a code that is not there, but the wording is kept (and saved) for
          // the day it is switched back on.
          enabled: _showQr,
          minLines: 2,
          maxLines: 3,
          maxLength: widget.qrNoteMax,
          decoration: InputDecoration(
            hintText: widget.qrNoteDefault.isNotEmpty ? widget.qrNoteDefault : 'Scan the QR code below',
            helperText: !_showQr
                ? 'Not printed while the QR code is off.'
                : widget.qrNoteDefault.isNotEmpty
                    ? 'Leave blank to use the default: "${widget.qrNoteDefault}"'
                    : 'Leave blank to use the built-in default.',
            helperMaxLines: 3,
            counterText: '$noteLen/${widget.qrNoteMax}',
            isDense: true,
          ),
          onChanged: (_) => setState(() {}),
        ),
        const SizedBox(height: AppSpacing.lg),
        Wrap(spacing: 8, runSpacing: 8, children: [
          ForkButton(
            label: _busy ? 'Saving…' : 'Save bill details',
            icon: Icons.save_outlined,
            dense: true,
            onPressed: _busy ? null : _save,
          ),
        ]),
      ]),
    );
  }
}

/// THE FEEDBACK-FORM KEYS AN OWNER ACTUALLY CHANGED, as the save body.
///
/// This card used to post the WHOLE form from the state it read when it was
/// built. Valet parking now has a second editor (web Settings > Feedback form),
/// and the backend writes feedback settings as a PATCH — so a card opened before
/// someone flipped valet on the web would, on saving an unrelated welcome-text
/// edit, have written its stale `valet_enabled` back over theirs. Sending only
/// what differs from the card's own baseline keeps every other editor's change.
///
/// Categories compare as the ordered label list the card edits; keys are derived
/// from labels exactly as the save always derived them.
Map<String, dynamic> feedbackSettingsChanges(Map<String, dynamic> baseline, Map<String, dynamic> current) {
  final out = <String, dynamic>{};
  for (final key in const ['title', 'subtitle', 'review_url', 'valet_enabled', 'require_image']) {
    if (baseline[key] != current[key]) out[key] = current[key];
  }
  final before = (baseline['categories'] as List?) ?? const [];
  final after = (current['categories'] as List?) ?? const [];
  final same = before.length == after.length &&
      [for (var i = 0; i < before.length; i++) (before[i] as Map)['label'] == (after[i] as Map)['label']].every((b) => b);
  if (!same) out['categories'] = after;
  return out;
}

// Configure the customer feedback form (title, valet parking, categories, review link).
class _FeedbackSettingsCard extends StatefulWidget {
  final RestClient rest;
  final Map initial;
  final VoidCallback reload;
  const _FeedbackSettingsCard({required this.rest, required this.initial, required this.reload});
  @override
  State<_FeedbackSettingsCard> createState() => _FeedbackSettingsCardState();
}

class _FeedbackSettingsCardState extends State<_FeedbackSettingsCard> {
  late final TextEditingController _title;
  late final TextEditingController _subtitle;
  late final TextEditingController _reviewUrl;
  late bool _valet;
  late bool _requireImage;
  late List<TextEditingController> _cats;
  bool _saving = false;

  /// What the form held when it was loaded or last saved — the base the save
  /// compares against (see [feedbackSettingsChanges]).
  late Map<String, dynamic> _baseline;

  /// The form as the owner has it now, in save-body shape.
  Map<String, dynamic> _current() => {
        'title': _title.text.trim(),
        'subtitle': _subtitle.text.trim(),
        'valet_enabled': _valet,
        'require_image': _requireImage,
        'review_url': _reviewUrl.text.trim(),
        'categories': _cats
            .map((c) => c.text.trim())
            .where((s) => s.isNotEmpty)
            .map((label) => {
                  'label': label,
                  'key': label.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '_').replaceAll(RegExp(r'^_+|_+$'), ''),
                })
            .toList(),
      };

  @override
  void initState() {
    super.initState();
    final c = widget.initial;
    _title = TextEditingController(text: _s(c, 'title', 'Restaurant Feedback'));
    _subtitle = TextEditingController(text: _s(c, 'subtitle', ''));
    _reviewUrl = TextEditingController(text: _s(c, 'review_url', ''));
    _valet = c['valet_enabled'] == true;
    _requireImage = c['require_image'] == true;
    final cats = (c['categories'] as List?) ?? const [];
    final labels = cats.isEmpty
        ? const ['Initial Greeting', 'Waiter Service', 'Food Quality', 'Ambience', 'Restroom', 'Valet Parking']
        : cats.map((e) => _s(e as Map, 'label')).where((s) => s.isNotEmpty).toList();
    _cats = labels.map((s) => TextEditingController(text: s)).toList();
    _baseline = _current();
  }

  @override
  void dispose() {
    _title.dispose();
    _subtitle.dispose();
    _reviewUrl.dispose();
    for (final c in _cats) {
      c.dispose();
    }
    super.dispose();
  }

  Future<void> _save() async {
    final messenger = ScaffoldMessenger.of(context);
    final current = _current();
    final changes = feedbackSettingsChanges(_baseline, current);
    if (changes.isEmpty) {
      messenger.showSnackBar(const SnackBar(content: Text('Nothing to save — the feedback form is unchanged.')));
      return;
    }
    setState(() => _saving = true);
    try {
      await widget.rest.post('/restaurant/settings', {'feedback_config': changes});
      _baseline = current;
      messenger.showSnackBar(const SnackBar(content: Text('Feedback form saved.')));
