// THE TWO KITCHEN DOCKET SETTINGS (migration 050) — which docket the kitchen
// printers print, and how large the reference docket's type is. The web
// dashboard's "KOT print style" card offers the same two choices in the same
// words; models/kot_docket_settings.dart holds them.
//
// THE STYLE IS A RECOVERY CONTROL. The reference docket prints as an image; a
// kitchen printer that cannot draw one feeds BLANK PAPER, which is an order
// nobody cooks. This is the switch back to the plain text docket.
//
// THE SIZE is the client's "The font sizes must be smaller in the KOT":
// Small / Standard (their reference ticket exactly) / Large. It sizes the
// reference docket only — the classic text docket prints in the printer's own
// font and ignores it. The copy says so, and the card repeats it while classic
// is the style selected.
//
// SAVED ON PICK, one key per save, like the web card and the switches above:
// whoever changes either is standing at a printer comparing paper. The choice
// moves first so it answers the tap, and is put back if the save is refused —
// a control that sat on the old value mid-request gets pressed twice.
//
// Admin-only, like the rest of this screen; POST /restaurant/settings checks
// "Manage Restaurant Settings", and a 403 reverts with the server's sentence.
// A 200 whose settings document lacks the key (a backend rolled back since the
// page loaded, which ignores the key) stored nothing: kotDocketSaved throws,
// and the card reverts with kotDocketNotSupported rather than confirming.
class _KotDocketCard extends StatefulWidget {
  final RestClient rest;
  final String initialStyle;
  final String initialTextSize;
  const _KotDocketCard({required this.rest, required this.initialStyle, required this.initialTextSize});

  @override
  State<_KotDocketCard> createState() => _KotDocketCardState();
}

class _KotDocketCardState extends State<_KotDocketCard> {
  late String _style = widget.initialStyle;
  late String _size = widget.initialTextSize;
  bool _busy = false;

  void _put(String key, String value) {
    if (key == kotPrintStyleKey) {
      _style = value;
    } else {
      _size = value;
    }
  }

  Future<void> _save(String key, String value) async {
    final previous = key == kotPrintStyleKey ? _style : _size;
    if (_busy || value == previous) return;
    setState(() {
      _put(key, value);
      _busy = true;
    });
    try {
      final reply = await widget.rest.post('/restaurant/settings', {key: value});
      if (!mounted) return;
      final saved = kotDocketSaved(reply, key, value);
      setState(() => _put(key, saved));
      // The latest pick's sentence, not the one before it: an owner flipping
      // style then size should not read the first confirmation for four seconds.
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(SnackBar(content: Text(kotDocketSavedMessage(key, saved, style: _style))));
    } catch (e) {
      if (mounted) {
        setState(() => _put(key, previous)); // revert on failure
        final msg = (e is ApiException && e.status == 403)
            ? e.sentenceOr('Only an admin can change how kitchen dockets print.')
            : '$e';
        ScaffoldMessenger.of(context)
          ..hideCurrentSnackBar()
          ..showSnackBar(SnackBar(content: Text(msg)));
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  // One choice: a radio mark, the owner's words, and a line of detail — the
  // queue-menu editor's option rows.
  Widget _option(TextTheme text, String key, KotDocketOption o, String selected) {
    final on = o.value == selected;
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: ForkCard(
        key: ValueKey('$key-${o.value}'),
        inset: true,
        selected: on,
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
        onTap: _busy ? null : () => _save(key, o.value),
        child: Row(children: [
          Icon(
            on ? Icons.radio_button_checked : Icons.radio_button_unchecked,
            size: 16,
            color: on ? AppColors.copperHi : AppColors.textTertiary,
          ),
          const SizedBox(width: AppSpacing.sm),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
              Text(o.label, style: text.titleSmall),
              Text(o.detail, style: text.bodySmall),
            ]),
          ),
        ]),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [
          Icon(Icons.print_outlined, size: 18, color: AppColors.copperHi),
          const SizedBox(width: AppSpacing.sm),
          Expanded(child: Text(kotPrintStyleTitle, style: text.titleMedium)),
        ]),
        const SizedBox(height: 4),
        Text(kotPrintStyleDescription, style: text.bodySmall),
        const SizedBox(height: AppSpacing.md),
        for (final o in kotPrintStyleOptions) _option(text, kotPrintStyleKey, o, _style),
        Text(kotPrintStyleHelp, style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Text(kotTextSizeTitle, style: text.titleSmall),
        const SizedBox(height: AppSpacing.sm),
        for (final o in kotTextSizeOptions) _option(text, kotTextSizeKey, o, _size),
        Text(kotTextSizeHelp, style: text.bodySmall),
        if (_style == kotPrintStyleClassic) ...[
          const SizedBox(height: 4),
          Text(
            kotTextSizeClassicNote,
            key: const ValueKey('kot-text-size-classic-note'),
            style: text.bodySmall!.copyWith(fontWeight: FontWeight.w600),
          ),
        ],
      ]),
    );
  }
}

// The restaurant's reporting timezone — the single anchor every timestamp in
// this app is rendered in (orders, bills, bookings, waitlist, attendance, cash
// sessions, audit rows, reports, printed tickets and exported filenames), via
// RestaurantTime. Stored as `timezone` on POST /restaurant/settings, which is
// admin-only and 400s an id Intl does not know.
class _TimezoneCard extends StatefulWidget {
  final RestClient rest;
  final String initial;
  final VoidCallback reload;
  const _TimezoneCard({required this.rest, required this.initial, required this.reload});

  @override
  State<_TimezoneCard> createState() => _TimezoneCardState();
}

class _TimezoneCardState extends State<_TimezoneCard> {
  late String _zone = widget.initial;
  Timer? _tick;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    // The settings read is authoritative for this session too — the shell's
    // /restaurant/timezones call and this one must not disagree.
    RestaurantTime.adopt(widget.initial);
    // The card shows a live clock, so it needs a second hand.
    _tick = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _tick?.cancel();
    super.dispose();
  }

  Future<void> _pick() async {
    final chosen = await showDialog<String>(
      context: context,
      builder: (_) => _TimezoneDialog(rest: widget.rest, current: _zone),
    );
    if (!mounted || chosen == null || chosen.isEmpty || chosen == _zone) return;
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _busy = true);
    try {
      await widget.rest.post('/restaurant/settings', {'timezone': chosen});
      RestaurantTime.adopt(chosen);
      if (mounted) setState(() => _zone = chosen);
      messenger.showSnackBar(SnackBar(
        content: Text('Timezone set to $chosen. Every timestamp now reads '
            '${RestaurantTime.offsetLabelOf(chosen)}.'),
      ));
      widget.reload();
    } catch (e) {
      // 403 = not an admin; 400 = the backend rejected the id (its message
      // names the offending zone, so show it verbatim).
      final msg = (e is ApiException && e.status == 403)
          ? e.sentenceOr('Only an admin can change the restaurant timezone.')
          : '$e';
      messenger.showSnackBar(SnackBar(content: Text(msg)));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final supported = tzZoneKnown(_zone);
    final now = RestaurantTime.nowIn(_zone);
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Text('Restaurant timezone', style: text.titleMedium),
        const SizedBox(height: 4),
        Text(
          'Every time this app shows — order placed, bill settled, booking, shift, '
          'audit entry, report range, printed ticket — is written in this zone, on '
          'every device, whatever each machine\'s own clock is set to. Change it only '
          'if the restaurant actually moves.',
          style: text.bodySmall,
        ),
        const SizedBox(height: AppSpacing.lg),
        Wrap(spacing: 24, runSpacing: 12, children: [
          MicroStat(value: _zone, label: 'zone'),
          MicroStat(
            value: now == null ? '—' : RestaurantTime.clockIn(_zone),
            label: 'local time now',
          ),
          MicroStat(value: RestaurantTime.offsetLabelOf(_zone), label: 'offset from UTC'),
        ]),
        if (!supported)
          Padding(
            padding: const EdgeInsets.only(top: AppSpacing.md),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Icon(Icons.warning_amber, size: 14, color: AppColors.warning),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  'This app build does not carry the offset rules for "$_zone", so it is '
                  'falling back to each device\'s own clock. Update the app, or pick a '
                  'zone from the list below.',
                  style: text.bodySmall!.copyWith(color: AppColors.warning),
                ),
              ),
            ]),
          ),
        const Divider(height: 28),
        Row(children: [
          Expanded(
            child: Text(
              'Daylight saving is handled per timestamp — a winter and a summer order in '
              'the same zone render at their own offsets, not one fixed number.',
              style: text.bodySmall!.copyWith(fontSize: 11.5),
            ),
          ),
          const SizedBox(width: AppSpacing.md),
          ForkButton(
            label: _busy ? 'Saving…' : 'Change',
            icon: Icons.public,
            dense: true,
            onPressed: _busy ? null : _pick,
          ),
        ]),
      ]),
    );
  }
}

// Timezone picker: the backend's list (GET /restaurant/timezones) with a search
// box, each row previewing that zone's current local time. Zones this build has
// no offset rules for are listed but not selectable — choosing one would look
// like it worked and then quietly render every timestamp in device time.
class _TimezoneDialog extends StatefulWidget {
  final RestClient rest;
  final String current;
  const _TimezoneDialog({required this.rest, required this.current});

  @override
  State<_TimezoneDialog> createState() => _TimezoneDialogState();
}

class _TimezoneDialogState extends State<_TimezoneDialog> {
  // Seeded from the bundled table so the picker works offline, then replaced by
  // the server's list (the authority on what POST /restaurant/settings accepts).
  List<String> _zones = tzZoneNames;
  final _search = TextEditingController();
  String _query = '';

  @override
  void initState() {
    super.initState();
    widget.rest.getMap('/restaurant/timezones').then((m) {
      final list = [for (final z in (m['timezones'] as List?) ?? const []) '$z'];
      if (mounted && list.isNotEmpty) setState(() => _zones = list);
    }).catchError((_) {/* offline — the bundled list still works */});
  }

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final q = _query.trim().toLowerCase().replaceAll(' ', '_');
    final shown = q.isEmpty ? _zones : _zones.where((z) => z.toLowerCase().contains(q)).toList();
    return Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        width: 460,
        padding: const EdgeInsets.all(22),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.borderStrong),
        ),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxHeight: 560),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('TIMESTAMPS', style: text.labelSmall),
            const SizedBox(height: 6),
            Text('Restaurant timezone', style: text.titleMedium),
            const SizedBox(height: AppSpacing.lg),
            TextField(
              controller: _search,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: 'Search (city or region)',
                prefixIcon: Icon(Icons.search, size: 18),
                isDense: true,
              ),
              onChanged: (v) => setState(() => _query = v),
            ),
            const SizedBox(height: AppSpacing.md),
            if (shown.isEmpty)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 16),
                child: Text('No zone matches "$_query".', style: text.bodySmall),
              )
            else
              Flexible(
                child: ListView.separated(
                  shrinkWrap: true,
                  itemCount: shown.length,
                  separatorBuilder: (_, _) => const SizedBox(height: 6),
                  itemBuilder: (_, i) {
                    final z = shown[i];
                    final selected = z == widget.current;
                    final supported = tzZoneKnown(z);
                    return ForkCard(
                      inset: true,
                      selected: selected,
                      onTap: supported ? () => Navigator.pop(context, z) : null,
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
                      child: Row(children: [
                        Icon(selected ? Icons.check_circle : Icons.public,
                            size: 14,
                            color: selected
                                ? AppColors.copperHi
                                : supported
                                    ? AppColors.textTertiary
                                    : AppColors.warning),
                        const SizedBox(width: AppSpacing.sm),
                        Expanded(
                          child: Text(z,
                              style: text.titleSmall!.copyWith(
                                color: supported ? null : AppColors.textTertiary,
                              ),
                              overflow: TextOverflow.ellipsis),
                        ),
                        const SizedBox(width: AppSpacing.sm),
                        Text(
                          supported
                              ? '${RestaurantTime.clockIn(z)} · ${RestaurantTime.offsetLabelOf(z)}'
                              : 'not in this app build',
                          style: text.bodySmall!.copyWith(fontSize: 11),
                        ),
                      ]),
                    );
                  },
                ),
              ),
            const SizedBox(height: AppSpacing.lg),
            Row(children: [
              Expanded(
                child: Text('${_zones.length} zones · offsets from this build\'s table '
                    '($tzDataFromYear–$tzDataToYear)', style: text.bodySmall!.copyWith(fontSize: 11)),
              ),
              ForkButton.ghost(label: 'Cancel', dense: true, onPressed: () => Navigator.pop(context)),
            ]),
          ]),
        ),
      ),
    );
  }
}

// Billing controls: manager-approval threshold for staff discounts + how long
// a closed bill stays re-openable. Saved via POST /restaurant/settings.
class _BillingControlsCard extends StatefulWidget {
  final RestClient rest;
  final double initialThreshold;
  final int initialReopenWindow;
  final VoidCallback reload;
  const _BillingControlsCard({
    required this.rest,
    required this.initialThreshold,
    required this.initialReopenWindow,
    required this.reload,
  });

  @override
  State<_BillingControlsCard> createState() => _BillingControlsCardState();
}

class _BillingControlsCardState extends State<_BillingControlsCard> {
  late final TextEditingController _threshold =
      TextEditingController(text: widget.initialThreshold <= 0 ? '' : _trimNum(widget.initialThreshold));
  late final TextEditingController _reopen =
      TextEditingController(text: '${widget.initialReopenWindow}');
  bool _busy = false;

  static String _trimNum(double v) => v == v.roundToDouble() ? '${v.round()}' : '$v';

  @override
  void dispose() {
    _threshold.dispose();
    _reopen.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    final threshold = double.tryParse(_threshold.text.trim());
    final reopen = int.tryParse(_reopen.text.trim());
    if (_threshold.text.trim().isNotEmpty && (threshold == null || threshold < 0)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Discount threshold must be a non-negative amount.')));
      return;
    }
    if (reopen == null || reopen < 0) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Re-open window must be a non-negative number of minutes.')));
      return;
    }
    setState(() => _busy = true);
    try {
      await widget.rest.post('/restaurant/settings', {
        'discount_approval_threshold': threshold ?? 0,
        'bill_reopen_window_min': reopen,
      });
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Billing controls saved.')));
        widget.reload();
      }
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Text('Billing controls', style: text.titleMedium),
        const SizedBox(height: 4),
        Text('Manager approval for large staff discounts + how long a closed bill stays re-openable.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Text('DISCOUNT APPROVAL THRESHOLD', style: text.labelSmall),
        const SizedBox(height: 6),
        TextField(
          controller: _threshold,
          keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(hintText: '0', isDense: true),
        ),
        const SizedBox(height: 6),
        Text('Staff discounts above this amount need manager approval. 0 = every discount applies directly.',
            style: text.bodySmall!.copyWith(fontSize: 11)),
        const SizedBox(height: AppSpacing.lg),
        Text('BILL RE-OPEN WINDOW (MINUTES)', style: text.labelSmall),
        const SizedBox(height: 6),
        TextField(
          controller: _reopen,
          keyboardType: TextInputType.number,
          decoration: const InputDecoration(hintText: '240', isDense: true),
        ),
        const SizedBox(height: 6),
        Text('How long after settling a bill an admin can still re-open it.',
            style: text.bodySmall!.copyWith(fontSize: 11)),
        const SizedBox(height: AppSpacing.lg),
        Align(
          alignment: Alignment.centerRight,
          child: ForkButton(
            label: _busy ? 'Saving…' : 'Save',
            icon: Icons.save_outlined,
            dense: true,
            onPressed: _busy ? null : _save,
          ),
        ),
      ]),
    );
  }
}

// Currency picker + the restaurant's payment modes: switch any on or off, rename
// any, require a screenshot, offer it on the guest QR page — and ADD ITS OWN.
//
// "There has to be an option to add mode of payments, it's not there." This card
// used to render a closed list of eight and said it chose what GUESTS can use; its
// switches never reached the till. Now it edits the one list both this app's
// settle sheet and the web dashboard's pickers read (GET /restaurant/settings
// `payment_methods`, models/payment_modes.dart):
//   * A NEW MODE'S NAME IS PERMANENT — it is what every bill settled with it
//     stores and what reports group by. The LABEL can change any time.
//   * NOTHING IS DELETED. A mode is switched off; its old bills keep their name.
//   * Some names are refused (Complimentary / NC / Staff meal: use Mark as
//     non-chargeable; Credit / Due: no money has arrived; built-ins; report
//     rows). The server refuses them regardless and its sentence is shown as-is.
//   * Modes you add are NOT cash: the drawer counts Cash only.
class _PaymentSettingsCard extends StatefulWidget {
  final RestClient rest;
  final String initialCurrency;
  final List initialMethods;
  final VoidCallback reload;
  const _PaymentSettingsCard({required this.rest, required this.initialCurrency, required this.initialMethods, required this.reload});

  @override
  State<_PaymentSettingsCard> createState() => _PaymentSettingsCardState();
}

class _PaymentSettingsCardState extends State<_PaymentSettingsCard> {
  // Mutable (NOT const) — we add the saved currency if it isn't a preset.
  final List<String> _currencies = ['₹', '\$', '€', '£', 'AED', '¥'];
  late String _currency;
  late List<PaymentMode> _methods;
  final Map<String, TextEditingController> _labels = {};
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _currency = widget.initialCurrency.isNotEmpty ? widget.initialCurrency : '₹';
    if (!_currencies.contains(_currency)) _currencies.add(_currency);
    _adopt(PaymentModes.parse(widget.initialMethods));
  }

  @override
  void dispose() {
    for (final c in _labels.values) {
      c.dispose();
    }
    super.dispose();
  }

  /// Take [modes] as the card's list, keeping a label box per mode.
  void _adopt(List<PaymentMode> modes) {
    _methods = modes;
    for (final m in modes) {
      final c = _labels[m.id];
      if (c == null) {
        _labels[m.id] = TextEditingController(text: m.label);
      } else if (c.text != m.label) {
        c.text = m.label;
      }
    }
  }

  void _patch(String id, PaymentMode Function(PaymentMode) change) {
    setState(() => _methods = [for (final m in _methods) m.id == id ? change(m) : m]);
  }

  /// The list as it is on screen, labels from their boxes.
  List<PaymentMode> get _current =>
      [for (final m in _methods) m.copyWith(label: PaymentModes.tidy(_labels[m.id]?.text ?? m.label))];

  String? _labelRefusal(PaymentMode m) =>
      PaymentModes.labelRefusal(_labels[m.id]?.text ?? m.label, m.id, _current);

  Future<bool> _save({List<PaymentMode>? modes, String message = 'Payment settings saved.'}) async {
    final list = modes ?? _current;
    setState(() => _busy = true);
    try {
      final res = await widget.rest.post('/restaurant/settings', {
        'currency': _currency,
        'payment_methods': [for (final m in list) m.toJson()],
      });
      if (!mounted) return true;
      setState(() => _adopt(res is Map && res['payment_methods'] is List ? PaymentModes.parse(res['payment_methods']) : list));
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
      widget.reload();
      return true;
    } catch (e) {
      // A refused save names every problem (a reserved name, a clash…) — as-is.
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
      return false;
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _addMode() async {
    // The dialog OWNS its text controller (see _AddPaymentModeDialog): disposing
    // one here, the moment showDialog returns, pulls it out from under the
    // TextField while the dialog is still animating closed.
    final draft = await showDialog<({String name, bool requiresScreenshot, bool showToGuests})>(
      context: context,
      builder: (_) => _AddPaymentModeDialog(existing: _current),
    );
    if (draft == null || !mounted) return;
    final next = PaymentModes.withCustom(_current,
        name: draft.name, requiresScreenshot: draft.requiresScreenshot, showToGuests: draft.showToGuests);
    await _save(modes: next, message: '${PaymentModes.tidy(draft.name)} can now be chosen when settling a bill.');
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final refusals = [for (final m in _methods) ?_labelRefusal(m)];
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Text('Payments & currency', style: text.titleMedium),
        const SizedBox(height: 4),
        Text(
            'Payment modes offered at the till and on the guest QR page. Add your own, rename any, '
            'or switch one off — a switched-off mode can’t be used for new payments, and past bills keep their mode.',
            style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Row(children: [
          Expanded(child: Text('CURRENCY', style: text.labelSmall)),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12),
            decoration: BoxDecoration(
              color: AppColors.inset,
              borderRadius: AppRadius.inputAll,
              border: Border.all(color: AppColors.border),
            ),
            child: DropdownButton<String>(
              value: _currency,
              underline: const SizedBox.shrink(),
              dropdownColor: AppColors.cardRaised,
              borderRadius: AppRadius.controlAll,
              items: _currencies.map((c) => DropdownMenuItem(value: c, child: Text(c, style: text.bodyLarge))).toList(),
              onChanged: (v) => setState(() => _currency = v ?? _currency),
            ),
          ),
        ]),
        const Divider(height: 24),
        Text('PAYMENT MODES', style: text.labelSmall),
        const SizedBox(height: 6),
        for (final m in _methods)
          Column(key: ValueKey('payment-mode-row-${m.id}'), crossAxisAlignment: CrossAxisAlignment.start, children: [
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Row(children: [
                Expanded(
                  child: TextField(
                    key: ValueKey('payment-mode-label-${m.id}'),
                    controller: _labels[m.id],
                    maxLength: PaymentModes.labelMax,
                    enabled: !_busy,
                    onChanged: (_) => setState(() {}),
                    style: text.bodyMedium!.copyWith(
                        color: m.enabled ? AppColors.textPrimary : AppColors.textSecondary),
                    decoration: InputDecoration(
                      isDense: true,
                      counterText: '',
                      hintText: PaymentModes.fallback.where((d) => d.id == m.id).firstOrNull?.label ?? m.id,
                    ),
                  ),
                ),
                if (m.custom) ...[
                  const SizedBox(width: 8),
                  const InfoChip(icon: Icons.add_card_outlined, label: 'added'),
                ],
                if (m.online) ...[
                  const SizedBox(width: 8),
                  const InfoChip(icon: Icons.bolt, label: 'online'),
                ],
                const SizedBox(width: AppSpacing.md),
                SizedBox(
                  height: 24,
                  child: FittedBox(
                    fit: BoxFit.contain,
                    child: Switch(
                        key: ValueKey('payment-mode-enabled-${m.id}'),
                        value: m.enabled,
                        onChanged: _busy ? null : (v) => _patch(m.id, (x) => x.copyWith(enabled: v))),
                  ),
                ),
              ]),
            ),
            if (_labelRefusal(m) != null)
              Padding(
                padding: const EdgeInsets.only(left: 4, bottom: 4),
                child: Text(_labelRefusal(m)!, style: text.bodySmall!.copyWith(color: AppColors.danger)),
              ),
            if (m.custom || PaymentModes.tidy(_labels[m.id]?.text ?? '') != m.id)
              Padding(
                padding: const EdgeInsets.only(left: 4, bottom: 2),
                child: Text('Stored on bills as “${m.id}”${m.enabled ? '' : ' · switched off'}',
                    style: text.bodySmall!.copyWith(fontSize: 11, color: AppColors.textTertiary)),
              ),
            if (m.enabled && !m.online)
              Padding(
                padding: const EdgeInsets.only(left: 16, bottom: 4),
                child: Wrap(spacing: 12, children: [
                  Row(mainAxisSize: MainAxisSize.min, children: [
                    Checkbox(
                      value: m.requiresScreenshot,
                      visualDensity: VisualDensity.compact,
                      activeColor: AppColors.copper,
                      checkColor: AppColors.onCopper,
                      side: BorderSide(color: AppColors.borderStrong),
                      onChanged: _busy ? null : (v) => _patch(m.id, (x) => x.copyWith(requiresScreenshot: v ?? false)),
                    ),
                    Text('Require payment screenshot', style: text.bodySmall),
                  ]),
                  Row(mainAxisSize: MainAxisSize.min, children: [
                    Checkbox(
                      value: m.showToGuests,
                      visualDensity: VisualDensity.compact,
                      activeColor: AppColors.copper,
                      checkColor: AppColors.onCopper,
                      side: BorderSide(color: AppColors.borderStrong),
                      onChanged: _busy ? null : (v) => _patch(m.id, (x) => x.copyWith(showToGuests: v ?? false)),
                    ),
                    Text('Show on guest QR page', style: text.bodySmall),
                  ]),
                ]),
              ),
          ]),
        const SizedBox(height: AppSpacing.md),
        Wrap(alignment: WrapAlignment.spaceBetween, spacing: 8, runSpacing: 8, children: [
          ForkButton.ghost(
            key: const ValueKey('payment-mode-open-add'),
            label: 'Add payment mode',
            icon: Icons.add,
            dense: true,
            onPressed: _busy ? null : _addMode,
          ),
          ForkButton(
            label: _busy ? 'Saving…' : 'Save payments & currency',
            icon: Icons.save_outlined,
            dense: true,
            // A label the server would refuse is said beside its box, not after a round trip.
            onPressed: (_busy || refusals.isNotEmpty) ? null : _save,
          ),
        ]),
      ]),
    );
  }
}

/// "Add payment mode": a name, whether it needs a screenshot, whether guests see
