        Expanded(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
            Text('Show menu & pre-order in the queue', style: text.titleSmall),
            const SizedBox(height: 3),
            Text('When off, waiting guests on the public queue page only see their place in line (no menu, no pre-order).',
                style: text.bodySmall),
          ]),
        ),
        const SizedBox(width: AppSpacing.md),
        SizedBox(
          height: 24,
          child: FittedBox(fit: BoxFit.contain, child: Switch(value: _showMenu, onChanged: _busy ? null : _save)),
        ),
      ]),
    );
  }
}

// Logo upload + theme-colour picker for the customer-facing pages.
class _BrandingCard extends StatefulWidget {
  final RestClient rest;
  final String initialLogo;
  final String initialColor;
  final VoidCallback reload;
  const _BrandingCard({required this.rest, required this.initialLogo, required this.initialColor, required this.reload});

  @override
  State<_BrandingCard> createState() => _BrandingCardState();
}

class _BrandingCardState extends State<_BrandingCard> {
  static const _swatches = [
    0xFFEA580C, 0xFFDC2626, 0xFFD97706, 0xFF16A34A,
    0xFF0D9488, 0xFF2563EB, 0xFF7C3AED, 0xFFDB2777, 0xFF111827,
  ];
  late String _logo;
  late int _color;
  bool _busy = false;

  @override
  void initState() {
    super.initState();
    _logo = widget.initialLogo;
    final hex = widget.initialColor.replaceAll('#', '');
    _color = hex.length == 6 ? (0xFF000000 | int.parse(hex, radix: 16)) : _swatches.first;
  }

  String get _hex => '#${(_color & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';

  Future<void> _post(Map<String, dynamic> body) async {
    setState(() => _busy = true);
    try {
      final res = await widget.rest.post('/restaurant/branding', body);
      if (res is Map && res['logo_url'] is String) _logo = res['logo_url'] as String;
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Branding saved.')));
        widget.reload();
      }
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _uploadLogo() async {
    final picked = await FilePicker.pickFiles(type: FileType.image, withData: true);
    final bytes = picked?.files.single.bytes;
    if (bytes == null) return;
    final ext = (picked!.files.single.extension ?? 'png').toLowerCase();
    await _post({'logo_base64': base64Encode(bytes), 'content_type': ext == 'png' ? 'image/png' : 'image/jpeg'});
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('Customer ordering page branding', style: text.titleMedium),
        const SizedBox(height: 4),
        Text('Logo + colour shown to guests on the QR ordering & reservation pages.', style: text.bodySmall),
        const SizedBox(height: AppSpacing.lg),
        Row(children: [
          Container(
            width: 64, height: 64,
            decoration: BoxDecoration(
              color: AppColors.inset,
              borderRadius: AppRadius.tileAll,
              border: Border.all(color: AppColors.border),
              image: _logo.isNotEmpty ? DecorationImage(image: NetworkImage(_logo), fit: BoxFit.contain) : null,
            ),
            child: _logo.isEmpty ? Icon(Icons.storefront, color: AppColors.textSecondary) : null,
          ),
          const SizedBox(width: AppSpacing.md),
          ForkButton.ghost(
            label: _logo.isEmpty ? 'Upload logo' : 'Change logo',
            icon: Icons.upload,
            dense: true,
            onPressed: _busy ? null : _uploadLogo,
          ),
        ]),
        const SizedBox(height: AppSpacing.lg),
        Text('THEME COLOUR', style: text.labelSmall),
        const SizedBox(height: AppSpacing.sm),
        // Guest-page palette by design: these swatches ARE the owner's choices
        // for the customer page, so they keep their real colours here.
        Wrap(spacing: 10, runSpacing: 10, children: [
          for (final c in _swatches)
            MouseRegion(
              cursor: SystemMouseCursors.click,
              child: GestureDetector(
                onTap: _busy ? null : () => setState(() => _color = c),
                child: AnimatedContainer(
                  duration: AppDurations.fast,
                  curve: Curves.easeOut,
                  width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: Color(c),
                    shape: BoxShape.circle,
                    border: Border.all(color: _color == c ? AppColors.textPrimary : Colors.transparent, width: 3),
                  ),
                  child: _color == c ? const Icon(Icons.check, color: Colors.white, size: 18) : null,
                ),
              ),
            ),
        ]),
        const SizedBox(height: AppSpacing.lg),
        Align(
          alignment: Alignment.centerRight,
          child: ForkButton(
            label: _busy ? 'Saving…' : 'Save theme colour',
            icon: Icons.palette_outlined,
            dense: true,
            onPressed: _busy ? null : () => _post({'theme_color': _hex}),
          ),
        ),
      ]),
    );
  }
}

// --- guest accent ramp (mirrors the guest pages) ------------------------------
// The dark guest design (ordering / feedback / valet) derives its whole palette
// from ONE accent hex: six lightness stops off the same hue —
// hi .75 · accent .63 · mid .51 · deep .39 · shadow .27 · ink .09 — each with a
// small saturation taper. Ported 1:1 from rampHS()/hexToHS() in
// Restaurant_Dashboard_UI/src/app/order/[restaurant]/page.tsx so this editor's
// preview and the real page cannot drift apart.
typedef _BrandRamp = ({Color hi, Color acc, Color mid, Color deep, Color shadow, Color ink});

double _c01(double x) => x < 0 ? 0 : (x > 1 ? 1 : x);

// hsl → Color, the same integer-rounded conversion the guest page uses.
Color _hslColor(double h, double s, double l) {
  final a = s * (l < 1 - l ? l : 1 - l);
  double f(double n) {
    final k = (n + h / 30) % 12;
    var m = k - 3;
    if (9 - k < m) m = 9 - k;
    if (m > 1) m = 1;
    if (m < -1) m = -1;
    return l - a * m;
  }

  int ch(double v) => (v * 255).round().clamp(0, 255);
  return Color.fromARGB(255, ch(f(0)), ch(f(8)), ch(f(4)));
}

// Resolve a brand accent hex into the six-stop ramp. An unparseable hex falls
// back to the guest page's own default copper (h 24 / s 38).
_BrandRamp _brandRamp(String hex) {
  var h = 24.0, s = 38.0;
  final m = RegExp(r'^#?([0-9a-fA-F]{6})$').firstMatch(hex.trim());
  if (m != null) {
    final n = int.parse(m.group(1)!, radix: 16);
    final r = ((n >> 16) & 0xff) / 255, g = ((n >> 8) & 0xff) / 255, b = (n & 0xff) / 255;
    final mx = r > g ? (r > b ? r : b) : (g > b ? g : b);
    final mn = r < g ? (r < b ? r : b) : (g < b ? g : b);
    final l = (mx + mn) / 2;
    h = 0;
    s = 0;
    if (mx != mn) {
      final d = mx - mn;
      s = (l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn)) * 100;
      if (mx == r) {
        h = (g - b) / d + (g < b ? 6 : 0);
      } else if (mx == g) {
        h = (b - r) / d + 2;
      } else {
        h = (r - g) / d + 4;
      }
      h *= 60;
    }
  }
  return (
    hi: _hslColor(h, _c01((s + 7) / 100), 0.75),
    acc: _hslColor(h, _c01(s / 100), 0.63),
    mid: _hslColor(h, _c01((s - 3) / 100), 0.51),
    deep: _hslColor(h, _c01((s - 6) / 100), 0.39),
    shadow: _hslColor(h, _c01((s - 8) / 100), 0.27),
    ink: _hslColor(h, _c01((s - 5) / 100), 0.09),
  );
}

String _hexOfColor(Color c) => '#${(c.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';

// A LinearGradient matching a CSS `linear-gradient(<deg>deg, …)`: 0° points up,
// 90° right, clockwise — so the Flutter preview's washes rotate exactly like the
// guest pages' CSS ones.
LinearGradient _brandAngleGradient(double deg, List<Color> colors) {
  final rad = deg * math.pi / 180;
  final dx = math.sin(rad), dy = -math.cos(rad);
  return LinearGradient(begin: Alignment(-dx, -dy), end: Alignment(dx, dy), colors: colors);
}

// The panel material behind `surface_style` — exactly the --panelBg/--blur/--pbA
// triples the guest pages use.
({Color bg, double blur, double edge}) _brandPanel(String style, _BrandRamp r) {
  switch (style) {
    case 'solid':
      return (bg: const Color(0xF0121215), blur: 0, edge: 0.10);
    case 'tinted':
      return (bg: r.shadow.withValues(alpha: 0.42), blur: 22, edge: 0.18);
    default:
      return (bg: const Color(0x8C1A1A1F), blur: 22, edge: 0.12);
  }
}

// Control radius behind `button_shape` — the guest pages' --rCtrl.
double _brandCtrlRadius(String shape) => switch (shape) {
      'pill' => 999,
      'square' => 4,
      _ => 13,
    };

// Guest-menu POSTERS: the owner's library of promotional images shown with the
// menu on the QR ordering page and the walk-in queue page.
//
// Fetches its own data (GET /posters) rather than reading the settings map,
// because posters are ROWS with their own lifecycle, not a settings key — the
// same reason the backend gave them a table instead of a brand_config blob.
//
// "SHOWING NOW" IS THE RESTAURANT'S DAY, NOT THIS LAPTOP'S. The server sends
// `today` as a YYYY-MM-DD key in the tenant's timezone and the badge is computed
// against that. An owner working from a different country — or simply a laptop
// whose clock has drifted — would otherwise be told a poster is live when their
// diners cannot see it, which is the one thing this badge exists to say.
//
// Gated on isAdmin to match the backend, which requires Manage Branding.
class _PostersCard extends StatefulWidget {
  final RestClient rest;
  final bool isAdmin;
  const _PostersCard({required this.rest, required this.isAdmin});

  @override
  State<_PostersCard> createState() => _PostersCardState();
}

class _PostersCardState extends State<_PostersCard> {
  static final RegExp _dateKey = RegExp(r'^\d{4}-\d{2}-\d{2}$');

  List<Map<String, dynamic>> _posters = const [];
  List<Map<String, dynamic>> _placements = const [];
  String _today = '';
  String _zone = '';
  int _maxPosters = 24;
  int _maxBytes = 3 * 1024 * 1024;
  bool _loading = true;
  bool _busy = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  Future<void> _load() async {
    try {
      final res = await widget.rest.get('/posters');
      if (!mounted) return;
      final m = (res is Map) ? res : const {};
      setState(() {
        _posters = [
          for (final p in (m['posters'] as List?) ?? const [])
            if (p is Map) Map<String, dynamic>.from(p),
        ];
        _placements = [
          for (final p in (m['placements'] as List?) ?? const [])
            if (p is Map) Map<String, dynamic>.from(p),
        ];
        _today = '${m['today'] ?? ''}';
        _zone = '${m['timezone'] ?? ''}';
        _maxPosters = (m['max_posters'] is num) ? (m['max_posters'] as num).toInt() : _maxPosters;
        _maxBytes = (m['max_upload_bytes'] is num) ? (m['max_upload_bytes'] as num).toInt() : _maxBytes;
        _loading = false;
        _error = null;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() { _loading = false; _error = '$e'; });
    }
  }

  /// The server's predicate, restated for the badge. Both bounds INCLUSIVE and a
  /// plain string compare — ISO day keys sort chronologically, so there is no
  /// date arithmetic here to get wrong.
  bool _isShowing(Map<String, dynamic> p) {
    if (p['active'] == false) return false;
    final start = p['start_on'] is String ? p['start_on'] as String : null;
    final end = p['end_on'] is String ? p['end_on'] as String : null;
    if (start == null && end == null) return true;
    if (!_dateKey.hasMatch(_today)) return false;
    if (start != null && start.compareTo(_today) > 0) return false;
    if (end != null && end.compareTo(_today) < 0) return false;
    return true;
  }

  String _scheduleLabel(Map<String, dynamic> p) {
    if (p['active'] == false) return 'Paused';
    final start = p['start_on'] is String ? p['start_on'] as String : null;
    final end = p['end_on'] is String ? p['end_on'] as String : null;
    if (start == null && end == null) return 'Always on';
    if (start != null && end != null) {
      return start == end ? 'On ${RestaurantTime.day(start)}' : '${RestaurantTime.day(start)} → ${RestaurantTime.day(end)}';
    }
    if (start != null) return 'From ${RestaurantTime.day(start)}';
    return 'Until ${RestaurantTime.day(end!)}';
  }

  void _say(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(msg)));
  }

  Future<void> _add() async {
    final picked = await FilePicker.pickFiles(type: FileType.image, withData: true);
    final file = picked?.files.single;
    final bytes = file?.bytes;
    if (bytes == null) return;
    // The SIZE pre-check runs on this machine so a 12 MB camera export never
    // leaves it. The TYPE is left to the server, which validates the BYTES and
    // not the file name — a .png that is really a zip is caught there.
    if (bytes.length > _maxBytes) {
      final mb = (bytes.length / (1024 * 1024)).toStringAsFixed(1);
      final cap = (_maxBytes / (1024 * 1024)).toStringAsFixed(0);
      _say('That image is $mb MB. Posters must be under $cap MB — try exporting it smaller.');
      return;
    }
    final ext = (file!.extension ?? 'png').toLowerCase();
    final contentType = switch (ext) {
      'png' => 'image/png',
      'webp' => 'image/webp',
      _ => 'image/jpeg',
    };
    setState(() => _busy = true);
    try {
      await widget.rest.post('/posters', {
        'image_base64': base64Encode(bytes),
        'content_type': contentType,
        // A new poster starts LIVE, unscheduled, in the menu slot: the owner just
        // picked a promo they want up, so the zero-click outcome is the one they
        // meant. Everything below is editable on the tile.
        'placement': 'menu',
        'sort_order': _posters.length,
        'active': true,
      });
      await _load();
      _say('Poster added — it is live on your guest menu now.');
    } catch (e) {
      _say('$e');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _patch(String id, Map<String, dynamic> body) async {
    setState(() => _busy = true);
    try {
      await widget.rest.patch('/posters/$id', body);
      await _load();
    } catch (e) {
      // Reload on failure too: the tile is showing a control the owner just
      // moved, and leaving it there would tell them a lie about what their
      // guests see.
      await _load();
      _say('$e');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _delete(Map<String, dynamic> p) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete poster?'),
        content: const Text('It will stop showing on your guest menu immediately.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          TextButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true) return;
    setState(() => _busy = true);
    try {
      await widget.rest.delete('/posters/${p['id']}');
      await _load();
      _say('Poster deleted.');
    } catch (e) {
      _say('$e');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  /// Pick a bound, or clear it. The picker opens on the RESTAURANT's today (not
  /// this device's) so the default landing month is the one the owner's diners
  /// are living in.
  Future<void> _pickDate(Map<String, dynamic> p, String key) async {
    final current = p[key] is String ? DateTime.tryParse(p[key] as String) : null;
    final anchor = RestaurantTime.nowIn(_zone.isEmpty ? RestaurantTime.zone : _zone) ?? DateTime.now();
    final picked = await showDatePicker(
      context: context,
      initialDate: current ?? anchor,
      firstDate: DateTime(anchor.year - 1),
      lastDate: DateTime(anchor.year + 3),
    );
    if (picked == null) return;
    final key0 = '${picked.year.toString().padLeft(4, '0')}-'
        '${picked.month.toString().padLeft(2, '0')}-'
        '${picked.day.toString().padLeft(2, '0')}';
    await _patch('${p['id']}', {key: key0});
  }

  Widget _dateField(Map<String, dynamic> p, String key, String label) {
    final value = p[key] is String ? p[key] as String : null;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      ForkButton.ghost(
        label: value == null ? label : RestaurantTime.day(value),
        icon: Icons.event_outlined,
        dense: true,
        onPressed: _busy ? null : () => unawaited(_pickDate(p, key)),
      ),
      if (value != null)
        ForkIconButton(
          icon: Icons.backspace_outlined,
          tooltip: 'Clear $label',
          // null CLEARS the bound server-side. Without this an owner could set a
          // date and never take it off again.
          onPressed: _busy ? null : () => unawaited(_patch('${p['id']}', {key: null})),
        ),
    ]);
  }

  Widget _tile(Map<String, dynamic> p) {
    final text = Theme.of(context).textTheme;
    final showing = _isShowing(p);
    final w = (p['width'] is num) ? (p['width'] as num).toDouble() : 0.0;
    final h = (p['height'] is num) ? (p['height'] as num).toDouble() : 0.0;
    // The poster's own ratio when the encoder reported one, so the list does not
    // reflow as thumbnails load. 16:9 is the fallback, not a crop.
    final ratio = (w > 0 && h > 0) ? w / h : 16 / 9;

    return Padding(
      // Keyed on the poster (found by the item 3 (2.0.1) sweep): the caption is an
      // initialValue field, so after a delete an unkeyed tile kept the deleted
      // poster's caption, and Enter saved that text onto the poster now beside it.
      key: ValueKey('poster-${p['id']}'),
      padding: const EdgeInsets.only(bottom: 12),
      child: Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: AppColors.inset,
          borderRadius: AppRadius.tileAll,
          border: Border.all(color: AppColors.border),
        ),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          SizedBox(
            width: 160,
            child: AspectRatio(
              aspectRatio: ratio,
              child: ClipRRect(
                borderRadius: AppRadius.tileAll,
                child: Opacity(
                  opacity: showing ? 1 : 0.45,
                  child: Image.network(
                    '${p['image_url']}',
                    fit: BoxFit.cover,
                    errorBuilder: (_, _, _) => Container(
                      color: AppColors.surface,
                      child: Icon(Icons.broken_image_outlined, color: AppColors.textSecondary),
                    ),
                  ),
                ),
              ),
            ),
          ),
          const SizedBox(width: AppSpacing.md),
          Expanded(
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                StatusChip(
                  label: showing ? 'Showing now' : 'Not showing',
                  color: showing ? AppColors.success : AppColors.neutral,
                  dense: true,
                ),
                const SizedBox(width: AppSpacing.sm),
                Flexible(child: Text(_scheduleLabel(p), style: text.bodySmall, overflow: TextOverflow.ellipsis)),
              ]),
              const SizedBox(height: AppSpacing.sm),
              TextFormField(
                initialValue: '${p['title'] ?? ''}',
                maxLength: 80,
                enabled: !_busy,
                decoration: const InputDecoration(
                  labelText: 'Caption (also the image description for screen readers)',
                  hintText: 'Sunday brunch, 11–3',
                  isDense: true,
                  counterText: '',
                ),
                // Saved when the field loses focus, not per keystroke: one PATCH
                // per edit rather than one per character.
                onFieldSubmitted: (v) => unawaited(_patch('${p['id']}', {'title': v.trim()})),
                onTapOutside: (_) => FocusManager.instance.primaryFocus?.unfocus(),
              ),
              const SizedBox(height: AppSpacing.sm),
              Wrap(spacing: 12, runSpacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
                DropdownButton<String>(
                  value: '${p['placement'] ?? 'menu'}',
                  underline: const SizedBox.shrink(),
                  items: [
                    for (final pl in _placements)
                      DropdownMenuItem(value: '${pl['value']}', child: Text('${pl['label']}')),
                  ],
                  onChanged: _busy ? null : (v) { if (v != null) unawaited(_patch('${p['id']}', {'placement': v})); },
                ),
                _dateField(p, 'start_on', 'Starts'),
                _dateField(p, 'end_on', 'Ends'),
                Row(mainAxisSize: MainAxisSize.min, children: [
                  Text('Live', style: text.bodySmall),
                  const SizedBox(width: 6),
                  SizedBox(
                    height: 24,
                    child: FittedBox(
                      fit: BoxFit.contain,
                      child: Switch(
                        value: p['active'] != false,
                        onChanged: _busy ? null : (v) => unawaited(_patch('${p['id']}', {'active': v})),
                      ),
                    ),
                  ),
                ]),
                ForkIconButton(
                  icon: Icons.delete_outline,
                  tooltip: 'Delete poster',
                  onPressed: _busy ? null : () => unawaited(_delete(p)),
                ),
              ]),
            ]),
          ),
        ]),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.isAdmin) return const SizedBox.shrink();
    final text = Theme.of(context).textTheme;
    final showingCount = _posters.where(_isShowing).length;
    final full = _posters.length >= _maxPosters;

    return ForkCard(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('Guest menu posters', style: text.titleMedium),
        const SizedBox(height: 4),
        Text(
          'Promotional images shown with your menu on the QR ordering page and the walk-in queue page.'
          '${_zone.isEmpty ? '' : " Dates follow your restaurant's clock ($_zone)."}',
          style: text.bodySmall,
        ),
        const SizedBox(height: AppSpacing.lg),
        if (_error != null)
          Padding(
            padding: const EdgeInsets.only(bottom: AppSpacing.md),
            child: Text(_error!, style: text.bodySmall?.copyWith(color: AppColors.danger)),
          ),
        Row(children: [
          ForkButton(
            label: _busy ? 'Working…' : 'Add poster',
            icon: Icons.add_photo_alternate_outlined,
            dense: true,
            onPressed: (_busy || _loading || full) ? null : () => unawaited(_add()),
          ),
          const SizedBox(width: AppSpacing.md),
          Expanded(
            child: Text(
              _loading
                  ? 'Loading…'
                  : full
                      ? 'You have reached the limit of $_maxPosters posters. Delete one to add another.'
                      : _posters.isEmpty
                          ? 'No posters yet — your guest menu looks exactly as it does today.'
                          : '$showingCount of ${_posters.length} showing right now.',
              style: text.bodySmall,
            ),
          ),
        ]),
        if (_posters.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.lg),
          for (final p in _posters) _tile(p),
          for (final pl in _placements)
            Padding(
              padding: const EdgeInsets.only(top: 2),
              child: Text('${pl['label']}: ${pl['hint']}', style: text.bodySmall),
            ),
        ],
      ]),
    );
  }
}

// Guest page theme editor. The guest surfaces (ordering, feedback, valet) are one
// committed dark design that themes itself from a single accent ramp, so this card
// only exposes the keys that genuinely re-render them — the backend's
// brand_fields.live list — and shows the retired colour keys as read-only history
// instead of pretending they still work. Preview mirrors the real page: near-black
// shell, accent orb, hero wash, frosted panel, accent CTA.
// Persists via POST /restaurant/branding {brand_config:{…}} (merge-on-omit; only
// provided, valid keys overwrite). Admin-only, matching the backend gate.
class _CustomerBrandingCard extends StatefulWidget {
  final RestClient rest;
  final bool isAdmin;
  final Map initialConfig;
  final List<String> fonts;
  // brand_fields.live / .legacy and brand_field_options from GET
  // /restaurant/settings. Empty lists fall back to the shipped contract, so an
  // older backend still renders a working editor.
  final List<String> liveFields;
  final List<String> legacyFields;
  final Map fieldOptions;
  // brand_schemes from GET /restaurant/settings: [{id,label,hint,preview:{...}}].
  // Empty falls back to the shipped catalogue so an older backend still works.
  final List schemes;
  final VoidCallback reload;
  const _CustomerBrandingCard({
    required this.rest,
    required this.isAdmin,
    required this.initialConfig,
    required this.fonts,
    required this.liveFields,
    required this.legacyFields,
    required this.fieldOptions,
    required this.schemes,
    required this.reload,
  });

  @override
  State<_CustomerBrandingCard> createState() => _CustomerBrandingCardState();
}

class _CustomerBrandingCardState extends State<_CustomerBrandingCard> {
  // Accent presets. Only real hues here: the accent seeds a six-stop ramp, so a
  // white/black/grey "accent" would flatten the whole guest palette.
  static const _presets = <int>[
    0xFFEA580C, 0xFFF97316, 0xFFDC2626, 0xFFD97706, 0xFFCA8A04,
    0xFF16A34A, 0xFF0D9488, 0xFF0EA5E9, 0xFF2563EB, 0xFF6366F1,
    0xFF7C3AED, 0xFFDB2777,
  ];
  // Fallback allowlists mirroring the backend, used only when the settings fetch
  // didn't return brand_fonts / brand_field_options (e.g. a transient error).
  static const _fallbackFonts = <String>[
    'Inter', 'Poppins', 'Playfair Display', 'Montserrat', 'Lato',
    'Nunito', 'Oswald', 'Roboto Slab', 'DM Sans', 'Merriweather',
  ];
  // THE editable-contract tables. Every control the card renders is BUILT from
  // these (the colour-role groups, the gradient groups and the base knobs), and
  // _unsupported = the server's live list minus exactly these keys — so adding a
  // key here grows its editor and empties the "server also offers" banner in the
  // same commit, by construction. The banner only returns for a genuinely
  // unknown future key the server starts advertising.
  static const _knobKeys = <String>[
    'scheme', 'color_primary', 'font', 'font_scale', 'header_style', 'button_shape', 'surface_style', 'card_shape',
  ];
  // Colour ROLES, grouped the way the web editor groups them (brand / shell /
  // status). Each entry: key, label, one-line hint.
  static const _colorRoleGroups = <(String, List<(String, String, String)>)>[
    ('Brand colours', [
      ('color_secondary', 'Secondary', 'Chips and secondary buttons.'),
      ('color_accent', 'Highlight', 'Badges and price emphasis.'),
    ]),
    ('Shell', [
      ('color_bg', 'Page background', 'The shell behind everything.'),
      ('color_card', 'Card surface', 'Panel base colour.'),
      ('color_text', 'Body text', 'Main ink colour — the server keeps it readable.'),
    ]),
    ('Status colours', [
      ('color_success', 'Success', 'Confirmations, ready / seated states.'),
      ('color_warning', 'Warning', 'Waiting and caution states.'),
      ('color_error', 'Error', 'Failures and destructive actions.'),
    ]),
  ];
  // Gradient surfaces: id (the `<id>_grad_from/_to/_angle` key prefix), label,
  // hint, and the angle the shipped derived wash uses (mirrors the backend's
  // BRAND_GRADIENT_ANGLE_DEFAULTS).
  static const _gradientGroups = <(String, String, String, double)>[
    ('header', 'Header wash gradient', 'Your own two-stop wash behind the restaurant name.', 150),
    ('button', 'Button gradient', 'The fill of accent buttons — same colour twice = solid.', 180),
    ('bg', 'Page background gradient', 'A wash painted over the page shell.', 180),
  ];
  static final List<String> _editableKeys = [
    ..._knobKeys,
    for (final (_, roles) in _colorRoleGroups)
      for (final (key, _, _) in roles) key,
    for (final (id, _, _, _) in _gradientGroups) ...['${id}_grad_from', '${id}_grad_to', '${id}_grad_angle'],
  ];
  // The shipped backend advertises every colour role + gradient key as live and
  // retires nothing; these fallbacks (used only when /settings didn't answer)
  // mirror that so a transient error doesn't hide working controls.
  static List<String> get _fallbackLive => _editableKeys;
  static const _fallbackLegacy = <String>[];
  static const _fallbackOptions = <String, List<String>>{
    'header_style': ['gradient', 'solid'],
    'button_shape': ['rounded', 'pill', 'square'],
    'surface_style': ['frosted', 'solid', 'tinted'],
    'scheme': ['classic', 'copper', 'airy', 'contrast', 'custom'],
    'font_scale': ['small', 'medium', 'large'],
    'card_shape': ['rounded', 'sharp'],
  };
  // Mirrors the server's BRAND_SCHEMES previews; the server list wins when sent.
  static const _fallbackSchemes = <Map<String, dynamic>>[
    {'id': 'classic', 'label': 'Classic dark', 'preview': {'background': '#08080A', 'surface': '#1A1A1F', 'text': '#ECEAE6'}},
    {'id': 'copper', 'label': 'Warm copper', 'preview': {'background': '#0E0A08', 'surface': '#201812', 'text': '#F1E9DF'}},
    {'id': 'airy', 'label': 'Light & airy', 'preview': {'background': '#F6F4EF', 'surface': '#FFFFFF', 'text': '#2B2723'}},
    {'id': 'contrast', 'label': 'High contrast', 'preview': {'background': '#000000', 'surface': '#101010', 'text': '#FFFFFF'}},
    {'id': 'custom', 'label': 'Custom', 'preview': {'background': '#08080A', 'surface': '#1A1A1F', 'text': '#ECEAE6'}},
  ];
  // Human labels for the enum values + the retired keys.
  static const _optionLabels = <String, String>{
    'gradient': 'Gradient',
    'solid': 'Solid',
    'rounded': 'Rounded',
    'pill': 'Pill',
    'square': 'Square',
    'frosted': 'Frosted',
    'tinted': 'Accent glass',
    'small': 'S',
    'medium': 'M',
    'large': 'L',
    'sharp': 'Sharp',
  };
  static const _legacyLabels = <String, String>{
    'color_secondary': 'Secondary colour',
    'color_bg': 'Page background',
    'color_text': 'Body text',
    'color_card': 'Card surface',
  };
  static final _hexRe = RegExp(r'^#[0-9a-fA-F]{6}$');

  late final List<String> _fonts;
  late final List<String> _live;
  late final List<String> _legacyStored; // retired keys this tenant actually has
  late final List<String> _unsupported; // live keys this app build can't edit yet
  late String _font;
  late String _headerStyle;
  late String _buttonShape;
  late String _surfaceStyle;
  late String _scheme;
  late String _fontScale;
  late String _cardShape;
  final TextEditingController _accent = TextEditingController();
  // One controller per colour ROLE (the 8 non-primary keys). Empty text = "auto":
  // the save sends null, which DELETES the stored override server-side.
  final Map<String, TextEditingController> _roles = {};
  // Gradient state per surface id (header/button/bg): two stop controllers +
  // the angle. A gradient is ON only while BOTH stops parse — mirroring the
  // server's activation rule, so the preview can never show a wash a guest
  // wouldn't get.
  final Map<String, TextEditingController> _gradFrom = {};
  final Map<String, TextEditingController> _gradTo = {};
  final Map<String, double> _gradAngle = {};
  bool _busy = false;
  bool _showRetired = false;

  @override
  void initState() {
    super.initState();
    final c = widget.initialConfig;
    _fonts = widget.fonts.isNotEmpty ? List<String>.from(widget.fonts) : List<String>.from(_fallbackFonts);
    _live = widget.liveFields.isNotEmpty ? List<String>.from(widget.liveFields) : List<String>.from(_fallbackLive);
    final legacy = widget.legacyFields.isNotEmpty ? widget.legacyFields : _fallbackLegacy;
    // Only surface retired keys the tenant really stored — a clean tenant sees none.
    _legacyStored = legacy.where((k) => '${c[k] ?? ''}'.trim().isNotEmpty).toList();
    // Derived from the SAME table the editors are built from (_editableKeys), so
    // this list — and the banner it feeds — empties by construction.
    _unsupported = _live.where((k) => !_editableKeys.contains(k)).toList();
    final f = _s(c, 'font', 'Inter');
    _font = _fonts.contains(f) ? f : _fonts.first;
    _headerStyle = _pick('header_style', '${c['header_style'] ?? ''}', 'gradient');
    _buttonShape = _pick('button_shape', '${c['button_shape'] ?? ''}', 'rounded');
    _surfaceStyle = _pick('surface_style', '${c['surface_style'] ?? ''}', 'frosted');
    _scheme = _pick('scheme', '${c['scheme'] ?? ''}', 'classic');
    _fontScale = _pick('font_scale', '${c['font_scale'] ?? ''}', 'medium');
    _cardShape = _pick('card_shape', '${c['card_shape'] ?? ''}', 'rounded');
    final accent = '${c['color_primary'] ?? ''}'.trim();
    if (_hexRe.hasMatch(accent)) _accent.text = accent;
    // Roles prefill with the RESOLVED value the server returned (never blank for
    // an existing tenant) — same as the web editor, so saving what you loaded
    // pins exactly what guests already see.
    for (final (_, roles) in _colorRoleGroups) {
      for (final (key, _, _) in roles) {
        final v = '${c[key] ?? ''}'.trim();
        _roles[key] = TextEditingController(text: _hexRe.hasMatch(v) ? v : '');
      }
    }
    // Gradients prefill only from EXPLICIT stored keys (the server passes them
    // through rather than resolving defaults in), so blank = off = derived wash.
    for (final (id, _, _, angleDefault) in _gradientGroups) {
      final from = '${c['${id}_grad_from'] ?? ''}'.trim();
      final to = '${c['${id}_grad_to'] ?? ''}'.trim();
      _gradFrom[id] = TextEditingController(text: _hexRe.hasMatch(from) ? from : '');
      _gradTo[id] = TextEditingController(text: _hexRe.hasMatch(to) ? to : '');
      final rawAngle = c['${id}_grad_angle'];
      _gradAngle[id] = (rawAngle is num) ? (rawAngle.toDouble() % 360 + 360) % 360 : angleDefault;
    }
  }

  @override
  void dispose() {
    _accent.dispose();
    for (final c in _roles.values) {
      c.dispose();
    }
    for (final c in _gradFrom.values) {
      c.dispose();
    }
    for (final c in _gradTo.values) {
      c.dispose();
    }
    super.dispose();
  }

  // Allowed values for an enum key, backend-first so a newer option shows up
  // without an app release.
  List<String> _options(String key) {
    final v = widget.fieldOptions[key];
    final list = (v is List) ? v.map((e) => '$e'.trim()).where((e) => e.isNotEmpty).toList() : const <String>[];
    return list.isNotEmpty ? list : (_fallbackOptions[key] ?? const <String>[]);
  }

  String _pick(String key, String stored, String fallback) {
    final opts = _options(key);
    return opts.contains(stored) ? stored : fallback;
  }

  String _label(String v) => _optionLabels[v] ?? (v.isEmpty ? v : '${v[0].toUpperCase()}${v.substring(1)}');

  Color? _parse(String s) {
    final t = s.trim();
    if (!_hexRe.hasMatch(t)) return null;
    return Color(0xFF000000 | int.parse(t.substring(1), radix: 16));
  }

  String _fmt(int argb) => '#${(argb & 0xFFFFFF).toRadixString(16).padLeft(6, '0')}';

  // The ramp the guest pages will actually derive — unset accent shows their own
  // copper default rather than a lie.
  _BrandRamp get _ramp => _brandRamp(_accent.text);

  List<Map> get _schemeList {
    final fromServer = [for (final e in widget.schemes) if (e is Map) e];
    return fromServer.isNotEmpty ? fromServer : _fallbackSchemes;
  }

  Map? _schemeMeta(String id) {
    for (final m in _schemeList) {
      if ('${m['id']}' == id) return m;
    }
    return null;
  }

  // A preview colour for the ACTIVE scheme's shell role, or null for
  // classic/custom (whose shell is the shipped dark design).
  Color? _schemeShell(String role) {
    if (_scheme == 'classic' || _scheme == 'custom') return null;
    final prev = _schemeMeta(_scheme)?['preview'];
    return prev is Map ? _parse('${prev[role] ?? ''}') : null;
  }

  // brand_config key → the scheme preview's role name for the six shell/status
  // colours a preset pins (the accent trio is brand identity and never touched).
  static const _schemeRoleOf = <String, String>{
    'color_bg': 'background',
    'color_card': 'surface',
    'color_text': 'text',
    'color_success': 'success',
    'color_warning': 'warning',
    'color_error': 'error',
  };

  // Picking a preset fills the shell/status role fields with the scheme's own
  // values (blank for "classic" = re-derive the shipped defaults), so what is
  // saved is exactly what the picker showed — the same rule as the web editor.
  // "custom" only flips the marker and leaves every field alone.
  void _applyScheme(String id) {
    setState(() {
      _scheme = id;
      if (id == 'custom') return;
      final prev = id == 'classic' ? null : _schemeMeta(id)?['preview'];
      _schemeRoleOf.forEach((key, role) {
        final ctrl = _roles[key];
        if (ctrl == null) return;
        final v = prev is Map ? '${prev[role] ?? ''}'.trim() : '';
        ctrl.text = _hexRe.hasMatch(v) ? v : '';
      });
    });
  }

  // A manual tweak of a shell/status role while a NAMED preset is active flips
  // the marker to "custom", so the picker never claims a look that's been edited.
  void _touchRole() {
    if (_scheme != 'classic' && _scheme != 'custom') _scheme = 'custom';
    setState(() {});
  }

  Future<void> _save() async {
    final messenger = ScaffoldMessenger.of(context);
    // Only the LIVE keys travel. Anything the server doesn't advertise is never
    // re-sent, so it stays exactly as stored server-side (merge-on-omit).
    final cfg = <String, dynamic>{};
    if (_live.contains('font')) cfg['font'] = _font;
    if (_live.contains('header_style')) cfg['header_style'] = _headerStyle;
    if (_live.contains('button_shape')) cfg['button_shape'] = _buttonShape;
    if (_live.contains('surface_style')) cfg['surface_style'] = _surfaceStyle;
    if (_live.contains('scheme')) cfg['scheme'] = _scheme;
    if (_live.contains('font_scale')) cfg['font_scale'] = _fontScale;
    if (_live.contains('card_shape')) cfg['card_shape'] = _cardShape;
    // Colour roles: what a field says is what the tenant gets — a valid hex pins
    // the role, a blank sends null, which DELETES the stored override so the
    // role re-derives (and follows any future evolution of the scheme/derived
    // defaults). Mirrors the web editor exactly.
    for (final (_, roles) in _colorRoleGroups) {
      for (final (key, _, _) in roles) {
        if (!_live.contains(key)) continue;
        final t = _roles[key]!.text.trim();
        cfg[key] = _hexRe.hasMatch(t) ? t : null;
      }
    }
    if (_live.contains('color_primary')) {
      final t = _accent.text.trim();
      // Blank accent = keep whatever the page resolves today (merge-on-omit).
      if (_hexRe.hasMatch(t)) cfg['color_primary'] = t;
    }
    // Gradients: both stops valid → the full triple; anything else → null for
    // ALL THREE keys, which deletes them (absent must stay absent, so a cleared
    // gradient renders the shipped derived wash again).
    for (final (id, _, _, _) in _gradientGroups) {
      if (!_live.contains('${id}_grad_from')) continue;
      final from = _gradFrom[id]!.text.trim(), to = _gradTo[id]!.text.trim();
      final on = _hexRe.hasMatch(from) && _hexRe.hasMatch(to);
      cfg['${id}_grad_from'] = on ? from : null;
      cfg['${id}_grad_to'] = on ? to : null;
      cfg['${id}_grad_angle'] = on ? _gradAngle[id]!.round() : null;
    }
    setState(() => _busy = true);
    try {
      final resp = await widget.rest.post('/restaurant/branding', {'brand_config': cfg});
      // The server may have adjusted a colour to keep guest text readable
      // (brand_contrast). Repeat that in plain words rather than leaving the
      // owner wondering why the live page differs from what they picked.
      final contrast = (resp is Map && resp['brand_contrast'] is List) ? (resp['brand_contrast'] as List) : const [];
      var msg = 'Guest page theme saved.';
      final note = contrast.isNotEmpty && contrast.first is Map ? contrast.first as Map : null;
      if (note != null) {
        msg = 'Saved — but your ${note['role']} colour ${note['requested']} is too close to the ${note['against']} '
            '(${note['ratio']}:1 contrast; ${note['minimum']}:1 needed), so guests see ${note['applied']} instead. '
            'Pick a stronger colour to clear the guard.';
      }
      messenger.showSnackBar(SnackBar(content: Text(msg), duration: Duration(seconds: note == null ? 4 : 9)));
      widget.reload();
    } on ApiException catch (e) {
      messenger.showSnackBar(SnackBar(content: Text(e.status == 403 ? 'Only an admin can change branding.' : '$e')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  // Segmented pill choice in the template voice — recessed track, active pill
  // lifted with a hairline border (selection also carries its text label).
  Widget _toggle(String label, String caption, List<(String, String)> options, String value, ValueChanged<String> onPick) {
    return Builder(
