// ----------------------------------------------------------- write dialogs ----

Future<void> _addInventory(
    BuildContext context, RestClient rest, List<String> categories, bool isAdmin, VoidCallback reload) async {
  final name = TextEditingController();
  final stock = TextEditingController();
  final unit = TextEditingController();
  final reorder = TextEditingController();
  final messenger = ScaffoldMessenger.of(context);
  // Local mutable copy of the managed list so the inline "Manage categories"
  // affordance can refresh the picker without closing this dialog.
  var cats = List<String>.from(categories);
  String? category = cats.isNotEmpty ? cats.first : null;
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setLocal) => Dialog(
        backgroundColor: Colors.transparent,
        child: Container(
          width: 400,
          padding: const EdgeInsets.all(22),
          decoration: BoxDecoration(
            gradient: AppColors.cardGradient,
            borderRadius: AppRadius.cardAll,
            border: Border.all(color: AppColors.borderStrong),
          ),
          child: SingleChildScrollView(
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('INVENTORY', style: Theme.of(ctx).textTheme.labelSmall),
              const SizedBox(height: 6),
              Text('Add inventory item', style: Theme.of(ctx).textTheme.titleMedium),
              const SizedBox(height: AppSpacing.lg),
              TextField(controller: name, decoration: const InputDecoration(labelText: 'Name', isDense: true)),
              const SizedBox(height: AppSpacing.sm),
              Row(children: [
                Expanded(
                  child: cats.isEmpty
                      ? Text('No categories yet — add one via the tune icon.',
                          style: Theme.of(ctx).textTheme.bodySmall)
                      : DropdownButtonFormField<String>(
                          initialValue: category,
                          isExpanded: true,
                          dropdownColor: AppColors.cardRaised,
                          decoration: const InputDecoration(labelText: 'Category', isDense: true),
                          items: [for (final c in cats) DropdownMenuItem(value: c, child: Text(c))],
                          onChanged: (v) => setLocal(() => category = v),
                        ),
                ),
                const SizedBox(width: AppSpacing.sm),
                ForkIconButton(
                  icon: Icons.tune,
                  tooltip: 'Manage categories',
                  onPressed: () async {
                    final changed = await showDialog<bool>(
                      context: ctx,
                      builder: (_) => _InventoryCategoriesDialog(rest: rest, isAdmin: isAdmin, initial: cats),
                    );
                    if (changed != true) return;
                    // Re-read the managed list so the picker reflects the edits,
                    // and refresh the underlying inventory list too.
                    try {
                      final s = await rest.getMap('/restaurant/settings');
                      final fresh = ((s['inventory_categories'] as List?) ?? const [])
                          .map((e) => '$e'.trim())
                          .where((e) => e.isNotEmpty)
                          .toList();
                      setLocal(() {
                        cats = fresh;
                        final cur = category;
                        if (cur == null || !cats.any((c) => c.toLowerCase() == cur.toLowerCase())) {
                          category = cats.isNotEmpty ? cats.first : null;
                        }
                      });
                    } catch (_) {/* keep the current picker on refresh failure */}
                    reload();
                  },
                ),
              ]),
              const SizedBox(height: AppSpacing.sm),
              TextField(
                  controller: stock,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(labelText: 'Stock', isDense: true)),
              const SizedBox(height: AppSpacing.sm),
              TextField(
                controller: unit,
                decoration: const InputDecoration(labelText: 'Unit (e.g. kg)', isDense: true),
                // The reorder field below is labelled in whatever unit is typed
                // here — a level means nothing without the unit it counts.
                onChanged: (_) => setLocal(() {}),
              ),
              const SizedBox(height: AppSpacing.sm),
              TextField(
                controller: reorder,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(
                  labelText: unit.text.trim().isEmpty
                      ? 'Reorder at (optional)'
                      : 'Reorder at (${unit.text.trim()})',
                  helperText: 'Blank = sensible default for this unit',
                  isDense: true,
                ),
              ),
              const SizedBox(height: AppSpacing.xl),
              Row(mainAxisAlignment: MainAxisAlignment.end, children: [
                ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
                const SizedBox(width: AppSpacing.sm),
                ForkButton(label: 'Add', icon: Icons.add, onPressed: () => Navigator.pop(ctx, true)),
              ]),
            ]),
          ),
        ),
      ),
    ),
  );
  if (ok == true) {
    try {
      final level = num.tryParse(reorder.text.trim());
      await rest.post('/inventory', {
        'name': name.text.trim(),
        'category': (category ?? '').trim(),
        'stock': num.tryParse(stock.text.trim()) ?? 0,
        'unit': unit.text.trim(),
        // Sent as an explicit null when blank so the server clears any stored
        // level rather than being left to guess what "absent" meant.
        'reorder_level': (level != null && level > 0) ? level : null,
      });
      reload();
      messenger.showSnackBar(const SnackBar(content: Text('Item added.')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }
  name.dispose();
  stock.dispose();
  unit.dispose();
  reorder.dispose();
}

/// Set (or clear) ONE item's reorder level, in that item's own unit.
///
/// POSTs /inventory/reorder-level, which touches only the threshold. The
/// add-item route would have written "Quantity" too — see the note on the sheet
/// button that opens this.
Future<void> _setReorderLevel(
    BuildContext context, RestClient rest, Map item, VoidCallback reload) async {
  final unit = _s(item, 'unit', '');
  final current = item['reorder_level'];
  final applied = double.tryParse('${item['reorder_applied'] ?? ''}');
  final field = TextEditingController(text: current == null ? '' : _stockNum(double.tryParse('$current')));
  final messenger = ScaffoldMessenger.of(context);

  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        width: 380,
        padding: const EdgeInsets.all(22),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.borderStrong),
        ),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('INVENTORY', style: Theme.of(ctx).textTheme.labelSmall),
          const SizedBox(height: 6),
          Text('Reorder level - ${_s(item, 'name')}', style: Theme.of(ctx).textTheme.titleMedium),
          const SizedBox(height: AppSpacing.sm),
          Text(
            'Flag this item Low Stock at or below this level. Entered in the '
            'item\'s own unit${unit.isEmpty ? '' : ' ($unit)'}.',
            style: Theme.of(ctx).textTheme.bodySmall,
          ),
          const SizedBox(height: AppSpacing.lg),
          TextField(
            controller: field,
            keyboardType: TextInputType.number,
            autofocus: true,
            decoration: InputDecoration(
              labelText: unit.isEmpty ? 'Reorder at' : 'Reorder at ($unit)',
              helperText: applied == null
                  ? 'Blank = sensible default for this unit'
                  : 'Blank = default (${_stockNum(applied)}${unit.isEmpty ? '' : ' $unit'})',
              isDense: true,
            ),
          ),
          const SizedBox(height: AppSpacing.xl),
          Row(mainAxisAlignment: MainAxisAlignment.end, children: [
            ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
            const SizedBox(width: AppSpacing.sm),
            ForkButton(label: 'Save', icon: Icons.check, onPressed: () => Navigator.pop(ctx, true)),
          ]),
        ]),
      ),
    ),
  );

  if (ok == true) {
    final raw = field.text.trim();
    final level = raw.isEmpty ? null : num.tryParse(raw);
    if (raw.isNotEmpty && (level == null || level <= 0)) {
      messenger.showSnackBar(const SnackBar(content: Text('Enter a number greater than 0, or leave it blank.')));
    } else {
      try {
        await rest.post('/inventory/reorder-level', {
          'inventory_id': '${item['id'] ?? ''}',
          'reorder_level': level,
        });
        reload();
        messenger.showSnackBar(SnackBar(content: Text(level == null ? 'Using the default level.' : 'Reorder level saved.')));
      } catch (e) {
        messenger.showSnackBar(SnackBar(content: Text('$e')));
      }
    }
  }
  field.dispose();
}

Future<void> _addEmployee(BuildContext context, RestClient rest, VoidCallback reload) async {
  final first = TextEditingController();
  final last = TextEditingController();
  final username = TextEditingController();
  final password = TextEditingController();
  final email = TextEditingController();
  String role = 'employee';
  final messenger = ScaffoldMessenger.of(context);
  // Custom roles were missing from this dialog entirely, so a role created in
  // Roles & Permissions could never be given to a NEW employee — only added
  // afterwards. Load them and offer them alongside the built-ins; the value is
  // the role's uuid, which the backend resolves against "Roles".
  List<Map<String, dynamic>> customRoles = const [];
  try {
    final raw = await rest.get('/roles');
    if (raw is List) {
      customRoles = raw
          .whereType<Map>()
          .map((e) => {'id': '${e['id'] ?? ''}', 'name': '${e['role_name'] ?? ''}'})
          .where((e) => (e['id'] as String).isNotEmpty && (e['name'] as String).isNotEmpty)
          .toList();
    }
  } catch (_) {
    // Roles are a nicety here — a failure must not block adding staff.
  }
  // The roles fetch above is an async gap — bail out if this screen is gone.
  if (!context.mounted) {return;}
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        width: 400,
        padding: const EdgeInsets.all(22),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.borderStrong),
        ),
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text('STAFF', style: Theme.of(ctx).textTheme.labelSmall),
            const SizedBox(height: 6),
            Text('Add employee', style: Theme.of(ctx).textTheme.titleMedium),
            const SizedBox(height: AppSpacing.lg),
            TextField(controller: first, decoration: const InputDecoration(labelText: 'First name', isDense: true)),
            const SizedBox(height: AppSpacing.sm),
            TextField(controller: last, decoration: const InputDecoration(labelText: 'Last name', isDense: true)),
            const SizedBox(height: AppSpacing.sm),
            TextField(controller: username, decoration: const InputDecoration(labelText: 'Username', isDense: true)),
            const SizedBox(height: AppSpacing.sm),
            TextField(
                controller: password,
                obscureText: true,
                decoration: const InputDecoration(labelText: 'Password', isDense: true)),
            const SizedBox(height: AppSpacing.sm),
            TextField(controller: email, decoration: const InputDecoration(labelText: 'Email (optional)', isDense: true)),
            const SizedBox(height: AppSpacing.md),
            DropdownButtonFormField<String>(
              initialValue: role,
              dropdownColor: AppColors.cardRaised,
              decoration: const InputDecoration(labelText: 'Role', isDense: true),
              items: [
                const DropdownMenuItem(value: 'employee', child: Text('Employee')),
                const DropdownMenuItem(value: 'manager', child: Text('Manager')),
                const DropdownMenuItem(value: 'cashier', child: Text('Cashier')),
                const DropdownMenuItem(value: 'waiter', child: Text('Waiter')),
                const DropdownMenuItem(value: 'captain', child: Text('Captain')),
                const DropdownMenuItem(value: 'valet', child: Text('Valet')),
                for (final r in customRoles)
                  DropdownMenuItem(value: r['id'] as String, child: Text('${r['name']} (custom)')),
              ],
              onChanged: (v) => role = v ?? 'employee',
            ),
            const SizedBox(height: AppSpacing.xl),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              ForkButton.ghost(label: 'Cancel', onPressed: () => Navigator.pop(ctx, false)),
              const SizedBox(width: AppSpacing.sm),
              ForkButton(label: 'Add', icon: Icons.person_add_alt, onPressed: () => Navigator.pop(ctx, true)),
            ]),
          ]),
        ),
      ),
    ),
  );
  if (ok == true) {
    try {
      await rest.post('/restaurant/users', {
        'emp_Fname': first.text.trim(),
        'emp_Lname': last.text.trim(),
        'username': username.text.trim(),
        'password': password.text,
        'email': email.text.trim(),
        'role': role,
      });
      reload();
      messenger.showSnackBar(const SnackBar(content: Text('Employee added.')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    }
  }
  first.dispose();
  last.dispose();
  username.dispose();
  password.dispose();
  email.dispose();
}

// ------------------------------------------------------------- roles (RBAC) ----

const _coreRoles = <String>['admin', 'manager', 'cashier', 'waiter', 'captain', 'valet', 'employee'];

// A stable colour per role so role chips/badges read at a glance (Discord-style).
Color _roleColor(String role) {
  switch (role.toLowerCase()) {
    case 'admin':
      return AppColors.danger; // red — highest authority
    case 'manager':
      return AppColors.copperHi; // purple
    case 'captain':
      return AppColors.info; // blue
    case 'cashier':
      return AppColors.success; // teal
    case 'waiter':
      return AppColors.warning; // orange
    case 'valet':
      return AppColors.copperDeep; // brown
    case 'employee':
      return AppColors.neutral; // slate
    default:
      return AppColors.copperMid; // indigo — custom roles
  }
}

// A coloured role pill in the shared status voice (tint + dot + label — the
// colour never travels alone). Optionally shows an "x" to remove it inline.
// Custom-role names, keyed by their "Roles" uuid. Employee/role screens fetch
// /roles anyway, so they warm this; anywhere that only has a bare role list can
// then print a NAME instead of a raw guid. Falls back to a plain label rather
// than leaking the id when the cache is cold.
final Map<String, String> _customRoleNames = <String, String>{};

void _cacheCustomRoleNames(List roles) {
  for (final r in roles) {
    if (r is! Map) continue;
    final id = '${r['id'] ?? ''}'.trim();
    final name = '${r['role_name'] ?? ''}'.trim();
    if (id.isNotEmpty && name.isNotEmpty) _customRoleNames[id] = name;
  }
}

final RegExp _uuidRe = RegExp(r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$');

/// A role as a person should read it: built-ins as-is, a custom role by name.
String _roleLabel(String role) {
  final r = role.trim();
  if (!_uuidRe.hasMatch(r)) return r;
  return _customRoleNames[r] ?? 'Custom role';
}

/// Comma-joined role labels for the account/profile rows.
String _roleLabels(Iterable<String> roles) =>
    roles.map(_roleLabel).where((s) => s.isNotEmpty).join(', ');

Widget _roleChip(String role, {VoidCallback? onRemove}) {
  final c = _roleColor(role);
  return Container(
    padding: EdgeInsets.fromLTRB(8, 3, onRemove == null ? 8 : 5, 3),
    decoration: BoxDecoration(
      color: AppColors.tint(c),
      borderRadius: BorderRadius.circular(AppRadius.chip),
      border: Border.all(color: AppColors.edge(c)),
    ),
    child: Row(mainAxisSize: MainAxisSize.min, children: [
      Container(width: 5, height: 5, decoration: BoxDecoration(color: c, shape: BoxShape.circle)),
      const SizedBox(width: 5),
      Text(role,
          style: TextStyle(
            fontSize: 10.5,
            fontWeight: FontWeight.w600,
            letterSpacing: 0.3,
            color: Color.lerp(c, Colors.white, 0.25),
          )),
      if (onRemove != null) ...[
        const SizedBox(width: 3),
        InkWell(
          onTap: onRemove,
          borderRadius: BorderRadius.circular(AppRadius.chip),
          child: Icon(Icons.close, size: 12, color: c.withValues(alpha: 0.8)),
        ),
      ],
    ]),
  );
}

/// THE ACTION IDS THE SERVER ACTUALLY VALIDATES ON THE RBAC ROUTES, copied from
/// routes/roles.ts. Requirement C5 is "permissions … distinct and customizable;
/// Super Admins and Managers can view and edit custom roles", and the only
/// honest way to say who that is, is to ask the SAME question the server asks.
///
/// NOT ONE OF THESE IS NEW. Migration 025's rule is that minting a fresh uuid
/// for a capability that already has one silently strips it from every role
/// holding the old id — so a tenant who granted their managers role editing
/// would wake up unable to edit roles. These are the existing ids, reused.
///
/// `Profile.actions` carries `*` for an admin, so a Super Admin passes all three
/// without any of them being listed against their role.
// (GET /roles and GET /core-roles are gated on 17ba6407-…, which every reader
// who can open this screen already holds — the module would not be in their nav
// otherwise — so there is nothing for this file to decide about reading.)
const String _permCreateRole = 'c0135d18-68b4-45e9-9b51-849158df6efd';
const String _permDeleteRole = '53d0927d-00f4-48cc-a40c-51edb09826d8';

Widget rolesModule(RestClient rest, Profile p) => AsyncView<Map<String, dynamic>>(
      load: () async {
        final r = await Future.wait([rest.getList('/roles'), rest.getList('/actions')]);
        // REQUIREMENT C6 — what a core role actually grants, from the ONE place
        // that knows: GET /core-roles serves the server's own CORE_ROLES table.
        //
        // Read here rather than hard-coded beside _coreRoles, and that is the
        // whole fix rather than a detail of it. The core sets change — the
        // manager role gained the three MIS-capture acts, the waiter and captain
        // roles gained "View Bill" — and a copy in this file would have gone on
        // showing a restaurant the permissions their staff had two releases ago,
        // which is worse than showing nothing.
        //
        // BEST-EFFORT: the route carries the same view-roles gate as /roles, so a
        // build pointed at an older backend (or a user without it) gets an empty
        // map and the chips below say so, instead of the screen failing to load.
        var core = const <String, List<String>>{};
        // C6's SECOND half, and the one that produced the actual symptom: a role
        // that opened onto a COLUMN OF UUIDS. The ids alone are unreadable, and
        // the names live in GET /actions — which is gated on a DIFFERENT
        // permission (2b6f7948…), so any manager holding "Get Roles" and not
        // "Get Actions" loaded the role, joined against an empty catalogue and
        // was shown a hex dump. The server now ships `permissions` beside
        // `actions`: the same ids, same order, same length, with the name,
        // description and group already attached. Read it, and the second call
        // stops mattering.
        var corePerms = const <String, List<dynamic>>{};
        try {
          final rows = await rest.getList('/core-roles');
          core = {
            for (final row in rows.whereType<Map>())
              _s(row, 'role').toLowerCase(): [
                for (final a in (row['actions'] as List?) ?? const []) '$a',
              ],
          };
          corePerms = {
            for (final row in rows.whereType<Map>())
              if (row['permissions'] is List)
                _s(row, 'role').toLowerCase(): row['permissions'] as List,
          };
        } catch (_) {/* the chips explain themselves when this is empty */}
        return {'roles': r[0], 'actions': r[1], 'core': core, 'core_permissions': corePerms};
      },
      builder: (context, data, reload) {
        final roles = (data['roles'] as List?) ?? [];
        final actions = (data['actions'] as List?) ?? [];
        final core = (data['core'] as Map?)?.cast<String, List<String>>() ?? const {};
        final corePerms =
            (data['core_permissions'] as Map?)?.cast<String, List<dynamic>>() ?? const {};
        final text = Theme.of(context).textTheme;
        // C5. Each gate is the action the SERVER enforces on that exact route, so
        // a control that is drawn will work and one that is hidden would have
        // 403'd. Nothing here widens anything: a manager sees the editor only
        // because their tenant granted them the create-role action, which is
        // precisely what "customizable" means.
        final mayEdit = _mayDo(p, Capability.manageRoles, _permCreateRole);
        final mayDelete = _holdsAction(p, _permDeleteRole);
        return Scaffold(
          backgroundColor: Colors.transparent,
          floatingActionButton: !mayEdit
              ? null
              : FloatingActionButton.extended(
            onPressed: () async {
              final created = await showDialog<bool>(
                context: context,
                builder: (_) => _CreateRoleDialog(rest: rest, actions: actions),
              );
              if (created == true) reload();
            },
            icon: const Icon(Icons.add_moderator),
            label: const Text('New role'),
          ),
          body: ListView(padding: AppSpacing.pageNarrow, children: [
            Padding(
              padding: const EdgeInsets.only(bottom: AppSpacing.lg),
              child: Text(
                  mayEdit
                      ? 'Custom roles are built from permissions and can be assigned to staff '
                          '(tap an employee in the Employees tab).'
                      : 'Custom roles are built from permissions. You can see what each one '
                          'grants; changing them needs the role-editing permission.',
                  style: text.bodySmall),
            ),
            // Built-in roles (always available — Admin grants everything and can
            // only be given or taken away by the owner/super-admin).
            const SectionHeader(title: 'Core roles', padding: EdgeInsets.only(bottom: 10)),
            // ---- REQUIREMENT C6 --------------------------------------------
            //
            // "Fix the issue preventing users from clicking and viewing core
            // roles." There was no issue to fix in the sense of a bug: these were
            // StatusChips — a label and a tint, with no gesture on them at all —
            // so a restaurant could see that a role called "cashier" existed and
            // had no way whatever to find out what a cashier is allowed to do.
            // The only thing the screen invited you to open was a CUSTOM role,
            // which is the half a restaurant already understands because they
            // built it.
            //
            // They are buttons now, and what opens is the server's own answer:
            // see [_coreRolePermissions].
            Text(
                core.isEmpty
                    ? 'Built in and always available. Their permissions are set by the system.'
                    : 'Built in and always available — tap one to see exactly what it grants.',
                style: text.bodySmall),
            const SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 8, children: [
              for (final r in _coreRoles)
                _CoreRoleChip(
                  key: ValueKey('core-role-$r'),
                  role: r,
                  // A chip with nothing behind it stays inert rather than opening
                  // an empty sheet: an older backend has no /core-roles, and a
                  // dialog that says nothing is a worse answer than a label.
                  onTap: core.containsKey(r)
                      ? () => _showCoreRole(context,
                          role: r,
                          actionIds: core[r] ?? const [],
                          permissions: corePerms[r],
                          actions: actions)
                      : null,
                ),
            ]),
            const SizedBox(height: AppSpacing.xxl),
            SectionHeader(title: 'Custom roles', count: roles.length, padding: const EdgeInsets.only(bottom: 10)),
            if (roles.isEmpty)
              _empty('No custom roles yet — create one with the button below.')
            else
              ...roles.map((r) {
                final role = r as Map;
                final roleName = _s(role, 'role_name');
                final count = (role['actions_performable'] as List?)?.length ?? 0;
                final c = _roleColor(roleName);
                final messenger = ScaffoldMessenger.of(context);
                return Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: ForkCard(
                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                    // C5 — "Super Admins and Managers can VIEW and edit custom
                    // roles". Two verbs, and they are gated separately: anyone
                    // who can open this screen at all holds the view-roles
                    // action, so the card always opens; whether the tick boxes
                    // can be CHANGED is the create-role action, which is what
                    // POST /roles enforces. A read-only pass is what makes "view"
                    // real for a role that may look but not rewrite.
                    onTap: () async {
                      final saved = await showDialog<bool>(
                        context: context,
                        builder: (_) => _CreateRoleDialog(
                            rest: rest, actions: actions, existing: role, readOnly: !mayEdit),
                      );
                      if (saved == true) reload();
                    },
                    child: Row(children: [
                      Container(
                        width: 38,
                        height: 38,
                        decoration: BoxDecoration(
                          color: AppColors.tint(c),
                          borderRadius: AppRadius.controlAll,
                          border: Border.all(color: AppColors.edge(c)),
                        ),
                        child: Icon(Icons.shield_outlined, size: 16, color: c),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      Expanded(
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
                          Text(roleName, style: text.titleSmall, maxLines: 1, overflow: TextOverflow.ellipsis),
                          const SizedBox(height: 3),
                          Text('$count permission(s) · tap to ${mayEdit ? 'edit' : 'view'}',
                              style: text.bodySmall),
                        ]),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      if (mayDelete)
                      ForkIconButton(
                        icon: Icons.delete_outline,
                        tooltip: 'Delete role',
                        onPressed: () async {
                          final ok = await _confirm(context, 'Delete role', 'Delete the "$roleName" role?');
                          if (!ok) return;
                          try {
                            await rest.delete('/roles/${role['id']}');
                            reload();
                          } catch (e) {
                            messenger.showSnackBar(SnackBar(content: Text('$e')));
                          }
                        },
                      ),
                    ]),
                  ),
                );
              }),
          ]),
        );
      },
    );

/// A CORE ROLE, AS A CONTROL — requirement C6.
///
/// It reads exactly like the StatusChip it replaces (tint, dot, label — colour
/// never travels alone) and adds the one thing that was missing: it is
/// pressable, and it says so. [onTap] is null for a build that could not read
/// /core-roles, and an inert chip is then visibly inert rather than a button
/// that does nothing when pressed.
class _CoreRoleChip extends StatelessWidget {
  const _CoreRoleChip({super.key, required this.role, this.onTap});

  final String role;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    final label = role == 'admin' ? 'admin (owner-grantable)' : role;
    final chip = StatusChip(label: label, color: _roleColor(role));
    if (onTap == null) return chip;
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(AppRadius.chip),
      // Named for a screen reader, because the chip's own text is a bare role
      // name and "waiter" alone does not announce that it opens anything.
      child: Semantics(button: true, label: 'View what the $role role can do', child: chip),
    );
  }
}

/// WHAT A CORE ROLE GRANTS — the sheet requirement C6 asks for.
///
/// [permissions] IS THE SERVER'S OWN NAMED LIST and is read FIRST — the same
/// ids, in the same order, with `action_name`, `action_desc` and `group`
/// already attached (GET /core-roles). It exists because the join this function
/// used to do could not be relied on: the names live in GET /actions, which is
/// gated on a DIFFERENT permission, so a manager holding "Get Roles" and not
/// "Get Actions" opened a core role and was shown a column of uuids. That is the
/// C6 symptom, and reading the field the server added is the whole of the fix —
/// an answer shipped and not consumed is not a fix, it is a claim.
///
/// [actionIds] and [actions] are the FALLBACK for a backend that predates
/// `permissions`: the raw id list joined against the catalogue, exactly as
/// before. An id with no name in EITHER path keeps its place in the count rather
/// than being dropped — a role that under-reports what it grants is how a
/// reviewer concludes it is safe when it is not.
///
/// READ-ONLY, AND IT SAYS WHY. A core role is not editable — CORE_ROLES is code,
/// not a per-tenant row — and a restaurant that wants a cashier who can comp a
/// dish makes a custom role. Saying that on the sheet is the difference between
/// a screen that refuses and a screen that tells you what to do instead.
void _showCoreRole(
  BuildContext context, {
  required String role,
  required List<String> actionIds,
  List<dynamic>? permissions,
  required List<dynamic> actions,
}) {
  // The admin wildcard. Listing it as one permission called "*" would be true and
  // useless; what an owner needs to read is that it is everything.
  final wildcard = actionIds.contains('*') ||
      (permissions ?? const []).whereType<Map>().any((p) => '${p['id']}' == '*');
  final byId = <String, Map>{
    for (final a in actions.whereType<Map>()) '${a['id']}': a,
  };
  // Grouped the same way the custom-role editor groups them, so one permission
  // reads identically whichever screen you met it on.
  final groups = <String, List<String>>{};
  final unknown = <String>[];
  // THE SERVER'S ROWS WHERE IT SENT THEM, the local join only where it did not.
  final rows = <Map>[
    if (permissions != null)
      for (final p in permissions.whereType<Map>()) p
    else
      for (final id in actionIds) byId[id] ?? <String, dynamic>{'id': id},
  ];
  for (final a in rows) {
    // '' AND NOT `_s`'s DEFAULT EM-DASH: an id with no name must fall into
    // `unknown` and be COUNTED, not rendered as a tick beside a dash.
    final name = _s(a, 'action_name', '');
    if (name.isEmpty) {
      // An id with no name in the server's projection either (`action_name:
      // null`), or one this build's /actions does not carry. Counted honestly
      // rather than dropped, so the list cannot quietly under-report what a role
      // can do.
      unknown.add(_s(a, 'id', ''));
      continue;
    }
    (groups[_s(a, 'group', 'Other')] ??= []).add(name);
  }
  final groupNames = groups.keys.toList()..sort();
  for (final g in groupNames) {
    groups[g]!.sort();
  }
  showDialog<void>(
    context: context,
    builder: (ctx) {
      final text = Theme.of(ctx).textTheme;
      final c = _roleColor(role);
      return Dialog(
        backgroundColor: Colors.transparent,
        child: ConstrainedBox(
          constraints: BoxConstraints(
              maxWidth: 460, maxHeight: MediaQuery.sizeOf(ctx).height * 0.8),
          child: Container(
            padding: const EdgeInsets.all(22),
            decoration: BoxDecoration(
              gradient: AppColors.cardGradient,
              borderRadius: AppRadius.cardAll,
              border: Border.all(color: AppColors.borderStrong),
            ),
            child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('CORE ROLE', style: text.labelSmall),
              const SizedBox(height: 6),
              Row(children: [
                Container(width: 8, height: 8, decoration: BoxDecoration(color: c, shape: BoxShape.circle)),
                const SizedBox(width: 8),
                Expanded(child: Text(role, style: text.titleMedium)),
              ]),
              const SizedBox(height: AppSpacing.md),
              Text(
                  wildcard
                      ? 'Every permission in the system, including ones added by future '
                          'updates. Built in and not editable — it is the owner role.'
                      : 'Built in and not editable. To give someone this plus something '
                          'extra, create a custom role with the permissions you want and '
                          'assign it alongside.',
                  style: text.bodySmall),
              const SizedBox(height: AppSpacing.lg),
              if (!wildcard) ...[
                Text('${rows.length} PERMISSION(S)', style: text.labelSmall),
                const SizedBox(height: AppSpacing.sm),
                Flexible(
                  child: SingleChildScrollView(
                    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      if (rows.isEmpty)
                        Text('This role grants no permissions of its own.', style: text.bodySmall),
                      for (final g in groupNames) ...[
                        SectionHeader(title: g, padding: const EdgeInsets.only(top: 10, bottom: 4)),
                        for (final name in groups[g]!)
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 2),
                            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                              Icon(Icons.check, size: 14, color: AppColors.success),
                              const SizedBox(width: 8),
                              Expanded(child: Text(name, style: text.bodyLarge!.copyWith(fontSize: 13))),
                            ]),
                          ),
                      ],
                      if (unknown.isNotEmpty)
                        Padding(
                          padding: const EdgeInsets.only(top: 10),
                          child: Text(
                              '${unknown.length} further permission(s) this app does not have a '
                              'name for yet — update the app to see them listed.',
                              style: text.bodySmall!.copyWith(color: AppColors.warning)),
                        ),
                    ]),
                  ),
                ),
              ],
              const SizedBox(height: AppSpacing.lg),
              Align(
                alignment: Alignment.centerRight,
                child: ForkButton.ghost(label: 'Close', dense: true, onPressed: () => Navigator.pop(ctx)),
              ),
            ]),
          ),
        ),
      );
    },
  );
}

class _CreateRoleDialog extends StatefulWidget {
  final RestClient rest;
  final List<dynamic> actions;
  final Map? existing; // when set, edit this role's permissions (name is locked)

  /// C5's "VIEW and edit": true for a reader who may open a custom role but not
  /// rewrite it. The tick boxes still show what is granted — that is the whole
  /// point of viewing — and are simply not operable, with a line saying so and
  /// no Save button to press. An enabled Save that 403s at the server is how a
  /// manager learns their permissions from a red toast.
  final bool readOnly;
  const _CreateRoleDialog(
      {required this.rest, required this.actions, this.existing, this.readOnly = false});

  @override
  State<_CreateRoleDialog> createState() => _CreateRoleDialogState();
}

class _CreateRoleDialogState extends State<_CreateRoleDialog> {
  final _name = TextEditingController();
  final Set<String> _selected = {};
  bool _saving = false;
  String? _error;

  bool get _isEdit => widget.existing != null;

  @override
  void initState() {
    super.initState();
    final e = widget.existing;
    if (e != null) {
      _name.text = _s(e, 'role_name', '');
      for (final a in (e['actions_performable'] as List?) ?? const []) {
        _selected.add('$a');
      }
    }
  }

  @override
  void dispose() {
    _name.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    final name = _name.text.trim();
    if (name.isEmpty) {
      setState(() => _error = 'Role name is required.');
      return;
    }
    setState(() {
      _saving = true;
      _error = null;
    });
    try {
      await widget.rest.post('/roles', {'role_name': name, 'actions_performable': _selected.toList()});
      if (mounted) Navigator.pop(context, true);
    } catch (e) {
      setState(() {
        _error = '$e';
        _saving = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final groups = <String, List<Map>>{};
    for (final a in widget.actions) {
      final m = a as Map;
      (groups[_s(m, 'group', 'Other')] ??= []).add(m);
    }
    final groupNames = groups.keys.toList()..sort();
    return Dialog(
      backgroundColor: Colors.transparent,
      child: Container(
        width: 460,
        padding: const EdgeInsets.all(22),
        decoration: BoxDecoration(
          gradient: AppColors.cardGradient,
          borderRadius: AppRadius.cardAll,
          border: Border.all(color: AppColors.borderStrong),
        ),
        child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('RBAC', style: text.labelSmall),
          const SizedBox(height: 6),
          Text(
              _isEdit
                  ? '${widget.readOnly ? 'Role' : 'Edit role'} · ${_name.text}'
                  : 'Create role',
              style: text.titleMedium),
          if (widget.readOnly) ...[
            const SizedBox(height: 6),
            Text(
                'What this role grants. Changing it needs the role-editing '
                'permission — ask an owner or a manager who has it.',
                style: text.bodySmall),
          ],
          const SizedBox(height: AppSpacing.lg),
          TextField(
            controller: _name,
            readOnly: _isEdit, // the name is the role's key — locked while editing
            style: _isEdit ? TextStyle(fontSize: 14, color: AppColors.textSecondary) : null,
            decoration: const InputDecoration(
              labelText: 'Role name (e.g. Floor Supervisor)',
              isDense: true,
            ),
          ),
          const SizedBox(height: AppSpacing.sm),
          if (_error != null)
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: Text(_error!, style: text.bodySmall!.copyWith(color: AppColors.danger)),
            ),
          Text('${_selected.length} PERMISSION(S) SELECTED', style: text.labelSmall),
          const SizedBox(height: AppSpacing.sm),
          SizedBox(
            height: 320,
            width: double.maxFinite,
            child: ListView(children: [
              for (final g in groupNames) ...[
                SectionHeader(title: g, padding: const EdgeInsets.only(top: 10, bottom: 4)),
                for (final a in groups[g]!)
                  CheckboxListTile(
                    dense: true,
                    contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                    activeColor: AppColors.copper,
                    checkColor: AppColors.onCopper,
                    side: BorderSide(color: AppColors.borderStrong),
                    value: _selected.contains('${a['id']}'),
                    title: Text(_s(a, 'action_name'),
                        style: text.bodyLarge!.copyWith(fontSize: 13)),
                    // null disables the box while leaving its VALUE visible —
                    // which is exactly "view".
                    onChanged: widget.readOnly
                        ? null
                        : (v) => setState(() {
                              final id = '${a['id']}';
                              if (v == true) {
                                _selected.add(id);
                              } else {
                                _selected.remove(id);
                              }
                            }),
                  ),
              ],
            ]),
          ),
          const SizedBox(height: AppSpacing.lg),
          Row(mainAxisAlignment: MainAxisAlignment.end, children: [
            ForkButton.ghost(
                label: widget.readOnly ? 'Close' : 'Cancel',
                onPressed: _saving ? null : () => Navigator.pop(context, false)),
            if (!widget.readOnly) ...[
              const SizedBox(width: AppSpacing.sm),
              ForkButton(
                label: _saving ? 'Saving…' : (_isEdit ? 'Save' : 'Create'),
                icon: Icons.check,
                onPressed: _saving ? null : _save,
              ),
            ],
          ]),
        ]),
      ),
    );
  }
}

// Discord-style role manager: toggle roles on/off for an employee. Each role is
// a switch that applies immediately (assign/remove). The superadmin keeps admin.
class _ManageRolesSheet extends StatefulWidget {
  final RestClient rest;
  final Map employee;
  final List customRoles; // [{role_name, ...}]
  final bool isSuperadmin;
  const _ManageRolesSheet({required this.rest, required this.employee, required this.customRoles, required this.isSuperadmin});

  @override
  State<_ManageRolesSheet> createState() => _ManageRolesSheetState();
}

class _ManageRolesSheetState extends State<_ManageRolesSheet> {
  late Set<String> _assigned; // lowercased role names currently held
  final Set<String> _busy = {}; // roles with an in-flight toggle
  bool _changed = false;

  @override
  void initState() {
    super.initState();
    // A CUSTOM role comes back from the server as its "Roles" UUID, but every
    // toggle in this sheet is keyed by role NAME. Without translating, a custom
    // role that IS assigned matched nothing and its switch rendered OFF — so it
    // looked like the assignment never saved, even though it had.
    final byId = <String, String>{
      for (final r in widget.customRoles)
        '${(r as Map)['id'] ?? ''}'.toLowerCase().trim(): '${r['role_name'] ?? ''}'.toLowerCase().trim(),
    };
    final current = (widget.employee['role_all'] as List?)
            ?.map((e) => '$e'.toLowerCase().trim())
            .map((e) => byId[e] ?? e) // uuid -> name; built-ins pass through
            .where((s) => s.isNotEmpty) ??
        [_s(widget.employee, 'role', '').toLowerCase()];
    _assigned = {...current}..removeWhere((s) => s.isEmpty);
  }

  List<String> get _allRoles {
    final custom = widget.customRoles.map((r) => '${(r as Map)['role_name'] ?? ''}').where((s) => s.isNotEmpty);
    final seen = <String>{};
    final out = <String>[];
    for (final r in [..._coreRoles, ...custom]) {
      final key = r.toLowerCase();
      if (seen.add(key)) out.add(r);
    }
    return out;
  }

  Future<void> _toggle(String role, bool add) async {
    final key = role.toLowerCase();
    // The superadmin must always remain an admin.
    if (widget.isSuperadmin && key == 'admin' && !add) return;
    setState(() => _busy.add(key));
    final employeeId = '${widget.employee['employee_id'] ?? widget.employee['id'] ?? ''}';
    try {
      await widget.rest.post(add ? '/roles/assign' : '/roles/remove', {'employeeId': employeeId, 'role_name': role});
      setState(() {
        if (add) {
          _assigned.add(key);
        } else {
          _assigned.remove(key);
        }
        _changed = true;
      });
    } catch (e) {
      if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy.remove(key));
    }
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    final name = '${_s(widget.employee, 'emp_Fname')} ${_s(widget.employee, 'emp_Lname', '')}'.trim();
    final display = name.isEmpty ? _s(widget.employee, 'employee_Username') : name;
    final initials = display.split(RegExp(r'\s+')).where((s) => s.isNotEmpty).take(2).map((s) => s[0]).join();
    final all = _allRoles;
    return PopScope(
      canPop: true,
      onPopInvokedWithResult: (didPop, _) {},
      child: SafeArea(
        child: Padding(
          padding: EdgeInsets.only(
              left: AppSpacing.xl,
              right: AppSpacing.xl,
              bottom: AppSpacing.lg + MediaQuery.of(context).viewInsets.bottom),
          child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              InitialsAvatar(
                initials: initials.isEmpty ? '?' : initials,
                color: widget.isSuperadmin ? AppColors.warning : AppColors.copper,
              ),
              const SizedBox(width: AppSpacing.md),
              Expanded(
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    Flexible(
                      child: Text(display, style: text.titleMedium, maxLines: 1, overflow: TextOverflow.ellipsis),
                    ),
                    if (widget.isSuperadmin) ...[
                      const SizedBox(width: 6),
                      Tooltip(
                        message: 'Superadmin (owner)',
                        child: Icon(Icons.workspace_premium, size: 15, color: AppColors.warning),
                      ),
                    ],
                  ]),
                  const SizedBox(height: 2),
                  Text('MANAGE ROLES', style: text.labelSmall),
                ]),
              ),
            ]),
            const SizedBox(height: AppSpacing.sm),
            // Currently-assigned roles as removable chips.
            if (_assigned.isNotEmpty)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: AppSpacing.sm),
                child: Wrap(spacing: 6, runSpacing: 6, children: [
                  for (final role in all.where((r) => _assigned.contains(r.toLowerCase())))
                    _roleChip(role,
                        onRemove: (widget.isSuperadmin && role.toLowerCase() == 'admin') || _busy.contains(role.toLowerCase())
                            ? null
                            : () => _toggle(role, false)),
                ]),
              ),
            const Divider(),
            Flexible(
              child: ListView(shrinkWrap: true, children: [
                for (final role in all)
                  SwitchListTile(
                    dense: true,
                    contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                    secondary: Container(
                      width: 30,
                      height: 30,
                      decoration: BoxDecoration(
                        color: AppColors.tint(_roleColor(role)),
                        borderRadius: AppRadius.controlAll,
                        border: Border.all(color: AppColors.edge(_roleColor(role))),
                      ),
                      child: Icon(Icons.shield_outlined, size: 14, color: _roleColor(role)),
                    ),
                    title: Text(role, style: text.titleSmall),
                    subtitle: _coreRoles.contains(role.toLowerCase())
                        ? null
                        : Text('Custom role', style: text.bodySmall!.copyWith(fontSize: 11)),
                    value: _assigned.contains(role.toLowerCase()),
                    onChanged: (widget.isSuperadmin && role.toLowerCase() == 'admin') || _busy.contains(role.toLowerCase())
                        ? null
                        : (v) => _toggle(role, v),
                  ),
              ]),
            ),
            const SizedBox(height: AppSpacing.md),
            Row(mainAxisAlignment: MainAxisAlignment.end, children: [
              ForkButton(label: 'Done', icon: Icons.check, onPressed: () => Navigator.pop(context, _changed)),
            ]),
          ]),
        ),
      ),
    );
  }
}

// -------------------------------------------------------------- simulation ----
//
// MOVED, ON PURPOSE. The what-if simulator now lives in its own library,
// `simulation.dart`, with its 34-parameter catalogue in
// `../models/simulation_params.dart`. It was the last ~520 lines of a
// 30,000-line file and it shares nothing with the rest of it -- no helper, no
// dialog, no formatter -- so growing it HERE to carry an editable lever picker
// would have been another 500 lines of a file nobody can hold in their head.
// (reports.dart and mis_capture.dart are `part`s instead because they genuinely
// do reach into this library's private bill body and money formatters. This one
// does not, so it is a real library with its own imports and its own tests.)
//
// The delegate stays because home_shell.dart registers the module as
// `m.simulationModule`, and the gating behind that registration is subtle and
// load-bearing: the tile matches permitted ACTION NAMES, and the action that
// authorises /simulation/* server-side is named "View Order APC" -- which is
// exactly why the keyword list over there reads ['analytics', 'apc', 'report'].
// Nothing about that gate changes.
Widget simulationModule(RestClient rest, Profile p) => simulation.simulationModule(rest, p);
